var VOCAB = [
  {id:'v1', term:'EC2', domain:'tech', source:SOURCES.ec2, q:{text:'Amazon EC2とは何ですか？', choices:['仮想サーバーを提供するコンピューティングサービス','DNSを管理するサービス','オブジェクトストレージサービス','マネージド型のリレーショナルデータベース'], correct:0, why:['正しい。EC2 (Elastic Compute Cloud) は、仮想サーバーをオンデマンドで起動できるコンピューティングサービスです。','これはAmazon Route 53（DNS）の説明です。','これはAmazon S3（オブジェクトストレージ）の説明です。','これはAmazon RDS（マネージド型リレーショナルデータベース）の説明です。']}},
  {id:'v2', term:'S3', domain:'tech', source:SOURCES.s3, q:{text:'Amazon S3とは何ですか？', choices:['ネットワーク仮想化サービス','高い耐久性を持つオブジェクトストレージサービス','リソース監視サービス','仮想サーバーサービス'], correct:1, why:['これはAmazon VPC（ネットワーク仮想化）の説明です。','正しい。S3 (Simple Storage Service) は画像・ログ等のオブジェクトを保存できる高耐久なストレージサービスです。','これはAmazon CloudWatch（監視サービス）の説明です。','これはAmazon EC2（仮想サーバー）の説明です。']}},
  {id:'v3', term:'IAM', domain:'security', source:SOURCES.iam, q:{text:'AWS IAMの主な役割は何ですか？', choices:['コンテンツ配信の高速化','仮想マシンの作成','AWSリソースへのアクセス権限を管理する','課金レポートの生成'], correct:2, why:['これはAmazon CloudFront（コンテンツ配信）の説明です。','これはAmazon EC2（仮想マシンの作成）の説明です。','正しい。IAM (Identity and Access Management) は、誰がどのAWSリソースに何をできるかを管理するサービスです。','これは課金レポート機能（Cost Explorer等）の説明です。']}},
  {id:'v4', term:'VPC', domain:'tech', source:SOURCES.vpc, q:{text:'Amazon VPCとは何ですか？', choices:['請求管理サービス','メール送信サービス','オブジェクトストレージ','AWS上に論理的に分離されたネットワーク環境を作成するサービス'], correct:3, why:['これは請求管理機能の説明です。','これはAmazon SES（メール送信サービス）の説明です。','これはAmazon S3（オブジェクトストレージ）の説明です。','正しい。VPC (Virtual Private Cloud) は、自分専用の論理的に分離されたネットワーク環境をAWS上に構築する仕組みです。']}},
  {id:'v5', term:'Shared Responsibility Model', domain:'security', source:SOURCES.shared, q:{text:'責任共有モデルにおいて、AWS側が責任を持つのは次のうちどれですか？', choices:['クラウドの物理的インフラストラクチャの保護','データの暗号化キーの管理方法の選択','OS上のアプリケーション設定','ユーザーのIAMポリシー設定'], correct:0, why:['正しい。クラウドの物理的インフラ（データセンター等）の保護はAWS側の責任範囲です。','これはユーザー側（クラウド内のセキュリティ）の責任範囲です。','これはユーザー側（クラウド内のセキュリティ）の責任範囲です。','これはユーザー側（クラウド内のセキュリティ）の責任範囲です。']}},
  {id:'v6', term:'CloudFront', domain:'tech', source:SOURCES.cloudfront, q:{text:'Amazon CloudFrontの役割は何ですか？', choices:['仮想サーバー管理サービス','コンテンツをエッジロケーション経由で高速配信するCDNサービス','IDプロバイダー連携サービス','課金管理サービス'], correct:1, why:['これはAmazon EC2（仮想サーバー管理）の説明です。','正しい。CloudFrontは世界中のエッジロケーションを使ってコンテンツ配信を高速化するCDNです。','これはAmazon Cognito（ID連携）の説明です。','これは課金管理機能の説明です。']}},
  {id:'v7', term:'Free Tier', domain:'billing', source:SOURCES.free, q:{text:'AWS無料利用枠(Free Tier)の説明として正しいものは？', choices:['有料プランへ切り替えないと一切利用できない','全サービスが期間を問わず無期限に無料になる','「常に無料」の対象サービス、新規アカウント向けの無料クレジット、一定期間の無料トライアルなど複数の無料枠で構成される','サポートプランの費用のみが無料になる'], correct:2, why:['誤り。Free Planでも対象サービスはそのまま利用でき、有料プランへの切替えは必須ではありません。','誤り。無期限・全サービスが対象ではなく、サービスや条件によって範囲が異なります。','正しい。Free Tierは「常に無料」の対象サービス、新規アカウントが受け取れる無料クレジット、一定期間の無料トライアルなどで構成されます。','誤り。Basic Supportは全アカウントで無料ですが、それはサポートプランの話であり無料利用枠とは別の仕組みです。']}},
  {id:'v8', term:'Pay-as-you-go', domain:'billing', source:SOURCES.pricing, q:{text:'AWSの「従量課金制(Pay-as-you-go)」とは何ですか？', choices:['月額固定のサブスクリプション','無料で使い放題になる方式','年間契約で固定額を支払う方式','使用した分だけ料金を支払う方式'], correct:3, why:['誤り。これはサブスクリプション型の説明です。','誤り。従量課金制でも利用には料金が発生します。','誤り。これは固定額を前払いする契約の説明です。','正しい。従量課金制は、実際に使用したリソース量に応じて料金が発生する仕組みです。']}},

  // --- クラウドのコンセプト ---
  {id:'v9', term:'Elasticity', domain:'concepts', source:SOURCES.waf, q:{text:'「弾力性(Elasticity)」とは何ですか？', choices:['需要に応じてリソースを自動的に増減できる特性','データが失われない性質','システムが一貫した応答を返す性質','障害発生時に処理を継続できる性質'], correct:0, why:['正しい。弾力性は需要の変化に応じてコンピューティングリソースを自動的に増減できる特性です。','これは耐久性(Durability)の説明です。','これは一貫性(Consistency)の説明です。','これは耐障害性(Fault Tolerance)の説明です。']}},
  {id:'v10', term:'Scalability', domain:'concepts', source:SOURCES.waf, q:{text:'「スケーラビリティ(Scalability)」とは何ですか？', choices:['料金が固定されている度合い','需要の増加に応じてリソースを拡張し、パフォーマンスを維持できる能力','データセンターの地理的な分散度','データが暗号化されている度合い'], correct:1, why:['これは料金モデルの説明であり、スケーラビリティとは異なります。','正しい。スケーラビリティは需要の増加に合わせてリソースを拡張し、パフォーマンスを維持できる能力です。','これはリージョン/AZの地理的分散の説明であり、スケーラビリティとは異なります。','これは暗号化の説明であり、スケーラビリティとは異なります。']}},
  {id:'v11', term:'High Availability', domain:'concepts', source:SOURCES.wafReliability, q:{text:'「高可用性(High Availability)」の説明として正しいものはどれですか？', choices:['料金を固定額にすること','リソースを需要に応じて増減させること','障害が発生してもシステムが継続して稼働できるように設計すること','データを暗号化すること'], correct:2, why:['これは料金モデルの説明であり、高可用性とは異なります。','これは弾力性(Elasticity)の説明です。','正しい。高可用性は、障害が発生してもサービスを継続して提供できるようにシステムを設計する考え方です。','これは暗号化の説明であり、高可用性とは異なります。']}},
  {id:'v12', term:'Agility', domain:'concepts', source:SOURCES.sixAdv, q:{text:'クラウドにおける「アジリティ(Agility)」の説明として正しいものはどれですか？', choices:['データの耐久性を高める仕組み','料金を事前に一括で支払う契約形態','複数のAZにリソースを分散する仕組み','必要なリソースを迅速に調達・展開し、試行や変更を素早く行える能力'], correct:3, why:['これは耐久性の説明であり、アジリティとは異なります。','これはリザーブドインスタンス等の契約形態の説明であり、アジリティとは異なります。','これはマルチAZ構成の説明であり、アジリティとは異なります。','正しい。アジリティは、必要なリソースを数分で調達し、アイデアを素早く試せる俊敏性を指します。']}},
  {id:'v13', term:'CapEx / OpEx', domain:'concepts', source:SOURCES.sixAdv, q:{text:'クラウド移行によって「資本費用(CapEx)」を「運用費用(OpEx)」に変換できるとは、どのような意味ですか？', choices:['事前の大きな設備投資をせず、使用した分だけ費用を支払う形に変えられること','リージョンごとに固定の月額費用を支払う契約になること','すべての費用が無料になること','運用担当者が不要になること'], correct:0, why:['正しい。データセンター等への先行投資(CapEx)の代わりに、使用量に応じた費用(OpEx)を支払う形に変えられます。','誤り。固定の月額契約ではなく、使用量に応じた変動費が基本です。','誤り。無料になるわけではなく、支払い方法が変わるだけです。','誤り。運用担当者が不要になるとは限りません。']}},
  {id:'v14', term:'Region', domain:'concepts', source:SOURCES.globalInfra, q:{text:'AWSの「リージョン(Region)」とは何ですか？', choices:['1つのデータセンター内のサーバー群','世界中にある、複数のアベイラビリティーゾーンで構成される独立した地理的エリア','請求情報を管理する単位','CDNのキャッシュを配置する拠点'], correct:1, why:['これはデータセンターの説明であり、リージョンより小さい単位です。','正しい。リージョンは、複数の独立したアベイラビリティーゾーンで構成される地理的に分離されたエリアです。','これはAWSアカウントや請求管理の単位の説明であり、リージョンとは異なります。','これはエッジロケーションの説明です。']}},
  {id:'v15', term:'Availability Zone', domain:'concepts', source:SOURCES.globalInfra, q:{text:'「アベイラビリティーゾーン(AZ)」の説明として正しいものはどれですか？', choices:['複数のリージョンをまとめたグループ','世界中に配置されたキャッシュ用のエッジロケーション','1つ以上の物理的に分離されたデータセンターで構成される、リージョン内の拠点','ユーザーのアクセス権限を管理する単位'], correct:2, why:['これはリージョンの集合の説明であり、AZの説明ではありません。','これはエッジロケーションの説明です。','正しい。AZは、独立した電源・冷却・物理セキュリティを持つ1つ以上のデータセンターで構成されるリージョン内の拠点です。','これはIAMの説明であり、AZとは異なります。']}},
  {id:'v16', term:'Well-Architected Framework', domain:'concepts', source:SOURCES.waf, q:{text:'AWS Well-Architected Frameworkとは何ですか？', choices:['AWS資格試験の出題範囲を定めた文書','AWSサポートプランの契約書','AWSの料金体系を定めた文書','クラウド上でシステムを設計・運用する際のベストプラクティスをまとめたフレームワーク'], correct:3, why:['誤り。資格試験の出題範囲（試験ガイド）とは別のものです。','誤り。サポートプランの契約書ではありません。','誤り。料金体系の文書ではありません。','正しい。Well-Architected Frameworkは、信頼性・セキュリティ・コスト最適化等の観点からシステムを評価・改善するためのベストプラクティス集です。']}},
  {id:'v17', term:'Serverless', domain:'concepts', source:SOURCES.lambda, q:{text:'「サーバーレス(Serverless)」の説明として正しいものはどれですか？', choices:['サーバーのプロビジョニングや管理を利用者が行わずにアプリケーションを実行できる形態','サーバーを一切使わずにデータを保存する方式','オンプレミスのサーバーのみで構成されたシステム','無料でサーバーを利用できるプラン'], correct:0, why:['正しい。サーバーレスは、基盤となるサーバーの管理をAWSに任せ、利用者はコードや設定に集中できる形態です（例: AWS Lambda）。','誤り。裏側では実際にサーバーが使われており、「サーバーが存在しない」わけではありません。','誤り。サーバーレスはクラウドサービスの利用形態であり、オンプレミス限定の概念ではありません。','誤り。料金が無料になるわけではなく、実行時間等に応じて課金されます。']}},
  {id:'v18', term:'TCO', domain:'concepts', source:SOURCES.sixAdv, q:{text:'「TCO(総所有コスト)」とは何ですか？', choices:['AWSの月額利用料のみを指す金額','ハードウェア購入費だけでなく、運用・保守・人件費等も含めた総コスト','サポートプランの年間費用','無料利用枠で削減できる金額'], correct:1, why:['誤り。月額利用料のみではなく、より広い範囲のコストを含みます。','正しい。TCOは初期費用だけでなく、運用・保守・電力・人件費等を含めた総所有コストを指します。','誤り。サポートプラン費用のみを指す用語ではありません。','誤り。無料利用枠による削減額を指す用語ではありません。']}},

  // --- セキュリティとコンプライアンス ---
  {id:'v19', term:'MFA', domain:'security', source:SOURCES.iam, q:{text:'AWSにおける「多要素認証(MFA)」の目的として正しいものはどれですか？', choices:['通信内容を暗号化すること','複数のAWSアカウントを一括管理すること','パスワードに加えて追加の認証要素を要求し、不正アクセスのリスクを低減すること','課金を自動的に管理すること'], correct:2, why:['これは暗号化（KMSやTLS等）の説明であり、MFAとは異なります。','これはAWS Organizationsの説明であり、MFAとは異なります。','正しい。MFAはパスワードに加えて追加の認証要素を要求することで、不正アクセスのリスクを大幅に低減します。','これは課金管理機能の説明であり、MFAとは異なります。']}},
  {id:'v20', term:'Root User', domain:'security', source:SOURCES.iam, q:{text:'AWSアカウントの「ルートユーザー」に関する記述として正しいものはどれですか？', choices:['無料利用枠の利用上限を管理するためのアカウント','AWSサポートが管理する運用担当者アカウント','日常的なAWSリソース操作専用に作成する一般的なIAMユーザー','アカウント作成時に発行され、すべてのリソースと請求情報に無制限にアクセスできる特権アカウントで、日常作業には使わずIAMユーザーの利用が推奨される'], correct:3, why:['誤り。無料利用枠の管理に特化したアカウントではありません。','誤り。ルートユーザーはAWSサポートではなく、アカウント所有者が管理します。','誤り。これはIAMユーザーの説明であり、ルートユーザーとは権限の範囲が異なります。','正しい。ルートユーザーは無制限の権限を持つため、MFAを設定し日常作業にはIAMユーザーを使うことが推奨されます。']}},
  {id:'v21', term:'IAM Role', domain:'security', source:SOURCES.iam, q:{text:'IAMロールの特徴として正しいものはどれですか？', choices:['特定のユーザーやサービスが一時的に引き受けて使用する、長期的なアクセスキーを持たない権限セット','パスワードを一切使わずにAWS全体を無制限に操作できる特権','課金情報のみを閲覧できる専用の権限','常に1人の特定のユーザーに固定で割り当てられる認証情報'], correct:0, why:['正しい。IAMロールは一時的な認証情報を提供し、ユーザーやEC2インスタンス等のAWSサービスが必要な時だけ引き受けて使用します。','誤り。無制限の特権という意味ではなく、付与されたポリシー範囲内の権限です。','誤り。課金情報の閲覧のみに限定された仕組みではありません。','誤り。これはIAMユーザーの特徴であり、ロールは特定の1人に固定割り当てされるものではありません。']}},
  {id:'v22', term:'AWS KMS', domain:'security', source:SOURCES.kms, q:{text:'AWS KMS(Key Management Service)の役割は何ですか？', choices:['Webアプリケーションへの攻撃をフィルタリングするサービス','データ暗号化に使う暗号鍵を作成・管理するサービス','DDoS攻撃を防御するサービス','APIコールの履歴を記録するサービス'], correct:1, why:['これはAWS WAFの説明です。','正しい。KMSは、データの暗号化・復号に使用する暗号鍵を作成・管理・ローテーションするサービスです。','これはAWS Shieldの説明です。','これはAWS CloudTrailの説明です。']}},
  {id:'v23', term:'AWS WAF', domain:'security', source:SOURCES.wafService, q:{text:'AWS WAF(Web Application Firewall)の役割として正しいものはどれですか？', choices:['脅威を自動的に検知し通知する','暗号鍵を管理する','SQLインジェクションやクロスサイトスクリプティング(XSS)など、Webアプリケーションを標的とした攻撃をルールでフィルタリングする','DDoS攻撃からネットワーク層・トランスポート層を保護する'], correct:2, why:['これはAmazon GuardDutyの説明です。','これはAWS KMSの説明です。','正しい。AWS WAFは、HTTP/HTTPSリクエストをルールに基づいてフィルタリングし、Webアプリケーションを標的とした攻撃から保護します。','これはAWS Shieldの説明です。']}},
  {id:'v24', term:'AWS Shield', domain:'security', source:SOURCES.shield, q:{text:'AWS Shieldの役割として正しいものはどれですか？', choices:['Webアプリケーション層の攻撃ルールをカスタマイズするサービス','コンプライアンスレポートを提供するサービス','アカウントの操作履歴を記録するサービス','DDoS(分散型サービス拒否)攻撃からAWS上のリソースを保護するサービスで、Standardは全利用者に自動的に適用される'], correct:3, why:['これはAWS WAFの説明です。','これはAWS Artifactの説明です。','これはAWS CloudTrailの説明です。','正しい。AWS Shieldは、DDoS攻撃からリソースを保護するサービスで、Shield Standardは追加費用なしで全利用者に適用されます。']}},
  {id:'v25', term:'Amazon GuardDuty', domain:'security', source:SOURCES.guardduty, q:{text:'Amazon GuardDutyの役割として正しいものはどれですか？', choices:['機械学習を用いてAWS環境内の不審な挙動や脅威を継続的に検知するサービス','請求レポートを自動生成するサービス','ネットワークを論理的に分離するサービス','暗号鍵を保管するサービス'], correct:0, why:['正しい。GuardDutyはCloudTrailやVPCフローログ等を機械学習で分析し、不審な挙動や脅威を継続的に検知します。','これはAWS Cost Explorer等の説明です。','これはAmazon VPCの説明です。','これはAWS KMSの説明です。']}},
  {id:'v26', term:'AWS Artifact', domain:'security', source:SOURCES.artifact, q:{text:'AWS Artifactの役割として正しいものはどれですか？', choices:['DDoS攻撃を防御するサービス','AWSのコンプライアンスレポートや契約書（例: SOCレポート）にオンデマンドでアクセスできるサービス','課金アラートを設定するサービス','脅威を検知するセキュリティサービス'], correct:1, why:['これはAWS Shieldの説明です。','正しい。AWS Artifactは、AWSのコンプライアンス関連レポートや契約書をオンデマンドで取得できるセルフサービスポータルです。','これはAWS Budgetsの説明です。','これはAmazon GuardDutyの説明です。']}},
  {id:'v27', term:'AWS Secrets Manager', domain:'security', source:SOURCES.secretsmanager, q:{text:'AWS Secrets Managerの役割として正しいものはどれですか？', choices:['複数アカウントを一括管理するサービス','AWSアカウントの利用料金を分析するサービス','データベースの認証情報やAPIキーなどのシークレットを安全に保管・自動ローテーションするサービス','ネットワークトラフィックをフィルタリングするファイアウォール'], correct:2, why:['これはAWS Organizationsの説明です。','これはAWS Cost Explorerの説明です。','正しい。Secrets Managerは、データベース認証情報等のシークレットを安全に保管し、自動でローテーションできるサービスです。','これはAWS WAFの説明です。']}},
  {id:'v28', term:'Security Group', domain:'security', source:SOURCES.vpc, q:{text:'VPCにおける「セキュリティグループ」の特徴として正しいものはどれですか？', choices:['物理的なネットワーク機器','課金情報を管理する単位','サブネット単位で動作するステートレスなファイアウォールで、許可と拒否の両方を設定できる','インスタンス単位で動作するステートフルな仮想ファイアウォールで、許可ルールのみを設定できる'], correct:3, why:['誤り。物理機器ではなく、ソフトウェアによる仮想ファイアウォールです。','誤り。課金情報とは無関係です。','これはネットワークACL(NACL)の特徴です。NACLはサブネット単位でステートレスに動作し、許可・拒否の両方を設定できます。','正しい。セキュリティグループはインスタンス(ENI)単位で動作するステートフルなファイアウォールで、許可ルールのみを設定できます。']}},

  // --- クラウドテクノロジーとサービス ---
  {id:'v29', term:'AWS Lambda', domain:'tech', source:SOURCES.lambda, q:{text:'AWS Lambdaの特徴として正しいものはどれですか？', choices:['サーバーのプロビジョニングや管理をせずに、イベントに応じてコードを実行できるサーバーレスコンピューティングサービス','常時起動する仮想サーバーを提供するサービス','DNSルーティングを管理するサービス','リレーショナルデータベースを提供するサービス'], correct:0, why:['正しい。Lambdaはサーバー管理不要で、イベント発生時にコードを実行できるサーバーレスコンピューティングサービスです。','これはAmazon EC2の説明です。','これはAmazon Route 53の説明です。','これはAmazon RDSの説明です。']}},
  {id:'v30', term:'Auto Scaling', domain:'tech', source:SOURCES.autoscaling, q:{text:'Amazon EC2 Auto Scalingの役割として正しいものはどれですか？', choices:['データを自動的に暗号化する','需要の変化に応じてEC2インスタンスの数を自動的に増減させる','複数リージョンのアカウントを一括管理する','DNSの名前解決を行う'], correct:1, why:['これはAWS KMS等の説明です。','正しい。Auto Scalingは、需要や健全性の状態に応じてEC2インスタンス数を自動的に増減させます。','これはAWS Organizationsの説明です。','これはAmazon Route 53の説明です。']}},
  {id:'v31', term:'Elastic Load Balancing', domain:'tech', source:SOURCES.elb, q:{text:'Elastic Load Balancing(ELB)の役割として正しいものはどれですか？', choices:['課金アラートを送信する','APIコールの履歴を記録する','複数のターゲット(EC2インスタンス等)にトラフィックを分散させる','ストレージ容量を自動的に拡張する'], correct:2, why:['これはAWS Budgetsの説明です。','これはAWS CloudTrailの説明です。','正しい。ELBは、1つ以上のアベイラビリティーゾーンにある複数のターゲットに着信トラフィックを分散させます。','これはAmazon EFS等のストレージサービスの説明です。']}},
  {id:'v32', term:'Amazon EBS', domain:'tech', source:SOURCES.ebs, q:{text:'Amazon EBS(Elastic Block Store)の特徴として正しいものはどれですか？', choices:['複数のEC2インスタンスから同時にマウントできる共有ファイルストレージ','インターネット経由でオブジェクトを保存するストレージ','DNSクエリをキャッシュするストレージ','EC2インスタンスにアタッチして使用するブロックストレージで、インスタンスのライフサイクルとは独立して永続化できる'], correct:3, why:['これはAmazon EFS（共有ファイルストレージ）の説明です。','これはAmazon S3（オブジェクトストレージ）の説明です。','これはAmazon Route 53等の説明であり、EBSとは異なります。','正しい。EBSはEC2インスタンスにアタッチするブロックストレージで、インスタンスを削除してもボリュームを永続化できます。']}},
  {id:'v33', term:'Amazon EFS', domain:'tech', source:SOURCES.efs, q:{text:'Amazon EFS(Elastic File System)の特徴として正しいものはどれですか？', choices:['複数のEC2インスタンスから同時にマウントして共有できる、NFSベースのファイルストレージ','単一のEC2インスタンスにのみアタッチできるブロックストレージ','リレーショナルデータベースのストレージエンジン','オブジェクト単位でデータを保存するストレージ'], correct:0, why:['正しい。EFSは複数のEC2インスタンスから同時にマウントして共有できる、サーバーレスで拡張性のあるファイルストレージです。','これはAmazon EBSの説明です。','これはAmazon RDS等の説明です。','これはAmazon S3の説明です。']}},
  {id:'v34', term:'Amazon RDS', domain:'tech', source:SOURCES.rds, q:{text:'Amazon RDSの特徴として正しいものはどれですか？', choices:['オブジェクトストレージサービス','MySQLやPostgreSQL等のリレーショナルデータベースの運用・保守（パッチ適用やバックアップ等）をAWSが管理するマネージドサービス','キーバリュー型のNoSQLデータベースサービス','コンテンツ配信サービス'], correct:1, why:['これはAmazon S3の説明です。','正しい。RDSはリレーショナルデータベースのプロビジョニング・パッチ適用・バックアップ等の運用をAWSが管理するマネージドサービスです。','これはAmazon DynamoDBの説明です。','これはAmazon CloudFrontの説明です。']}},
  {id:'v35', term:'Amazon DynamoDB', domain:'tech', source:SOURCES.dynamodb, q:{text:'Amazon DynamoDBの特徴として正しいものはどれですか？', choices:['SQLのJOINを多用する用途に最適化されたリレーショナルデータベース','ファイルストレージサービス','サーバーレスで完全マネージドなキーバリュー/ドキュメント型のNoSQLデータベース','運用・保守が必要なオンプレミス専用データベース'], correct:2, why:['これはAmazon RDSの説明です。','これはAmazon EFS等の説明です。','正しい。DynamoDBはサーバーレスで完全マネージドなNoSQLデータベースで、大規模なアクセスに対して単一桁ミリ秒のレイテンシーを実現します。','誤り。DynamoDBはAWSが運用を管理するクラウドサービスであり、オンプレミス専用ではありません。']}},
  {id:'v36', term:'Amazon Route 53', domain:'tech', source:SOURCES.route53, q:{text:'Amazon Route 53の役割として正しいものはどれですか？', choices:['コンテンツをエッジロケーションで配信するCDN','仮想ネットワークを分離するサービス','データベースの負荷分散サービス','DNSの名前解決とドメイン登録、トラフィックルーティングを提供するサービス'], correct:3, why:['これはAmazon CloudFrontの説明です。','これはAmazon VPCの説明です。','これはElastic Load Balancing等の説明です。','正しい。Route 53はDNSの名前解決、ドメイン登録、さまざまなルーティングポリシーを提供するサービスです。']}},
  {id:'v37', term:'AWS Direct Connect', domain:'tech', source:SOURCES.directconnect, q:{text:'AWS Direct Connectの役割として正しいものはどれですか？', choices:['オンプレミス環境とAWS間に、公共のインターネットを経由しない専用のネットワーク接続を確立する','S3のデータをキャッシュする','インターネット経由の暗号化されたVPN接続を提供する','複数のAZにロードバランシングを行う'], correct:0, why:['正しい。Direct Connectは、オンプレミスとAWS間に専用線を使った接続を確立し、安定した帯域と低レイテンシーを得られます。','これはAmazon CloudFrontの説明です。','これはAWS Site-to-Site VPNの説明です。VPNは公共のインターネットを経由して暗号化通信を行います。','これはElastic Load Balancingの説明です。']}},
  {id:'v38', term:'Amazon CloudWatch', domain:'tech', source:SOURCES.cloudwatch, q:{text:'Amazon CloudWatchの役割として正しいものはどれですか？', choices:['複数アカウントを一括請求するサービス','AWSリソースやアプリケーションのメトリクス・ログを収集し、監視やアラームを設定できるサービス','ネットワークトラフィックをフィルタリングするファイアウォール','AWSアカウント内のAPIコールの履歴を記録し、監査に利用するサービス'], correct:1, why:['これはAWS Organizationsの説明です。','正しい。CloudWatchはメトリクス・ログを収集し、ダッシュボードやアラームによる監視を行うサービスです。','これはAWS WAFの説明です。','これはAWS CloudTrailの説明です。CloudWatchは運用メトリクス監視が主目的で、API操作履歴の監査が主目的ではありません。']}},
  {id:'v39', term:'AWS CloudTrail', domain:'tech', source:SOURCES.cloudtrail, q:{text:'AWS CloudTrailの役割として正しいものはどれですか？', choices:['Webアプリケーションへの攻撃をフィルタリングするサービス','DNSの名前解決を行うサービス','「誰が」「いつ」「どのAPIを呼び出したか」というアカウント内の操作履歴を記録し、監査やガバナンスに利用するサービス','CPU使用率やメモリ使用率などの運用メトリクスを収集し、アラームを設定するサービス'], correct:2, why:['これはAWS WAFの説明です。','これはAmazon Route 53の説明です。','正しい。CloudTrailはアカウント内のAPIコール履歴を記録し、誰がいつ何をしたかを追跡できる監査・ガバナンス用のサービスです。','これはAmazon CloudWatchの説明です。']}},
  {id:'v40', term:'AWS CloudFormation', domain:'tech', source:SOURCES.cloudformation, q:{text:'AWS CloudFormationの役割として正しいものはどれですか？', choices:['アプリケーションの脆弱性をスキャンするサービス','手動でコンソール上にリソースを作成する作業を記録するサービス','ネットワーク帯域を監視するサービス','テンプレート（コード）を使ってAWSリソースをプロビジョニングする、Infrastructure as Codeのサービス'], correct:3, why:['誤り。脆弱性スキャンはAmazon Inspector等の役割です。','誤り。操作の記録自体はCloudTrailの役割です。','誤り。帯域監視はAmazon CloudWatchの役割です。','正しい。CloudFormationはテンプレートに定義した構成をもとに、AWSリソースを自動的かつ再現可能にプロビジョニングするサービスです。']}},
  {id:'v41', term:'Amazon SageMaker', domain:'tech', source:SOURCES.sagemaker, q:{text:'Amazon SageMakerの役割として正しいものはどれですか？', choices:['機械学習モデルの構築・学習・デプロイを行うためのフルマネージドサービス','チャットボットを構築するためのサービス','画像や動画を解析するサービス','テキストを音声に変換するサービス'], correct:0, why:['正しい。SageMakerは、独自の機械学習モデルを構築・学習・デプロイできるフルマネージドサービスです。','これはAmazon Lex等の説明です。','これはAmazon Rekognitionの説明です。','これはAmazon Pollyの説明です。']}},

  // --- 請求、課金、サポート ---
  {id:'v42', term:'AWS Organizations', domain:'billing', source:SOURCES.organizations, q:{text:'AWS Organizationsの役割として正しいものはどれですか？', choices:['コストを可視化するダッシュボードサービス','複数のAWSアカウントを一元管理し、一括請求（コンソリデーティッドビリング）やガバナンス（SCP）を実現するサービス','単一アカウント内のIAMユーザーを管理するサービス','課金アラートを送信するサービス'], correct:1, why:['これはAWS Cost Explorerの説明です。','正しい。Organizationsは複数アカウントを一元管理し、一括請求やサービスコントロールポリシー(SCP)によるガバナンスを実現します。','これはAWS IAMの説明です。','これはAWS Budgetsの説明です。']}},
  {id:'v43', term:'AWS Budgets', domain:'billing', source:SOURCES.costmgmt, q:{text:'AWS Budgetsの役割として正しいものはどれですか？', choices:['複数アカウントを一括管理する','リザーブドインスタンスを自動購入する','コストや使用量の予算を設定し、閾値を超えた場合にアラートを送る','過去のコストを分析し傾向を可視化する'], correct:2, why:['これはAWS Organizationsの説明です。','誤り。Budgets自体に自動購入機能はありません。','正しい。AWS Budgetsは予算を設定し、実際や予測のコスト・使用量が閾値を超えた際にアラートを送ります。','これはAWS Cost Explorerの説明です。']}},
  {id:'v44', term:'AWS Cost Explorer', domain:'billing', source:SOURCES.costmgmt, q:{text:'AWS Cost Explorerの役割として正しいものはどれですか？', choices:['予算の閾値超過時にアラートを送るツール','複数アカウントを一括請求するサービス','リソースの脆弱性をスキャンするツール','過去のコストと使用量を分析・可視化し、将来のコストを予測できるツール'], correct:3, why:['これはAWS Budgetsの説明です。','これはAWS Organizationsの説明です。','これはAmazon Inspector等の説明です。','正しい。Cost Explorerは過去のコスト・使用量を可視化し、傾向分析や将来のコスト予測ができるツールです。']}},
  {id:'v45', term:'Savings Plans', domain:'billing', source:SOURCES.costmgmt, q:{text:'AWS Savings Plansの特徴として正しいものはどれですか？', choices:['1年または3年間、一定の使用量（ドル/時間）を契約することで、オンデマンドより低い料金を得られる柔軟な料金モデル','無料利用枠として提供される料金モデル','AWSの空き容量を低価格で利用できるが中断される可能性がある料金モデル','使用した分だけ支払う、契約を伴わない料金モデル'], correct:0, why:['正しい。Savings Plansは一定の使用量を1年・3年単位で契約することで、インスタンスタイプ等に縛られず割引価格を得られる料金モデルです。','これは無料利用枠の説明です。','これはスポットインスタンスの説明です。','これはオンデマインドインスタンスの説明です。']}},
  {id:'v46', term:'Reserved Instances', domain:'billing', source:SOURCES.costmgmt, q:{text:'Amazon EC2のリザーブドインスタンスの特徴として正しいものはどれですか？', choices:['AWSが中断できる空き容量を割安に利用する料金モデル','特定のインスタンスタイプ・リージョンを1年または3年間予約することで、オンデマンドより割安な料金を得られる','必要な時にすぐ起動し使用した分だけ支払う、予約を伴わない料金モデル','常に無料で利用できる料金モデル'], correct:1, why:['これはスポットインスタンスの説明です。','正しい。リザーブドインスタンスは特定の条件のインスタンスを1年・3年単位で予約することで割安な料金を得られます。','これはオンデマンドインスタンスの説明です。','誤り。無料になるわけではなく、割引価格での契約です。']}},
  {id:'v47', term:'Spot Instances', domain:'billing', source:SOURCES.costmgmt, q:{text:'Amazon EC2スポットインスタンスの特徴として正しいものはどれですか？', choices:['1年/3年の予約契約でオンデマンドより割安になる','常時可用性が保証された料金モデル','AWSの空きキャパシティを大幅な割引価格で利用できるが、AWSの都合で中断される可能性がある','使用量にかかわらず固定額を支払う'], correct:2, why:['これはリザーブドインスタンス/Savings Plansの説明です。','誤り。中断の可能性があり、常時可用性は保証されません。','正しい。スポットインスタンスはAWSの空きキャパシティを大幅な割引で利用できますが、AWSの都合で2分前通知のうえ中断される可能性があります。','誤り。使用量に応じて料金が発生します。']}},
  {id:'v48', term:'AWS Trusted Advisor', domain:'billing', source:SOURCES.trustedadvisor, q:{text:'AWS Trusted Advisorの役割として正しいものはどれですか？', choices:['リザーブドインスタンスを自動的に購入するサービス','予算超過時にアラートを送るサービス','複数アカウントを一括請求するサービス','コスト最適化・パフォーマンス・セキュリティ・レジリエンス（耐障害性）・サービス制限などの観点でベストプラクティスに基づく推奨事項を提示する'], correct:3, why:['誤り。自動購入機能を持つサービスではありません。','これはAWS Budgetsの説明です。','これはAWS Organizationsの説明です。','正しい。Trusted Advisorはコスト最適化・パフォーマンス・セキュリティ・レジリエンス・サービス制限等の観点で推奨事項を提示します。']}},

  // --- 追加分（耐障害性・ガバナンス・DR・エッジロケーション） ---
  {id:'v49', term:'Fault Tolerance', domain:'concepts', source:SOURCES.wafReliability, q:{text:'「耐障害性(Fault Tolerance)」とは何を指しますか？', choices:['一部のコンポーネントで障害が発生しても、システム全体として正常に機能を継続できる能力','需要に応じてリソースを自動的に増減できる特性','障害からの復旧にかかる時間を測定する指標','データが失われない性質'], correct:0, why:['正しい。耐障害性は、一部のコンポーネントで障害が発生してもシステム全体としては正常に機能し続けられる能力を指します。','これは弾力性(Elasticity)の説明です。','これは目標復旧時間(RTO)のような復旧指標に関する説明であり、耐障害性自体の定義ではありません。','これは耐久性(Durability)の説明です。']}},
  {id:'v50', term:'AWS Config', domain:'security', source:SOURCES.config, q:{text:'AWS Configの役割として正しいものはどれですか？', choices:['DDoS攻撃からリソースを保護する','AWSリソースの構成を記録し、構成変更の履歴を追跡してコンプライアンス評価に利用できるサービス','暗号鍵を管理する','Webアプリケーションへの攻撃をフィルタリングする'], correct:1, why:['これはAWS Shieldの説明です。','正しい。AWS Configはリソースの構成とその変更履歴を記録し、コンプライアンス評価やトラブルシューティングに利用できるサービスです。','これはAWS KMSの説明です。','これはAWS WAFの説明です。']}},
  {id:'v51', term:'Disaster Recovery (DR)', domain:'concepts', source:SOURCES.wafReliability, q:{text:'「ディザスタリカバリ(DR)」とは何ですか？', choices:['需要に応じてリソースを増減させる仕組み','複数のAZにインスタンスを分散配置する機能そのもの','災害や大規模障害発生時に、システムを復旧させ事業を継続するための計画・仕組み','コストを最小化するための購入オプション'], correct:2, why:['これは弾力性(Elasticity)の説明です。','複数AZへの分散はDR戦略の一手段ですが、それ自体がDRの定義ではありません。','正しい。DRは災害や大規模障害発生時にシステムを復旧し、事業を継続するための計画・仕組みです。','これはリザーブドインスタンスやSavings Plansなど購入オプションに関する説明です。']}},
  {id:'v52', term:'Edge Location', domain:'concepts', source:SOURCES.edgelocation, q:{text:'AWSの「エッジロケーション」とは何ですか？', choices:['複数のアベイラビリティーゾーンで構成される地理的エリア','1つ以上のデータセンターで構成されるリージョン内の拠点','請求情報を一括管理する拠点','CloudFrontなどのサービスがコンテンツをキャッシュし、利用者に近い場所から低レイテンシーで配信するために使用する拠点'], correct:3, why:['これはリージョンの説明です。','これはアベイラビリティーゾーンの説明です。','請求管理とは無関係です。','正しい。エッジロケーションはCloudFront等のサービスがコンテンツをキャッシュし、利用者に近い場所から低レイテンシーで配信するために使用する拠点です。']}},

  // --- 追加分（キャッシュ・データセキュリティ・スケーリング） ---
  {id:'v53', term:'Amazon ElastiCache', domain:'tech', source:SOURCES.elasticache, q:{text:'Amazon ElastiCacheの役割として正しいものはどれですか？', choices:['RedisやMemcached等のインメモリキャッシュをマネージドで運用し、データベースの負荷を減らしてアプリケーションの応答速度を向上させるサービス','S3に保存したオブジェクトを長期保管用の低コストストレージクラスへ自動的に移行するサービス','複数のAZにEC2インスタンスへのトラフィックを分散するサービス','オンプレミスとAWSの間に専用線接続を確立するサービス'], correct:0, why:['正しい。ElastiCacheはRedisやMemcached等のインメモリキャッシュエンジンをマネージドで提供し、頻繁にアクセスされるデータをキャッシュすることでデータベース負荷を減らし、応答速度を向上させます。','これはAmazon S3のライフサイクルルール（S3 Glacier等への移行）の説明です。','これはElastic Load Balancingの説明です。','これはAWS Direct Connectの説明です。']}},
  {id:'v54', term:'Amazon Macie', domain:'security', source:SOURCES.macie, q:{text:'Amazon Macieの役割として正しいものはどれですか？', choices:['DDoS攻撃からリソースを保護するサービス','AWS環境内の不審なAPIコールやネットワーク挙動を検知するサービス','機械学習とパターンマッチングを使い、S3内のデータから個人情報(PII)などの機密データを自動的に検出・可視化するサービス','暗号鍵を作成・管理するサービス'], correct:2, why:['これはAWS Shieldの説明です。','これはAmazon GuardDutyの説明です。','正しい。Amazon Macieは機械学習とパターンマッチングを用いて、S3バケット内のPIIなどの機密データを検出し、データセキュリティのリスクを可視化するサービスです。','これはAWS KMSの説明です。']}},
  {id:'v55', term:'Horizontal Scaling (Scale Out)', domain:'concepts', source:SOURCES.autoscaling, q:{text:'「水平スケーリング（スケールアウト）」とは何ですか？', choices:['単一のサーバーのCPUやメモリをより高性能なものに置き換えること','既存サーバーの台数は変えずにストレージ容量だけを増やすこと','インスタンスの稼働するリージョンを変更すること','同種のインスタンスの台数を増やすことで、全体の処理能力を増強すること'], correct:3, why:['これは垂直スケーリング（スケールアップ）の説明です。','ストレージ容量の拡張はスケーリングの一種ですが、水平スケーリングの定義そのものではありません。','リージョンの変更はスケーリングとは異なる概念です。','正しい。水平スケーリング（スケールアウト）は、Auto Scaling等で同種のインスタンスの台数を増減させることで処理能力を調整する方式です。']}},
  {id:'v56', term:'Vertical Scaling (Scale Up)', domain:'concepts', source:SOURCES.ec2, q:{text:'「垂直スケーリング（スケールアップ）」とは何ですか？', choices:['インスタンスの台数を増やして処理能力を増強すること','複数のアベイラビリティーゾーンにインスタンスを分散すること','1台のインスタンスをより高いCPU・メモリ性能のインスタンスタイプに変更することで処理能力を増強すること','無料利用枠の範囲内でリソースを使い続けること'], correct:2, why:['これは水平スケーリング（スケールアウト）の説明です。','これはマルチAZ構成の説明であり、スケーリングの方式とは異なります。','正しい。垂直スケーリング（スケールアップ）は、EC2インスタンスのタイプをより高性能なものに変更して処理能力を増強する方式です。多くの場合、変更には再起動が必要です。','Free Tierの説明であり、スケーリングとは無関係です。']}},
  {id:'v57', term:'AWS Cloud Adoption Framework (CAF)', domain:'concepts', source:SOURCES.caf, q:{text:'AWS Cloud Adoption Framework (AWS CAF) とは何ですか？', choices:['組織がクラウドへの移行・変革を計画・実行するためのガイダンスをまとめたフレームワーク','EC2インスタンスの性能を自動的に最適化するサービス','AWSの利用料金を監視し予算超過を通知するサービス','IAMユーザーの認証情報を一元管理するサービス'], correct:0, why:['正しい。AWS CAFは、ビジネス・人材・ガバナンス・プラットフォーム・セキュリティ・運用の観点から、組織がクラウド導入・変革を進めるための指針をまとめたフレームワークです。','これはAWS Compute Optimizerの説明です。','これはAWS Budgetsの説明です。','これはAWS IAM Identity Centerの説明です。']}},
  {id:'v58', term:'AWS IAM Identity Center', domain:'security', source:SOURCES.iamIdentityCenter, q:{text:'AWS IAM Identity Centerの主な役割は何ですか？', choices:['個々のEC2インスタンスへのネットワークアクセスを制御するファイアウォール機能','複数のAWSアカウントやビジネスアプリケーションへのシングルサインオン(SSO)によるアクセスを一元管理する機能','S3バケット内の機密データを自動的に検出する機能','オンプレミスとAWS間を専用線で接続する機能'], correct:1, why:['これはセキュリティグループの説明です。','正しい。IAM Identity Centerは、複数のAWSアカウントやクラウドアプリケーションへのアクセスをシングルサインオンで一元管理できるサービスです。','これはAmazon Macieの説明です。','これはAWS Direct Connectの説明です。']}},
  {id:'v59', term:'Amazon SNS', domain:'tech', source:SOURCES.sns, q:{text:'Amazon SNS (Simple Notification Service) とは何ですか？', choices:['メッセージを一時的に保持し受信側がポーリングして取得するキューイングサービス','アプリケーションの性能指標を収集・可視化する監視サービス','パブリッシャーからサブスクライバーへメッセージを配信するpub/sub型の通知サービス','仮想サーバー間のネットワーク通信を仲介するロードバランサー'], correct:2, why:['これはAmazon SQSの説明です。','これはAmazon CloudWatchの説明です。','正しい。Amazon SNSは、パブリッシャーが送信したメッセージを複数のサブスクライバー（メール、SMS、Lambda等）へ同時に配信するpub/sub型の通知サービスです。','これはElastic Load Balancingの説明です。']}},
  {id:'v60', term:'Consolidated Billing（一括支払い）', domain:'billing', source:SOURCES.consolidatedBilling, q:{text:'AWS Organizationsの「一括支払い（Consolidated Billing）」機能とは何ですか？', choices:['各メンバーアカウントが個別にAWSへ料金を支払う仕組み','サポートプランの料金のみを複数アカウントで分担する仕組み','無料利用枠を全メンバーアカウントで使い切るまで共有する仕組み','組織内の複数アカウントの請求を管理アカウントに集約し、利用量をまとめることでボリュームディスカウント等が適用されやすくなる仕組み'], correct:3, why:['誤り。一括支払いでは、管理アカウントが全メンバーアカウントの料金をまとめて支払います。','誤り。一括支払いは料金全体を対象とする仕組みで、サポート料金だけに限定されません。','誤り。無料利用枠の説明ではありません。','正しい。一括支払いは、組織内の複数アカウントの請求を管理アカウントに集約し、利用量を合算することでボリュームディスカウントなどが適用されやすくなる仕組みです。']}},
  {id:'v61', term:'AWS Systems Manager', domain:'tech', source:SOURCES.systemsManager, q:{text:'AWS Systems Managerの主な役割は何ですか？', choices:['SSHキーの管理や踏み台サーバーを使わずに、EC2インスタンス等のノードを一元的に表示・操作・運用できるようにする','Webアプリケーションへの攻撃をルールベースでフィルタリングする','リレーショナルデータベースの運用・保守を代行する','複数アカウントの請求を一つに集約する'], correct:0, why:['正しい。Systems Managerは、SSHキーや踏み台サーバーなしでEC2インスタンス等のノードを一元的に表示・操作できる運用管理サービスです（Session Manager機能など）。','これはAWS WAFの説明です。','これはAmazon RDSの説明です。','これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。']}},
  {id:'v62', term:'Amazon API Gateway', domain:'tech', source:SOURCES.apigateway, q:{text:'Amazon API Gatewayとは何ですか？', choices:['EC2インスタンスにアタッチするブロックストレージ','REST・HTTP・WebSocket形式のAPIを作成・公開・保護・監視できるマネージドサービス','DNSの名前解決を行うサービス','脆弱性スキャンを行うサービス'], correct:1, why:['これはAmazon EBSの説明です。','正しい。API Gatewayは、REST・HTTP・WebSocket APIを作成・公開・保護・監視できるマネージドサービスで、Lambda等のバックエンドと組み合わせて使われます。','これはAmazon Route 53の説明です。','これはAmazon Inspectorの説明です。']}},
  {id:'v63', term:'AWS Network Firewall', domain:'security', source:SOURCES.networkFirewall, q:{text:'AWS Network Firewallとは何ですか？', choices:['Webアプリケーション層の攻撃をフィルタリングするサービス','DDoS攻撃を検知し緩和するサービス','VPC単位でステートフルなトラフィック検査・フィルタリングを行うマネージドネットワークファイアウォール','インスタンス単位で動作するステートフルなファイアウォール'], correct:2, why:['これはAWS WAFの説明です。','これはAWS Shieldの説明です。','正しい。AWS Network Firewallは、VPC単位でステートフルなディープパケットインスペクションやルールベースのフィルタリングを行うマネージドネットワークファイアウォールです。','これはセキュリティグループの説明です（インスタンス単位で動作しますが、Network Firewallより狭い範囲です）。']}},
  {id:'v64', term:'Economies of Scale（規模の経済）', domain:'concepts', source:SOURCES.sixAdv, q:{text:'クラウドの「規模の経済(Economies of Scale)」とは何を指しますか？', choices:['リソースを自動的に増減できる特性','先行投資を運用費用に変換できる特性','複数リージョンに同時展開できる速さ','非常に多くの顧客の利用量を集約することで、個々の組織では実現できない低コスト構造を実現し、それが従量課金の低価格として還元される仕組み'], correct:3, why:['これは弾力性(Elasticity)の説明です。','これはCapEx/OpExの説明です。','これは俊敏性(Agility)に関連する説明です。','正しい。規模の経済は、AWSが非常に多くの顧客の利用を集約することでコスト構造を下げ、その低コストを利用者への低価格として還元する仕組みです。']}},
  {id:'v65', term:'Sustainability Pillar', domain:'concepts', source:SOURCES.wafSustainability, q:{text:'Well-Architected Frameworkの「持続可能性の柱」が重視する観点として正しいものはどれですか？', choices:['リソースの使用を最適化し、環境への影響（エネルギー消費等）を低減すること','DDoS攻撃からシステムを保護すること','料金を従量課金制にすること','複数のアベイラビリティーゾーンにインスタンスを分散配置すること'], correct:0, why:['正しい。持続可能性の柱は、クラウドワークロードが環境に与える影響を理解し、エネルギー消費や資源利用を最適化することに焦点を当てます。','これはセキュリティの柱（DDoS対策等）に関する内容です。','これは料金モデル（Pay-as-you-go）の説明であり、持続可能性の柱とは異なります。','これは信頼性の柱（高可用性設計）に関する内容です。']}},
  {id:'v66', term:'AWS Directory Service', domain:'security', source:SOURCES.directoryService, q:{text:'AWS Directory Serviceの役割として正しいものはどれですか？', choices:['Webアプリケーションへの攻撃をフィルタリングする','AWSクラウド上でMicrosoft Active Directoryを運用したり、既存のオンプレミスADと連携したりできるマネージド型ディレクトリサービス','暗号鍵を生成・管理する','DNSの名前解決を行う'], correct:1, why:['これはAWS WAFの説明です。','正しい。AWS Directory Serviceは、AWS Managed Microsoft ADの提供やAD Connectorによるオンプレミスとの連携など、複数の方式でディレクトリサービスを利用できるマネージド型サービスです。','これはAWS KMSの説明です。','これはAmazon Route 53の説明です。']}},
  {id:'v67', term:'Amazon EventBridge', domain:'tech', source:SOURCES.eventbridge, q:{text:'Amazon EventBridgeの役割として正しいものはどれですか？', choices:['リレーショナルデータベースを提供する','コンテナイメージを保存するレジストリ','AWSサービス・SaaSアプリケーション・自作アプリケーションからのイベントを受け取り、ルールに基づいて複数のターゲットにルーティングするサーバーレスのイベントバスサービス','仮想サーバーを提供するコンピューティングサービス'], correct:2, why:['これはAmazon RDSの説明です。','これはAmazon ECRの説明です。','正しい。EventBridgeは、イベントを受け取りルールに基づいてLambda等のターゲットにルーティングできる、サーバーレスのイベントバスサービスです。','これはAmazon EC2の説明です。']}},
  {id:'v68', term:'AWS Cost and Usage Report (CUR)', domain:'billing', source:SOURCES.cur, q:{text:'AWS Cost and Usage Report (CUR)の説明として正しいものはどれですか？', choices:['AWSサポートへの問い合わせ履歴をまとめたレポート','コンプライアンス関連の第三者認証レポート','リソースのパフォーマンスメトリクスをまとめたレポート','AWSの利用状況・コストに関する最も詳細なデータセットで、指定したS3バケットに1日1回CSV形式等で出力される'], correct:3, why:['これはAWS Supportのケース履歴の説明であり、CURとは異なります。','これはAWS Artifactが提供するレポートの説明です。','これはAmazon CloudWatchの説明です。','正しい。CURは、利用した製品・使用タイプ・操作ごとの行を含む、AWSで利用可能な最も詳細なコスト・利用状況データセットで、指定のS3バケットに定期的に出力されます。']}},
  {id:'v69', term:'AWS Batch', domain:'tech', source:SOURCES.batch, q:{text:'AWS Batchとは何ですか？', choices:['送信されたバッチジョブの量や要件に応じて、必要な量と種類のコンピューティングリソース（EC2やFargate等）を自動的にプロビジョニングして実行する、フルマネージドのバッチコンピューティングサービス','最大実行時間15分の短時間のイベント駆動型コードを実行するサーバーレスサービス','コンテナを実行するためのサーバー管理が不要なコンピューティングエンジン','需要に応じてEC2インスタンスの数を自動的に増減させるサービス'], correct:0, why:['正しい。AWS Batchは、送信されたジョブの量や要件に応じて最適な量・種類のコンピューティングリソースを自動的にプロビジョニングし、ジョブキューに基づいてバッチ処理を実行するフルマネージドサービスです。','これはAWS Lambdaの説明です（実行時間に上限があり、長時間のバッチ処理には不向きです）。','これはAWS Fargateの説明です。AWS BatchはFargate上でジョブを実行することもできますが、Fargate自体はジョブキューやスケジューリングの仕組みを持ちません。','これはAmazon EC2 Auto Scalingの説明です。']}},
  {id:'v70', term:'Amazon FSx', domain:'tech', source:SOURCES.fsx, q:{text:'Amazon FSxとは何ですか？', choices:['単一のEC2インスタンスにのみアタッチできるブロックストレージ','Windows File Server・Lustre・NetApp ONTAP・OpenZFSなど、人気のファイルシステムをベースにしたフルマネージドの共有ファイルストレージを提供するサービス','非構造化オブジェクトを保存する高耐久なストレージサービス','Linux向けにAWSネイティブに構築されたNFS対応のフルマネージドファイルストレージサービス'], correct:1, why:['これはAmazon EBSの説明です。','正しい。Amazon FSxは、Windows File Server・Lustre・NetApp ONTAP・OpenZFSといった人気のファイルシステムをベースにした、フルマネージドの共有ファイルストレージを複数の種類から選んで利用できるサービスです。','これはAmazon S3の説明です。','これはAmazon EFSの説明です。']}},
  {id:'v71', term:'Amazon Cognito', domain:'security', source:SOURCES.cognito, q:{text:'Amazon Cognitoの役割は何ですか？', choices:['AWSクラウド上でMicrosoft Active Directoryを運用するディレクトリサービス','AWSリソースへのアクセス権限を管理するサービス','Webアプリ・モバイルアプリにユーザーのサインアップ・サインイン機能や、外部IDプロバイダーとの連携によるアクセス制御を提供するサービス','機密情報（パスワードやAPIキー等）を安全に保管・ローテーションするサービス'], correct:2, why:['これはAWS Directory Serviceの説明です。','これはAWS IAMの説明です。IAMはAWSリソースへのアクセス権限を管理しますが、Cognitoは主にアプリのエンドユーザー向けの認証・認可を担います。','正しい。Amazon Cognitoは、ユーザープールによるサインアップ・サインイン機能や、IDプールによる外部IDプロバイダー（Google等）と連携したアクセス制御を提供するサービスです。','これはAWS Secrets Managerの説明です。']}},
  {id:'v72', term:'Performance Efficiency Pillar', domain:'concepts', source:SOURCES.wafPerformance, q:{text:'Well-Architected Frameworkの「パフォーマンス効率の柱」が重視する観点として正しいものはどれですか？', choices:['先行投資を従量課金の運用費用に変換すること','障害発生時にもシステムを継続稼働させること','環境への影響（エネルギー消費等）を低減すること','コンピューティングリソースを効率的に使用し、需要やテクノロジーの進化に応じてその効率を維持する方法を選択すること'], correct:3, why:['これはクラウドの経済的メリット（CapEx/OpEx）に関する内容です。','これは信頼性の柱に関する内容です。','これは持続可能性の柱に関する内容です。','正しい。パフォーマンス効率の柱は、システムリソースを効率的に使用し、需要の変化やテクノロジーの進化に応じて効率を維持する方法の選択に焦点を当てます。']}},

  // --- 追加分（Well-Architected Tool・Access Analyzer・Athena・Capacity Reservation） ---
  {id:'v73', term:'AWS Well-Architected Tool', domain:'concepts', source:SOURCES.watool, q:{text:'AWS Well-Architected Toolとは何ですか？', choices:['自分のワークロードをAWSのベストプラクティス（Well-Architected Frameworkの6つの柱）と比較して評価し、改善の推奨事項を得られる無料のツール','DDoS攻撃からワークロードを保護するサービス','ワークロードのコストを自動的に最適化し、支払いまで代行するサービス','IAMポリシーの過剰な権限を検出するサービス'], correct:0, why:['正しい。AWS Well-Architected Toolは、Well-Architected Frameworkの6つの柱に基づいてワークロードをレビューし、改善のための推奨事項を提示する無料のツールです。','これはAWS Shieldの説明です。','誤り。コストの自動最適化や支払いの代行を行うツールではなく、設計・運用のレビューを支援するツールです。','これはAWS IAM Access Analyzerの説明です。']}},
  {id:'v74', term:'AWS IAM Access Analyzer', domain:'security', source:SOURCES.accessAnalyzer, q:{text:'AWS IAM Access Analyzerの役割として正しいものはどれですか？', choices:['DDoS攻撃を検知し緩和する','S3バケットなどのリソースが、外部のAWSアカウントや公衆からアクセス可能な状態になっていないかを分析し、意図しない共有を検出する','データ暗号化に使う暗号鍵を作成・管理する','リソースの構成変更履歴を記録しコンプライアンス評価に使う'], correct:1, why:['これはAWS Shieldの説明です。','正しい。IAM Access Analyzerは論理推論を用いてリソースベースポリシーを分析し、外部アカウントや公衆に意図せず共有されているリソースを検出します。','これはAWS KMSの説明です。','これはAWS Configの説明です。']}},
  {id:'v75', term:'Amazon Athena', domain:'tech', source:SOURCES.athena, q:{text:'Amazon Athenaとは何ですか？', choices:['仮想サーバーを提供するコンピューティングサービス','データの収集・変換・結合（ETL）処理を行うサービス','Amazon S3に保存されたデータに対して、サーバーを管理せずに標準SQLで直接クエリを実行できるサーバーレスの分析サービス','ビジネスインテリジェンス向けのダッシュボードを作成するサービス'], correct:2, why:['これはAmazon EC2の説明です。','これはAWS Glueの説明です。','正しい。Amazon Athenaは、S3に保存されたデータに対してサーバーのプロビジョニングや管理をせずに標準SQLで直接クエリを実行できるサーバーレスの対話型分析サービスです。','これはAmazon QuickSightの説明です。']}},
  {id:'v76', term:'On-Demand Capacity Reservation', domain:'billing', source:SOURCES.capacityReservation, q:{text:'Amazon EC2のOn-Demand Capacity Reservationとは何ですか？', choices:['AWSの空きキャパシティを割引価格で利用できるが、AWSの都合で中断される可能性がある仕組み','1年または3年の使用量を契約することで割引を得られる料金モデル','特定のコンピューティングサービス横断で使用量を契約する料金モデル','特定のアベイラビリティーゾーンで、指定したインスタンスタイプの容量を必要な期間だけ確保できる仕組みで、料金はオンデマンド料金が基準となり自動的な割引は提供されない'], correct:3, why:['これはスポットインスタンスの説明です。','これはリザーブドインスタンス/Savings Plansの説明です。','これはSavings Plansの説明です。','正しい。On-Demand Capacity Reservationは、特定のAZで指定したインスタンスタイプの容量を必要な期間だけ確保できる仕組みです。容量確保自体に割引はなく、料金はオンデマンド料金が基準になります。']}},

  // --- 追加分（WorkSpaces・Control Tower・PrivateLink・Cost Anomaly Detection） ---
  {id:'v77', term:'Amazon WorkSpaces', domain:'tech', source:SOURCES.workspaces, q:{text:'Amazon WorkSpacesとは何ですか？', choices:['クラウド上でマネージド型の仮想デスクトップ(DaaS)を提供するサービス','オンプレミスとAWS間でファイルを安全に転送するサービス','コンテナイメージを保存するレジストリサービス','DNSの名前解決を行うサービス'], correct:0, why:['正しい。Amazon WorkSpacesは、Windows/Linux等のマネージド型仮想デスクトップ(Desktop as a Service)をクラウド上で提供するサービスです。','これはAWS DataSyncの説明です。','これはAmazon ECR(Elastic Container Registry)の説明です。','これはAmazon Route 53の説明です。']}},
  {id:'v78', term:'AWS Control Tower', domain:'concepts', source:SOURCES.controlTower, q:{text:'AWS Control Towerの役割として正しいものはどれですか？', choices:['単一アカウント内のコスト予算を管理する','ベストプラクティスに基づいたマルチアカウント環境(ランディングゾーン)を自動的にセットアップ・統制するサービス','EC2インスタンスの自動スケーリングを行う','オンプレミスとの専用線接続を確立する'], correct:1, why:['これはAWS Budgetsの説明です。','正しい。AWS Control Towerは、AWS Organizations等を活用し、ベストプラクティスに基づくマルチアカウント環境(ランディングゾーン)を自動構築・統制するサービスです。','これはAmazon EC2 Auto Scalingの説明です。','これはAWS Direct Connectの説明です。']}},
  {id:'v79', term:'AWS PrivateLink', domain:'security', source:SOURCES.privatelink, q:{text:'AWS PrivateLinkの役割として正しいものはどれですか？', choices:['インターネット経由でオンプレミスとVPCを暗号化接続する','複数のアベイラビリティーゾーンにトラフィックを分散する','インターネットを経由せずに、VPCとAWSサービスや他VPC/アカウントのサービスをプライベートに接続する','DDoS攻撃からアプリケーションを保護する'], correct:2, why:['これはAWS Site-to-Site VPNの説明です。','これはElastic Load Balancingの説明です。','正しい。AWS PrivateLinkは、インターネットゲートウェイやNAT、VPN等を使わずに、VPCエンドポイント経由でAWSサービスや他VPC上のサービスにプライベートに接続できます。','これはAWS Shieldの説明です。']}},
  {id:'v80', term:'AWS Cost Anomaly Detection', domain:'billing', source:SOURCES.costAnomalyDetection, q:{text:'AWS Cost Anomaly Detectionの役割として正しいものはどれですか？', choices:['予算の閾値を手動で設定し超過時にアラートを送る','複数アカウントを一括請求する','ベストプラクティスに基づく推奨事項を提示する','機械学習を使って通常と異なる異常なコスト・使用量のパターンを検知し通知する'], correct:3, why:['これはAWS Budgetsの説明です（Budgetsは手動で設定した閾値に基づきます）。','これはAWS Organizations（コンソリデーティッドビリング）の説明です。','これはAWS Trusted Advisorの説明です。','正しい。AWS Cost Anomaly Detectionは機械学習でコスト・使用量の異常なパターンを検知し、メールやAmazon SNS経由で通知します。']}},
  {id:'v81', term:'AWS Resource Access Manager (RAM)', domain:'security', source:SOURCES.ram, q:{text:'AWS RAMの役割として正しいものはどれですか？', choices:['複数のAWSアカウントの請求を一つにまとめる','自分のAWSアカウントが所有するリソースを、Organizations内の他アカウントやIAMロール/ユーザーと安全に共有できるようにする','IAMユーザーのアクセスキーを一元的にローテーションする','VPC間にプライベート接続を確立する'], correct:1, why:['これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。','正しい。AWS RAMは、自分が所有するリソースを他のAWSアカウント(Organizations内のアカウントやOU、個別アカウント)やIAMロール/ユーザーと安全に共有できるサービスです。','これはIAM/Secrets Managerなど認証情報管理の話であり、RAMの役割ではありません。','これはAWS PrivateLinkやVPCピアリング、Transit Gatewayの説明です。']}},
  {id:'v82', term:'AWS Backup', domain:'tech', source:SOURCES.backup, q:{text:'AWS Backupの役割として正しいものはどれですか？', choices:['オンプレミスとAWS間でファイルを転送・同期する','コンテナイメージを保存するレジストリを提供する','EC2・EBS・RDS・DynamoDB・EFSなど複数のAWSサービスのバックアップを一元化・自動化する','DNSの名前解決を行う'], correct:2, why:['これはAWS DataSyncの説明です。','これはAmazon ECRの説明です。','正しい。AWS Backupは、複数のAWSサービスにわたるバックアップポリシーを一つのコンソールで集中管理・自動化できるフルマネージドサービスです。','これはAmazon Route 53の説明です。']}},
  {id:'v83', term:'AWS Budgets', domain:'billing', source:SOURCES.budgets, q:{text:'AWS Budgetsの役割として正しいものはどれですか？', choices:['機械学習で異常なコストの急増を自動検知する','過去の利用履歴をもとにコストを可視化・分析する','複数アカウントの請求を一つにまとめて支払う','コスト・使用量・カバレッジに対して独自の予算を設定し、実績や予測が閾値を超えた場合にアラートを送る'], correct:3, why:['これはAWS Cost Anomaly Detectionの説明です。','これはAWS Cost Explorerの説明です。','これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。','正しい。AWS Budgetsは、コスト・使用量・カバレッジについて独自の予算を設定し、実績や予測支出がしきい値を超えた場合にアラートを送信できるサービスです。']}},
  {id:'v84', term:'Total Cost of Ownership (TCO)', domain:'concepts', source:SOURCES.costmgmt, q:{text:'クラウド移行の文脈における「総所有コスト(TCO)」とは何ですか？', choices:['ハードウェア購入費だけでなく、運用・保守・電力・人件費などを含めた、システムを保有・運用する際の総コスト','初期投資(CapEx)のみを指す会計上の分類','AWSの無料利用枠で削減できるコストの上限額','リザーブドインスタンス購入時の前払い額の合計'], correct:0, why:['正しい。TCOは初期費用だけでなく、運用・保守・人件費・電力等を含めたシステムの総保有コストを指し、オンプレミスとクラウドのコスト比較によく使われる指標です。','これはCapEx(資本支出)単体の説明であり、TCOは運用費(OpEx)も含みます。','これはAWS無料利用枠の説明であり、TCOとは異なります。','これはリザーブドインスタンスの前払いオプションの説明であり、TCO全体の定義ではありません。']}},
  {id:'v85', term:'AWS IAM Access Analyzer', domain:'security', source:SOURCES.accessAnalyzer, q:{text:'AWS IAM Access Analyzerの主な役割は何ですか？', choices:['EC2インスタンスの脆弱性を自動的にスキャンする','S3バケットやIAMロールなどのリソースが、組織外や想定外のエンティティに意図せず共有されていないかを検出する','アカウント全体のコストの異常な増加を検知する','DDoS攻撃からアプリケーションを保護する'], correct:1, why:['誤り。これはAmazon Inspectorの役割です。','正しい。IAM Access Analyzerは、論理推論を用いて、S3バケットやIAMロール等が組織外や想定外のエンティティと共有されていないかを検出します。','誤り。これはAWS Cost Anomaly Detectionの役割です。','誤り。これはAWS Shieldの役割です。']}},
  {id:'v86', term:'Amazon Textract', domain:'tech', source:SOURCES.textract, q:{text:'Amazon Textractとは何ですか？', choices:['音声をテキストに変換するサービス','テキストの感情分析やエンティティ抽出を行うサービス','スキャンした文書や画像から、活字・手書きのテキスト、フォーム、表のデータを自動的に抽出するサービス','文章を自然な音声に変換するサービス'], correct:2, why:['誤り。これはAmazon Transcribeの説明です。','誤り。これはAmazon Comprehendの説明です。','正しい。Amazon Textractは、機械学習を使って、スキャンした文書や画像から活字・手書きテキスト、フォーム、表のデータを自動的に検出・抽出するサービスです。','誤り。これはAmazon Pollyの説明です。']}},
  {id:'v87', term:'Amazon Polly', domain:'tech', source:SOURCES.polly, q:{text:'Amazon Pollyとは何ですか？', choices:['文書から活字・手書きのテキストを抽出するサービス','音声データをテキストに変換するサービス','テキストを様々な言語に翻訳するサービス','テキストを自然な音声に変換する音声合成（Text-to-Speech）サービス'], correct:3, why:['誤り。これはAmazon Textractの説明です。','誤り。これはAmazon Transcribeの説明です。','誤り。これはAmazon Translateの説明です。','正しい。Amazon Pollyは、深層学習を用いてテキストを自然な音声に変換する音声合成（Text-to-Speech）サービスです。']}},
  {id:'v88', term:'Loose Coupling（疎結合）', domain:'concepts', source:SOURCES.wafReliability, q:{text:'クラウドアーキテクチャにおける「疎結合（Loose Coupling）」とは何を指しますか？', choices:['キューなどを介してコンポーネント間の依存を減らし、一部の障害が全体に波及しにくくする設計','単一のサーバーにすべての処理を集約し、依存を一体化させる設計','すべてのコンポーネントを同期的に直接呼び出し合う設計','単一障害点を意図的に作り、管理を簡素化する設計'], correct:0, why:['正しい。疎結合は、Amazon SQSなどのキューを介した非同期連携などにより、コンポーネント間の依存を減らし、一部の障害が全体に波及しにくくする設計です。','誤り。これは単一障害点を生みやすい集中設計で、疎結合とは逆の考え方です。','誤り。同期的な直接呼び出しが多い設計は密結合（Tight Coupling）に近く、疎結合とは逆です。','誤り。単一障害点はむしろ避けるべき設計上の弱点であり、疎結合の目的に反します。']}},
  {id:'v89', term:'AWS Database Migration Service (DMS)', domain:'tech', source:SOURCES.dms, q:{text:'AWS Database Migration Service (DMS) とは何ですか？', choices:['EC2インスタンスの性能を自動的に最適化するサービス','リレーショナルデータベースやNoSQLデータベースなどのデータストアを、オンプレミスとAWSの間やクラウド間で移行できるサービスで、移行中も継続的なレプリケーションが可能','コンテナイメージを保存するレジストリサービス','DNSの名前解決を行うサービス'], correct:1, why:['これはAWS Compute Optimizerの説明です。','正しい。AWS DMSは、データベースやデータウェアハウス等を移行先へ移行するサービスで、1回限りの移行だけでなく継続的なレプリケーションにも対応します。','これはAmazon ECRの説明です。','これはAmazon Route 53の説明です。']}},
  {id:'v90', term:'AWS CloudHSM', domain:'security', source:SOURCES.cloudhsm, q:{text:'AWS CloudHSMの特徴として正しいものはどれですか？', choices:['S3内の個人情報(PII)などの機密データを自動的に検出するサービス','AWSが鍵管理の大部分を担うマネージド型の暗号鍵管理サービスで、AWS KMSと同じ運用モデルを持つ','利用者専有のハードウェアセキュリティモジュール(HSM)を提供し、鍵のライフサイクル管理をより細かく利用者自身がコントロールできるサービス','Webアプリケーションへの攻撃をルールでフィルタリングするサービス'], correct:2, why:['これはAmazon Macieの説明です。','誤り。この運用モデルはAWS KMSの説明であり、CloudHSMはより利用者側の管理責任が大きい専有HSMです。','正しい。AWS CloudHSMは専有のHSMクラスタを提供し、FIPS 140-2等の要件がある場合などに、利用者自身が鍵のライフサイクルをより細かく管理できます。','これはAWS WAFの説明です。']}},
  {id:'v91', term:'RTO / RPO', domain:'concepts', source:SOURCES.wafReliability, q:{text:'ディザスタリカバリにおける「RTO」と「RPO」の説明として正しいものはどれですか？', choices:['RTOとRPOはいずれも料金モデルの名称である','RTOとRPOはいずれもリージョン間のレイテンシーを測定する指標である','RTOは許容できるデータ損失の時間的範囲、RPOは障害復旧にかかる時間の目標値を指す','RTOは障害復旧にかかる時間の目標値、RPOは許容できるデータ損失の時間的範囲を指す'], correct:3, why:['誤り。料金モデルとは無関係の概念です。','誤り。レイテンシー指標ではなく、復旧時間とデータ損失許容量の指標です。','誤り。RTOとRPOの説明が入れ替わっています。','正しい。RTO(目標復旧時間)は障害発生からサービス復旧までに許容される時間、RPO(目標復旧時点)は障害発生時に許容できるデータ損失の時間的範囲を指します。']}},
  {id:'v92', term:'AWS CodePipeline', domain:'tech', source:SOURCES.codepipeline, q:{text:'AWS CodePipelineとは何ですか？', choices:['ソフトウェアのリリースプロセスの各ステージ（ビルド・テスト・デプロイ等）をモデル化し自動化する継続的デリバリーサービス','S3に保存したデータへ標準SQLで直接クエリを実行するサービス','複数のAWSアカウントを一括請求するサービス','オンプレミスとAWS間でファイルを安全に転送するサービス'], correct:0, why:['正しい。AWS CodePipelineは、ソフトウェアリリースに必要なビルド・テスト・デプロイ等のステージをモデル化し、継続的デリバリーを自動化するサービスです。','これはAmazon Athenaの説明です。','これはAWS Organizations（コンソリデーティッドビリング）の説明です。','これはAWS Transfer Familyの説明です。']}},
  {id:'v93', term:'VPC Flow Logs', domain:'security', source:SOURCES.vpcFlowLogs, q:{text:'Amazon VPC Flow Logsとは何ですか？', choices:['VPC内のAPIコール履歴を記録するサービス','VPC内のネットワークインターフェースを通過するIPトラフィック情報を取得する機能','VPCのリソース設定変更履歴を記録するサービス','VPC内の脆弱性を自動スキャンするサービス'], correct:1, why:['これはAWS CloudTrail（APIコール履歴の記録）の説明です。','正しい。VPC Flow Logsは、VPC内のネットワークインターフェースを通過するIPトラフィック情報を取得し、セキュリティグループルールの診断などに利用できる機能です。','これはAWS Config（リソース設定変更履歴の記録）の説明です。','これはAmazon Inspector（脆弱性スキャン）の説明です。']}},
  {id:'v94', term:'Amazon MSK', domain:'tech', source:SOURCES.msk, q:{text:'Amazon MSK (Managed Streaming for Apache Kafka)とは何ですか？', choices:['リレーショナルデータベースのマネージドサービス','メッセージをポーリング型で配信するシンプルなキューサービス','Apache Kafkaを使ったストリーミングデータ処理をフルマネージドで実行できるサービス','メールの送受信を行うマネージドサービス'], correct:2, why:['これはAmazon RDS（リレーショナルデータベース）の説明です。','これはAmazon SQS（キューサービス）の説明に近く、Kafkaベースのストリーミング基盤ではありません。','正しい。Amazon MSKは、Apache Kafkaのクラスター運用を代行するフルマネージドサービスで、ストリーミングデータの処理に使われます。','これはAmazon SES（メール送受信）の説明です。']}},
  {id:'v95', term:'Pay-As-You-Go', domain:'concepts', source:SOURCES.pricing, q:{text:'AWSの「従量課金制（Pay-As-You-Go）」とは何ですか？', choices:['利用した分だけ料金を支払う、長期契約が不要な料金モデル','1年単位の固定金額を前払いする料金モデル','無料利用枠のみで運用する料金モデル','すべてのリージョンで同一料金が保証される制度'], correct:0, why:['正しい。Pay-As-You-Goは使った期間・量に応じて支払う料金モデルで、長期契約や複雑なライセンスは不要です。','これはリザーブドインスタンスのような前払い型の料金モデルの説明です。','これは無料利用枠（Free Tier）単体の説明であり、Pay-As-You-Goの定義ではありません。','AWSの料金はリージョンごとに異なる場合があり、全リージョン同一料金が保証される制度ではありません。']}},
  {id:'v96', term:'AWS Audit Manager', domain:'security', source:SOURCES.auditManager, q:{text:'AWS Audit Managerの役割として正しいものはどれですか？', choices:['AWSのコンプライアンス報告書(SOC、ISO等)を自己サービスでダウンロードする','セキュリティの検出結果を集約し優先順位付けする','AWSの利用状況を継続的に監査し、コンプライアンス評価に必要な証拠(エビデンス)の収集を自動化する','複数アカウントのリソース設定の変更履歴を記録する'], correct:2, why:['これはAWS Artifactの説明です。','これはAWS Security Hubの説明です。','正しい。AWS Audit Managerは、ポリシーや管理策(コントロール)が有効に機能しているかを評価するためのエビデンス収集を自動化し、監査を支援します。','これはAWS Configの説明です。']}},
  {id:'v97', term:'Elasticity', domain:'concepts', source:SOURCES.sixAdv, q:{text:'クラウドコンピューティングにおける「弾力性(Elasticity)」とは何を指しますか？', choices:['複数のリージョンにまたがってリソースを分散配置すること','利用者の操作なしにインフラのセキュリティパッチを自動適用すること','長期契約により利用料金の割引を受けられること','需要の変化に応じてコンピューティングリソースを自動的に増減できること'], correct:3, why:['これはマルチリージョン構成（可用性・DR）の説明です。','これは責任共有モデルにおけるAWS側の責任範囲の一部ですが、弾力性の定義ではありません。','これはリザーブドインスタンスやSavings Plansの説明です。','正しい。弾力性とは、需要の増減に応じてリソースを自動的にスケールイン/アウトできる能力のことです。これにより事前のキャパシティ予測が不要になります。']}},
  {id:'v98', term:'Amazon Translate', domain:'tech', source:SOURCES.translate, q:{text:'Amazon Translateとは何ですか？', choices:['機械学習を使ってテキストをある言語から別の言語に翻訳するサービス','音声データをテキストに変換するサービス','テキストを自然な音声に変換するサービス','テキストから感情やエンティティを抽出するサービス'], correct:0, why:['正しい。Amazon Translateは機械学習を用いてテキストを高品質に翻訳するサービスです。','これはAmazon Transcribe（音声認識）の説明です。','これはAmazon Polly（音声合成）の説明です。','これはAmazon Comprehend（自然言語処理）の説明です。']}},
  {id:'v99', term:'Service Control Policy (SCP)', domain:'security', source:SOURCES.scp, q:{text:'AWS Organizationsの「サービスコントロールポリシー (SCP)」の説明として正しいものはどれですか？', choices:['IAMユーザーやロールに直接アクセス権限を付与するポリシー','組織内のメンバーアカウント（管理アカウントを除く）のIAMユーザー・ロールが利用できる権限の上限（ガードレール）を設定するポリシーで、それ自体は権限を付与しない','特定のS3バケットなど個々のリソースに対して誰がアクセスできるかを定義するポリシー','AWS Configが検出したリソースの構成がベストプラクティスに準拠しているかを継続的に評価する仕組み'], correct:1, why:['誤り。SCP自体は権限を付与しません。権限の付与はIAMのアイデンティティベースポリシーやリソースベースポリシーが行います。','正しい。SCPは組織内のメンバーアカウントのIAMユーザー・ロールが利用できる権限の上限を設定するガードレールで、権限を付与するものではなく、管理アカウントには影響しません。','これはリソースベースポリシー（例: S3バケットポリシー）の説明です。','これはAWS Configの説明です。']}},
  {id:'v100', term:'Replatform（リプラットフォーム）', domain:'concepts', source:SOURCES.migrationStrategies, q:{text:'移行戦略の一つ「リプラットフォーム(Replatform)」の説明として正しいものはどれですか？', choices:['アプリケーションのコア部分を全面的に書き換え、クラウドネイティブな設計に変更すること','アプリケーションをそのまま、変更を加えずにクラウドへ移行すること','アプリケーションのコアアーキテクチャは変更せず、自前運用のデータベースをAmazon RDS等のマネージド型サービスに置き換えるなど、クラウドの利点を活かすための最小限の最適化を加えて移行すること','使われていないアプリケーションを移行せず廃止すること'], correct:2, why:['これは「リファクタ／リアーキテクト(Refactor)」の説明です。','これは「リホスト(Rehost)」の説明です。','正しい。リプラットフォームは、アプリケーションのコア部分は変更せず、自前運用のミドルウェア等をマネージド型サービスに置き換えるなどの最小限の最適化を行う移行戦略です。','これは「リタイア(Retire)」の説明です。']}},
  {id:'v101', term:'AWS Marketplace', domain:'billing', source:SOURCES.marketplace, q:{text:'AWS Marketplaceとは何ですか？', choices:['AWSが提供する公式のサポートプランの契約ページ','AWSのコストを可視化するダッシュボード','リザーブドインスタンスを他の利用者と売買できるマーケットプレイス','サードパーティのソフトウェア（AMIやSaaS等）を検索・購入・デプロイでき、利用料金がAWSの請求に一括でまとめられるデジタルカタログ'], correct:3, why:['これはAWS Supportプランの説明です。','これはAWS Cost Explorer等の説明です。','誤り。リザーブドインスタンスの売買ができるのはReserved Instance Marketplaceであり、AWS Marketplace（サードパーティ製品のカタログ）とは異なります。','正しい。AWS Marketplaceは、サードパーティ製のソフトウェア（AMIやSaaS等）を検索・購入・デプロイでき、その利用料金をAWSの請求にまとめて含めることができるデジタルカタログです。']}},
  {id:'v102', term:'Amazon Inspector', domain:'security', source:SOURCES.inspector, q:{text:'Amazon Inspectorの役割として正しいものはどれですか？', choices:['DDoS攻撃からアプリケーションを保護する','EC2インスタンスやコンテナイメージ、Lambda関数を自動的・継続的にスキャンし、ソフトウェアの脆弱性や意図しないネットワーク露出を検出する','IAMユーザーの権限設定を分析し、外部共有を検出する','複数アカウントの請求を一括管理する'], correct:1, why:['誤り。これはAWS Shieldの説明です。','正しい。Amazon Inspectorは、EC2・ECR上のコンテナイメージ・Lambda関数を自動的に継続的スキャンし、既知の脆弱性や意図しないネットワーク露出を検出します。','誤り。これはAWS IAM Access Analyzerの説明です。','誤り。これはAWS Organizationsのコンソリデーティッドビリングの説明です。']}},
  {id:'v103', term:'Amazon SQS', domain:'tech', source:SOURCES.sqs, q:{text:'Amazon Simple Queue Service (SQS) の役割として正しいものはどれですか？', choices:['複数のEC2インスタンスにトラフィックを分散する','DNSの名前解決を行う','メッセージをキューに格納し、送信側と受信側を疎結合にしてコンポーネント間の非同期通信を実現する','リレーショナルデータベースをマネージドで提供する'], correct:2, why:['誤り。これはElastic Load Balancingの説明です。','誤り。これはAmazon Route 53の説明です。','正しい。Amazon SQSはフルマネージドのメッセージキューイングサービスで、メッセージをキューに保持することで送信側・受信側を疎結合にし、非同期通信を実現します。','誤り。これはAmazon RDSの説明です。']}},
  {id:'v104', term:'Amazon EMR', domain:'tech', source:SOURCES.emr, q:{text:'Amazon EMRとは何ですか？', choices:['リレーショナルデータベースを提供するマネージドサービス','サーバーレスで標準SQLを使いS3のデータに直接クエリを実行するサービス','Apache HadoopやApache Sparkなどのビッグデータフレームワークを実行するためのマネージドクラスターサービス','全文検索・あいまい検索に対応した検索エンジンサービス'], correct:2, why:['これはAmazon RDSの説明です。','これはAmazon Athenaの説明です。','正しい。Amazon EMR（旧称Amazon Elastic MapReduce）は、Apache HadoopやApache Sparkなどのビッグデータフレームワークを大規模に実行するためのマネージドクラスターサービスです。','これはAmazon OpenSearch Serviceの説明です。']}},
  {id:'v105', term:'AWS Local Zones', domain:'concepts', source:SOURCES.localZones, q:{text:'AWS Local Zonesとは何ですか？', choices:['世界中のリージョンをまとめて管理する請求上の単位','CloudFrontがコンテンツをキャッシュするための拠点','1つ以上のデータセンターで構成されるリージョン内の独立した拠点','大都市圏の近くにコンピューティングやストレージなどのAWSサービスを配置し、低レイテンシーが必要なアプリケーションに対応するためのリージョンの拡張拠点'], correct:3, why:['これは請求管理の単位の説明であり、Local Zonesとは異なります。','これはエッジロケーションの説明です。','これはアベイラビリティーゾーンの説明です。','正しい。AWS Local Zonesは、大都市圏の近くにコンピューティングやストレージなどのAWSサービスを配置し、低レイテンシーが要求されるアプリケーションに対応するためのリージョンの拡張拠点です。']}},
  {id:'v106', term:'Security Pillar（セキュリティの柱）', domain:'security', source:SOURCES.wafSecurity, q:{text:'Well-Architected Frameworkの「セキュリティの柱」が重視する観点として正しいものはどれですか？', choices:['リソースの使用を最適化し、環境への影響を低減すること','リスク評価や緩和戦略を適用しながら、データ・システム・資産を保護し、情報セキュリティの価値を向上させること','需要やテクノロジーの進化に応じて、リソースを効率的に使用する方法を選択すること','不要なコストを排除し、最も費用対効果の高い方法でビジネス価値を実現すること'], correct:1, why:['これは持続可能性の柱に関する内容です。','正しい。セキュリティの柱は、リスク評価と緩和戦略の適用を通じて情報・システム・資産を保護し、セキュリティ体制の価値を高めることに焦点を当てます。','これはパフォーマンス効率の柱に関する内容です。','これはコスト最適化の柱に関する内容です。']}},
  {id:'v107', term:'Cost Optimization Pillar（コスト最適化の柱）', domain:'concepts', source:SOURCES.wafCost, q:{text:'Well-Architected Frameworkの「コスト最適化の柱」が重視する観点として正しいものはどれですか？', choices:['障害から復旧し、需要を満たすリソースを動的に調達する能力','データ・システムを保護し、リスクを評価・軽減すること','不要なコストを排除し、最もコスト効率の良い方法でビジネス価値を実現する能力を維持すること','システムを実行・監視し、継続的にプロセスや手順を改善すること'], correct:2, why:['これは信頼性の柱に関する内容です。','これはセキュリティの柱に関する内容です。','正しい。コスト最適化の柱は、不要なコストを排除し、ビジネス価値を最もコスト効率の良い方法で実現する能力を維持することに焦点を当てます。','これは運用上の優秀性の柱に関する内容です。']}},
  {id:'v108', term:'AWS Support プラン', domain:'billing', source:SOURCES.support, q:{text:'AWSサポートプランの説明として正しいものはどれですか？', choices:['すべてのプランが有料で、無料のプランは存在しない','上位プランほど無料利用枠(Free Tier)が多く付与される','サポートプランはAWS Organizationsのメンバーアカウントごとに個別の料金体系を持ち、一括請求はできない','Basic Supportは全てのAWSアカウントで自動的に無料で利用でき、Business Support+やEnterprise Support等の上位プランでは技術支援の応答時間短縮などが受けられる'], correct:3, why:['誤り。Basic Supportは全アカウントで自動的に無料で利用できます。','誤り。サポートプラン自体が無料利用枠の付与量を決めるものではありません。','誤り。AWS Organizationsの一括支払い（コンソリデーティッドビリング）により、組織内のサポート料金もまとめて扱うことができます。','正しい。Basic Supportは全アカウントで自動的に無料提供され、Business Support+やEnterprise Support等の有料プランでは技術支援の応答時間短縮やTAM(Technical Account Manager)等の追加サービスを受けられます。']}},
  {id:'v109', term:'AWS Elastic Disaster Recovery (DRS)', domain:'tech', source:SOURCES.drs, q:{text:'AWS Elastic Disaster Recovery (DRS)の役割として正しいものはどれですか？', choices:['EC2のオンデマンド容量を事前に確保しておくサービス','複数のAWSアカウントを一括管理するサービス','S3オブジェクトを低コストストレージクラスへ自動的に移行するサービス','オンプレミスやクラウド上のサーバーをAWSの低コストなステージング環境へ継続的にレプリケートし、障害発生時に短時間で復旧できるようにするディザスタリカバリサービス'], correct:3, why:['これはAmazon EC2 On-Demand Capacity Reservationの説明です。','これはAWS Organizationsの説明です。','これはAmazon S3のライフサイクルルールの説明です。','正しい。AWS Elastic Disaster Recoveryは、オンプレミスやクラウド上のサーバーをAWSアカウント内の低コストなステージングエリアへ継続的にレプリケートし、障害発生時に数分で復旧用インスタンスを起動できるディザスタリカバリサービスです。']}},
  {id:'v110', term:'Amazon Neptune', domain:'tech', source:SOURCES.neptune, q:{text:'Amazon Neptuneとは何ですか？', choices:['MongoDBと互換性のあるマネージド型ドキュメントデータベース','高度に関連したデータ（グラフデータ）を扱うアプリケーション向けの、高速で信頼性の高いフルマネージド型グラフデータベースサービス','大量データを高速に分析するためのマネージド型データウェアハウス','キーバリュー型・ドキュメント型のデータを扱うマネージド型NoSQLデータベース'], correct:1, why:['これはAmazon DocumentDBの説明です。','正しい。Amazon Neptuneは、ソーシャルネットワークやレコメンデーション、不正検知などの高度に関連したデータを扱うための、フルマネージド型グラフデータベースサービスです。','これはAmazon Redshiftの説明です。','これはAmazon DynamoDBの説明です。']}},
  {id:'v111', term:'AWS Transform MGN（旧AWS Application Migration Service, MGN）', domain:'concepts', source:SOURCES.mgn, q:{text:'AWS Transform MGN とは何ですか？', choices:['オンプレミスのデータをAWSに物理デバイス経由で転送するサービス','リレーショナルデータベースを別のデータベースエンジンへ移行するサービス','オンプレミスとS3間でファイルを安全に同期・転送するサービス','サーバーをブロックレベルで継続的にレプリケーションし、最小限のダウンタイムでリホスト（lift-and-shift）移行を自動化するサービス'], correct:3, why:['これはAWS Snowballの説明です。','これはAWS Database Migration Service (DMS)の説明です。','これはAWS DataSyncの説明です。','正しい。AWS Transform MGN（旧AWS Application Migration Service）は、ソースサーバーを継続的にブロックレベルでレプリケーションし、最小限のダウンタイムでAWSへのリホスト（lift-and-shift）移行を自動化するサービスです。']}},
  {id:'v112', term:'AWS Security Hub', domain:'security', source:SOURCES.securityHub, q:{text:'AWS Security Hubの役割として正しいものはどれですか？', choices:['単一のS3バケット内の機密データを検出する','複数のセキュリティサービス（GuardDuty、Inspector等）の検出結果を集約し、セキュリティ状態を一元的に可視化する','DDoS攻撃からアプリケーションを保護する','専用ハードウェアで暗号化キーを管理する'], correct:1, why:['これはAmazon Macieの説明です。','正しい。AWS Security Hubは複数のセキュリティサービスの検出結果を集約し、セキュリティとコンプライアンスの状態を一元的に可視化します。','これはAWS Shieldの説明です。','これはAWS CloudHSMの説明です。']}},
  {id:'v113', term:'AWS Elastic Beanstalk', domain:'tech', source:SOURCES.beanstalk, q:{text:'AWS Elastic Beanstalkとは何ですか？', choices:['オンプレミスとAWS間でデータを転送するサービス','複数のAWSアカウントを一元管理するサービス','専用のハードウェアでキーを管理するサービス','Webアプリケーションのデプロイに必要なインフラ（EC2、ロードバランサー等）の管理を自動化するPaaS型のサービス'], correct:3, why:['これはAWS DataSyncの説明です。','これはAWS Organizationsの説明です。','これはAWS CloudHSMの説明です。','正しい。AWS Elastic Beanstalkは、コードをアップロードするだけでEC2やロードバランサー等のインフラ構築・デプロイ・スケーリングを自動化してくれるPaaS型のサービスです。']}},
  {id:'v114', term:'Rehost（リホスト）', domain:'concepts', source:SOURCES.migrationStrategies, q:{text:'移行戦略の「リホスト（Rehost）」とは何ですか？', choices:['アプリケーションをほとんど変更せず、そのままクラウドへ移行する方法（リフト&シフト）','アプリケーションのコードやアーキテクチャを大幅に変更してからクラウドに移行する方法','古いアプリケーションを使い続けず廃止する方法','同様の機能を持つ新しい製品（SaaS等）に切り替える方法'], correct:0, why:['正しい。リホストはアプリケーションをほとんど変更せずそのままクラウドへ移行する「リフト&シフト」です。','これはリファクタリング（Refactor）の説明です。','これはリタイア（Retire）の説明です。','これはリパーチェス（Repurchase）の説明です。']}},
  {id:'v115', term:'AWS Resilience Hub', domain:'concepts', source:SOURCES.resilienceHub, q:{text:'AWS Resilience Hubの役割として正しいものはどれですか？', choices:['オンプレミスのサーバーをAWSへ移行(リホスト)するサービス','Well-Architected Frameworkに基づき、アプリケーションのレジリエンス目標を設定・評価し改善策を提示するサービス','複数リージョンにDNSトラフィックを振り分けるサービス','コンテナイメージを保存するレジストリサービス'], correct:1, why:['これはAWS Application Migration Service (MGN)の説明です。','正しい。AWS Resilience Hubは、Well-Architected Frameworkに基づきレジリエンス目標の設定・評価・改善策の提示を行うサービスです。','これはAmazon Route 53の説明です。','これはAmazon ECRの説明です。']}},
  {id:'v116', term:'AWS Billing Conductor', domain:'billing', source:SOURCES.billingConductor, q:{text:'AWS Billing Conductorの役割として正しいものはどれですか？', choices:['AWSの実際の請求額を変更し割引を適用するサービス','複数アカウントのコストを機械学習で異常検知するサービス','請求を1つのアカウントに統合するConsolidated Billingの機能そのもの','AWS Marketplaceのチャネルパートナーや組織のチャージバック要件向けに、独自の料金ルールに基づく第二の費用（プロフォーマコスト）を作成・共有できるカスタム請求サービス'], correct:3, why:['誤り。Billing Conductorは実際のAWSの請求額や支払い方法を変更するものではありません。','これはAWS Cost Anomaly Detectionの説明です。','これはAWS Organizationsの一括支払い(Consolidated Billing)の説明で、Billing Conductorはその上でカスタム料金を設定する別の機能です。','正しい。AWS Billing Conductorは、チャネルパートナーやチャージバック要件を持つ組織向けに、独自の料金ルールに基づくプロフォーマコストを作成・共有できるカスタム請求サービスです。']}},
  {id:'v117', term:'Savings Plans の種類', domain:'billing', source:SOURCES.savingsplansTypes, q:{text:'Savings Plansの種類のうち、EC2・Fargate・Lambdaを横断して柔軟に割引を適用できるが、EC2 Instance Savings Plansより割引率がやや低いものはどれですか？', choices:['EC2 Instance Savings Plans','リザーブドインスタンス','Compute Savings Plans','スポットインスタンス'], correct:2, why:['誤り。EC2 Instance Savings Plansは割引率が高い一方、特定のインスタンスファミリー・リージョンへの変更に制限されます。','誤り。リザーブドインスタンスは特定のインスタンスタイプ・リージョンに紐づく予約で、Savings Plansのようにサービス横断で柔軟に適用されるものではありません。','正しい。Compute Savings Plansは、インスタンスファミリー・リージョン・OS等にかかわらずEC2・Fargate・Lambdaの利用に柔軟に適用できる、最も柔軟なSavings Plansです。','誤り。スポットインスタンスは空き容量の活用による割引で、コミットメント型の割引ではありません。']}},
  {id:'v118', term:'多要素認証（MFA）', domain:'security', source:SOURCES.mfa, q:{text:'AWS IAMにおける多要素認証（MFA）の説明として正しいものはどれですか？', choices:['VPCとAWSサービスをプライベートに接続する仕組み','パスワード（サインイン認証情報）に加えて、認証アプリやセキュリティキーなど別の要素による確認を必須にすることで、アカウントのセキュリティを強化する仕組み','複数のリージョンにトラフィックを分散させる仕組み','IAMポリシーの権限の上限を組織全体に適用する仕組み'], correct:1, why:['これはAWS PrivateLinkの説明です。','正しい。MFAは、ユーザー名とパスワードに加えて、仮想認証アプリやセキュリティキーなどから生成される認証情報の入力を求めることで、不正アクセスのリスクを減らす仕組みです。ルートユーザー・IAMユーザーの両方に設定できます。','これはAmazon Route 53やAWS Global Acceleratorなどのトラフィック分散の説明です。','これはAWS OrganizationsのSCP（サービスコントロールポリシー）の説明です。']}},
  {id:'v119', term:'AWS Migration Evaluator', domain:'concepts', source:SOURCES.migrationEvaluator, q:{text:'AWS Migration Evaluatorとは何ですか？', choices:['オンプレミス環境の使用状況データを分析し、クラウド移行後のコストを見積もることで、データドリブンな移行のビジネスケースを構築できるサービス','構成を手動で入力してAWS利用料金を事前に見積もるツール','稼働中のAWSリソースの使用率を分析し、インスタンスタイプ等の最適化を提案するサービス','AWS環境のコスト・セキュリティ等のベストプラクティスをチェックするサービス'], correct:0, why:['正しい。Migration Evaluatorは、オンプレミスサーバーの使用状況を分析し、過剰プロビジョニングの特定やクラウド移行後のコスト見積もりを行い、データドリブンな移行のビジネスケース構築を支援します。','これはAWS Pricing Calculatorの説明です。','これはAWS Compute Optimizerの説明です。','これはAWS Trusted Advisorの説明です。']}},
  {id:'v120', term:'AWS Health Dashboard', domain:'billing', source:SOURCES.awsHealth, q:{text:'AWS Health Dashboardとは何ですか？', choices:['コストや使用量の予算を設定し、閾値超過時にアラートを送るツール','ベストプラクティスに基づく推奨事項をチェックするツール','機械学習により異常なコストパターンを検知するツール','AWSサービスの稼働状況や、自分のアカウント・リソースに影響する事象について、継続的な可視性とアラートを提供するサービス'], correct:3, why:['これはAWS Budgetsの説明です。','これはAWS Trusted Advisorの説明です。','これはAWS Cost Anomaly Detectionの説明です。','正しい。AWS Health Dashboardは、AWSサービスの稼働状況や、自分のアカウント・リソースに影響する事象について、継続的な可視性とアラート通知を提供するサービスです。']}},
  {id:'v121', term:'AWS Service Catalog', domain:'concepts', source:SOURCES.serviceCatalog, q:{text:'AWS Service Catalogとは何ですか？', choices:['組織が承認したIT製品（CloudFormationテンプレート等）をカタログ化し、エンドユーザーがセルフサービスで利用できるようにするサービス','複数アカウントにガードレールを適用し、ベストプラクティスに基づくランディングゾーンを自動構築するサービス','AWSリソースの使用状況を分析し、コスト削減の推奨事項を提示するサービス','複数のAWSアカウントを一括請求し、組織全体を管理するサービス'], correct:0, why:['正しい。AWS Service Catalogは、組織が承認したIT製品（CloudFormationテンプレート等）をポートフォリオとしてカタログ化し、エンドユーザーがセルフサービスで必要な製品を選んで起動できるようにするサービスです。','これはAWS Control Towerの説明です。','これはAWS Trusted Advisorの説明です。','これはAWS Organizationsの説明です。']}},
  {id:'v122', term:'Network ACL (NACL)', domain:'security', source:SOURCES.vpc, q:{text:'VPCにおける「ネットワークACL(NACL)」の特徴として正しいものはどれですか？', choices:['インスタンス(ENI)単位で動作し、許可ルールのみを設定できるステートフルなファイアウォール','サブネット単位で動作し、許可・拒否の両方のルールを番号順に評価するステートレスなファイアウォール','VPCとオンプレミスの間を専用線で接続する機能','インターネットを経由せずにAWSサービスにプライベート接続する機能'], correct:1, why:['これはセキュリティグループの特徴です。','正しい。ネットワークACL(NACL)はサブネット単位で動作し、ルール番号の小さい順に評価される許可・拒否両方を設定できるステートレスなファイアウォールです。','これはAWS Direct Connectの説明です。','これはAWS PrivateLinkの説明です。']}},
  {id:'v123', term:'AWS Site-to-Site VPN', domain:'tech', source:SOURCES.siteToSiteVpn, q:{text:'AWS Site-to-Site VPNとは何ですか？', choices:['オンプレミスとAWS間を専用線で接続するサービス','VPCとAWSサービスをインターネットを経由せずプライベートに接続するサービス','IPsecを用いて、公共のインターネット経由でオンプレミスとVPCの間に暗号化された接続を確立するサービス','複数のVPCやオンプレミス拠点を接続するハブとなるサービス'], correct:2, why:['これはAWS Direct Connectの説明です。専用線を使用し、インターネットを経由しません。','これはAWS PrivateLinkの説明です。','正しい。AWS Site-to-Site VPNは、IPsecを用いて公共のインターネット経由でオンプレミスとVPC間に暗号化された接続(VPN接続)を確立するサービスです。','これはAWS Transit Gatewayの説明です。']}},
  {id:'v124', term:'Amazon Detective', domain:'security', source:SOURCES.detective, q:{text:'Amazon Detectiveの役割として正しいものはどれですか？', choices:['悪意のある操作や異常な動作を継続的に検出する脅威検出サービス','GuardDutyやMacie等が検出したセキュリティ上の問題について、関連するログデータを自動的に収集・分析し、根本原因の調査を容易にするサービス','S3に保存された機密データ（個人情報等）を機械学習で自動的に検出・分類するサービス','複数のセキュリティサービスの検出結果を一つの画面に集約して表示するサービス'], correct:1, why:['これはAmazon GuardDutyの説明です。','正しい。Amazon Detectiveは、GuardDuty等が検出した問題に関連するログデータ（VPCフローログ、CloudTrail等）を自動的に収集・分析し、根本原因調査のための可視化を提供します。','これはAmazon Macieの説明です。','これはAWS Security Hubの説明です。']}},
  {id:'v125', term:'Reliability Pillar', domain:'concepts', source:SOURCES.wafReliability, q:{text:'AWS Well-Architected Frameworkの「信頼性の柱」が重視する観点として正しいものはどれですか？', choices:['障害を検知・自動復旧し、需要やインフラの変化に応じて動的にリソースを調整できるようにワークロードを設計すること','利用した分だけ料金を払い、不要なコストを継続的に削減すること','ビジネス価値を生まない作業を自動化し、変更を最小のリスクで本番環境に反映すること','最小限のリソースで最大の需要を満たし、環境負荷を低減すること'], correct:0, why:['正しい。信頼性の柱は、障害の検知・自動復旧や、需要・インフラの変化に応じた動的なリソース調整などによって、ワークロードが期待どおりに機能し続けることを重視します。','これはコスト最適化の柱の説明です。','これは運用上の優秀性の柱の説明です。','これは持続可能性の柱の説明です。']}},
  {id:'v126', term:'Amazon Security Lake', domain:'security', source:SOURCES.securityLake, q:{text:'Amazon Security Lakeの役割として正しいものはどれですか？', choices:['AWSアカウント・オンプレミス・SaaS・サードパーティなど多様なソースからセキュリティログ・イベントデータを自動的に収集し、OCSF（オープンな標準スキーマ）に正規化して自社アカウント内のデータレイクに集約するサービス','機械学習を用いて、AWS環境内の悪意のある操作や異常な動作を継続的に検出する脅威検出サービス','複数のセキュリティサービス(GuardDuty, Inspector, Macieなど)の検出結果を一つのダッシュボードに集約して表示するサービス','S3に保存されたデータの中から機密情報（個人情報等）を機械学習で自動的に検出・分類するサービス'], correct:0, why:['正しい。Amazon Security Lakeは、AWS環境・オンプレミス・SaaS・サードパーティなど多様なソースからセキュリティログ・イベントデータを自動的に収集し、Apache Parquet形式およびOCSF(Open Cybersecurity Schema Framework)に正規化して、利用者自身のAWSアカウント内(S3バケット)に構築されるデータレイクに集約するサービスです。','誤り。これはAmazon GuardDutyの説明です。','誤り。これはAWS Security Hubの説明です。','誤り。これはAmazon Macieの説明です。']}},
  {id:'v127', term:'Amazon Kinesis Data Streams', domain:'tech', source:SOURCES.kinesis, q:{text:'Amazon Kinesis Data Streamsの用途として正しいものはどれですか？', choices:['リレーショナルデータベースのセットアップ・運用・スケーリングをマネージドで行うサービス','大量のストリーミングデータ（ログ、センサーデータ、クリックストリームなど）をリアルタイムに収集・処理するためのサービス','メッセージを発行し複数のサブスクライバーに同時配信するパブリッシュ/サブスクライブ型のメッセージングサービス','キューにメッセージを格納し、アプリケーション間を疎結合にするメッセージキューイングサービス'], correct:1, why:['誤り。これはAmazon RDSの説明です。','正しい。Amazon Kinesis Data Streamsは、ログ、センサーデータ、クリックストリームなど大量のストリーミングデータをリアルタイムに収集し、継続的に処理・分析できるようにするサービスです。','誤り。これはAmazon SNSの説明です。','誤り。これはAmazon SQSの説明です。']}},
  {id:'v128', term:'AWS Step Functions', domain:'tech', source:SOURCES.stepFunctions, q:{text:'AWS Step Functionsの役割として正しいものはどれですか？', choices:['コードをアップロードするだけでサーバーの管理なしに実行できるイベント駆動型のコンピューティングサービス','複数のAWSサービスやSaaSアプリケーションからのイベントをルールに基づいてターゲットへ配信するイベントバスサービス','複数のAWS Lambda関数やその他のAWSサービスの実行順序をステートマシン（ワークフロー）として視覚的に定義・オーケストレーションするサービス','メッセージをキューに格納し、コンポーネント間の処理を非同期に疎結合化するサービス'], correct:2, why:['誤り。これはAWS Lambdaの説明です。','誤り。これはAmazon EventBridgeの説明です。','正しい。AWS Step Functionsは、複数のAWS Lambda関数や他のAWSサービスの呼び出し順序を、ステートマシン（ワークフロー）として視覚的に定義し、オーケストレーションするサービスです。','誤り。これはAmazon SQSの説明です。']}},
  {id:'v129', term:'コスト配分タグ (Cost Allocation Tags)', domain:'billing', source:SOURCES.costAllocTags, q:{text:'AWSのコスト配分タグ(Cost Allocation Tags)とは何ですか？', choices:['部門やプロジェクトごとに支出の上限を設定し、閾値を超えた場合に通知するサービス','請求データを詳細な明細としてS3に出力するレポート機能','複数のAWSアカウントの利用料金を一つの支払いアカウントにまとめ、ボリュームディスカウントの対象にする仕組み','AWSリソースに付与したタグ(キーと値のペア)に基づいて、コスト配分レポート上でコストを分類・整理できるようにする機能'], correct:3, why:['誤り。これはAWS Budgetsの説明です。','誤り。これはAWS Cost and Usage Report (CUR)の説明です。','誤り。これはConsolidated Billing（一括支払い）の説明です。','正しい。コスト配分タグは、AWSリソースに付与したタグ（キーと値のペア）に基づいて、コスト配分レポートやCost Explorer上でコストをプロジェクト・部門・環境などの単位に分類・整理できるようにする機能です。']}},
  {id:'v130', term:'Amazon Timestream', domain:'tech', source:SOURCES.timestream, q:{text:'Amazon Timestreamとは何ですか？', choices:['大量のタイムスタンプ付きデータ(時系列データ)の保存・分析に特化した、サーバーレスのマネージド型データベースサービス','リレーショナルデータベースのセットアップ・運用・スケーリングをマネージドで行うサービス','キーバリュー型・ドキュメント型のデータを格納するフルマネージドNoSQLデータベースサービス','データウェアハウスとして大規模なデータに対する高速な分析クエリを実行するサービス'], correct:0, why:['正しい。Amazon Timestreamは、センサーデータやアプリケーションのメトリクスなど、大量のタイムスタンプ付き時系列データを保存・分析するために設計された、サーバーレスのマネージド型データベースサービスです。','これはAmazon RDSの説明です。','これはAmazon DynamoDBの説明です。','これはAmazon Redshiftの説明です。']}},
  {id:'v131', term:'AWS IoT Core', domain:'tech', source:SOURCES.iotcore, q:{text:'AWS IoT Coreの役割として正しいものはどれですか？', choices:['コンテナイメージを保存・管理するレジストリサービス','MQTTなどのプロトコルを使って、大量のIoTデバイスを安全にAWSクラウドや他のデバイスに接続し、相互に通信できるようにするサービス','大量のストリーミングデータをリアルタイムに収集・処理するサービス','サーバーレスで特定のイベントに応じてコードを実行するコンピューティングサービス'], correct:1, why:['これはAmazon ECRの説明です。','正しい。AWS IoT Coreは、MQTTやMQTT over WSS、HTTPSなどのプロトコルを使って、大量のIoTデバイスをAWSクラウドや他のデバイス・サービスに安全に接続し、双方向の通信を可能にするサービスです。','これはAmazon Kinesis Data Streamsの説明です。','これはAWS Lambdaの説明です。']}},
  {id:'v132', term:'AWS Cost Categories', domain:'billing', source:SOURCES.costCategories, q:{text:'AWS Cost Categoriesとは何ですか？', choices:['AWSリソースに付与したタグに基づいてコストを分類する機能で、事前に各リソースへのタグ付けが前提となる機能','複数のAWSアカウントの請求を一つの支払いアカウントにまとめ、ボリュームディスカウントの対象にする仕組み','アカウント・サービス・タグなどの請求ディメンションに基づくルールを定義し、組織の部門やチームなど独自の構造に合わせてコストをグループ化・分類できる機能','設定した予算のしきい値を超えた場合にアラートを送信する機能'], correct:2, why:['誤り。これはAWSコスト配分タグ(Cost Allocation Tags)の説明です（Cost Categoriesはタグ付けが不完全な場合でもアカウントやサービスなど他のディメンションでコストを分類できます）。','誤り。これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。','正しい。AWS Cost Categoriesは、アカウント・サービス・タグなどの請求ディメンションに基づくルールを定義し、組織独自の部門やチームなどの構造に合わせてコストをグループ化・分類できる機能です。','誤り。これはAWS Budgetsの説明です。']}},
  {id:'v133', term:'AWS Private CA', domain:'security', source:SOURCES.acmpca, q:{text:'AWS Private CA (AWS Certificate Manager Private CA)とは何ですか？', choices:['インターネットに公開するWebサイト向けに無料のパブリックSSL/TLS証明書を発行・管理するサービス','DDoS攻撃を検知し自動的に緩和するサービス','データ暗号化に使う暗号鍵を作成・管理するサービス','社内システムやIoTデバイス認証など、組織内部で使用するプライベートな認証局(CA)階層を、自前でオンプレミスのCAを構築・運用することなく作成できるサービス'], correct:3, why:['誤り。これは（パブリックな証明書を扱う）AWS Certificate Manager (ACM)自体の説明です。Private CAは社内向けのプライベート証明書を扱います。','誤り。これはAWS Shieldの説明です。','誤り。これはAWS KMSの説明です。','正しい。AWS Private CAは、オンプレミスで自前の認証局を構築・運用するコストをかけずに、社内システムやIoTデバイス認証などに使うプライベートな認証局(ルートCA・下位CA)階層を作成できるサービスです。']}},
  {id:'v134', term:'AWS AppSync', domain:'tech', source:SOURCES.appsync, q:{text:'AWS AppSyncとは何ですか？', choices:['GraphQLおよびPub/Sub APIを通じて、複数のデータソースへのアクセスやリアルタイムの更新配信を行える、フルマネージドのサーバーレスAPIサービス','RESTfulなAPIの作成・公開・監視・保護を行うマネージドサービス','リレーショナルデータベースのクエリ結果をキャッシュするインメモリキャッシュサービス','アプリケーションのバックエンドを構成するコンテナを運用するオーケストレーションサービス'], correct:0, why:['正しい。AWS AppSyncは、GraphQLおよびPub/Sub APIを通じて複数のデータソースに単一のエンドポイントからアクセスし、アプリケーションにリアルタイムの更新を配信できる、フルマネージドのサーバーレスサービスです。','これはAmazon API Gateway（RESTful/HTTP/WebSocket APIの作成・公開・保護）の説明です。','これはAmazon ElastiCache（インメモリキャッシュ）の説明です。','これはAmazon ECS（コンテナオーケストレーション）の説明です。']}},
  {id:'v135', term:'AWS Fault Injection Service (FIS)', domain:'tech', source:SOURCES.fis, q:{text:'AWS Fault Injection Service (AWS FIS)とは何ですか？', choices:['アプリケーションのセキュリティ脆弱性を自動的にスキャンするサービス','カオスエンジニアリングの原則に基づき、本番相当の環境でわざと障害(フォールト)を注入する実験を行い、システムの耐障害性や回復性を検証できるマネージドサービス','アプリケーションの障害発生時に自動的に別リージョンへフェイルオーバーするDNSサービス','インフラの構成変更履歴を記録し、ベストプラクティスへの準拠を継続的に評価するサービス'], correct:1, why:['これはAmazon Inspector（脆弱性スキャン）の説明です。','正しい。AWS FISは、カオスエンジニアリングの原則に基づき、本番相当の環境で意図的に障害を注入する実験を行い、アプリケーションの耐障害性や回復性を検証できるマネージドサービスです。','これはAmazon Route 53のフェイルオーバールーティングの説明です。','これはAWS Configの説明です。']}},
  {id:'v136', term:'ボリュームディスカウント（段階的価格）', domain:'billing', source:SOURCES.pricing, q:{text:'AWSの料金モデルにおける「ボリュームディスカウント」とは何ですか？', choices:['1年または3年の利用を事前にコミットすることで割引を受けられる購入オプション','利用量が無料利用枠の範囲内であれば料金が発生しない仕組み','Amazon S3のストレージ料金やデータ転送料金など一部のサービスで、利用量が増えるほど段階的に単価が下がる料金体系','複数のAWSアカウントの利用量を合算し、組織全体でまとめて料金を支払う仕組み'], correct:2, why:['これはリザーブドインスタンスやSavings Plansのような事前コミット型の割引購入オプションの説明です。','これはAWS無料利用枠の説明です。','正しい。ボリュームディスカウントは、Amazon S3のストレージ料金やデータ転送料金などで見られる、利用量が増えるほど段階的に単価(1GBあたりの料金等)が下がる料金体系です。','これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。']}},
  {id:'v137', term:'効率の測定（Measure Overall Efficiency）', domain:'concepts', source:SOURCES.wafCost, q:{text:'AWS Well-Architected Frameworkの「コスト最適化の柱」の設計原則の一つ「効率の測定(Measure Overall Efficiency)」が重視する内容として正しいものはどれですか？', choices:['開発・テスト環境は使用していない時間帯は停止し、使用した分のみ料金を支払うこと','サーバーのラッキングや電源管理など、データセンター運用の重労働をAWSに任せ、差別化につながらない作業への投資を減らすこと','コストと使用状況を正確に特定し、ITコストを収益やワークロード所有者に透過的に帰属させること','ワークロードのビジネス上の成果(アウトプット)と、それを実現するためにかかったコストの両方を測定し、出力や機能の増加によって得られる効果を把握すること'], correct:3, why:['これは「消費モデルの導入(Adopt a consumption model)」という別の設計原則の内容です。','これは「差別化につながらない重労働への投資をやめる」という別の設計原則の内容です。','これは「費用の分析と帰属(Analyze and attribute expenditure)」という別の設計原則の内容です。','正しい。「効率の測定」は、ワークロードのビジネス上の成果とそれにかかるコストの両方を測定し、アウトプットや機能の増加によって得られる効果を把握することを重視する設計原則です。']}},
  {id:'v138', term:'AWS Verified Access', domain:'security', source:SOURCES.verifiedAccess, q:{text:'AWS Verified Accessとは何ですか？', choices:['VPNを使わずに、ユーザーのID情報やデバイスの状態をリクエストごとに評価し、社内アプリケーションへのゼロトラストなアクセスを実現するサービス','DDoS攻撃からAWSリソースを保護するサービス','複数のAWSアカウントに共通のセキュリティルール(AWS WAFやAWS Shield Advanced等)を一元的に適用するサービス','オンプレミスとAWS間を専用線で接続するサービス'], correct:0, why:['正しい。AWS Verified Accessは、VPNを使わずに、リクエストごとにユーザーのID情報やデバイスの状態を評価してアクセスを許可するかどうかを判断する、ゼロトラスト型のアクセス方式を実現するサービスです。','これはAWS Shieldの説明です。','これはAWS Firewall Managerの説明です。','これはAWS Direct Connectの説明です。']}},
  {id:'v139', term:'AWS Pricing Calculator', domain:'billing', source:SOURCES.pricingcalc, q:{text:'AWS Pricing Calculatorとは何ですか？', choices:['実際の利用量に基づいて請求書を生成し、支払いを処理するサービス','AWSを利用していない段階でも、想定するサービス構成や使用量を入力して月額コストの見積もりを作成できる、無料のWebベースツール','過去の利用履歴を分析し、購入すべきリザーブドインスタンスやSavings Plansを推奨するサービス','稼働中のEC2インスタンス等の使用率を分析し、インスタンスタイプの最適化を提案するサービス'], correct:1, why:['これはAWSの請求・支払い処理機能の説明です。','正しい。AWS Pricing Calculatorは、AWSを利用する前の段階でも想定する構成や使用量を入力して、月額コストの見積もりを作成できる無料のツールです。','これはAWS Cost Explorerの購入推奨機能の説明です。','これはAWS Compute Optimizerの説明です。']}},
  {id:'v140', term:'Amazon OpenSearch Service', domain:'tech', source:SOURCES.opensearch, q:{text:'Amazon OpenSearch Serviceとは何ですか？', choices:['リレーショナルデータベースのクエリ結果をキャッシュするインメモリサービス','Amazon S3に保存されたデータに対して直接SQLクエリを実行するサービス','ログ分析や全文検索などに使われる、スケーラブルな検索・分析エンジンをマネージドサービスとして提供するサービス','構造化データを可視化してBIダッシュボードを作成するサービス'], correct:2, why:['これはAmazon ElastiCacheの説明です。','これはAmazon Athenaの説明です。','正しい。Amazon OpenSearch Serviceは、ログ分析や全文検索などに使われるスケーラブルな検索・分析エンジンをマネージドサービスとして提供します。','これはAmazon QuickSightの説明です。']}},
  {id:'v141', term:'AWS Outposts', domain:'concepts', source:SOURCES.outposts, q:{text:'AWS Outpostsとは何ですか？', choices:['AWSが提供するマネージド型の仮想デスクトップサービス','オンプレミスとAWS間でファイルを安全に同期するサービス','複数のAWSアカウントを一括管理するサービス','AWSのコンピューティング・ストレージ・APIをオンプレミスのデータセンターに拡張し、クラウドと一貫性のあるハイブリッドな運用を実現するサービス'], correct:3, why:['これはAmazon WorkSpacesの説明です。','これはAWS DataSyncの説明です。','これはAWS Organizationsの説明です。','正しい。AWS Outpostsは、AWSのコンピューティング・ストレージ機能やAPIをオンプレミスのデータセンターに拡張し、クラウドと一貫性のあるハイブリッドな運用を実現するサービスです。']}},
  {id:'v142', term:'Total Cost of Ownership (TCO)', domain:'concepts', source:SOURCES.tco, q:{text:'クラウド移行を検討する際の「総所有コスト(Total Cost of Ownership, TCO)」の考え方として正しいものはどれですか？', choices:['ハードウェア費用だけでなく、運用・保守などのコストも含めて算出した総コストを比較すること','初期導入費用のみを比較対象とすること','無料利用枠の対象サービスの利用料金のみを比較すること','サポートプランの月額料金のみを比較すること'], correct:0, why:['正しい。AWS Well-Architected Frameworkでも、総所有コスト(TCO)は運用・管理コストなどを含めて算出すべきとされており、特にマネージドサービスを使う場合はその効果が大きいとされています。','誤り。初期導入費用だけでなく、運用・保守・管理などランニングコストも含めて比較する必要があります。','誤り。無料利用枠の範囲内かどうかはTCOの算出要素の一部に過ぎず、全体のコストを表すものではありません。','誤り。サポートプランの料金はコストの一部であり、TCO全体を表すものではありません。']}},
  {id:'v143', term:'AWS Firewall Manager', domain:'security', source:SOURCES.firewallManager, q:{text:'AWS Firewall Managerの役割として正しいものはどれですか？', choices:['DDoS攻撃の影響を受けた際に金銭的補償を提供するサービス','AWS WAF・AWS Shield Advanced・セキュリティグループ・AWS Network Firewall等のセキュリティルールを、複数のAWSアカウント・リソースに一元的に設定・適用するサービス','S3バケット内の機密データを検出するサービス','VPC内の通信ログを記録するサービス'], correct:1, why:['これはAWS Shield Advancedの補償(DDoS Cost Protection)に関する内容です。','正しい。AWS Firewall Managerは、AWS WAF・AWS Shield Advanced・セキュリティグループ・AWS Network Firewall・Route 53 Resolver DNS Firewallなどの保護設定を、複数のアカウントやリソースに一元的に設定・適用できるサービスです。','これはAmazon Macieの説明です。','これはAmazon VPC Flow Logsの説明です。']}},
  {id:'v144', term:'AWS CodeArtifact', domain:'tech', source:SOURCES.codeartifact, q:{text:'AWS CodeArtifactとは何ですか？', choices:['アプリケーションのソースコードをホストするバージョン管理サービス','アプリケーションのビルドとテストを実行するサービス','npm・Maven・pip等のパッケージマネージャーで使うソフトウェアパッケージを安全に保管・共有できるマネージド型のアーティファクトリポジトリサービス','コンテナイメージを保存するレジストリサービス'], correct:2, why:['これはAWS CodeCommit等のソースコードリポジトリサービスの説明です。','これはAWS CodeBuildの説明です。','正しい。AWS CodeArtifactは、npm・Maven・pip・NuGet等のパッケージマネージャーで使用するソフトウェアパッケージを安全に保管・共有できるマネージド型のアーティファクトリポジトリサービスです。','これはAmazon ECRの説明です。']}},
  {id:'v145', term:'AWS Cost Optimization Hub', domain:'billing', source:SOURCES.costOptimizationHub, q:{text:'AWS Cost Optimization Hubとは何ですか？', choices:['予算のしきい値を超えた場合にアラートを送信するサービス','サードパーティ製ソフトウェアの利用料金をAWSの利用料金と合わせて請求するサービス','複数のAWSアカウントの利用量を合算し、ボリュームディスカウントを受けやすくする請求の仕組み','AWS Compute Optimizer・Cost Explorerのライトサイジング推奨・Savings Plans/リザーブドインスタンスの購入推奨など、複数のコスト削減に関する推奨事項を組織内の複数アカウント・リージョンにわたって一元的に集約するサービス'], correct:3, why:['これはAWS Budgetsの説明です。','これはAWS Marketplaceの説明です。','これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。','正しい。AWS Cost Optimization Hubは、Compute Optimizerやコスト削減に関する複数の推奨事項の種類を、組織内の複数アカウント・リージョンにわたって一元的に集約する、より上位の集約レイヤーです。']}},
  {id:'v146', term:'AWS Wavelength', domain:'tech', source:SOURCES.wavelength, q:{text:'AWS Wavelengthとは何ですか？', choices:['通信事業者(キャリア)のネットワークエッジにAWSのコンピューティング・ストレージサービスを展開し、5G等のモバイルデバイスに対して超低レイテンシーを実現するインフラストラクチャ','オンプレミスのデータセンターにAWSのサービスを拡張するハイブリッドクラウドサービス','大都市圏の近接拠点にAWSのサブセットのサービスを展開する、リージョンを拡張した拠点','世界中のエッジロケーションでコンテンツをキャッシュし配信するCDNサービス'], correct:0, why:['正しい。AWS Wavelengthは、通信事業者(CSP)のネットワークのエッジにAWSのコンピューティング・ストレージサービスを展開し、5G等のモバイルデバイスやエンドユーザーに対して超低レイテンシーを実現するインフラストラクチャです。','これはAWS Outpostsの説明です。','これはAWS Local Zonesの説明です。','これはAmazon CloudFrontの説明です。']}},
  {id:'v147', term:'Amazon Lightsail', domain:'tech', source:SOURCES.lightsail, q:{text:'Amazon Lightsailとは何ですか？', choices:['大量データに対して複雑な分析クエリを高速に実行するデータウェアハウスサービス','仮想サーバー・ストレージ・ネットワークなどをあらかじめ組み合わせ、月額の定額料金で簡単にWebサイトやアプリケーションを立ち上げられる、EC2よりもシンプルな仮想プライベートサーバーサービス','複数のAWSアカウントを一括管理するサービス','コンテナイメージを保存するレジストリサービス'], correct:1, why:['これはAmazon Redshiftの説明です。','正しい。Amazon Lightsailは、仮想サーバー・ストレージ・ネットワークなどがあらかじめ組み合わされ、月額定額の分かりやすい料金体系でWebサイトやシンプルなアプリケーションを素早く立ち上げられる、EC2よりも簡易な仮想プライベートサーバー(VPS)サービスです。','これはAWS Organizationsの説明です。','これはAmazon ECRの説明です。']}},
  {id:'v148', term:'Amazon Verified Permissions', domain:'security', source:SOURCES.verifiedPermissions, q:{text:'Amazon Verified Permissionsとは何ですか？', choices:['アプリケーションのソースコードの脆弱性をスキャンするサービス','ネットワークトラフィックをルールベースでフィルタリングするファイアウォールサービス','Cedarポリシー言語を使い、「誰がどのリソースに対してどの操作を許可されるか」という認可(authorization)ロジックをアプリケーションのコードから切り離して一元的に管理・評価できるフルマネージドサービス','AWSアカウント全体のIAMポリシーの一覧を可視化するサービス'], correct:2, why:['これはAmazon Inspectorの説明です。','これはAWS Network FirewallやAWS WAFの説明です。','正しい。Amazon Verified Permissionsは、Cedarポリシー言語で記述した認可ロジックをアプリケーションのコードから切り離し、「誰がどのリソースに対してどの操作を許可されるか」を一元的に管理・評価できるフルマネージドサービスです。','これはAWS IAM Access Analyzer等の説明です。']}},
  {id:'v149', term:'Amazon EC2 Reserved Instance Marketplace', domain:'billing', source:SOURCES.riMarketplace, q:{text:'Amazon EC2 Reserved Instance Marketplaceとは何ですか？', choices:['リザーブドインスタンスを初めて購入する際に割引価格を提示してくれる仕組み','スポットインスタンスを入札形式で売買する市場','AWS Marketplaceで販売されているサードパーティ製ソフトウェアの売買市場','他の顧客が不要になったAmazon EC2のStandard Reserved Instanceを売却でき、購入者は残りの契約期間を市場価格で購入できる仕組み'], correct:3, why:['誤り。新規購入時の割引提示の仕組みではなく、既存のリザーブドインスタンスの売買の場です。','誤り。スポットインスタンスの入札とは異なる仕組みです。','誤り。AWS Marketplaceとは別の、EC2 Standard Reserved Instance専用の売買の場です。','正しい。Reserved Instance Marketplaceは、不要になったAmazon EC2のStandard Reserved Instanceを他の顧客に売却でき、購入者は残りの契約期間分を市場価格で購入できる仕組みです。']}},
  {id:'v150', term:'Amazon AppFlow', domain:'tech', source:SOURCES.appflow, q:{text:'Amazon AppFlowとは何ですか？', choices:['Salesforce・ServiceNow・SAP等のSaaSアプリケーションとAmazon S3・Redshift等のAWSサービスの間で、コードを書かずに安全かつスケーラブルにデータを転送できるフルマネージド型の統合サービス','オンプレミスのファイルサーバーとAmazon S3の間でファイルを同期するサービス','複数のAWSアカウントに安全にリソースを共有するサービス','アプリケーションのログを収集・分析するサービス'], correct:0, why:['正しい。Amazon AppFlowは、Salesforce・ServiceNow・SAP等のSaaSアプリケーションとAmazon S3・Redshift等のAWSサービスの間で、コード不要で安全かつスケーラブルにデータを転送できるフルマネージド型の統合サービスです。','これはAWS DataSyncの説明です。','これはAWS Resource Access Manager (RAM)の説明です。','これはAmazon CloudWatch Logs等のログ管理サービスの説明です。']}},
  {id:'v151', term:'AWS Certificate Manager (ACM)', domain:'security', source:SOURCES.acm, q:{text:'AWS Certificate Manager (ACM)とは何ですか？', choices:['AWSリソースへのアクセス権限を管理するサービス','Webサイトやロードバランサー等で使用するパブリックなSSL/TLS証明書を発行・管理し、Elastic Load BalancingやCloudFront等のAWS統合サービスに無料で自動的にデプロイ・更新できるサービス','データベースの認証情報を安全に保管し、自動的にローテーションするサービス','Webアプリケーションへの攻撃をルールベースでフィルタリングするサービス'], correct:1, why:['これはAWS IAMの説明です。','正しい。AWS Certificate Manager (ACM)は、Webサイトやロードバランサー等で使用するパブリックなSSL/TLS証明書を発行・管理するサービスで、Elastic Load BalancingやCloudFront等のAWS統合サービスに証明書を無料で自動的にデプロイ・更新できます。','これはAWS Secrets Managerの説明です。','これはAWS WAFの説明です。']}},
  {id:'v152', term:'Operational Excellence Pillar（運用上の優秀性の柱）', domain:'concepts', source:SOURCES.wafOps, q:{text:'AWS Well-Architected Frameworkの「運用上の優秀性の柱」が重視する観点として正しいものはどれですか？', choices:['リスク評価や緩和戦略を適用しながら、データ・システム・資産を保護すること','環境への影響（エネルギー消費等）を低減すること','システムを実行・監視し、ビジネス価値をサポートするプロセスや手順を継続的に改善すること','不要なコストを排除し、最もコスト効率の良い方法でビジネス価値を実現すること'], correct:2, why:['これはセキュリティの柱の説明です。','これは持続可能性の柱の説明です。','正しい。運用上の優秀性の柱は、システムを実行・監視し、ビジネス価値をサポートするプロセスや手順を継続的に改善することに焦点を当てます。','これはコスト最適化の柱の説明です。']}},
  {id:'v153', term:'AWS IoT Greengrass', domain:'tech', source:SOURCES.iotGreengrass, q:{text:'AWS IoT Greengrassとは何ですか？', choices:['クラウド上でIoTデバイスからのメッセージ(MQTT等)を安全に送受信・ルーティングするマネージド型メッセージブローカーサービス','オンプレミスのMongoDBワークロードをマネージド型データベースへ移行するサービス','コンテナイメージを安全に保存するレジストリサービス','IoTデバイス(エッジ)上でローカルにデータ処理・機械学習推論・メッセージのフィルタリングや集約を実行できるオープンソースのIoTエッジランタイムであり、ネットワーク接続が不安定・一時的に切断した場合でもローカルで動作を継続し、接続が回復した際にAWSクラウドと同期できる'], correct:3, why:['これはAWS IoT Coreの説明です。','これはAmazon DocumentDBの説明です。','これはAmazon ECRの説明です。','正しい。AWS IoT Greengrassは、IoTデバイス(エッジ)上でローカルにデータ処理・機械学習推論・メッセージのフィルタリングや集約を実行できるオープンソースのIoTエッジランタイムで、ネットワーク接続が不安定・一時的に切断しても動作を継続し、接続回復時にAWSクラウドと同期できます。']}},
  {id:'v154', term:'Amazon Bedrock', domain:'tech', source:SOURCES.bedrock, q:{text:'Amazon Bedrockとは何ですか？', choices:['Anthropic・Meta・AmazonなどのAIプロバイダーが提供する複数の基盤モデル(Foundation Model)に、単一のAPIから安全かつスケーラブルにアクセスし、生成AIアプリケーションを構築・拡張できるフルマネージドサービス','あらかじめ用意された需要予測に基づき、ITインフラの増減を自動化するサービス','オンプレミスのデータセンターとAWSを専用線で接続するサービス','コンテナイメージをスキャンして脆弱性を検出するサービス'], correct:0, why:['正しい。Amazon Bedrockは、Anthropic・Meta・AmazonなどのAIプロバイダーが提供する複数の基盤モデルに単一のAPIから安全かつスケーラブルにアクセスし、生成AIアプリケーションを構築・拡張できるフルマネージドサービスです。','これはAmazon EC2 Auto Scaling等の説明です。','これはAWS Direct Connectの説明です。','これはAmazon ECRの拡張スキャン機能(Amazon Inspector連携)の説明です。']}},
  {id:'v155', term:'AWS IAM Roles Anywhere', domain:'security', source:SOURCES.rolesAnywhere, q:{text:'AWS IAM Roles Anywhereとは何ですか？', choices:['IAMユーザーのパスワードに多要素認証(MFA)を強制するサービス','AWS外部で稼働するサーバーやコンテナなどのワークロードが、X.509証明書を使ってIAMロールを引き受け、一時的なセキュリティ認証情報を取得できるようにするサービス','複数のAWSアカウントに共通のセキュリティルールを一元的に適用するサービス','オンプレミスの認証局(CA)を構築・運用するサービス'], correct:1, why:['これはIAMのMFA設定の説明です。','正しい。AWS IAM Roles Anywhereは、サーバーやコンテナなどAWS外部で稼働するワークロードが、信頼されたCAが発行したX.509証明書を使ってIAMロールを引き受け、長期的なアクセスキーを管理せずに一時的なセキュリティ認証情報を取得できるようにするサービスです。','これはAWS Firewall Managerの説明です。','これはAWS Private CAの説明です（Roles Anywhereは既存のCAと連携する側です）。']}},
  {id:'v156', term:'Retain（リテイン）', domain:'concepts', source:SOURCES.migrationStrategies, q:{text:'移行戦略の一つである「リテイン(Retain)」の説明として正しいものはどれですか？', choices:['既存のアプリケーションを変更せずにそのままクラウドへ移行すること','アプリケーションを別のSaaS製品に置き換えること','現時点では移行せず、コンプライアンス要件や依存関係、投資回収の観点などから、アプリケーションを既存の環境にそのまま残しておくこと','不要なアプリケーションを完全に廃止・停止すること'], correct:2, why:['これは「リホスト(Rehost)」の説明です。','これは「リパーチェス(Repurchase)」の説明です。','正しい。「リテイン(Retain)」は、コンプライアンス要件・高リスク・依存関係・投資回収などの理由から、現時点では移行せずにアプリケーションを既存の環境にそのまま残しておく移行戦略です。','これは「リタイア(Retire)」の説明です。']}},
  {id:'v157', term:'AWS Data Exports', domain:'billing', source:SOURCES.dataExports, q:{text:'AWS Data Exportsとは何ですか？', choices:['予算のしきい値を超えた場合にアラートを送信するサービス','複数のAWSアカウントの請求を一つにまとめ、ボリュームディスカウントの対象にする仕組み','異常なコストの急増を機械学習で検知するサービス','コスト・使用量データや二酸化炭素排出量データを、SQLで列・行を選んでカスタマイズしながら、業界標準のFOCUS形式などでAmazon S3へ定期的にエクスポートできる課金管理サービス'], correct:3, why:['これはAWS Budgetsの説明です。','これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。','これはAWS Cost Anomaly Detectionの説明です。','正しい。AWS Data Exportsは、コスト・使用量データや二酸化炭素排出量データを、SQLによる列・行の選択でカスタマイズしながら、業界標準のFOCUS形式などの形式でAmazon S3へ定期的にエクスポートできる課金管理サービスです。']}},
  {id:'v158', term:'Amazon Personalize', domain:'tech', source:SOURCES.personalize, q:{text:'Amazon Personalizeとは何ですか？', choices:['機械学習の専門知識がなくても、ユーザーの行動データ（商品クリック・購買履歴等）に基づいて、ECサイトや動画配信アプリに個別のレコメンデーション（おすすめ商品等）を組み込めるフルマネージド型の機械学習サービス','テキストから感情分析やエンティティ抽出を行うサービス','時系列データから将来の需要を予測するサービス','構造化されていない文書からテキストやテーブルを抽出するサービス'], correct:0, why:['正しい。Amazon Personalizeは、機械学習の専門知識がなくても、ユーザーの行動データに基づいて商品・コンテンツの個別レコメンデーションや類似ユーザーのセグメント化をアプリに組み込めるフルマネージド型の機械学習サービスです。','これはAmazon Comprehendの説明です。','これはAmazon Forecastの説明です。','これはAmazon Textractの説明です。']}},
  {id:'v159', term:'AWS Organizations', domain:'security', source:SOURCES.organizations, q:{text:'AWS Organizationsとは何ですか？', choices:['単一のAWSアカウント内でIAMユーザーのアクセス権限を管理するサービス','複数のAWSアカウントを組織単位(OU)としてグループ化し、一括請求やサービスコントロールポリシー(SCP)などのガバナンスルールを階層的に適用できる、複数アカウントの一元管理サービス','AWSリソースの利用コストを可視化するダッシュボードサービス','オンプレミスのActive Directoryをクラウド上で運用するサービス'], correct:1, why:['これはAWS IAMの説明です。','正しい。AWS Organizationsは、複数のAWSアカウントを組織単位(OU)としてグループ化し、一括請求(Consolidated Billing)やSCPによるガバナンスルールを階層的に適用できる、複数アカウントの一元管理サービスです。','これはAWS Cost Explorerの説明です。','これはAWS Directory Serviceの説明です。']}},
  {id:'v160', term:'AWS Cost Explorer', domain:'billing', source:SOURCES.costExplorer, q:{text:'AWS Cost Explorerとは何ですか？', choices:['複数のAWSアカウントの請求を一つにまとめる機能','予算のしきい値を超えた場合にアラートを送信するサービス','過去のコスト・使用量の傾向を可視化し、カスタムレポートの作成や将来のコスト予測、リザーブドインスタンス/Savings Plansの購入推奨などの分析を行えるサービス','機械学習によって異常なコストの急増を自動的に検知するサービス'], correct:2, why:['これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。','これはAWS Budgetsの説明です。','正しい。AWS Cost Explorerは、過去のコスト・使用量の傾向をグラフで可視化し、カスタムレポートの作成、将来のコスト予測、リザーブドインスタンス/Savings Plansの購入推奨など、コスト分析のための機能を提供するサービスです。','これはAWS Cost Anomaly Detectionの説明です。']}},
  {id:'v161', term:'Refactor / Re-architect（リファクター）', domain:'concepts', source:SOURCES.migrationStrategies, q:{text:'移行戦略の一つである「リファクター(Refactor / Re-architect)」の説明として正しいものはどれですか？', choices:['既存のアプリケーションをほぼそのままEC2上に移行すること（リフト&シフト）','アプリケーションのコードをあまり変更せずに、一部の基盤をRDS等のマネージドサービスに置き換えること','アプリケーションを別のSaaS製品に置き換えること','既存の設計や実装から離れ、マイクロサービス化やサーバーレス化など、クラウドネイティブな機能を活用するために大幅にアプリケーションを再設計すること'], correct:3, why:['これは「リホスト(Rehost)」の説明です。','これは「リプラットフォーム(Replatform)」の説明です。','これは「リパーチェス(Repurchase)」の説明です。','正しい。「リファクター(Refactor / Re-architect)」は、既存の設計・実装から離れ、マイクロサービス化やサーバーレス化などクラウドネイティブな機能を活用するためにアプリケーションを大幅に再設計する移行戦略です。通常、最も労力がかかりますが、クラウドのメリットを最大限に活かせます。']}},
  {id:'v162', term:'Durability', domain:'concepts', source:SOURCES.s3, q:{text:'クラウドコンピューティングにおける「耐久性(Durability)」とは何を指しますか？', choices:['データが長期間にわたって失われたり破損したりしない度合いを表す指標。例えばAmazon S3標準ストレージクラスは99.999999999%(11個の9)の耐久性を実現している','システムやサービスが必要なときに利用可能である度合いを表す指標','需要の変化に応じてリソースを自動的に増減できる能力','使用した分だけ料金を支払う課金モデル'], correct:0, why:['正しい。耐久性(Durability)は、データが長期間にわたって失われたり破損したりしない度合いを表す指標です。Amazon S3標準ストレージクラスは、複数のアベイラビリティーゾーンにデータを冗長的に保存することで99.999999999%(11個の9)の耐久性を実現しています。','誤り。これは可用性(Availability)の説明です。耐久性はデータの損失・破損のしにくさを表すのに対し、可用性はシステムが利用可能である時間の割合を表します。','誤り。これは弾力性(Elasticity)の説明です。','誤り。これは従量課金制(Pay-as-you-go)の説明です。']}},
  {id:'v163', term:'AWS Well-Architected Framework', domain:'concepts', source:SOURCES.waf, q:{text:'AWS Well-Architected Frameworkとは何ですか？', choices:['AWS環境内の脆弱性を自動的にスキャンし修正するセキュリティサービス','クラウド上でシステムを設計・運用する際のベストプラクティスを、6つの柱(運用上の優秀性・セキュリティ・信頼性・パフォーマンス効率・コスト最適化・持続可能性)に整理したフレームワーク。AWS Well-Architected Toolを使えば、設計をこのベストプラクティスと比較してレビューできる','複数のAWSアカウントの請求を一括請求でまとめるためのフレームワーク','オンプレミスからクラウドへの移行戦略を7つに分類したガイド'], correct:1, why:['誤り。これはAmazon Inspector等の脆弱性スキャンサービスの説明です。','正しい。AWS Well-Architected Frameworkは、クラウド上でシステムを設計・運用する際のベストプラクティスを6つの柱に整理したフレームワークであり、AWS Well-Architected Toolを使ってワークロードの設計をこれらのベストプラクティスと比較してレビューできます。','誤り。これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。','誤り。これは移行戦略(7つのR)の説明です。']}},
  {id:'v164', term:'AWS Nitro System', domain:'security', source:SOURCES.nitroSystem, q:{text:'AWS Nitro Systemとは何ですか？', choices:['EC2インスタンス間の通信を暗号化するVPN機能','AWS Key Management Serviceが管理する暗号鍵を保護するための専用ハードウェアモジュール','仮想化に必要なCPU・メモリ・ストレージ・ネットワークの処理を専用のハードウェア・ソフトウェアに分離することで、ほぼ全てのサーバーリソースをインスタンスに割り当てられるようにし、さらにAmazon社員を含む運用者によるインスタンスへのアクセスを排除するなどのセキュリティ上の分離を実現する、最新世代EC2インスタンスの基盤技術','オンプレミスとAWS間を専用線で接続するネットワークサービス'], correct:2, why:['誤り。これはAWS Site-to-Site VPN等の説明です。','誤り。これはAWS CloudHSMの説明です。','正しい。AWS Nitro Systemは、仮想化に必要なCPU・メモリ・ストレージ・ネットワークの処理を専用のハードウェアとソフトウェアに分離することで、ほぼ全てのサーバーリソースをインスタンスに割り当てられるようにし、またNitro Hypervisor/Nitro Security Chipにより運用者を含むいかなる者もインスタンスへアクセスできないように分離する、最新世代EC2インスタンスの基盤技術です。','誤り。これはAWS Direct Connectの説明です。']}},
  {id:'v165', term:'AWS Amplify', domain:'tech', source:SOURCES.amplify, q:{text:'AWS Amplifyとは何ですか？', choices:['EC2インスタンスをコードで定義してプロビジョニングするIaCサービス','Dockerコンテナをオーケストレーションするサービス','仮想デスクトップ環境をクラウド上で提供するサービス','Git連携によるCI/CDとホスティングを提供し、React・Next.js等のフロントエンドフレームワークで構築したフルスタックのWebアプリケーションをAWSのグローバルCDN上に簡単にデプロイできるサービス'], correct:3, why:['誤り。これはAWS CloudFormationの説明です。','誤り。これはAmazon ECS等の説明です。','誤り。これはAmazon WorkSpacesの説明です。','正しい。AWS Amplifyは、Gitリポジトリと連携した継続的デプロイ(CI/CD)とホスティング機能を提供し、React・Next.js・Vue.js等のフレームワークで構築したフルスタックのサーバーレスWebアプリケーションをAWSのグローバルコンテンツデリバリーネットワーク(CDN)上に簡単にデプロイできるサービスです。']}},
  {id:'v166', term:'Amazon MemoryDB', domain:'tech', source:SOURCES.memorydb, q:{text:'Amazon MemoryDBとは何ですか？', choices:['Redis OSS・Valkeyと互換性があり、マイクロ秒単位の読み取り・1桁ミリ秒の書き込みレイテンシーを実現しつつ、複数のアベイラビリティーゾーンにまたがるトランザクションログでデータを永続的に保存することで、キャッシュ専用ではなく高性能なプライマリデータベースとしても利用できるインメモリデータベースサービス','頻繁にアクセスされるデータを一時的にキャッシュし、データベースの読み取り負荷を下げるためのインメモリキャッシュサービスで、再起動時にデータが失われる可能性がある','大量のタイムスタンプ付きデータ(時系列データ)の保存・分析に特化したサーバーレスデータベースサービス','キーバリュー型・ドキュメント型のデータを格納するフルマネージドNoSQLデータベースサービス'], correct:0, why:['正しい。Amazon MemoryDBはRedis OSS・Valkeyと互換性のあるインメモリデータベースで、マルチAZのトランザクションログによりデータを永続的に保存するため、キャッシュとしてだけでなくマイクロサービスのプライマリデータベースとしても利用できます。','誤り。これはAmazon ElastiCacheの説明です。ElastiCacheは主にキャッシュ用途で、データの永続性を主目的とはしていません。','誤り。これはAmazon Timestreamの説明です。','誤り。これはAmazon DynamoDBの説明です。']}},
  {id:'v167', term:'AWS Clean Rooms', domain:'security', source:SOURCES.cleanrooms, q:{text:'AWS Clean Roomsとは何ですか？', choices:['自分が所有するAWSリソースを、Organizations内の他アカウントと安全に共有するサービス','複数のAWSアカウントを一元的に管理し、SCPでガバナンスを適用するサービス','S3バケット内の個人情報等の機密データを機械学習で自動的に検出・分類するサービス','複数の企業が、それぞれのデータセットの内容を互いに開示せずに、データを結合した分析・コラボレーションを行えるセキュアなコラボレーションワークスペースを提供するサービス'], correct:3, why:['誤り。これはAWS Resource Access Manager (RAM)の説明です。','誤り。これはAWS Organizationsの説明です。','誤り。これはAmazon Macieの説明です。','正しい。AWS Clean Roomsは、提携企業同士がそれぞれのデータセットの内容を互いに開示することなく、分析ルールや暗号化技術などのプライバシー強化機能を使ってデータを結合・分析できるセキュアなコラボレーションワークスペースを提供するサービスです。']}},
  {id:'v168', term:'Warm Standby（ウォームスタンバイ）', domain:'concepts', source:SOURCES.drStrategies, q:{text:'ディザスタリカバリ(DR)戦略の一つである「Warm Standby（ウォームスタンバイ）」の説明として正しいものはどれですか？', choices:['バックアップデータのみを別リージョンに保存し、障害時はそこからインフラ全体をゼロから構築する、最もコストが低く復旧に時間がかかる戦略','データベースなど中核となる要素のみを別リージョンで常時起動させておき、その他の要素は障害発生時に起動する戦略','本番環境の縮小版（スケールダウンされた完全に機能する環境）を別リージョンで常時稼働させ、障害発生時にはそのキャパシティを本番相当まで迅速にスケールアップして切り替える戦略','複数リージョンで常に本番相当のキャパシティを稼働させ、通常時から全リージョンでトラフィックを処理する、最もコストが高く復旧がほぼ即時の戦略'], correct:2, why:['これは「Backup and Restore」の説明です。','これは「Pilot Light」の説明です。','正しい。Warm Standbyは、本番環境の縮小版（スケールダウンされているが完全に機能する環境）を別リージョンで常時稼働させておき、障害発生時にはそのキャパシティを本番相当まで迅速にスケールアップして切り替える戦略で、Pilot Lightより高速に復旧できますが、コストも高くなります。','これは「Multi-Site Active-Active」の説明です。']}},
  {id:'v169', term:'Convertible Reserved Instances', domain:'billing', source:SOURCES.ec2Ri, q:{text:'Amazon EC2の「Convertible Reserved Instances」の特徴として正しいものはどれですか？', choices:['AWSの空きキャパシティを割安に利用できるが、AWSの都合で中断される可能性がある購入オプション','需要に応じてコンピューティングリソースを自動的に増減させる購入オプション','初期費用を一切支払わず、常にオンデマンド料金と同額を支払う購入オプション','契約期間中に同等以上の価値を持つ別の構成（インスタンスファミリー・OS・テナンシー等）へ交換できる柔軟性を持つが、Standard Reserved Instancesより割引率がやや低く、Reserved Instance Marketplaceでの売却はできない購入オプション'], correct:3, why:['これはスポットインスタンスの説明です。','これはEC2 Auto Scalingの説明です。','誤り。Reserved Instanceは何らかの形でコミットメントに応じた割引を受けるための購入オプションであり、オンデマンド料金と同額になるわけではありません。','正しい。Convertible Reserved Instancesは、契約期間中に同等以上の価値を持つ別の構成（インスタンスファミリー・OS・テナンシー等）へ交換できる柔軟性を持ちますが、その柔軟性の代わりにStandard Reserved Instancesより割引率がやや低く、また契約を解消したい場合でもReserved Instance Marketplaceでの売却はできません（売却できるのはStandard RIのみです）。']}},
  {id:'v170', term:'Amazon Q Developer', domain:'tech', source:SOURCES.qDeveloper, q:{text:'Amazon Q Developerとは何ですか？', choices:['AWSのアーキテクチャやリソース、ベストプラクティスについて会話形式で質問でき、IDE内でのコード提案・説明・セキュリティスキャンなど開発作業も支援する生成AIアシスタント','社内文書やナレッジベースの内容をもとに、ビジネス上の質問に自然言語で回答するエンタープライズ向けの生成AIアシスタント','アプリケーションのコードを自動的にレビューし、パフォーマンス改善のための推奨事項を提示するサービス','AWSの利用状況を分析し、コスト・パフォーマンス・セキュリティ等の観点でベストプラクティスに基づく推奨事項を提示するサービス'], correct:0, why:['正しい。Amazon Q Developerは、AWSのアーキテクチャやリソース、ベストプラクティスについて会話形式で質問でき、IDE上でのコード提案・説明・セキュリティスキャンなど開発作業も支援する生成AIアシスタントです。','これはAmazon Q Business（社内文書等を活用するエンタープライズ向けアシスタント）の説明です。','これはAmazon CodeGuruの説明です。','これはAWS Trusted Advisorの説明です。']}},
  {id:'v171', term:'AWS AppFabric', domain:'security', source:SOURCES.appfabric, q:{text:'AWS AppFabricとは何ですか？', choices:['AWSアカウント内の各サービスで発生したセキュリティ上の検出結果(Findings)を一つの画面に集約し、優先順位付けするサービス','複数のSaaS(Software as a Service)アプリケーションを接続し、各アプリケーションの監査ログを標準化されたスキーマ(OCSF)に正規化して集約することで、セキュリティの可視化や管理を効率化するサービス','AWSアカウント内のAPIコールの履歴を記録し、監査証跡として保存するサービス','IAMのリソースベースポリシーを分析し、意図しない外部アクセス権限を検出するサービス'], correct:1, why:['これはAWS Security Hubの説明です。','正しい。AWS AppFabricは、複数のSaaSアプリケーションをノーコードで接続し、各アプリケーションの監査ログを共通のスキーマ(OCSF: Open Cybersecurity Schema Framework)に正規化して集約することで、セキュリティの可視化・管理を効率化するサービスです。','これはAWS CloudTrailの説明です。','これはAWS IAM Access Analyzerの説明です。']}},
  {id:'v172', term:'Regional RI / Zonal RI（リザーブドインスタンスのスコープ）', domain:'billing', source:SOURCES.ec2Ri, q:{text:'Amazon EC2のリザーブドインスタンスにおける「リージョナル」と「ゾーナル」のスコープの違いとして正しいものはどれですか？', choices:['両方とも特定のアベイラビリティーゾーンでの容量確保を保証する','リージョナルは特定のアベイラビリティーゾーンでの容量確保を保証するが、ゾーナルは保証しない','リージョナルはリージョン内のどのアベイラビリティーゾーンで起動しても割引が適用されるが容量確保は保証されず、ゾーナルは指定したアベイラビリティーゾーンでの容量確保が保証されるが割引の適用はそのAZ内に限られる','リージョナルとゾーナルでは、同じ条件であっても割引率が大きく異なる'], correct:2, why:['誤り。容量確保が保証されるのはゾーナルスコープのみです。','誤り。説明が逆です。容量確保を保証するのはゾーナルスコープです。','正しい。リージョナルスコープはリージョン内のどのAZで起動しても割引が適用されますが容量確保は保証されません。ゾーナルスコープは指定したAZでの容量確保が保証されますが、割引の適用はそのAZ内の利用に限られます。','誤り。AWSは、スコープの違いによって割引率に大きな差は設けていません。']}},
  {id:'v173', term:'RTO (Recovery Time Objective)', domain:'concepts', source:SOURCES.rtorpo, q:{text:'ディザスタリカバリ(DR)における「RTO(目標復旧時間)」とは何ですか？', choices:['障害発生時に許容できる最大のデータ損失量を、あらかじめビジネス側が定義しておく目標値','システムが実際に正常稼働している時間の割合を表す指標','サービス提供者と利用者の間で合意されたサービス品質の水準を定めた契約','障害発生からサービスが復旧するまでに許容できる最大の時間を、あらかじめビジネス側が定義しておく目標値'], correct:3, why:['これはRPO(目標復旧時点)の説明です。','これは可用性(Availability)の説明です。','これはSLA(サービスレベルアグリーメント)の説明です。','正しい。RTO(Recovery Time Objective)は、障害発生からサービスが復旧するまでに許容できる最大の時間を、あらかじめビジネス側が目標値として定義しておく指標です。']}},
  {id:'v174', term:'Retire（リタイア）', domain:'concepts', source:SOURCES.migrationStrategies, q:{text:'移行戦略の一つである「リタイア(Retire)」の説明として正しいものはどれですか？', choices:['利用状況を調査し、もはや必要とされていないアプリケーションを移行対象から外し、廃止すること','アプリケーションをそのまま変更せずにクラウドへ移行すること','アプリケーションのコア部分を書き換え、クラウドネイティブな設計に変更すること','同様の機能を持つSaaS製品に切り替えること'], correct:0, why:['正しい。リタイア(Retire)は、利用状況の調査によってもはや必要とされていないと判断したアプリケーションを移行対象から外し、廃止する移行戦略です。コスト削減やセキュリティ対象範囲の縮小につながります。','これは「リホスト(Rehost)」の説明です。','これは「リファクター(Refactor)」の説明です。','これは「リパーチェス(Repurchase)」の説明です。']}},
  {id:'v175', term:'AWS Signer', domain:'security', source:SOURCES.signer, q:{text:'AWS Signerとは何ですか？', choices:['S3バケットへの署名付きURLを生成し、一時的なアクセス権を付与するサービス','Lambda関数のデプロイパッケージやIoTデバイス向けのコードに対してデジタル署名を行い、コードの改ざんがないことと発行元の信頼性を検証できるようにするフルマネージドのコード署名サービス','SSL/TLS証明書を発行・管理し、ロードバランサーやCloudFrontに適用するサービス','コンテナイメージの脆弱性をスキャンするセキュリティサービス'], correct:1, why:['これはAmazon S3の署名付きURL機能の説明であり、AWS Signerとは異なります。','正しい。AWS Signerは、LambdaのデプロイパッケージやAmazon FreeRTOS/AWS IoTデバイス向けのコードなどにデジタル署名を行い、コードの完全性と発行元の信頼性を検証できるようにするフルマネージドのコード署名サービスです。','これはAWS Certificate Manager (ACM)の説明です。','これはAmazon Inspectorの説明です。']}},
  {id:'v176', term:'Amazon DataZone', domain:'tech', source:SOURCES.dataZone, q:{text:'Amazon DataZoneとは何ですか？', choices:['ETL処理を行い、データカタログを自動生成するサーバーレスのデータ統合サービス','S3に保存されたデータに対してサーバーレスでSQLクエリを実行するサービス','AWSやオンプレミス、サードパーティに分散したデータをカタログ化・検索・ガバナンスし、組織内でセルフサービスに発見・共有・分析できるようにするデータ管理サービス','リレーショナルデータベースのデータをデータウェアハウスに同期するサービス'], correct:2, why:['これはAWS Glueの説明です。','これはAmazon Athenaの説明です。','正しい。Amazon DataZoneは、AWS・オンプレミス・サードパーティに分散したデータをカタログ化し、きめ細かなアクセス制御によるガバナンスを維持しながら、組織内のユーザーがセルフサービスでデータを発見・共有・分析できるようにするデータ管理サービスです。','これはAWS Database Migration Service (DMS)などの説明に近く、DataZoneの役割とは異なります。']}},
  {id:'v177', term:'AWS re:Post', domain:'billing', source:SOURCES.repost, q:{text:'AWS re:Postとは何ですか？', choices:['AWSサポートプランの一つで、追加費用を払うことで24時間365日有人サポートを受けられるプラン','AWSの利用料金を部門やプロジェクト単位に割り振るためのコスト管理サービス','AWSのコンプライアンスレポートをオンデマンドでダウンロードできるセルフサービスポータル','AWSアカウントを持つ誰でも無料で利用できる、コミュニティ主導の質問・回答(Q&A)サービス。コミュニティの専門家に加えAWSの従業員も回答に参加し、旧AWS Forumsの後継として提供されている'], correct:3, why:['これはAWSサポートプラン(Business Support+やEnterprise Support等)の説明であり、re:Postとは別物です。','これはAWS Cost Categoriesやコスト配分タグ等の説明です。','これはAWS Artifactの説明です。','正しい。AWS re:Postは、AWSアカウントを持つ誰でも無料で利用できるコミュニティ主導のQ&Aサービスで、旧AWS Forumsを置き換えるものです。コミュニティの専門家やAWSの従業員が回答に参加します。']}},
  {id:'v178', term:'Amazon CodeGuru Profiler', domain:'tech', source:SOURCES.codeguru, q:{text:'Amazon CodeGuru Profilerとは何ですか？', choices:['アプリケーションの実行時パフォーマンスデータを収集し、機械学習によりCPU使用率が高いコード行を特定して、効率改善の推奨事項を提示するサービス','アプリケーションのソースコードを静的に解析し、セキュリティ上の脆弱性やコード品質の問題を検出するサービス','AWSリソースの利用状況を分析し、インスタンスタイプのライトサイジング推奨を提示するサービス','アプリケーションの分散トレーシングを行い、マイクロサービス間のリクエストの流れを可視化するサービス'], correct:0, why:['正しい。Amazon CodeGuru Profilerは、稼働中のアプリケーションから実行時パフォーマンスデータを収集し、機械学習アルゴリズムによってCPU使用率が高い（最もコストのかかる）コード行を特定し、効率改善の推奨事項を提示するサービスです。','これはAmazon CodeGuru Reviewerの説明です。','これはAWS Compute Optimizerの説明です。','これはAWS X-Rayの説明です。']}},
  {id:'v179', term:'AWS Resource Groups', domain:'tech', source:SOURCES.resourceGroups, q:{text:'AWS Resource Groupsとは何ですか？', choices:['複数のAWSアカウントの請求を一つにまとめて管理するサービス','タグまたは単一のCloudFormationスタックを基準に複数のAWSリソースをグループ化し、一つの画面から一括で表示・操作できるようにするサービス','組織が承認したITサービスのカタログを作成し、エンドユーザーがセルフサービスで利用できるようにするサービス','複数アカウント・リージョンにガードレールを適用したランディングゾーンを自動構築するサービス'], correct:1, why:['これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。','正しい。AWS Resource Groupsは、タグに基づくクエリまたは単一のCloudFormationスタックに基づくクエリでAWSリソースをグループ化し、同じリージョン内の複数のリソースを一つの画面から一括で表示・操作できるようにするサービスです。','これはAWS Service Catalogの説明です。','これはAWS Control Towerの説明です。']}},
  {id:'v180', term:'AWS License Manager', domain:'security', source:SOURCES.licenseManager, q:{text:'AWS License Managerとは何ですか？', choices:['SSL/TLS証明書を発行・管理するサービス','オンプレミスやAWS上で使用しているソフトウェアライセンス(BYOL)の使用状況を一元管理し、契約条件に基づくルールを設定して利用状況を追跡できるようにするサービス','IAMユーザー・ロールのアクセス権限を分析し、過剰な権限を検出するサービス','ソフトウェアの脆弱性をスキャンするサービス'], correct:2, why:['これはAWS Certificate Manager (ACM)の説明です。','これはAWS IAM Access Analyzerの説明です。','正しい。AWS License Managerは、オンプレミスやAWS上で使用しているソフトウェアライセンス(BYOL: Bring Your Own License)の使用状況を一元管理し、契約条件に基づくルールを設定して利用状況を追跡できるようにするサービスです。','これはAmazon Inspectorの説明です。']}},
  {id:'v181', term:'AWS Systems Manager パラメータストア', domain:'security', source:SOURCES.parameterStore, q:{text:'AWS Systems Manager パラメータストアの「SecureString」型パラメータの特徴として正しいものはどれですか？', choices:['値が自動的に定期ローテーションされる','値がAWS KMSを使って暗号化され、保存・取得される','パラメータストアには値のサイズ上限が存在しない','標準(Standard)ティアでも無制限に高頻度なAPIコールが可能になる'], correct:1, why:['誤り。SecureStringパラメータ自体に自動ローテーション機能はありません（定期ローテーションが必要な場合はAWS Secrets Managerの利用が推奨されます）。','正しい。パラメータストアの「SecureString」型パラメータは、値がAWS KMSのキーを使って暗号化された状態で保存され、取得時に復号されます。','誤り。標準パラメータは4KBまでなどのサイズ上限があります（より大きな値にはアドバンストパラメータが必要です）。','誤り。標準ティアにはAPIコール数やスループットに制限があり、高頻度なアクセスにはアドバンストティアが必要です。']}},
  {id:'v182', term:'Amazon Data Firehose', domain:'tech', source:SOURCES.firehose, q:{text:'Amazon Data Firehoseとは何ですか？', choices:['ストリーミングデータを受け取り、シャード(容量単位)の管理や配信先アプリケーションの開発を必要とせず、Amazon S3・Redshift・OpenSearch Service等の送信先へ自動的かつほぼリアルタイムに配信できるフルマネージドサービス','ストリーミングデータを取り込み、開発者が自らシャード数を管理しながらカスタムアプリケーションでリアルタイムに処理するサービス','メッセージをキューに格納し、送信側と受信側のアプリケーションを疎結合にするサービス','さまざまなデータソースからのデータを抽出・変換・ロード(ETL)するサーバーレスなデータ統合サービス'], correct:0, why:['正しい。Amazon Data Firehoseは、ストリーミングデータをシャード管理不要でS3・Redshift・OpenSearch Service・Splunk等の送信先へ自動的に配信できるフルマネージドサービスです。','これはAmazon Kinesis Data Streamsの説明です。Kinesis Data Streamsではシャードの管理が必要ですが、Data Firehoseでは不要です。','これはAmazon SQSの説明です。','これはAWS Glueの説明です。']}},
  {id:'v183', term:'AWS Security Incident Response', domain:'security', source:SOURCES.securityIR, q:{text:'AWS Security Incident Responseとは何ですか？', choices:['AWSアカウント内のセキュリティ検出結果(Findings)を一つの画面に集約し、優先順位付けするサービス','AWSのセキュリティ専門家(インシデント対応チーム)による24時間365日の支援を受けながら、実際に発生したセキュリティインシデントの準備・検知・分析・封じ込め・復旧を進められるようにするサービス','機械学習を使ってAWS環境内の不審なAPIコールやネットワーク挙動を継続的に検知するサービス','複数のAWSアカウントのセキュリティ設定を一元的に評価し、自動的に修復するサービス'], correct:1, why:['これはAWS Security Hubの説明です。','正しい。AWS Security Incident Responseは、AWSのセキュリティ専門家による人的支援を受けながら、実際のセキュリティインシデントの対応(準備・検知・分析・封じ込め・復旧)を進められるようにするサービスです。','これはAmazon GuardDutyの説明です。','これはAWS Firewall Managerの説明です。']}},
  {id:'v184', term:'AWS Compute Optimizer', domain:'billing', source:SOURCES.computeOptimizer, q:{text:'AWS Compute Optimizerとは何ですか？', choices:['不要になったリザーブドインスタンスを他の顧客に売却できるようにする仕組み','組織内の複数アカウントにまたがるコスト削減の推奨事項を一箇所に集約する機能','EC2インスタンスやLambda関数などのCloudWatchメトリクス(CPU・メモリ使用率等)を機械学習で分析し、コストとパフォーマンスの両面から見て最適なリソース構成への変更を追加費用なしで推奨するサービス','設定した予算のしきい値を超えた場合にアラートを送信するサービス'], correct:2, why:['これはAmazon EC2 Reserved Instance Marketplaceの説明です。','これはAWS Cost Optimization Hubの説明です。','正しい。AWS Compute Optimizerは、使用率データを機械学習で分析し、コストとパフォーマンスの両面から最適なリソース構成を無料で推奨するサービスです。','これはAWS Budgetsの説明です。']}},
  {id:'v185', term:'Amazon Managed Grafana', domain:'tech', source:SOURCES.grafana, q:{text:'Amazon Managed Grafanaとは何ですか？', choices:['ログの収集・保存・全文検索に特化したマネージド型のElasticsearch互換サービス','リソースのメトリクスを収集し、しきい値を超えた場合にアラームを発報するモニタリングサービス','分散アプリケーションのリクエストをエンドツーエンドでトレースし、ボトルネックを可視化するサービス','CloudWatch・OpenSearch Service・X-Ray・Amazon Timestream・Amazon Managed Service for Prometheusなど複数のデータソースを横断して運用メトリクス・ログ・トレースを可視化するダッシュボードを構築できる、オープンソースのGrafanaをベースにしたフルマネージドサービス'], correct:3, why:['これはAmazon OpenSearch Serviceの説明です。','これはAmazon CloudWatchの説明です。','これはAWS X-Rayの説明です。','正しい。Amazon Managed Grafanaは、複数のデータソースを横断して運用メトリクス・ログ・トレースを可視化できる、オープンソースのGrafanaをベースにしたフルマネージドサービスです。']}},
  {id:'v186', term:'AWS IoT Device Defender', domain:'security', source:SOURCES.iotDeviceDefender, q:{text:'AWS IoT Device Defenderとは何ですか？', choices:['IoTデバイスの構成をセキュリティのベストプラクティスに照らして監査し、異常な通信などの不審な挙動を検知するセキュリティ・モニタリングサービス','AWS環境全体のAPIコールやネットワークトラフィックを機械学習で分析し、脅威を検知するサービス','Amazon S3に保存された機密データを機械学習で自動的に検出・分類するサービス','EC2インスタンスやコンテナイメージの既知の脆弱性を自動的にスキャンするサービス'], correct:0, why:['正しい。AWS IoT Device Defenderは、IoTデバイスの構成をセキュリティのベストプラクティスに照らして監査(Audit)し、デバイスの異常な挙動を検知(Detect)するセキュリティ・モニタリングサービスです。','これはAmazon GuardDutyの説明です。GuardDutyはIoTデバイスに特化したサービスではありません。','これはAmazon Macieの説明です。','これはAmazon Inspectorの説明です。']}},
  {id:'v187', term:'Amazon Managed Service for Prometheus', domain:'tech', source:SOURCES.prometheus, q:{text:'Amazon Managed Service for Prometheusとは何ですか？', choices:['ログの収集・保存・全文検索に特化したマネージド型のサービス','オープンソースのPrometheusと互換性のあるクエリ言語(PromQL)やデータモデルを使って、コンテナ環境のメトリクスを収集・保存・クエリできるサーバーレスのモニタリングサービス','収集したメトリクス・ログ・トレースを一つのダッシュボードで可視化するサービス','分散アプリケーションのリクエストをエンドツーエンドでトレースするサービス'], correct:1, why:['これはAmazon OpenSearch Serviceの説明です。','正しい。Amazon Managed Service for Prometheusは、オープンソースのPrometheusと同じデータモデル・PromQLクエリ言語を使い、コンテナ環境のメトリクスをサーバーレスで収集・保存・クエリできるモニタリングサービスです。','これはAmazon Managed Grafanaの説明です。Grafanaは可視化(ダッシュボード)を担い、メトリクスの収集・保存自体はPrometheus等が担います。','これはAWS X-Rayの説明です。']}},
  {id:'v188', term:'パブリッククラウド / プライベートクラウド (デプロイモデル)', domain:'concepts', source:SOURCES.hybridCloud, q:{text:'クラウドの「デプロイモデル」のうち、「パブリッククラウド」の説明として正しいものはどれですか？', choices:['単一の組織専用に構築・運用され、他の組織とは共有されないコンピューティング環境','オンプレミス環境とクラウド環境を接続し、両方を組み合わせて利用する環境','AWSなどのクラウドプロバイダーが所有・運用し、インターネット経由で複数の組織・顧客が共有して利用できるコンピューティング環境','複数の異なるクラウドプロバイダーのサービスを組み合わせて利用する環境'], correct:2, why:['これは「プライベートクラウド」の説明です。','これは「ハイブリッドクラウド」の説明です。','正しい。「パブリッククラウド」は、AWSなどのクラウドプロバイダーが所有・運用し、インターネット経由で複数の組織・顧客が共有して利用できるコンピューティング環境です。','これは「マルチクラウド」の説明です。']}},
  {id:'v189', term:'AWS Organizations の管理アカウント (Management Account)', domain:'billing', source:SOURCES.organizations, q:{text:'AWS Organizationsにおける「管理アカウント(Management Account)」の特徴として正しいものはどれですか？', choices:['組織内のどのメンバーアカウントからでも、いつでも自由に管理アカウントの役割を引き継げる','管理アカウントは、他のメンバーアカウントと同様にOrganizationsから退出(Leave)できる','管理アカウントにはサービスコントロールポリシー(SCP)が適用され、他のメンバーアカウントと同じ制限を受ける','組織全体の一括支払い(Consolidated Billing)の請求先となり、Organizationsから退出することはできず、組織自体を削除することでのみ組織から外れる'], correct:3, why:['誤り。管理アカウントの役割は自由に引き継げるものではなく、作成時のアカウントが担います。','誤り。メンバーアカウントはLeaveOrganization操作で組織から退出できますが、管理アカウントはこの方法で退出できません。','誤り。SCPは管理アカウントには適用されません（メンバーアカウントにのみ適用されます）。','正しい。管理アカウントは組織全体の請求を一括して受け取る請求先であり、通常の退出操作はできず、組織自体を削除(DeleteOrganization)することでのみ組織から外れます。']}},
  {id:'v190', term:'SLA (Service Level Agreement)', domain:'concepts', source:SOURCES.slaLegal, q:{text:'AWSにおける「SLA(Service Level Agreement、サービスレベルアグリーメント)」とは何ですか？', choices:['AWSが対象サービスについて保証する稼働率(可用性)などの水準を定めた契約で、満たせなかった場合にサービスクレジット等の補償を受けられる','障害発生時に許容できる最大のデータ損失量を、利用者側が事前に定義する目標値','障害発生からサービス復旧までに許容できる最大時間を、利用者側が事前に定義する目標値','利用者が自ら設定する、アプリケーションの応答時間の目標値'], correct:0, why:['正しい。SLAはAWSが対象の有料サービスについて保証する稼働率などの水準を定めた契約で、水準を満たせなかった場合は利用者がサービスクレジット等の補償を申請できます。','これはRPO(目標復旧時点)の説明です。SLAはAWS側が提示する契約であり、利用者が設定する目標値ではありません。','これはRTO(目標復旧時間)の説明です。SLAはAWS側が提示する契約であり、利用者が設定する目標値ではありません。','これはアプリケーション側で独自に設定する性能目標の説明であり、AWSが契約として保証するSLAとは異なります。']}},
  {id:'v191', term:'マルチクラウド (Multi-Cloud)', domain:'concepts', source:SOURCES.hybridCloud, q:{text:'クラウドの「デプロイモデル」のうち、「マルチクラウド」の説明として正しいものはどれですか？', choices:['オンプレミス環境とクラウド環境を接続し、両方を組み合わせて利用する環境','複数の異なるクラウドプロバイダーのサービスを組み合わせて利用する環境','単一の組織専用に構築・運用され、他の組織とは共有されないコンピューティング環境','AWSが所有・運用し、インターネット経由で複数の組織が共有して利用できるコンピューティング環境'], correct:1, why:['これは「ハイブリッドクラウド」の説明です。','正しい。「マルチクラウド」は、複数の異なるクラウドプロバイダー(例: AWSと他社クラウド)のサービスを組み合わせて利用する環境です。','これは「プライベートクラウド」の説明です。','これは「パブリッククラウド」の説明です。']}},
  {id:'v192', term:'AWS Cloud Map', domain:'tech', source:SOURCES.cloudMap, q:{text:'AWS Cloud Mapとは何ですか？', choices:['VPC内のネットワークトラフィックのログを記録し、分析できるようにするサービス','複数のAWSリージョンにまたがるリソースを、名前やタグで横断的に検索するサービス','EC2インスタンスやECSタスク、DynamoDBテーブルなどのリソースに論理的な名前を割り当て、アプリケーションがAPI呼び出しやDNSクエリでそれらを検出(ディスカバリー)できるようにするサービス。ヘルスチェックに対応しており、正常な状態のリソースのみを返す','複数のAWSアカウントの課金を一つにまとめて管理するサービス'], correct:2, why:['これはAmazon VPC Flow Logsの説明です。','これはAWS Resource Explorerの説明です。','正しい。AWS Cloud Mapは、EC2・ECS・DynamoDB・SQSなど動的に変化するリソースに論理的な名前を割り当て、アプリケーションがAPI呼び出しやDNSクエリで動的にそれらを検出できるようにするサービスです。ヘルスチェックを設定すれば、正常な状態のリソースのみを返します。','これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。']}},
  {id:'v193', term:'最小権限の原則 (Principle of Least Privilege)', domain:'security', source:SOURCES.iam, q:{text:'IAMにおける「最小権限の原則(Principle of Least Privilege)」とは何ですか？', choices:['すべてのIAMユーザーにAdministratorAccessポリシーを付与し、管理を簡略化する考え方','一つのIAMロールをすべてのアプリケーションで共有し、ポリシー管理の手間を減らす考え方','パスワードの複雑性要件をできるだけ緩和し、ユーザーの利便性を優先する考え方','ユーザーやアプリケーションには、タスクの実行に必要な最小限の権限だけを付与するという、IAMポリシー設計の基本的な考え方'], correct:3, why:['誤り。全員に管理者権限を付与することは最小権限の原則に反し、セキュリティリスクを高めます。','誤り。ロールの共有は権限の範囲が広がりすぎる可能性があり、最小権限の原則に反します。','誤り。パスワード要件の緩和は最小権限の原則とは無関係で、むしろセキュリティを弱める可能性があります。','正しい。最小権限の原則は、ユーザーやアプリケーションに対して、タスクの実行に必要な最小限のアクセス権限だけを付与するという、IAMポリシー設計の基本的な考え方です。']}},
  {id:'v194', term:'AWS Service Quotas', domain:'concepts', source:SOURCES.serviceQuotas, q:{text:'AWS Service Quotas（サービスクォータ）とは何ですか？', choices:['AWSアカウントにおける各サービスのリソース数・操作回数の上限値を一元的に確認し、必要に応じて引き上げをリクエストできるサービス','EC2インスタンスのCPU使用率を監視し、しきい値超過時に通知するサービス','AWSの利用料金の上限額を設定し、超過しそうになったら通知するサービス','IAMユーザーが実行できるAPIの種類を制限するサービス'], correct:0, why:['正しい。Service Quotasは、AWSアカウントにおける各サービスの上限値（クォータ、旧称:制限）を一元的に確認でき、引き上げが可能なクォータについてはリクエストを申請できるサービスです。','これはAmazon CloudWatch（メトリクス監視・アラーム）の説明です。','これはAWS Budgets（予算のしきい値通知）の説明です。','これはIAMポリシー（アクセス許可の制御）の説明であり、Service Quotasの役割とは異なります。']}},
  {id:'v195', term:'AWS Shield Advanced', domain:'security', source:SOURCES.shield, q:{text:'AWS Shield Advancedが、無料で全アカウントに提供されるAWS Shield Standardと比べて追加で提供する機能として正しいものはどれですか？', choices:['Amazon S3のデータを自動的に暗号化する機能','大規模DDoS攻撃を受けた際に、攻撃に起因するスケーリング費用（EC2・ELB・CloudFront・Route 53等）の増加分に対する請求保護（コスト保護）と、24時間365日対応のDDoS Response Team(DRT)によるサポート','IAMユーザーのパスワードポリシーを強制する機能','VPC内の通信ログをS3に自動保存する機能'], correct:1, why:['これはAWS KMSやS3のデフォルト暗号化機能の説明であり、Shield Advancedの機能ではありません。','正しい。Shield Advancedは、DDoS攻撃に起因するスケーリング費用の増加分に対するコスト保護や、DRT（DDoS Response Team）への24時間365日のサポート依頼など、Standardにはない高度な保護とサポートを追加料金で提供します。','これはIAMパスワードポリシーの説明であり、Shield Advancedの機能ではありません。','これはAmazon VPC Flow Logsの説明であり、Shield Advancedの機能ではありません。']}},
  {id:'v196', term:'AWS CodeBuild', domain:'tech', source:SOURCES.codebuild, q:{text:'AWS CodeBuildとは何ですか？', choices:['複数のAWSリージョンにまたがるリソースをタグで横断的に検索するサービス','ソースコードのコンパイル、テストの実行、デプロイ可能なソフトウェアパッケージの生成までを行う、フルマネージド型のビルド(継続的インテグレーション)サービス','アプリケーションのデプロイ処理を自動化するサービス','複数のAWSサービスを連携させたリリースパイプライン全体を管理するサービス'], correct:1, why:['これはAWS Resource Explorerの説明です。','正しい。CodeBuildは、ソースコードのコンパイル・単体テストの実行・デプロイ可能な成果物の生成までを、サーバーを管理することなく実行できるフルマネージド型のビルドサービスです。','これはAWS CodeDeploy（デプロイ自動化）の説明です。','これはAWS CodePipeline（リリースパイプライン全体の管理）の説明です。']}},
  {id:'v197', term:'EC2 Dedicated Host', domain:'billing', source:SOURCES.dedicatedHosts, q:{text:'Amazon EC2の「Dedicated Host（専有ホスト）」の特徴として正しいものはどれですか？', choices:['複数のAWSアカウントでインスタンスを共有する、最も安価な購入オプション','物理サーバーを丸ごと占有でき、ソケット単位・コア単位のBYOL（持ち込みライセンス）に対応し、ホスト単位で課金される購入オプション','必要なときだけ数分間利用し、中断されると課金されない最も安価な購入オプション','1年または3年の利用を確約することで割引を受けられるが、物理サーバーは専有できない購入オプション'], correct:1, why:['誤り。これはオンデマンドインスタンスの一般的な説明とは異なり、Dedicated Hostは他のAWSアカウントとは共有せず専有する購入オプションです（ホスト単位でインスタンス容量を他アカウントと共有する設定も可能ですが、既定では専有です）。','正しい。Dedicated Hostは物理サーバーを丸ごと専有でき、ソケット単位・コア単位のソフトウェアライセンスを持ち込める(BYOL)点が特徴で、インスタンス単位ではなくホスト単位で課金されます。','これはスポットインスタンスの説明です。','これはリザーブドインスタンス（Dedicated Hostではなく通常のインスタンスに対する購入オプション）の説明です。']}},
  {id:'v198', term:'AWS Transform', domain:'concepts', source:SOURCES.transform, q:{text:'AWS Transformとは何ですか？', choices:['生成AI(エージェント型AI)を使って、メインフレームやVMware環境、.NETアプリケーションなどの大規模なモダナイゼーション・移行作業を支援するサービスで、利用に追加料金はかからない','オンプレミスのサーバーをAWSへそのまま複製してEC2上で起動する、再ホスト(リホスト)専用の移行サービス','オンプレミスとAWSの間でVPN接続を確立するネットワークサービス','複数のAWSアカウントの請求を一つにまとめて管理するサービス'], correct:0, why:['正しい。AWS Transformは、メインフレーム・VMware環境・.NETアプリケーションなどの大規模なモダナイゼーション・移行作業を、専門分野ごとのAIエージェントが支援するサービスで、利用自体に追加料金はかかりません。','これはAWS Application Migration Service (MGN)など、リホストに特化したサービスの説明です。AWS Transformはリホストだけでなくモダナイゼーションやコード変換など幅広い作業を支援します。','これはAWS Site-to-Site VPNの説明です。','これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。']}},
  {id:'v199', term:'Amazon Transcribe', domain:'tech', source:SOURCES.transcribe, q:{text:'Amazon Transcribeとは何ですか？', choices:['テキストを自然な音声に変換するサービス','音声データ(音声ファイルやストリーミング音声)を自動的にテキストに変換する、音声認識(Speech-to-Text)サービス','テキストの文章から感情や主要なキーフレーズを抽出するサービス','会話型のインターフェース(チャットボット)を構築するサービス'], correct:1, why:['これはAmazon Pollyの説明です。','正しい。Amazon Transcribeは、音声ファイルやストリーミング音声を自動的にテキストに変換する音声認識(Speech-to-Text)サービスです。','これはAmazon Comprehendの説明です。','これはAmazon Lexの説明です。']}},
  {id:'v200', term:'AWS X-Ray', domain:'tech', source:SOURCES.xray, q:{text:'AWS X-Rayとは何ですか？', choices:['EC2インスタンスのCPU使用率などのメトリクスを収集し、しきい値超過時にアラームを発報するサービス','複数のログソースを一箇所に集約し、全文検索できるようにするサービス','分散アプリケーションを構成する複数のサービス間を流れるリクエストをエンドツーエンドで追跡し、サービスマップとして可視化することで、ボトルネックや障害箇所の特定を支援するサービス','IoTデバイスの構成を監査し、異常な挙動を検知するサービス'], correct:2, why:['これはAmazon CloudWatch(メトリクス監視・アラーム)の説明です。','これはAmazon OpenSearch Serviceの説明です。','正しい。AWS X-Rayは、マイクロサービスなど複数のコンポーネントを流れるリクエストをエンドツーエンドで追跡し、サービスマップとして可視化することで、ボトルネックや障害箇所の特定を支援する分散トレーシングサービスです。','これはAWS IoT Device Defenderの説明です。']}},
  {id:'v201', term:'アベイラビリティーゾーン (Availability Zone, AZ)', domain:'concepts', source:SOURCES.globalInfra, q:{text:'AWSグローバルインフラストラクチャにおける「アベイラビリティーゾーン(AZ)」とは何ですか？', choices:['世界各地に分散して配置され、ユーザーに最も近い場所でコンテンツを配信するためのキャッシュサーバー群','1つ以上のAWSリージョンをまとめた、地理的に大きな単位','オンプレミスとAWSクラウドを接続するための専用線の接続ポイント','1つのAWSリージョン内にある、独立した電源・ネットワーク・冷却設備を備えた1つまたは複数のデータセンターの集まりで、同じリージョン内の他のAZとは低レイテンシーのプライベートリンクで接続されている'], correct:3, why:['これはAmazon CloudFrontの「エッジロケーション」の説明です。','リージョンはAZをまとめた単位ではなく、むしろAZの集合がリージョンを構成します(説明が逆です)。','これはAWS Direct Connectの「Direct Connectロケーション」の説明です。','正しい。アベイラビリティーゾーン(AZ)は、独立した電源・ネットワーク・冷却設備を備えた1つまたは複数のデータセンターの集まりで、同じリージョン内の他のAZとは低レイテンシーのプライベートリンクで接続されています。']}},
  {id:'v202', term:'AWS Well-Architected レンズ (Lens)', domain:'concepts', source:SOURCES.waLens, q:{text:'AWS Well-Architected Frameworkにおける「レンズ(Lens)」とは何ですか？', choices:['6つの柱の基本的な質問に加えて、サーバーレスやSaaSなど特定のワークロードやドメインに特化した追加のベストプラクティス・質問を提供する仕組み','ワークロードの構成情報を自動的に収集し、アーキテクチャ図を生成する機能','AWSサポートプランごとに提供される、人による無料のアーキテクチャレビューサービス','IAMポリシーの許可内容を可視化するコンソール機能'], correct:0, why:['正しい。レンズは、6つの柱に基づく汎用的な質問に加えて、サーバーレスアプリケーションレンズやSaaSレンズのように、特定のワークロードタイプやドメインに特化した追加のベストプラクティス・質問を提供する仕組みです。','これはアーキテクチャ図の自動生成ツールの説明であり、レンズの機能ではありません。','これはAWSサポートの人的なアーキテクチャレビューの説明であり、レンズ自体は人によるレビューサービスではありません。','これはIAM Access Analyzer等の説明であり、レンズとは無関係です。']}},
  {id:'v203', term:'AWS Network Access Analyzer', domain:'security', source:SOURCES.networkAccessAnalyzer, q:{text:'AWS Network Access Analyzerとは何ですか？', choices:['IAMユーザーやロールに付与されたポリシーが未使用かどうかを分析するサービス','指定したネットワークアクセス要件(セグメンテーションやインターネットからの到達可能性など)に反する、意図しないネットワークパスを静的解析によって検出する機能','VPC内の通信を実際にキャプチャし、送信元・宛先ごとの通信量を記録するサービス','DDoS攻撃の発生を検知し、自動的に緩和策を適用するサービス'], correct:1, why:['これはAWS IAM Access Analyzerの説明です。','正しい。Network Access Analyzerは、ネットワークセグメンテーションやインターネットからの到達可能性など指定した要件に反する潜在的なネットワークパスを、実際にパケットを送信せず静的解析(自動推論)によって検出します。','これはVPC Flow Logsの説明です。','これはAWS Shieldの説明です。']}},
  {id:'v204', term:'AWS Elemental MediaConvert', domain:'tech', source:SOURCES.mediaconvert, q:{text:'AWS Elemental MediaConvertとは何ですか？', choices:['ライブイベントの映像をリアルタイムでエンコードし配信するためのライブストリーミング専用サービス','オンプレミスのメディアファイルをAWSへ転送するためのデータ転送サービス','放送用コーデックやHDR、DRM、字幕といった高度な機能を備え、オンデマンド配信向けに動画ファイルをトランスコードする、ファイルベースの動画処理サービス','動画コンテンツに含まれる不適切なシーンを自動検出するサービス'], correct:2, why:['これはAWS Elemental MediaLive(ライブストリーミング)の説明です。','これはAWS DataSyncなどのデータ転送サービスの説明です。','正しい。MediaConvertは、放送用コーデックやHDR対応、DRM、字幕サポートなどの高度な機能を備え、オンデマンド配信向けの動画ファイルをトランスコードするファイルベースの動画処理サービスです。','これはAmazon Rekognitionの動画コンテンツモデレーション機能の説明です。']}},
  {id:'v205', term:'AWS Budgets アクション (Budget Actions)', domain:'billing', source:SOURCES.budgets, q:{text:'AWS Budgetsの「アクション(Budget Actions)」機能の特徴として正しいものはどれですか？', choices:['コストが予算のしきい値を超えた場合に、自動的にAWSサポートへの問い合わせチケットを作成する','コスト超過を検知した場合に、必ず承認なしで即座にリソースを削除する','予算のしきい値監視機能のみを提供し、超過時に実際のリソースへアクションを実行することはできない','しきい値を超えた際に、IAMポリシーの適用、サービスコントロールポリシー(SCP)のアタッチ、対象のEC2/RDSインスタンスの停止といった対応を、承認を挟んで(または自動で)実行できる'], correct:3, why:['誤り。Budget Actionsが作成するのはサポートチケットではなく、IAMポリシーの適用・SCPのアタッチ・EC2/RDSインスタンスの停止などの実際のアクションです。','誤り。アクションの実行には承認ワークフローを挟む設定も可能であり、常に承認なしで即実行されるわけではありません。','誤り。AWS Budgets単体(アクションなし)では監視とアラート通知のみですが、Budget Actions機能を使うと実際のリソースへの対応アクションを実行できます。','正しい。Budget Actionsは、しきい値超過時にIAMポリシーの適用・SCPのアタッチ・対象のEC2/RDSインスタンスの停止といったアクションを、承認制または自動で実行できる機能です。']}},
  {id:'v206', term:'Amazon Location Service', domain:'tech', source:SOURCES.locationService, q:{text:'Amazon Location Serviceとは何ですか？', choices:['地図、場所検索(ジオコーディング)、ルート検索、ジオフェンス、トラッカーといった位置情報関連の機能を、自社で地図データを保有せずにアプリケーションへ追加できるマネージド型の位置情報サービス','IoTデバイスの位置情報を収集し、機械学習で異常な移動パターンを検知するサービス','オンプレミスのGPSデータをAWSへ一括インポートするためのデータ転送サービス','ユーザーの位置情報に基づいてCloudFrontのキャッシュ配信先を自動的に切り替える機能'], correct:0, why:['正しい。Amazon Location Serviceは、地図・場所検索(ジオコーディング)・ルート検索・ジオフェンス・トラッカーといった高品質な位置情報データを使った機能を、自社で地図データを保有・管理せずにアプリケーションへ追加できるマネージド型サービスです。','これは説明の一部(トラッカー機能)のみを指しており、Amazon Location Serviceが提供する機能全体の説明ではありません。','Amazon Location Serviceはデータ転送サービスではありません。','Amazon Location ServiceはCloudFrontのキャッシュ配信先切り替え機能を提供するものではありません。']}},
  {id:'v207', term:'AWS WAF Bot Control', domain:'security', source:SOURCES.wafService, q:{text:'AWS WAF Bot Controlとは何ですか？', choices:['DDoS攻撃を検知し自動的に緩和するAWSのマネージドサービス','AWS WAFのマネージドルールグループの一つで、検索エンジンのクローラーなど正当なボットを識別しつつ、スクレイピングツールなど望ましくないボットのトラフィックを検出・ブロックする機能','Webアプリケーションの脆弱性を継続的にスキャンするサービス','VPC内の通信を記録し、ボットによる不審な通信パターンを事後分析するためのログサービス'], correct:1, why:['これはAWS Shieldの説明です。','正しい。Bot ControlはAWS WAFのマネージドルールグループの一つで、検索エンジンのクローラーなど正当な(既知の)ボットを識別しつつ、スクレイピングツールなど望ましくないボットのトラフィックを検出・ブロックします。','これはAmazon Inspectorの説明です。','これはVPC Flow Logsの説明であり、Bot Controlはリアルタイムでのトラフィック検出・ブロックを行う機能です。']}},
  {id:'v208', term:'AWS Skill Builder', domain:'concepts', source:SOURCES.skillBuilder, q:{text:'AWS Skill Builder（AWS Training and Certification）とは何ですか？', choices:['AWSの利用料金の見積りを作成するためのツール','AWSリソースの構成を自動でコード化するサービス','AWSが提供する公式の学習プラットフォームで、無料のデジタルコースや、サブスクリプションで利用できるハンズオンラボ・認定試験対策コンテンツなどを通じてクラウドスキルの習得や資格取得を支援する','AWS認定資格保有者同士が交流するためのコミュニティサイト'], correct:2, why:['これはAWS Pricing Calculatorの説明です。','これはAWS CloudFormation等のInfrastructure as Codeサービスの説明です。','正しい。AWS Skill Builderは、AWSが提供する公式の学習プラットフォームで、無料のデジタルコースに加え、サブスクリプション契約でハンズオンラボや認定試験対策コンテンツなどを利用でき、クラウドスキルの習得や資格取得を支援します。','AWS Skill Builderは学習プラットフォームであり、単なる交流コミュニティではありません。']}},
  {id:'v209', term:'AWS Partner Network (APN)', domain:'billing', source:SOURCES.partnerNetwork, q:{text:'AWS Partner Network (APN)とは何ですか？', choices:['AWSが企業内に設置する専用のネットワーク機器','AWSサポートプランの一つで、専任の技術アカウントマネージャーが付与される仕組み','サードパーティ製のソフトウェアやデータ製品を検索・購入できるオンラインカタログ','AWS上でのソリューションの構築・導入・運用を支援するコンサルティングパートナーやテクノロジーパートナーなど、世界中の企業で構成されるグローバルなパートナーコミュニティ'], correct:3, why:['AWS Partner Networkは物理的なネットワーク機器ではありません。','これはAWSサポートプラン(Enterprise Support等)の技術アカウントマネージャー(TAM)の説明です。','これはAWS Marketplaceの説明です。','正しい。AWS Partner Network (APN) は、AWS上でのソリューションの構築・導入・運用を支援するコンサルティングパートナーやテクノロジーパートナーなど、世界中の企業で構成されるグローバルなパートナーコミュニティです。']}},
  {id:'v210', term:'AWS Lake Formation', domain:'tech', source:SOURCES.lakeFormation, q:{text:'AWS Lake Formationとは何ですか？', choices:['Amazon S3上のデータレイクとAWS Glueデータカタログのメタデータに対して、データベース・テーブル・列・行単位の詳細なアクセス許可を一元的に管理できる、データレイクの構築とガバナンスを支援するサービス','S3に保存された生データを変換・クレンジングし、Glueデータカタログへ登録するためのサーバーレスなETLサービス','S3やRDS等に保存されたデータに対してSQLクエリを直接実行できるサーバーレスのクエリサービス','複数のAWSアカウント間でVPCサブネットやTransit Gateway等のリソースを安全に共有するサービス'], correct:0, why:['正しい。AWS Lake Formationは、Amazon S3上のデータレイクとAWS Glueデータカタログのメタデータに対し、データベース・テーブル・列・行単位の詳細なアクセス許可を一元的に管理できる、データレイクの構築とガバナンスを支援するサービスです。','これはAWS Glueの説明です。Lake FormationはGlueデータカタログと連携してアクセス許可を管理する側であり、ETL処理自体を行うサービスではありません。','これはAmazon Athenaの説明です。','これはAWS Resource Access Manager (RAM)の説明です。']}},
  {id:'v211', term:'AWS Elemental MediaLive', domain:'tech', source:SOURCES.medialive, q:{text:'AWS Elemental MediaLiveとは何ですか？', choices:['事前に録画・保存された動画ファイルをバッチ処理で複数のフォーマットへトランスコードするサービス','ライブ(リアルタイム)の動画コンテンツを、放送やストリーミング配信に適した複数の形式・パッケージへリアルタイムで変換するサービス','動画や画像のコンテンツを解析し、不適切なコンテンツや特定の物体・顔を検出するサービス','動画コンテンツをエッジロケーション経由でキャッシュし、視聴者に低レイテンシーで配信するCDNサービス'], correct:1, why:['これはAWS Elemental MediaConvertの説明です。MediaConvertは保存済み(オンデマンド)の動画ファイルをバッチでトランスコードするサービスで、ライブ配信には対応していません。','正しい。AWS Elemental MediaLiveは、ライブの動画コンテンツを放送やストリーミング配信に適した複数の形式・パッケージへリアルタイムで変換するサービスです。','これはAmazon Rekognitionの説明です。','これはAmazon CloudFrontの説明です。']}},
  {id:'v212', term:'Amazon ECS', domain:'tech', source:SOURCES.ecs, q:{text:'Amazon ECS (Elastic Container Service)とは何ですか？', choices:['Kubernetesの標準APIに準拠した管理コントロールプレーンを提供するマネージド型コンテナサービス','サーバーやクラスターを自分で管理せずにコンテナを直接実行できる、サーバーレスのコンピューティングエンジン','Dockerコンテナを、管理者が指定したEC2インスタンス群、またはサーバーレスの起動タイプ(AWS Fargate)の上で実行・管理できる、AWS独自のAPIを使うマネージド型コンテナオーケストレーションサービス','コンテナイメージを安全に保存・管理し、脆弱性スキャンも行えるプライベートコンテナレジストリサービス'], correct:2, why:['これはAmazon EKSの説明です。EKSはKubernetesの標準APIに準拠しますが、ECSはAWS独自のAPIを使用します。','これはAWS Fargateの説明です。FargateはECSやEKSの起動タイプの一つとして利用できるサーバーレスのコンピューティングエンジンです。','正しい。Amazon ECSは、Dockerコンテナを管理者が指定したEC2インスタンス群、またはサーバーレスの起動タイプ(AWS Fargate)の上で実行・管理できる、AWS独自のAPIを使うマネージド型コンテナオーケストレーションサービスです。','これはAmazon ECRの説明です。']}},
  {id:'v213', term:'ハイブリッドクラウド (Hybrid Cloud)', domain:'concepts', source:SOURCES.hybridCloud, q:{text:'クラウドの「デプロイモデル」のうち、「ハイブリッドクラウド」の説明として正しいものはどれですか？', choices:['複数の異なるクラウドプロバイダーのサービスを組み合わせて利用する環境','AWSなどのクラウドプロバイダーが所有・運用し、インターネット経由で複数の組織・顧客が共有して利用できるコンピューティング環境','単一の組織専用に構築・運用され、他の組織とは共有されないコンピューティング環境','オンプレミスのデータセンターとクラウド環境をDirect ConnectやVPN等のネットワークで接続し、ワークロードやデータの要件に応じて両方の環境を組み合わせて利用する環境'], correct:3, why:['これは「マルチクラウド」の説明です。','これは「パブリッククラウド」の説明です。','これは「プライベートクラウド」の説明です。','正しい。「ハイブリッドクラウド」は、オンプレミスのデータセンターとクラウド環境をDirect ConnectやVPN等のネットワークで接続し、ワークロードやデータの要件に応じて両方の環境を組み合わせて利用する環境です。']}},
  {id:'v214', term:'Amazon GameLift Servers', domain:'tech', source:SOURCES.gamelift, q:{text:'Amazon GameLift Serversとは何ですか？', choices:['セッションベースのマルチプレイヤーゲーム向けに、専用のゲームサーバーをクラウド上でデプロイ・運用し、プレイヤー数に応じて動的にスケールできるサービス','モバイルアプリのバックエンドとして、HTTPリクエストを受け付けAWS Lambda関数を呼び出すためのAPI管理サービス','リアルタイムの音声・ビデオ通話やメッセージング、画面共有の機能を自社アプリに組み込むための通信コンポーネント群','ライブ配信の動画を放送・ストリーミング配信に適した形式へリアルタイムで変換するサービス'], correct:0, why:['正しい。Amazon GameLift Serversは、セッションベースのマルチプレイヤーゲーム向けに、低コストで信頼性の高い専用ゲームサーバーをクラウド上でデプロイ・運用し、プレイヤー数に応じて動的にスケールできるサービスです。','これはAmazon API Gatewayの説明です。','これはAmazon Chime SDKの説明です。','これはAWS Elemental MediaLiveの説明です。']}},
  {id:'v215', term:'Amazon Chime SDK', domain:'tech', source:SOURCES.chimeSdk, q:{text:'Amazon Chime SDKとは何ですか？', choices:['Dockerコンテナを管理者が指定したEC2インスタンス群、またはサーバーレスの起動タイプの上で実行・管理するコンテナオーケストレーションサービス','メッセージング、音声通話、ビデオ通話、画面共有の機能を、自社のWebアプリやモバイルアプリに組み込める、リアルタイムコミュニケーション向けのコンポーネント群','ライブのマルチプレイヤーゲーム向けに専用のゲームサーバーをクラウド上でホスティングするサービス','ストリーミングデータをリアルタイムで収集・処理するためのマネージド型サービス'], correct:1, why:['これはAmazon ECSの説明です。','正しい。Amazon Chime SDKは、メッセージング・音声・ビデオ・画面共有の機能を自社アプリに組み込める、リアルタイムコミュニケーション向けのコンポーネント群で、従量課金制(pay-for-use)で提供されます。','これはAmazon GameLift Serversの説明です。','これはAmazon Kinesis Data Streamsの説明です。']}},
  {id:'v216', term:'AWS Payment Cryptography', domain:'security', source:SOURCES.paymentCryptography, q:{text:'AWS Payment Cryptographyとは何ですか？', choices:['一般的なデータの暗号化・復号に使う汎用的な暗号鍵を作成・管理するマネージド型サービス','専用のハードウェアセキュリティモジュール(HSM)インスタンスを1顧客専有で提供する汎用HSMサービス','カード会員PINの変換やCVV生成・検証などの決済処理向け暗号機能・鍵管理を、専用のペイメントHSMを自前で調達せずに利用できるマネージド型サービス','サードパーティの決済代行会社が提供する決済処理ソフトウェアを購入できるマーケットプレイス'], correct:2, why:['これはAWS KMSの説明です。AWS Payment Cryptographyはペイメント業界(PCI)基準に沿った決済処理専用の暗号機能を提供します。','これはAWS CloudHSMの説明です。','正しい。AWS Payment Cryptographyは、カード会員PINの変換、CVV/CVV2/ARQCの生成・検証など決済処理に使う暗号機能と鍵管理を、専用のペイメントHSMを調達せずに利用できるマネージド型サービスです。','これはAWS Marketplaceの説明です。']}},
  {id:'v217', term:'AWS Cloud Value Framework', domain:'concepts', source:SOURCES.cloudValueFramework, q:{text:'AWSの「Cloud Value Framework（クラウド・バリュー・フレームワーク）」とは何ですか？', choices:['AWSの各リージョン・アベイラビリティーゾーンの物理的な配置を示すフレームワーク','オンプレミスからクラウドへの移行戦略を7つのパターン(7R\'s)に分類したフレームワーク','Well-Architected Frameworkの6つの柱に基づいてワークロードを評価するためのツール','コスト削減・スタッフの生産性向上・運用上の回復性・ビジネスアジリティ・持続可能性という5つの観点から、クラウド導入がもたらすビジネス価値を測定するためのフレームワーク'], correct:3, why:['これはAWSグローバルインフラストラクチャの説明です。','これは移行戦略(7R\'s)の説明です。','これはAWS Well-Architected Toolの説明です。','正しい。AWS Cloud Value Frameworkは、コスト削減・スタッフの生産性向上・運用上の回復性・ビジネスアジリティ・持続可能性の5つの観点から、クラウド導入のビジネス価値を測定するためのフレームワークです。']}},
  {id:'v218', term:'AWS Fargate', domain:'tech', source:SOURCES.fargate, q:{text:'AWS Fargateとは何ですか？', choices:['Amazon ECSやAmazon EKSでコンテナを実行する際に、基盤となるEC2インスタンスのプロビジョニングやパッチ適用・スケーリングを自前で行う必要がない、サーバーレスのコンピューティングエンジン','仮想サーバー(EC2インスタンス)を起動し、OSやミドルウェアを自分で管理するコンピューティングサービス','特定のイベントをトリガーに任意の関数コードを実行する、コンテナを使わないサーバーレスのコンピューティングサービス','静的なWebサイトやシンプルな仮想サーバー環境を低コストで素早く構築できるサービス'], correct:0, why:['正しい。AWS Fargateは、Amazon ECSやAmazon EKSでコンテナを実行する際に、基盤となるEC2インスタンスのプロビジョニングやパッチ適用・スケーリングを自前で行う必要がない、サーバーレスのコンピューティングエンジンです。','これはAmazon EC2の説明です。','これはAWS Lambdaの説明です。','これはAmazon Lightsailの説明です。']}},
  {id:'v219', term:'AWS IAM Policy Simulator', domain:'security', source:SOURCES.iamPolicySimulator, q:{text:'AWS IAM Policy Simulator(IAMポリシーシミュレーター)とは何ですか？', choices:['IAMユーザーの操作履歴を記録し、誰がいつどのAPIを呼び出したかを監査するサービス','IDベース・リソースベースのポリシーが特定のアクションを許可するか拒否するかを、実際にAWSリソースへ影響を与える本物のAPIコールを発行せずに検証できるツール','アカウント外部や組織外への意図しないリソース共有を検出するサービス','IAMポリシーの構文エラーやセキュリティ上の警告を検出する静的なポリシー検証機能'], correct:1, why:['これはAWS CloudTrailの説明です。','正しい。IAM Policy Simulatorは、IDベース・リソースベースのポリシーが特定のアクションを許可するか拒否するかを、実際にAWSリソースへ影響を与える本物のAPIコールを発行せずに検証できるツールです。','これはAWS IAM Access Analyzerの外部アクセス分析の説明です。','これはAWS IAM Access Analyzerのポリシー検証機能の説明です。']}},
  {id:'v220', term:'Amazon EC2 Capacity Reservation Fleet', domain:'billing', source:SOURCES.capacityReservationFleet, q:{text:'Amazon EC2のCapacity Reservation Fleetとは何ですか？', choices:['単一のインスタンスタイプ・単一のアベイラビリティーゾーンに対してのみ容量を確保する、最も基本的なOn-Demand Capacity Reservation','スポット容量のみを対象に、複数のインスタンスタイプへ分散してリクエストを行う仕組み','複数のインスタンスタイプに優先順位と重みを設定し、指定した合計目標容量に達するまで、EC2が自動的に複数のCapacity Reservationを作成・管理する仕組み','リザーブドインスタンスの購入条件を複数まとめて比較検討できる見積もりツール'], correct:2, why:['これは単一のOn-Demand Capacity Reservationの説明です。','これはEC2 Spot Fleet(スポットフリート)の説明です。','正しい。Capacity Reservation Fleetは、複数のインスタンスタイプに優先順位と重みを設定し、指定した合計目標容量に達するまで、EC2が自動的に複数のCapacity Reservationを作成・管理する仕組みです。','これはAWS Pricing Calculatorのような見積もりツールの説明です。']}},
  {id:'v221', term:'Amazon Kinesis Video Streams', domain:'tech', source:SOURCES.kinesisVideo, q:{text:'Amazon Kinesis Video Streamsとは何ですか？', choices:['構造化されたレコードデータをリアルタイムで収集・処理するための汎用的なストリーミングサービス','収集したストリーミングデータをAmazon S3やRedshiftなど指定した送信先へ自動的に配信するサービス','リアルタイムの音声・ビデオ通話やメッセージングの機能を自社アプリに組み込むための通信コンポーネント群','防犯カメラやドローン、スマートフォンなど多数のデバイスからのライブ映像を、保持期間を指定して暗号化保存しつつクラウドへストリーミングし、フレーム単位でのリアルタイム処理やバッチ分析のアプリケーションを構築できるフルマネージド型サービス'], correct:3, why:['これはAmazon Kinesis Data Streamsの説明です。','これはAmazon Kinesis Data Firehoseの説明です。','これはAmazon Chime SDKの説明です。','正しい。Amazon Kinesis Video Streamsは、多数のデバイスからのライブ映像を保持期間を指定して暗号化保存しつつクラウドへストリーミングし、フレーム単位でのリアルタイム処理やバッチ分析のアプリケーションを構築できるフルマネージド型サービスです。']}},
  {id:'v222', term:'AWS Prescriptive Guidance', domain:'concepts', source:SOURCES.prescriptiveGuidance, q:{text:'AWS Prescriptive Guidanceとは何ですか？', choices:['AWSの技術専門家が蓄積した移行・モダナイゼーションのノウハウを、戦略(Strategy)・パターン(Pattern)・ガイドなどの形式で提供するコンテンツライブラリで、AWS Cloud Adoption Framework (CAF)の考え方を踏まえて体系化されている','AWSの利用料金をサービス・リージョンごとに予測し、見積りを作成するツール','AWSサポートプランの一つで、専任のソリューションアーキテクトが個別に設計レビューを行うプラン','IAMポリシーが意図した権限のみを許可しているかを静的に検証するツール'], correct:0, why:['正しい。AWS Prescriptive Guidanceは、AWSの技術専門家が蓄積した移行・モダナイゼーションのノウハウを、戦略(Strategy)・パターン(Pattern)・ガイドなどの形式で提供するコンテンツライブラリで、AWS Cloud Adoption Framework (CAF)の考え方を踏まえて体系化されています。','これはAWS Pricing Calculatorの説明です。','これはAWSサポートプラン(Enterprise Support等)の技術アカウントマネージャーやアーキテクチャレビューの説明であり、Prescriptive Guidanceはドキュメント形式のコンテンツライブラリです。','これはAWS IAM Access Analyzerのポリシー検証機能の説明です。']}},
  {id:'v223', term:'AWS コンプライアンスプログラム (AWS Compliance Programs)', domain:'security', source:SOURCES.compliancePrograms, q:{text:'AWSの「コンプライアンスプログラム」ページが提供する情報として正しいものはどれですか？', choices:['利用中のAWSリソースの構成変更履歴を記録する機能','AWSが準拠・認証を取得している規格(ISO 27001、SOC 2、PCI DSSなど)や法規制・プライバシー要件を、リージョンやサービスの対象範囲とともに一覧できる公式情報ページ','顧客自身のAWS環境がコンプライアンス要件を満たしているかを自動的にスキャンし、スコアを算出するサービス','サードパーティのコンプライアンス監査人を検索・依頼できるマーケットプレイス'], correct:1, why:['これはAWS Configの説明です。','正しい。AWSのコンプライアンスプログラムページは、AWSが準拠・認証を取得している規格や法規制・プライバシー要件を、対象のリージョンやサービスの範囲とともに一覧できる公式情報ページです。','これはAWS Audit Managerの説明に近いですが、コンプライアンスプログラムのページ自体は顧客環境を自動スキャンするサービスではなく、AWS側の認証状況を示す情報ページです。','これはAWS Partner Network (APN)などの説明に近いですが、コンプライアンス監査人を検索するマーケットプレイスではありません。']}},
  {id:'v224', term:'Amazon GuardDuty Malware Protection for S3', domain:'security', source:SOURCES.guardduty, q:{text:'Amazon GuardDuty Malware Protection for S3の特徴として正しいものはどれですか？', choices:['EBSボリュームにのみ対応したマルウェアスキャン機能で、S3は対象外である','顧客自身でスキャン用のEC2インスタンスやLambda関数を構築し、スキャンエンジンを運用する必要がある','Amazon S3バケットへ新しくアップロードされたオブジェクトをマルウェアの観点でスキャンし、結果をAmazon EventBridgeへ発行することで、検疫(クアランティン)などの自動対応につなげられるフルマネージド機能','S3バケットの暗号化設定が正しいかどうかを静的に検証する機能'], correct:2, why:['誤り。GuardDutyはEC2/EBSボリュームのマルウェア保護に加えて、S3へのマルウェア保護機能も提供しています。','誤り。スキャンはAWSが完全にマネージドで実行し、顧客がスキャン用のインフラを構築・運用する必要はありません。','正しい。GuardDuty Malware Protection for S3は、S3バケットへ新しくアップロードされたオブジェクトをマルウェアの観点でスキャンし、結果をAmazon EventBridgeへ発行することで、検疫などの自動対応につなげられるフルマネージド機能です。','誤り。これはAWS Configなどの静的な設定検証サービスの説明に近く、Malware Protection for S3はアップロードされたオブジェクトの内容をスキャンする機能です。']}},
  {id:'v225', term:'AWS Activate', domain:'billing', source:SOURCES.activate, q:{text:'AWS Activateとは何ですか？', choices:['AWSサポートプランの一つで、スタートアップ企業向けに割引価格で提供されるサポートプラン','AWS Marketplaceで販売されているサードパーティ製ソフトウェアを、スタートアップ向けの特別価格で購入できる仕組み','AWS認定資格を保有するスタートアップのエンジニアに対して認定バッジを付与する制度','スタートアップ向けに、AWS利用料金に充当できるクレジットや技術サポート、トレーニングなどを提供するプログラムで、自己資金のスタートアップ向け(Activate Founders)と、VCやアクセラレーター等の提供者から紹介されたスタートアップ向け(Activate Portfolio)の仕組みがある'], correct:3, why:['誤り。AWS Activateはサポートプランではなく、クレジットや技術サポート、トレーニングなどを提供するスタートアップ向けプログラムです。','誤り。AWS Marketplaceの割引購入の仕組みではありません。','誤り。AWS認定資格のバッジ付与とは無関係です。','正しい。AWS Activateは、スタートアップ向けにAWS利用料金に充当できるクレジットや技術サポート、トレーニングなどを提供するプログラムで、自己資金のスタートアップ向け(Activate Founders)と、VCやアクセラレーターなどの提供者から紹介されたスタートアップ向け(Activate Portfolio)という仕組みがあります。']}},
  {id:'v226', term:'AWS Ground Station', domain:'tech', source:SOURCES.groundStation, q:{text:'AWS Ground Stationとは何ですか？', choices:['人工衛星との通信(ダウンリンク/アップリンク)に必要なアンテナ設備を自前で構築・運用せずに利用できる、フルマネージド型の衛星通信サービス','IoTデバイスとクラウド間のメッセージングを中継するマネージド型サービス','地図データやジオコーディング、ルート検索などの位置情報サービスを提供するサービス','オンプレミスとAWSの間を専用線で接続するネットワークサービス'], correct:0, why:['正しい。AWS Ground Stationは、人工衛星との通信に必要なアンテナ設備を自前で構築・運用・スケールせずに利用できる、フルマネージド型の衛星通信サービスです。','これはAWS IoT Coreの説明です。','これはAmazon Location Serviceの説明です。','これはAWS Direct Connectの説明です。']}},
  {id:'v227', term:'AWS Elemental MediaPackage', domain:'tech', source:SOURCES.mediaPackage, q:{text:'AWS Elemental MediaPackageとは何ですか？', choices:['ライブ映像をリアルタイムにエンコードし、放送・配信用の形式に変換するサービス','動画をセキュアかつスケーラブルに、様々な再生デバイスやCDNへ配信できる形式へパッケージング・オリジネーション(配信元として配布)するサービス','動画ファイルをオンデマンド(ファイルベース)でトランスコードするサービス','動画や画像に含まれる物体・テキストを認識するサービス'], correct:1, why:['これはAWS Elemental MediaLiveの説明です。','正しい。AWS Elemental MediaPackageは、動画をセキュアかつスケーラブルに、様々な再生デバイスやCDNへ配信できる形式へパッケージング・オリジネーションするJust-In-Timeの動画配信サービスです。','これはAWS Elemental MediaConvertの説明です。','これはAmazon Rekognitionの説明です。']}},
  {id:'v228', term:'AWS WAF Fraud Control - Account Takeover Prevention (ATP)', domain:'security', source:SOURCES.wafAtp, q:{text:'AWS WAFの「Account Takeover Prevention (ATP)」とは何ですか？', choices:['DDoS攻撃を検知し自動的に緩和するAWSのサービス','IAMユーザーの未使用の認可を検出する機能','盗まれた認証情報を使った不正ログイン(アカウントテイクオーバー)の試行を検知・ブロックする、AWS WAFのマネージドルールグループ','S3バケットの公開設定の誤りを検出する機能'], correct:2, why:['これはAWS Shieldの説明です。','これはAWS IAM Access Analyzerの説明です。','正しい。ATPは、ログインエンドポイントへのログイン試行を検査し、盗まれた認証情報やブルートフォース攻撃によるアカウントテイクオーバーの試行を検知・ブロックするAWS WAFのマネージドルールグループです。','これはAmazon S3のブロックパブリックアクセスなどの説明に近い内容です。']}},
  {id:'v229', term:'AWS Support App in Slack', domain:'billing', source:SOURCES.supportApp, q:{text:'AWS Support App in Slackとは何ですか？', choices:['Slack上でAWSの利用料金の支払いを完結できるサービス','Slackの投稿内容を監査ログとして記録するサービス','SlackのメッセージをAmazon Transcribeで文字起こしするサービス','Slackチャンネル上でAWSサポートケースの作成・更新・解決や、サポートエージェントとのチャットができるようにするサービス'], correct:3, why:['誤り。料金の支払いをSlack上で完結する機能はありません。','これはAWS CloudTrailなどの説明とは異なります。','Amazon Transcribeとは無関係です。','正しい。AWS Support App in Slackは、Slackチャンネル上でAWSサポートケースの作成・更新・解決や、サポートエージェントとのライブチャットができるようにするサービスです。']}},
  {id:'v230', term:'AWS Sustainability コンソール', domain:'concepts', source:SOURCES.sustainabilityConsole, q:{text:'AWS Sustainability コンソールとは何ですか？', choices:['AWSが提示するSLA(稼働率保証)の達成状況を確認するコンソール','AWSの利用料金をリージョン・サービス別に予測するコンソール','AWSの利用に伴う推定炭素排出量を、リージョン・サービス・排出区分(Scope1/2/3)別に、市場ベースおよびロケーションベースの算出方法で確認できる、無料でスタンドアロンのコンソール','IAMポリシーが最小権限の原則に沿っているかを診断するコンソール'], correct:2, why:['これはAWSのSLA関連ページの説明です。','これはAWS Pricing Calculatorなどの説明です。','正しい。AWS Sustainability コンソールは、AWS利用に伴う推定炭素排出量をリージョン・サービス・排出区分(Scope1/2/3)別に、市場ベース(MBM)・ロケーションベース(LBM)の算出方法で確認できる、無料のスタンドアロンサービスです。','これはAWS IAM Access Analyzerなどの説明です。']}},
  {id:'v231', term:'Amazon S3 Object Lock', domain:'security', source:SOURCES.s3ObjectLock, q:{text:'Amazon S3 Object Lockとは何ですか？', choices:['S3バケットへのアクセスを特定のVPCエンドポイントからのみに制限する機能','S3オブジェクトを、指定した期間または無期限に削除・上書きできないようにする、WORM(Write Once Read Many)モデルでの保護機能','S3に保存するオブジェクトをアップロード時に自動的にウイルススキャンする機能','S3バケットのデータを別リージョンへ自動的に複製する機能'], correct:1, why:['これはS3のバケットポリシーやVPCエンドポイントの説明です。','正しい。S3 Object Lockは、オブジェクトを指定した期間または無期限に削除・上書きできないようにする、WORM(Write Once Read Many)モデルでの保護機能で、規制対応やランサムウェア対策に利用できます。','これはAmazon GuardDuty Malware Protection for S3の説明です。','これはAmazon S3のクロスリージョンレプリケーション(CRR)の説明です。']}},
  {id:'v232', term:'AWS Glue DataBrew', domain:'tech', source:SOURCES.databrew, q:{text:'AWS Glue DataBrewとは何ですか？', choices:['S3に保存されたデータに対してSQLクエリを直接実行できるサーバーレスのクエリサービス','構造化データをリアルタイムで収集・処理するストリーミングサービス','データベースの構成変更履歴を記録するサービス','コードを書くことなく、250種類以上のポイント&クリック操作で、データのクレンジングや正規化を視覚的なインターフェースで行えるサーバーレスのデータ準備ツール'], correct:3, why:['これはAmazon Athenaの説明です。','これはAmazon Kinesis Data Streamsの説明です。','これはAWS Configの説明です。','正しい。AWS Glue DataBrewは、コードを書くことなく250種類以上のポイント&クリック操作でデータのクレンジング・正規化を視覚的に行えるサーバーレスのデータ準備ツールで、分析・機械学習向けのデータ準備時間を大幅に短縮できます。']}},
  {id:'v233', term:'AWS Purchase Order Management', domain:'billing', source:SOURCES.purchaseOrderMgmt, q:{text:'AWS Purchase Order Management (購入注文管理)とは何ですか？', choices:['Billing and Cost Managementコンソール上で、顧客自身が複数の購入注文(PO)とその明細(ライン品目)を登録・管理し、AWSの請求書と自動的に照合できるようにするセルフサービス機能','AWS Marketplaceで販売されている製品を購入注文(PO)形式で発注できるAWS側の代行購買サービス','AWSサポートプランの契約更新を自動化するサービス','AWS Organizationsのメンバーアカウント作成を承認制にする機能'], correct:0, why:['正しい。AWS Purchase Order Managementは、Billing and Cost Managementコンソール上で顧客自身が複数の購入注文(PO)とその明細(ライン品目)を登録・管理し、AWSの請求書と自動的に照合できるセルフサービス機能です。','誤り。AWSが代行購買を行うサービスではありません。','AWSサポートプランの契約更新機能ではありません。','AWS Organizationsのアカウント作成承認機能ではありません。']}},
  {id:'v234', term:'Amazon CloudWatch Application Signals', domain:'tech', source:SOURCES.appSignals, q:{text:'Amazon CloudWatch Application Signalsとは何ですか？', choices:['Java/Python/Node.js/.NETなどのアプリケーションを自動計装し、サービス間の依存関係を示すアプリケーションマップの表示、SLO(サービスレベル目標)の作成・追跡、呼び出し数・可用性・レイテンシー・エラー等のメトリクスとトレースの自動収集を、コードを書いたりダッシュボードを作成したりすることなく行えるCloudWatchのアプリケーション監視機能','実際のエンドユーザーのブラウザ上でのページ読み込み時間やJavaScriptエラーを計測するクライアントサイドのパフォーマンス監視機能','定期的に生成した合成トラフィックでAPIやWebページの可用性を監視する機能','分散トレーシングに特化し、リクエストがサービス間をどのように伝播したかを可視化する機能'], correct:0, why:['正しい。Application Signalsは、アプリケーションを自動計装してサービス間の依存関係を示すアプリケーションマップを表示し、SLOの作成・追跡や各種メトリクス・トレースの自動収集を、コードの記述やダッシュボード作成なしで行えるCloudWatchの機能です。','これはAmazon CloudWatch RUMの説明です。RUMはSLOの作成・追跡機能は持ちません。','これはAmazon CloudWatch Synthetics(合成監視)の説明です。','これはAWS X-Rayの説明です。X-Ray自体にはSLOの作成・追跡やサービスの自動グループ化機能はありません。']}},
  {id:'v235', term:'Amazon EC2 Capacity Blocks for ML', domain:'billing', source:SOURCES.capacityBlocks, q:{text:'Amazon EC2 Capacity Blocks for MLとは何ですか？', choices:['GPUインスタンスを常時オンデマンドで起動し続け、使った分だけ秒単位で課金される通常のオンデマンド購入オプション','GPUやアクセラレータを搭載したEC2インスタンス(またはUltraServer)について、将来の特定の日付から始まる一定期間分の容量をあらかじめ予約できる購入オプションで、機械学習のトレーニングなど短期集中のワークロードに向いており、価格は予約時点の需給状況に応じて変動する','1年または3年の長期利用を前提に、インスタンスファミリーを特定せずコンピューティング使用量にコミットすることで割引を受ける購入オプション','容量確保の保証はなく、需要と供給に応じて価格が変動し、AWS側の都合で中断されることがある低価格の購入オプション'], correct:1, why:['誤り。これは通常のオンデマンドインスタンスの説明です。Capacity Blocksは将来の特定期間をあらかじめ予約する仕組みです。','正しい。Capacity Blocks for MLは、GPU等を搭載したインスタンス(またはUltraServer)について将来の特定日から始まる一定期間の容量を事前予約できる購入オプションで、短期集中の機械学習トレーニング等に向いており、価格は予約時点の需給状況に応じて変動します。','これはSavings Plansの説明です。Capacity Blocksは容量確保が目的であり、コミットメント割引の仕組みとは異なります。','これはスポットインスタンスの説明です。Capacity Blocksは指定した期間の容量確保が保証されます。']}},
  {id:'v236', term:'インスタンスメタデータサービス (IMDS)', domain:'security', source:SOURCES.imdsv2, q:{text:'Amazon EC2の「インスタンスメタデータサービス(IMDS)」とは何ですか？', choices:['アプリケーションの設定値やシークレットを一元管理し、EC2インスタンスから取得できるようにする仕組み','AWSアカウント内で発生したAPIコールの履歴を記録する仕組み','EC2インスタンス自身から、インスタンスID・AMI ID・ネットワーク設定・IAMロールに関連付けられた一時的なセキュリティ認証情報など、そのインスタンス自体に関する情報を、リンクローカルアドレス(169.254.169.254)経由で取得できる仕組みで、AWSの長期的な認証情報をインスタンス内にハードコードせずに済む','インスタンス起動時に一度だけ実行されるスクリプトや設定データ(User Data)を、インスタンスに渡すための仕組み'], correct:2, why:['これはAWS Systems Manager Parameter Storeの説明です。','これはAWS CloudTrailの説明です。','正しい。インスタンスメタデータサービス(IMDS)は、EC2インスタンス自身がインスタンスID・AMI ID・IAMロールの一時的な認証情報などを169.254.169.254経由で取得できる仕組みで、長期的な認証情報をインスタンス内にハードコードする必要をなくします。','これはEC2のUser Dataの説明です。User Dataはインスタンス自身に関する情報の取得とは異なります。']}},
  {id:'v237', term:'Repurchase（リパーチェス）', domain:'concepts', source:SOURCES.migrationStrategies, q:{text:'移行戦略の一つである「Repurchase（リパーチェス）」とは何ですか？', choices:['既存のオンプレミスアプリケーションを、コードをほとんど変更せずにそのままAmazon EC2等に移行する移行戦略','既存のオンプレミスアプリケーションのコアアーキテクチャは変更せず、クラウドに最適化するための一部変更を加えて移行する移行戦略','移行の優先度が低いアプリケーションを、現時点では移行せずそのままオンプレミスに残しておく移行戦略','既存のオンプレミスアプリケーションを、多くの場合SaaS型の別製品に置き換える移行戦略(例: 社内開発のCRMをSalesforceのようなSaaS製品へ切り替える)'], correct:3, why:['これはRehost（リホスト）の説明です。','これはReplatform（リプラットフォーム）の説明です。','これはRetain（リテイン）の説明です。','正しい。Repurchase（リパーチェス）は、既存のアプリケーションを多くの場合SaaS型の別製品に置き換える移行戦略です。']}},
  {id:'v238', term:'AWS User Notifications', domain:'tech', source:SOURCES.userNotifications, q:{text:'AWS User Notificationsとは何ですか？', choices:['AWS管理通知（AWS Healthなどから自動的に生成される通知）と、ユーザーが作成したルールに基づくユーザー設定通知（UCN）の両方を、コンソールの通知センターやメール、モバイルアプリ、チャットなど複数のチャネルでまとめて確認・管理できるサービス','EventBridgeのルールに基づいてイベントをLambda等のターゲットへ配信するイベントバスサービス','サブスクライバーに対してメールやSMS等でメッセージを配信するパブリッシュ/サブスクライブ型のメッセージングサービス','CloudWatchのメトリクスがしきい値を超えた場合に通知を送るアラーム機能'], correct:0, why:['正しい。AWS User Notificationsは、AWS管理通知とユーザー設定通知(UCN)の両方を一か所にまとめ、コンソール通知センター・メール・モバイルアプリ・チャットアプリケーションなど複数のチャネルで受け取れるようにするサービスです。','これはAmazon EventBridgeの説明です。','これはAmazon SNSの説明です。','これはAmazon CloudWatchアラームの説明です。']}},
  {id:'v239', term:'Amazon Comprehend Medical', domain:'tech', source:SOURCES.comprehendMedical, q:{text:'Amazon Comprehend Medicalとは何ですか？', choices:['テキストの感情分析やキーフレーズ抽出など、一般的な自然言語処理を行うサービス','医師の診療メモなどの非構造化された臨床テキストから、病名・薬剤名・用量などの医療情報を抽出し、ICD-10-CMやRxNormなどの医療用語体系にリンクできる、機械学習ベースの自然言語処理サービス','医療従事者の音声を文字起こしする音声認識サービス','医療データをFHIR形式で保存・分析するためのデータレイクサービス'], correct:1, why:['これは汎用的なテキスト分析を行うAmazon Comprehendの説明です。','正しい。Comprehend Medicalは、臨床テキストから医療情報を抽出し、ICD-10-CMやRxNormなどの医療標準コードにリンクできる専用の自然言語処理サービスです。','これはAmazon Transcribe Medicalの説明です。','これはAWS HealthLakeの説明です。']}},
  {id:'v240', term:'AWS WAF Fraud Control ACFP', domain:'security', source:SOURCES.wafAcfp, q:{text:'AWS WAF Fraud Control: Account Creation Fraud Prevention (ACFP)とは何ですか？', choices:['ログインページを標的にした、漏洩済み認証情報を使ったアカウント乗っ取り試行を検知・ブロックする機能','SQLインジェクションやクロスサイトスクリプティングなど、一般的なWebアプリケーションへの攻撃をルールでフィルタリングする機能','新規アカウント登録（サインアップ）ページを標的にした、使い捨てメールアドレスの使用や漏洩済み認証情報の使い回しなど、大量の偽アカウント作成の試行を検知・ブロックする機能','DDoS攻撃からネットワーク層・トランスポート層のリソースを保護する機能'], correct:2, why:['これはAWS WAF Fraud Control: Account Takeover Prevention (ATP)の説明です。','これはAWS WAFの基本的なマネージドルールの説明です。','正しい。ACFPは、サインアップページを標的にした、使い捨てメールアドレスや漏洩済み認証情報の使い回しなどによる大量の偽アカウント作成の試行を検知・ブロックする機能です。','これはAWS Shieldの説明です。']}},
  {id:'v241', term:'AWS Snow Family', domain:'concepts', source:SOURCES.snowFamily, q:{text:'AWS Snow Familyとは何ですか？', choices:['オンプレミスとAWSの間を専用線で接続するネットワークサービス','オンプレミスとAmazon S3の間でファイルをオンライン経由で安全に同期・転送するサービス','オンプレミスとクラウドストレージをハイブリッドに統合するストレージアプライアンス','ネットワーク帯域の制約や接続が不安定な環境において、大量データの物理的な輸送やエッジでのコンピューティング処理を行うための物理デバイス群（Snowcone、Snowball Edge、Snowmobile等）の総称'], correct:3, why:['これはAWS Direct Connectの説明です。','これはAWS DataSyncの説明です。','これはAWS Storage Gatewayの説明です。','正しい。AWS Snow Familyは、ネットワーク帯域の制約や接続が不安定な環境で、大量データの物理輸送やエッジでのコンピューティング処理を行うための物理デバイス群の総称です。']}},
  {id:'v242', term:'AWS HealthOmics', domain:'tech', source:SOURCES.healthomics, q:{text:'AWS HealthOmicsとは何ですか？', choices:['ゲノムデータなどのオミクスデータの保存・解析ワークフロー実行を、WDL/Nextflow/CWL等に対応したマネージド基盤で提供するサービス','医療機関向けの電子カルテ(EHR)システムをクラウド上でホスティングするマネージドサービス','IoTデバイスから収集した工業用センサーデータを分析するためのマネージドサービス','臨床テキストから病名や薬剤名を抽出する自然言語処理(NLP)サービス'], correct:0, why:['正しい。AWS HealthOmicsは、ゲノム・トランスクリプトームなどのオミクスデータについて、WDL・Nextflow・CWLといった業界標準のワークフロー言語に対応したインフラを完全マネージドで提供し、保存(シーケンスストア等)と解析(分析ストア)を統合的に扱えるサービスです。','これは電子カルテシステムの説明であり、AWS HealthOmicsが直接提供するサービスではありません。','これはIoT向けの産業データ分析サービス(例: AWS IoT SiteWise)に近い説明であり、HealthOmicsの説明ではありません。','これはAmazon Comprehend Medicalの説明です。']}},
  {id:'v243', term:'AWS Marketplace Vendor Insights', domain:'security', source:SOURCES.marketplaceVendorInsights, q:{text:'AWS Marketplace Vendor Insightsとは何ですか？', choices:['AWS自身が取得した第三者認証やコンプライアンスレポートをダウンロードできるサービス','AWS Marketplaceで提供されるSaaS製品について、販売者のセキュリティ体制やコンプライアンス状況をダッシュボードで評価できる機能','AWS Marketplaceで購入したソフトウェアのライセンス利用状況を一括管理する機能','AWSリソースの設定変更履歴を記録し、コンプライアンス評価に利用するサービス'], correct:1, why:['これはAWS Artifactの説明です。','正しい。AWS Marketplace Vendor Insightsは、AWS Marketplaceで提供されるSaaS等の製品について、販売者のセキュリティ・コンプライアンス情報を単一のダッシュボードで継続的に評価できるようにする機能です。','これはAWS License Managerに近い説明であり、Vendor Insightsの説明ではありません。','これはAWS Configの説明です。']}},
  {id:'v244', term:'Pilot Light（パイロットライト）', domain:'concepts', source:SOURCES.drStrategies, q:{text:'ディザスタリカバリ(DR)戦略の「パイロットライト(Pilot Light)」とは何ですか？', choices:['復旧リージョンに本番と同規模の環境を常時フル稼働させておき、障害時に即座に切り替える戦略','複数のリージョンで常時アクティブにトラフィックを処理し、フェイルオーバーという概念自体が不要な戦略','データのバックアップのみを別リージョンに保持し、障害時にゼロから環境を構築する戦略','復旧リージョンにコア部分のインフラやデータのレプリカのみを最小構成で常時起動しておき、障害時に残りのリソースをスケールアップして復旧させる戦略'], correct:3, why:['これはマルチサイトアクティブ/アクティブに近い、常時フル稼働の構成の説明であり、パイロットライトではありません。','これはマルチサイトアクティブ/アクティブの説明です。','これはバックアップ&リストアの説明です。','正しい。パイロットライトは、データベースなどコア部分のレプリカのみを復旧リージョンで最小構成で常時起動しておき、障害時に残りのコンポーネントを起動・スケールして復旧させるDR戦略です。']}},
  {id:'v245', term:'Multi-Site Active/Active（マルチサイトアクティブ/アクティブ）', domain:'concepts', source:SOURCES.drStrategies, q:{text:'ディザスタリカバリ(DR)戦略の「マルチサイトアクティブ/アクティブ」とは何ですか？', choices:['復旧リージョンのリソースを普段は停止しておき、障害発生時にのみ起動する戦略','コア部分のレプリカのみを最小構成で常時起動しておく戦略','複数のリージョンで本番ワークロードを同時にアクティブに稼働させ、フェイルオーバーという概念をほぼ不要にする、最もRTOが短く最もコストが高い戦略','バックアップデータのみを別リージョンに保存しておく、最もコストの低い戦略'], correct:2, why:['これはパイロットライトやウォームスタンバイに近い、リソースを縮小・停止しておく戦略の説明であり、マルチサイトアクティブ/アクティブではありません。','これはパイロットライトの説明です。','正しい。マルチサイトアクティブ/アクティブは複数のリージョンで本番ワークロードを同時にアクティブに稼働させる戦略で、障害発生時のフェイルオーバーという概念をほぼ不要にできる一方、4つのDR戦略のうち最もコストが高くなる傾向があります。','これはバックアップ&リストアの説明です。']}},
  {id:'v246', term:'Backup and Restore（バックアップ&リストア）', domain:'concepts', source:SOURCES.drStrategies, q:{text:'ディザスタリカバリ(DR)戦略の「バックアップ&リストア(Backup and Restore)」とは何ですか？', choices:['バックアップデータのみを別リージョンに保存しておき、障害発生時にそのバックアップから環境を一から構築して復元する、4つのDR戦略のうち最もコストが低く、RTO/RPOが最も長くなる戦略','データベースなどコア部分のレプリカのみを最小構成で常時起動しておき、障害時に残りを起動・スケールして復旧する戦略','本番環境の縮小版を別リージョンで常時稼働させ、障害時にスケールアップして切り替える戦略','複数リージョンで本番ワークロードを同時にアクティブに稼働させる戦略'], correct:0, why:['正しい。Backup and Restoreは、バックアップデータのみを別リージョンに保存しておき、障害発生時にそのバックアップから環境を一から構築して復元する戦略で、4つのDR戦略のうち実装が最も簡単でコストも最も低い一方、RTO/RPOは最も長くなります。','これは「Pilot Light」の説明です。','これは「Warm Standby」の説明です。','これは「Multi-Site Active/Active」の説明です。']}},
  {id:'v247', term:'Compute Savings Plans', domain:'billing', source:SOURCES.savingsplansTypes, q:{text:'Savings Plansの種類の一つである「Compute Savings Plans」とは何ですか？', choices:['特定のインスタンスファミリー・リージョンに限定されるが、その分割引率が最も高いSavings Plans','インスタンスファミリー・リージョン・OS・テナンシーを問わず、EC2・Fargate・Lambdaの利用に横断的かつ柔軟に適用できる、最も柔軟なSavings Plans','1年または3年の期間、特定のアベイラビリティーゾーンの容量確保に対してのみ適用される購入オプション','AWSの空きキャパシティを活用する代わりに、AWSの都合で中断される可能性がある購入オプション'], correct:1, why:['これはEC2 Instance Savings Plansの説明です。','正しい。Compute Savings Plansは、インスタンスファミリー・リージョン・OS・テナンシーにかかわらず、EC2・Fargate・Lambdaの利用に横断的に柔軟に適用できる、最も柔軟性の高いSavings Plansです（割引率はEC2 Instance Savings Plansよりやや低くなります）。','これはOn-Demand Capacity Reservationの説明です。','これはスポットインスタンスの説明です。']}},
  {id:'v248', term:'Amazon Comprehend', domain:'tech', source:SOURCES.comprehend, q:{text:'Amazon Comprehendとは何ですか？', choices:['臨床テキストから病名・薬剤名を抽出する医療特化の自然言語処理サービス','テキストを自然な音声に変換する音声合成サービス','機械学習を使い、テキストからエンティティ・キーフレーズ・言語・感情(ポジティブ/ネガティブ等)を自動的に抽出する自然言語処理(NLP)サービス','音声データをテキストに変換する音声認識サービス'], correct:2, why:['これは医療特化版のAmazon Comprehend Medicalの説明です。','これはAmazon Pollyの説明です。','正しい。Amazon Comprehendは、機械学習を用いてテキストからエンティティ・キーフレーズ・使用言語・感情(センチメント)などを自動的に抽出できる、汎用的な自然言語処理(NLP)サービスです。','これはAmazon Transcribeの説明です。']}},
  {id:'v249', term:'VPC Peering', domain:'tech', source:SOURCES.vpcPeering, q:{text:'VPCピアリング(VPC Peering)とは何ですか？', choices:['インターネットを経由せずにVPCとAWSサービスをプライベートに接続する仕組み','複数のVPCをハブ&スポーク型で相互接続し、ルートの集約も行う仕組み','オンプレミスとVPCの間をインターネット経由の暗号化トンネルで接続する仕組み','2つのVPCの間に、ゲートウェイやVPN、専用のハードウェアを使わずにネットワーク接続を確立し、プライベートIPアドレスを使ってトラフィックをルーティングできるようにする仕組みで、接続は1対1であり推移的ではない(Aが推移的な経由でCと通信することはできない)'], correct:3, why:['これはAWS PrivateLinkの説明です。','これはAWS Transit Gatewayの説明です。','これはAWS Site-to-Site VPNの説明です。','正しい。VPCピアリングは、ゲートウェイやVPN、専用のハードウェアを使わずに2つのVPC間にネットワーク接続を確立する仕組みです。接続は1対1の関係であり、推移的ではないため、AとBがピアリングされ、BとCがピアリングされていても、AはBを経由してCと通信することはできません。']}},
  {id:'v250', term:'Amazon DynamoDB Accelerator (DAX)', domain:'tech', source:SOURCES.dax, q:{text:'Amazon DynamoDB Accelerator (DAX)とは何ですか？', choices:['DynamoDBと互換性があり、結果整合性のある読み取りの応答時間を一桁台ミリ秒からマイクロ秒単位まで高速化する、インメモリキャッシュサービス','DynamoDBのテーブルを継続的にバックアップし、過去35日以内の任意の時点の状態に復元できるようにする機能','DynamoDBのテーブルを複数リージョンに複製し、どのリージョンからも読み書きできるようにする機能','DynamoDBの読み取り・書き込みキャパシティユニットをアプリケーションの負荷に応じて自動的に調整する機能'], correct:0, why:['正しい。DAXはDynamoDBと互換性のあるインメモリキャッシュサービスで、結果整合性のある読み取りの応答時間を一桁台ミリ秒からマイクロ秒単位まで高速化します。','これはDynamoDBのポイントインタイムリカバリ(PITR)の説明です。','これはDynamoDBグローバルテーブルの説明です。','これはDynamoDBのオートスケーリングの説明です。']}},
  {id:'v251', term:'EC2 Instance Savings Plans', domain:'billing', source:SOURCES.savingsplansTypes, q:{text:'Savings Plansの種類の一つである「EC2 Instance Savings Plans」とは何ですか？', choices:['インスタンスファミリー・リージョンを問わず、EC2・Fargate・Lambdaの利用に横断的に適用できる、最も柔軟なSavings Plans','特定のリージョンの特定のインスタンスファミリーへの利用をコミットすることでCompute Savings Plansより高い割引率が得られる一方、コミットしたファミリー内であればインスタンスサイズ・OS・テナンシーは自由に変更できるSavings Plans','特定のアベイラビリティーゾーンの容量を1年または3年確保する購入オプション','AWSの空きキャパシティを利用する代わりに、AWSの都合で中断される可能性がある購入オプション'], correct:1, why:['これはCompute Savings Plansの説明です。','正しい。EC2 Instance Savings Plansは、特定のリージョンの特定のインスタンスファミリーへのコミットによりCompute Savings Plansより高い割引率を得られます。コミットしたファミリー内であれば、インスタンスサイズ・OS・テナンシーは自由に変更できます。','これはOn-Demand Capacity Reservationの説明です。','これはスポットインスタンスの説明です。']}},
  {id:'v252', term:'RPO (Recovery Point Objective)', domain:'concepts', source:SOURCES.rtorpo, q:{text:'ディザスタリカバリ(DR)における「RPO(Recovery Point Objective、目標復旧時点)」とは何ですか？', choices:['障害発生からサービスが復旧するまでに許容できる最大の時間を、あらかじめビジネス側が目標値として定義しておく指標','サービス提供者と利用者の間で合意されたサービス品質の水準を定めた契約','障害発生時に許容できるデータ損失の最大範囲を、直前のバックアップ・レプリケーション時点からの経過時間として表した目標値','システムが実際に正常稼働している時間の割合を表す指標'], correct:2, why:['これはRTO(Recovery Time Objective)の説明です。','これはSLA(サービスレベルアグリーメント)の説明です。','正しい。RPOは、障害発生時に許容できるデータ損失の最大範囲を、直前のバックアップ・レプリケーション時点からの経過時間として表した目標値です。','これは可用性(Availability)の説明です。']}},
  {id:'v253', term:'カスタマーマネージドキー (Customer Managed Key)', domain:'security', source:SOURCES.kms, q:{text:'AWS KMSの「カスタマーマネージドキー」と「AWSマネージドキー」の違いとして正しいものはどれですか？', choices:['カスタマーマネージドキーは無効化やスケジュール削除ができないが、AWSマネージドキーは利用者が削除できる','AWSマネージドキーは利用者がキーポリシーを自由に編集できるが、カスタマーマネージドキーはAWSが固定したポリシーしか使えない','カスタマーマネージドキーはAWSアカウント間で共有できないが、AWSマネージドキーはどのアカウントからも直接利用できる','カスタマーマネージドキーは利用者がキーポリシーを管理し、無効化やスケジュール削除、自動ローテーションの有効/無効を選択できるが、AWSマネージドキーはAWSが管理し、利用者が削除することはできない'], correct:3, why:['誤り。実際には逆で、カスタマーマネージドキーは利用者が無効化・削除をスケジュールできますが、AWSマネージドキーは利用者が削除できません。','誤り。キーポリシーを利用者が編集できるのはカスタマーマネージドキーの方です。','誤り。この説明は不正確です。','正しい。カスタマーマネージドキーは利用者がキーポリシーを管理し、無効化・スケジュール削除・自動ローテーションの有効化/無効化を選択できますが、AWSマネージドキーはAWSが管理し、利用者が削除することはできません。']}},
  {id:'v254', term:'AWS CodeDeploy', domain:'tech', source:SOURCES.codedeploy, q:{text:'AWS CodeDeployとは何ですか？', choices:['EC2インスタンス・オンプレミスサーバー・Lambda関数・ECSサービスへのアプリケーションのデプロイを自動化し、ブルー/グリーンデプロイやローリング更新、デプロイ失敗時の自動ロールバックに対応するサービス','アプリケーションのビルドとテストを自動化するサービス','インフラをコードで定義してプロビジョニングするサービス','複数のデプロイステージを順序立てて連携させる継続的デリバリーのパイプライン管理サービス'], correct:0, why:['正しい。AWS CodeDeployは、EC2・オンプレミス・Lambda・ECSへのアプリケーションデプロイを自動化し、ブルー/グリーンデプロイやローリング更新、失敗時の自動ロールバックに対応するサービスです。','誤り。これはAWS CodeBuildの説明です。','誤り。これはAWS CloudFormation(Infrastructure as Code)の説明です。','誤り。これはAWS CodePipelineの説明です。']}},
  {id:'v255', term:'IAMグループ (IAM Group)', domain:'security', source:SOURCES.iam, q:{text:'AWS IAMの「グループ」の特徴として正しいものはどれですか？', choices:['グループ自体がAWSリソースへアクセスするための認証情報(アクセスキー)を直接持ち、プログラムから呼び出すことができる','複数のIAMユーザーをまとめ、グループにアタッチしたポリシーをメンバー全員に適用できる仕組みで、グループ自体はプリンシパル(操作の主体)にはなれない','グループは他のグループを子として含む階層構造(グループの中にグループ)を作ることができる','EC2インスタンスなどのAWSサービスにアタッチして、一時的な認証情報を引き受けさせるために使う'], correct:1, why:['誤り。IAMグループ自体はアクセスキー等の認証情報を持たず、プログラムから直接呼び出すことはできません。','正しい。IAMグループは複数のIAMユーザーをまとめる入れ物で、グループにアタッチしたポリシーはメンバー全員に適用されますが、グループ自体はプリンシパルにはなれません。','誤り。IAMグループはグループを子として含むことはできず、ネスト(入れ子)はサポートされていません。','誤り。これはIAMロールの説明です。']}},
  {id:'v256', term:'AWS Invoicing (AWS請求書発行機能)', domain:'billing', source:SOURCES.invoices, q:{text:'AWS Billing and Cost Managementコンソールの「Invoices(請求書)」機能の役割として正しいものはどれですか？', choices:['AWSサービスの使用量に対して将来の料金を事前に見積もる機能','異常なコストの急増を機械学習で検知する機能','アカウント(または一括支払いの管理アカウント)に対して発行された確定済み・保留中の請求書を、サービスごとの明細や合計金額とともに確認・ダウンロードできる機能','複数のAWSアカウントの請求を1つにまとめる一括支払い(Consolidated Billing)を有効化する機能'], correct:2, why:['誤り。これはAWS Pricing Calculatorの役割です。','誤り。これはAWS Cost Anomaly Detectionの役割です。','正しい。Invoices機能では、アカウント(または一括支払いの管理アカウント)に発行された確定済み・保留中の請求書を、サービスごとの明細とともに確認・ダウンロードできます。','誤り。これはAWS Organizationsの一括支払い設定の役割です。']}},
  {id:'v257', term:'Stop Guessing Capacity（キャパシティの推測が不要）', domain:'concepts', source:SOURCES.sixAdv, q:{text:'クラウドコンピューティングの6つのメリットの一つ「Stop Guessing Capacity(キャパシティの推測が不要)」とは何ですか？', choices:['将来の利用量を正確に予測するための専門チームを社内に設置すること','常に最大想定のキャパシティを事前に購入しておくことで、性能不足を未然に防ぐこと','データセンターの建設計画を数年前から立てておくこと','必要なキャパシティを事前に過不足なく予測する必要がなくなり、必要に応じて必要な分だけリソースを調達・解放できること'], correct:3, why:['誤り。クラウドの利点は予測の精度を上げることではなく、予測自体が不要になることです。','誤り。これは従来のオンプレミスで過剰プロビジョニングを行う考え方であり、クラウドの利点とは逆です。','誤り。これはオンプレミスのデータセンター建設計画の説明であり、クラウドではこの種の長期計画が不要になります。','正しい。Stop Guessing Capacityは、必要なキャパシティを事前に正確に予測する必要がなくなり、需要に応じて必要な分だけリソースを調達・解放できるという、クラウドコンピューティングのメリットです。']}}
];

var PRACTICE = [
  {id:'p1', domain:'concepts', type:'single', source:SOURCES.waf, text:'オンデマンドで必要な分だけコンピューティングリソースを増減できるクラウドの特性を何と呼びますか？',
    choices:['弾力性（Elasticity）','耐久性（Durability）','冗長性（Redundancy）','一貫性（Consistency）'], correct:[0],
    why:['正しい。弾力性（Elasticity）は、需要に応じてリソースを自動的に増減できる特性です。','耐久性（Durability）はデータが失われない性質を指す概念で、リソースの増減とは異なります。','冗長性（Redundancy）は障害対策のための複製を指す概念で、リソースの増減とは異なります。','一貫性（Consistency）はデータの整合性を指す概念で、リソースの増減とは異なります。']},
  {id:'p2', domain:'billing', type:'multi', source:SOURCES.sixAdv, text:'AWSクラウドを利用する経済的メリットとして正しいものを2つ選択してください。',
    choices:['常に無料で利用できる','初期投資（資本費用）が不要になる','ハードウェアの調達・保守が不要になる','すべてのリージョンで同一価格になる'], correct:[1,2],
    why:['誤り。クラウド利用には基本的に料金が発生します。','正しい。クラウドでは先行投資（資本費用）が不要になります。','正しい。物理ハードウェアの調達・保守が不要になります。','誤り。価格はリージョンによって異なります。']},
  {id:'p3', domain:'security', type:'single', source:SOURCES.shared, text:'責任共有モデルにおいて、利用者（ユーザー）側の責任範囲に該当するものはどれですか？',
    choices:['データセンターの物理セキュリティ','ネットワークインフラの物理層','データの暗号化とアクセス管理','ハードウェアの保守'], correct:[2],
    why:['誤り。データセンターの物理セキュリティはAWS側の責任範囲です。','誤り。ネットワークインフラの物理層はAWS側の責任範囲です。','正しい。データの暗号化やアクセス管理はユーザー側（クラウド内）の責任範囲です。','誤り。ハードウェアの保守はAWS側の責任範囲です。']},
  {id:'p4', domain:'tech', type:'single', source:SOURCES.wafReliability, text:'複数のアベイラビリティーゾーンにリソースを分散させる主な目的は何ですか？',
    choices:['レイテンシーを完全にゼロにするため','セキュリティ設定を簡略化するため','コストを削減するため','可用性と耐障害性を高めるため'], correct:[3],
    why:['誤り。レイテンシーを完全になくすことはできません。','誤り。セキュリティ設定の簡略化が目的ではありません。','誤り。主な目的はコスト削減ではなく、可用性・耐障害性の向上です。','正しい。複数AZへの分散は、一つの施設で障害が発生しても他で稼働を継続できるようにするためです。']},
  {id:'p5', domain:'billing', type:'multi', source:SOURCES.organizations, text:'AWS Organizationsを使うメリットとして正しいものを2つ選択してください。',
    choices:['一括請求（コンソリデーティッドビリング）が可能になる','すべてのサービスが無料になる','複数アカウントを一括管理できる','自動でアプリをデプロイできる'], correct:[0,2],
    why:['正しい。コンソリデーティッドビリングにより請求を一括管理できます。','誤り。AWS Organizations自体が利用を無料にする機能ではありません。','正しい。AWS Organizationsで複数アカウントを一括管理できます。','誤り。自動デプロイはAWS Organizationsの機能ではありません。']},
  {id:'p6', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'AWSの「マネージドサービス」の特徴として正しいものはどれですか？',
    choices:['利用者がすべてのサーバー管理を自分で行う必要がある','AWSがインフラの運用・保守を担当し、利用者は設定・利用に集中できる','常に無料で提供される','オンプレミスでのみ利用可能である'], correct:[1],
    why:['誤り。マネージドサービスの特徴は、利用者がサーバー管理を自分で行う必要がない点です。','正しい。マネージドサービスはAWSが運用・保守を担い、利用者は設定・利用に集中できます。','誤り。多くのマネージドサービスは利用に応じて料金が発生します。','誤り。クラウド上のサービスであり、オンプレミス限定ではありません。']},

  // --- クラウドのコンセプト ---
  {id:'p7', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'オンプレミスのデータセンターからAWSクラウドへ移行する経済的メリットとして、最も適切なものはどれですか？',
    choices:['データセンターの建設費用が別途必要になる','年間契約でのみ利用可能になる','大規模な先行投資（資本費用）を、使用量に応じた費用（運用費用）に変えられる','すべてのAWSサービスが完全に無料になる'], correct:[2],
    why:['誤り。クラウド移行により自前のデータセンター建設は不要になります。','誤り。年間契約以外にオンデマンドなど多様な利用形態があります。','正しい。クラウドでは先行投資を行わず、使用した分だけ支払う運用費用型のモデルに変えられます。','誤り。AWSサービスの利用には基本的に料金が発生します。']},
  {id:'p8', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'AWSのような大規模クラウド事業者を利用することで、個々の企業が得られるメリットとして正しいものはどれですか？',
    choices:['契約したリージョン以外は利用できなくなる','セキュリティ対策が一切不要になる','自社サーバーより必ず性能が低くなる','多数の利用を集約することによる規模の経済で、より低い従量課金価格を享受できる'], correct:[3],
    why:['誤り。複数リージョンを利用することも可能です。','誤り。責任共有モデルにより、利用者側のセキュリティ対策は依然として必要です。','誤り。性能が必ず低くなるという事実はありません。','正しい。多数の顧客の利用を集約することで、AWSは規模の経済を実現し、低価格を提供できます。']},
  {id:'p9', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'キャンペーン時にアクセスが急増するWebサイトで、事前に必要なサーバー数を正確に予測する必要がなくなる理由として最も適切なものはどれですか？',
    choices:['Auto Scalingなどにより需要に応じてリソースを自動的に増減できるため','AWSが無料でリソースを提供するため','契約時に将来のアクセス数が保証されるため','すべてのリクエストをキャッシュできるため'], correct:[0],
    why:['正しい。弾力性のあるリソース（例: Auto Scaling）により、需要予測を厳密に行わなくても自動的に対応できます。','誤り。リソースの利用には料金が発生します。','誤り。将来のアクセス数が保証される契約ではありません。','誤り。キャッシュはアクセス増への一つの対策ですが、容量予測が不要になる主因ではありません。']},
  {id:'p10', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'新しいリージョンにアプリケーションを展開し、短期間で海外のユーザーにサービス提供を開始できるというクラウドのメリットを何と呼びますか？',
    choices:['責任共有モデル','数分でグローバル展開できること（Go Global in Minutes）','耐久性（Durability）','AWS Organizationsによるアカウント統合'], correct:[1],
    why:['誤り。責任共有モデルはセキュリティ責任の分担に関する概念です。','正しい。AWSのグローバルインフラを利用することで、数クリックで新しいリージョンにアプリケーションを展開できます。','誤り。耐久性はデータが失われない性質を指し、展開速度とは異なります。','誤り。これはAWS Organizationsの機能に関する説明で、展開速度とは異なります。']},
  {id:'p11', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'クラウドを利用することで新しいITリソースを「数分で」調達できるようになり、それが開発チームにもたらす主なメリットは何ですか？',
    choices:['セキュリティ設定が自動的に不要になる','ハードウェアの保守作業が増える','アイデアの実験や新機能の試行にかかる時間とコストを削減できる','すべての開発コストが無料になる'], correct:[2],
    why:['誤り。セキュリティ設定は責任共有モデルの下で依然として必要です。','誤り。クラウドでは物理ハードウェアの保守は基本的に不要になります。','正しい。必要なリソースを即座に調達できることで、試行にかかる時間とコストを削減し、スピードと俊敏性（アジリティ）が向上します。','誤り。開発コストが無料になるわけではありません。']},
  {id:'p12', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'クラウドを利用することで企業が「データセンターの運用・保守」から解放されるメリットとして正しい説明はどれですか？',
    choices:['すべての既存システムを即座に廃止できる','運用保守コストが完全にゼロになることが保証される','データセンターが不要になり、インターネット接続も不要になる','電源・冷却・物理警備などの運用保守をAWSに任せ、自社はアプリケーション開発に集中できる'], correct:[3],
    why:['誤り。既存システムの廃止は移行計画次第であり、即座に行われるわけではありません。','誤り。コストがゼロになる保証はなく、使用量に応じた費用は発生します。','誤り。インターネット接続はクラウド利用に必要です。','正しい。データセンターの運用・保守をAWSに任せることで、自社はアプリケーション開発など差別化につながる業務に集中できます。']},
  {id:'p13', domain:'concepts', type:'single', source:SOURCES.wafCost, text:'AWS Well-Architected Frameworkの「コスト最適化の柱」が重視する内容として正しいものはどれですか？',
    choices:['不要なコストを排除し、支出に対して最大の価値を得ること','すべての通信を暗号化すること','リソースをすべて無料利用枠内で運用すること','システムが障害から復旧する速さ'], correct:[0],
    why:['正しい。コスト最適化の柱は、不要な支出を排除し投資対効果を最大化することに重点を置きます。','これはセキュリティの柱に関する内容です。','誤り。無料利用枠の活用は一手段ですが、柱の定義そのものではありません。','これは信頼性の柱に関する内容です。']},
  {id:'p14', domain:'concepts', type:'multi', source:SOURCES.wafReliability, text:'AWS Well-Architected Frameworkの「信頼性の柱」の観点から、障害発生時にもサービスを継続させるための設計として適切なものを2つ選択してください。',
    choices:['単一のAZにすべてのリソースを集約する','複数のアベイラビリティーゾーンにリソースを分散させる','定期的にバックアップを取得し復旧手順を整備する','パスワードを全ユーザーで共有する'], correct:[1,2],
    why:['誤り。単一AZへの集約は単一障害点を生み、信頼性を低下させます。','正しい。複数AZへの分散は、単一施設の障害がサービス全体に影響しないようにする基本的な設計です。','正しい。定期的なバックアップと復旧手順の整備は、障害からの復旧力を高めます。','誤り。パスワード共有はセキュリティ上のベストプラクティスに反し、信頼性とも無関係です。']},
  {id:'p15', domain:'concepts', type:'single', source:SOURCES.hybridCloud, text:'一部のワークロードをオンプレミスに残しつつ、他のワークロードをAWSクラウドで運用する構成を何と呼びますか？',
    choices:['プライベートクラウド単独構成','マルチアカウント構成','ハイブリッドクラウド','パブリッククラウド単独構成'], correct:[2],
    why:['誤り。プライベートクラウド単独構成はパブリッククラウドを併用しません。','誤り。マルチアカウント構成はAWSアカウントの分割管理を指し、オンプレミスとの併用とは別の概念です。','正しい。ハイブリッドクラウドは、オンプレミスの既存インフラとクラウドのリソース・サービスを統合して運用する構成です。','誤り。パブリッククラウド単独構成はオンプレミス資産を併用しません。']},
  {id:'p16', domain:'concepts', type:'single', source:SOURCES.wafReliability, text:'システムの一部のコンポーネントが停止しても、他のコンポーネントへの影響を最小限にする設計を何と呼びますか？',
    choices:['単一障害点（Single Point of Failure）','ルートユーザーの共有','密結合（Tight Coupling）','疎結合（Loose Coupling）'], correct:[3],
    why:['誤り。単一障害点はむしろ避けるべき設計上の弱点です。','誤り。ルートユーザーの共有はセキュリティ上のアンチパターンであり、設計原則とは無関係です。','誤り。密結合はコンポーネント間の依存が強く、一部の障害が他へ波及しやすくなります。','正しい。疎結合は、コンポーネント間の依存を減らし（例: キューを介した非同期連携）、一部の障害が全体に波及しにくくする設計です。']},

  // --- セキュリティとコンプライアンス ---
  {id:'p17', domain:'security', type:'single', source:SOURCES.shared, text:'責任共有モデルにおいて、Amazon EC2インスタンスのゲストOSへのセキュリティパッチ適用は誰の責任ですか？',
    choices:['利用者（お客様）の責任','AWSサポートが自動的に対応するため責任は発生しない','ゲストOSへのパッチ適用という概念自体が存在しない','AWSの責任'], correct:[0],
    why:['正しい。EC2はIaaS型のサービスであり、ゲストOS以上の管理（パッチ適用等）は「クラウド内のセキュリティ」として利用者の責任です。','誤り。自動的に対応されるわけではなく、利用者が対応する必要があります。','誤り。ゲストOSのパッチ適用は実際に必要な作業です。','誤り。AWSの責任範囲は物理インフラやホスト側の管理までです。']},
  {id:'p18', domain:'security', type:'multi', source:SOURCES.shared, text:'責任共有モデルにおいて、AWS側の責任に該当するものを2つ選択してください。',
    choices:['ゲストOSへのパッチ適用','ハードウェアインフラストラクチャの保守','アプリケーションレベルのアクセス管理','データセンターの物理的セキュリティ'], correct:[1,3],
    why:['誤り。ゲストOSへのパッチ適用は利用者の責任範囲です。','正しい。ハードウェアインフラの保守もAWSの責任範囲です。','誤り。アプリケーションレベルのアクセス管理は利用者の責任範囲です。','正しい。データセンターの物理的セキュリティは「クラウドのセキュリティ」としてAWSの責任範囲です。']},
  {id:'p19', domain:'security', type:'single', source:SOURCES.iam, text:'AWSアカウントのセキュリティを強化するために、ルートユーザーに対して最初に行うべき対策として最も適切なものはどれですか？',
    choices:['ルートユーザーのパスワードをチームで共有する','ルートユーザーを日常的な管理業務に使用する','多要素認証（MFA）を有効化し、日常作業はIAMユーザーで行う','ルートユーザーのアクセスキーを作成し全メンバーに配布する'], correct:[2],
    why:['誤り。パスワードの共有はセキュリティリスクを大幅に高めます。','誤り。ルートユーザーの日常利用は推奨されていません。','正しい。ルートユーザーにはMFAを有効化し、日常作業は権限を絞ったIAMユーザーで行うことが推奨されるベストプラクティスです。','誤り。ルートユーザーのアクセスキー配布は極めて危険であり、推奨されません。']},
  {id:'p20', domain:'security', type:'single', source:SOURCES.iam, text:'IAMポリシーを設計する際の「最小権限の原則」として正しい考え方はどれですか？',
    choices:['ルートユーザーの権限を全員に共有する','パスワードを設定しない','すべてのユーザーに管理者権限（AdministratorAccess）を付与する','各ユーザーやロールには、業務上必要な最小限の権限だけを付与する'], correct:[3],
    why:['誤り。ルートユーザー権限の共有は重大なセキュリティリスクです。','誤り。パスワード設定自体は最小権限とは無関係で、認証の基本対策として必要です。','誤り。全員に管理者権限を付与することは最小権限の原則に反します。','正しい。最小権限の原則は、各ユーザー・ロールに業務上必要な最小限の権限だけを付与する考え方です。']},
  {id:'p21', domain:'security', type:'single', source:SOURCES.iam, text:'長期的な認証情報（アクセスキー）を持たず、EC2インスタンスなどのAWSリソースに一時的に権限を付与する仕組みとして最も適切なものはどれですか？',
    choices:['IAMロール','IAMユーザー','ルートユーザー','IAMグループ'], correct:[0],
    why:['正しい。IAMロールは一時的な認証情報を発行し、EC2インスタンス等のリソースやサービスに権限を引き受けさせる仕組みです。','誤り。IAMユーザーは通常、長期的な認証情報（パスワードやアクセスキー）を持つ個人や用途に紐づく識別子です。','誤り。ルートユーザーはアカウント全体の最高権限を持つ特権アカウントであり、一時的な権限付与の仕組みではありません。','誤り。IAMグループは複数のIAMユーザーをまとめてポリシーを適用する単位であり、ロールとは異なります。']},
  {id:'p22', domain:'security', type:'single', source:SOURCES.kms, text:'Amazon S3に保存されたデータを「保管時（at rest）」に暗号化する方法として適切なものはどれですか？',
    choices:['IAMポリシーでアクセスを制限する','AWS KMSのキーを使ったサーバーサイド暗号化を有効にする','HTTPS通信のみを使用する','セキュリティグループで通信を制限する'], correct:[1],
    why:['誤り。IAMポリシーはアクセス制御であり、データの暗号化そのものではありません。','正しい。保管時の暗号化（暗号化 at rest）は、KMS等の鍵を用いたサーバーサイド暗号化によって実現します。','誤り。HTTPSは通信経路上の暗号化（in transit）であり、保管時の暗号化とは異なります。','誤り。セキュリティグループは通信の許可制御であり、暗号化機能ではありません。']},
  {id:'p23', domain:'security', type:'single', source:SOURCES.shield, text:'大量のリクエストでサーバーのネットワーク帯域を飽和させようとするDDoS攻撃から保護するために、最も適したサービスはどれですか？',
    choices:['Amazon GuardDuty','AWS WAF','AWS Shield','AWS KMS'], correct:[2],
    why:['誤り。GuardDutyは脅威を検知する監視サービスで、DDoS攻撃を直接ブロックする機能ではありません。','誤り。AWS WAFは主にアプリケーション層（HTTP/HTTPS）の攻撃をフィルタリングするサービスで、DDoS対策が主目的ではありません。','正しい。AWS ShieldはDDoS攻撃からネットワーク層・トランスポート層を含めて保護する専用サービスです。','誤り。KMSは暗号鍵管理サービスであり、DDoS対策とは無関係です。']},
  {id:'p24', domain:'security', type:'single', source:SOURCES.guardduty, text:'AWS環境内でアカウントの異常なAPIコールや不審な通信を機械学習で検知したい場合、最も適したサービスはどれですか？',
    choices:['AWS Organizations','AWS Secrets Manager','AWS Artifact','Amazon GuardDuty'], correct:[3],
    why:['誤り。Organizationsは複数アカウント管理サービスであり、脅威検知機能はありません。','誤り。Secrets Managerはシークレット管理サービスであり、脅威検知機能はありません。','誤り。AWS Artifactはコンプライアンスレポートの取得サービスであり、脅威検知機能はありません。','正しい。GuardDutyはCloudTrailやVPCフローログ等を機械学習で分析し、不審な挙動を継続的に検知する脅威検出サービスです。']},
  {id:'p25', domain:'security', type:'single', source:SOURCES.vpc, text:'サブネットレベルで動作し、許可ルールと拒否ルールの両方を設定できるステートレスなファイアウォールは何ですか？',
    choices:['ネットワークACL（NACL）','セキュリティグループ','AWS Shield','AWS WAF'], correct:[0],
    why:['正しい。ネットワークACLはサブネット単位で動作し、許可・拒否の両方のルールをステートレスに評価します。','誤り。セキュリティグループはインスタンス単位でステートフルに動作し、許可ルールのみを設定できます。','誤り。AWS ShieldはDDoS対策サービスであり、ファイアウォールではありません。','誤り。AWS WAFはアプリケーション層の攻撃をフィルタリングするサービスで、NACLとは異なるレイヤーで動作します。']},
  {id:'p26', domain:'security', type:'single', source:SOURCES.organizations, text:'複数のAWSアカウントに対して、組織全体で許可できる操作の範囲に上限を設ける（ガードレールを設定する）仕組みは何ですか？',
    choices:['AWS Budgetsのアラート','AWS Organizationsのサービスコントロールポリシー（SCP）','IAMユーザーのパスワードポリシー','セキュリティグループ'], correct:[1],
    why:['誤り。Budgetsのアラートはコスト通知の仕組みであり、操作範囲の制限機能ではありません。','正しい。SCPはAWS Organizations内のアカウントに対し、許可できる操作範囲の上限（ガードレール）を組織全体で設定する仕組みです。','誤り。パスワードポリシーは個々のIAMユーザーの認証情報要件を定めるものであり、組織全体の操作範囲の制御ではありません。','誤り。セキュリティグループはネットワーク通信の許可制御であり、組織のガバナンスとは異なります。']},

  // --- クラウドテクノロジーとサービス ---
  {id:'p27', domain:'tech', type:'single', source:SOURCES.lambda, text:'画像がS3にアップロードされた際に、サムネイルを自動生成する小さな処理を、サーバーを管理せずに実行したい場合、最も適したサービスはどれですか？',
    choices:['Amazon EC2','Amazon RDS','AWS Lambda','AWS Direct Connect'], correct:[2],
    why:['誤り。EC2は仮想サーバーであり、OSやスケーリングの管理が必要です。','誤り。RDSはリレーショナルデータベースサービスであり、イベント処理の実行基盤ではありません。','正しい。LambdaはS3イベントなどをトリガーに、サーバー管理なしでコードを実行できるサーバーレスコンピューティングサービスです。','誤り。Direct Connectはネットワーク接続サービスであり、コード実行とは無関係です。']},
  {id:'p28', domain:'tech', type:'single', source:SOURCES.ebs, text:'EC2インスタンスのOS（ルートボリューム）として使用する、インスタンスにアタッチするストレージに最も適したサービスはどれですか？',
    choices:['Amazon Route 53','Amazon S3','Amazon EFS','Amazon EBS'], correct:[3],
    why:['誤り。Route 53はDNSサービスであり、ストレージではありません。','誤り。S3はオブジェクトストレージであり、OSのルートボリュームとして直接マウントすることはできません。','誤り。EFSは複数インスタンスで共有するファイルストレージであり、ルートボリューム用途には使用しません。','正しい。EBSはEC2インスタンスにアタッチするブロックストレージで、OSのルートボリュームとして利用されます。']},
  {id:'p29', domain:'tech', type:'single', source:SOURCES.efs, text:'複数のEC2インスタンスから同時にアクセス・共有できるファイルストレージが必要な場合、最も適したサービスはどれですか？',
    choices:['Amazon EFS','AWS Direct Connect','Amazon EBS','Amazon S3 Glacier'], correct:[0],
    why:['正しい。EFSは複数のEC2インスタンスから同時にマウントして共有できるNFSベースのファイルストレージです。','誤り。Direct Connectはネットワーク接続サービスであり、ストレージではありません。','誤り。EBSは基本的に単一インスタンスにアタッチするブロックストレージです。','誤り。S3 Glacierは長期アーカイブ向けのオブジェクトストレージで、ファイル共有用途ではありません。']},
  {id:'p30', domain:'tech', type:'single', source:SOURCES.rds, text:'複雑なJOINを伴うトランザクション処理が必要な業務システムのデータベースとして、最も適したサービスはどれですか？',
    choices:['Amazon S3','Amazon RDS','Amazon DynamoDB','Amazon CloudFront'], correct:[1],
    why:['誤り。S3はオブジェクトストレージであり、データベースではありません。','正しい。RDSはSQLによる複雑なJOINやトランザクション処理に対応したリレーショナルデータベースのマネージドサービスです。','誤り。DynamoDBはキーバリュー/ドキュメント型のNoSQLデータベースで、複雑なJOINには不向きです。','誤り。CloudFrontはCDNサービスであり、データベースではありません。']},
  {id:'p31', domain:'tech', type:'single', source:SOURCES.dynamodb, text:'数百万件規模のアクセスに対して単一桁ミリ秒のレイテンシーが求められる、キーバリュー形式のデータを扱うアプリケーションに最も適したサービスはどれですか？',
    choices:['Amazon EBS','AWS CloudFormation','Amazon DynamoDB','Amazon RDS'], correct:[2],
    why:['誤り。EBSはブロックストレージであり、データベースサービスではありません。','誤り。CloudFormationはInfrastructure as Codeのサービスであり、データベースではありません。','正しい。DynamoDBはサーバーレスでスケーラブルなNoSQLデータベースで、大規模アクセスでも単一桁ミリ秒の応答を実現します。','誤り。RDSはリレーショナルデータベースであり、超大規模なキーバリューアクセスにはDynamoDBの方が適しています。']},
  {id:'p32', domain:'tech', type:'single', source:SOURCES.route53, text:'独自ドメインの名前解決（DNS）を行い、さらに地理的位置に応じたルーティングも設定できるサービスはどれですか？',
    choices:['Amazon CloudFront','AWS Direct Connect','Amazon VPC','Amazon Route 53'], correct:[3],
    why:['誤り。CloudFrontはCDNサービスであり、DNSのルーティングポリシー設定機能そのものではありません。','誤り。Direct Connectは専用線接続サービスであり、DNSとは無関係です。','誤り。VPCはネットワーク分離サービスであり、DNSルーティングポリシーの主目的ではありません。','正しい。Route 53はDNSサービスであり、レイテンシーベースや地理的位置に基づくルーティングポリシーを設定できます。']},
  {id:'p33', domain:'tech', type:'single', source:SOURCES.directconnect, text:'オンプレミスのデータセンターとAWS間で、安定した帯域と低レイテンシーを得るために、公共のインターネットを経由しない専用線接続を構築したい場合、最も適したサービスはどれですか？',
    choices:['AWS Direct Connect','AWS Site-to-Site VPN','Amazon CloudFront','Amazon Route 53'], correct:[0],
    why:['正しい。Direct Connectは専用線を用いてオンプレミスとAWSを接続し、安定した帯域と低レイテンシーを実現します。','誤り。Site-to-Site VPNは公共のインターネットを経由して暗号化通信を行う接続方式であり、専用線ではありません。','誤り。CloudFrontはCDNサービスであり、専用線接続とは無関係です。','誤り。Route 53はDNSサービスであり、専用線接続とは無関係です。']},
  {id:'p34', domain:'tech', type:'multi', source:SOURCES.autoscaling, text:'アクセス量が時間帯によって大きく変動するWebアプリケーションで、可用性とコスト効率を両立する構成として適切なものを2つ選択してください。',
    choices:['Elastic Load Balancingで複数インスタンスにトラフィックを分散する','すべてのトラフィックを1台のインスタンスに集約する','インスタンスのサイズと台数を永久に固定する','Auto Scalingで需要に応じてインスタンス数を自動調整する'], correct:[0,3],
    why:['正しい。ELBで複数インスタンスにトラフィックを分散することで、可用性と負荷分散を両立できます。','誤り。1台への集約は単一障害点を生み、可用性を損ないます。','誤り。固定構成では需要変動に対応できず、コストや可用性の面で非効率です。','正しい。Auto Scalingにより需要に応じてインスタンス数を調整し、コスト効率と可用性を両立できます。']},
  {id:'p35', domain:'tech', type:'single', source:SOURCES.cloudtrail, text:'「どのIAMユーザーが、いつ、どのAPIを呼び出したか」を調査するために確認すべきサービスはどれですか？',
    choices:['AWS Config','Amazon GuardDuty','AWS CloudTrail','Amazon CloudWatch'], correct:[2],
    why:['誤り。AWS Configはリソースの構成変更履歴やコンプライアンス評価が主目的で、API呼び出し履歴そのものを調査する一次ツールではありません。','誤り。GuardDutyは脅威検知サービスであり、通常のAPI呼び出し履歴の網羅的な調査用ではありません。','正しい。CloudTrailはアカウント内のAPIコール履歴を記録し、誰がいつ何を実行したかを確認できる監査用サービスです。','誤り。CloudWatchは運用メトリクスやログの監視が主目的で、API呼び出し履歴の監査が主目的ではありません。']},
  {id:'p36', domain:'tech', type:'single', source:SOURCES.cloudformation, text:'同じ構成のインフラ環境を、コードのテンプレートから繰り返し再現可能な形で構築したい場合、最も適したサービスはどれですか？',
    choices:['Amazon Route 53','AWS Direct Connect','Amazon CloudWatch','AWS CloudFormation'], correct:[3],
    why:['誤り。Route 53はDNSサービスであり、インフラ構築のテンプレート化とは無関係です。','誤り。Direct Connectは専用線接続サービスであり、インフラ構築のテンプレート化とは無関係です。','誤り。CloudWatchは監視サービスであり、リソースのプロビジョニング機能ではありません。','正しい。CloudFormationはテンプレートに定義した構成をもとに、AWSリソースを再現可能な形でプロビジョニングできるIaCサービスです。']},
  {id:'p37', domain:'tech', type:'single', source:SOURCES.rekognition, text:'機械学習の専門知識がなくても、画像内の物体やテキストを検出・分析したい場合に最も適したサービスはどれですか？',
    choices:['Amazon Rekognition','AWS Lambda','Amazon SageMaker','Amazon DynamoDB'], correct:[0],
    why:['正しい。Rekognitionは事前学習済みのモデルを使い、専門知識なしで画像・動画の物体検出やテキスト検出ができるサービスです。','誤り。Lambdaはサーバーレスの実行基盤であり、画像解析のモデル自体は提供しません。','誤り。SageMakerは自分でモデルを構築・学習・デプロイするためのサービスで、専門知識や作業負担が大きくなります。','誤り。DynamoDBはNoSQLデータベースであり、画像解析機能はありません。']},
  {id:'p38', domain:'tech', type:'multi', source:SOURCES.globalInfra, text:'新しい顧客向けにAWSリソースをデプロイするリージョンを選ぶ際に考慮すべき要素として適切なものを2つ選択してください。',
    choices:['リージョン名のアルファベット順','ユーザーとの地理的な近さによる通信レイテンシー','データの保存場所に関する法令・コンプライアンス要件','そのリージョンにおけるAWSの資本金'], correct:[1,2],
    why:['誤り。リージョン名のアルファベット順は技術的・業務的な判断基準ではありません。','正しい。ユーザーに近いリージョンを選ぶことで通信レイテンシーを低減できます。','正しい。データの保存場所に関する法令・コンプライアンス要件は、リージョン選定の重要な判断基準です。','誤り。AWSの資本金はリージョン選定の判断基準ではありません。']},
  {id:'p39', domain:'tech', type:'single', source:SOURCES.fargate, text:'Dockerコンテナを実行する際に、基盤となるサーバー（EC2インスタンス）のプロビジョニングや管理を行わずに済むサービスはどれですか？',
    choices:['Amazon EBS','Amazon Route 53','AWS Fargate','AWS Direct Connect'], correct:[2],
    why:['誤り。EBSはブロックストレージサービスであり、コンテナ実行基盤ではありません。','誤り。Route 53はDNSサービスであり、コンテナ実行とは無関係です。','正しい。Fargateはコンテナ向けのサーバーレスコンピューティングエンジンで、EC2インスタンスの管理なしでコンテナを実行できます。','誤り。Direct Connectはネットワーク接続サービスであり、コンテナ実行とは無関係です。']},

  // --- 請求、課金、サポート ---
  {id:'p40', domain:'billing', type:'multi', source:SOURCES.organizations, text:'AWS Organizationsでコンソリデーティッドビリングを利用する主なメリットを2つ選択してください。',
    choices:['組織内の全アカウントの請求を1つにまとめて管理できる','IAMユーザーのパスワードが自動生成される','すべてのサービスが無料になる','すべてのメンバーアカウントの使用量を集約し、ボリュームディスカウントを受けやすくなる'], correct:[0,3],
    why:['正しい。複数アカウントの請求を1つの支払いにまとめて管理できます。','誤り。パスワードの自動生成はコンソリデーティッドビリングの機能ではありません。','誤り。無料になるわけではなく、料金体系が有利になる場合があるという話です。','正しい。使用量を集約することで、ボリュームディスカウント等の料金メリットを受けやすくなります。']},
  {id:'p41', domain:'billing', type:'single', source:SOURCES.costmgmt, text:'月間のAWS利用コストが予算の80%に達した時点で担当者にメール通知を送りたい場合、最も適したサービスはどれですか？',
    choices:['AWS Budgets','AWS Cost Explorer','AWS Trusted Advisor','AWS Organizations'], correct:[0],
    why:['正しい。AWS Budgetsは予算に対する閾値を設定し、超過や超過予測時にアラートを送信できます。','誤り。Cost Explorerは過去のコスト分析・将来予測が主目的で、閾値通知の主目的のツールではありません。','誤り。Trusted Advisorはベストプラクティスの推奨事項を提示するサービスで、予算アラートの主目的のツールではありません。','誤り。Organizationsは複数アカウント管理サービスであり、予算アラート機能ではありません。']},
  {id:'p42', domain:'billing', type:'single', source:SOURCES.costmgmt, text:'過去6ヶ月のコスト傾向を分析し、今後のコストを予測したい場合、最も適したサービスはどれですか？',
    choices:['AWS Budgets','AWS Cost Explorer','Amazon GuardDuty','AWS Artifact'], correct:[1],
    why:['誤り。Budgetsは予算に対するアラート機能が主目的で、傾向分析・予測の主目的のツールではありません。','正しい。Cost Explorerは過去のコスト・使用量を可視化し、将来のコストを予測する機能を持ちます。','誤り。GuardDutyは脅威検知サービスであり、コスト分析機能はありません。','誤り。Artifactはコンプライアンスレポートの取得サービスであり、コスト分析機能はありません。']},
  {id:'p43', domain:'billing', type:'single', source:SOURCES.costmgmt, text:'数時間だけ使い捨てで実行する、中断されても問題のないバッチ処理のコストを最小化したい場合、最も適した購入オプションはどれですか？',
    choices:['オンデマンドインスタンス','リザーブドインスタンス','スポットインスタンス','Savings Plans'], correct:[2],
    why:['誤り。オンデマンドインスタンスは割引がなく、スポットインスタンスよりコストが高くなります。','誤り。リザーブドインスタンスは1年・3年の長期利用を前提とした契約であり、短時間の使い捨て処理には不向きです。','正しい。中断が許容できる短時間の処理には、大幅な割引が得られるスポットインスタンスが最もコスト効率が良い選択です。','誤り。Savings Plansも長期的な使用量の契約を前提としており、短時間の使い捨て処理には不向きです。']},
  {id:'p44', domain:'billing', type:'single', source:SOURCES.costmgmt, text:'向こう3年間、常時稼働させることが確定している本番データベースサーバーのコストを抑えたい場合、最も適した購入オプションはどれですか？',
    choices:['無料利用枠','スポットインスタンス','オンデマンドインスタンスのみ','リザーブドインスタンスまたはSavings Plans'], correct:[3],
    why:['誤り。無料利用枠は期間や範囲が限定されており、3年間の本番運用をカバーするものではありません。','誤り。スポットインスタンスは中断の可能性があり、常時稼働が必須の本番データベースには不向きです。','誤り。オンデマンドインスタンスのみでは、長期利用の割引を受けられずコストが高くなります。','正しい。長期間の継続利用が確定している場合、リザーブドインスタンスやSavings Plansの長期契約によりオンデマンドより割安な料金を得られます。']},
  {id:'p45', domain:'billing', type:'multi', source:SOURCES.trustedadvisor, text:'AWS Trusted Advisorが推奨事項を提示するカテゴリとして正しいものを2つ選択してください。',
    choices:['ネットワークの物理的な配線設計','従業員の勤怠管理','コスト最適化','セキュリティ'], correct:[2,3],
    why:['誤り。物理的な配線設計はAWSが管理する範囲であり、Trusted Advisorの推奨カテゴリではありません。','誤り。従業員の勤怠管理はAWSのサービス範囲外です。','正しい。コスト最適化はTrusted Advisorが推奨事項を提示する代表的なカテゴリの一つです。','正しい。セキュリティもTrusted Advisorが推奨事項を提示するカテゴリの一つです。']},
  {id:'p46', domain:'billing', type:'single', source:SOURCES.support, text:'AWSサポートプランに関する正しい説明はどれですか？',
    choices:['すべてのサポートプランは有料で、Basicプランも費用が発生する','Basic Supportはすべてのアカウントで自動的に無料で利用でき、上位プランでは対応時間の短縮や専任担当（TAM）などの手厚い支援が追加される','サポートプランはセキュリティ機能の有効化にのみ関係する','サポートプランはAWSの利用料金に含まれ、別途申込みは一切不要である'], correct:[1],
    why:['誤り。Basic Supportは無料で、追加費用は発生しません。','正しい。Basic Supportは全アカウントに自動的に無料で付属し、上位の有料プランでは対応時間の短縮や専任のテクニカルアカウントマネージャー（TAM）などが追加されます。','誤り。サポートプランはセキュリティに限らず、技術支援全般に関係します。','誤り。上位プランは別途申込み・契約が必要です。']},

  // --- 追加分 ---
  {id:'p47', domain:'concepts', type:'single', source:SOURCES.wafReliability, text:'システムの各コンポーネント間の依存関係を減らし、一部に障害が発生しても全体への影響を抑える設計思想を何と呼びますか？',
    choices:['疎結合（Loose Coupling）','密結合（Tight Coupling）','垂直スケーリング','単一障害点の集中設計'], correct:[0],
    why:['正しい。疎結合（Loose Coupling）はコンポーネント間の依存を減らし、一部の障害が全体に波及しにくくする設計です。','誤り。密結合は依存が強く、障害の影響が広がりやすい設計です。','誤り。垂直スケーリングはリソースの増強方法であり、結合度とは無関係です。','誤り。単一障害点はむしろ避けるべき設計上の弱点です。']},
  {id:'p48', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'AWSのような大規模事業者が多数の顧客の需要を集約することで、利用者が単位あたりのコストを下げられる効果を何と呼びますか？',
    choices:['弾力性（Elasticity）','規模の経済（Economies of Scale）','疎結合（Loose Coupling）','責任共有モデル'], correct:[1],
    why:['誤り。弾力性は需要に応じたリソースの増減を指す概念です。','正しい。規模の経済は、多数の利用を集約することで単位コストを引き下げられる効果を指します。','誤り。疎結合はコンポーネント間の依存を減らす設計思想です。','誤り。責任共有モデルはセキュリティ責任の分担に関する概念です。']},
  {id:'p49', domain:'concepts', type:'single', source:SOURCES.wafReliability, text:'ディザスタリカバリ(DR)計画を策定する目的として最も適切なものはどれですか？',
    choices:['日常のコストを完全にゼロにすること','単一のアベイラビリティーゾーンにリソースを集中させ管理を簡素化すること','大規模な障害や災害が発生した場合に、システムを復旧し事業を継続できるようにすること','すべてのIAMユーザーに管理者権限を付与すること'], correct:[2],
    why:['誤り。コストをゼロにすることが目的ではありません。','誤り。単一AZへの集中は可用性・耐障害性を下げる方向であり、DRの目的に反します。','正しい。DR計画は大規模な障害や災害発生時にシステムを復旧し、事業を継続できるようにすることが目的です。','誤り。IAM権限管理とは無関係です。']},
  {id:'p50', domain:'security', type:'single', source:SOURCES.config, text:'AWSリソースの構成変更履歴を記録し、特定時点での構成を遡って確認できるようにしたい場合、最も適したサービスはどれですか？',
    choices:['Amazon GuardDuty','AWS CloudTrail','Amazon CloudWatch','AWS Config'], correct:[3],
    why:['誤り。GuardDutyは脅威検知サービスであり、構成変更履歴の記録が主目的ではありません。','誤り。CloudTrailはAPIコールの履歴を記録しますが、リソースの構成そのものの履歴を時系列で評価する役割はAWS Configが担います。','誤り。CloudWatchは運用メトリクス・ログの監視が主目的です。','正しい。AWS Configはリソースの構成と変更履歴を記録し、特定時点の構成を確認できます。']},
  {id:'p51', domain:'security', type:'single', source:SOURCES.inspector, text:'EC2インスタンスやコンテナイメージ、Lambda関数を自動的にスキャンし、ソフトウェアの脆弱性や意図しないネットワーク露出を継続的に検出するサービスはどれですか？',
    choices:['Amazon Inspector','AWS Secrets Manager','AWS Artifact','AWS Organizations'], correct:[0],
    why:['正しい。Amazon Inspectorは、EC2・コンテナイメージ・Lambda関数等を自動的にスキャンし、脆弱性やネットワーク露出を継続的に検出する脆弱性管理サービスです。','誤り。Secrets Managerはシークレットの保管・ローテーションサービスです。','誤り。Artifactはコンプライアンスレポートの取得サービスです。','誤り。Organizationsは複数アカウント管理サービスです。']},
  {id:'p52', domain:'security', type:'single', source:SOURCES.acm, text:'Webサイトやロードバランサーで使用するSSL/TLS証明書を発行・管理し、多くの場合自動的に更新できるサービスはどれですか？',
    choices:['AWS KMS','AWS Certificate Manager (ACM)','Amazon Cognito','AWS Secrets Manager'], correct:[1],
    why:['誤り。KMSは暗号鍵の作成・管理サービスであり、SSL/TLS証明書の発行に特化したサービスではありません。','正しい。ACMはSSL/TLS証明書を発行・管理し、ELBやCloudFront等と連携して自動更新できるサービスです。','誤り。Cognitoはアプリケーションのユーザー認証・ID管理サービスです。','誤り。Secrets Managerはデータベース認証情報等のシークレット管理サービスです。']},
  {id:'p53', domain:'security', type:'multi', source:SOURCES.cognito, text:'モバイルアプリのユーザーにサインアップ・サインイン機能を提供し、Google等の外部IDプロバイダーと連携した認証を実装したい場合に有効な対策を2つ選択してください。',
    choices:['Amazon Cognitoのユーザープールを使用して認証機能を実装する','外部IDプロバイダー(例: Google)とのフェデレーションを設定する','すべてのユーザーにルートユーザーの認証情報を共有する','IAMロールをエンドユーザーに直接割り当てて個人管理する'], correct:[0,1],
    why:['正しい。Cognitoのユーザープールは、サインアップ・サインイン機能を提供する認証サービスです。','正しい。Cognitoは外部IDプロバイダーとのフェデレーションをサポートし、既存のソーシャル/エンタープライズIDでのサインインを実現できます。','誤り。ルートユーザー認証情報の共有は重大なセキュリティリスクです。','誤り。IAMロールは一時的な権限委譲のための仕組みで、エンドユーザー個人への直接割り当て・個人管理には適していません。']},
  {id:'p54', domain:'tech', type:'single', source:SOURCES.ecs, text:'Dockerコンテナを複数のEC2インスタンスやFargate上でオーケストレーション（配置・スケーリング管理）したい場合、最も適したサービスはどれですか？',
    choices:['Amazon RDS','AWS Direct Connect','Amazon Elastic Container Service (ECS)','Amazon Route 53'], correct:[2],
    why:['誤り。RDSはリレーショナルデータベースサービスです。','誤り。Direct Connectは専用線接続サービスです。','正しい。ECSはコンテナのデプロイ・管理・スケーリングを行うフルマネージドなコンテナオーケストレーションサービスです。','誤り。Route 53はDNSサービスです。']},
  {id:'p55', domain:'tech', type:'single', source:SOURCES.aurora, text:'MySQLおよびPostgreSQLと互換性があり、クラウド向けに設計された高性能なリレーショナルデータベースサービスはどれですか？',
    choices:['Amazon DynamoDB','Amazon S3','Amazon ElastiCache','Amazon Aurora'], correct:[3],
    why:['誤り。DynamoDBはNoSQL型のデータベースです。','誤り。S3はオブジェクトストレージです。','誤り。ElastiCacheはインメモリキャッシュサービスであり、永続化を主目的とするリレーショナルデータベースではありません。','正しい。AuroraはMySQL・PostgreSQL互換の、クラウド向けに最適化された高性能なリレーショナルデータベースサービスです。']},
  {id:'p56', domain:'tech', type:'multi', source:SOURCES.sqs, text:'マイクロサービス間の処理を非同期化し、一時的な負荷の急増でも後続処理が失敗しないように疎結合化する設計として適切なものを2つ選択してください。',
    choices:['すべてのサービスを密結合にして同期呼び出しのみで連携する','Amazon SQSを使ってサービス間にキューを挟み、非同期にメッセージを受け渡す','AWS Lambdaを使ってイベント駆動で後続処理を実行する','単一のEC2インスタンスにすべての処理を集約する'], correct:[1,2],
    why:['誤り。密結合・同期呼び出しのみの構成は、負荷急増時に障害が伝播しやすくなります。','正しい。SQSによるキューを介した非同期連携は、サービス間を疎結合にし負荷の急増を吸収できます。','正しい。Lambdaのイベント駆動実行は、キューに溜まったメッセージを非同期に処理するのに適しています。','誤り。単一インスタンスへの集約は単一障害点を生み、スケーラビリティも損ないます。']},
  {id:'p57', domain:'tech', type:'single', source:SOURCES.beanstalk, text:'アプリケーションのコードをアップロードするだけで、EC2・ロードバランサー・Auto Scalingなどの基盤環境をAWSが自動的にプロビジョニングし、運用の詳細を管理せずにWebアプリケーションを実行したい場合、最も適したサービスはどれですか？',
    choices:['AWS Elastic Beanstalk','Amazon EFS','Amazon Route 53','AWS Direct Connect'], correct:[0],
    why:['正しい。Elastic Beanstalkは、コードをアップロードするだけでEC2・ロードバランサー・Auto Scaling等の環境をAWSが自動的に構築・管理してくれるサービスです。','誤り。EFSは共有ファイルストレージサービスです。','誤り。Route 53はDNSサービスです。','誤り。Direct Connectは専用線接続サービスです。']},
  {id:'p58', domain:'tech', type:'single', source:SOURCES.s3glacier, text:'数年に一度程度しかアクセスしない法令保存用のログデータを、できるだけ低コストで長期保管したい場合、最も適したストレージクラスはどれですか？',
    choices:['S3 Standard','S3 Glacier Deep Archive','Amazon EBS','Amazon EFS'], correct:[1],
    why:['誤り。S3 Standardは頻繁にアクセスするデータ向けの標準ストレージクラスで、長期保管用途としては割高です。','正しい。S3 Glacier Deep Archiveは、年に一度未満程度のアクセス頻度を想定した最も低コストな長期アーカイブ向けストレージクラスです。','誤り。EBSはEC2にアタッチするブロックストレージであり、長期アーカイブ用途には適していません。','誤り。EFSは複数インスタンスで共有するファイルストレージであり、長期アーカイブ用途には適していません。']},
  {id:'p59', domain:'billing', type:'single', source:SOURCES.pricingcalc, text:'新しいワークロードをAWS上に構築する前に、想定する構成（インスタンスタイプ・使用量等）を入力して事前にコストを見積もりたい場合、最も適したツールはどれですか？',
    choices:['AWS Budgets','AWS Cost Explorer','AWS Pricing Calculator','AWS Trusted Advisor'], correct:[2],
    why:['誤り。Budgetsは予算に対するアラート機能が主目的で、構築前の見積もりツールではありません。','誤り。Cost Explorerは過去の実績コストの分析・予測が主目的で、未構築のワークロードの見積もりには使いにくいです。','正しい。AWS Pricing Calculatorは、想定する構成を入力してワークロードのコストを事前に見積もれるツールです。','誤り。Trusted Advisorはベストプラクティスの推奨事項を提示するサービスです。']},

  // --- 追加分（運用上の優秀性・データセキュリティ・キャッシュ・コンテナ等） ---
  {id:'p60', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'クラウドの「俊敏性(アジリティ)」が新規事業のアイデア検証にもたらすメリットとして最も適切なものはどれですか？',
    choices:['必要なリソースを数分で調達できるため、低コスト・低リスクで新しいアイデアを素早く試せる','既存システムをすべて即座に廃止できる','料金が完全に無料になる','データセンターの建設が不要になるだけで、試行速度には影響しない'], correct:[0],
    why:['正しい。必要なリソースを素早く調達できることで、アイデアの実験や方向転換にかかる時間とコストを削減できます。','誤り。既存システムの廃止は移行計画次第であり、即座に行われるわけではありません。','誤り。リソースの利用には料金が発生します。','誤り。データセンター建設の不要化は俊敏性向上の一因であり、試行速度に影響しないという説明は誤りです。']},
  {id:'p61', domain:'concepts', type:'single', source:SOURCES.wafOps, text:'AWS Well-Architected Frameworkの「運用上の優秀性の柱」が重視する内容として正しいものはどれですか？',
    choices:['不要なコストを排除し支出対効果を最大化すること','システムを運用・監視し、手順を継続的に改善してビジネス価値を生み出すこと','障害発生時にシステムが復旧できる能力を高めること','環境への影響を低減すること'], correct:[1],
    why:['これはコスト最適化の柱の説明です。','正しい。運用上の優秀性の柱は、システムの運用・監視を行い、手順を継続的に改善してビジネス価値を生み出すことを重視します。','これは信頼性の柱の説明です。','これは持続可能性の柱の説明です。']},
  {id:'p62', domain:'concepts', type:'single', source:SOURCES.globalInfra, text:'サービスを複数のAWSリージョンに展開する目的として最も適切なものはどれですか？',
    choices:['単一のデータセンターに全リソースを集約し管理を簡素化するため','課金方法を一本化するため','利用者に近いリージョンからサービス提供してレイテンシーを下げたり、リージョン単位の障害に備えて災害対策を行うため','セキュリティグループの設定を不要にするため'], correct:[2],
    why:['誤り。これは複数リージョン展開とは逆の方針です。','誤り。課金方法の一本化が主目的ではありません。','正しい。複数リージョンへの展開により、利用者に近い場所からの低レイテンシーな提供や、リージョン規模の障害に対する災害対策（DR）を実現できます。','誤り。セキュリティグループの設定はリージョンを問わず必要です。']},
  {id:'p63', domain:'concepts', type:'multi', source:SOURCES.sixAdv, text:'クラウド移行によって得られる経済的・運用的なメリットとして正しいものを2つ選択してください。',
    choices:['先行投資（資本費用）が不要になり、使用した分だけの費用（運用費用）に変えられる','必要なITリソースを数分で調達できるようになる','すべてのサービスの利用が無期限に無料になる','サーバーの保守作業が自動的に3倍に増える'], correct:[0,1],
    why:['正しい。クラウドでは先行投資（資本費用）を行わず、使用量に応じた費用（運用費用）に変えられます。','正しい。必要なリソースを数分で調達できるようになり、俊敏性が向上します。','誤り。無期限・無料になるわけではありません。','誤り。保守作業は自動的に増えるのではなく、AWSが管理する範囲が増えることで利用者側の負担は減る方向です。']},
  {id:'p64', domain:'security', type:'single', source:SOURCES.macie, text:'機械学習とパターンマッチングを使って、S3バケット内のデータから個人情報(PII)などの機密データを自動的に検出するサービスはどれですか？',
    choices:['Amazon GuardDuty','Amazon Inspector','AWS Config','Amazon Macie'], correct:[3],
    why:['誤り。GuardDutyはAPIコールやネットワーク挙動から脅威を検知するサービスで、S3内データの機密情報検出が主目的ではありません。','誤り。Inspectorはソフトウェアの脆弱性をスキャンするサービスです。','誤り。Configはリソースの構成変更履歴を記録するサービスです。','正しい。Amazon Macieは機械学習とパターンマッチングでS3内のPII等の機密データを検出し、データセキュリティのリスクを可視化します。']},
  {id:'p65', domain:'security', type:'multi', source:SOURCES.shared, text:'責任共有モデルにおいて、利用者（ユーザー）側の責任範囲に該当するものを2つ選択してください。',
    choices:['データセンターの物理的な警備','保存するデータの暗号化の有無や方法の選択','ハードウェアの老朽化対応','IAMユーザー・ロールへの適切な権限付与'], correct:[1,3],
    why:['誤り。データセンターの物理的な警備はAWS側の責任範囲です。','正しい。データを暗号化するかどうか、どの方式で暗号化するかはユーザー側が選択・管理する責任範囲です。','誤り。ハードウェアの老朽化対応はAWS側の責任範囲です。','正しい。IAMユーザー・ロールへの適切な権限付与（最小権限の原則の適用）はユーザー側の責任範囲です。']},
  {id:'p66', domain:'security', type:'single', source:SOURCES.acm, text:'Webサイトで使用するSSL/TLS証明書の発行・管理・自動更新を行いたい場合、最も適したサービスはどれですか？',
    choices:['AWS Secrets Manager','AWS Certificate Manager (ACM)','AWS KMS','Amazon Cognito'], correct:[1],
    why:['誤り。Secrets Managerはデータベース認証情報等のシークレット管理サービスです。','正しい。ACMはパブリック・プライベートのSSL/TLS証明書を発行・管理し、ELBやCloudFront等と連携して自動更新できるサービスです。','誤り。KMSは暗号鍵の作成・管理サービスで、証明書の発行機能は主目的ではありません。','誤り。Cognitoはアプリケーションの利用者認証・認可を管理するサービスです。']},
  {id:'p67', domain:'tech', type:'single', source:SOURCES.elasticache, text:'データベースへの読み取り負荷を減らし、アプリケーションの応答速度を改善するために、頻繁にアクセスされるデータをインメモリに保持したい場合、最も適したサービスはどれですか？',
    choices:['Amazon EBS','AWS Direct Connect','Amazon ElastiCache','Amazon Route 53'], correct:[2],
    why:['誤り。EBSはEC2にアタッチするブロックストレージであり、インメモリキャッシュではありません。','誤り。Direct Connectは専用線接続サービスです。','正しい。ElastiCacheはRedisやMemcached等のインメモリキャッシュをマネージドで提供し、データベースの負荷軽減とアプリケーションの応答速度向上に利用されます。','誤り。Route 53はDNSサービスです。']},
  {id:'p68', domain:'tech', type:'single', source:SOURCES.ecs, text:'複数のDockerコンテナを本番環境でオーケストレーション（配置・スケーリング・管理）したい場合、最も適したサービスはどれですか？',
    choices:['Amazon EBS','Amazon Route 53','AWS Budgets','Amazon Elastic Container Service (ECS)'], correct:[3],
    why:['誤り。EBSはブロックストレージサービスです。','誤り。Route 53はDNSサービスです。','誤り。Budgetsは予算管理サービスです。','正しい。ECSはDockerコンテナのデプロイ・スケーリング・管理をオーケストレーションするマネージドサービスです。']},
  {id:'p69', domain:'tech', type:'multi', source:SOURCES.aurora, text:'Amazon Auroraの特徴として正しいものを2つ選択してください。',
    choices:['MySQLやPostgreSQLと互換性のあるマネージドリレーショナルデータベースである','キーバリュー型のNoSQLデータベースである','一般的なMySQLに比べて高いスループットを実現できるよう設計されている','オンプレミス環境専用のデータベースエンジンである'], correct:[0,2],
    why:['正しい。AuroraはMySQL・PostgreSQL互換のマネージドリレーショナルデータベースです。','誤り。これはAmazon DynamoDBの説明です。','正しい。Auroraは一般的なMySQLデータベースに比べて高いスループットを実現できるよう設計されています。','誤り。Auroraはクラウド上で提供されるマネージドサービスであり、オンプレミス専用ではありません。']},
  {id:'p70', domain:'tech', type:'single', source:SOURCES.sqs, text:'アプリケーションのコンポーネント間でメッセージを受け渡し、処理のタイミングを分離（デカップリング）したい場合、最も適したサービスはどれですか？',
    choices:['Amazon SQS','Amazon CloudWatch','AWS CloudTrail','Amazon Route 53'], correct:[0],
    why:['正しい。Amazon SQSはメッセージキューイングサービスで、コンポーネント間でメッセージを受け渡すことで処理のタイミングを分離（デカップリング）できます。','誤り。CloudWatchはメトリクス監視サービスです。','誤り。CloudTrailはAPI操作履歴の記録サービスです。','誤り。Route 53はDNSサービスです。']},
  {id:'p71', domain:'tech', type:'single', source:SOURCES.beanstalk, text:'インフラの構成管理やキャパシティプロビジョニング、ロードバランシングを自動で行い、コードをアップロードするだけでWebアプリケーションを素早くデプロイしたい場合、最も適したサービスはどれですか？',
    choices:['Amazon EBS','AWS Elastic Beanstalk','AWS Direct Connect','Amazon GuardDuty'], correct:[1],
    why:['誤り。EBSはブロックストレージサービスです。','正しい。Elastic Beanstalkはコードをアップロードするだけで、インフラのプロビジョニング・ロードバランシング・Auto Scaling等を自動的に処理し、Webアプリケーションを素早くデプロイできるサービスです。','誤り。Direct Connectは専用線接続サービスです。','誤り。GuardDutyは脅威検知サービスです。']},
  {id:'p72', domain:'billing', type:'single', source:SOURCES.pricingcalc, text:'まだAWS上に構築していないワークロードについて、想定する構成を入力して事前にコストの見積もりを行いたい場合、最も適したツールはどれですか？',
    choices:['AWS Cost Explorer','AWS Budgets','AWS Pricing Calculator','AWS Trusted Advisor'], correct:[2],
    why:['誤り。Cost Explorerは過去の実績コストの分析・予測ツールです。','誤り。Budgetsは予算に対するアラート機能が主目的です。','正しい。AWS Pricing Calculatorは、想定する構成を入力することで、未構築のワークロードのコストを事前に見積もれるツールです。','誤り。Trusted Advisorはベストプラクティスの推奨事項を提示するサービスです。']},
  {id:'p73', domain:'concepts', type:'single', source:SOURCES.caf, text:'AWS Cloud Adoption Framework (AWS CAF) が示す6つの視点（パースペクティブ）に含まれないものはどれですか？',
    choices:['テクニカルサポート','ガバナンス','プラットフォーム','セキュリティ'], correct:[0],
    why:['正しい。AWS CAFの6つの視点はビジネス・人材・ガバナンス・プラットフォーム・セキュリティ・運用であり、「テクニカルサポート」という視点は含まれません。','誤り。ガバナンスはAWS CAFの6つの視点の1つです。','誤り。プラットフォームはAWS CAFの6つの視点の1つです。','誤り。セキュリティはAWS CAFの6つの視点の1つです。']},
  {id:'p74', domain:'concepts', type:'single', source:SOURCES.migrationStrategies, text:'既存のオンプレミスアプリケーションを、同等機能を持つ別の製品（多くはSaaS）に乗り換える移行戦略を何と呼びますか？',
    choices:['リホスト(Rehost)','リパーチェス(Repurchase)','リファクタリング(Refactor / Re-architect)','リタイア(Retire)'], correct:[1],
    why:['誤り。リホストは、アプリケーションをほぼ変更せずそのままクラウドに移す戦略です。','正しい。リパーチェスは、既存のアプリケーションを同等機能を持つ別の製品（多くはSaaS）に置き換える移行戦略です。','誤り。リファクタリングは、クラウドネイティブな機能を活用するためにアプリケーションを再設計する戦略です。','誤り。リタイアは、不要になったアプリケーションを廃止する戦略です。']},
  {id:'p75', domain:'concepts', type:'single', source:SOURCES.hybridCloud, text:'オンプレミス環境とAWSクラウド環境を接続し、両方を組み合わせて利用するデプロイモデルを何と呼びますか？',
    choices:['パブリッククラウド','プライベートクラウド','ハイブリッドクラウド','マルチクラウド'], correct:[2],
    why:['誤り。パブリッククラウドは、AWSのようなプロバイダーが提供するクラウド環境のみを利用する形態です。','誤り。プライベートクラウドは、自社専用に構築・運用されるクラウド環境のみを指します。','正しい。ハイブリッドクラウドは、オンプレミス環境とパブリッククラウド環境を接続し、両方を組み合わせて利用するデプロイモデルです。','誤り。マルチクラウドは、複数の異なるクラウドプロバイダーを組み合わせて利用する形態を指し、オンプレミスとの組み合わせを前提とした用語ではありません。']},
  {id:'p76', domain:'security', type:'single', source:SOURCES.iamIdentityCenter, text:'複数のAWSアカウントを運用する組織で、従業員が1回のログインで許可された複数のAWSアカウントやアプリケーションにアクセスできるようにしたい場合、最も適したサービスはどれですか？',
    choices:['Amazon Cognito','AWS Secrets Manager','AWS Key Management Service (KMS)','AWS IAM Identity Center'], correct:[3],
    why:['誤り。Cognitoは主にアプリケーションの利用者（エンドユーザー）向けの認証・ID管理サービスです。','誤り。Secrets Managerはデータベース認証情報等のシークレットを管理するサービスです。','誤り。KMSは暗号鍵を作成・管理するサービスです。','正しい。IAM Identity Centerは、複数のAWSアカウントやアプリケーションへのシングルサインオンによる従業員アクセスを一元管理するサービスです。']},
  {id:'p77', domain:'security', type:'single', source:SOURCES.kms, text:'保管時のデータ（保存されているデータ）を暗号化する際に、暗号鍵の作成・管理に使われるAWSサービスはどれですか？',
    choices:['AWS Key Management Service (KMS)','AWS Certificate Manager (ACM)','Amazon CloudWatch','AWS Trusted Advisor'], correct:[0],
    why:['正しい。AWS KMSは、保管時のデータ暗号化等に使用する暗号鍵を作成・管理するサービスです。','誤り。ACMはSSL/TLS証明書を発行・管理するサービスで、主に転送中データの暗号化（通信の暗号化）に関わります。','誤り。CloudWatchは監視サービスで、暗号鍵管理機能はありません。','誤り。Trusted Advisorはベストプラクティスの推奨を行うサービスで、暗号鍵管理機能はありません。']},
  {id:'p78', domain:'security', type:'single', source:SOURCES.securityHub, text:'Amazon GuardDuty・Amazon Inspector・Amazon Macieなど複数のセキュリティサービスの検出結果を一つの画面に集約し、セキュリティ状態を統合的に確認できるサービスはどれですか？',
    choices:['AWS Config','AWS Security Hub','AWS CloudTrail','AWS Artifact'], correct:[1],
    why:['誤り。Configはリソースの構成変更履歴を記録・評価するサービスです。','正しい。AWS Security Hubは、GuardDuty・Inspector・Macieなど複数のセキュリティサービスの検出結果を集約し、セキュリティ状態を統合的に可視化するサービスです。','誤り。CloudTrailはAPIコールの記録・監査を行うサービスです。','誤り。Artifactはコンプライアンスレポートや契約書を取得できるサービスです。']},
  {id:'p79', domain:'tech', type:'single', source:SOURCES.sns, text:'アプリケーションから送信された1件の通知を、メール・SMS・複数のLambda関数など複数の宛先に同時に配信したい場合、最も適したサービスはどれですか？',
    choices:['Amazon SQS','Amazon EventBridge','Amazon SNS','AWS Direct Connect'], correct:[2],
    why:['誤り。SQSは1つのキューを介した非同期メッセージ処理に向いたキューイングサービスで、1件のメッセージを複数の宛先に同時配信することは主目的ではありません。','誤り。EventBridgeはイベント駆動のルーティングサービスで、主にAWSサービス間やSaaS連携のイベント処理に使われます。本シナリオのような通知のマルチ配信にはSNSがより直接的に適しています。','正しい。Amazon SNSはpub/sub型のサービスで、1件のメッセージを複数のサブスクライバー（メール、SMS、Lambda等）へ同時に配信できます。','誤り。Direct Connectは専用線接続サービスで、通知配信とは無関係です。']},
  {id:'p80', domain:'tech', type:'single', source:SOURCES.snowFamily, text:'数百テラバイト〜ペタバイト規模のデータを、インターネット経由ではなく物理デバイスを使ってオンプレミスからAWSへ輸送したい場合に使うサービスはどれですか？',
    choices:['AWS Direct Connect','AWS Storage Gateway','AWS Database Migration Service (DMS)','AWS Snowball Edge'], correct:[3],
    why:['誤り。Direct Connectはオンプレミスとの専用線接続サービスで、物理デバイスによる大容量データ輸送ではなくネットワーク経由の接続手段です。','誤り。Storage GatewayはオンプレミスとS3等を連携させるハイブリッドストレージサービスで、ネットワーク経由でのデータ連携が前提です。','誤り。DMSはデータベースをAWSへ移行・レプリケーションするサービスで、物理デバイスによる大容量データ輸送のためのサービスではありません。','正しい。AWS Snowball Edge(Storage Optimized/Compute Optimized)は、物理デバイスを使ってオンプレミスとAWS間で大容量データを輸送するサービスです。']},
  {id:'p81', domain:'tech', type:'single', source:SOURCES.redshift, text:'大量の履歴データを対象に複雑な集計・分析クエリ（OLAP）を高速に実行したい場合に最も適したサービスはどれですか？',
    choices:['Amazon Redshift','Amazon RDS','Amazon DynamoDB','Amazon ElastiCache'], correct:[0],
    why:['正しい。Amazon Redshiftは、ペタバイト規模のデータに対する複雑な分析クエリ（OLAP）を高速に処理できるマネージド型データウェアハウスサービスです。','誤り。RDSはオンライントランザクション処理（OLTP）向けのマネージド型リレーショナルデータベースサービスで、大規模分析処理に特化したサービスではありません。','誤り。DynamoDBはキーバリュー型のNoSQLデータベースで、低レイテンシーなトランザクション処理に向いていますが、複雑な分析クエリには向いていません。','誤り。ElastiCacheはインメモリキャッシュサービスで、データウェアハウスではありません。']},
  {id:'p82', domain:'tech', type:'multi', source:SOURCES.lambda, text:'次のAWSのコンピューティングサービスのうち、サーバーのプロビジョニングや管理が不要な「サーバーレス」なサービスを2つ選択してください。',
    choices:['Amazon EC2','AWS Lambda','AWS Fargate','Amazon Lightsail'], correct:[1,2],
    why:['誤り。EC2は仮想サーバー（インスタンス）をユーザー自身が起動・管理するサービスで、サーバーレスではありません。','正しい。AWS Lambdaは、コードを実行するためのサーバーをユーザーが管理する必要がないサーバーレスなコンピューティングサービスです。','正しい。AWS Fargateは、コンテナを実行するためのサーバーやクラスターをユーザーが管理する必要がないサーバーレスなコンピューティングサービスです。','誤り。Lightsailは簡易な仮想サーバー（VPS）を提供するサービスで、サーバー自体の管理は依然としてユーザー側で必要です。']},
  {id:'p83', domain:'billing', type:'single', source:SOURCES.consolidatedBilling, text:'複数の子会社がそれぞれ別々のAWSアカウントを持つ企業グループが、AWS Organizationsの一括支払い（Consolidated Billing）を使う主なメリットは何ですか？',
    choices:['各アカウントのセキュリティ設定が自動的に統一される','各アカウントのIAMユーザーが自動的に共有される','複数アカウントの利用量を合算することで、ボリュームディスカウントなどが適用されやすくなる','各アカウントで異なるリージョンの料金表が自動的に適用される'], correct:[2],
    why:['誤り。セキュリティ設定の統一は一括支払いの機能ではなく、AWS OrganizationsのSCP(サービスコントロールポリシー)等の別機能で実現します。','誤り。IAMユーザーはアカウントごとに個別に管理され、一括支払いによって自動的に共有されるわけではありません。','正しい。一括支払いでは複数アカウントの利用量が合算されるため、ボリュームディスカウントやリザーブドインスタンス割引等が適用されやすくなります。','誤り。リージョンごとの料金表はアカウントの支払い方法に関わらず同一の基準で適用されます。']},
  {id:'p84', domain:'billing', type:'single', source:SOURCES.computeOptimizer, text:'EC2インスタンスやLambda関数などの使用率を分析し、コスト削減とパフォーマンス向上につながるリソースサイズの変更（ライトサイジング）を推奨するサービスはどれですか？',
    choices:['AWS Budgets','AWS Cost Explorer','AWS Trusted Advisor','AWS Compute Optimizer'], correct:[3],
    why:['誤り。Budgetsは予算を設定し、超過時に通知するサービスです。','誤り。Cost Explorerは過去のコスト・使用状況を可視化・分析するサービスです。','誤り。Trusted Advisorはコスト・セキュリティ・耐障害性等の観点から幅広い推奨事項を提示しますが、利用率メトリクスに基づく詳細なライトサイジング推奨に特化したサービスはCompute Optimizerです。','正しい。AWS Compute Optimizerは、EC2・Lambda・EBS等の使用率メトリクスを分析し、コスト削減やパフォーマンス向上につながるリソース設定変更を推奨するサービスです。']},
  {id:'p85', domain:'billing', type:'single', source:SOURCES.costmgmt, text:'中断されても問題ない処理（バッチ処理等）で、オンデマンド料金に比べて大幅なコスト削減を狙える代わりに、AWS側の都合で中断される可能性があるEC2の購入オプションはどれですか？',
    choices:['スポットインスタンス(Spot Instances)','リザーブドインスタンス(Reserved Instances)','Savings Plans','オンデマンドインスタンス(On-Demand Instances)'], correct:[0],
    why:['正しい。スポットインスタンスはAWSの余剰キャパシティを活用した購入オプションで、オンデマンドに比べ大幅に安価ですが、AWS側の都合で中断される可能性があります。','誤り。リザーブドインスタンスは一定期間の利用を事前にコミットすることで割引を受ける購入オプションで、中断されることはありません。','誤り。Savings Plansは一定期間・一定金額分の利用をコミットすることで割引を受ける購入オプションで、中断されることはありません。','誤り。オンデマンドインスタンスは最も柔軟で中断されない購入オプションですが、割引はありません。']},

  // --- 追加分（規模の経済/HA・FT比較/Network Firewall/API Gateway/Systems Manager/Transit Gateway/Marketplace/Free Tier構成） ---
  {id:'p86', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'AWSの「規模の経済(Economies of Scale)」によって利用者が得られる主なメリットは何ですか？',
    choices:['AWSが大規模な利用を集約することで実現した低コスト構造が、従量課金の低価格として利用者に還元される','サーバーの台数を自動的に増減できる','複数のアベイラビリティーゾーンにデータが自動的に複製される','IAMによるアクセス制御が不要になる'], correct:[0],
    why:['正しい。規模の経済は、AWSが非常に多くの顧客の利用を集約して実現した低コスト構造が、従量課金の低価格として利用者に還元される仕組みです。','誤り。これは弾力性(Elasticity)の説明です。','誤り。これは可用性・耐久性向上のための仕組みの説明です。','誤り。規模の経済とIAMによるアクセス制御は無関係で、アクセス制御は引き続き必要です。']},
  {id:'p87', domain:'concepts', type:'single', source:SOURCES.wafReliability, text:'「高可用性(High Availability)」と「耐障害性(Fault Tolerance)」の違いに関する説明として正しいものはどれですか？',
    choices:['両者は完全に同義であり、互換的に使ってよい','高可用性は障害発生時にユーザーへの影響を完全にゼロにすることを指す','耐障害性は稼働率(アップタイム)の目標値のみを指す指標である','高可用性はダウンタイムを最小化する設計を指し、耐障害性はコンポーネント障害が発生してもシステム全体が機能を継続できる、より高いレベルの要件を指す'], correct:[3],
    why:['誤り。両者は関連しますが、要求レベルが異なる別の概念です。','誤り。高可用性はダウンタイムの最小化を目指しますが、影響を完全にゼロにすることを保証するものではありません。','誤り。耐障害性は稼働率の数値指標ではなく、障害時にも機能を継続できる設計上の能力を指します。','正しい。高可用性はダウンタイムを最小限に抑える設計を指し、耐障害性はコンポーネント障害時にもシステム全体として機能を継続できる、より高いレベルの要件を指します。']},
  {id:'p88', domain:'concepts', type:'multi', source:SOURCES.sixAdv, text:'AWSクラウドを利用する6つのメリットのうち、正しい組み合わせを2つ選択してください。',
    choices:['需要を見積もる前にキャパシティを確保する必要がなくなる（キャパシティの推測が不要になる）','すべてのAWSサービスが永続的に無料になる','数クリック・数分で複数リージョンへグローバル展開できる','ハードウェアの保守は利用者自身が行う必要がある'], correct:[0,2],
    why:['正しい。クラウドでは事前にキャパシティを見積もる必要がなく、必要に応じてリソースを調整できます。','誤り。永続的に無料というわけではなく、使用量に応じて料金が発生します。','正しい。AWSのグローバルインフラを使えば、数クリックで複数リージョンへ短時間で展開できます。','誤り。ハードウェアの保守はAWS側が担当し、利用者が行う必要はありません。']},
  {id:'p89', domain:'security', type:'single', source:SOURCES.networkFirewall, text:'複数のVPCに対して、ステートフルなディープパケットインスペクションや侵入検知/防止(IDS/IPS)ルールを一元的に適用したい場合に適したサービスはどれですか？',
    choices:['AWS WAF','AWS Network Firewall','AWS Shield','AWS Secrets Manager'], correct:[1],
    why:['誤り。WAFはWebアプリケーション層(HTTP/HTTPS)のリクエストをフィルタリングするサービスで、VPC全体のネットワークトラフィックは対象外です。','正しい。AWS Network Firewallは、VPC単位でステートフルなディープパケットインスペクションやSuricata互換のIDS/IPSルールを適用できるマネージドネットワークファイアウォールです。','誤り。ShieldはDDoS攻撃対策に特化したサービスです。','誤り。Secrets Managerはシークレット情報の管理サービスです。']},
  {id:'p90', domain:'security', type:'single', source:SOURCES.vpc, text:'セキュリティグループ・ネットワークACL(NACL)・AWS Network Firewallの役割の違いに関する説明として正しいものはどれですか？',
    choices:['3つとも同じ単位（VPC単位）で動作し、役割に違いはない','セキュリティグループがVPC全体、NACLがサブネット、Network Firewallがインスタンス単位で動作する','セキュリティグループはインスタンス単位、NACLはサブネット単位、Network FirewallはVPC単位というように、段階的に広い範囲をカバーする多層防御を構成できる','Network FirewallはセキュリティグループやNACLを置き換える後継サービスであり、両方とも不要になる'], correct:[2],
    why:['誤り。3つはそれぞれ異なる単位（インスタンス/サブネット/VPC）で動作します。','誤り。動作する単位が入れ替わっています。セキュリティグループはインスタンス単位、Network FirewallはVPC単位です。','正しい。インスタンス単位のセキュリティグループ、サブネット単位のNACL、VPC単位のNetwork Firewallを組み合わせることで、段階的な多層防御を実現できます。','誤り。Network Firewallは既存のセキュリティグループやNACLを置き換えるものではなく、組み合わせて使う追加の防御層です。']},
  {id:'p91', domain:'security', type:'multi', source:SOURCES.networkFirewall, text:'AWS環境におけるネットワークレベルでの防御策として適切なものを2つ選択してください。',
    choices:['AWS Secrets Managerでシークレットをローテーションする','セキュリティグループでインスタンスへのインバウンド通信を制限する','AWS KMSでS3オブジェクトを暗号化する','AWS Network FirewallでVPCの境界を通過するトラフィックを検査する'], correct:[1,3],
    why:['誤り。Secrets Managerのシークレットローテーションはアプリケーション層の認証情報管理であり、ネットワークレベルの防御ではありません。','正しい。セキュリティグループはインスタンスへのネットワークアクセスを制限するネットワークレベルの防御策です。','誤り。KMSによる暗号化はデータ保護の対策であり、ネットワークレベルの通信制御ではありません。','正しい。AWS Network FirewallはVPCの境界を通過するトラフィックを検査・フィルタリングするネットワークレベルの防御策です。']},
  {id:'p92', domain:'tech', type:'single', source:SOURCES.apigateway, text:'モバイルアプリのバックエンドとして、AWS Lambda関数をHTTP経由で呼び出せるRESTful APIを作成・公開・保護したい場合に適したサービスはどれですか？',
    choices:['Elastic Load Balancing','Amazon API Gateway','Amazon CloudFront','Amazon Route 53'], correct:[1],
    why:['誤り。ELBはEC2インスタンス等へのトラフィック分散が主目的で、API定義・管理機能は提供しません。','正しい。API Gatewayは、Lambda等をバックエンドとするREST・HTTP・WebSocket APIの作成・公開・保護・監視を行うマネージドサービスです。','誤り。CloudFrontはコンテンツ配信(CDN)サービスです。','誤り。Route 53はDNSサービスです。']},
  {id:'p93', domain:'tech', type:'single', source:SOURCES.systemsManager, text:'本番環境のEC2インスタンスに対して、インバウンドのSSHポートを開けず、SSHキーも管理せずに、ブラウザやCLIから安全にシェルアクセスしたい場合に使える機能はどれですか？',
    choices:['Site-to-Site VPNで常時接続する','踏み台(bastion)サーバーを別途構築する','セキュリティグループで22番ポートを全開放する','AWS Systems Manager の Session Manager機能を使う'], correct:[3],
    why:['誤り。VPN接続自体はSSHポートを開ける必要性を直接なくすものではありません。','誤り。踏み台サーバーを使う方法はありますが、別途構築・管理コストがかかり、SSHキー管理も必要です。','誤り。22番ポートの全開放はセキュリティリスクを高める危険な設定です。','正しい。Systems ManagerのSession Managerを使うと、インバウンドポートを開けず、SSHキーも管理せずに、ブラウザやCLIから安全にインスタンスへアクセスできます。']},
  {id:'p94', domain:'tech', type:'single', source:SOURCES.transitGateway, text:'数十のVPCを相互接続する際、個別のVPCピアリング接続を多数管理する代わりにハブ&スポーク型の構成でネットワークを簡素化したい場合に適したサービスはどれですか？',
    choices:['AWS Transit Gateway','Amazon Route 53','AWS CloudFormation','Elastic Load Balancing'], correct:[0],
    why:['正しい。AWS Transit Gatewayは、多数のVPCやオンプレミス拠点を単一のハブ経由で相互接続でき、個別のVPCピアリングを多数管理する複雑さを解消します。','誤り。Route 53はDNSサービスです。','誤り。CloudFormationはInfrastructure as Codeのサービスです。','誤り。ELBはトラフィック分散サービスであり、VPC間接続のハブ機能ではありません。']},
  {id:'p95', domain:'tech', type:'multi', source:SOURCES.fargate, text:'サーバーのプロビジョニングや管理を利用者が行う必要がない「サーバーレス」な選択肢を2つ選択してください。',
    choices:['AWS Lambda','Amazon EC2','Amazon Lightsail','AWS Fargate'], correct:[0,3],
    why:['正しい。Lambdaはサーバーのプロビジョニングや管理を利用者が行う必要のない、イベント駆動のサーバーレスコンピューティングサービスです。','誤り。EC2は仮想サーバーであり、OSやスケーリングの管理が必要です。','誤り。Lightsailは簡易な仮想サーバー提供サービスで、基盤となるサーバーの管理という概念自体は残ります。','正しい。Fargateは、ECS/EKS上でコンテナを実行する際にサーバーの管理が不要なサーバーレスコンピューティングエンジンです。']},
  {id:'p96', domain:'billing', type:'single', source:SOURCES.marketplace, text:'サードパーティ製のソフトウェア（AMIベースの製品やSaaS型製品）をAWS上で検索・購入し、料金をAWSの利用料金とまとめて請求してもらいたい場合、最も適したサービスはどれですか？',
    choices:['AWS Budgets','AWS Cost Explorer','AWS Marketplace','AWS Organizations'], correct:[2],
    why:['誤り。Budgetsは予算アラートの設定サービスです。','誤り。Cost Explorerはコスト分析・予測ツールです。','正しい。AWS Marketplaceは、サードパーティ製ソフトウェアを検索・購入できるカタログで、料金はAWSの利用料金とまとめて請求されます。','誤り。Organizationsは複数アカウント管理サービスです。']},
  {id:'p97', domain:'billing', type:'single', source:SOURCES.free, text:'現行のAWS Free Tier（無料利用枠）の構成に関する説明として正しいものはどれですか？',
    choices:['すべてのサービスが12ヶ月間無料で使い放題になる','「常に無料」の対象サービス、新規アカウント向けの無料クレジット、特定サービスの短期無料トライアルという複数の仕組みで構成される','サポートプランの費用のみが無料になる制度である','新規アカウントであれば、すべてのサービスが永続的に無料になる'], correct:[1],
    why:['誤り。「12ヶ月間無料」という説明は現行の構成とは異なり、サービスや条件によって範囲が異なります。','正しい。現行のFree Tierは、常に無料の対象サービス、新規アカウント向けの無料クレジット、一部サービスの短期無料トライアルという複数の仕組みで構成されます。','誤り。サポートプランの無料提供（Basic Support）とは別の仕組みです。','誤り。永続的にすべてのサービスが無料になるわけではありません。']},
  {id:'p98', domain:'billing', type:'multi', source:SOURCES.computeOptimizer, text:'コストとパフォーマンスの最適化に関する推奨事項を得られるサービスを2つ選択してください。',
    choices:['AWS CloudTrail','AWS Trusted Advisor','AWS Compute Optimizer','Amazon GuardDuty'], correct:[1,2],
    why:['誤り。CloudTrailはAPIコール履歴の記録サービスであり、コスト最適化の推奨事項は提供しません。','正しい。Trusted Advisorはコスト最適化・パフォーマンス・セキュリティ等の観点からベストプラクティスに基づく推奨事項を提示します。','正しい。Compute Optimizerは利用率メトリクスを分析し、コスト削減とパフォーマンス向上につながるリソース変更を推奨します。','誤り。GuardDutyは脅威検知サービスであり、コスト最適化の推奨事項は提供しません。']},
  {id:'p99', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'クラウドコンピューティングの6つの利点のうち、「キャパシティ推測からの解放」とは何を指しますか？',
    choices:['必要なキャパシティを事前に予測して購入する必要がなくなり、需要に応じて必要な分だけ利用できること','データセンターの建設コストを削減できること','全リソースが永久に無料になること','障害発生時にシステムが自動的に復旧すること'], correct:[0],
    why:['正しい。クラウドでは事前にキャパシティを予測して購入する必要がなく、必要になった時に必要な分だけ調達・利用できます。','これはCapEx/OpExの変換（先行投資の削減）に関する利点であり、キャパシティ推測からの解放とは異なる論点です。','誤り。無料になるわけではなく、使用した分だけ課金されます。','これは耐障害性(Fault Tolerance)に関する内容であり、キャパシティ推測とは異なります。']},
  {id:'p100', domain:'concepts', type:'single', source:SOURCES.wafReliability, text:'信頼性の柱が推奨する「疎結合アーキテクチャ(Loose Coupling)」の利点として正しいものはどれですか？',
    choices:['全コンポーネントを1つのサーバーに集約し管理を簡素化できる','コンポーネント間の依存を減らすことで、一部の障害が他の部分に影響しにくくなり、個別にスケール・更新できる','料金を固定額にできる','暗号化を自動的に有効化できる'], correct:[1],
    why:['誤り。疎結合はむしろコンポーネントを分離する考え方であり、1つのサーバーへの集約とは逆の方向性です。','正しい。疎結合アーキテクチャはコンポーネント間の依存を減らし、一部の障害が他へ連鎖しにくくし、各コンポーネントを個別にスケール・更新できるようにします。','誤り。料金モデルとは直接関係しません。','誤り。暗号化の有効化とは直接関係しません。']},
  {id:'p101', domain:'concepts', type:'single', source:SOURCES.caf, text:'AWS Cloud Adoption Framework (AWS CAF)の目的として正しいものはどれですか？',
    choices:['EC2インスタンスの購入オプションを比較すること','DDoS攻撃から保護すること','組織がクラウド導入のための能力を体系的に構築・発展させるための指針を、ビジネス・人材・ガバナンス等の観点から提供すること','S3のストレージクラスを選択すること'], correct:[2],
    why:['誤り。これはEC2購入オプション（オンデマンド・RI等）の比較に関する内容で、CAFの目的ではありません。','誤り。これはAWS Shield等のセキュリティサービスの役割です。','正しい。AWS CAFは、ビジネス・人材・ガバナンス・プラットフォーム・セキュリティ・運用等の観点から、組織のクラウド導入能力の構築を支援する指針です。','誤り。これはAmazon S3のストレージクラス選択に関する内容で、CAFの目的ではありません。']},
  {id:'p102', domain:'concepts', type:'single', source:SOURCES.wafReliability, text:'可用性を高めるためにアプリケーションを複数のアベイラビリティーゾーン(AZ)に配置する設計の主な目的は何ですか？',
    choices:['料金を割引価格にすること','コンテナイメージのスキャンを自動化すること','ログデータを一元的に収集すること','単一のAZで障害が発生した場合でも、他のAZでサービス提供を継続できるようにすること'], correct:[3],
    why:['誤り。AZをまたいだ配置は料金の割引を目的とした仕組みではありません。','誤り。これはAmazon ECR等のイメージスキャン機能の説明です。','誤り。これはAmazon CloudWatch Logs等の説明です。','正しい。複数AZへの配置は、単一のAZで障害が発生してもサービス提供を継続できるようにする高可用性設計の基本です。']},
  {id:'p103', domain:'security', type:'single', source:SOURCES.cloudhsm, text:'AWS KMSとAWS CloudHSMの違いとして正しいものはどれですか？',
    choices:['CloudHSMは専有のハードウェアセキュリティモジュール(HSM)を提供し、鍵の管理をより細かく利用者自身で行う必要があるのに対し、KMSはAWSが鍵管理の大部分を担うマネージド型サービスである','KMSはDDoS対策サービスであり、CloudHSMは暗号鍵管理サービスである','CloudHSMは無料で利用できるが、KMSは有料である','KMSはオンプレミス専用のサービスであり、CloudHSMはクラウド専用のサービスである'], correct:[0],
    why:['正しい。CloudHSMは専有のHSMクラスタを提供し、利用者自身がより多くの鍵管理責任を持つのに対し、KMSはAWSが鍵管理の大部分を担うマネージド型サービスです。','誤り。KMSはDDoS対策サービスではなく暗号鍵管理サービスです（DDoS対策はAWS Shield）。','誤り。CloudHSMは専有ハードウェアを利用するため料金が発生します。','誤り。両方ともAWSクラウド上で提供されるサービスであり、オンプレミス専用ではありません。']},
  {id:'p104', domain:'security', type:'single', source:SOURCES.firewallManager, text:'AWS Firewall Managerの役割として正しいものはどれですか？',
    choices:['EC2インスタンスのOSにセキュリティパッチを適用する','AWS Organizations配下の複数アカウントにまたがって、AWS WAFルールやAWS Shield Advanced等のセキュリティポリシーを中央から一括管理・適用する','S3バケットのストレージクラスを自動で切り替える','IAMユーザーのパスワードを自動生成する'], correct:[1],
    why:['誤り。これはAWS Systems Manager等のパッチ管理機能の説明です。','正しい。Firewall Managerは、AWS Organizations配下の複数アカウント・アプリケーションに対し、WAFルールやShield Advanced保護などのセキュリティポリシーを中央から一括設定・適用できます。','誤り。これはS3ライフサイクルポリシーの説明です。','誤り。これはIAMのパスワードポリシーとは異なる機能です。']},
  {id:'p105', domain:'security', type:'single', source:SOURCES.detective, text:'Amazon Detectiveの役割として正しいものはどれですか？',
    choices:['Webアプリケーション層の攻撃をリアルタイムでブロックする','コンプライアンスレポートをオンデマンドで提供する','VPCフローログやAWS CloudTrailログ、Amazon GuardDutyの検出結果などを機械学習・グラフ理論で分析し、セキュリティ調査や根本原因の特定を支援する','暗号鍵のローテーションを自動化する'], correct:[2],
    why:['誤り。これはAWS WAFの役割です。','誤り。これはAWS Artifactの役割です。','正しい。Amazon Detectiveは、VPCフローログ・CloudTrailログ・GuardDutyの検出結果等を機械学習やグラフ理論で分析し、セキュリティ調査や根本原因の特定を支援します。','誤り。これはAWS KMS/Secrets Managerの役割です。']},
  {id:'p106', domain:'security', type:'single', source:SOURCES.iam, text:'IAMポリシーを設計する際の「最小権限の原則(Principle of Least Privilege)」とは何ですか？',
    choices:['すべてのユーザーにAdministratorAccessを付与すること','ルートユーザーのみでリソースを操作すること','MFAを無効化して操作を簡略化すること','ユーザーやロールには、タスクの実行に必要な最小限の権限のみを付与すること'], correct:[3],
    why:['誤り。すべてに管理者権限を付与するのは最小権限の原則に反します。','誤り。ルートユーザーの常用は推奨されず、最小権限の原則とも関係しません。','誤り。MFAの無効化はセキュリティを低下させ、最小権限の原則とは無関係です。','正しい。最小権限の原則は、ユーザーやロールにタスク実行に必要な最小限の権限のみを付与する考え方です。']},
  {id:'p107', domain:'tech', type:'single', source:SOURCES.ecr, text:'Amazon ECR(Elastic Container Registry)の役割として正しいものはどれですか？',
    choices:['Dockerコンテナイメージ等を安全に保存・管理できるマネージド型のコンテナイメージレジストリ','コンテナのオーケストレーション(実行・スケジューリング)を行うサービス','サーバーレスでコードを実行するサービス','リレーショナルデータベースを提供するサービス'], correct:[0],
    why:['正しい。ECRは、Dockerコンテナイメージ等をIAMで権限管理しながら安全に保存・管理できるマネージド型のコンテナイメージレジストリです。','誤り。これはAmazon ECS/EKSの役割です。','誤り。これはAWS Lambdaの役割です。','誤り。これはAmazon RDSの役割です。']},
  {id:'p108', domain:'tech', type:'single', source:SOURCES.globalAccelerator, text:'AWS Global AcceleratorとAmazon CloudFrontの違いとして正しいものはどれですか？',
    choices:['CloudFrontはネットワーク層でTCP/UDPトラフィックを最適化し、Global Acceleratorは静的コンテンツ配信に特化したCDNである','Global Acceleratorはネットワーク層でAWSのグローバルネットワークを使い、TCP/UDPを含むトラフィックを最適なエンドポイントにルーティングするのに対し、CloudFrontは主にコンテンツ配信(CDN)に特化している','両者はまったく同じ機能を提供し、完全に互換である','Global Acceleratorはリレーショナルデータベースサービスである'], correct:[1],
    why:['誤り。CloudFrontとGlobal Acceleratorの役割が逆です。','正しい。Global Acceleratorはネットワーク層でAWSのグローバルネットワークを利用し、TCP/UDPを含むトラフィックを最適なエンドポイントにルーティングするのに対し、CloudFrontはコンテンツ配信(CDN)に特化したサービスです。','誤り。両者は役割が異なり、用途に応じて使い分けます。','誤り。これはAmazon RDS等の説明です。']},
  {id:'p109', domain:'tech', type:'single', source:SOURCES.kinesis, text:'Amazon Kinesis Data Streamsの用途として正しいものはどれですか？',
    choices:['コンテナイメージを保存する','DNSクエリを解決する','ログデータやクリックストリームなどの大量データをリアルタイムに収集・処理するためのストリーミングデータサービス','IAMポリシーの構文を評価する'], correct:[2],
    why:['誤り。これはAmazon ECRの用途です。','誤り。これはAmazon Route 53の用途です。','正しい。Kinesis Data Streamsは、ログやクリックストリームなどの大量データをリアルタイムに収集・処理するためのストリーミングデータサービスです。','誤り。これはIAM Policy Simulator等の用途です。']},
  {id:'p110', domain:'tech', type:'single', source:SOURCES.natGateway, text:'VPCの「NATゲートウェイ」の役割として正しいものはどれですか？',
    choices:['複数のVPCやオンプレミス拠点を相互接続するハブとして機能する','インターネットからのインバウンド接続をプライベートサブネットのインスタンスに直接許可する','HTTP/HTTPSリクエストをルールに基づいてフィルタリングする','プライベートサブネット内のインスタンスがインターネット等の外部サービスへアウトバウンド接続できるようにする一方、外部からそのインスタンスへ接続を開始することはできないようにする'], correct:[3],
    why:['誤り。これはAWS Transit Gatewayの役割です。','誤り。NATゲートウェイは外部からのインバウンド接続の開始を許可しません。','誤り。これはAWS WAFの役割です。','正しい。NATゲートウェイは、プライベートサブネット内のインスタンスが外部サービスへアウトバウンド接続できるようにする一方、外部からの接続開始は許可しません。']},
  {id:'p111', domain:'tech', type:'multi', source:SOURCES.stepFunctions, text:'AWS Step Functionsの特徴として正しいものを2つ選択してください。',
    choices:['複数のAWS Lambda関数やその他のAWSサービスを順序立てて実行するワークフロー(ステートマシン)を構築できる','仮想サーバーのOSパッチ管理を行う','ワークフロー内の各ステップの再試行やエラーハンドリングを組み込みで管理できる','S3オブジェクトのストレージクラスを自動変更する'], correct:[0,2],
    why:['正しい。Step Functionsは、Lambda関数等を組み合わせて順序立てて実行するワークフロー(ステートマシン)を視覚的に構築できます。','誤り。これはAWS Systems Managerの役割です。','正しい。Step Functionsはワークフロー内の各ステップの再試行(リトライ)やエラーハンドリングを組み込みの仕組みで管理できます。','誤り。これはAmazon S3のライフサイクルポリシーの役割です。']},
  {id:'p112', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'オンプレミスでデータセンターを構築する場合と比較した、クラウドの経済的メリットとして正しいものはどれですか？',
    choices:['サーバー等への大きな先行投資（資本費用）を、実際に使用した分だけ支払う運用費用に変換できる','全サービスが完全に無料になる','ハードウェアの保守は依然として利用者が行う必要がある','リージョンを問わず同一の料金になる'], correct:[0],
    why:['正しい。クラウドでは先行投資（CapEx）を、使用量に応じた運用費用（OpEx）に変換できます。','誤り。クラウド利用には通常料金が発生します。','誤り。クラウドでは物理ハードウェアの保守はAWS側が担います。','誤り。料金はリージョンによって異なります。']},
  {id:'p113', domain:'concepts', type:'single', source:SOURCES.migrationStrategies, text:'移行戦略の一つである「リホスト(Rehost)」の説明として正しいものはどれですか？',
    choices:['アプリケーションのコードを大幅に変更し、クラウドネイティブな機能を活用できるように再設計する','アプリケーションをコードの変更を行わずに、そのままクラウドへ「リフト＆シフト」する','既存のライセンス製品を、クラウド上の別の製品に置き換える（購入し直す）','使用しなくなったアプリケーションを廃止する'], correct:[1],
    why:['これは「リファクタリング/リアーキテクト(Refactor)」の説明です。','正しい。リホストはアプリケーションのコードを変更せずにそのままクラウドへ移行する「リフト＆シフト」のアプローチです。','これは「リパーチェス(Repurchase)」の説明です。','これは「リタイア(Retire)」の説明です。']},
  {id:'p114', domain:'concepts', type:'multi', source:SOURCES.caf, text:'AWS Cloud Adoption Framework (CAF)が定義する観点（パースペクティブ）として正しいものを2つ選択してください。',
    choices:['ビジネス(Business)パースペクティブ','ガバナンス(Governance)パースペクティブ','マーケティング(Marketing)パースペクティブ','営業(Sales)パースペクティブ'], correct:[0,1],
    why:['正しい。AWS CAFは、ビジネス・人材・ガバナンス・プラットフォーム・セキュリティ・運用の観点でクラウド導入を整理するフレームワークで、ビジネスはその一つです。','正しい。ガバナンスもAWS CAFが定義する観点の一つです。','誤り。マーケティングはAWS CAFが定義する観点には含まれません。','誤り。営業はAWS CAFが定義する観点には含まれません。']},
  {id:'p115', domain:'concepts', type:'single', source:SOURCES.wafPerformance, text:'新しいAWSサービスやインスタンスタイプが登場した際、ワークロードのパフォーマンスを維持・向上させるために検証・採用していく姿勢は、Well-Architected Frameworkのどの柱に関連しますか？',
    choices:['信頼性の柱','コスト最適化の柱','パフォーマンス効率の柱','持続可能性の柱'], correct:[2],
    why:['信頼性の柱は障害時の継続稼働に関する内容で、新技術の採用による効率向上とは異なります。','コスト最適化の柱は費用対効果に関する内容です。','正しい。パフォーマンス効率の柱は、テクノロジーの進化に応じて新しいサービスやアプローチを検証・採用し、効率を維持する姿勢を含みます。','持続可能性の柱は環境負荷の低減に関する内容です。']},
  {id:'p116', domain:'security', type:'single', source:SOURCES.shield, text:'AWS Shield StandardとAWS Shield Advancedの違いとして正しいものはどれですか？',
    choices:['Standardのみ有料で、Advancedは無料で提供される','StandardはWebアプリケーション層の攻撃をルールベースでフィルタリングし、AdvancedはDDoS攻撃を検知する','Advancedではネットワークの脆弱性スキャンが行われる','Standardは全AWSアカウントに自動で無料提供される基本的なDDoS対策で、Advancedは追加費用を払うことで24時間365日のDDoS対応チームのサポートや高度な緩和機能を利用できる'], correct:[3],
    why:['誤り。Standardは無料、Advancedは有料のサブスクリプションです。','誤り。両方ともDDoS対策サービスです（Web層フィルタリングを行うのはAWS WAFです）。','誤り。脆弱性スキャンはAmazon Inspectorの機能です。','正しい。Shield Standardは全アカウントに無料で自動提供される基本的なDDoS対策で、Shield Advancedは有料で高度な緩和機能やDDoS対応チーム(DRT)のサポートを利用できます。']},
  {id:'p117', domain:'security', type:'multi', source:SOURCES.iam, text:'AWS IAMで作成できるポリシーの種類として正しいものを2つ選択してください。',
    choices:['課金ポリシー','IDベースポリシー（ユーザー・グループ・ロールにアタッチする）','リソースベースポリシー（S3バケット等のリソースに直接アタッチする）','ネットワークポリシー'], correct:[1,2],
    why:['誤り。「課金ポリシー」という種類のIAMポリシーはありません。','正しい。IDベースポリシーは、IAMユーザー・グループ・ロールにアタッチする管理ポリシーです。','正しい。リソースベースポリシーは、S3バケットなどのリソースに直接アタッチするポリシーです。','誤り。「ネットワークポリシー」という種類のIAMポリシーはありません（ネットワーク制御はセキュリティグループ等で行います）。']},
  {id:'p118', domain:'security', type:'single', source:SOURCES.cognito, text:'Amazon Cognitoの「ユーザープール」と「IDプール（フェデレーテッドアイデンティティ）」の違いとして正しいものはどれですか？',
    choices:['ユーザープールはアプリのサインアップ・サインインを管理するディレクトリであり、IDプールは認証済みユーザー等に一時的なAWS認証情報を発行してAWSリソースへのアクセスを許可する仕組みである','ユーザープールは常に無料で、IDプールは常に有料である','IDプールはActive Directoryと同一の機能である','ユーザープールはAWSリソースへの一時的なアクセス権限の発行のみを行う'], correct:[0],
    why:['正しい。ユーザープールはサインアップ・サインインを管理するユーザーディレクトリで、IDプールは認証済みのユーザーなどに一時的なAWS認証情報を発行し、S3やDynamoDB等のAWSリソースへのアクセスを許可する仕組みです。','誤り。いずれも使用量に応じて料金が発生する場合があります。','誤り。IDプールとAWS Directory Serviceは別の仕組みです。','誤り。一時的なAWS認証情報の発行を行うのはIDプールの役割です。']},
  {id:'p119', domain:'tech', type:'single', source:SOURCES.batch, text:'数千件規模のバッチジョブを、ジョブキューに基づいて必要な量・種類のコンピューティングリソースへ自動的に割り当てて実行したい場合、最も適したサービスはどれですか？',
    choices:['Amazon EventBridge','AWS Batch','Amazon API Gateway','AWS Step Functions'], correct:[1],
    why:['誤り。EventBridgeはイベントのルーティングを行うサービスで、バッチジョブのキューイングやリソース割り当てには特化していません。','正しい。AWS Batchは、送信されたバッチジョブの量や要件に応じて最適な量・種類のコンピューティングリソースを自動的にプロビジョニングして実行する、フルマネージドのバッチコンピューティングサービスです。','誤り。API GatewayはAPIの作成・公開・保護を行うサービスです。','誤り。Step Functionsは複数のAWSサービスを順序立てて実行するワークフローを構築するサービスで、大量バッチジョブの動的なリソース割り当てに特化したものではありません。']},
  {id:'p120', domain:'tech', type:'single', source:SOURCES.fsx, text:'Windows File ServerやLustreなど、人気のファイルシステムをベースにしたフルマネージドの共有ファイルストレージを、複数の種類から選んで利用したい場合、最も適したサービスはどれですか？',
    choices:['Amazon EBS','Amazon S3','Amazon FSx','Amazon EFS'], correct:[2],
    why:['誤り。EBSは単一のEC2インスタンスにアタッチするブロックストレージです。','誤り。S3はオブジェクトストレージであり、ファイルシステムとしては利用できません。','正しい。Amazon FSxは、Windows File Server・Lustre・NetApp ONTAP・OpenZFSといった人気のファイルシステムをベースにしたフルマネージドの共有ファイルストレージを、複数の種類から選んで利用できるサービスです。','誤り。EFSはAWSネイティブなLinux向けNFSファイルストレージで、Windows File ServerやLustre等の他のファイルシステムは提供しません。']},
  {id:'p121', domain:'tech', type:'multi', source:SOURCES.elasticache, text:'Amazon ElastiCacheの用途として正しいものを2つ選択してください。',
    choices:['オブジェクトを長期保存するためのアーカイブストレージ','仮想サーバーのOSパッチ管理','データベースへの問い合わせ結果をメモリ内にキャッシュし、読み取りレイテンシーを下げる','ウェブアプリケーションのセッション情報をメモリ内に保存し、高速に読み書きする'], correct:[2,3],
    why:['誤り。これはAmazon S3 Glacier等の用途です。','誤り。これはAWS Systems Managerの用途です。','正しい。ElastiCacheはRedisやMemcached互換のインメモリキャッシュを提供し、データベースへの問い合わせ結果をキャッシュして読み取りを高速化します。','正しい。ElastiCacheはセッション情報など頻繁にアクセスされるデータをメモリ内に保存し、高速に読み書きする用途にも使われます。']},
  {id:'p122', domain:'tech', type:'single', source:SOURCES.redshift, text:'複数のデータソースから集めた大量データを対象に、複雑な分析クエリやビジネスインテリジェンス(BI)処理を高速に実行したい場合、最も適したサービスはどれですか？',
    choices:['Amazon DynamoDB','Amazon RDS','Amazon ElastiCache','Amazon Redshift'], correct:[3],
    why:['誤り。DynamoDBはキーバリュー型のNoSQLデータベースで、大規模な分析クエリ(OLAP)には最適化されていません。','誤り。RDSはトランザクション処理(OLTP)向けのリレーショナルデータベースです。','誤り。ElastiCacheはインメモリキャッシュサービスで、データウェアハウス用途ではありません。','正しい。Amazon Redshiftは、大量データに対する複雑な分析クエリを高速に実行できるマネージド型のデータウェアハウスサービスです。']},
  {id:'p123', domain:'billing', type:'single', source:SOURCES.costmgmt, text:'「今月のコストが先月に比べてどのサービスでどれだけ増減したか」を分析したい場合、最も適したサービスはどれですか？',
    choices:['AWS Cost Explorer','AWS Budgets','AWS Organizations','AWS Artifact'], correct:[0],
    why:['正しい。Cost Explorerは、サービス別・期間別にコストと使用量の傾向を可視化・分析できるツールです。','誤り。Budgetsは予算の閾値超過時にアラートを送るツールで、傾向分析が主目的ではありません。','誤り。Organizationsは複数アカウントの一括管理・一括請求を行うサービスです。','誤り。Artifactはコンプライアンス関連レポートを提供するサービスです。']},
  {id:'p124', domain:'billing', type:'multi', source:SOURCES.free, text:'現在のAWS Free Tier（無料利用枠）を構成する要素として正しいものを2つ選択してください。',
    choices:['一部のサービスで常に無料で利用できる範囲（Always Free）','すべてのAWSサービスが期間を問わず常に無料になる仕組み','サポートプランの費用が無料になる仕組み（Basic Support）','新規アカウント向けに提供される、一定期間・一定額の無料クレジット'], correct:[0,3],
    why:['正しい。一部のサービスには期間に関わらず常に無料で使える範囲（Always Free）があります。','誤り。すべてのサービスが無期限に無料になるわけではありません。','誤り。Basic Supportが無料なのはサポートプランの話であり、Free Tierの構成要素とは別に説明されます。','正しい。新規アカウント向けに、一定期間・一定額の無料クレジットが提供される区分があります。']},

  // --- 追加分（Well-Architected Tool・ハイブリッド・Access Analyzer・分析系・Capacity Reservation） ---
  {id:'p125', domain:'concepts', type:'single', source:SOURCES.watool, text:'AWS Well-Architected FrameworkとAWS Well-Architected Toolの関係として正しいものはどれですか？',
    choices:['Frameworkはベストプラクティスの指針であり、Toolはその指針に基づいてワークロードをレビュー・評価するための無料の実践ツールである','Frameworkは有料サービスであり、Toolはその契約状況を管理する画面である','Toolを使うとAWSの利用料金が自動的に割引される','Frameworkはセキュリティのみを扱うドキュメントであり、Toolはコストのみを扱う'], correct:[0],
    why:['正しい。Well-Architected Frameworkは6つの柱からなるベストプラクティスの指針であり、Well-Architected Toolはその指針に基づいてワークロードをレビュー・評価できる無料のツールです。','誤り。Well-Architected Frameworkはドキュメント・考え方であり、有料サービスではありません。','誤り。利用料金の割引とは無関係です。','誤り。Frameworkは運用上の優秀性・セキュリティ・信頼性・パフォーマンス効率・コスト最適化・持続可能性という6つの柱を扱う包括的な指針です。']},
  {id:'p126', domain:'concepts', type:'single', source:SOURCES.outposts, text:'オンプレミスのデータセンター内に、AWSのコンピューティング・ストレージ機能やAPIをそのまま拡張して、AWSリージョンの一部として運用したい場合、最も適したサービスはどれですか？',
    choices:['AWS Direct Connect','AWS Outposts','Amazon VPC','AWS Snow Family'], correct:[1],
    why:['誤り。Direct ConnectはオンプレミスとAWS間の専用線接続を提供しますが、オンプレミスにAWSのインフラそのものを拡張するものではありません。','正しい。AWS Outposts（ラック）は、AWSのコンピューティング・ストレージ機能をオンプレミスのデータセンターに拡張し、AWSが運用・監視するマネージドサービスです。','誤り。VPCはAWSクラウド内の論理的に分離されたネットワークであり、オンプレミスへの拡張機能ではありません。','誤り。Snow Familyは主にデータ移行やエッジコンピューティング向けの物理デバイス群であり、AWSリージョンの一部として常設運用するものではありません。']},
  {id:'p127', domain:'concepts', type:'single', source:SOURCES.hybridCloud, text:'クラウドの導入モデルのうち、「ハイブリッドクラウド」の説明として正しいものはどれですか？',
    choices:['すべてのワークロードを単一のクラウドプロバイダーに統合すること','オンプレミス環境を一切使わず、すべてをクラウド上で運用すること','オンプレミス環境とクラウド環境を接続・統合し、両方を組み合わせて運用すること','複数のクラウドプロバイダーのサービスを同時に利用すること'], correct:[2],
    why:['これは単一クラウドへの集約の説明であり、ハイブリッドクラウドの定義ではありません。','これはクラウドへの全面移行の説明であり、ハイブリッドクラウドとは異なります。','正しい。ハイブリッドクラウドは、オンプレミス環境とクラウド環境を接続・統合し、両方の長所を組み合わせて運用するモデルです。','これはマルチクラウドの説明であり、ハイブリッドクラウドとは異なる概念です。']},
  {id:'p128', domain:'security', type:'single', source:SOURCES.accessAnalyzer, text:'S3バケットなどのリソースが、意図せず別のAWSアカウントや公衆からアクセス可能な状態になっていないかを自動的に分析したい場合、最も適したサービスはどれですか？',
    choices:['AWS Config','Amazon GuardDuty','AWS Shield','AWS IAM Access Analyzer'], correct:[3],
    why:['誤り。AWS Configはリソースの構成変更履歴を記録しますが、外部共有の検出に特化したサービスではありません。','誤り。GuardDutyは脅威インテリジェンスや機械学習を用いた不審なアクティビティの検知が主目的です。','誤り。ShieldはDDoS攻撃からの保護が目的です。','正しい。IAM Access Analyzerは論理推論を用いてリソースベースポリシーを分析し、外部アカウントや公衆への意図しない共有を検出します。']},
  {id:'p129', domain:'security', type:'single', source:SOURCES.securityHub, text:'GuardDuty・Inspector・Macieなど複数のセキュリティサービスの検出結果を一つの場所に集約し、セキュリティ状態を統合的に把握したい場合、最も適したサービスはどれですか？',
    choices:['AWS Security Hub','AWS Config','AWS Artifact','AWS Trusted Advisor'], correct:[0],
    why:['正しい。AWS Security Hubは、GuardDuty・Inspector・Macieなど複数のセキュリティサービスやパートナー製品の検出結果を集約し、セキュリティ状態を統合的に可視化するサービスです。','誤り。Configはリソースの構成変更履歴に特化しており、複数セキュリティサービスの検出結果集約を主目的としたサービスではありません。','誤り。Artifactはコンプライアンスレポートの取得が目的です。','誤り。Trusted Advisorはコスト・パフォーマンス・セキュリティ等の推奨事項提示が目的で、複数セキュリティサービスの検出結果集約には特化していません。']},
  {id:'p130', domain:'security', type:'multi', source:SOURCES.organizations, text:'AWS Organizationsのサービスコントロールポリシー(SCP)に関する説明として正しいものを2つ選択してください。',
    choices:['SCPはIAMポリシーの代わりに、ユーザーへ直接アクセス許可を付与する仕組みである','SCPは、OU(組織単位)やアカウントに適用し、メンバーアカウントで許可可能な権限の上限(ガードレール)を設定するもので、権限を直接付与するものではない','SCPを設定すると、メンバーアカウントの請求が自動的に一つにまとめられる(一括支払い)','管理アカウント(Organizationsの管理アカウント)には、デフォルトでSCPの制限が適用されない'], correct:[1,3],
    why:['誤り。SCPは権限を直接付与する仕組みではなく、許可できる権限の上限を定めるガードレールです。実際の権限付与はIAMポリシーが行います。','正しい。SCPはOUやアカウントに適用し、メンバーアカウントで許可可能な権限の上限を設定するガードレールであり、権限を直接付与するものではありません。','誤り。請求の一括化(Consolidated Billing)はSCPとは別の機能です。','正しい。管理アカウントには、デフォルトでSCPの制限は適用されません。']},
  {id:'p131', domain:'tech', type:'single', source:SOURCES.eks, text:'Kubernetesを使ってコンテナを運用したい場合、最も適したサービスはどれですか？',
    choices:['Amazon ECS','Amazon EKS','AWS Lambda','Amazon Lightsail'], correct:[1],
    why:['誤り。ECSはAWS独自のコンテナオーケストレーションサービスで、Kubernetesではなく独自のオーケストレーション方式を使用します。','正しい。Amazon EKS(Elastic Kubernetes Service)は、Kubernetesの管理コントロールプレーンの運用・保守を行うマネージドサービスで、既存のKubernetesツール・プラグインをそのまま利用できます。','誤り。Lambdaはサーバーレスのコード実行サービスで、Kubernetesクラスタの運用機能はありません。','誤り。Lightsailは、あらかじめ構成が用意されたシンプルな仮想サーバー等を提供するサービスで、Kubernetesオーケストレーションには特化していません。']},
  {id:'p132', domain:'tech', type:'single', source:SOURCES.glue, text:'異なるデータソースからデータを収集し、形式を変換・整形してデータレイクやデータウェアハウスに読み込む(ETL)処理を、サーバーを管理せずに行いたい場合、最も適したサービスはどれですか？',
    choices:['Amazon Athena','Amazon QuickSight','AWS Glue','AWS Storage Gateway'], correct:[2],
    why:['誤り。Athenaは既に保存されたデータに対してSQLクエリを実行する分析サービスであり、ETL処理自体が主目的ではありません。','誤り。QuickSightはBIダッシュボードの作成・可視化を行うサービスです。','正しい。AWS Glueは、データの検出・変換・結合(ETL)をサーバーレスで行うデータ統合サービスで、処理結果をデータカタログに登録しAthena等から利用できます。','誤り。Storage Gatewayはオンプレミスとクラウドストレージを接続するハイブリッドストレージサービスです。']},
  {id:'p133', domain:'tech', type:'single', source:SOURCES.quicksight, text:'収集・整形したデータを使って、インタラクティブなダッシュボードを作成し、ビジネス上の意思決定に役立てたい場合、最も適したサービスはどれですか？',
    choices:['AWS Glue','Amazon Athena','AWS Storage Gateway','Amazon QuickSight'], correct:[3],
    why:['誤り。Glueはデータの収集・変換・結合(ETL)が主目的のサービスです。','誤り。AthenaはS3上のデータにSQLクエリを実行する分析サービスで、ダッシュボード作成機能自体は主目的ではありません。','誤り。Storage Gatewayはオンプレミスとクラウドストレージを接続するハイブリッドストレージサービスです。','正しい。Amazon QuickSightは、データを可視化してインタラクティブなダッシュボードやレポートを作成できるサーバーレスのビジネスインテリジェンス(BI)サービスです。']},
  {id:'p134', domain:'tech', type:'single', source:SOURCES.storagegateway, text:'オンプレミスのアプリケーションからクラウド上のストレージへ、iSCSI・SMB・NFSなどの標準プロトコルを使って低レイテンシーにアクセスし、オンプレミスとAWSのストレージをシームレスに統合したい場合、最も適したサービスはどれですか？',
    choices:['AWS Storage Gateway','Amazon FSx','Amazon EBS','AWS Direct Connect'], correct:[0],
    why:['正しい。AWS Storage Gatewayは、オンプレミスとAWSクラウド間のハイブリッドストレージサービスで、iSCSI・SMB・NFS等の標準プロトコルを使い、よく使うデータをオンプレミスにキャッシュしながらAWSのストレージをシームレスに利用できます。','誤り。FSxはフルマネージドの共有ファイルストレージそのものを提供するサービスで、オンプレミスとのゲートウェイ機能に特化したものではありません。','誤り。EBSはEC2インスタンス専用のブロックストレージです。','誤り。Direct Connectは専用線によるネットワーク接続を提供しますが、ストレージプロトコルの変換機能は持ちません。']},
  {id:'p135', domain:'billing', type:'single', source:SOURCES.capacityReservation, text:'特定のアベイラビリティーゾーンで、必要な時にEC2インスタンスを確実に起動できるよう、あらかじめ指定したインスタンスタイプの容量を確保しておきたい場合、最も適した仕組みはどれですか？',
    choices:['スポットインスタンス','On-Demand Capacity Reservation','Savings Plans','AWS Budgets'], correct:[1],
    why:['誤り。スポットインスタンスは空きキャパシティを利用するため、容量の確保を保証するものではありません。','正しい。On-Demand Capacity Reservationは、特定のAZで指定したインスタンスタイプの容量を必要な期間だけ確保できる仕組みです。料金的な割引は提供されず、オンデマンド料金が基準となります。','誤り。Savings Plansは使用量契約による割引を得る料金モデルで、容量そのものを確保する仕組みではありません。','誤り。Budgetsは予算の設定とアラート通知が目的のサービスです。']},
  {id:'p136', domain:'billing', type:'single', source:SOURCES.support, text:'AWSサポートプランに関する記述として正しいものはどれですか？',
    choices:['上位プランに加入しない限り、Basic Supportも有料契約が必要である','全てのサポートプランで、技術的な問い合わせに対する応答時間は同一である','Basic Supportはすべてのアカウントで自動的に提供され、請求・アカウント関連のサポートやドキュメント・コミュニティフォーラムへのアクセスなどを無料で利用できる','サポートプランは年単位の契約が必須で、月単位では解約できない'], correct:[2],
    why:['誤り。Basic Supportはすべてのアカウントで自動的に無料提供され、追加の契約は不要です。','誤り。応答時間はプランによって異なり、上位プランほど短い応答時間が設定されています。','正しい。Basic Supportは全アカウントに自動的に無料で提供され、請求・アカウントに関するサポートやドキュメント、AWSの状態に関する情報、コミュニティフォーラムへのアクセス等を利用できます。','誤り。有料のサポートプランは月単位の契約で、必要に応じて変更・解約が可能です。']},
  {id:'p137', domain:'billing', type:'single', source:SOURCES.marketplace, text:'サードパーティが提供するソフトウェア(AMIやSaaS製品など)を購入・デプロイし、その利用料金をAWSの利用料金と合わせて一つの請求にまとめたい場合、最も適したサービスはどれですか？',
    choices:['AWS Budgets','AWS Cost Explorer','AWS Organizations','AWS Marketplace'], correct:[3],
    why:['誤り。Budgetsは予算設定とアラート通知が目的です。','誤り。Cost Explorerはコストと使用量の分析・可視化が目的です。','誤り。Organizationsは複数アカウントの管理・一括支払いが目的ですが、サードパーティ製品の購入・カタログ機能は持ちません。','正しい。AWS Marketplaceは、サードパーティが提供するソフトウェア(AMI・SaaS等)を検索・購入・デプロイできるカタログサービスで、利用料金はAWSの利用料金と合わせて請求されます。']},

  // --- 追加分（Control Tower・PrivateLink・GuardDuty比較・WorkSpaces・DataSync・OpenSearch・X-Ray・Comprehend・Cost Anomaly Detection） ---
  {id:'p138', domain:'concepts', type:'single', source:SOURCES.controlTower, text:'企業が複数のAWSアカウントを新規に展開する際、セキュリティ・コンプライアンスのベストプラクティスに基づいた「ランディングゾーン」を短時間で自動構築し、ガードレール(統制)を適用したい。最も適切なサービスはどれですか？',
    choices:['AWS Control Tower','AWS Trusted Advisor','AWS Budgets','Amazon Inspector'], correct:[0],
    why:['正しい。AWS Control Towerは、AWS Organizations等を組み合わせ、ベストプラクティスに基づくマルチアカウントのランディングゾーンをガードレール付きで自動構築します。','誤り。Trusted Advisorはベストプラクティスの推奨事項を提示しますが、ランディングゾーンの自動構築は行いません。','誤り。Budgetsは予算アラートのサービスで、マルチアカウント統制とは無関係です。','誤り。Inspectorは脆弱性スキャンサービスで、アカウント統制とは無関係です。']},
  {id:'p139', domain:'concepts', type:'single', source:SOURCES.caf, text:'AWS Cloud Adoption Framework (AWS CAF) における「ガバナンス」の視点が主に扱う内容として最も適切なものはどれですか？',
    choices:['アプリケーションコードの実装パターン','ビジネス目標に沿ってリスク・コンプライアンスを管理し、クラウド利用に関する意思決定プロセスを整備すること','EC2インスタンスのOSパッチ適用手順','ネットワークの物理的な配線設計'], correct:[1],
    why:['誤り。これはAWS CAFの「プラットフォーム」や「運用」の視点に近い技術的な内容です。','正しい。AWS CAFの「ガバナンス」の視点は、ビジネス目標に沿ったリスク管理・コンプライアンス・意思決定プロセスの整備を扱います。','誤り。これは運用上の技術的な作業であり、ガバナンスの視点とは異なります。','誤り。これはAWSが責任を持つ物理的インフラの領域です。']},
  {id:'p140', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'クラウドコンピューティングの6つのメリットのうち、「キャパシティ(容量)の予測が不要になる」という点を最もよく表している説明はどれですか？',
    choices:['データセンターの運用費を変動費化できる','世界中の複数リージョンに数分でデプロイできる','将来の需要を事前に予測して機器を購入する必要がなく、必要な分だけリソースを増減できる','固定費を可変費に転換できる'], correct:[2],
    why:['誤り。これは「固定費を可変費に」というメリットの説明です。','誤り。これは「数分で世界中にデプロイ」というメリットの説明です。','正しい。クラウドでは需要予測が不要で、必要なときに必要な分だけキャパシティを確保・解放できます。','誤り。これは別のメリット（資本費用の削減）の説明です。']},
  {id:'p141', domain:'security', type:'single', source:SOURCES.privatelink, text:'オンプレミスのネットワークを経由せず、VPC内から特定のAWSサービスやパートナーが提供するサービスに、インターネットを経由せずプライベートに接続したい。最も適切な方法はどれですか？',
    choices:['AWS Direct Connect','AWS Site-to-Site VPN','インターネットゲートウェイ経由の接続','AWS PrivateLink（VPCインターフェースエンドポイント）'], correct:[3],
    why:['誤り。Direct ConnectはオンプレミスとAWS間を専用線で接続するサービスで、今回のようなVPC内からサービスへの接続ではありません。','誤り。Site-to-Site VPNもオンプレミスとVPC間の接続であり、要件に合いません。','誤り。インターネットゲートウェイ経由ではインターネットを経由してしまいます。','正しい。AWS PrivateLinkはVPCエンドポイントを使い、インターネットを経由せずにAWSサービスやパートナーサービスにプライベート接続できます。']},
  {id:'p142', domain:'security', type:'single', source:SOURCES.guardduty, text:'VPCフローログやDNSログ、CloudTrailイベントなどを継続的に分析し、機械学習や脅威インテリジェンスを使って悪意のある活動や不審な挙動を自動的に検知したい。最も適切なサービスはどれですか？',
    choices:['Amazon GuardDuty','AWS Security Hub','Amazon Detective','AWS Config'], correct:[0],
    why:['正しい。GuardDutyはVPCフローログ・DNSログ・CloudTrail等を機械学習と脅威インテリジェンスで分析し、脅威を自動検知する脅威検出サービスです。','誤り。Security Hubは複数のセキュリティサービスの検出結果を集約・一元管理するサービスで、検知そのものは行いません。','誤り。Detectiveは検知後の原因調査・可視化を支援するサービスです。','誤り。Configはリソース設定の記録・評価を行うサービスで、脅威検知が主目的ではありません。']},
  {id:'p143', domain:'security', type:'single', source:SOURCES.secretsmanager, text:'データベースの認証情報(パスワード)を安全に保管し、自動的にローテーション(定期的な変更)させたい場合、最も適切なサービスはどれですか？',
    choices:['AWS KMS','AWS Secrets Manager','AWS CloudHSM','Amazon Macie'], correct:[1],
    why:['誤り。KMSは暗号化キーの作成・管理を行うサービスで、認証情報のローテーション機能自体は持ちません。','正しい。Secrets Managerはデータベース認証情報などのシークレットを安全に保管し、自動ローテーションさせることができます。','誤り。CloudHSMは専用ハードウェアでキーを管理するサービスで、シークレットのローテーションは主目的ではありません。','誤り。MacieはS3内の機密データを検出するサービスで、認証情報管理とは異なります。']},
  {id:'p144', domain:'tech', type:'single', source:SOURCES.workspaces, text:'社員が自宅や外出先の様々なデバイスから、会社が管理するセキュアな仮想デスクトップ環境にアクセスできるようにしたい。物理的なPCの調達・管理の手間を減らしたい場合、最も適切なサービスはどれですか？',
    choices:['Amazon EC2','AWS Fargate','Amazon WorkSpaces','AWS Lambda'], correct:[2],
    why:['誤り。EC2は仮想サーバーですが、仮想デスクトップ(DaaS)専用の管理機能は持ちません。','誤り。Fargateはコンテナ向けのサーバーレスコンピューティングサービスです。','正しい。Amazon WorkSpacesはマネージド型の仮想デスクトップ(DaaS)サービスで、様々なデバイスから安全にアクセスできます。','誤り。Lambdaはイベント駆動型のサーバーレスコンピューティングサービスです。']},
  {id:'p145', domain:'tech', type:'single', source:SOURCES.datasync, text:'オンプレミスのファイルサーバーにある大量のデータを、ネットワーク経由で安全かつ高速にAmazon S3へ移行し、その後も定期的に同期したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Snowball','AWS Direct Connect','AWS Database Migration Service (DMS)','AWS DataSync'], correct:[3],
    why:['誤り。Snowballは物理デバイスを使ったオフラインでの大容量データ輸送サービスで、ネットワーク経由の継続的な同期には使いません。','誤り。Direct Connectはネットワーク接続サービスであり、データ転送・同期を自動化する機能自体は持ちません。','誤り。DMSはデータベースの移行・レプリケーション用のサービスで、ファイルサーバーのデータ移行には使いません。','正しい。AWS DataSyncはオンプレミスとAWSストレージ(S3等)間のデータ転送・同期をネットワーク経由で高速かつ安全に行うサービスです。']},
  {id:'p146', domain:'tech', type:'single', source:SOURCES.opensearch, text:'アプリケーションから出力される大量のログデータをリアルタイムに検索・分析し、運用監視用のダッシュボードを構築したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon OpenSearch Service','Amazon Redshift','Amazon Athena','Amazon DynamoDB'], correct:[0],
    why:['正しい。Amazon OpenSearch Serviceはログ分析やリアルタイム検索・可視化のダッシュボード構築に適したマネージド型の検索・分析サービスです。','誤り。Redshiftはデータウェアハウスで、大規模なバッチ分析向けのサービスです。','誤り。AthenaはS3上のデータにSQLクエリを実行する分析サービスで、リアルタイムダッシュボード用途には向きません。','誤り。DynamoDBはNoSQLデータベースで、ログ検索・分析機能は持ちません。']},
  {id:'p147', domain:'tech', type:'single', source:SOURCES.xray, text:'複数のマイクロサービスで構成されたアプリケーションで、リクエストがどのサービスを経由し、どこで遅延やエラーが発生しているかを可視化して分析したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon CloudWatch','AWS X-Ray','AWS CloudTrail','AWS Config'], correct:[1],
    why:['誤り。CloudWatchはメトリクス監視・ログ収集が主目的で、リクエスト単位の分散トレーシングはX-Rayの役割です。','正しい。AWS X-Rayは、分散アプリケーション内でのリクエストの経路を追跡し、遅延やエラーの発生箇所を可視化・分析できます。','誤り。CloudTrailはAPIコールの履歴（誰が何をしたか）を記録するサービスです。','誤り。Configはリソース設定の変更履歴を記録・評価するサービスです。']},
  {id:'p148', domain:'tech', type:'multi', source:SOURCES.comprehend, text:'Amazon Comprehendが提供する機能として正しいものはどれですか？（2つ選択）',
    choices:['画像内の物体やシーンを検出する','テキストから感情(ポジティブ/ネガティブ等)を分析する','音声をテキストに変換する','テキストからエンティティ(人名・組織名等)やキーフレーズを抽出する'], correct:[1,3],
    why:['誤り。これはAmazon Rekognitionの機能です。','正しい。Amazon Comprehendは自然言語処理(NLP)により、テキストの感情分析ができます。','誤り。これはAmazon Transcribeの機能です。','正しい。Amazon Comprehendはテキストからエンティティやキーフレーズを抽出する機能も提供します。']},
  {id:'p149', domain:'billing', type:'single', source:SOURCES.costAnomalyDetection, text:'日々のAWS利用料金について、手動で閾値を設定せずに、機械学習によって通常の利用パターンから外れた異常なコストの急増を自動的に検知し、メールで通知を受け取りたい場合、最も適切なサービスはどれですか？',
    choices:['AWS Budgets','AWS Cost Explorer','AWS Cost Anomaly Detection','AWS Trusted Advisor'], correct:[2],
    why:['誤り。Budgetsは利用者が手動で設定した予算の閾値に基づいてアラートを送る仕組みです。','誤り。Cost Explorerは過去のコスト分析・将来予測のための可視化ツールで、異常検知を自動で行う主目的の機能ではありません。','正しい。AWS Cost Anomaly Detectionは機械学習を使い、閾値を手動設定せずに異常なコストパターンを自動検知し通知します。','誤り。Trusted Advisorはベストプラクティスに基づく推奨事項を提示するサービスです。']},
  {id:'p150', domain:'billing', type:'single', source:SOURCES.pricing, text:'特定のインスタンスファミリーやリージョンに縛られず、EC2・Fargate・Lambdaなど複数のコンピューティングサービスを横断して、一定の利用コミットメント（USD/時間）に対する割引を受けたい場合、最も適切な購入オプションはどれですか？',
    choices:['リザーブドインスタンス','Savings Plans','スポットインスタンス','On-Demand Capacity Reservation'], correct:[1],
    why:['誤り。リザーブドインスタンスは基本的に特定のインスタンスファミリー・リージョンに対する予約であり、サービス横断の柔軟性はSavings Plansより低いです。','正しい。Savings PlansはEC2・Fargate・Lambda等を横断して、一定の利用コミットメントに対する割引を受けられる購入オプションです。','誤り。スポットインスタンスは空き容量を活用した大幅割引ですが、中断されるリスクがあり、コミットメント型の割引ではありません。','誤り。On-Demand Capacity Reservationは容量確保が目的で、料金の割引は提供しません。']},
  {id:'p151', domain:'concepts', type:'single', source:SOURCES.migrationStrategies, text:'既存のオンプレミスのアプリケーションを、コードをほとんど変更せずにそのままAmazon EC2に移行する移行戦略は何と呼ばれますか？',
    choices:['リプラットフォーム(Replatform)','リホスト(Rehost)','リファクタ/リアーキテクト(Refactor/Re-architect)','リパーチェス(Repurchase)'], correct:[1],
    why:['誤り。リプラットフォームは、移行時にOSやデータベースエンジンなど一部のコンポーネントを最適化する戦略で、コードを変更しない「そのまま移行」とは異なります。','正しい。リホストは「リフト&シフト」とも呼ばれ、アプリケーションのコードをほとんど変更せずにクラウドへそのまま移行する戦略です。','誤り。リファクタ/リアーキテクトは、クラウドネイティブな機能を活用するためにアプリケーションの設計自体を変更する戦略です。','誤り。リパーチェスは、既存のアプリケーションを捨てて別のSaaS製品に置き換える戦略です。']},
  {id:'p152', domain:'concepts', type:'single', source:SOURCES.migrationStrategies, text:'移行戦略の一つ「リプラットフォーム(Replatform)」が適しているケースとして最も適切なものはどれですか？',
    choices:['自前で運用しているMySQLデータベースの運用負荷を減らすため、アプリケーションのコードはそのままにAmazon RDS for MySQLへ移行したい','アプリケーションをそのままの構成でクラウドへ移行し、できるだけ早く移行を完了させたい','使われなくなった古いアプリケーションを完全に廃止したい','SaaS製品に置き換えて自社開発をやめたい'], correct:[0],
    why:['正しい。リプラットフォームは、アプリケーションのコアは変更せず、自前運用のデータベース等をRDSのようなマネージド型サービスに置き換えることでクラウドの利点を活かす戦略です。','これはリホスト(Rehost)が適したケースです。','これはリタイア(Retire)が適したケースです。','これはリパーチェス(Repurchase)が適したケースです。']},
  {id:'p153', domain:'concepts', type:'single', source:SOURCES.migrationStrategies, text:'移行の優先度が低く、現時点では移行せずオンプレミスに残しておき、将来再検討することにしたアプリケーションに適した移行戦略を何と呼びますか？',
    choices:['リホスト(Rehost)','リタイア(Retire)','リテイン(Retain)','リロケート(Relocate)'], correct:[2],
    why:['誤り。リホストは実際に移行を行う戦略であり、「移行せず残しておく」こととは異なります。','誤り。リタイアは、不要なアプリケーションを完全に廃止する戦略で、「将来再検討のために残す」こととは異なります。','正しい。リテインは、現時点では移行せずオンプレミスに残し、将来再検討する戦略です。','誤り。リロケートは、ハイパーバイザーレベルでインフラをそのままクラウドに移設する戦略で、オンプレミスに残すこととは異なります。']},
  {id:'p154', domain:'concepts', type:'single', source:SOURCES.migrationStrategies, text:'移行戦略の一つである「リロケート(Relocate)」の説明として正しいものはどれですか？',
    choices:['アプリケーションを同等機能の別製品(多くはSaaS)に乗り換える','VMware Cloud on AWS等を利用して、アプリケーションを変更せずにインフラをそのままクラウドに移動する','使われていないアプリケーションを完全に廃止する','アプリケーションのアーキテクチャを大幅に変更し、クラウドネイティブな機能を活用するよう作り直す'], correct:[1],
    why:['誤り。これは「リパーチェス(Repurchase)」の説明です。','正しい。リロケートは、VMware Cloud on AWSなどを使い、アプリケーションやインフラをほとんど変更せずにクラウドへ移動する戦略です。','誤り。これは「リタイア(Retire)」の説明です。','誤り。これは「リファクタ(Refactor)」の説明です。']},
  {id:'p155', domain:'concepts', type:'single', source:SOURCES.migrationStrategies, text:'移行戦略の一つである「リファクタリング / リアーキテクト(Refactor / Re-architect)」の説明として正しいものはどれですか？',
    choices:['既存のアプリケーションを同等機能を持つ別の製品（多くはSaaS）に置き換える','クラウドネイティブな機能（サーバーレスやマネージドサービス等）を活用するために、アプリケーションの一部を再設計・再構築する','アプリケーションのコードをほとんど変更せずそのままクラウドに移す','使用率が低く今後利用予定のないアプリケーションを廃止する'], correct:[1],
    why:['誤り。これは「リパーチェス(Repurchase)」の説明です。','正しい。リファクタリング/リアーキテクトは、クラウドネイティブな機能を活用して新しい機能や性能を実現するために、アプリケーションの一部やアーキテクチャ自体を再設計・再構築する移行戦略です。','誤り。これは「リホスト(Rehost)」の説明です。','誤り。これは「リタイア(Retire)」の説明です。']},
  {id:'p156', domain:'security', type:'single', source:SOURCES.accessAnalyzer, text:'S3バケットのバケットポリシーやIAMポリシーの設定ミスにより、意図せず外部(インターネットやアカウント外)からアクセス可能になっているリソースがないかを自動的に検出したい場合、最も適切なサービスはどれですか？',
    choices:['AWS IAM Access Analyzer','Amazon Macie','Amazon GuardDuty','AWS CloudTrail'], correct:[0],
    why:['正しい。IAM Access Analyzerは、論理的な推論(Automated Reasoning)を使って、S3バケットなどのリソースが意図せず外部やアカウント外からアクセス可能になっていないかを検出します。','誤り。Amazon Macieは、S3内の機密データ(個人情報等)の検出に特化したサービスです。','誤り。Amazon GuardDutyは、不審なAPIコールやネットワークアクティビティなど脅威検出に特化したサービスです。','誤り。AWS CloudTrailはAPIコールの記録・監査を行うサービスであり、アクセス設定の分析機能ではありません。']},
  {id:'p157', domain:'security', type:'single', source:SOURCES.accessAnalyzer, text:'企業のセキュリティ担当者が、自社のS3バケットやIAMロールが誤って外部アカウントや公開状態で共有されていないかを継続的に検出したいと考えている。最も適切なサービスはどれですか？',
    choices:['Amazon Inspector','AWS Shield','Amazon GuardDuty','AWS IAM Access Analyzer'], correct:[3],
    why:['誤り。Amazon Inspectorは、EC2やコンテナイメージ等の脆弱性スキャンを行うサービスです。','誤り。AWS ShieldはDDoS攻撃からの保護を行うサービスです。','誤り。Amazon GuardDutyは、ログを分析して脅威となる挙動を検知するサービスで、リソース共有設定の分析に特化したものではありません。','正しい。AWS IAM Access Analyzerは、論理推論を用いてS3バケットやIAMロール等が組織外や想定外のエンティティに共有されていないかを検出します。']},
  {id:'p158', domain:'tech', type:'single', source:SOURCES.dms, text:'オンプレミスで稼働している商用データベースを、ダウンタイムを最小限に抑えながらAmazon Auroraへ移行し、移行中も継続的にデータを同期したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Database Migration Service (AWS DMS)','AWS Snowball','AWS DataSync','AWS Direct Connect'], correct:[0],
    why:['正しい。AWS DMSは、リレーショナルデータベースなどのデータストアを、ダウンタイムを最小限に抑えながら移行し、継続的なデータ同期(レプリケーション)も行えるサービスです。','誤り。AWS Snowballは、大量データを物理デバイスで輸送するオフラインのデータ転送サービスであり、継続的なデータベース同期には使いません。','誤り。AWS DataSyncは主にファイルストレージ間のデータ転送・同期サービスであり、データベースのスキーマ変換や継続的なレプリケーションには特化していません。','誤り。AWS Direct Connectは、オンプレミスとAWSを専用線で接続するネットワークサービスであり、データベース移行機能そのものではありません。']},
  {id:'p159', domain:'tech', type:'single', source:SOURCES.dms, text:'本番稼働中のオンプレミスのリレーショナルデータベースを、ダウンタイムを最小限に抑えながらAmazon RDSへ移行し、移行完了まで継続的にデータを同期したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Snowball','AWS DataSync','AWS Storage Gateway','AWS Database Migration Service (DMS)'], correct:[3],
    why:['誤り。Snowballは大容量データの物理的な一括転送が主目的で、継続的なデータベース同期には向きません。','誤り。DataSyncはファイルデータの転送・同期が主目的で、リレーショナルデータベースの継続的なレプリケーションには向きません。','誤り。Storage Gatewayはハイブリッドストレージ接続が目的で、データベース移行機能ではありません。','正しい。AWS DMSは、稼働中のデータベースから継続的に変更を複製（ongoing replication）しながら、ダウンタイムを最小限に抑えて移行できます。']},
  {id:'p160', domain:'concepts', type:'single', source:SOURCES.caf, text:'AWS Cloud Adoption Framework (AWS CAF)の「ピープル(人材)」の視点が主に対象とする領域はどれですか？',
    choices:['ネットワーク構成やインフラの技術的な設計','クラウド利用料金の予算管理','組織の役割・スキル・人材育成など、クラウド導入に伴う人材・組織文化の変革','セキュリティインシデントへの対応手順'], correct:[2],
    why:['誤り。これはAWS CAFのプラットフォームの視点に近い内容です。','誤り。これはAWS CAFのガバナンスの視点に近い内容です。','正しい。AWS CAFのピープルの視点は、クラウド導入に伴う役割・スキル・組織文化の変革など、人材・組織面の観点を扱います。','誤り。これはAWS CAFのセキュリティの視点に近い内容です。']},
  {id:'p161', domain:'concepts', type:'single', source:SOURCES.caf, text:'AWS Cloud Adoption Framework (CAF) の「プラットフォーム」の視点が主に扱う内容として最も適切なものはどれですか？',
    choices:['クラウド利用に伴うリスク管理やポリシー整備など組織全体のガバナンス体制の構築','ITシステムの設計・構築に関するベストプラクティス（スケーラブルでクラウドネイティブなアーキテクチャの実現など）','従業員のクラウドスキル育成や組織体制の変更管理','セキュリティインシデントの監視・検知・対応体制の構築'], correct:[1],
    why:['これは「ガバナンス」の視点の内容です。','正しい。CAFの「プラットフォーム」の視点は、スケーラブルでクラウドネイティブなアーキテクチャの実現など、ITシステムの設計・構築に関するベストプラクティスを扱います。','これは「人材」の視点の内容です。','これは「セキュリティ」の視点の内容です。']},
  {id:'p162', domain:'concepts', type:'single', source:SOURCES.caf, text:'AWS Cloud Adoption Framework (AWS CAF) の「運用(Operations)」の視点が主に扱う内容として正しいものはどれですか？',
    choices:['クラウド導入に伴う組織文化や人材スキルの変革','ビジネス目標とIT投資の整合性の確保','クラウド上のワークロードを安定的に稼働・監視・保守するための運用プロセスとプラクティスの定義','アプリケーションやインフラの技術的な設計方針の策定'], correct:[2],
    why:['誤り。これはAWS CAFの「人材」の視点の内容です。','誤り。これはAWS CAFの「ビジネス」の視点の内容です。','正しい。AWS CAFの「運用」の視点は、クラウド上のワークロードを健全に運用し続けるためのプロセス・プラクティスの定義や、インシデント対応・変更管理などを扱います。','誤り。これはAWS CAFの「プラットフォーム」の視点の内容です。']},
  {id:'p163', domain:'concepts', type:'single', source:SOURCES.caf, text:'組織がクラウド導入を進める際に、AWS Cloud Adoption Framework (CAF)が示す「ガバナンス」の観点が主に扱う内容はどれですか？',
    choices:['EC2インスタンスのOSパッチ適用やネットワーク構成などの技術的な実装作業','クラウド利用に伴うリスク管理・コンプライアンス・コスト管理など、組織としての意思決定とプロセスの整備','データの暗号化アルゴリズムの選定など、セキュリティ技術の実装','アプリケーションの可用性を高めるための冗長構成の設計'], correct:[1],
    why:['誤り。これは主にCAFの「プラットフォーム」の観点が扱う技術的な実装作業です。','正しい。CAFのガバナンスの観点は、クラウド利用に伴うリスク管理・コンプライアンス・コスト管理など、組織としての意思決定とプロセスの整備を扱います。','誤り。これは主に「セキュリティ」の観点が扱う内容です。','誤り。これは主に「プラットフォーム」や「オペレーション」の観点が扱う技術的な設計です。']},
  {id:'p164', domain:'tech', type:'single', source:SOURCES.fsx, text:'Windows Server上で稼働するアプリケーションから、SMBプロトコルでアクセスできるマネージド型のファイルストレージが必要な場合、最も適切なサービスはどれですか？',
    choices:['Amazon EFS','Amazon FSx for Windows File Server','Amazon EBS','Amazon S3'], correct:[1],
    why:['誤り。Amazon EFSはLinux向けのNFSプロトコルを使ったマネージド型ファイルストレージであり、SMBには対応していません。','正しい。Amazon FSx for Windows File Serverは、SMBプロトコルでアクセスできるWindows向けのマネージド型ファイルストレージです。','誤り。Amazon EBSはEC2インスタンスにアタッチするブロックストレージであり、SMBでの共有アクセスには使えません。','誤り。Amazon S3はオブジェクトストレージであり、SMBファイル共有としては利用できません。']},
  {id:'p165', domain:'tech', type:'single', source:SOURCES.fsx, text:'Windowsベースのアプリケーションから、SMBプロトコルでアクセスできるマネージド型のファイルストレージが必要な場合、最も適切なサービスはどれですか？',
    choices:['Amazon EFS','Amazon S3','Amazon FSx for Windows File Server','Amazon EBS'], correct:[2],
    why:['誤り。Amazon EFSはLinuxベースのワークロード向けのNFSファイルシステムで、SMBには対応していません。','誤り。S3はオブジェクトストレージで、ファイルシステムとしてマウントする用途には適しません。','正しい。Amazon FSx for Windows File ServerはSMBプロトコルに対応したマネージド型のWindowsファイルサーバーです。','誤り。EBSは単一のEC2インスタンスにアタッチするブロックストレージです。']},
  {id:'p166', domain:'tech', type:'single', source:SOURCES.backup, text:'EC2・EBS・RDS・DynamoDB・EFSなど、サービスごとに個別にバックアップの設定を行う運用から、ポリシーベースでバックアップルールを一元的に定義・適用し、監査ログも集約したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Storage Gateway','AWS DataSync','AWS Backup','Amazon S3 Glacier'], correct:[2],
    why:['誤り。AWS Storage Gatewayは、オンプレミスとAWSストレージ間をハイブリッドに接続するサービスであり、複数AWSサービス横断のバックアップ一元管理機能ではありません。','誤り。AWS DataSyncは、オンプレミスとAWS間、またはAWSストレージ間のデータ転送・同期サービスです。','正しい。AWS Backupは、EC2・EBS・RDS・DynamoDB・EFSなど複数のAWSサービスにわたるバックアップポリシーを一つのコンソールで集中管理・自動化できます。','誤り。Amazon S3 Glacierは低コストのアーカイブ用ストレージクラスであり、バックアップの一元管理機能そのものではありません。']},
  {id:'p167', domain:'tech', type:'single', source:SOURCES.backup, text:'複数のAWSサービス（EC2、RDS、DynamoDB、EFSなど）に対するバックアップ処理を、サービスごとに個別のスクリプトを作らず、1つのコンソールでポリシーベースに一元管理したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon S3 Glacier','AWS Backup','AWS Storage Gateway','Amazon FSx'], correct:[1],
    why:['誤り。S3 Glacierは低コストのアーカイブストレージクラスで、バックアップの一元管理機能ではありません。','正しい。AWS Backupは、複数のAWSサービスに対するバックアップポリシーを1つのコンソールで一元的に作成・管理・監視できるフルマネージドサービスです。','誤り。Storage Gatewayはオンプレミスとクラウドをつなぐハイブリッドストレージサービスで、バックアップの一元管理が主目的ではありません。','誤り。FSxはマネージド型ファイルストレージサービスで、バックアップの一元管理機能ではありません。']},
  {id:'p168', domain:'billing', type:'single', source:SOURCES.budgets, text:'今月のAWS利用コストが、設定した予算の90%に達する見込みになった時点で、担当者にメール等で事前にアラートを送りたい場合、最も適切なサービスはどれですか？',
    choices:['AWS Cost Anomaly Detection','AWS Cost Explorer','AWS Budgets','AWS Trusted Advisor'], correct:[2],
    why:['誤り。AWS Cost Anomaly Detectionは、機械学習により通常のパターンから外れた異常なコストを検知するサービスで、あらかじめ設定した予算のしきい値に対するアラートとは異なります。','誤り。AWS Cost Explorerは、過去のコスト・使用量の可視化・分析を行うサービスで、予算アラートの設定機能ではありません。','正しい。AWS Budgetsは、独自の予算を設定し、実績コストや予測コストがしきい値(例: 予算の90%)に達した場合にアラートを送信できます。','誤り。AWS Trusted Advisorは、コスト最適化やセキュリティなど複数カテゴリのベストプラクティスチェックを行うサービスで、カスタム予算アラートの設定機能ではありません。']},
  {id:'p169', domain:'billing', type:'single', source:SOURCES.budgets, text:'月間のAWS利用コストが予算の80%に達した時点で、担当者にメールやSNS通知でアラートを送りたい場合、最も適切なサービスはどれですか？',
    choices:['AWS Cost Explorer','AWS Cost and Usage Report (CUR)','AWS Budgets','AWS Trusted Advisor'], correct:[2],
    why:['誤り。Cost Explorerはコストの可視化・分析・予測が主目的で、しきい値に基づく通知機能ではありません。','誤り。CURは詳細なコスト・使用量データをレポートとして出力する機能で、しきい値通知機能ではありません。','正しい。AWS Budgetsは、コストや使用量にしきい値を設定し、実際の値や予測値がそのしきい値に達した場合にメールやSNSで通知できます。','誤り。Trusted Advisorはベストプラクティスに基づく推奨事項を提示するサービスで、予算しきい値通知機能ではありません。']},
  {id:'p170', domain:'billing', type:'single', source:SOURCES.consolidatedBilling, text:'AWS Organizationsで複数のメンバーアカウントを管理している企業が、各アカウントの請求を1つにまとめ、さらに全アカウントの利用量を合算してボリュームディスカウントの対象にしたい場合、最も適切な機能はどれですか？',
    choices:['AWS RAMによるリソース共有','AWS IAM Identity Centerによるシングルサインオン','サービスコントロールポリシー(SCP)による権限制限','AWS Organizationsの一括支払い(Consolidated Billing)'], correct:[3],
    why:['誤り。AWS RAMはリソースの共有機能であり、請求の統合や割引のまとめとは異なります。','誤り。AWS IAM Identity Centerは複数アカウントへのシングルサインオンを実現する機能であり、請求の統合機能ではありません。','誤り。SCPはアカウントやOUに適用できる権限の上限を設定する機能であり、請求の統合とは異なります。','正しい。一括支払い(Consolidated Billing)を使うと、組織内の全メンバーアカウントの請求を管理アカウントに一本化し、利用量を合算してボリュームディスカウントの対象にできます。']},
  {id:'p171', domain:'billing', type:'single', source:SOURCES.consolidatedBilling, text:'複数のAWSアカウントを束ねて管理している組織で、各アカウントの使用量を合算することで、ボリュームベースの料金ティア（使用量に応じた割引）にまとめて到達しやすくしたい場合、最も適した機能はどれですか？',
    choices:['AWS Budgets','AWS Organizationsのコンソリデーティッドビリング（一括支払い）','AWS Trusted Advisor','Savings Plans'], correct:[1],
    why:['誤り。Budgetsは予算アラートの設定機能です。','正しい。AWS Organizationsのコンソリデーティッドビリング（一括支払い）は、複数アカウントの使用量を合算し、ボリュームベースの料金ティアにまとめて到達しやすくする機能です。','誤り。Trusted Advisorはベストプラクティスの推奨事項を提示するサービスです。','誤り。Savings Plansは個々の利用コミットメントに対する割引モデルで、複数アカウントの使用量合算による割引とは異なります。']},
  {id:'p172', domain:'security', type:'multi', source:SOURCES.securityHub, text:'AWS Security Hubの特徴として正しいものを2つ選択してください。',
    choices:['GuardDuty・Inspector・Macieなど複数のセキュリティサービスの検出結果を単一のダッシュボードに集約する','検出した脆弱性を必ず自動的に修復(パッチ適用)する','セキュリティスコアやベストプラクティスのチェック結果により、AWS環境全体のコンプライアンス状況を可視化する','VPC内のネットワークパケットを直接解析してマルウェアの通信を検出する'], correct:[0,2],
    why:['正しい。Security Hubは、GuardDuty・Inspector・Macieなど複数のサービスのセキュリティ検出結果を単一の画面に集約します。','誤り。Security Hubは検出結果の集約・可視化を行いますが、脆弱性を自動的に修復する機能ではありません(自動修復には別途Systems Managerなどの対応が必要です)。','正しい。Security Hubは、セキュリティスコアや業界標準に基づくベストプラクティスチェックにより、コンプライアンス状況を可視化します。','誤り。ネットワークパケットやDNSクエリを解析して脅威を検出するのはAmazon GuardDutyの機能です。']},
  {id:'p173', domain:'security', type:'single', source:SOURCES.securityHub, text:'GuardDuty・Inspector・Macieなど複数のセキュリティサービスの検出結果を一つのダッシュボードに集約し、セキュリティ状況を統合的に把握したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Security Hub','Amazon Detective','AWS Firewall Manager','AWS Config'], correct:[0],
    why:['正しい。AWS Security Hubは、GuardDuty・Inspector・Macie等の複数のセキュリティサービスの検出結果を集約し、セキュリティ状況を統合的なダッシュボードで可視化するサービスです。','誤り。Detectiveは検出結果の根本原因を深く調査・分析するためのサービスで、複数サービスの検出結果を集約するダッシュボードではありません。','誤り。Firewall Managerは複数アカウントのWAF/Shield等のルールを一元管理するサービスです。','誤り。Configはリソースの構成変更履歴の記録が主目的です。']},
  {id:'p174', domain:'concepts', type:'single', source:SOURCES.hybridCloud, text:'オンプレミスのデータセンターに機密性の高いレガシーシステムを残しつつ、新規のWebアプリケーションはAWS上で構築・運用したい。このようなオンプレミスとクラウドを組み合わせる構成は何と呼ばれますか？',
    choices:['ハイブリッドクラウド','マルチクラウド','プライベートクラウド','パブリッククラウドのみの構成'], correct:[0],
    why:['正しい。オンプレミス環境とパブリッククラウド(AWS)を組み合わせて利用する構成はハイブリッドクラウドと呼ばれます。','誤り。マルチクラウドは複数の異なるクラウドプロバイダーを組み合わせて使う構成を指し、オンプレミスとの組み合わせとは異なります。','誤り。プライベートクラウドは自社専用に構築されたクラウド環境を指し、パブリッククラウドであるAWSとの組み合わせとは異なります。','誤り。オンプレミス環境を残している点でパブリッククラウドのみの構成ではありません。']},
  {id:'p175', domain:'concepts', type:'single', source:SOURCES.hybridCloud, text:'一部のワークロードを低レイテンシが必要なオンプレミス環境に残しつつ、他のワークロードを段階的にAWSへ移行したい場合に採用される、オンプレミスとクラウドを組み合わせた構成を何と呼びますか？',
    choices:['マルチアカウント構成','マルチリージョン構成','ハイブリッドクラウド','サーバーレスアーキテクチャ'], correct:[2],
    why:['誤り。マルチアカウント構成は、AWS Organizations等を使って複数のAWSアカウントを管理する構成であり、オンプレミスとの統合を指す用語ではありません。','誤り。マルチリージョン構成は、複数のAWSリージョンにリソースを分散配置する構成です。','正しい。ハイブリッドクラウドは、オンプレミス環境とAWSのようなパブリッククラウドを組み合わせ、低レイテンシが必要なワークロードをオンプレミスに残しながら段階的に移行できる構成です。','誤り。サーバーレスアーキテクチャは、サーバー管理不要のコンピューティング（Lambda等）を使った構成で、オンプレミスとの統合とは直接関係しません。']},
  {id:'p176', domain:'tech', type:'single', source:SOURCES.drs, text:'オンプレミスのサーバー群に対して、障害発生時のダウンタイムとデータ損失を最小限に抑えるため、継続的にAWS上へレプリケーションしておき、必要なときに数分でAWS上にインスタンスを起動して復旧したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Backup','AWS Storage Gateway','Amazon S3 Glacier','AWS Elastic Disaster Recovery (AWS DRS)'], correct:[3],
    why:['誤り。AWS Backupは定期的なバックアップの一元管理を行うサービスで、継続的なレプリケーションによる即時復旧には特化していません。','誤り。AWS Storage Gatewayは、オンプレミスとAWSストレージ間のハイブリッドなデータアクセスを提供するサービスで、災害復旧専用のサービスではありません。','誤り。Amazon S3 Glacierは低コストのアーカイブストレージであり、即時のサーバー復旧を目的としたサービスではありません。','正しい。AWS Elastic Disaster Recoveryは、オンプレミスやクラウドのサーバーをAWSへ継続的にレプリケーションし、障害時に数分でインスタンスを起動して復旧できる災害復旧サービスです。']},
  {id:'p177', domain:'tech', type:'single', source:SOURCES.drs, text:'オンプレミスで稼働しているサーバーを、ブロックレベルでの継続的なレプリケーションにより、わずかなダウンタイムでAWSクラウドへ移行（リホスト）したい場合、最も適したサービスはどれですか？',
    choices:['AWS Direct Connect','AWS Database Migration Service','AWS Elastic Disaster Recovery','AWS Snowball'], correct:[2],
    why:['誤り。Direct Connectは専用線によるネットワーク接続サービスです。','誤り。DMSはデータベース・データストアの移行に特化したサービスです。','正しい。AWS Elastic Disaster Recoveryは、オンプレミス等のサーバーをブロックレベルで継続的にレプリケーションし、短いダウンタイムでAWS上に起動できるサービスで、リホスト型の移行にも活用されます。','誤り。Snowballは大容量データを物理デバイスで転送するサービスで、サーバー自体の継続的なレプリケーションは行いません。']},
  {id:'p178', domain:'security', type:'single', source:SOURCES.ram, text:'1つのAWSアカウントで作成したVPCサブネットを、同じAWS Organizations配下にある複数のアカウントで重複作成せずに利用できるようにしたい場合、最も適切な方法はどれですか？',
    choices:['各アカウントに同じ設定のVPCサブネットを個別に作成する','AWS Direct Connectで各アカウントを接続する','IAMユーザーを全アカウントで共有する','AWS Resource Access Manager (RAM) を使って、サブネットなどのリソースをOrganizations内の他アカウントと共有する'], correct:[3],
    why:['誤り。重複して作成することになり、運用負荷が増え、要件を満たしません。','誤り。Direct Connectはオンプレミスとの専用線接続のサービスであり、アカウント間のリソース共有の仕組みではありません。','誤り。IAMユーザーの共有はセキュリティ上推奨されず、リソース共有の仕組みでもありません。','正しい。AWS RAMを使うと、自分のアカウントが所有するリソース(VPCサブネット等)を、Organizations内の他アカウントと重複作成せずに共有できます。']},
  {id:'p179', domain:'security', type:'single', source:SOURCES.ram, text:'複数のAWSアカウントで、重複して同じVPCサブネットやTransit Gatewayを作成するのを避け、1つのアカウントで作成したリソースを他のアカウントと安全に共有したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Resource Access Manager (RAM)','AWS Organizationsの一括支払い（Consolidated Billing）','AWS IAM Identity Center','AWS Directory Service'], correct:[0],
    why:['正しい。AWS RAMを使うと、1つのアカウントで作成したリソース（VPCサブネットやTransit Gatewayなど）を、他のAWSアカウントやOUと安全に共有できます。','誤り。一括支払いは請求を統合する機能で、リソース自体の共有機能ではありません。','誤り。IAM Identity Centerはユーザーのシングルサインオン管理が目的で、リソース共有機能ではありません。','誤り。Directory Serviceはディレクトリ（ユーザー管理）サービスで、リソース共有機能ではありません。']},
  {id:'p180', domain:'security', type:'single', source:SOURCES.cloudhsm, text:'コンプライアンス要件により、暗号鍵を他の顧客と共有しない専用(シングルテナント)のFIPS 140-2認証済みハードウェアで管理する必要がある場合、最も適切なサービスはどれですか？',
    choices:['AWS KMS (AWS管理のデフォルトキー)','AWS CloudHSM','AWS Secrets Manager','AWS Certificate Manager'], correct:[1],
    why:['誤り。AWS KMSはマネージドサービスとして鍵を管理しますが、基盤となるHSMはAWSが管理するマルチテナントのリソースであり、顧客専用の単一テナントHSMではありません。','正しい。AWS CloudHSMは、顧客専用(シングルテナント)のFIPS 140-2認証済みハードウェアセキュリティモジュールを提供し、顧客が鍵を完全に管理できます。','誤り。AWS Secrets Managerは、データベース認証情報などのシークレットのローテーション・管理を行うサービスで、専用HSMの提供とは異なります。','誤り。AWS Certificate Managerは、SSL/TLS証明書の発行・管理を行うサービスです。']},
  {id:'p181', domain:'security', type:'single', source:SOURCES.cloudhsm, text:'規制上の要件により、暗号鍵を顧客専用の単一テナントのハードウェアセキュリティモジュール（HSM）上で管理する必要がある場合、最も適したサービスはどれですか？',
    choices:['AWS CloudHSM','AWS KMS','AWS Secrets Manager','AWS Certificate Manager (ACM)'], correct:[0],
    why:['正しい。AWS CloudHSMは、顧客専用（シングルテナント）のFIPS準拠HSM上で暗号鍵を管理できるサービスで、厳格な規制要件に対応しやすい選択肢です。','誤り。KMSはマルチテナントのマネージドサービスで、多くの用途で十分ですが、専用ハードウェアでの管理を求める要件には必ずしも対応しません。','誤り。Secrets Managerはデータベース認証情報等のシークレット管理サービスです。','誤り。ACMはSSL/TLS証明書の発行・管理サービスです。']},
  {id:'p182', domain:'concepts', type:'single', source:SOURCES.wafSustainability, text:'Well-Architected Frameworkの持続可能性の柱（Sustainability Pillar）が重視する観点として最も適切なものはどれですか？',
    choices:['コストを最小化すること','ワークロードが環境に与える影響を理解し、リソース利用を最適化して環境負荷を削減すること','システムの応答速度を最大化すること','アクセス権限を最小化すること'], correct:[1],
    why:['誤り。コスト最小化は主にコスト最適化の柱が扱う観点です（両者は関連しますが同一ではありません）。','正しい。持続可能性の柱は、ワークロードが環境に与える影響を理解し、エネルギー消費やリソース利用を最適化して環境負荷を削減することを重視します。','誤り。応答速度の最大化は主にパフォーマンス効率の柱が扱う観点です。','誤り。アクセス権限の最小化は主にセキュリティの柱が扱う観点です。']},
  {id:'p183', domain:'security', type:'single', source:SOURCES.kms, text:'業界の規制要件により、暗号鍵を専有（シングルテナント）のハードウェアセキュリティモジュール上で管理する必要がある場合、最も適切なサービスはどれですか？',
    choices:['AWS CloudHSM','AWS KMS','AWS Secrets Manager','AWS Certificate Manager'], correct:[0],
    why:['正しい。AWS CloudHSMは、専有（シングルテナント）のハードウェアセキュリティモジュール(HSM)を提供し、厳格な規制要件への対応に適しています。','誤り。AWS KMSはマルチテナントのマネージド鍵管理サービスで、多くの用途に適しますが、専有HSMの要件には対応しません。','誤り。AWS Secrets Managerはデータベース認証情報等のシークレット管理サービスで、HSMによる鍵管理サービスではありません。','誤り。AWS Certificate ManagerはSSL/TLS証明書の発行・管理サービスです。']},
  {id:'p184', domain:'tech', type:'single', source:SOURCES.appstream, text:'自社で開発したWindowsデスクトップアプリケーションを、ユーザーの端末にインストールせず、ブラウザ経由でストリーミング配信したい場合、最も適したサービスはどれですか？',
    choices:['Amazon WorkSpaces Applications（旧Amazon AppStream 2.0）','Amazon WorkSpaces','AWS Transfer Family','Amazon Chime'], correct:[0],
    why:['正しい。Amazon WorkSpaces Applications（旧Amazon AppStream 2.0）は、個別のデスクトップアプリケーションを、端末にインストールせずブラウザ等へストリーミング配信できるサービスです。','誤り。Amazon WorkSpacesは、個別アプリではなく仮想デスクトップ環境全体（DaaS）を提供するサービスです。','誤り。AWS Transfer Familyは、SFTP/FTPS等のプロトコルでファイル転送を行うマネージドサービスです。','誤り。Amazon Chimeはビデオ会議・チャットのコミュニケーションサービスです。']},
  {id:'p185', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'オンプレミスのデータセンターでは将来の需要を予測して事前にハードウェアを購入する必要がありますが、AWSクラウドではその必要がなくなります。このクラウドの利点を何と呼びますか？',
    choices:['規模の経済（Economies of Scale）','キャピタルエクスペンス（CapEx）の増加','キャパシティ予測が不要になること（Stop guessing capacity）','俊敏性（Agility）の低下'], correct:[2],
    why:['誤り。規模の経済は、AWSが大量の顧客の需要を集約することで得られるコスト効率を指し、需要予測の要否とは別の利点です。','誤り。クラウドでは固定資産への先行投資（CapEx）がむしろ減り、利用量に応じた変動費（OpEx）に置き換わります。','正しい。AWSクラウドでは必要なときに必要な分だけリソースを調達できるため、事前に将来の需要を予測してキャパシティを確保する必要がなくなります。','誤り。これは逆の内容です。クラウドはむしろ俊敏性を高めます。']},
  {id:'p186', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'「スケーラビリティ(拡張性)」と「弾力性(Elasticity)」の違いとして最も適切な説明はどれですか？',
    choices:['スケーラビリティは需要増加に対応してリソースを増強できる能力全般を指し、弾力性はそのうち需要の変化に応じて自動的にリソースを増減させる能力を指す','弾力性はリソースを増やすことだけを指し、減らすことは含まない','スケーラビリティはAWSが提供する特定のサービス名であり、弾力性は料金モデルの名称である','スケーラビリティと弾力性は完全に同じ意味で区別されない'], correct:[0],
    why:['正しい。スケーラビリティは需要増に応じて拡張できる能力全般を指し、弾力性はその中でも自動的な増減（スケールイン/アウト）に注目した概念です。','誤り。弾力性は需要減少時に自動的にリソースを縮小することも含みます。','誤り。どちらも特定のサービス名や料金モデル名ではなく、クラウドの設計上の概念です。','誤り。意味的に重なる部分はありますが、弾力性は「自動的な増減」という時間的な側面を強調する点で区別されます。']},
  {id:'p187', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'クラウドの経済的・運用上のメリットのうち、「わずか数クリック・数分程度の作業でアプリケーションを世界中の複数リージョンにデプロイできる」特性を表す用語として最も適切なものはどれですか？',
    choices:['グローバル規模で数分のうちに展開できること(Go Global in Minutes)','規模の経済(Economies of Scale)','先行投資の変動費化(Trade capital expense for variable expense)','推測に頼らない容量計画(Stop guessing capacity)'], correct:[0],
    why:['正しい。AWSクラウドの利点の一つは、クリック数回・数分程度の作業で、世界中の複数リージョンにアプリケーションを展開できることです。','誤り。規模の経済は、AWSが多数の顧客の利用を集約することで得られる低コストをユーザーに還元する仕組みを指します。','誤り。先行投資の変動費化は、データセンター等への先行投資を使用量に応じた変動費に置き換えられることを指します。','誤り。推測に頼らない容量計画は、需要を事前に予測して過剰/不足のリソースを確保する必要がなくなることを指します。']},
  {id:'p188', domain:'concepts', type:'multi', source:SOURCES.sixAdv, text:'AWSクラウドを利用するメリットとして正しいものを2つ選択してください。',
    choices:['数分で世界中にアプリケーションを展開できる(デプロイのスピードと範囲)','物理的なデータセンターの建設にかかる時間を短縮できるだけで、運用コストは従来と変わらない','需要の変動に応じて必要な分だけリソースを増減できる(弾力性)により、過剰なプロビジョニングを避けられる','ハードウェアの調達が不要になる代わりに、より多くの固定長期契約が必須になる'], correct:[0,2],
    why:['正しい。AWSのグローバルインフラストラクチャを使うことで、数分で世界中の複数リージョンにアプリケーションを展開できます(Go Global in Minutes)。','誤り。クラウドでは固定費(CapEx)を可変費(OpEx)に変えられ、実際に使った分だけ支払う従量課金により運用コストも最適化できます。','正しい。弾力性により需要に応じてリソースを増減でき、過剰なプロビジョニングを避けてコストを最適化できます。','誤り。クラウドでは必要な分だけ利用する従量課金が基本であり、長期契約は必須ではありません(リザーブド等は任意の選択肢です)。']},
  {id:'p189', domain:'tech', type:'single', source:SOURCES.textract, text:'紙の請求書をスキャンしたPDFから、取引先名・金額・日付などの情報を自動的に抽出してシステムに取り込みたい場合、最も適したサービスはどれですか？',
    choices:['Amazon Comprehend','Amazon Textract','Amazon Polly','Amazon Rekognition'], correct:[1],
    why:['誤り。Amazon Comprehendは自然言語のテキストを対象としたNLPサービスで、画像・PDFからの文字抽出自体は主目的ではありません。','正しい。Amazon Textractは、AnalyzeExpense APIなどにより、請求書や受領書のスキャン画像・PDFから取引先名・金額・日付等のデータを自動的に抽出できます。','誤り。Amazon Pollyはテキストを音声に変換するサービスです。','誤り。Amazon Rekognitionは画像・動画内の物体やシーンの認識を行うサービスです。']},
  {id:'p190', domain:'tech', type:'single', source:SOURCES.textract, text:'請求書や申込書などの画像・PDFドキュメントから、機械学習の専門知識なしにテキストやテーブル・フォームのデータを自動的に抽出したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon Textract','Amazon Rekognition','Amazon Comprehend','Amazon Translate'], correct:[0],
    why:['正しい。Amazon Textractは、ドキュメント画像やPDFからテキスト・フォーム・テーブルのデータを機械学習の専門知識なしに自動抽出できるサービスです。','誤り。Rekognitionは画像・動画の物体検出や顔分析が主目的で、ドキュメント内のテキスト・テーブル抽出には特化していません。','誤り。Comprehendは抽出済みのテキストに対する自然言語処理（感情分析等）が主目的で、ドキュメントからのテキスト抽出自体は行いません。','誤り。Translateはテキストの言語翻訳が目的で、ドキュメントからのテキスト抽出機能ではありません。']},
  {id:'p191', domain:'tech', type:'single', source:SOURCES.neptune, text:'SNSアプリケーションで「友人の友人」のような複雑な関係性を高速にたどって分析したい場合、最も適したデータベースサービスはどれですか？',
    choices:['Amazon RDS','Amazon DynamoDB','Amazon Redshift','Amazon Neptune'], correct:[3],
    why:['誤り。RDSはリレーショナルデータベースで、複雑な関係性を高速にたどるグラフクエリには最適化されていません。','誤り。DynamoDBはキーバリュー/ドキュメント型のNoSQLデータベースで、関係性をたどるクエリには向きません。','誤り。Redshiftはデータウェアハウスで、大規模な分析集計に向きますが、グラフ構造の関係性探索には向きません。','正しい。Amazon Neptuneは、Gremlin・openCypher・SPARQLに対応したグラフデータベースで、高度に関連し合ったデータセットを高速にたどるクエリに最適です。']},
  {id:'p192', domain:'tech', type:'single', source:SOURCES.neptune, text:'ソーシャルネットワークのつながりや不正検知のための関係性など、大量の「ノードとエッジ」で構成される高度に関連したデータを効率的に扱いたい場合、最も適切なデータベースサービスはどれですか？',
    choices:['Amazon DynamoDB','Amazon Neptune','Amazon Redshift','Amazon RDS'], correct:[1],
    why:['誤り。DynamoDBはキーバリュー/ドキュメント型のNoSQLデータベースで、グラフ構造のクエリに特化したものではありません。','正しい。Amazon Neptuneは、ノードとエッジで構成される高度に関連したデータを効率的に扱うために最適化されたフルマネージドのグラフデータベースサービスです。','誤り。Redshiftは大規模データ分析向けのデータウェアハウスです。','誤り。RDSはリレーショナルデータベースで、グラフ構造のクエリには適していません。']},
  {id:'p193', domain:'billing', type:'single', source:SOURCES.ec2Ri, text:'1年または3年の利用をコミットする代わりに割引を受けられ、特定のインスタンスファミリー・リージョンに結び付く購入オプションはどれですか？',
    choices:['オンデマンドインスタンス','スポットインスタンス','リザーブドインスタンス','Savings Plans'], correct:[2],
    why:['誤り。オンデマンドインスタンスは使用した分だけ支払う方式で、長期コミットメントによる割引はありません。','誤り。スポットインスタンスは空きキャパシティを利用した大幅割引ですが、コミットメント型の割引ではなく、中断されるリスクがあります。','正しい。リザーブドインスタンスは、1年または3年の利用をコミットすることで割引を受けられ、特定のインスタンスファミリー・リージョンに結び付く購入オプションです。','誤り。Savings Plansはコンピューティングサービス横断で柔軟性が高く、特定のインスタンスファミリーに固定されません。']},
  {id:'p194', domain:'billing', type:'single', source:SOURCES.ec2Ri, text:'Amazon EC2のリザーブドインスタンスを購入する際、初期費用を一切支払わず、代わりに利用期間中の時間料金をやや高めに設定することで月々のキャッシュフローを安定させたい場合、最も適切な支払いオプションはどれですか？',
    choices:['No Upfront（前払いなし）','All Upfront（全額前払い）','Partial Upfront（一部前払い）','スポットインスタンス'], correct:[0],
    why:['正しい。No Upfrontは前払いが一切不要で、代わりに時間料金がAll Upfront/Partial Upfrontよりやや高く設定される支払いオプションです。','誤り。All Upfrontは契約期間分の料金を全額前払いする、最も割引率が高いオプションです。','誤り。Partial Upfrontは一部を前払いし、残りを時間料金で支払うオプションです。','誤り。スポットインスタンスはリザーブドインスタンスの支払いオプションではなく、別の購入オプションです。']},
  {id:'p195', domain:'billing', type:'single', source:SOURCES.pricingcalc, text:'AWSへの移行を検討している企業が、まだAWSアカウントを作成していない段階で、想定するアーキテクチャの構成に基づいた月額コストの見積もりを作成したい場合、最も適したツールはどれですか？',
    choices:['AWS Cost Explorer','AWS Budgets','AWS Cost and Usage Report (CUR)','AWS Pricing Calculator'], correct:[3],
    why:['誤り。AWS Cost Explorerは、既存のAWS利用状況に基づいてコストを可視化・分析するツールで、アカウント作成前の見積もりには使えません。','誤り。AWS Budgetsは、既存のAWS利用に対して予算アラートを設定するサービスです。','誤り。AWS Cost and Usage Reportは、既存のAWS利用の詳細なコストデータを出力するレポートです。','正しい。AWS Pricing Calculatorは、AWSアカウントの有無に関わらず、想定する構成に基づいた月額コストの見積もりを作成できるツールです。']},
  {id:'p196', domain:'billing', type:'single', source:SOURCES.pricingcalc, text:'新規事業向けに、まだAWS上に構築していないワークロードについて、想定するインスタンスタイプや使用量を入力し、月額のおおよそのコストを事前に見積もりたい場合、最も適したツールはどれですか？',
    choices:['AWS Cost Explorer','AWS Budgets','AWS Pricing Calculator','AWS Trusted Advisor'], correct:[2],
    why:['誤り。Cost Explorerは、すでに発生した過去のコスト・使用量を分析・可視化するツールです。','誤り。Budgetsは予算の閾値を設定し、超過時にアラートを送るツールです。','正しい。AWS Pricing Calculatorは、想定する構成（インスタンスタイプや使用量等）を入力することで、未構築のワークロードについて事前にコストを見積もれるツールです。','誤り。Trusted Advisorはベストプラクティスに基づく推奨事項を提示するサービスです。']},
  {id:'p197', domain:'security', type:'single', source:SOURCES.secretsmanager, text:'データベースの認証情報を保管し、定期的な自動ローテーションを設定したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Systems Managerのパラメータストア','AWS Secrets Manager','Amazon Cognito','AWS Directory Service'], correct:[1],
    why:['誤り。パラメータストアはシークレットの保管も可能ですが、認証情報の定期的な自動ローテーション機能はAWS Secrets Managerの方が適しています。','正しい。AWS Secrets Managerは、データベース認証情報などのシークレットを安全に保管し、定期的な自動ローテーションを設定できます。','誤り。Amazon Cognitoはアプリケーションの利用者向け認証・認可サービスです。','誤り。AWS Directory ServiceはMicrosoft Active Directoryとの連携等を提供するサービスです。']},
  {id:'p198', domain:'security', type:'single', source:SOURCES.secretsmanager, text:'データベースのパスワードを保存し、定期的な自動ローテーションを行いたい場合、AWS Secrets ManagerとAWS Systems Manager Parameter Storeのうち、より適切なのはどちらですか？',
    choices:['Systems Manager Parameter Store。無料で全機能が利用できるため常に優先すべき','AWS Secrets Manager。シークレットの自動ローテーション機能を標準で備えている','どちらも同一のローテーション機能を持ち、差はない','Systems Manager Parameter Store。ローテーションの自動化に特化して設計されている'], correct:[1],
    why:['誤り。Parameter Storeにも無料枠はありますが、シークレットの自動ローテーション機能は標準では備えていません。','正しい。AWS Secrets Managerは、データベース認証情報などのシークレットを保存し、自動ローテーション機能を標準で提供します。','誤り。両者のローテーション機能には差があり、Secrets Managerの方が自動ローテーションに特化しています。','誤り。Parameter Storeはパラメータの階層管理が主目的で、自動ローテーションに特化した設計ではありません。']},
  {id:'p199', domain:'tech', type:'multi', source:SOURCES.backup, text:'AWS Backupの特徴として正しいものを2つ選択してください。',
    choices:['Amazon EBS・RDS・DynamoDB・EFS等、複数のAWSサービスのバックアップを一つのコンソールでポリシーベースに管理できる','EC2インスタンスの脆弱性を自動的にスキャンする','ネットワークの異常な通信パターンを機械学習で検知する','バックアップの作成・保持期間・コピー先リージョンなどを定義したバックアップポリシーを、複数リソースに一括で適用できる'], correct:[0,3],
    why:['正しい。AWS Backupは、EBS・RDS・DynamoDB・EFSなど複数のAWSサービスのバックアップを一つのコンソールでポリシーベースに集中管理できます。','誤り。これはAmazon Inspectorの機能です。','誤り。これはAmazon GuardDutyなどの脅威検知サービスの機能です。','正しい。AWS Backupでは、バックアップの作成スケジュールや保持期間、コピー先リージョンなどを定義したバックアップポリシーを作成し、複数のリソースに一括適用できます。']},
  {id:'p200', domain:'security', type:'single', source:SOURCES.firewallManager, text:'複数のAWSアカウントで構成される組織全体に対して、AWS WAFのルールやAWS Shield Advancedの保護を一元的に適用・管理したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon GuardDuty','AWS Organizations','AWS Firewall Manager','AWS Security Hub'], correct:[2],
    why:['誤り。Amazon GuardDutyは脅威検知サービスで、WAFルールの一元管理機能ではありません。','誤り。AWS Organizationsは複数アカウントの管理基盤ですが、WAF/Shieldルールの一元適用機能そのものはAWS Firewall Managerが担います。','正しい。AWS Firewall Managerは、AWS Organizations配下の複数アカウント・リソースに対して、AWS WAFのルールやAWS Shield Advancedの保護を一元的に適用・管理できます。','誤り。AWS Security Hubはセキュリティ検出結果を集約するサービスで、ルールの適用自体を行うものではありません。']},
  {id:'p201', domain:'security', type:'single', source:SOURCES.firewallManager, text:'AWS Organizationsで管理する多数のアカウントに対し、AWS WAFのルールやAWS Shield Advancedの保護を一元的に設定・適用し、新しく作成されたアカウントにも自動的に適用したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Security Hub','Amazon GuardDuty','AWS Firewall Manager','AWS Network Firewall'], correct:[2],
    why:['誤り。Security Hubは検出結果の集約が主目的です。','誤り。GuardDutyは脅威検知サービスです。','正しい。AWS Firewall Managerは、Organizations配下の複数アカウントに対してAWS WAFやShield Advanced等のセキュリティポリシーを一元的に設定・適用し、新規アカウントにも自動適用できるサービスです。','誤り。Network FirewallはVPC単位のネットワークトラフィックをフィルタリングするファイアウォールで、複数アカウントへのポリシー一元適用が主目的ではありません。']},
  {id:'p202', domain:'tech', type:'single', source:SOURCES.licenseManager, text:'複数のAWSアカウント・リージョンにわたって、Microsoft・Oracle・SAPなどのサードパーティ製ソフトウェアのライセンス使用状況を一元的に可視化し、ライセンス超過のリスクを抑えたい場合、最も適切なサービスはどれですか？',
    choices:['AWS Trusted Advisor','AWS License Manager','AWS Organizations','AWS Config'], correct:[1],
    why:['誤り。Trusted Advisorはベストプラクティスに基づく推奨事項の提示が主目的です。','正しい。AWS License Managerは、複数のAWSアカウント・リージョンにまたがるソフトウェアライセンスの使用状況を一元的に可視化・追跡し、ライセンス超過や非準拠のリスクを抑えるサービスです。','誤り。Organizationsは複数アカウントの管理・一括請求が主目的で、ライセンス追跡に特化した機能ではありません。','誤り。Configはリソースの構成変更履歴の記録が主目的です。']},
  {id:'p203', domain:'security', type:'single', source:SOURCES.licenseManager, text:'オンプレミスから持ち込んだ(BYOL)Microsoft/Oracle等の商用ソフトウェアライセンスを、複数のAWSアカウント・リージョンにわたって一元的に可視化し、ライセンス利用上限を超えないように管理したい場合、最も適切なサービスはどれですか？',
    choices:['AWS License Manager','AWS Organizations','AWS Trusted Advisor','AWS Config'], correct:[0],
    why:['正しい。AWS License Managerは、BYOLを含む商用ソフトウェアライセンスを複数アカウント・リージョンにわたって一元管理し、利用上限(ハード/ソフトリミット)を設定して管理できます。','誤り。Organizationsは複数アカウントの一元管理・一括請求・SCPによるガバナンスを行うサービスで、ソフトウェアライセンス管理は主目的ではありません。','誤り。Trusted Advisorはベストプラクティスに基づく推奨事項を提示するサービスです。','誤り。Configはリソースの構成変更履歴を記録するサービスで、ソフトウェアライセンスの利用量管理は行いません。']},
  {id:'p204', domain:'concepts', type:'multi', source:SOURCES.drStrategies, text:'AWSが示す災害復旧(DR)戦略のうち、「最もコストが低く復旧に時間がかかる」戦略と「最も複雑でコストが高く、複数リージョンが同時にトラフィックを処理する」戦略の組み合わせとして正しいものを2つ選択してください。',
    choices:['バックアップ＆リストア','パイロットライト','ウォームスタンバイ','マルチサイトアクティブ/アクティブ'], correct:[0,3],
    why:['正しい。バックアップ＆リストアは4つの戦略の中で最もコストが低く、復旧には基盤の再構築とデータの復元が必要なため最も時間がかかります。','誤り。パイロットライトはコア基盤を常時稼働させる中間的な戦略です。','誤り。ウォームスタンバイは縮小版の本番環境を常時稼働させる、マルチサイトより複雑さ・コストが低い戦略です。','正しい。マルチサイトアクティブ/アクティブは複数リージョンで同時に本番トラフィックを処理する、最も複雑でコストが高い戦略です。']},
  {id:'p205', domain:'concepts', type:'multi', source:SOURCES.drStrategies, text:'AWSの代表的なディザスタリカバリ(DR)戦略として正しいものはどれですか？（2つ選択）',
    choices:['オンデマンドキャパシティ予約','パイロットライト（Pilot Light）','コンソリデーティッドビリング','ウォームスタンバイ（Warm Standby）'], correct:[1,3],
    why:['誤り。オンデマンドキャパシティ予約はEC2の容量確保の仕組みで、DR戦略の分類名ではありません。','正しい。パイロットライトは、最小限のコア基盤を他リージョンに常時稼働させておき、災害時にスケールアウトするDR戦略です。','誤り。コンソリデーティッドビリングは複数アカウントの請求を一括管理する仕組みで、DR戦略ではありません。','正しい。ウォームスタンバイは、縮小構成の本番環境を他リージョンで常時稼働させておき、災害時にスケールアップするDR戦略です。']},
  {id:'p206', domain:'concepts', type:'single', source:SOURCES.drStrategies, text:'4つのディザスタリカバリ(DR)戦略(Backup and Restore/Pilot Light/Warm Standby/Multi-Site Active-Active)のうち、最もコストが低く、復旧に要する時間(RTO)が最も長い傾向にある戦略はどれですか？',
    choices:['Multi-Site Active-Active','Warm Standby','Backup and Restore','Pilot Light'], correct:[2],
    why:['誤り。Multi-Site Active-Activeは複数リージョンで同時稼働するため、最もコストが高く、復旧時間はほぼゼロです。','誤り。Warm Standbyは縮小版の環境を常時稼働させるため、Backup and Restoreよりコストは高く、復旧時間は短くなります。','正しい。Backup and Restoreはバックアップからの復元に基づく戦略で、4戦略の中で最もコストが低く、復旧時間(RTO)は最も長くなる傾向があります。','誤り。Pilot Lightはコア基盤を最小限常時稼働させるため、Backup and Restoreよりコストは高く、復旧時間は短くなります。']},
  {id:'p207', domain:'concepts', type:'single', source:SOURCES.drStrategies, text:'ディザスタリカバリ戦略の「Pilot Light」と「Warm Standby」の違いとして正しい説明はどれですか？',
    choices:['Pilot Lightは複数リージョンで同時にトラフィックを処理するが、Warm Standbyは1つのリージョンのみでトラフィックを処理する','Pilot LightはバックアップのみでDR環境を持たないが、Warm Standbyは縮小版の環境を常時稼働させる','Warm StandbyはDR環境を全く用意しないが、Pilot Lightは本番と同じ規模の環境を常時稼働させる','Pilot Lightはコア基盤を最小限の状態で待機させ復旧時に起動・スケールが必要だが、Warm Standbyは縮小版の環境が常時稼働しており即座にトラフィックを処理できる'], correct:[3],
    why:['誤り。複数リージョンで同時にトラフィックを処理するのはMulti-Site Active-Activeの特徴です。','誤り。Pilot LightもDR環境(コア基盤)を用意します。バックアップのみの戦略はBackup and Restoreです。','誤り。説明が逆です。','正しい。Pilot Lightはコア基盤(データベース等)のみ常時稼働させ、復旧時にアプリケーションサーバー等を起動・スケールする必要があるのに対し、Warm Standbyは縮小版ながら完全に機能する環境が常時稼働しており、即座にトラフィックを処理できます。']},
  {id:'p208', domain:'concepts', type:'single', source:SOURCES.wafReliability, text:'ある企業が「災害発生時、データの損失は最大15分分まで許容できるが、サービスは1時間以内に復旧させたい」という要件を定めた。この「1時間以内に復旧」が指す指標として正しいものはどれですか？',
    choices:['RPO(目標復旧時点)', 'RTO(目標復旧時間)', 'TCO(総所有コスト)', 'SLA(サービス品質保証)'], correct:[1],
    why:['誤り。RPOは「データ損失が最大15分分まで許容できる」という方の指標です。','正しい。RTO(目標復旧時間)は障害発生からサービスが復旧するまでに許容される時間を指す指標で、この例では「1時間以内」がRTOに該当します。','誤り。TCOは総所有コストを指す概念で、復旧時間とは無関係です。','誤り。SLAはサービス品質に関する保証を定めた契約であり、個々の復旧時間の指標そのものではありません。']},
  {id:'p209', domain:'concepts', type:'single', source:SOURCES.wafReliability, text:'AWS Well-Architected Frameworkの信頼性の柱が推奨する「障害から自動的に復旧する」ための設計として最も適切なものはどれですか？',
    choices:['単一のアベイラビリティーゾーンにすべてのリソースを配置する','障害発生時の対応手順を文書化するだけで、実際のテストは行わない','システムの主要な指標を監視し、障害を検知した際に自動的に復旧アクションを実行する仕組みを組み込む','スケーリングは常に手動で実施する'], correct:[2],
    why:['誤り。単一AZへの集約はむしろ可用性を下げ、信頼性の柱の推奨に反します。','誤り。手順の文書化だけでなく、実際に復旧手順をテストすることが信頼性の柱で推奨されています。','正しい。信頼性の柱は、主要な指標を監視し、障害を検知した際に自動で復旧アクションを実行する仕組みを構築することを推奨しています。','誤り。手動のみのスケーリングは障害時の迅速な対応を妨げる可能性があります。']},
  {id:'p210', domain:'concepts', type:'single', source:SOURCES.wafReliability, text:'災害復旧(DR)戦略のうち、セカンダリリージョンで本番環境とほぼ同等規模のシステムを常時稼働させ、障害時に数秒〜数分でトラフィックを切り替えられる、RTO/RPOが最も短い戦略はどれですか？',
    choices:['マルチサイト アクティブ-アクティブ（Multi-Site Active-Active）','バックアップ＆リストア（Backup and Restore）','パイロットライト（Pilot Light）','ウォームスタンバイ（Warm Standby）'], correct:[0],
    why:['正しい。マルチサイト アクティブ-アクティブは、複数リージョンで本番同等の環境を常時稼働させる戦略で、4つの戦略の中で最もRTO/RPOを短くできますが、コストも最も高くなります。','誤り。バックアップ＆リストアは最もコストが低い一方、復旧に時間がかかりRTO/RPOは最も長くなります。','誤り。パイロットライトは最小限のコア基盤のみ常時起動しておく戦略で、Multi-Siteよりコストは低いですが復旧に時間がかかります。','誤り。ウォームスタンバイは縮小版の環境を常時稼働させる戦略で、Multi-Siteよりコストは低いですが、フルスケールへの切り替えに多少時間がかかります。']},
  {id:'p211', domain:'concepts', type:'single', source:SOURCES.wafReliability, text:'災害復旧(ディザスタリカバリ)の計画において、「障害発生からシステムが復旧するまでに許容できる最大時間」を表す指標を何と呼びますか？',
    choices:['RPO (Recovery Point Objective)','SLA (Service Level Agreement)','RTO (Recovery Time Objective)','MTBF (Mean Time Between Failures)'], correct:[2],
    why:['誤り。RPOは「どの時点のデータまで復旧できるか（許容できるデータ損失量）」を表す指標です。','誤り。SLAはサービス提供者と利用者間の品質保証契約です。','正しい。RTO (Recovery Time Objective) は、障害発生からシステムが復旧するまでに許容できる最大時間を表す指標です。','誤り。MTBFは故障間の平均稼働時間を表す信頼性の指標です。']},
  {id:'p212', domain:'concepts', type:'single', source:SOURCES.localZones, text:'リアルタイム性の高いゲームや動画配信など低レイテンシーが求められるアプリケーションを、大都市圏のユーザーの近くで実行したい場合に利用できる、リージョンを拡張したAWSインフラストラクチャの拠点を何と呼びますか？',
    choices:['リージョン','アベイラビリティーゾーン','エッジロケーション','AWS Local Zones'], correct:[3],
    why:['誤り。リージョンはより広い地理的エリアの単位で、Local Zonesより大きな概念です。','誤り。アベイラビリティーゾーンはリージョン内の独立したデータセンター群で、大都市圏向けの低レイテンシー拠点という位置づけとは異なります。','誤り。エッジロケーションは主にCloudFront等のコンテンツキャッシュ配信に使われる拠点です。','正しい。AWS Local Zonesは、コンピューティングやストレージ等の一部のAWSサービスを大都市圏の近くに配置し、低レイテンシーなアプリケーション実行を可能にする、リージョンを拡張したインフラストラクチャです。']},
  {id:'p213', domain:'concepts', type:'single', source:SOURCES.localZones, text:'特定の大都市圏のエンドユーザー向けに、超低遅延が求められるアプリケーション（例: リアルタイムゲーミング、ライブ動画配信）をAWS上でホストしたい場合に利用できる、リージョンを拡張した拠点はどれですか？',
    choices:['エッジロケーション','AWS Local Zones','アベイラビリティーゾーン','AWS Outposts'], correct:[1],
    why:['誤り。エッジロケーションは主にCloudFront等のキャッシュ配信拠点です。','正しい。AWS Local Zonesは、大都市圏の近くに配置されたリージョンの拡張拠点で、EC2やEBS等の一部サービスを低遅延で利用できます。','誤り。アベイラビリティーゾーンはリージョン内のデータセンター拠点であり、大都市圏ごとの追加拠点ではありません。','誤り。AWS Outpostsはオンプレミス環境にAWSインフラを拡張するハードウェアで、大都市圏向けの拠点ではありません。']},
  {id:'p214', domain:'billing', type:'single', source:SOURCES.costAllocTags, text:'複数のアプリケーションやコストセンターでAWSリソースを共有して利用している組織が、タグを使ってコストをアプリケーション単位・部門単位で詳細に分類・追跡したい場合、利用すべき仕組みは何ですか？',
    choices:['AWS Cost Anomaly Detection','AWS Trusted Advisor','コスト配分タグ(Cost Allocation Tags)','AWS Budgets'], correct:[2],
    why:['誤り。Cost Anomaly Detectionは異常なコストパターンの検知が主目的です。','誤り。Trusted Advisorはベストプラクティスに基づく推奨事項の提示が主目的です。','正しい。コスト配分タグは、リソースに付けたタグ(キーと値)をBilling and Cost Managementコンソールで有効化することで、コストをタグ単位で分類したコスト配分レポートを生成できる仕組みです。','誤り。Budgetsは予算の閾値に対するアラート機能であり、タグ単位でのコスト分類が主目的ではありません。']},
  {id:'p215', domain:'billing', type:'single', source:SOURCES.costmgmt, text:'「設定した予算の閾値を超えた場合にアラートを送る機能」と「過去のコスト・使用量を分析し将来のコストを予測する機能」を提供するサービスの組み合わせとして正しいものはどれですか？',
    choices:['AWS Trusted Advisor と AWS Budgets','AWS Cost Explorer と AWS Trusted Advisor','AWS Cost Explorer と AWS Budgets','AWS Budgets と AWS Cost Explorer'], correct:[3],
    why:['誤り。Trusted Advisorはベストプラクティスの推奨事項を提示するサービスで、閾値アラートは主目的ではありません。','誤り。Trusted Advisorは将来のコスト予測機能を主目的とするサービスではありません。','誤り。前半（閾値アラート）はAWS Budgets、後半（分析・予測）はAWS Cost Explorerの役割であり、順序が入れ替わっています。','正しい。AWS Budgetsは予算の閾値超過時にアラートを送り、AWS Cost Explorerは過去のコスト・使用量を分析し将来のコストを予測します。']},
  {id:'p216', domain:'billing', type:'single', source:SOURCES.costmgmt, text:'AWS BudgetsとAWS Cost Explorerの違いとして正しいものはどれですか？',
    choices:['どちらも過去のコストを可視化するだけで、将来に対するアラート機能はない','Cost Explorerは予算の閾値を超えた際にアラートを送信するサービスである','Budgetsは過去のコスト・使用量の傾向を可視化・分析するためのサービスである','Budgetsは予算の閾値を設定し超過（または超過予測）時にアラートを送る予防的な仕組みであり、Cost Explorerは過去のコスト・使用量の傾向を可視化・分析するための仕組みである'], correct:[3],
    why:['誤り。AWS Budgetsは閾値超過時にアラートを送信する機能を持ちます。','誤り。これはAWS Budgetsの説明です。','誤り。これはAWS Cost Explorerの説明です。','正しい。AWS Budgetsは予算に対する実際・予測のコストや使用量が閾値を超えた場合にアラートを送る予防的な仕組みであり、Cost Explorerは過去の傾向を可視化・分析するための仕組みです。']},
  {id:'p217', domain:'security', type:'single', source:SOURCES.detective, text:'GuardDutyが検出したセキュリティ上の懸念事項について、関連するAPIコールやネットワーク通信の履歴を可視化し、根本原因を詳しく調査したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon Inspector','Amazon Detective','AWS Security Hub','AWS Shield Advanced'], correct:[1],
    why:['誤り。Inspectorはソフトウェアの脆弱性やネットワーク到達性をスキャンするサービスです。','正しい。Amazon Detectiveは、GuardDuty等が検出した事象について、関連するログやAPIコールの履歴を可視化し、セキュリティ問題の根本原因を効率的に調査できるサービスです。','誤り。Security Hubは複数サービスの検出結果を集約するダッシュボードで、詳細な根本原因調査に特化したサービスではありません。','誤り。Shield AdvancedはDDoS攻撃対策の高度なサービスです。']},
  {id:'p218', domain:'security', type:'single', source:SOURCES.detective, text:'Amazon GuardDutyが複数の疑わしい検出結果を報告した際、それらの結果に関連するリソース・IPアドレス・ユーザーの行動の関係性を可視化し、根本原因の調査を効率化したい場合、最も適したサービスはどれですか？',
    choices:['AWS Trusted Advisor','AWS Artifact','Amazon Detective','AWS Config'], correct:[2],
    why:['これはコスト・パフォーマンス・セキュリティ等の推奨事項を提示するサービスで、セキュリティ調査の可視化機能はありません。','これはコンプライアンスレポートを提供するサービスで、調査機能はありません。','正しい。Amazon Detectiveは、GuardDuty等の検出結果に関連するリソース・IPアドレス・ユーザー行動の関係性を可視化し、セキュリティ調査の根本原因分析を支援するサービスです。','これはリソースの構成変更履歴を記録するサービスで、調査のための関係性可視化機能は主機能ではありません。']},
  {id:'p219', domain:'tech', type:'single', source:SOURCES.transferFamily, text:'取引先企業との間で、SFTP/FTPS/FTPといった標準プロトコルを使ったファイル転送の仕組みを、サーバーを自前で構築・運用せずにクラウド上で提供し、データはS3やEFSに保存したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Transfer Family','AWS DataSync','AWS Storage Gateway','AWS Direct Connect'], correct:[0],
    why:['正しい。AWS Transfer Familyは、SFTP・FTPS・FTP・AS2といった標準プロトコルによるファイル転送をマネージド型で提供し、データをAmazon S3やAmazon EFSに保存できるサービスです。','誤り。DataSyncはオンプレミスとクラウド間でのデータ転送・同期が主目的で、SFTP等のファイル転送サーバーを外部取引先に提供する用途には向きません。','誤り。Storage Gatewayはオンプレミスとクラウドストレージをシームレスに統合するハイブリッドストレージサービスです。','誤り。Direct Connectは専用線によるネットワーク接続サービスで、ファイル転送プロトコルの提供とは異なります。']},
  {id:'p220', domain:'tech', type:'single', source:SOURCES.transferFamily, text:'取引先企業から、SFTPプロトコルを使ってファイルをAmazon S3に安全にアップロードできる仕組みを、サーバーを自前で構築・管理せずに提供したい場合、最も適したサービスはどれですか？',
    choices:['AWS Transfer Family','AWS DataSync','AWS Snowball','AWS Storage Gateway'], correct:[0],
    why:['正しい。AWS Transfer Familyは、SFTP/FTPS/FTP/AS2経由でAmazon S3やAmazon EFSに安全にファイルを転送できるマネージド型サービスです。','誤り。DataSyncはオンプレミスとAWS間のデータ同期サービスで、SFTP等のファイル転送プロトコルのエンドポイントを提供するものではありません。','誤り。Snowballは物理デバイスによるオフラインの大容量データ転送サービスです。','誤り。Storage Gatewayはオンプレミス環境にAWSストレージをハイブリッドに接続するサービスです。']},
  {id:'p221', domain:'tech', type:'single', source:SOURCES.codepipeline, text:'アプリケーションのビルド・テスト・デプロイといったリリースプロセスの各ステージを可視化し、コードの変更をトリガーに継続的デリバリーを自動化したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon EventBridge','AWS Step Functions','AWS CloudFormation','AWS CodePipeline'], correct:[3],
    why:['誤り。EventBridgeはイベント駆動のルーティングが主目的のサービスです。','誤り。Step Functionsは複数のサービスを順序立てて連携させるワークフローオーケストレーションサービスで、リリースパイプライン専用のサービスではありません。','誤り。CloudFormationはInfrastructure as Codeによるリソース構築が主目的で、リリースプロセス全体のパイプライン管理とは異なります。','正しい。AWS CodePipelineは、ビルド・テスト・デプロイ等のリリースステージをモデル化し、継続的デリバリーを自動化するサービスです。']},
  {id:'p222', domain:'concepts', type:'single', source:SOURCES.globalInfra, text:'AWSグローバルインフラストラクチャにおける「リージョン」と「アベイラビリティーゾーン(AZ)」の関係を正しく説明しているものはどれですか？',
    choices:['1つのAZが複数のリージョンにまたがって存在する','AZはリージョンと無関係に独立して存在する','1つのリージョンは、物理的に分離された複数のAZで構成される','リージョンとAZは同一の概念であり、呼び方が異なるだけである'], correct:[2],
    why:['誤り。AZはリージョン内に属し、複数のリージョンにまたがることはありません。','誤り。AZは特定のリージョンに属する概念です。','正しい。1つのリージョンは、低レイテンシーで接続された物理的に分離された複数のAZで構成されます。','誤り。リージョンとAZは異なる階層の概念です。']},
  {id:'p223', domain:'concepts', type:'single', source:SOURCES.globalInfra, text:'AWSグローバルインフラストラクチャにおける「アベイラビリティーゾーン(AZ)」の説明として正しいものはどれですか？',
    choices:['世界中に配置された、CDN用のキャッシュサーバー拠点','1つのリージョン内に必ず1つだけ存在する、唯一のデータセンター','1つ以上の物理的に分離したデータセンターで構成され、同一リージョン内の他のAZと低レイテンシーのネットワークで接続されている','顧客が独自に建設し、AWSが運用を代行するデータセンター'], correct:[2],
    why:['これはエッジロケーション(CDN拠点)の説明です。','誤り。1つのリージョンは通常、複数（最低3つ以上）のアベイラビリティーゾーンで構成されます。','正しい。アベイラビリティーゾーンは、1つ以上の物理的に分離したデータセンターで構成され、同一リージョン内の他のAZと高速・低レイテンシーのネットワークで接続されています。','誤り。AZはAWSが設計・所有・運用するデータセンターです。']},
  {id:'p224', domain:'tech', type:'single', source:SOURCES.msk, text:'既存のオンプレミスのApache Kafkaクラスターをコード変更なしでAWSに移行し、クラスター運用の管理負荷を削減したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon SQS','Amazon SNS','Amazon MSK (Managed Streaming for Apache Kafka)','Amazon Kinesis Data Streams'], correct:[2],
    why:['誤り。SQSはシンプルなキューサービスで、Kafka互換のAPIやプロトコルは提供しません。','誤り。SNSはPub/Sub型の通知サービスで、Kafkaクラスターの移行先には適しません。','正しい。Amazon MSKはApache Kafkaのオープンソース版をそのまま実行できるフルマネージドサービスで、既存のアプリケーションやコードを変更せずに移行できます。','誤り。Kinesis Data StreamsはAWS独自のストリーミングサービスで、Kafka互換ではなく、コード変更なしの移行には向きません。']},
  {id:'p225', domain:'tech', type:'single', source:SOURCES.msk, text:'既存のApache Kafkaベースのストリーミングアプリケーションを、インフラ管理の手間なくクラウド上で運用したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon Kinesis Data Streams','Amazon SQS','Amazon SNS','Amazon MSK (Managed Streaming for Apache Kafka)'], correct:[3],
    why:['誤り。Kinesis Data Streamsは独自APIのストリーミングサービスで、既存のKafkaアプリをそのまま移行することは想定されていません。','誤り。SQSはメッセージキューイングサービスで、Kafka互換ではありません。','誤り。SNSはパブリッシュ/サブスクライブ型の通知サービスで、Kafka互換ではありません。','正しい。Amazon MSKはApache Kafkaのマネージドサービスで、既存のKafkaアプリケーションやツールをそのまま利用できます。']},
  {id:'p226', domain:'billing', type:'single', source:SOURCES.costExplorer, text:'過去13ヶ月分のAWSコストの傾向を可視化し、今後18ヶ月分のコストを予測して分析したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Budgets','AWS Pricing Calculator','AWS Compute Optimizer','AWS Cost Explorer'], correct:[3],
    why:['誤り。Budgetsは予算しきい値に対する通知が主目的で、過去データの可視化や将来予測の中心的な分析ツールではありません。','誤り。Pricing Calculatorは将来構築するシステムの見積もりが主目的で、過去の実コストの可視化・分析機能ではありません。','誤り。Compute Optimizerはリソースのサイジング最適化の推奨が目的で、コストの可視化・予測ツールではありません。','正しい。AWS Cost Explorerは、過去13ヶ月分のコストを可視化し、今後18ヶ月分のコストを予測できる分析ツールです。']},
  {id:'p227', domain:'concepts', type:'single', source:SOURCES.pricing, text:'あるスタートアップが、初期投資を抑えつつ利用量に応じた支払いにしたいと考えています。AWSの料金モデルのうち、この要件に最も合致するものはどれですか？',
    choices:['従量課金制（Pay-As-You-Go）','3年間の全額前払いプラン限定契約','月額固定のサブスクリプション契約（利用量に関わらず同額）','年間最低利用量を保証するコミット契約のみ'], correct:[0],
    why:['正しい。従量課金制（Pay-As-You-Go）は使った分だけ支払う料金モデルで、初期投資を抑えつつ利用量に応じた支払いが可能です。','全額前払い契約は初期投資を抑えたいという要件に合致しません。','固定サブスクリプションは利用量に応じた支払いにはなりません。','最低利用量保証のコミット契約は、利用量に応じた柔軟な支払いという要件に合致しません。']},
  {id:'p228', domain:'security', type:'single', source:SOURCES.vpcFlowLogs, text:'あるエンジニアが、EC2インスタンスへの通信が意図せずブロックされている原因を調査するため、セキュリティグループルールが過度に制限されていないかを診断したいと考えています。最も適切な方法はどれですか？',
    choices:['AWS CloudTrailでAPIコール履歴を確認する','AWS Configでリソースの設定変更履歴を確認する','Amazon Inspectorで脆弱性スキャンを実行する','VPC Flow Logsを有効にして、ネットワークインターフェースを通過するIPトラフィックを確認する'], correct:[3],
    why:['誤り。CloudTrailはAPIコール履歴の記録が目的で、ネットワークトラフィックそのものの診断には使いません。','誤り。Configはリソース設定の変更履歴を記録するもので、トラフィックの流れの診断には向きません。','誤り。Inspectorは脆弱性スキャンが目的で、ネットワークトラフィックの診断機能ではありません。','正しい。VPC Flow Logsを有効にすると、ネットワークインターフェースを通過するIPトラフィック情報を取得でき、過度に制限されたセキュリティグループルールの診断に利用できます。']},
  {id:'p229', domain:'security', type:'multi', source:SOURCES.iam, text:'IAMで権限を付与する方法として、正しいものを2つ選択してください。',
    choices:['IAMユーザーやロールにアイデンティティベースポリシーをアタッチする','EC2インスタンスのOSにログインしてパスワードを設定する','S3バケットなどのリソースにリソースベースポリシーをアタッチする','ルートユーザーのメールアドレスを変更する'], correct:[0,2],
    why:['正しい。IAMユーザーやロールにアイデンティティベースポリシーをアタッチすることで権限を付与できます。','誤り。OSへのログインやパスワード設定は、AWSリソースへのアクセス権限管理とは無関係です。','正しい。S3バケットなどのリソース側にリソースベースポリシーをアタッチすることでも権限を付与できます。','誤り。ルートユーザーのメールアドレス変更はアカウント設定であり、権限付与の方法ではありません。']},
  {id:'p230', domain:'security', type:'single', source:SOURCES.iam, text:'IAMポリシーの評価において、同じアクションに対してAllow（許可）とDeny（拒否）が両方存在する場合、どちらが優先されますか？',
    choices:['後から作成されたポリシーが優先される','より多くのポリシーで許可されている方が優先される','IAMロールに付与されたポリシーが常に優先される','明示的なDenyが常に優先され、最終的にそのアクションは拒否される'], correct:[3],
    why:['誤り。作成日時の順序は評価には影響しません。','誤り。許可するポリシーの数は評価結果に影響しません。','誤り。ポリシーの付与先（ユーザー/グループ/ロール）の種類は、明示的なDenyの優先順位を上回りません。','正しい。IAMポリシーの評価では、明示的なDenyが存在する場合は他のAllowに関わらず最終的にそのアクションは拒否されます。']},
  {id:'p231', domain:'tech', type:'single', source:SOURCES.polly, text:'生成したテキストを複数言語の自然な音声としてアプリ内で読み上げたい場合、最も適切なサービスはどれですか？',
    choices:['Amazon Transcribe','Amazon Polly','Amazon Rekognition','Amazon Lex'], correct:[1],
    why:['誤り。Amazon Transcribeは音声をテキストに変換するサービスで、逆方向です。','正しい。Amazon Pollyは、テキストを自然な音声(TTS)に変換するサービスです。','誤り。Amazon Rekognitionは画像・動画の分析サービスで、音声合成は行いません。','誤り。Amazon Lexは会話型インターフェース(チャットボット)構築サービスで、音声合成自体が主目的ではありません。']},
  {id:'p232', domain:'tech', type:'single', source:SOURCES.polly, text:'ニュース記事の文章を、自然な音声に変換してモバイルアプリで読み上げる機能を実装したい場合、最も適したサービスはどれですか？',
    choices:['Amazon Lex','Amazon Transcribe','Amazon Polly','Amazon Comprehend'], correct:[2],
    why:['誤り。Amazon Lexは音声・テキストによる会話型インターフェース(チャットボット)の構築が主目的です。','誤り。Amazon Transcribeは音声からテキストへの変換（音声認識）を行うサービスで、今回の「テキストから音声」とは逆方向です。','正しい。Amazon Pollyは、テキストを自然で人間らしい音声に変換する(Text-to-Speech)サービスです。','誤り。Amazon Comprehendはテキストの意味・感情・エンティティ等を分析する自然言語処理サービスです。']},
  {id:'p233', domain:'security', type:'single', source:SOURCES.auditManager, text:'複数のコンプライアンス標準(PCI DSSやHIPAA等)に対するAWS利用状況の証拠(エビデンス)収集を自動化し、監査対応の報告書作成を効率化したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Audit Manager','AWS Artifact','AWS Security Hub','AWS Config'], correct:[0],
    why:['正しい。AWS Audit Managerは事前定義されたフレームワークに基づき、コンプライアンス評価用のエビデンス収集を自動化します。','誤り。AWS ArtifactはAWS自身のコンプライアンス報告書をダウンロードするポータルで、利用者側の証拠収集は行いません。','誤り。Security Hubはセキュリティの検出結果を集約・優先順位付けするサービスです。','誤り。Configはリソース設定の記録・評価を行うサービスで、監査報告書の作成支援自体は主目的ではありません。']},
  {id:'p234', domain:'security', type:'single', source:SOURCES.auditManager, text:'社内のコントロール（ポリシー・手順）が特定のコンプライアンス基準や規制の要件を満たしているかどうかを継続的に評価し、証拠（エビデンス）の収集やレポート作成を自動化したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Artifact','AWS Config','Amazon Macie','AWS Audit Manager'], correct:[3],
    why:['誤り。AWS ArtifactはAWSのコンプライアンスレポートや契約書をオンデマンドでダウンロードできるサービスで、自社のコントロール評価の自動化を行うものではありません。','誤り。AWS Configはリソースの構成変更の記録・評価が目的で、コンプライアンス基準に基づく証拠収集・レポート作成に特化したものではありません。','誤り。Macieは機械学習を使ってS3内の個人識別情報(PII)等の機密データを検出するサービスです。','正しい。AWS Audit Managerは、コントロールが特定の規制・標準の要件を満たしているかを継続的に評価し、証拠の収集や監査対応レポートの作成を自動化するサービスです。']},
  {id:'p235', domain:'concepts', type:'single', source:SOURCES.artifact, text:'第三者機関による審査済みのAWSのセキュリティ・コンプライアンス報告書(SOC、ISO認証等)を、必要なときにセルフサービスでダウンロードしたい場合、最も適切なサービスはどれですか？',
    choices:['AWS Audit Manager','AWS Trusted Advisor','AWS Artifact','AWS Security Hub'], correct:[2],
    why:['誤り。Audit Managerは利用者自身のコンプライアンス評価のためのエビデンス収集を支援するサービスで、AWS自身の報告書提供が目的ではありません。','誤り。Trusted Advisorはベストプラクティスに基づく推奨事項を提示するサービスです。','正しい。AWS Artifactは、AWSのコンプライアンス報告書や契約書をオンデマンドでセルフサービス取得できるポータルです。','誤り。Security Hubはセキュリティの検出結果を集約するサービスです。']},
  {id:'p236', domain:'tech', type:'single', source:SOURCES.transcribe, text:'音声の会議録音データをテキストの文字起こしに変換し、検索可能な議事録を作成したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon Transcribe','Amazon Polly','Amazon Translate','Amazon Comprehend'], correct:[0],
    why:['正しい。Amazon Transcribeは機械学習を用いて音声をテキストに変換する自動音声認識(ASR)サービスです。','誤り。Amazon Pollyはテキストを音声に変換するサービスで、逆方向の処理です。','誤り。Amazon Translateはテキストの言語翻訳を行うサービスで、音声認識機能は提供しません。','誤り。Amazon Comprehendはテキストの自然言語処理(感情分析等)を行うサービスで、音声認識は行いません。']},
  {id:'p237', domain:'tech', type:'multi', source:SOURCES.transcribe, text:'Amazon Transcribeが提供する機能として正しいものはどれですか？（2つ選択）',
    choices:['画像内の物体やシーンを検出する','音声データをテキストに変換する','テキストから感情(ポジティブ/ネガティブ等)を分析する','複数の話者を区別して書き起こす(スピーカー分離)'], correct:[1,3],
    why:['誤り。これはAmazon Rekognitionの機能です。','正しい。Amazon Transcribeは機械学習モデルを使って音声データをテキストに変換する音声認識サービスです。','誤り。これはAmazon Comprehendの機能です。','正しい。Amazon Transcribeは、複数の話者が存在する音声データに対してスピーカー分離（話者ごとの書き起こし）を行う機能も提供します。']},
  {id:'p238', domain:'security', type:'single', source:SOURCES.verifiedAccess, text:'社外からの従業員アクセスについて、VPNを使わずに、デバイスやID情報に基づいてリクエストごとにアクセス権限を評価する仕組みを実現したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Site-to-Site VPN','AWS Direct Connect','AWS Verified Access','AWS PrivateLink'], correct:[2],
    why:['誤り。Site-to-Site VPNはインターネット経由でオンプレミスとVPCを接続する仕組みで、VPNを使わない要件には合いません。','誤り。Direct Connectはオンプレミスとの専用線接続サービスで、VPNの代替にはなりますが、リクエスト単位の条件付きアクセス評価は行いません。','正しい。AWS Verified Accessは、VPNなしで、ID・デバイスの状態などに基づきアプリケーションへのリクエストごとにアクセスを評価します。','誤り。PrivateLinkはVPCとサービス間をプライベートに接続する仕組みで、従業員のゼロトラストアクセス制御が主目的ではありません。']},
  {id:'p239', domain:'tech', type:'single', source:SOURCES.vpcPeering, text:'VPC Aは VPC B と、VPC B は VPC C とそれぞれVPCピアリング接続されていますが、VPC A と VPC C の間には接続がありません。この状態について正しい説明はどれですか？',
    choices:['VPCピアリングは推移的ではないため、VPC Aは VPC Bを経由してVPC Cと通信することはできない','VPC Aは自動的にVPC Bを中継してVPC Cと通信できる','VPC Aと VPC Cの間にも自動的にピアリング接続が作成される','VPC BがTransit Gatewayとして機能し、AとCの通信を中継する'], correct:[0],
    why:['正しい。VPCピアリングは推移的な関係をサポートしないため、VPC Aが VPC Cと通信するには、AとCの間に新たに専用のピアリング接続を作成する必要があります。','誤り。VPC Bを経由した中継はできません。','誤り。ピアリング接続は自動的には作成されません。','誤り。VPCピアリング接続自体はゲートウェイやハードウェアではなく、Transit Gatewayのような中継機能を持ちません。']},
  {id:'p240', domain:'tech', type:'single', source:SOURCES.vpcPeering, text:'同じAWSアカウント内にある2つのVPCの間で、プライベートIPアドレスを使って直接通信できるようにしたい。ゲートウェイやVPN、専用のハードウェアを使わずに接続する場合、最も適切な方法はどれですか？',
    choices:['VPCピアリング接続','AWS Transit Gateway経由の複数VPC接続','AWS Site-to-Site VPN','AWS Direct Connect'], correct:[0],
    why:['正しい。VPCピアリング接続は、ゲートウェイやVPN接続、専用ハードウェアを使わずに、2つのVPC間をプライベートIPアドレスで直接接続できる仕組みです。','誤り。Transit Gatewayは多数のVPCやオンプレミス拠点を単一のハブで集約接続する場合に適しており、2つのVPCだけの単純な接続には過剰な場合があります。','誤り。Site-to-Site VPNはオンプレミスとの接続が主目的です。','誤り。Direct Connectは専用線によるオンプレミスとの接続が主目的です。']},
  {id:'p241', domain:'concepts', type:'single', source:SOURCES.shared, text:'責任共有モデルにおいて、インターネットを経由する通信の「転送中のデータ暗号化（暗号化の実施そのもの）」の設定は誰の責任ですか？',
    choices:['AWSが自動的にすべての通信を暗号化するため、利用者側の作業は不要である','データセンターの物理的警備と同様にAWSの責任範囲である','利用者が、TLS/SSLの有効化やVPN等を用いて自身のデータ・通信を適切に暗号化する責任を負う','暗号化は行う必要がない'], correct:[2],
    why:['誤り。AWSはインフラを保護しますが、アプリケーション層での転送中データの暗号化設定は利用者の責任です。','これはAWS側（クラウドの保護）の責任範囲の例ですが、暗号化設定自体はこれに含まれません。','正しい。責任共有モデルにおいて「クラウド内のセキュリティ」に区分される転送中データの暗号化は、利用者がTLS/SSLやVPN等を用いて設定する責任があります。','誤り。データの機密性に応じて暗号化を検討することが推奨されます。']},
  {id:'p242', domain:'security', type:'multi', source:SOURCES.shared, text:'AWSの「責任共有モデル」において、顧客（お客様）側の責任に該当するものを2つ選択してください。',
    choices:['データセンターの物理的な警備','ゲストOSへのセキュリティパッチの適用','保存データの暗号化設定','基盤となるハードウェアの保守'], correct:[1,2],
    why:['誤り。データセンターの物理的な警備はAWS側の責任です。','正しい。ゲストOS(EC2インスタンス上のOS)へのパッチ適用は顧客側の責任です。','正しい。保存データを暗号化するかどうか、どのように暗号化するかの設定は顧客側の責任です。','誤り。基盤ハードウェアの保守はAWS側の責任です。']},
  {id:'p243', domain:'tech', type:'single', source:SOURCES.storagegateway, text:'オンプレミスで使用しているテープバックアップの仕組みを、物理テープ装置を使わずにクラウド上の低コストストレージへ置き換えたい場合、AWS Storage Gatewayのどのタイプが適していますか？',
    choices:['Amazon S3ファイルゲートウェイ','FSxファイルゲートウェイ','ボリュームゲートウェイ','テープゲートウェイ'], correct:[3],
    why:['これはNFS/SMBでS3にファイルとしてアクセスする構成向けで、テープバックアップの置き換えには使用しません。','これはWindows File Server等のファイル共有プロトコル向けのゲートウェイで、テープバックアップ向けではありません。','これはiSCSIブロックストレージをクラウドでバックアップ/階層化する構成向けです。','正しい。テープゲートウェイは、既存のテープバックアップソフトウェアとの互換性を保ちながら、仮想テープライブラリ(VTL)としてクラウド上の低コストストレージにバックアップを保存できます。']},
  {id:'p244', domain:'tech', type:'single', source:SOURCES.storagegateway, text:'オンプレミスのアプリケーションから、NFSやSMBといった標準的なファイルプロトコルを使って、Amazon S3に保存されたデータにシームレスにアクセスしたい場合、最も適切なサービスはどれですか？',
    choices:['AWS DataSync','Amazon FSx','AWS Storage Gateway (ファイルゲートウェイ)','Amazon EFS'], correct:[2],
    why:['誤り。DataSyncはデータの転送・同期が主目的で、継続的なファイルプロトコルアクセスの提供が主目的ではありません。','誤り。FSxはWindows/Lustre等向けのマネージド型ファイルストレージで、S3データへの透過的アクセスゲートウェイではありません。','正しい。AWS Storage Gatewayのファイルゲートウェイは、NFS/SMBプロトコルでオンプレミスからS3に保存されたデータにシームレスにアクセスできるようにします。','誤り。EFSはAWS上で使うマネージド型NFSファイルシステムで、オンプレミスからのゲートウェイ機能ではありません。']},
  {id:'p245', domain:'billing', type:'multi', source:SOURCES.cur, text:'AWS Cost and Usage Report (CUR) の特徴として正しいものを2つ選択してください。',
    choices:['手動で設定した予算の閾値を超えた場合にのみ生成される','AWSで利用可能な、製品・使用タイプ・操作ごとの明細を含む最も詳細なコスト・使用状況データセットである','機械学習によって異常なコストパターンを自動的に検知する','指定したAmazon S3バケットに、CSV形式などで定期的（例: 1日1回）に出力される'], correct:[1,3],
    why:['誤り。これはAWS Budgetsの説明に近く、CUR自体は閾値の超過に関係なく定期的に生成されます。','正しい。CURは、AWSで利用可能な中で最も詳細な粒度（製品・使用タイプ・操作ごとの明細）を持つコスト・使用状況データセットです。','誤り。これはAWS Cost Anomaly Detectionの説明です。','正しい。CURは、指定したS3バケットにCSV形式などで定期的に出力されます。']},
  {id:'p246', domain:'billing', type:'single', source:SOURCES.cur, text:'AWSの利用料金について、時間単位・サービス単位・タグ単位など最も詳細な粒度でコスト・使用量データをS3バケットに出力し、Athena等で分析したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Cost and Usage Report (CUR)','AWS Budgets','AWS Trusted Advisor','AWS Pricing Calculator'], correct:[0],
    why:['正しい。AWS Cost and Usage Report (CUR) は、時間単位・製品単位・タグ単位などで最も詳細な粒度のコスト・使用量データをS3に出力でき、Athena等で分析できます。','誤り。Budgetsは予算の閾値に対するアラート機能で、詳細なコストデータのエクスポート機能ではありません。','誤り。Trusted Advisorはベストプラクティスの推奨事項を提示するサービスです。','誤り。Pricing Calculatorは将来の利用コストを見積もるツールで、実際の利用データの出力機能ではありません。']},
  {id:'p247', domain:'security', type:'single', source:SOURCES.scp, text:'AWS Organizationsでサービスコントロールポリシー(SCP)を使ってメンバーアカウントにIAMユーザーが利用できる権限の上限を設定しましたが、そのメンバーアカウントのIAMユーザーに何らかのIAM権限ポリシーをまだ一つも付与していません。この場合、そのユーザーがSCPで許可された範囲の操作を実行できますか？',
    choices:['SCPはあくまで権限の上限（ガードレール）であり権限自体は付与しないため、別途IAMの権限ポリシーで許可されない限りその操作はできない','SCPで許可されていれば、他に何の設定もなくても操作できる','SCPはIAMユーザーには影響せず、IAMロールにのみ影響するため操作できる','そのメンバーアカウントがSCPの対象外（管理アカウント）であれば操作できる'], correct:[0],
    why:['正しい。SCPは権限の上限を定めるガードレールであり、権限そのものは付与しないため、別途IAMの権限ポリシーで許可される必要があります。','誤り。SCPは権限を付与しないため、他にIAMの権限ポリシーがなければ操作できません。','誤り。SCPはIAMユーザーにもIAMロールにも、ルートユーザーも含めて影響します。','誤り。この設問のメンバーアカウントはSCPの対象であり、管理アカウントではありません。']},
  {id:'p248', domain:'tech', type:'single', source:SOURCES.eks, text:'すでにオンプレミスでKubernetesを運用しており、標準のKubernetes API・ツールチェーンをそのままAWS上でも使い続けたい場合に、Amazon ECSより適しているサービスはどれですか？',
    choices:['AWS Batch','Amazon ECR','Amazon Elastic Kubernetes Service (EKS)','AWS Fargate'], correct:[2],
    why:['これはバッチジョブのスケジューリングサービスで、コンテナオーケストレーションの標準APIを提供するものではありません。','これはコンテナイメージを保存するレジストリサービスで、オーケストレーション機能はありません。','正しい。Amazon EKSはマネージド型のKubernetesサービスで、標準のKubernetes API・既存のツールチェーンをそのまま利用できます（ECSはAWS独自のオーケストレーションAPIです）。','これはサーバー管理不要でコンテナを実行する起動タイプで、ECS・EKSのどちらと組み合わせても使えますが、オーケストレーションAPI自体ではありません。']},
  {id:'p249', domain:'tech', type:'single', source:SOURCES.eks, text:'Kubernetesを使ってコンテナアプリケーションをオーケストレーションしたいが、Kubernetesコントロールプレーンの運用・管理はAWSに任せたい場合、最も適したサービスはどれですか？',
    choices:['Amazon ECS','Amazon Elastic Kubernetes Service (EKS)','AWS Batch','AWS Elastic Beanstalk'], correct:[1],
    why:['誤り。ECSはAWS独自のコンテナオーケストレーションサービスで、Kubernetesを使用しません。','正しい。Amazon EKSは、マネージドなKubernetesコントロールプレーンを提供し、Kubernetes標準のAPIでコンテナをオーケストレーションできるサービスです。','誤り。AWS Batchはバッチ処理ジョブの実行を管理するサービスで、Kubernetesオーケストレーションとは異なります。','誤り。Elastic Beanstalkはアプリケーションのデプロイ・運用を簡素化するPaaS的サービスで、Kubernetesを直接扱うものではありません。']},
  {id:'p250', domain:'tech', type:'single', source:SOURCES.kinesis, text:'多数のデバイスやアプリケーションから送られてくる大量のデータをリアルタイムに収集・処理したい場合、最も適したサービスはどれですか？',
    choices:['Amazon Athena','AWS Glue','Amazon Redshift','Amazon Kinesis Data Streams'], correct:[3],
    why:['誤り。Athenaは、S3に保存されたデータに対してSQLクエリを実行する分析サービスで、リアルタイムのデータ収集を主目的としたものではありません。','誤り。AWS Glueは、データのETL（抽出・変換・ロード）を行うサービスです。','誤り。Redshiftはデータウェアハウスサービスで、主に分析用途のデータ格納に使われます。','正しい。Amazon Kinesis Data Streamsは、大量のストリーミングデータをリアルタイムに収集・処理するためのサービスです。']},
  {id:'p251', domain:'tech', type:'single', source:SOURCES.kinesis, text:'センサーやアプリケーションログなど、大量のデータをリアルタイムに継続的に収集・処理したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon Kinesis Data Streams','Amazon SQS','AWS Step Functions','Amazon ECR'], correct:[0],
    why:['正しい。Amazon Kinesis Data Streamsは、大量のデータをリアルタイムに継続的に収集し、処理・分析するためのサービスです。','誤り。SQSはメッセージキューイングサービスで、リアルタイムのストリーミングデータ処理に特化したものではありません。','誤り。Step Functionsはワークフローのオーケストレーションサービスです。','誤り。ECRはコンテナイメージを保存するレジストリサービスです。']},
  {id:'p252', domain:'tech', type:'single', source:SOURCES.batch, text:'数千件規模のバッチ処理ジョブを、必要な量のコンピューティングリソースを自動的にプロビジョニングして実行したい場合、最も適したサービスはどれですか？',
    choices:['Amazon EventBridge','AWS Step Functions','AWS Batch','Amazon SQS'], correct:[2],
    why:['誤り。EventBridgeはイベント駆動型のアプリケーションを連携させるイベントバスサービスです。','誤り。Step Functionsは複数のAWSサービスをワークフローとして連携させるオーケストレーションサービスです。','正しい。AWS Batchは、ジョブの量に応じて必要なコンピューティングリソース（EC2やFargate）を自動的にプロビジョニング・スケーリングし、バッチ処理ジョブを効率的に実行できるサービスです。','誤り。SQSはメッセージキューイングサービスで、バッチジョブの実行環境を直接管理するものではありません。']},
  {id:'p253', domain:'tech', type:'single', source:SOURCES.batch, text:'多数のバッチ処理ジョブについて、必要なコンピューティング環境(EC2やSpot等)の種類・量をジョブの要件に応じて自動的に決定・プロビジョニングし、ジョブのスケジューリングとキューイングも管理したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Lambda','AWS Batch','AWS Fargate','Amazon EC2 Auto Scaling'], correct:[1],
    why:['誤り。Lambdaは実行時間などに制約があるイベント駆動型サーバーレスサービスで、大規模・長時間のバッチジョブ管理には適しません。','正しい。AWS Batchは、ジョブの要件に応じて最適なコンピューティング環境(インスタンスタイプ、オンデマンド/スポット等)の種類・量を自動的に決定し、ジョブのスケジューリング・キューイングも管理します。','誤り。Fargateはコンテナ向けのサーバーレスコンピューティング基盤で、バッチジョブのスケジューリング機能自体は持ちません。','誤り。EC2 Auto Scalingはインスタンス数の自動調整を行いますが、ジョブのキューイング・スケジューリングは行いません。']},
  {id:'p254', domain:'tech', type:'multi', source:SOURCES.lambda, text:'次のうち、サーバーレスコンピューティングサービスに該当するものを2つ選択してください。',
    choices:['AWS Fargate','Amazon EC2','AWS Lambda','Amazon Lightsail'], correct:[0,2],
    why:['正しい。AWS Fargateは、コンテナを実行するためのサーバーレスコンピューティングエンジンで、サーバーの管理が不要です。','誤り。Amazon EC2は仮想サーバーを提供するサービスで、インスタンスの管理（OSパッチ適用等）が必要です。','正しい。AWS Lambdaは、サーバーのプロビジョニングや管理なしにコードを実行できるサーバーレスコンピューティングサービスです。','誤り。Amazon Lightsailは、仮想プライベートサーバー（VPS）を簡単に利用できるサービスで、サーバーの管理が必要です。']},
  {id:'p255', domain:'concepts', type:'single', source:SOURCES.awsHealth, text:'AWSのサービス障害やメンテナンス予定など、自分のアカウントのリソースに影響する可能性があるイベントについて、パーソナライズされた通知を確認したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon CloudWatch','AWS Health Dashboard','AWS CloudTrail','AWS Trusted Advisor'], correct:[1],
    why:['誤り。CloudWatchは自分のリソースのメトリクスやログを監視するサービスで、AWS側のサービス障害情報の通知が主目的ではありません。','正しい。AWS Health Dashboardは、AWSサービスの状態や、自分のアカウントのリソースに影響する可能性のあるイベント・メンテナンス予定について、パーソナライズされた情報を提供します。','誤り。CloudTrailはAPIコールの記録・監査が目的です。','誤り。Trusted Advisorはコスト・パフォーマンス・セキュリティ等のベストプラクティス推奨事項を提示するサービスです。']},
  {id:'p256', domain:'security', type:'single', source:SOURCES.systemsManager, text:'データベースの接続文字列や設定値などの機密情報を安価に保管・取得したいが、自動ローテーションのような高度な機能までは不要な場合、最もコスト効率の良い選択肢はどれですか？',
    choices:['AWS Systems Manager パラメータストア','AWS Secrets Manager','AWS KMS','AWS CloudHSM'], correct:[0],
    why:['正しい。Systems Managerのパラメータストアは、設定値や機密情報を安価に保管・取得できる機能で、シークレットの自動ローテーションのような高度な機能が不要な場合に適しています。','誤り。Secrets Managerは自動ローテーションなどの高度な機能を持ちますが、パラメータストアに比べて料金が高くなります。','誤り。KMSは暗号化キーの作成・管理を行うサービスで、設定値自体の保管サービスではありません。','誤り。CloudHSMは専用の物理的なハードウェアセキュリティモジュールで鍵を管理するサービスで、オーバースペックかつ高コストです。']},
  {id:'p257', domain:'billing', type:'single', source:SOURCES.support, text:'ビジネスに重大な影響を与える問題が発生した場合に、24時間365日、電話・チャット・メールでクラウドサポートエンジニアに直接相談できるサポートプランとして、最低限必要なものはどれですか？',
    choices:['Basic Support','Developer Support','該当するプランはなく、追加の専門家に別途依頼する必要がある','Business Support以上のプラン'], correct:[3],
    why:['誤り。Basic Supportはすべてのアカウントで無料ですが、技術的な問い合わせへのサポートエンジニアによる対応は含まれません。','誤り。Developer Supportは主に開発・テスト環境向けで、営業時間内のメール中心のサポートであり、ビジネスクリティカルな問題への24時間対応は想定されていません。','誤り。AWS Support内のプランでこのニーズに対応できます。','正しい。Business Support以上のプランでは、ビジネスに重大な影響を与える問題について24時間365日、電話・チャット・メールでクラウドサポートエンジニアに相談できます。']},
  {id:'p258', domain:'billing', type:'single', source:SOURCES.support, text:'本番環境で緊急の障害が発生し、AWSサポートから可能な限り早い初回応答を得たい場合、応答時間の目標が最も短い（最も速い）サポートプランはどれですか？',
    choices:['Basic Support','Business Support+','Enterprise Support','Unified Operations'], correct:[3],
    why:['誤り。Basic Supportは全アカウントに無料で付属しますが、技術的な問い合わせへの対応時間の目標は設定されておらず、主に請求・アカウント関連のサポートが対象です。','誤り。Business Support+は最も緊急度の高いケースで30分未満の初回応答を目標としていますが、Unified Operationsより長い設定です。','誤り。Enterprise Supportは最も緊急度の高いケースで15分未満の初回応答を目標としていますが、Unified Operationsより長い設定です。','正しい。Unified Operationsは、最も緊急度の高いケースでインシデント管理エンジニアによる5分未満の初回応答を目標とする、最上位クラスのサポートプランです。']},
  {id:'p259', domain:'concepts', type:'single', source:SOURCES.serviceCatalog, text:'複数の部門が自由にAWSリソースを作成すると統制が取れなくなるため、IT部門が承認済みのITサービス（製品）のカタログを作成し、利用者はそのカタログからのみ製品をデプロイできるようにしたい。最も適切なサービスはどれですか？',
    choices:['AWS Service Catalog','AWS Control Tower','AWS Organizations','AWS Trusted Advisor'], correct:[0],
    why:['正しい。AWS Service Catalogは、管理者が承認済みのITサービス（製品）のポートフォリオを作成・管理し、エンドユーザーはそのカタログの中からのみ製品をデプロイできるようにするサービスです。','誤り。Control Towerはマルチアカウント環境全体のランディングゾーン構築・ガードレール適用が主目的で、個々の製品カタログ管理とは異なります。','誤り。Organizationsは複数アカウントの管理・一括請求が主目的です。','誤り。Trusted Advisorはベストプラクティスの推奨事項を提示するサービスです。']},
  {id:'p260', domain:'concepts', type:'single', source:SOURCES.serviceCatalog, text:'複数の部署が独自にEC2インスタンスやRDSを立ち上げてしまい、承認されていない構成のリソースが社内に乱立している。IT部門が事前に承認した構成（CloudFormationテンプレート等）だけをカタログ化し、エンドユーザーはその中からセルフサービスで選んで起動できるようにしたい場合、最も適切なサービスはどれですか？',
    choices:['AWS Service Catalog','AWS Control Tower','AWS Organizations','AWS Systems Manager'], correct:[0],
    why:['正しい。AWS Service Catalogは、承認済みのIT製品をポートフォリオとしてカタログ化し、エンドユーザーがセルフサービスで必要な構成を選んで起動できるようにします。','誤り。Control Towerはマルチアカウント環境(ランディングゾーン)自体の構築・統制が主目的で、個々の承認済み構成のカタログ化とは異なります。','誤り。Organizationsは複数アカウントの一括請求・ガバナンスのためのサービスで、承認済み構成のカタログ化機能はありません。','誤り。Systems Managerは運用管理のためのサービスで、承認済み構成のセルフサービス提供が主目的ではありません。']},
  {id:'p261', domain:'concepts', type:'multi', source:SOURCES.waf, text:'AWS Well-Architected Frameworkにおける「柱(Pillar)」として実際に定義されているものを2つ選択してください。',
    choices:['拡張性の柱（Scalability Pillar）','運用上の優秀性の柱（Operational Excellence Pillar）','コスト最適化の柱（Cost Optimization Pillar）','可用性の柱（Availability Pillar）'], correct:[1,2],
    why:['誤り。「拡張性の柱」という名称の柱は存在しません(拡張性は信頼性の柱などに関連する概念です)。','正しい。運用上の優秀性の柱は、Well-Architected Frameworkの6つの柱の1つです。','正しい。コスト最適化の柱も、Well-Architected Frameworkの6つの柱の1つです。','誤り。「可用性の柱」という名称の柱は存在しません(可用性は信頼性の柱に含まれる概念です)。']},
  {id:'p262', domain:'concepts', type:'single', source:SOURCES.waf, text:'AWS Well-Architected Frameworkの6つの柱に含まれないものはどれですか？',
    choices:['運用上の優秀性','パフォーマンス効率','スケーラビリティ','持続可能性'], correct:[2],
    why:['誤り。運用上の優秀性（Operational Excellence）は6つの柱の一つです。','誤り。パフォーマンス効率（Performance Efficiency）は6つの柱の一つです。','正しい。スケーラビリティ自体は重要な概念ですが、Well-Architected Frameworkの6つの柱（運用上の優秀性・セキュリティ・信頼性・パフォーマンス効率・コスト最適化・持続可能性）には含まれません。','誤り。持続可能性（Sustainability）は6つの柱の一つです。']},
  {id:'p263', domain:'tech', type:'multi', source:SOURCES.cloudwatch, text:'Amazon CloudWatchが提供する機能として正しいものを2つ選択してください。',
    choices:['EC2インスタンス等のメトリクス(CPU使用率等)を収集・監視する','収集したログデータを集約・検索し、指定した閾値に基づいてアラームを発生させる','VPCのサブネット間の通信を許可/拒否するステートレスなフィルタリングを行う','AWSアカウント内のAPIコールの履歴を記録し証跡として保存する'], correct:[0,1],
    why:['正しい。CloudWatchはEC2インスタンス等のリソースのメトリクス(CPU使用率、ネットワーク使用量等)を収集・監視します。','正しい。CloudWatch LogsやCloudWatch Alarmsにより、ログの集約・検索や、閾値に基づくアラームの発生（Auto Scalingのトリガー等）が可能です。','誤り。これはVPCのネットワークACL(NACL)の説明です。','誤り。これはAWS CloudTrailの説明です。']},
  {id:'p264', domain:'billing', type:'single', source:SOURCES.marketplace, text:'サードパーティベンダーが提供するソフトウェア(AMIやSaaS製品等)を、自社で別途契約や支払いを行わずにAWSの利用料金と合わせて一括で支払いたい場合、最も適したサービスはどれですか？',
    choices:['AWS Organizationsのコンソリデーティッドビリング','AWS Marketplace','AWS Budgets','AWS Cost Explorer'], correct:[1],
    why:['誤り。コンソリデーティッドビリングは、Organizations内の複数AWSアカウントの請求を一括管理する機能で、サードパーティ製品の購入窓口ではありません。','正しい。AWS Marketplaceは、サードパーティベンダーのソフトウェア（AMI、SaaS製品等）を検索・購入できるデジタルカタログで、利用料金はAWSの利用料金と合わせて一括請求されます。','誤り。Budgetsは予算アラートの設定サービスです。','誤り。Cost Explorerはコストの分析・可視化ツールです。']},
  {id:'p265', domain:'billing', type:'single', source:SOURCES.marketplace, text:'AWS Marketplaceで購入したサードパーティ製ソフトウェア(AMIやSaaS製品)の利用料金は、どのように請求されますか？',
    choices:['販売元の企業から別途、個別の請求書で支払う','必ず年間一括払いの契約が必要で、月額払いの選択肢はない','AWSの利用料金（EC2やその他サービスの料金）と合わせて、通常のAWS請求書にまとめて計上される','AWS Marketplaceの利用料金はすべて無料で、追加費用は一切発生しない'], correct:[2],
    why:['誤り。販売元への個別請求ではなく、AWSの請求に統合されます。','誤り。製品によって時間単位・月額・年間契約など複数の料金モデルが用意されています。','正しい。AWS Marketplaceで購入した製品の利用料金は、通常のAWS利用料金と合わせて1つの請求書にまとめて計上されます。','誤り。多くの製品には製品自体の利用料金が発生し、無料とは限りません。']},
  {id:'p266', domain:'tech', type:'single', source:SOURCES.lex, text:'音声やテキストを使った会話型のチャットボットを、AWS Lambda等と連携させてアプリケーションに組み込みたい場合、最も適したサービスはどれですか？',
    choices:['Amazon Polly','Amazon Textract','Amazon Comprehend','Amazon Lex'], correct:[3],
    why:['誤り。Amazon Pollyはテキストを音声に変換するサービスです。','誤り。Amazon Textractは文書からテキスト・データを抽出するサービスです。','誤り。Amazon Comprehendはテキストの自然言語処理(感情分析等)を行うサービスです。','正しい。Amazon Lexは、自動音声認識(ASR)と自然言語理解(NLU)を使い、音声・テキストによる会話型インターフェース(チャットボット)を構築できるサービスで、AWS Lambda等と連携できます。']},
  {id:'p267', domain:'security', type:'single', source:SOURCES.iamIdentityCenter, text:'複数のAWSアカウントを持つ組織で、従業員が1つのID（シングルサインオン）で複数のAWSアカウントやクラウドアプリケーションにアクセスできるようにしたい場合、最も適したサービスはどれですか？',
    choices:['AWS IAM Identity Center','AWS Directory Service','Amazon Cognito','AWS Secrets Manager'], correct:[0],
    why:['正しい。AWS IAM Identity Centerは、複数のAWSアカウントやクラウドアプリケーションへのシングルサインオン(SSO)アクセスを一元管理できるサービスです。','誤り。Directory Serviceは主にActive Directory互換のディレクトリをAWS上で運用・連携するためのサービスです。','誤り。Cognitoは主にWeb/モバイルアプリのエンドユーザー向け認証・認可を提供するサービスです。','誤り。Secrets Managerはシークレット情報の保管・ローテーションを行うサービスです。']},
  {id:'p268', domain:'security', type:'single', source:SOURCES.iamIdentityCenter, text:'複数のAWSアカウントに対して、MFAで保護されたシングルサインオン（SSO）アクセスを一箇所で集中管理したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Resource Access Manager (RAM)','AWS Key Management Service (KMS)','AWS IAM Identity Center','AWS Certificate Manager (ACM)'], correct:[2],
    why:['誤り。AWS RAMはリソースの共有を行うサービスで、SSOアクセスの管理機能ではありません。','誤り。AWS KMSは暗号鍵の管理サービスで、SSOアクセスの管理とは異なります。','正しい。AWS IAM Identity Centerは、複数のAWSアカウントへのMFA保護されたシングルサインオンアクセスを一箇所で集中管理できるサービスです。','誤り。AWS ACMはSSL/TLS証明書の管理サービスで、SSOアクセスの管理とは異なります。']},
  {id:'p269', domain:'tech', type:'single', source:SOURCES.ses, text:'自社のWebアプリケーションから、注文確認メールやパスワードリセットメールなどのトランザクションメールを、独自ドメインを使って大量に送信したい場合、最も適したサービスはどれですか？',
    choices:['Amazon SES (Simple Email Service)','Amazon SNS','Amazon Connect','AWS Direct Connect'], correct:[0],
    why:['正しい。Amazon SESは、独自のメールアドレス・ドメインを使ってマーケティングメールやトランザクションメール（注文確認・パスワードリセット等）を低コストに送受信できるメールプラットフォームです。','誤り。SNSはPub/Sub型の通知サービスで、SMSやモバイルプッシュ、メール等の通知配信は可能ですが、独自ドメインでの大量メール送信基盤としてはSESが主に使われます。','誤り。Amazon Connectはクラウド型のコンタクトセンター（コールセンター）サービスです。','誤り。Direct ConnectはオンプレミスとAWSの専用線接続サービスで、メール送信とは無関係です。']},
  {id:'p270', domain:'tech', type:'single', source:SOURCES.ses, text:'自社のメールアドレス・独自ドメインを使って、注文確認メールなどのトランザクションメールを大量に送信したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon Simple Email Service (SES)','Amazon Simple Notification Service (SNS)','Amazon Simple Queue Service (SQS)','AWS Lambda'], correct:[0],
    why:['正しい。Amazon SESは、独自のメールアドレス・ドメインを使ってマーケティングメールやトランザクションメール（注文確認等）を低コストで送受信できるメールプラットフォームです。','誤り。SNSはパブリッシュ/サブスクライブ型の通知サービスで、SMS・プッシュ通知・メール通知等に対応しますが、独自ドメインでの大量トランザクションメール送信に特化したサービスではありません。','誤り。SQSはメッセージキューイングサービスで、メール送信機能はありません。','誤り。AWS Lambdaはサーバーレスのコード実行サービスで、メール送信機能自体は持ちません（SES等と組み合わせて使うことはあります）。']},
  {id:'p271', domain:'tech', type:'single', source:SOURCES.s3StorageClasses, text:'アクセス頻度が不規則で予測しづらいデータを保存する際、アクセスパターンに応じて自動的に最適なコスト階層(アクセスティア)にオブジェクトを移動させ、取得料金もかけずにコストを最適化したい場合、最も適したS3ストレージクラスはどれですか？',
    choices:['S3 Standard','S3 Intelligent-Tiering','S3 Glacier Deep Archive','S3 One Zone-IA'], correct:[1],
    why:['誤り。S3 Standardは頻繁にアクセスされるデータ向けの標準クラスで、アクセス頻度に応じた自動最適化機能はありません。','正しい。S3 Intelligent-Tieringは、オブジェクトへのアクセス頻度を監視し、追加の運用負荷や取得料金なしでアクセスパターンに応じた最適なコスト階層へ自動的に移動させます。','誤り。S3 Glacier Deep Archiveは年1〜2回程度のアクセスを想定した最低コストの長期アーカイブ用クラスで、取得には時間がかかります。','誤り。S3 One Zone-IAは単一のアベイラビリティーゾーンにのみデータを保持する低頻度アクセス向けクラスで、自動階層化機能はありません。']},
  {id:'p272', domain:'security', type:'single', source:SOURCES.acm, text:'パブリックに公開するWebサイト用のSSL/TLS証明書を取得し、Elastic Load BalancingやCloudFrontに無料で自動的にデプロイ・更新（ローテーション）したい場合、最も適したサービスはどれですか？',
    choices:['AWS KMS','AWS Certificate Manager (ACM)','AWS Secrets Manager','AWS CloudHSM'], correct:[1],
    why:['誤り。KMSは暗号鍵の作成・管理サービスで、SSL/TLS証明書の発行・自動更新は主目的ではありません。','正しい。AWS Certificate Manager (ACM) は、SSL/TLS証明書を無料で発行し、ELBやCloudFront等のAWSサービスに自動的にデプロイ・更新できます。','誤り。Secrets Managerはデータベース認証情報等のシークレットの保管・ローテーションを行うサービスで、SSL/TLS証明書の発行は主目的ではありません。','誤り。CloudHSMは専用のハードウェアセキュリティモジュールで鍵を管理するサービスです。']},
  {id:'p273', domain:'security', type:'single', source:SOURCES.inspector, text:'EC2インスタンスやコンテナイメージに既知の脆弱性（CVE）が存在しないか、ソフトウェアの構成を継続的にスキャンして検出したい場合、最も適したサービスはどれですか？',
    choices:['Amazon GuardDuty','AWS Config','Amazon Macie','Amazon Inspector'], correct:[3],
    why:['誤り。GuardDutyはCloudTrailログやネットワークトラフィック等を分析し、不審な挙動や脅威を検知するサービスで、ソフトウェアの脆弱性スキャンは主目的ではありません。','誤り。Configはリソースの構成とその変更履歴を記録・評価するサービスで、脆弱性スキャンは主目的ではありません。','誤り。Macieは主にS3内の個人情報等の機密データを検出するサービスです。','正しい。Amazon Inspectorは、EC2インスタンス・コンテナイメージ・Lambda関数を継続的にスキャンし、既知の脆弱性(CVE)やネットワーク到達性の問題を検出します。']},
  {id:'p274', domain:'tech', type:'single', source:SOURCES.documentdb, text:'既存のMongoDBワークロードを、互換性を保ちながらマネージド型のサービスへ移行したい場合、最も適したサービスはどれですか？',
    choices:['Amazon Neptune','Amazon Aurora','Amazon DynamoDB','Amazon DocumentDB'], correct:[3],
    why:['誤り。Neptuneはグラフデータベースで、MongoDBとの互換性はありません。','誤り。AuroraはMySQL/PostgreSQL互換のリレーショナルデータベースです。','誤り。DynamoDBは独自のAPIを持つNoSQLデータベースで、MongoDB APIとの互換性はありません。','正しい。Amazon DocumentDBはMongoDBワークロードと互換性のあるマネージド型ドキュメントデータベースサービスです。']},
  {id:'p275', domain:'tech', type:'single', source:SOURCES.documentdb, text:'既存のMongoDBアプリケーションを、同じドライバー・ツールを使いながらフルマネージドなAWS環境に移行したい場合、最も適したデータベースサービスはどれですか？',
    choices:['Amazon Neptune','Amazon DynamoDB','Amazon Aurora','Amazon DocumentDB'], correct:[3],
    why:['誤り。Neptuneはグラフデータベースで、MongoDB互換のドキュメント指向ワークロードには対応していません。','誤り。DynamoDBはキーバリュー型のNoSQLデータベースで、MongoDB互換のドライバーはそのまま使用できません。','誤り。AuroraはMySQL/PostgreSQL互換のリレーショナルデータベースで、MongoDB互換ではありません。','正しい。Amazon DocumentDBはMongoDB互換のフルマネージドドキュメントデータベースで、同じドライバー・ツールを使用できます。']},
  {id:'p276', domain:'security', type:'multi', source:SOURCES.guardduty, text:'Amazon GuardDuty、AWS Security Hub、Amazon Detectiveの役割の組み合わせとして正しいものを2つ選択してください。',
    choices:['GuardDutyは機械学習を用いて悪意ある活動や異常な動作を継続的に検知する脅威検出サービスである','Security Hubは各サービスからのセキュリティの検出結果を一元的に集約・優先順位付けするサービスである','Detectiveは物理データセンターへの不正侵入を検知するサービスである','GuardDutyはネットワークファイアウォールとしてインバウンド/アウトバウンドの通信を直接ブロックするサービスである'], correct:[0,1],
    why:['正しい。GuardDutyは機械学習や脅威インテリジェンスを用いて、異常な動作や既知の悪意ある活動を継続的に検知する脅威検出サービスです。','正しい。Security Hubは、GuardDutyやInspector等複数のサービスのセキュリティ検出結果を一元的に集約・優先順位付けするサービスです。','誤り。Detectiveはセキュリティ検出結果の根本原因をグラフで可視化し調査を支援するサービスで、物理的な侵入検知は行いません。','誤り。GuardDutyは検知に特化したサービスで、通信を直接ブロックする機能は持ちません（ブロックはNetwork FirewallやセキュリティグループなどAWS Network Firewall等が担います）。']},
  {id:'p277', domain:'concepts', type:'single', source:SOURCES.mgn, text:'大量のオンプレミスサーバーを、ソースコードやアーキテクチャを変更せずにできるだけ早くAWSへ移行（リホスト）したい場合、最も適したサービスはどれですか？',
    choices:['AWS Transform MGN','AWS Database Migration Service (DMS)','AWS DataSync','AWS Snowball'], correct:[0],
    why:['正しい。MGNはサーバーを継続的にレプリケーションし、アーキテクチャを変更せずに最小ダウンタイムでリホスト移行を自動化します。','誤り。DMSはデータベースの移行に特化したサービスです。','誤り。DataSyncはファイルデータの転送・同期サービスで、サーバー全体の移行には使いません。','誤り。Snowballは物理デバイスを使った大容量データのオフライン転送サービスです。']},
  {id:'p278', domain:'tech', type:'single', source:SOURCES.ecr, text:'Dockerコンテナイメージを安全に保存し、Amazon ECSやEKSなどからプルして利用したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon S3','AWS CodeCommit','Amazon ECR','AWS Systems Manager'], correct:[2],
    why:['誤り。S3はオブジェクトストレージであり、コンテナイメージ専用のレジストリ機能（タグ管理やECSとの統合等）は持ちません。','誤り。CodeCommitはソースコードのバージョン管理（Gitリポジトリ）サービスです。','正しい。Amazon ECR (Elastic Container Registry) は、Dockerコンテナイメージを安全に保存・管理できるフルマネージド型のレジストリサービスです。','誤り。Systems Managerはサーバー等の運用管理サービスです。']},
  {id:'p279', domain:'tech', type:'multi', source:SOURCES.ecs, text:'コンテナ化されたアプリケーションのオーケストレーション（コンテナの配置・スケーリング・管理）を行うサービスとして正しいものを2つ選択してください。',
    choices:['AWS Lambda','Amazon ECS (Elastic Container Service)','Amazon RDS','Amazon EKS (Elastic Kubernetes Service)'], correct:[1,3],
    why:['誤り。Lambdaはイベント駆動型のサーバーレスコンピューティングサービスで、コンテナオーケストレーション専用のサービスではありません。','正しい。Amazon ECSはAWS独自のコンテナオーケストレーションサービスです。','誤り。RDSはマネージド型のリレーショナルデータベースサービスです。','正しい。Amazon EKSはマネージド型のKubernetesサービスで、コンテナのオーケストレーションを行います。']},
  {id:'p280', domain:'tech', type:'multi', source:SOURCES.ecs, text:'AWS上でコンテナを「オーケストレーション（コンテナ群のスケジューリングや管理）」するためのサービスを2つ選択してください。',
    choices:['Amazon ECS','Amazon ECR','AWS Fargate','Amazon EKS'], correct:[0,3],
    why:['正しい。Amazon ECSはAWS独自のコンテナオーケストレーションサービスです。','誤り。ECRはコンテナイメージを保存するレジストリサービスで、オーケストレーション機能はありません。','誤り。Fargateはコンテナを実行するためのサーバーレスなコンピューティングエンジン(起動タイプ)で、ECSやEKSと組み合わせて使われますが、オーケストレーター自体はECS/EKSです。','正しい。Amazon EKSはマネージド型のKubernetesサービスで、コンテナのオーケストレーションを行います。']},
  {id:'p281', domain:'tech', type:'single', source:SOURCES.stepFunctions, text:'複数のAWS Lambda関数やその他のAWSサービスを、順序や条件分岐を含むワークフローとして組み合わせてオーケストレーションしたい場合、最も適切なサービスはどれですか？',
    choices:['Amazon EventBridge','AWS Step Functions','Amazon SNS','AWS Batch'], correct:[1],
    why:['誤り。EventBridgeはイベント駆動のルーティングサービスで、複雑な順序・条件分岐を持つワークフロー全体の管理には向きません。','正しい。AWS Step Functionsは、複数のLambda関数やAWSサービスを順序・条件分岐を含むワークフローとして視覚的にオーケストレーションできるサービスです。','誤り。SNSはパブリッシュ/サブスクライブ型の通知サービスです。','誤り。Batchはバッチ処理ジョブの実行を管理するサービスです。']},
  {id:'p282', domain:'concepts', type:'single', source:SOURCES.resilienceHub, text:'あるチームが、本番環境のアプリケーションについて「障害発生時にどの程度の時間で復旧できるか」といった復旧目標を定義し、それを評価・継続的に改善したいと考えている。最も適切なサービスはどれですか？',
    choices:['AWS Trusted Advisor','AWS Resilience Hub','AWS Cost Explorer','AWS Artifact'], correct:[1],
    why:['誤り。Trusted Advisorはコスト・パフォーマンス・セキュリティ等のベストプラクティス推奨を提示しますが、アプリケーション単位のレジリエンス目標設定・評価には特化していません。','正しい。AWS Resilience Hubは、Well-Architected Frameworkに基づきアプリケーションのレジリエンス目標を設定・評価し、改善の推奨事項を提示します。','誤り。Cost Explorerはコスト分析ツールです。','誤り。Artifactはコンプライアンスレポートを取得するサービスです。']},
  {id:'p283', domain:'tech', type:'single', source:SOURCES.translate, text:'ユーザーが投稿したテキストを、機械学習を使って別の言語に自動翻訳する機能をアプリケーションに追加したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon Translate','Amazon Comprehend','Amazon Transcribe','Amazon Polly'], correct:[0],
    why:['正しい。Amazon Translateは機械学習を使ってテキストを別の言語に翻訳するサービスです。','誤り。Comprehendはテキストから感情分析やエンティティ抽出を行う自然言語処理サービスで、翻訳機能ではありません。','誤り。Transcribeは音声をテキストに変換するサービスです。','誤り。Pollyはテキストを音声に変換するサービスです。']},
  {id:'p284', domain:'billing', type:'multi', source:SOURCES.billingConductor, text:'AWS Billing Conductorの特徴として正しいものを2つ選択してください。',
    choices:['AWS Marketplaceのチャネルパートナーや、組織内のチャージバック要件に対応するための独自の料金ルールを設定できる','設定することで実際にAWSから発行される請求書(インボイス)の金額自体が変更される','複数アカウントを自動でリザーブドインスタンスの割引対象に追加する','アカウントをビリンググループにまとめ、独自に設定した料金（プロフォーマコスト）に基づくレポートを提供する'], correct:[0,3],
    why:['正しい。Billing Conductorはチャネルパートナーやチャージバック要件向けに、独自の料金ルール(pricing rules)を設定できます。','誤り。Billing Conductorの設定は実際のAWSインボイスの金額には影響しません（内部的なプロフォーマコストのみ変わります）。','誤り。リザーブドインスタンスの割引適用はAWS Organizationsの一括請求の仕組みで、Billing Conductorの主目的ではありません。','正しい。アカウントをビリンググループにまとめ、独自料金に基づくプロフォーマコストのレポートを提供します。']},
  {id:'p285', domain:'billing', type:'single', source:SOURCES.billingConductor, text:'AWSのリセラー事業者が、エンドカスタマーごとに独自の料金ルールを適用したプロフォーマ(見なし)コストを作成し、実際のAWS課金とは別にカスタムな請求書・チャージバックを行いたい場合、最も適切なサービスはどれですか？',
    choices:['AWS Budgets','AWS Billing Conductor','AWS Cost Explorer','AWS Organizations'], correct:[1],
    why:['誤り。Budgetsは予算の閾値に基づくアラート機能であり、カスタム請求ルールの作成は行いません。','正しい。AWS Billing Conductorは、独自の価格ルールに基づくプロフォーマコストを作成し、パートナーやエンドカスタマー向けにカスタムな請求・チャージバックを実現するサービスです。','誤り。Cost Explorerはコストの可視化・分析ツールで、カスタム請求書の作成機能は持ちません。','誤り。Organizationsは複数アカウントの一括請求(実際のAWS課金そのまま)を行うサービスで、独自の料金ルールへの変換は行いません。']},
  {id:'p286', domain:'concepts', type:'single', source:SOURCES.rtorpo, text:'あるシステムで、「最後に取得したバックアップ(復旧時点)から障害発生までの間に許容できるデータ損失は最大15分まで」という要件が定められている。この要件が表す指標は何ですか？',
    choices:['目標復旧時間(RTO)','目標復旧時点(RPO)','可用性(Availability)','耐久性(Durability)'], correct:[1],
    why:['誤り。RTOはサービス中断から復旧までに許容できる時間を表し、データ損失の許容量ではありません。','正しい。RPOは直前の復旧時点から障害発生までの間に許容できる最大のデータ損失期間を表す指標で、本問の「15分」はRPOに相当します。','誤り。可用性は一定期間にわたるシステムの稼働率を表す指標で、個々の障害時のデータ損失量を直接表すものではありません。','誤り。耐久性はデータが失われない性質を表す概念で、障害発生時に許容するデータ損失期間を定める指標ではありません。']},
  {id:'p287', domain:'concepts', type:'single', source:SOURCES.rtorpo, text:'大規模システム障害からの復旧において、「サービス中断から復旧までに許容できる最大の時間」を表す指標は何ですか？',
    choices:['目標復旧時間(RTO: Recovery Time Objective)','目標復旧時点(RPO: Recovery Point Objective)','平均復旧時間(MTTR: Mean Time to Recovery)','サービスレベルアグリーメント(SLA)'], correct:[0],
    why:['正しい。RTOは、サービス中断の発生から復旧までに許容できる最大の時間を定義する指標です。','誤り。RPOは直前の復旧時点から許容できる最大のデータ損失期間を表す指標で、時間ではなくデータ損失の許容範囲を定義します。','誤り。MTTRは複数の障害イベントにおける復旧時間の平均値であり、単一イベントに対する目標値であるRTOとは異なります。','誤り。SLAはサービス提供者が保証する可用性等の水準を定めた合意であり、個々の障害からの復旧目標を直接定義するものではありません。']},
  {id:'p288', domain:'billing', type:'single', source:SOURCES.savingsplansTypes, text:'特定のインスタンスファミリーやリージョンに縛られず、EC2・Fargate・Lambdaを横断して柔軟に割引を適用したい場合に最も適したSavings Plansの種類はどれですか？',
    choices:['EC2 Instance Savings Plans','リザーブドインスタンス','Compute Savings Plans','オンデマンド'], correct:[2],
    why:['誤り。EC2 Instance Savings Plansは割引率が高い分、特定のインスタンスファミリー・リージョンに適用が限定されます。','誤り。リザーブドインスタンスは特定のインスタンスタイプ・リージョンへの予約が基本であり、サービス横断の柔軟性はありません。','正しい。Compute Savings Plansは、インスタンスファミリー・リージョン・OS等を問わずEC2・Fargate・Lambdaの利用に柔軟に適用できます。','誤り。オンデマンドは割引のない標準料金モデルです。']},
  {id:'p289', domain:'billing', type:'multi', source:SOURCES.savingsplansTypes, text:'コンピューティングリソースの利用について、長期的な使用量をコミットすることで割引を受けられる購入オプションを2つ選択してください。',
    choices:['リザーブドインスタンス','スポットインスタンス','Savings Plans','On-Demand Capacity Reservation'], correct:[0,2],
    why:['正しい。リザーブドインスタンスは1年または3年の利用をコミットすることで割引を受けられる購入オプションです。','誤り。スポットインスタンスは空き容量の活用による割引で、長期的な利用コミットメントに基づく割引ではありません。','正しい。Savings Plansも1年または3年の利用コミットメント(USD/時間)に基づいて割引を受けられる購入オプションです。','誤り。On-Demand Capacity Reservationは容量確保が目的で、長期コミットメントによる料金の割引は提供しません。']},
  {id:'p290', domain:'tech', type:'single', source:SOURCES.amazonMQ, text:'オンプレミスで稼働している既存のApache ActiveMQベースのメッセージングアプリケーションを、メッセージングコードを書き換えずにAWSのマネージドサービスへ移行したい。最も適切なサービスはどれですか？',
    choices:['Amazon SQS','Amazon SNS','Amazon EventBridge','Amazon MQ'], correct:[3],
    why:['誤り。SQSはAWS独自のキューサービスで、既存のActiveMQ/RabbitMQ向けのメッセージングコードをそのまま使うことはできません。','誤り。SNSはパブリッシュ/サブスクライブ型の通知サービスで、既存のメッセージブローカー向けコードの移行には向きません。','誤り。EventBridgeはイベントルーティングサービスで、既存のメッセージブローカープロトコルをそのまま扱うものではありません。','正しい。Amazon MQは、Apache ActiveMQやRabbitMQといった業界標準のメッセージブローカーのマネージドサービスで、既存のメッセージングコードを書き換えずに移行できます。']},
  {id:'p291', domain:'tech', type:'single', source:SOURCES.amazonMQ, text:'Amazon MQとAmazon SQSの違いとして最も適切なものはどれですか？',
    choices:['Amazon MQは既存のActiveMQ/RabbitMQ互換アプリケーションをそのまま移行できる業界標準プロトコル対応のメッセージブローカーであるのに対し、Amazon SQSはAWS独自APIに基づくフルマネージドのキューサービスである','Amazon MQはオブジェクトストレージであるのに対し、Amazon SQSはブロックストレージである','Amazon MQはリレーショナルデータベースであるのに対し、Amazon SQSはNoSQLデータベースである','両者は全く同じ機能を提供し、互換性のあるAPIを持つ'], correct:[0],
    why:['正しい。Amazon MQは既存のActiveMQ/RabbitMQベースのアプリケーションをコード変更なしで移行できる業界標準プロトコル対応のブローカーで、SQSはAWS独自APIのフルマネージドキューサービスです。','誤り。両者ともストレージサービスではありません。','誤り。両者ともデータベースサービスではありません。','誤り。APIやプロトコルの互換性は異なり、用途によって使い分けられます。']},
  {id:'p292', domain:'billing', type:'single', source:SOURCES.free, text:'AWSアカウントを新規作成した利用者が、作成から一定期間(6か月間)に限り利用できる仕組みとして正しいものはどれですか？',
    choices:['常時無料サービス(Always Free)','ベーシックサポートプラン','短期トライアル(Short-Term Free Trials)','新規アカウント向けの無料クレジット'], correct:[3],
    why:['誤り。常時無料サービスはアカウント作成からの期間に関わらず一定の範囲内で常に無料利用できるサービス群で、6か月間限定ではありません。','誤り。ベーシックサポートプランは期間限定の無料枠ではなく、全アカウントに常時無料で提供されるサポートプランです。','誤り。短期トライアルは特定サービスについて数日〜数週間程度の短い期間だけ提供される無料枠で、6か月間ではありません。','正しい。新規アカウント向けの無料クレジット(例: $200相当)は、アカウント作成から6か月間に限り利用できる仕組みです。']},
  {id:'p293', domain:'security', type:'single', source:SOURCES.mfa, text:'AWSアカウントのルートユーザーについて、パスワード漏洩時のリスクを軽減するために最初に設定すべき対策として最も適切なものはどれですか？',
    choices:['多要素認証（MFA）の設定','AWS WAFのルール設定','セキュリティグループの設定','VPCピアリングの設定'], correct:[0],
    why:['正しい。ルートユーザーはアカウントへの無制限のアクセス権を持つため、パスワードに加えてMFAを設定し、サインイン時に追加の認証要素を必須にすることが強く推奨されます。','誤り。AWS WAFはWebアプリケーションへの悪意ある通信をフィルタするサービスで、ルートユーザーの認証強化とは関係ありません。','誤り。セキュリティグループはEC2インスタンス等のインバウンド/アウトバウンド通信を制御するもので、アカウントのサインイン認証とは異なります。','誤り。VPCピアリングは複数VPC間の通信を可能にする仕組みで、アカウントの認証強化とは関係ありません。']},
  {id:'p294', domain:'security', type:'single', source:SOURCES.mfa, text:'AWSアカウントのルートユーザーを保護するためのベストプラクティスとして最も適切なものはどれですか？',
    choices:['ルートユーザーのアクセスキーを作成し、日常のプログラムからのアクセスに使用する','ルートユーザーのパスワードを複数の管理者で共有して利用する','ルートユーザーに最小権限のIAMポリシーを直接アタッチして運用する','ルートユーザーに多要素認証(MFA)を設定し、日常的なタスクには使用しない'], correct:[3],
    why:['誤り。ルートユーザーのアクセスキーを作成し日常的に使用することは推奨されず、漏えいのリスクを高めます。','誤り。認証情報を複数人で共有することは責任の所在を不明確にし、セキュリティ上のベストプラクティスに反します。','誤り。ルートユーザーにはIAMポリシーを直接アタッチすることができず、権限を制限する管理はできません。','正しい。ルートユーザーにはMFAを設定し、日常的なタスクには権限を制限したIAMユーザーを使用することが推奨されます。']},
  {id:'p295', domain:'security', type:'single', source:SOURCES.compliancePrograms, text:'AWSが取得している第三者機関の認証(ISO 27001、SOC 2、PCI DSSなど)や準拠している法規制・プライバシー要件の全体像を確認できる公式情報区分を何と呼びますか？',
    choices:['AWSコンプライアンスプログラム(AWS Compliance Programs)','AWS Artifact','AWS Trusted Advisor','責任共有モデル(Shared Responsibility Model)'], correct:[0],
    why:['正しい。AWSコンプライアンスプログラムは、AWSが取得している認証・準拠している規制やプライバシー要件を「認証・証明」「法規制・プライバシー」「アライメント・フレームワーク」のカテゴリで整理したものです。','誤り。AWS Artifactは、これらの認証に関する監査報告書や合意書を実際にオンデマンドで入手できるセルフサービスポータルです。','誤り。AWS Trusted Advisorは、コスト・セキュリティ・耐障害性等の観点からベストプラクティスをチェックするサービスで、第三者認証の一覧ではありません。','誤り。責任共有モデルは、セキュリティ責任をAWSと顧客間でどう分担するかを示す概念で、第三者認証の一覧ではありません。']},
  {id:'p296', domain:'concepts', type:'single', source:SOURCES.migrationEvaluator, text:'自社のオンプレミスサーバーの使用状況データを分析し、過剰プロビジョニングを特定した上で、AWS移行後の想定コストを算出してクラウド移行のビジネスケースを作りたい。最も適したサービスはどれですか？',
    choices:['AWS Migration Evaluator','AWS Compute Optimizer','AWS Pricing Calculator','AWS Cost Explorer'], correct:[0],
    why:['正しい。Migration Evaluatorは、オンプレミスの使用状況データを分析し、移行後の想定コストを算出してデータドリブンな移行のビジネスケースを構築できるサービスです。','誤り。Compute Optimizerは既にAWS上で稼働しているリソースの使用率を分析し、インスタンスタイプ等の最適化を提案するサービスで、オンプレミスの移行前分析には使いません。','誤り。Pricing Calculatorは、構成を手動で入力してAWS利用料金を事前見積もりするツールで、オンプレミスの実使用データの分析はできません。','誤り。Cost Explorerは、AWS利用後の実際のコスト・使用量を可視化・分析するツールで、移行前のオンプレミス分析には使いません。']},
  {id:'p297', domain:'concepts', type:'multi', source:SOURCES.wafOps, text:'AWS Well-Architected Frameworkの「運用上の優秀性の柱」が推奨するプラクティスとして正しいものを2つ選択してください。',
    choices:['将来の需要に備えて、使用する可能性のあるハードウェアを事前に大量購入しておく','変更は小規模かつ頻繁に行い、問題が発生した場合に元に戻せる(可逆的な)設計にする','運用手順は一度整備したら変更せず、長期間同じ手順を維持する','運用上のイベントや障害から学び、手順(runbook/playbook)を定期的に見直し改善する'], correct:[1,3],
    why:['誤り。ハードウェアの事前大量購入はクラウドの弾力性の利点を活かせず、運用上の優秀性の柱が推奨する内容ではありません。','正しい。小規模・頻繁かつ可逆的な変更を行うことは、運用上の優秀性の柱が推奨するプラクティスです。','誤り。運用手順は継続的に見直し・改善することが推奨されており、長期間固定化することは推奨されません。','正しい。障害やイベントから学び、手順を継続的に改善することは運用上の優秀性の柱が重視する内容です。']},
  {id:'p298', domain:'concepts', type:'single', source:SOURCES.wafOps, text:'Well-Architected Frameworkの「運用上の優秀性の柱」が重視する考え方として最も適切なものはどれですか？',
    choices:['データを暗号化し、最小権限の原則を徹底する','需要予測を不要にし、使った分だけ支払う','運用を「コードとして」記述し、小さく頻繁に変更を行い、イベントへの対応手順を事前に準備する','複数のアベイラビリティーゾーンにリソースを分散し障害に備える'], correct:[2],
    why:['誤り。これはセキュリティの柱の考え方です。','誤り。これはコスト最適化の柱、またはクラウドの俊敏性に関する考え方です。','正しい。運用上の優秀性の柱は、運用手順をコード化し、小さく頻繁な変更を行い、障害に備えて対応手順を事前に準備・改善することを重視します。','誤り。これは信頼性の柱の考え方です。']},
  {id:'p299', domain:'tech', type:'single', source:SOURCES.aurora, text:'標準的なMySQL/PostgreSQL互換のリレーショナルデータベースについて、オープンソース版と比較してスループットの向上と高可用性を得たい場合、最も適切なサービスはどれですか？',
    choices:['Amazon DynamoDB','Amazon Redshift','Amazon ElastiCache','Amazon Aurora'], correct:[3],
    why:['誤り。DynamoDBはNoSQLデータベースで、MySQL/PostgreSQL互換ではありません。','誤り。Redshiftはデータウェアハウスで、OLTP用途のリレーショナルデータベースではありません。','誤り。ElastiCacheはインメモリキャッシュサービスで、永続的なリレーショナルデータベースではありません。','正しい。Amazon Auroraは、MySQL/PostgreSQL互換で、標準的なオープンソースデータベースと比較して高いスループットと高可用性を提供するマネージド型データベースです。']},
  {id:'p300', domain:'billing', type:'single', source:SOURCES.awsHealth, text:'AWS Health APIを使って、自社の監視システムにAWSサービスの状態や自分のアカウントへの影響に関する情報を統合したい場合、最低限必要となるサポートプランはどれですか？',
    choices:['AWS Business Support+、AWS Enterprise Support、またはAWS Unified Operations','AWS Basic Support(追加契約不要)','AWS Developer Support相当の無料プラン','サポートプランに関係なく誰でも利用できる'], correct:[0],
    why:['正しい。AWS Health APIの利用には、AWS Business Support+、AWS Enterprise Support、またはAWS Unified Operationsのいずれかのサポートプランが必要です。','誤り。Basic SupportではコンソールのAWS Health Dashboardは利用できますが、Health APIは利用できません。','誤り。「Developer Support」という無料プランはなく、Health APIには上位プランの契約が必要です。','誤り。AWS Health Dashboard自体はすべての利用者が無料で見られますが、Health APIには上位サポートプランが必要です。']},
  {id:'p301', domain:'security', type:'single', source:SOURCES.vpc, text:'ネットワークACL(NACL)に関する正しい説明はどれですか？',
    choices:['ルール番号の小さい順に評価され、一致した時点でそのルール(許可または拒否)が適用されるステートレスなサブネット単位のファイアウォール','インスタンス(ENI)に直接アタッチされ、許可ルールのみを設定できるステートフルなファイアウォール','VPCエンドポイント経由でAWSサービスにプライベート接続するための仕組み','DDoS攻撃を自動的に検知・緩和するマネージドサービス'], correct:[0],
    why:['正しい。NACLはサブネット単位で動作し、ルール番号の小さい順に評価され、最初に一致したルール(許可または拒否)が適用されるステートレスなファイアウォールです。','誤り。これはセキュリティグループの説明です。','誤り。これはAWS PrivateLinkの説明です。','誤り。これはAWS Shieldの説明です。']},
  {id:'p302', domain:'tech', type:'single', source:SOURCES.siteToSiteVpn, text:'オンプレミスとAWSを接続する手段のうち、「公共のインターネットを経由して暗号化トンネルを確立する」という特徴を持つものはどれですか？',
    choices:['AWS Direct Connect','AWS PrivateLink','AWS Site-to-Site VPN','AWS Transit Gateway'], correct:[2],
    why:['誤り。Direct Connectは専用線を使用し、インターネットを経由しません。','誤り。PrivateLinkはVPCエンドポイント経由のプライベート接続で、オンプレミスとの接続やインターネット経由の暗号化トンネルとは異なります。','正しい。AWS Site-to-Site VPNは、IPsecにより公共のインターネットを経由して暗号化トンネル(VPN接続)を確立します。','誤り。Transit Gatewayは複数のVPC/オンプレミス接続を相互接続するハブであり、それ自体がインターネット経由の暗号化トンネルを提供するものではありません。']},
  {id:'p303', domain:'security', type:'single', source:SOURCES.siteToSiteVpn, text:'専用線の新設工事を待たずに、今すぐオンプレミスとVPCの間に暗号化された接続を確立したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Direct Connect','AWS Site-to-Site VPN','AWS PrivateLink','Amazon CloudFront'], correct:[1],
    why:['誤り。Direct Connectは専用線の物理的な配線工事が必要で、構築に時間がかかります。','正しい。Site-to-Site VPNは、IPsecを用いて公共のインターネット経由で暗号化された接続を確立でき、物理的な配線工事なしで迅速に利用を開始できます。','誤り。PrivateLinkはVPCエンドポイント経由でAWSサービス等にプライベート接続する仕組みで、オンプレミスとの接続が主目的ではありません。','誤り。CloudFrontはCDNサービスで、オンプレミスとの暗号化接続とは無関係です。']},
  {id:'p304', domain:'security', type:'single', source:SOURCES.parameterStore, text:'データベースの認証情報(パスワード)を保存し、定期的な自動ローテーションなどの機能を使いたい場合、AWS Systems Manager Parameter StoreよりもAWS Secrets Managerが推奨される理由として正しいものはどれですか？',
    choices:['Parameter StoreはそもそもAWSのサービスではないため','Parameter Storeは暗号化機能を全く持たないため','Secrets Managerは認証情報などのシークレット管理に特化し、データベースと連携した自動ローテーション機能を備えているが、Parameter Storeにはその機能がないため','Parameter Storeは有料だが、Secrets Managerは常に無料であるため'], correct:[2],
    why:['誤り。Parameter StoreはAWS Systems Managerの機能の一つです。','誤り。Parameter StoreもSecureString(AWS KMSによる暗号化)をサポートしています。','正しい。Secrets Managerは認証情報などのシークレット管理に特化しており、データベースと連携した自動ローテーション機能を備えています。Parameter Storeは静的な設定データの保存に向いており、自動ローテーション機能はありません。','誤り。Parameter Storeは標準タイプは無料ですが、Secrets Managerはシークレットごとに料金が発生する有料サービスです。']},
  {id:'p305', domain:'concepts', type:'single', source:SOURCES.snowFamily, text:'データセンターを閉鎖し、ペタバイト規模のデータをAWSへ移行したいが、ネットワーク帯域の制約から通常のオンライン転送では現実的な時間で完了できない。最も適したサービスはどれですか？',
    choices:['AWS DataSync','AWS Storage Gateway','AWS Snowball','AWS Direct Connect'], correct:[2],
    why:['誤り。DataSyncはネットワーク経由のオンラインデータ転送サービスで、帯域幅が制約となる超大規模なデータ移行には不向きです。','誤り。Storage Gatewayはオンプレミスとクラウドをオンラインでつなぐハイブリッドストレージサービスで、オフラインの物理転送は行いません。','正しい。AWS Snowballは、物理的なストレージデバイスを使ってペタバイト規模のデータをオフラインで輸送し、ネットワーク帯域の制約を回避してAWSへ移行できます。','誤り。Direct Connectはオンプレミスとの専用線接続を確立するサービスで、即座に大容量データを転送できる仕組みではありません。']},
  {id:'p306', domain:'tech', type:'single', source:SOURCES.outposts, text:'法令により特定の種類のデータを自社データセンター内に物理的に保持する必要があるが、そのデータセンター内でもAWSと同じAPI・ツール・ハードウェアを使い、クラウドと一貫性のある運用を行いたい。最も適したサービスはどれですか？',
    choices:['AWS Direct Connect','AWS Outposts','AWS Local Zones','AWS Snowball Edge'], correct:[1],
    why:['誤り。Direct Connectはオンプレミスとクラウド間の専用線接続サービスで、オンプレミス側にAWSのハードウェアを設置するものではありません。','正しい。AWS Outpostsは、顧客のデータセンター内にAWSが設計したハードウェアを設置し、オンプレミスでもAWSと同じAPI・ツールを使って一貫性のある運用を行えるサービスです。','誤り。Local ZonesはAWSが運用する拠点であり、顧客自身のデータセンター内に設置されるものではありません。','誤り。Snowball Edgeは一時的なエッジコンピューティング・データ転送用のデバイスで、永続的なオンプレミス運用基盤としての用途ではありません。']},
  {id:'p307', domain:'billing', type:'single', source:SOURCES.computeOptimizer, text:'現在使用しているEC2インスタンスの多くが実際の使用率に対して過剰にプロビジョニングされている可能性がある。機械学習を用いた使用率データの分析に基づき、よりコスト効率の良いインスタンスタイプへの変更を推奨してもらいたい。最も適したサービスはどれですか？',
    choices:['AWS Budgets','AWS Cost Explorer','AWS Trusted Advisor','AWS Compute Optimizer'], correct:[3],
    why:['誤り。Budgetsは予算の設定とアラート通知を行うサービスです。','誤り。Cost Explorerは過去のコストの可視化・分析ツールで、リソースタイプ変更の推奨は主目的ではありません。','誤り。Trusted Advisorはベストプラクティス全般の推奨事項を提示しますが、機械学習による使用率分析に特化したものではありません。','正しい。AWS Compute Optimizerは、機械学習を用いてEC2・Lambda等の使用率データを分析し、コスト削減とパフォーマンス向上につながるライトサイジングを推奨します。']},
  {id:'p308', domain:'tech', type:'multi', source:SOURCES.amazonMQ, text:'Amazon MQが標準でサポートするメッセージブローカーエンジンとして正しいものを2つ選択してください。',
    choices:['Apache ActiveMQ','Apache Kafka','RabbitMQ','Amazon SQS'], correct:[0,2],
    why:['正しい。Amazon MQはApache ActiveMQをサポートするマネージド型メッセージブローカーサービスです。','誤り。Kafkaはストリーミングデータ処理の仕組みで、Amazon MQが提供するブローカーエンジンではありません(Kafka互換のマネージドサービスはAmazon MSKです)。','正しい。Amazon MQはRabbitMQもサポートするマネージド型メッセージブローカーサービスです。','誤り。Amazon SQSは別のAWSのキューイングサービスであり、Amazon MQがサポートする「ブローカーエンジン」ではありません。']},
  {id:'p309', domain:'security', type:'single', source:SOURCES.config, text:'あるAWSリソースの設定が、社内で定めたコンプライアンスルール(例: 全てのEBSボリュームを暗号化する)に準拠しているかどうかを継続的に評価し、違反があれば記録したい場合、最も適切なサービスはどれですか？',
    choices:['AWS CloudTrail','Amazon GuardDuty','AWS Config','Amazon Inspector'], correct:[2],
    why:['誤り。CloudTrailは誰がいつどのAPIを呼び出したかを記録するサービスで、リソースの設定自体の継続的な評価は行いません。','誤り。GuardDutyは機械学習による脅威検知サービスで、設定のコンプライアンス評価が主目的ではありません。','正しい。AWS Configは、リソースの構成を継続的に記録・評価し、指定したルールに準拠しているかどうかをチェックできます。','誤り。Inspectorは主にEC2やコンテナイメージの脆弱性スキャンを行うサービスです。']},
  {id:'p310', domain:'tech', type:'single', source:SOURCES.emr, text:'オンプレミスで運用していたApache Hadoop/Sparkクラスターによる大規模データ処理を、クラスターの構築・管理の手間を抑えつつクラウド上に移行したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon EMR','Amazon Athena','AWS Glue','Amazon Redshift'], correct:[0],
    why:['正しい。Amazon EMRは、Apache HadoopやSparkなどのクラスターをEC2・EKS・サーバーレス上で簡単に構築・拡張・管理できるマネージドのビッグデータ処理サービスです。','誤り。AthenaはS3上のデータに対する標準SQLクエリの実行に特化したサーバーレス分析サービスで、Hadoop/Sparkクラスターの運用とは異なります。','誤り。GlueはサーバーレスのETL(データ変換・統合)サービスで、Hadoop/Sparkクラスター全体の移行先としては主目的が異なります。','誤り。RedshiftはSQLベースのデータウェアハウスで、Hadoop/Sparkのクラスター処理基盤ではありません。']},
  {id:'p311', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'クラウドコンピューティングの6つの利点のうち、「わずか数クリックで新しいリージョンにアプリケーションをデプロイし、数分で世界中の顧客に低レイテンシでサービスを提供できる」という利点を表す用語はどれですか？',
    choices:['グローバル展開の迅速化（Go Global in Minutes）','可変費への変換（Trade Capital Expense for Variable Expense）','規模の経済によるコスト削減（Benefit from Massive Economies of Scale）','スピードと俊敏性の向上（Increase Speed and Agility）'], correct:[0],
    why:['正しい。クラウドの利点の一つ「Go Global in Minutes」は、AWSの世界中のリージョンを利用して、わずか数クリックでアプリケーションを複数リージョンにデプロイし、低レイテンシで世界中の顧客にサービスを提供できることを指します。','誤り。これは固定的な先行投資（データセンター等）を利用量に応じた可変費に変換できるという利点の説明です。','誤り。これはAWSが多数の顧客の需要を集約することで、個々の企業単独では得られない規模の経済によるコスト削減を実現できるという利点の説明です。','誤り。これは必要なITリソースを数分で調達できることにより、新しいアイデアを試す際の実験・開発のスピードと俊敏性が向上するという利点の説明です。']},
  {id:'p312', domain:'concepts', type:'multi', source:SOURCES.waf, text:'次のうち、AWS Well-Architected Frameworkの柱として正しいものを2つ選択してください。',
    choices:['オペレーショナル・エクセレンスの柱','収益性の柱','セキュリティの柱','マーケティングの柱'], correct:[0,2],
    why:['正しい。運用上の優秀性(Operational Excellence)はWell-Architected Frameworkの6つの柱の一つです。','誤り。「収益性の柱」というWell-Architected Frameworkの柱は存在しません。','正しい。セキュリティの柱はWell-Architected Frameworkの6つの柱の一つです。','誤り。「マーケティングの柱」というWell-Architected Frameworkの柱は存在しません。']},
  {id:'p313', domain:'concepts', type:'single', source:SOURCES.hybridCloud, text:'「ハイブリッドクラウド」の説明として最も適切なものはどれですか？',
    choices:['単一の企業専用に構築され、他の組織とリソースを共有しないクラウド環境','オンプレミス環境とパブリッククラウド環境を接続し、ワークロードやデータを両方の環境にまたがって運用するデプロイモデル','インターネットを経由して誰でも利用できる、複数の組織が共有するクラウド環境','物理的なサーバーをすべて自社データセンター内に設置し、クラウドサービスを一切利用しない運用形態'], correct:[1],
    why:['誤り。これはプライベートクラウドの説明です。','正しい。ハイブリッドクラウドは、オンプレミス環境とパブリッククラウド環境を接続し、ワークロードやデータを両方の環境にまたがって運用するデプロイモデルです。','誤り。これはパブリッククラウドの説明です。','誤り。これはオンプレミス（クラウドを利用しない従来型の運用形態）の説明です。']},
  {id:'p314', domain:'security', type:'single', source:SOURCES.securityLake, text:'複数のAWSアカウント・リージョン、オンプレミス、SaaSプロバイダーなど多様なソースからセキュリティ関連のログ・イベントデータを自動的に収集し、OCSF（Open Cybersecurity Schema Framework）という標準スキーマに正規化して、自社アカウント内のデータレイクに集約したいです。最も適切なサービスはどれですか？',
    choices:['AWS CloudTrail','AWS Security Hub','Amazon Security Lake','Amazon GuardDuty'], correct:[2],
    why:['誤り。CloudTrailは誰がいつどのAPIを呼び出したかを記録するサービスで、多様なソースからのログを正規化してデータレイクに集約する機能はありません。','誤り。Security Hubは複数のセキュリティサービスの検出結果を集約して表示しますが、生ログをOCSF形式でデータレイクに集約する仕組みとは異なります。','正しい。Amazon Security Lakeは、AWS環境・オンプレミス・SaaS・サードパーティなど多様なソースからセキュリティログ・イベントデータを自動的に収集し、OCSFに正規化して自社アカウント内のデータレイク(S3)に集約するサービスです。','誤り。GuardDutyは機械学習による脅威検出サービスで、多様なソースのログを正規化して集約するデータレイクサービスではありません。']},
  {id:'p315', domain:'security', type:'single', source:SOURCES.macie, text:'Amazon S3バケットに保存された大量のデータの中から、氏名・クレジットカード番号などの個人を特定できる情報（PII）を機械学習とパターンマッチングによって自動的に検出・分類したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon Inspector','AWS Config','Amazon GuardDuty','Amazon Macie'], correct:[3],
    why:['誤り。Inspectorは主にEC2インスタンスやコンテナイメージ、Lambda関数の脆弱性スキャンを行うサービスで、S3内のデータ内容の機密情報検出は行いません。','誤り。Configはリソースの構成の継続的な評価・記録を行うサービスで、データ内容の機密情報検出は行いません。','誤り。GuardDutyは機械学習による脅威検出サービスで、S3内のデータ内容そのものの機密情報検出が主目的ではありません。','正しい。Amazon Macieは、機械学習とパターンマッチングを用いて、S3に保存されたデータの中から個人を特定できる情報（PII）などの機密データを自動的に検出・分類するサービスです。']},
  {id:'p316', domain:'security', type:'single', source:SOURCES.accessAnalyzer, text:'IAMロールやS3バケットなど、組織外(アカウント外)から意図せずアクセス可能になっているリソースを自動的に検出したい場合、最も適切なサービスはどれですか？',
    choices:['AWS IAM Access Analyzer','AWS Organizations','AWS IAM Identity Center','AWS Security Hub'], correct:[0],
    why:['正しい。IAM Access Analyzerは、IAMロールやS3バケット、KMSキーなどのリソースベースポリシーを分析し、組織やアカウントの外部から意図せずアクセス可能になっているリソースを自動的に検出します。','誤り。Organizationsは複数のAWSアカウントを一元管理するためのサービスで、外部アクセスの検出が主目的ではありません。','誤り。IAM Identity Centerは複数のAWSアカウントやアプリケーションへのシングルサインオン(SSO)を提供するサービスです。','誤り。Security Hubは複数のセキュリティサービスの検出結果を集約するサービスで、外部アクセスの検出自体を行うのはAccess Analyzerです。']},
  {id:'p317', domain:'security', type:'multi', source:SOURCES.shield, text:'DDoS(分散型サービス拒否)攻撃からAWS上のアプリケーションを保護するために利用できるサービスを2つ選択してください。',
    choices:['Amazon Macie','AWS Shield','AWS IAM Access Analyzer','AWS WAF'], correct:[1,3],
    why:['誤り。Macieは機密データの検出サービスで、DDoS攻撃対策ではありません。','正しい。AWS Shieldは、DDoS攻撃からアプリケーションを保護するマネージドサービスです。','誤り。IAM Access Analyzerは外部アクセスの検出サービスで、DDoS攻撃対策ではありません。','正しい。AWS WAFは悪意のあるWebリクエストをフィルタするWebアプリケーションファイアウォールで、レート制限ルールなどを通じてAWS Shieldと連携し、アプリケーション層のDDoS攻撃対策にも活用されます。']},
  {id:'p318', domain:'tech', type:'single', source:SOURCES.kinesis, text:'Webサイトのクリックストリームデータやセンサーから送信される大量のデータを、ほぼリアルタイムで収集し、継続的に処理・分析したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon SQS','Amazon Kinesis Data Streams','Amazon SNS','AWS Step Functions'], correct:[1],
    why:['誤り。SQSはメッセージキューイングサービスで、個々のメッセージを非同期に処理するのに適していますが、大量のストリーミングデータのリアルタイム収集・分析には向きません。','正しい。Amazon Kinesis Data Streamsは、クリックストリームやセンサーデータなど大量のストリーミングデータをほぼリアルタイムに収集し、継続的に処理・分析できるようにするサービスです。','誤り。SNSはパブリッシュ/サブスクライブ型の通知サービスで、ストリーミングデータの継続的な収集・分析が主目的ではありません。','誤り。Step Functionsは複数のサービスの実行順序をオーケストレーションするサービスで、ストリーミングデータの収集自体は行いません。']},
  {id:'p319', domain:'tech', type:'single', source:SOURCES.stepFunctions, text:'複数のAWS Lambda関数の実行順序や条件分岐、エラー処理を視覚的なワークフロー（ステートマシン）として定義し、オーケストレーションしたい場合、最も適切なサービスはどれですか？',
    choices:['Amazon EventBridge','Amazon SQS','AWS Step Functions','AWS Lambda'], correct:[2],
    why:['誤り。EventBridgeはイベントをルールに基づいてターゲットにルーティングするイベントバスサービスで、複数ステップのワークフローの視覚的なオーケストレーションが主目的ではありません。','誤り。SQSはメッセージキューイングサービスで、ワークフローのオーケストレーション機能はありません。','正しい。AWS Step Functionsは、複数のLambda関数や他のAWSサービスの実行順序、条件分岐、エラー処理を視覚的なステートマシン(ワークフロー)として定義・オーケストレーションするサービスです。','誤り。Lambdaは個々の関数を実行するコンピューティングサービスで、複数の関数をまたぐワークフロー自体の管理機能は持ちません。']},
  {id:'p320', domain:'tech', type:'single', source:SOURCES.opensearch, text:'アプリケーションのログデータを集約し、全文検索やリアルタイムに近い分析・可視化（ログ分析ダッシュボード等）を行いたい場合、最も適切なサービスはどれですか？',
    choices:['Amazon Athena','Amazon Redshift','AWS Glue','Amazon OpenSearch Service'], correct:[3],
    why:['誤り。AthenaはS3上のデータに対する標準SQLクエリに特化したサービスで、全文検索やログ分析ダッシュボードが主目的ではありません。','誤り。RedshiftはSQLベースのデータウェアハウスで、大規模ログの全文検索・可視化用途には向きません。','誤り。GlueはサーバーレスのETL(データ変換・統合)サービスで、ログの検索・可視化機能自体は持ちません。','正しい。Amazon OpenSearch Serviceは、ログデータの集約・全文検索・リアルタイムに近い分析や可視化（ダッシュボード）に適したマネージドサービスです。']},
  {id:'p321', domain:'billing', type:'single', source:SOURCES.costAllocTags, text:'複数のプロジェクトやチームが同じAWSアカウントを利用している環境で、AWSリソースに付与したタグ(キーと値のペア)に基づいて、Cost ExplorerやCost and Usage Reportでコストをプロジェクト・チーム別に分類・集計したい場合、利用する機能はどれですか？',
    choices:['コスト配分タグ（Cost Allocation Tags）','AWS Budgets','Consolidated Billing（一括支払い）','AWS Billing Conductor'], correct:[0],
    why:['正しい。コスト配分タグは、AWSリソースに付与したタグに基づいて、Cost ExplorerやCost and Usage Report上でコストをプロジェクト・チームなどの単位に分類・集計できるようにする機能です。','誤り。AWS Budgetsは支出や使用量に予算の閾値を設定し、超過時に通知するサービスで、タグによるコスト分類が主目的ではありません。','誤り。Consolidated Billingは複数のAWSアカウントの請求を一つにまとめる仕組みで、タグによるコスト分類とは異なります。','誤り。AWS Billing Conductorは、社内顧客向けにカスタムの請求ルールやプライシングを適用して請求書を作成するサービスで、タグによる基本的なコスト分類機能とは異なります。']},
  {id:'p322', domain:'billing', type:'single', source:SOURCES.pricingcalc, text:'AWSの利用を開始する前に、想定するリソース構成（EC2インスタンスタイプ、ストレージ容量など）を入力して、月額利用料金の見積もりを作成したい場合、最も適切なツールはどれですか？',
    choices:['AWS Cost Explorer','AWS Pricing Calculator','AWS Budgets','AWS Cost and Usage Report (CUR)'], correct:[1],
    why:['誤り。Cost Explorerは過去から現在までの実際の利用料金を可視化・分析するツールで、利用開始前の見積もり作成が主目的ではありません。','正しい。AWS Pricing Calculatorは、想定するリソース構成を入力することで、利用開始前に月額利用料金の見積もりを作成できる無料のツールです。','誤り。AWS Budgetsは予算の閾値を設定し超過時に通知するサービスで、見積もり作成ツールではありません。','誤り。CURは実際に発生した請求データの詳細な明細レポートで、利用開始前の見積もりではありません。']},
  {id:'p323', domain:'billing', type:'single', source:SOURCES.savingsplansTypes, text:'今後1〜3年間、特定のインスタンスファミリーに縛られず、EC2・Fargate・Lambdaなど複数のコンピューティングサービスにまたがって一定の利用額（$/時間）を継続してコミットすることで割引を受けたい場合、最も適切な購入オプションはどれですか？',
    choices:['スポットインスタンス','リザーブドインスタンス','Savings Plans','オンデマンドインスタンス'], correct:[2],
    why:['誤り。スポットインスタンスはAWSの余剰キャパシティを割引価格で利用できますが、中断のリスクがあり、特定の支出コミットメントによる割引とは異なります。','誤り。リザーブドインスタンスは主にEC2やRDSなど特定のインスタンスファミリー・リージョンを対象とした予約で、Fargate・Lambdaなど複数のコンピューティングサービス横断の割引ではありません。','正しい。Savings Plansは、1年または3年間、一定の利用額（$/時間）を継続してコミットすることで割引を受けられる購入オプションで、EC2だけでなくFargateやLambdaなど複数のコンピューティングサービスにまたがって適用できます。','誤り。オンデマンドインスタンスは特定のコミットメントなしに使った分だけ支払う標準料金で、割引はありません。']},
  {id:'p324', domain:'security', type:'single', source:SOURCES.acmpca, text:'複数の内部マイクロサービス間やIoTデバイスの認証に、独自のプライベート認証局(CA)から発行したTLS証明書を使いたいが、オンプレミスで認証局を構築・運用するコストはかけたくない。最も適切なサービスはどれですか？',
    choices:['AWS Private CA','AWS Certificate Manager (ACM)のパブリック証明書','AWS KMS','AWS Secrets Manager'], correct:[0],
    why:['正しい。AWS Private CAは、オンプレミスでの構築・運用コストをかけずに、内部マイクロサービス間の通信やIoTデバイス認証などに使うプライベートな認証局階層を作成できるサービスです。','誤り。ACMのパブリック証明書は、インターネットに公開するWebサイト等のために認証局(CA)から発行される証明書で、社内限定のプライベートな認証局を自分で構築する用途には使えません。','誤り。KMSは暗号鍵の作成・管理サービスであり、証明書(CA)の発行・管理サービスではありません。','誤り。Secrets Managerはデータベース認証情報などのシークレットを管理するサービスで、証明書発行局ではありません。']},
  {id:'p325', domain:'security', type:'single', source:SOURCES.acm, text:'Application Load Balancerに、インターネット上の一般利用者がブラウザで警告なくアクセスできるパブリックなSSL/TLS証明書を無料で発行・自動更新したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Private CA','AWS Certificate Manager (ACM)','AWS KMS','AWS CloudHSM'], correct:[1],
    why:['誤り。AWS Private CAは社内向けのプライベートな認証局を構築するサービスで、一般のブラウザに信頼されるパブリック証明書の発行には使えません。','正しい。AWS Certificate Manager (ACM) は、公的に信頼されたパブリックSSL/TLS証明書を無料で発行し、ELBやCloudFrontなど統合サービスへの適用や自動更新を行えるサービスです。','誤り。KMSは暗号鍵の作成・管理サービスで、SSL/TLS証明書の発行サービスではありません。','誤り。CloudHSMは専有のハードウェアセキュリティモジュールを提供するサービスで、パブリック証明書の発行機能はありません。']},
  {id:'p326', domain:'security', type:'single', source:SOURCES.vpcFlowLogs, text:'EC2インスタンスへの特定の通信が到達しているかどうかを調べるため、ネットワークインターフェースを通過するIPトラフィックの送信元・宛先・ポート・許可/拒否などの情報を記録・分析したい場合、最も適切な機能はどれですか？',
    choices:['AWS CloudTrail（APIコール履歴の記録）','AWS Config（リソース構成の記録・評価）','Amazon VPC Flow Logs（ネットワークトラフィック情報の記録）','Amazon CloudWatch Logs Insights単体でのログ集計機能'], correct:[2],
    why:['誤り。CloudTrailはAPIコールの履歴（誰が何をしたか）を記録するもので、ネットワークのIPトラフィック自体は記録しません。','誤り。Configはリソースの構成（設定内容）の変更履歴を記録・評価するもので、ネットワークトラフィックの記録は行いません。','正しい。VPC Flow Logsは、VPC内のネットワークインターフェースを通過するIPトラフィックの送信元・宛先・ポート・許可/拒否などの情報をキャプチャして記録する機能です。','誤り。CloudWatch Logs Insightsはログの検索・分析ツールであり、それ自体がネットワークトラフィックを記録するわけではありません（VPC Flow Logsの出力先の一つとして使われることはあります）。']},
  {id:'p327', domain:'security', type:'single', source:SOURCES.verifiedAccess, text:'社外から社内アプリケーションにアクセスする従業員に対して、常時接続のVPNトンネルを維持するのではなく、リクエストごとにユーザーID・デバイスの状態などを評価してアクセス可否を判断するゼロトラスト型のアクセス方式を実現したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Site-to-Site VPN','AWS Direct Connect','AWS Transit Gateway','AWS Verified Access'], correct:[3],
    why:['誤り。Site-to-Site VPNはオンプレミスとVPC間を暗号化されたトンネルで常時接続する方式で、リクエストごとの動的な評価を行うゼロトラストアクセスではありません。','誤り。Direct Connectはオンプレミスとの専用線接続サービスで、ゼロトラストアクセス方式ではありません。','誤り。Transit Gatewayは複数のVPC・オンプレミスネットワークを接続するハブとなるサービスで、ユーザー単位のゼロトラストアクセス評価を行うものではありません。','正しい。AWS Verified Accessは、VPNを使わずに、ユーザーID・デバイスの状態などのリクエストごとの評価に基づいてアプリケーションへのアクセス可否を判断する、ゼロトラストのアクセスソリューションです。']},
  {id:'p328', domain:'security', type:'multi', source:SOURCES.kms, text:'AWS KMSで管理される暗号化キーの種類として正しいものを2つ選択してください。',
    choices:['AWSマネージドキー（AWSサービスが自動的に作成・管理するキー）','カスタマーマネージドキー（利用者が作成しポリシーやローテーションを管理するキー）','パブリックキー（Webサイト向けのSSL/TLS証明書に使われる鍵）','ルートキー（AWSアカウントのルートユーザー専用の鍵）'], correct:[0,1],
    why:['正しい。AWSマネージドキーは、多くのAWSサービスが暗号化のために自動的に作成・管理するKMSキーです。','正しい。カスタマーマネージドキーは、利用者自身が作成し、キーポリシーやローテーション設定などを管理できるKMSキーです。','誤り。「パブリックキー」はKMSキーの分類名ではなく、SSL/TLS証明書に関連する概念（ACM等）です。','誤り。「ルートキー」という種類のKMSキーの分類名はありません。ルートユーザーはIAMの概念であり、KMSキーの種類ではありません。']},
  {id:'p329', domain:'tech', type:'single', source:SOURCES.timestream, text:'IoTセンサーから送信される大量のタイムスタンプ付きデータを低コストで保存し、時系列データに特化した分析関数を使って傾向やパターンをほぼリアルタイムに把握したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon Timestream','Amazon RDS','Amazon DynamoDB','Amazon Redshift'], correct:[0],
    why:['正しい。Amazon Timestreamは、IoTセンサーデータなど大量のタイムスタンプ付き時系列データを低コストで保存し、時系列に特化した分析関数でほぼリアルタイムに傾向を把握できる、サーバーレスのマネージド型データベースサービスです。','誤り。RDSはリレーショナルデータベースサービスで、時系列データに特化した分析関数は備えていません。','誤り。DynamoDBはキーバリュー・ドキュメント型のNoSQLデータベースで、時系列データ専用の分析関数は備えていません。','誤り。Redshiftはデータウェアハウスサービスで、時系列データに特化した設計ではありません。']},
  {id:'p330', domain:'tech', type:'single', source:SOURCES.iotcore, text:'工場内の数千台のセンサーデバイスから、MQTTプロトコルを使って安全にデータをAWSクラウドへ送信し、他のAWSサービスと連携させたい場合、最も適切なサービスはどれですか？',
    choices:['Amazon API Gateway','AWS IoT Core','Amazon EventBridge','Amazon SQS'], correct:[1],
    why:['誤り。API GatewayはHTTP(S)ベースのAPIを作成・管理するサービスで、MQTTによる大量デバイスの接続に特化したものではありません。','正しい。AWS IoT Coreは、MQTTなどのプロトコルを使って大量のIoTデバイスを安全にAWSクラウドに接続し、他のAWSサービスと連携させることができるサービスです。','誤り。EventBridgeはAWSサービスやSaaS間のイベントをルーティングするイベントバスサービスで、IoTデバイスとの直接のプロトコル接続機能が主目的ではありません。','誤り。SQSはメッセージキューイングサービスで、IoTデバイスとの直接接続のためのプロトコル(MQTT等)はサポートしていません。']},
  {id:'p331', domain:'tech', type:'single', source:SOURCES.keyspaces, text:'オンプレミスで運用しているApache Cassandraのワークロードを、既存のアプリケーションコードやCQL(Cassandra Query Language)をそのまま使いながら、サーバー管理不要でAWSに移行したい場合、最も適切なサービスはどれですか？',
    choices:['Amazon DynamoDB','Amazon DocumentDB','Amazon Keyspaces (for Apache Cassandra)','Amazon Neptune'], correct:[2],
    why:['誤り。DynamoDBは独自のAPI・データモデルを持つマネージドNoSQLデータベースで、既存のCassandraアプリケーションコードやCQLをそのまま使うことはできません。','誤り。DocumentDBはMongoDB互換のドキュメントデータベースサービスで、Cassandra互換ではありません。','正しい。Amazon Keyspacesは、既存のCassandraアプリケーションコードやCQLをそのまま使いながら、サーバー管理不要でCassandraワークロードを実行・スケールできる、Apache Cassandra互換のマネージドデータベースサービスです。','誤り。Neptuneはグラフデータベースサービスで、Cassandra互換ではありません。']},
  {id:'p332', domain:'tech', type:'single', source:SOURCES.privatelink, text:'VPC内のEC2インスタンスから、インターネットゲートウェイやNATゲートウェイを経由せずに、Amazon S3へ追加料金なしでプライベートにアクセスしたい場合、最も適切な方法はどれですか？',
    choices:['AWS PrivateLink経由のインターフェースエンドポイント（ENIを使用し時間課金が発生する）','AWS Direct Connect','AWS Transit Gateway','VPCのゲートウェイエンドポイント（S3・DynamoDB向けに追加料金なしで提供されるルートテーブルベースの接続）'], correct:[3],
    why:['誤り。インターフェースエンドポイント（PrivateLink）はENIを使用し時間課金が発生する接続方式で、S3・DynamoDB向けには追加料金のないゲートウェイエンドポイントが提供されています。','誤り。Direct Connectはオンプレミスとの専用線接続サービスで、VPC内からS3への接続方式ではありません。','誤り。Transit Gatewayは複数VPC・オンプレミスネットワークの接続ハブであり、S3への直接のプライベート接続方式ではありません。','正しい。VPCのゲートウェイエンドポイントは、Amazon S3とAmazon DynamoDBに限り、追加料金なしでルートテーブルを経由してプライベートにアクセスできる接続方式です（AWS PrivateLinkは使用しません）。']},
  {id:'p333', domain:'tech', type:'multi', source:SOURCES.keyspaces, text:'サーバーのプロビジョニングや管理が不要で、トラフィックに応じて自動的にスケールする「サーバーレス」なデータベースサービスを2つ選択してください。',
    choices:['Amazon DynamoDB','Amazon RDS（プロビジョンドインスタンスモード）','Amazon Keyspaces (for Apache Cassandra)','Amazon Neptune（プロビジョンドインスタンスモード）'], correct:[0,2],
    why:['正しい。DynamoDBはサーバーのプロビジョニングが不要で、トラフィックに応じて自動的にスケールするサーバーレスのNoSQLデータベースです。','誤り。RDSのプロビジョンドインスタンスモードは、インスタンスタイプを選択してサーバーを稼働させる方式で、サーバーレスではありません。','正しい。Amazon Keyspacesはサーバーレスで、利用した分だけ課金され、トラフィックに応じて自動的にスケールするApache Cassandra互換のデータベースサービスです。','誤り。Neptuneのプロビジョンドインスタンスモードは、インスタンスタイプを選択してサーバーを稼働させる方式で、サーバーレスではありません。']},
  {id:'p334', domain:'billing', type:'single', source:SOURCES.costExplorer, text:'過去のEC2利用実績を分析し、リザーブドインスタンスやSavings Plansをどの程度購入すればコストを最適化できるかという購入推奨(レコメンデーション)を確認したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Cost Explorer','AWS Budgets','AWS Cost and Usage Report (CUR)','AWS Cost Categories'], correct:[0],
    why:['正しい。AWS Cost Explorerは、過去の利用実績を分析し、リザーブドインスタンスやSavings Plansの購入推奨(レコメンデーション)を提供する機能を備えています。','誤り。AWS Budgetsは予算のしきい値超過を通知するサービスで、購入推奨機能ではありません。','誤り。CURは請求データの詳細な明細レポートで、それ自体が購入推奨を提示する機能ではありません。','誤り。Cost Categoriesはコストを独自の構造に分類する機能で、購入推奨機能ではありません。']},
  {id:'p335', domain:'billing', type:'single', source:SOURCES.costCategories, text:'複数のAWSアカウントにまたがる費用を、各リソースに付与されたタグが不完全な場合でも、アカウントIDやサービス名などの条件を組み合わせたルールに基づいて、部門ごとに独自に分類・集計したい場合、最も適切な機能はどれですか？',
    choices:['AWSコスト配分タグ (Cost Allocation Tags)','AWS Cost Categories','AWS Organizations の一括支払い (Consolidated Billing)','AWS Cost Anomaly Detection'], correct:[1],
    why:['誤り。コスト配分タグは、各リソースに付与されたタグを前提とする仕組みで、タグ付けが不完全な場合に他のディメンション（アカウント等）を組み合わせて分類することはできません。','正しい。AWS Cost Categoriesは、アカウント・サービス・タグなど複数の請求ディメンションを組み合わせたルールを定義できるため、タグ付けが不完全な場合でもアカウントIDやサービス名などの条件で部門ごとにコストを分類・集計できます。','誤り。一括支払いは複数アカウントの請求を一つにまとめる仕組みで、部門別の分類・集計機能ではありません。','誤り。Cost Anomaly Detectionは異常なコストの急増を検知するサービスで、部門別の分類・集計機能ではありません。']},
  {id:'p336', domain:'billing', type:'single', source:SOURCES.budgets, text:'AWSの請求額に関するアラートについて、現在推奨される一般的な方法として最も適切なものはどれですか？',
    choices:['バージニア北部(us-east-1)リージョンでの請求アラート機能の有効化とAmazon CloudWatchの料金アラームの組み合わせのみに依存する','AWS Trusted Advisorでコストしきい値を設定する','AWS Budgetsで予算・しきい値を設定し、実績または予測が超過した場合にメールやAmazon SNSで通知を受け取る','AWS Artifactでコンプライアンスレポートと合わせてコストしきい値を確認する'], correct:[2],
    why:['誤り。CloudWatchの請求アラームは請求アラート機能の有効化(us-east-1限定)が前提の古くからの方法で、AWS Budgetsの方が柔軟な予算設定や予測に基づく通知が可能です。','誤り。Trusted Advisorはベストプラクティスのチェックを行うサービスで、予算のしきい値設定機能は主目的ではありません。','正しい。AWS Budgetsは、コスト・使用量・カバレッジについて柔軟に予算としきい値を設定し、実績または予測がそれを超えた場合にメールやSNSで通知を受け取れる、現在推奨される方法です。','誤り。AWS Artifactはコンプライアンスレポートやアグリーメントを取得するサービスで、コストしきい値の確認機能はありません。']},
  {id:'p337', domain:'concepts', type:'single', source:SOURCES.wafPerformance, text:'AWS Well-Architected Frameworkの「パフォーマンス効率の柱」の設計原則の一つ「サーバーレスアーキテクチャを使用する」が重視する内容として正しいものはどれですか？',
    choices:['物理サーバーの運用・保守の必要性を排除し、マネージド型のサービスを使うことでコンピューティング活動の運用負荷を下げること','複数のAWSリージョンにワークロードを展開し、低コストで利用者に近い場所から低レイテンシーなサービスを提供すること','複雑な技術の実装をクラウドベンダーに委ね、NoSQLデータベースや機械学習などをサービスとして利用すること','仮想的で自動化可能なリソースを使い、異なるインスタンスタイプやストレージ構成の比較検証を頻繁に行うこと'], correct:[0],
    why:['正しい。「サーバーレスアーキテクチャを使用する」という設計原則は、物理サーバーの運用・保守を不要にし、マネージドサービスの活用によってコンピューティング活動の運用負荷を下げ、クラウド規模のメリットにより取引コストを下げられるという考え方です。','これは「数分でグローバル展開する(Go global in minutes)」という別の設計原則の内容です。','これは「高度なテクノロジーを誰でも使えるようにする(Democratize advanced technologies)」という別の設計原則の内容です。','これは「より頻繁に実験する(Experiment more often)」という別の設計原則の内容です。']},
  {id:'p338', domain:'concepts', type:'single', source:SOURCES.wafSustainability, text:'AWS Well-Architected Frameworkの「持続可能性の柱」の設計原則の一つ「マネージドサービスを使用する」が重視する内容として正しいものはどれですか？',
    choices:['新しい効率的なハードウェアやソフトウェアが登場した際に、積極的にテスト・採用すること','共有されたマネージドサービスを活用することで、多くの顧客間でリソースの利用率を高め、ワークロードを支えるために必要なインフラ全体を削減すること','クラウドワークロードが環境に与える影響を測定し、持続可能性改善の投資対効果をモデル化すること','ワークロードを利用するエンドユーザー側に必要なエネルギーやリソース(データ転送量等)を削減すること'], correct:[1],
    why:['これは「新しくより効率的なハードウェア・ソフトウェアを予測して採用する」という別の設計原則の内容です。','正しい。「マネージドサービスを使用する」設計原則は、共有されたマネージドサービスの活用により、多くの顧客間でリソースの利用率を高め、ワークロードを支えるために必要なインフラ全体を削減することを重視します。','これは「自社の影響を理解する(Understand your impact)」という別の設計原則の内容です。','これは「ワークロードの下流への影響を低減する」という別の設計原則の内容です。']},
  {id:'p339', domain:'concepts', type:'single', source:SOURCES.wafCost, text:'AWS Well-Architected Frameworkの「コスト最適化の柱」の設計原則の一つ「費用の分析と帰属(Analyze and attribute expenditure)」が重視する内容として正しいものはどれですか？',
    choices:['利用した分だけ料金を支払い、ビジネス要件に応じて使用量を増減させること','サーバーのラッキングや電源管理などデータセンター運用の重労働をAWSに任せること','クラウドによって可視化されたコストと使用状況を正確に特定・分類し、ITコストを収益やワークロード所有者に対して透過的に帰属させること','ワークロードのビジネス上の成果と、それにかかるコストの両方を測定すること'], correct:[2],
    why:['これは「消費モデルの導入(Adopt a consumption model)」という別の設計原則の内容です。','これは「差別化につながらない重労働への投資をやめる」という別の設計原則の内容です。','正しい。「費用の分析と帰属」は、コストと使用状況を正確に特定・分類し、ITコストを収益やワークロード所有者に透過的に帰属させることで、投資対効果(ROI)の測定やリソース最適化の機会を生み出す設計原則です。','これは「効率の測定(Measure overall efficiency)」という別の設計原則の内容です。']},
  {id:'p340', domain:'security', type:'single', source:SOURCES.wafSecurity, text:'AWS Well-Architected Frameworkの「セキュリティの柱」の設計原則の一つ「セキュリティを全レイヤーに適用する」が推奨する内容として正しいものはどれですか？',
    choices:['長期的な静的認証情報への依存を排除し、IDを一元管理すること','環境への変更やアクションをリアルタイムで監視・記録し、ログと指標の収集をシステムに統合すること','セキュリティのベストプラクティスをコード化し、バージョン管理されたテンプレートとして実装すること','ネットワークの境界、VPC、ロードバランサー、各インスタンスやコンピューティングサービス、OS、アプリケーション、コードといった複数の階層すべてに、多層防御の考え方でセキュリティ管理策を適用すること'], correct:[3],
    why:['これは「強力なアイデンティティ基盤を実装する」という別の設計原則の内容です。','これは「トレーサビリティを維持する」という別の設計原則の内容です。','これは「セキュリティのベストプラクティスを自動化する」という別の設計原則の内容です。','正しい。「セキュリティを全レイヤーに適用する」は、ネットワークの境界からVPC、ロードバランサー、各インスタンス・コンピューティングサービス、OS、アプリケーション、コードまで、複数の階層すべてに多層防御のセキュリティ管理策を適用する設計原則です。']},
  {id:'p341', domain:'security', type:'single', source:SOURCES.compliancePrograms, text:'ある企業が、利用を検討している特定のAWSサービスが、自社が準拠すべき規制やPCI DSSなどの認証の対象範囲(スコープ)に含まれているかどうかを、リージョンやサービスごとに事前に確認したい場合、どこを参照するのが最も適切ですか？',
    choices:['AWSが対象としている規制・法規制やコンプライアンス認証を、対象サービス・リージョンごとに一覧できる公式のコンプライアンスプログラムの情報','AWS Trusted Advisorのコスト最適化に関するチェック結果','Amazon CloudWatchのメトリクスダッシュボード','AWS Health Dashboardの障害通知'], correct:[0],
    why:['正しい。AWSの公式サイトでは、対象としている規制・法規制やコンプライアンス認証(ISO、PCI DSS、HIPAA等)について、対象となるサービスやリージョンの範囲を含めて一覧できるコンプライアンスプログラムの情報が公開されています。','誤り。Trusted Advisorのコスト最適化チェックは、コンプライアンス認証の対象範囲とは関係ありません。','誤り。CloudWatchはメトリクスやログの監視サービスであり、コンプライアンス認証の対象範囲の確認には使いません。','誤り。AWS Health Dashboardはアカウントに影響するAWSの運用イベントを通知するものであり、コンプライアンス認証の対象範囲とは関係ありません。']},
  {id:'p342', domain:'security', type:'single', source:SOURCES.verifiedAccess, text:'AWS Verified Accessの特徴として正しいものはどれですか？',
    choices:['社内アプリケーションへの通信を暗号化するために、常時接続のVPNトンネルをクライアント端末に構築する','ユーザーのIDやデバイスのセキュリティ状態(準拠状況)など複数の信号をリクエストごとに評価し、VPNクライアントソフトウェアを使わずにゼロトラストでアクセスを許可するかどうかを判断する','オンプレミスとAWSの間に専用線を敷設し、インターネットを経由しない閉域network接続を提供する','IAMユーザーやロールに付与できる権限の上限(ガードレール)を組織全体に設定する'], correct:[1],
    why:['誤り。Verified Accessは、VPNクライアントソフトウェアや常時接続のVPNトンネルを必要としない点が特徴です。','正しい。AWS Verified Accessは、ユーザーのIDやデバイスのセキュリティ状態など複数の信号をリクエストごとに評価し、VPNクライアントソフトウェアなしでゼロトラストの原則に基づきアクセスの許可を判断するサービスです。','これはAWS Direct Connectの説明です。','これはAWS Organizationsのサービスコントロールポリシー(SCP)の説明です。']},
  {id:'p343', domain:'security', type:'single', source:SOURCES.vpcFlowLogs, text:'Amazon VPC Flow Logsで取得したトラフィックログについて、長期保存や高度な分析のためにAmazon S3やAmazon CloudWatch Logsに発行(パブリッシュ)することはできますか？',
    choices:['できない。Flow Logsはリアルタイム表示専用で、保存先を指定することはできない','できるが、Amazon S3のみが保存先として選択可能で、CloudWatch Logsには発行できない','できる。Flow Logsの発行先としてAmazon S3またはAmazon CloudWatch Logsを選択でき、長期保存やAmazon Athena等を使った分析に利用できる','できるが、保存先はAmazon CloudWatch Logsのみで、S3には発行できない'], correct:[2],
    why:['誤り。VPC Flow Logsはログの発行先として保存先を指定でき、リアルタイム表示専用ではありません。','誤り。Amazon S3に加えてAmazon CloudWatch Logsも発行先として選択できます。','正しい。VPC Flow Logsは、取得したトラフィックログの発行先としてAmazon S3またはAmazon CloudWatch Logsを選択でき、長期保存や、Amazon Athenaなどを使った詳細な分析に活用できます。','誤り。Amazon CloudWatch Logsに加えてAmazon S3にも発行できます。']},
  {id:'p344', domain:'tech', type:'single', source:SOURCES.glue, text:'AWS Glueの「データカタログ(Data Catalog)」の役割として正しいものはどれですか？',
    choices:['ETL処理に使うコンピューティングリソースを自動的にスケールするサーバーレスの実行環境','データの変換ロジックをビジュアルエディタ上で作成する機能','Amazon S3などに格納されたデータのスキーマ(テーブル定義)を検出・保存し、Amazon AthenaやAmazon Redshift Spectrumなど他のサービスから参照できるようにする中央リポジトリ','リレーショナルデータベースのテーブル定義を自動的にバックアップするサービス'], correct:[2],
    why:['誤り。これはAWS Glueのサーバーレスなジョブ実行環境(ETLの実行基盤)に関する説明です。','誤り。これはAWS Glue Studio(ビジュアルなETL作成ツール)に関する説明です。','正しい。AWS Glueのデータカタログは、Amazon S3等に格納されたデータのスキーマ(テーブル定義)を検出・保存する中央リポジトリで、Amazon AthenaやAmazon Redshift Spectrumなどの他のサービスから参照してクエリを実行できます。','誤り。データカタログはテーブル定義(メタデータ)を管理するものであり、データベースのバックアップ機能ではありません。']},
  {id:'p345', domain:'tech', type:'single', source:SOURCES.globalAccelerator, text:'AWS Global Acceleratorを使う主なメリットとして正しいものはどれですか？',
    choices:['AWSのグローバルネットワークを経由する固定のAnycast静的IPアドレスを提供し、アプリケーションの障害時にヘルスチェックに基づいて別リージョンのエンドポイントへ自動的にトラフィックをルーティングできる','静的コンテンツやメディアをエッジロケーションにキャッシュし、オリジンサーバーへのリクエスト数を減らす','オンプレミス環境とAWSの間に専用線接続を確立する','複数のAWSアカウントにまたがるリソースをタグベースで一括管理する'], correct:[0],
    why:['正しい。AWS Global Acceleratorは、固定のAnycast静的IPアドレスを提供し、AWSのグローバルネットワークを経由してトラフィックを最適なエンドポイントへ振り分け、ヘルスチェックに基づいて障害時には別リージョンへ自動的にフェイルオーバーできます。','これはAmazon CloudFrontの説明です(CloudFrontはコンテンツキャッシュに重点を置き、Global Acceleratorは非キャッシュ対象のTCP/UDPトラフィックの高速化・可用性向上に重点を置きます)。','これはAWS Direct Connectの説明です。','これはAWS Resource Access Manager等の説明です。']},
  {id:'p346', domain:'tech', type:'single', source:SOURCES.quicksight, text:'Amazon QuickSightの料金モデルの特徴として正しいものはどれですか？',
    choices:['月額固定料金のみで、ダッシュボードの閲覧者数に関わらず料金は変わらない','ダッシュボード作成者(Author)向けの料金プランに加えて、閲覧のみを行う読者(Reader)向けに、実際に使用したセッション数に応じて支払う「ペイパーセッション」の料金オプションが用意されている','保存したデータ量に応じてのみ課金され、閲覧やクエリの実行回数は料金に影響しない','オンプレミスのBIツールのライセンスを購入しAWS上で稼働させる必要がある'], correct:[1],
    why:['誤り。QuickSightの料金は、作成者(Author)と閲覧者(Reader)で異なり、閲覧者向けにはセッション単位の課金オプションがあります。','正しい。Amazon QuickSightは、ダッシュボードを作成するAuthor向けの月額/年間プランに加えて、閲覧のみを行うReader向けに、実際に使用したセッション数に応じて支払う「ペイパーセッション」の料金オプションを提供しており、大規模な閲覧者層へのコストを抑えられます。','誤り。保存データ量(SPICE容量)も課金要素の一つですが、閲覧・セッションも別途課金対象です。','誤り。QuickSightはAWSのマネージドサービスであり、オンプレミスBIツールのライセンス購入は不要です。']},
  {id:'p347', domain:'tech', type:'multi', source:SOURCES.s3glacier, text:'Amazon S3 Glacier Flexible Retrieval(S3のアーカイブ用ストレージクラス)からデータを取り出す(retrieval)際に選択できるオプションとして正しいものを2つ選択してください。',
    choices:['Instant(即時) - 常にミリ秒単位で取り出せ、取り出し料金が発生しないオプション','Expedited(迅速) - 通常1〜5分程度で取り出せるが、取り出し料金は他のオプションより高くなるオプション','Immediate(即時) - 追加料金なしで即座にすべてのデータを取り出せるオプション','Bulk(大容量) - 通常5〜12時間程度かかるが、最も低コストで大量データを取り出せるオプション'], correct:[1,3],
    why:['誤り。S3 Glacier Flexible Retrievalの取り出しオプションに「Instant」という名称のものはありません(ミリ秒単位の即時アクセスは、別のストレージクラスであるS3 Glacier Instant Retrievalの特徴です)。','正しい。Expedited(迅速)オプションは、通常1〜5分程度で取り出せますが、取り出し料金は他のオプションより高くなります。','誤り。「Immediate」という名称のオプションは存在しません。','正しい。Bulk(大容量)オプションは、通常5〜12時間程度かかりますが、最も低コストで大量のデータをまとめて取り出せるオプションです。']},
  {id:'p348', domain:'tech', type:'single', source:SOURCES.natGateway, text:'VPCでNATゲートウェイを使って複数のアベイラビリティーゾーン(AZ)にわたる高可用性を実現したい場合、どのように構成するのが推奨されますか？',
    choices:['1つのNATゲートウェイを1つのAZに作成し、すべてのAZのプライベートサブネットからそのNATゲートウェイを共有して使う','NATゲートウェイはリージョン全体で冗長化されているため、追加の構成は不要である','AZごとにNATゲートウェイを作成し、各AZのプライベートサブネットはそれぞれ同じAZ内のNATゲートウェイを使うように構成する','NATゲートウェイの代わりにインターネットゲートウェイを各AZに作成する'], correct:[2],
    why:['誤り。1つのAZのNATゲートウェイを他のAZからも使う構成は可能ですが、そのAZで障害が発生すると他のAZからのアウトバウンド通信も影響を受けるため、高可用性の推奨構成ではありません。','誤り。NATゲートウェイは単一のAZ内に作成されるリソースであり、リージョン全体で自動的に冗長化されるわけではありません。','正しい。高可用性を実現するには、AZごとにNATゲートウェイを作成し、各AZのプライベートサブネットが同じAZ内のNATゲートウェイを使うように構成することで、1つのAZの障害が他のAZのアウトバウンド通信に影響しないようにします。','誤り。インターネットゲートウェイはVPC全体に対して1つ作成するリソースであり、プライベートサブネットからの送信元ネットワークアドレス変換(NAT)の役割を持ちません。']},
  {id:'p349', domain:'billing', type:'single', source:SOURCES.costExplorer, text:'特定の期間について、サービス別・リンクされたアカウント別・タグ別などの条件でAWSのコストと使用量の内訳を可視化し、カスタムレポートとして保存・再利用したい場合、最も適切なサービスはどれですか？',
    choices:['AWS Budgets','AWS Cost Anomaly Detection','AWS Billing Conductor','AWS Cost Explorer'], correct:[3],
    why:['誤り。AWS Budgetsは予算のしきい値を設定し超過時に通知する機能で、コスト内訳の可視化・カスタムレポート作成が主目的ではありません。','誤り。AWS Cost Anomaly Detectionは機械学習による異常なコストの検知を行うサービスです。','誤り。AWS Billing Conductorはプロフォーマコストを使ったカスタム請求のためのサービスです。','正しい。AWS Cost Explorerは、サービス別・リンクされたアカウント別・タグ別などの条件でコストと使用量の内訳をグラフで可視化し、カスタムレポートとして保存・再利用できるサービスです。']},
  {id:'p350', domain:'concepts', type:'single', source:SOURCES.shared, text:'Amazon RDSのようなAWSのマネージド型データベースサービスを利用する場合、基盤となるデータベースエンジンのソフトウェアパッチ適用の責任は誰が負いますか？',
    choices:['AWS側が責任を持ち、利用者はOS・DBエンジンのパッチ適用作業を行う必要はない','利用者側が責任を持ち、EC2にインストールしたデータベースと同様に自分でパッチを適用する必要がある','AWSと利用者が共同で、毎回事前に合意したスケジュールで手動適用する','パッチ適用はサードパーティのサポート契約に委ねられ、AWSも利用者も責任を負わない'], correct:[0],
    why:['正しい。RDSのようなマネージド型サービスでは、責任共有モデルにおいて基盤となるOSやデータベースエンジンのパッチ適用はAWSの責任範囲に含まれます(これはEC2上に自分でデータベースを構築する場合とは異なります)。','誤り。これはEC2上に自分でミドルウェアをインストールして運用する場合の説明であり、RDSのようなマネージド型サービスには当てはまりません。','誤り。パッチ適用のタイミング(メンテナンスウィンドウ)は利用者が設定できますが、適用作業自体をAWSと利用者が共同で手動実施するわけではありません。','誤り。AWSの責任共有モデルにおいて、マネージド型サービスの基盤インフラの保守はAWSの責任です。']},
  {id:'p351', domain:'concepts', type:'single', source:SOURCES.caf, text:'AWS Cloud Adoption Framework (AWS CAF) における「セキュリティ」の視点(パースペクティブ)が主に扱う内容として最も適切なものはどれですか？',
    choices:['予算編成やクラウド導入のビジネスケースの構築','セキュリティに関する目標をビジネス目標と整合させ、リスク管理やセキュリティのベストプラクティスの自動化を通じて組織全体のセキュリティ体制を維持すること','複数のAWSアカウントにわたる基盤(ランディングゾーン)の設計・構築','クラウド導入に必要な人材のスキル育成や組織構造の変革'], correct:[1],
    why:['誤り。これは「ビジネス」の視点が主に扱う内容です。','正しい。「セキュリティ」の視点は、セキュリティに関する目標をビジネス目標と整合させ、リスク管理やセキュリティのベストプラクティスの自動化を通じて組織全体のセキュリティ体制を維持することを重視します。','誤り。これは「プラットフォーム」の視点が主に扱う内容です。','誤り。これは「ピープル」の視点が主に扱う内容です。']},
  {id:'p352', domain:'security', type:'single', source:SOURCES.parameterStore, text:'アプリケーションで「データベースの認証情報のように定期的な自動ローテーションが必要な機密情報」と「AMI IDやエンドポイントURLのように変化が少ない一般的な設定値」を、それぞれ最もコスト効率よく管理する組み合わせとして正しいものはどれですか？',
    choices:['両方をAWS Secrets Managerで管理する','両方をAWS Systems Manager パラメータストアの標準パラメータで管理する','機密情報はAWS Secrets Managerで自動ローテーションを設定し、一般的な設定値はAWS Systems Manager パラメータストアの標準パラメータ(無料)で管理する','両方をAmazon S3バケットに暗号化して保存する'], correct:[2],
    why:['誤り。Secrets Managerは自動ローテーション等の機能を持ちますが有料であり、変化が少ない一般的な設定値まで管理すると不要なコストが発生します。','誤り。パラメータストアの標準パラメータには自動ローテーションの機能はなく、データベース認証情報のローテーションには適しません。','正しい。Secrets Managerは自動ローテーションが必要な機密情報に、Systems Manager パラメータストアの標準パラメータ(無料)は変化の少ない一般的な設定値の管理にそれぞれ適しています。','誤り。S3に保存することも技術的には可能ですが、パラメータの一元管理やアクセス制御、自動ローテーション機能はパラメータストアやSecrets Managerの方が適しています。']},
  {id:'p353', domain:'security', type:'single', source:SOURCES.wafService, text:'特定のIPアドレスから短時間に異常な数のリクエストが送られ、Webアプリケーションに過剰な負荷がかかっている。IPアドレスごとのリクエスト数が一定のしきい値を超えた場合に自動的にブロックしたい場合、AWS WAFで使用する機能として最も適切なものはどれですか？',
    choices:['マネージドルールグループによるSQLインジェクションの検出','IPセットによる特定の国・地域からのアクセス拒否','ステートフルなディープパケットインスペクションによる侵入検知','レート制限ルール(rate-based rule)により、指定した時間内のリクエスト数がしきい値を超えたIPアドレスを自動的にブロックする'], correct:[3],
    why:['誤り。これはSQLインジェクション等の既知の攻撃パターンを検出するマネージドルールの説明であり、リクエスト数のしきい値に基づくブロックではありません。','誤り。これは地理的な制限に基づくアクセス制御であり、リクエスト数のしきい値に基づくものではありません。','誤り。これはAWS Network Firewallの機能の説明です。','正しい。AWS WAFのレート制限ルールは、指定した時間内のリクエスト数が設定したしきい値を超えたIPアドレスを自動的にブロックできます。']},
  {id:'p354', domain:'tech', type:'single', source:SOURCES.s3StorageClasses, text:'あるデータへのアクセス頻度は低い(年に数回程度)が、アクセスする際は追加の待ち時間なしでミリ秒単位で取得する必要があり、かつ複数のアベイラビリティーゾーンにまたがる高い耐久性を維持したい。最もコスト効率が良いS3ストレージクラスはどれですか？',
    choices:['S3標準-低頻度アクセス(S3 Standard-IA) — 複数のAZにデータを冗長化しミリ秒単位の即時アクセスが可能で、低頻度アクセス向けの低いストレージ料金を実現する','S3 One Zone-IA — ミリ秒単位の即時アクセスは可能だが、単一のAZにしかデータを保存しないためAZ障害時にデータを失うリスクがある','S3 Glacier Deep Archive — 最もストレージ料金が低いが、取り出しには数時間から数日の待ち時間が必要で即時アクセスはできない','S3 Intelligent-Tiering — アクセスパターンが不明・変動する場合に自動的に最適な階層へ移動させる仕組み'], correct:[0],
    why:['正しい。S3標準-IAは複数のAZにデータを冗長化して高い耐久性を維持しつつ、ミリ秒単位の即時アクセスと、低頻度アクセス向けの低いストレージ料金を両立できます。','誤り。単一のAZにしか保存しないため、複数AZをまたいだ耐久性という要件を満たしません。','誤り。取り出しに数時間から数日かかるため、即時アクセスという要件を満たしません。','誤り。今回のようにアクセス頻度のパターンが明確に分かっている場合は、Intelligent-Tieringの自動階層化は不要で、S3標準-IAを直接選ぶ方がシンプルかつ確実です。']},
  {id:'p355', domain:'tech', type:'single', source:SOURCES.codebuild, text:'自社のソースコードをコンパイルし、ユニットテストを実行し、デプロイ可能なビルド成果物(アーティファクト)を生成する処理を、ビルドサーバーの構築・運用管理不要でフルマネージドに実行したい場合、最も適したサービスはどれですか？',
    choices:['AWS CodePipeline — ビルド・テスト・デプロイといったリリースプロセス全体のワークフローをオーケストレーションするサービス','AWS CodeBuild — ソースコードのコンパイル・ユニットテストの実行・デプロイ可能なアーティファクトの生成を行う、フルマネージドのビルドサービス','AWS CodeDeploy — ビルド済みのアプリケーションをEC2やLambda、ECS等に自動的にデプロイするサービス','Amazon ECR — コンテナイメージを保存・管理するレジストリサービス'], correct:[1],
    why:['誤り。これはAWS CodePipelineの説明です。CodePipelineはビルド・テスト・デプロイ全体のワークフローを管理しますが、ビルド自体の実行はCodeBuildのような別のサービスに委ねます。','正しい。AWS CodeBuildは、ソースコードのコンパイル・ユニットテストの実行・デプロイ可能なアーティファクトの生成を、ビルドサーバーの管理不要でフルマネージドに実行できるサービスです。','誤り。これはAWS CodeDeployの説明です。','誤り。これはAmazon ECR(Elastic Container Registry)の説明です。']},
  {id:'p356', domain:'tech', type:'single', source:SOURCES.codedeploy, text:'ビルド済みのアプリケーションを、EC2インスタンス・オンプレミスサーバー・Lambda関数・ECSサービスに対して、ブルー/グリーンデプロイやローリング更新などの方式で自動的に展開し、デプロイ失敗時には自動的にロールバックしたい場合、最も適したサービスはどれですか？',
    choices:['AWS CodeBuild — ソースコードのビルド・テストを行うサービス','AWS CloudFormation — テンプレートに基づきインフラリソースをプロビジョニングするサービス','AWS CodeDeploy — EC2・オンプレミスサーバー・Lambda・ECSへのアプリケーションデプロイを自動化し、ブルー/グリーン等のデプロイ方式や失敗時の自動ロールバックに対応するサービス','AWS Elastic Beanstalk — Webアプリケーションのインフラ管理を自動化するPaaS型のサービス'], correct:[2],
    why:['誤り。これはAWS CodeBuildの説明です。','誤り。これはAWS CloudFormationの説明です。','正しい。AWS CodeDeployは、EC2・オンプレミスサーバー・Lambda・ECSへのアプリケーションデプロイを自動化し、ブルー/グリーン等のデプロイ方式や失敗時の自動ロールバックに対応するサービスです。','誤り。これはAWS Elastic Beanstalkの説明です。']},
  {id:'p357', domain:'tech', type:'single', source:SOURCES.rekognition, text:'動画配信プラットフォームにアップロードされた動画コンテンツに、不適切な画像やコンテンツ(暴力的な表現等)が含まれていないかを自動的に検出し、モデレーション作業を効率化したい場合、最も適したサービスはどれですか？',
    choices:['Amazon Comprehend — テキストから感情や言語を分析する自然言語処理サービス','Amazon Textract — 文書内のテキストやフォーム・テーブルを抽出するサービス','Amazon Transcribe — 音声をテキストに変換するサービス','Amazon Rekognition — 画像や動画の中の物体・シーン・人物の顔に加え、不適切なコンテンツなども機械学習で検出・分析できるサービス'], correct:[3],
    why:['誤り。これはAmazon Comprehendの説明です。','誤り。これはAmazon Textractの説明です。','誤り。これはAmazon Transcribeの説明です。','正しい。Amazon Rekognitionは、画像や動画の中の物体・シーン・人物の顔に加えて、不適切なコンテンツなども機械学習で検出・分析できるサービスです。']},
  {id:'p358', domain:'tech', type:'single', source:SOURCES.datasync, text:'オンプレミスのデータセンターに数十TB規模のデータがあり、十分な帯域のネットワーク回線が確保できている。このデータをAmazon S3へ移行し、移行後も継続的に差分を同期したい場合に最も適したサービスと、ネットワーク回線が極端に細く大量データの転送が非現実的な場合に有効な代替手段の組み合わせとして正しいものはどれですか？',
    choices:['ネットワーク経由の継続同期にはAWS DataSync、ネットワークが細い場合は物理デバイスでデータを輸送するAWS Snowballが有効','ネットワーク経由の継続同期にはAWS Snowball、ネットワークが細い場合はAWS DataSyncが有効','どちらの場合もAWS Direct Connectで専用線を新設するのが唯一の解決策である','どちらの場合もAmazon S3 Transfer Accelerationを使えば帯域の制約なく高速転送できる'], correct:[0],
    why:['正しい。AWS DataSyncはネットワーク経由でオンプレミスとS3間のデータを安全かつ高速に転送・継続同期でき、ネットワーク帯域が極端に細く大量データの転送が非現実的な場合は、物理デバイスでデータを輸送するAWS Snowballが有効な代替手段になります。','誤り。DataSyncとSnowballの用途が逆です。Snowballはネットワークを使わずに物理デバイスでデータを輸送するサービスです。','誤り。Direct Connectの新設には時間とコストがかかり、今回のような状況に対する唯一の解決策ではありません。','誤り。S3 Transfer Accelerationは地理的に離れた場所からのアップロードを高速化する機能であり、ネットワーク帯域そのものの制約を解消するものではありません。']},
  {id:'p359', domain:'tech', type:'single', source:SOURCES.lex, text:'顧客からの問い合わせに音声やテキストで自動応答する会話型チャットボットを構築したい。「ユーザーの発話内容を理解して適切な処理に振り分ける対話エンジン」「音声をテキストに変換する機能」「テキストを自然な音声に変換する機能」をそれぞれ担うサービスの組み合わせとして正しいものはどれですか？',
    choices:['Amazon Translate / Amazon Polly / Amazon Transcribe','Amazon Lex / Amazon Transcribe / Amazon Polly','Amazon Comprehend / Amazon Polly / Amazon Transcribe','Amazon Lex / Amazon Polly / Amazon Transcribe'], correct:[1],
    why:['誤り。Amazon Translateは言語間の機械翻訳を行うサービスで対話エンジンではなく、Polly(音声合成)とTranscribe(音声認識)の役割も入れ替わっています。','正しい。対話エンジンにはAmazon Lex、音声からテキストへの変換にはAmazon Transcribe、テキストから音声への変換にはAmazon Pollyを使用します。','誤り。Amazon Comprehendは自然言語のテキスト分析(感情分析等)を行うサービスで対話エンジンではなく、Polly(音声合成)とTranscribe(音声認識)の役割も入れ替わっています。','誤り。Polly(音声合成)とTranscribe(音声認識)の役割が入れ替わっています。']},
  {id:'p360', domain:'billing', type:'multi', source:SOURCES.costOptimizationHub, text:'AWS Cost Optimization Hubの特徴として正しいものを2つ選択してください。',
    choices:['予算のしきい値を自分で設定し、超過時にアラートを送信する','複数のAWSアカウント・リージョンにわたるコスト最適化の推奨事項(リソースのライトサイジング、アイドルリソースの削除、Savings Plans/リザーブドインスタンスの購入推奨等)を1つのダッシュボードに集約する','第三者機関によるコンプライアンス認証レポートを提供する','自社のAWSの料金・割引条件(リザーブドインスタンスやSavings Plans等)を反映した上で、推奨事項を実施した場合の節約額を重複排除して定量化する'], correct:[1,3],
    why:['誤り。これはAWS Budgetsの説明です。','正しい。AWS Cost Optimization Hubは、複数のAWSアカウント・リージョンにわたるコスト最適化の推奨事項を1つのダッシュボードに集約し、個別の製品にアクセスしなくても最適化の機会を特定できます。','誤り。これはAWS Artifactの説明です。','正しい。AWS Cost Optimization Hubは、利用者ごとの料金・割引条件を反映して節約額を定量化し、関連する推奨事項間での重複を排除して算出します。']},
  {id:'p361', domain:'billing', type:'single', source:SOURCES.computeOptimizer, text:'AWS Compute OptimizerとAWS Cost Optimization Hubの役割の違いとして正しいものはどれですか？',
    choices:['Compute Optimizerは複数アカウントの請求を一括請求にまとめ、Cost Optimization Hubは個々のリソースを分析する','Compute Optimizerは第三者認証レポートを提供し、Cost Optimization Hubは予算アラートを送信する','Compute OptimizerはCloudWatchメトリクスに基づき個々のリソース(EC2・Lambda等)のライトサイジング推奨を生成し、Cost Optimization Hubはそれらの推奨事項をRI/Savings Plansの購入推奨等も含めて複数アカウント・リージョンにわたって集約・一元化する','Compute OptimizerはAWSの利用規約への準拠を評価し、Cost Optimization Hubはセキュリティインシデントを検出する'], correct:[2],
    why:['誤り。Compute Optimizerは一括請求(Consolidated Billing)の機能ではありません。','誤り。両サービスとも第三者認証レポートの提供や予算アラートの送信は行いません。','正しい。Compute OptimizerはCloudWatchメトリクスに基づき個々のリソースのライトサイジング推奨を生成し、Cost Optimization Hubはそれらを含む複数の種類の推奨事項を複数アカウント・リージョンにわたって集約・一元化する、より上位の集約レイヤーです。','誤り。どちらのサービスもセキュリティの評価・検出は行いません。']},
  {id:'p362', domain:'billing', type:'multi', source:SOURCES.support, text:'AWS Basic Supportプラン(すべてのAWSアカウントに自動的に無料で付与される)に含まれるものを2つ選択してください。',
    choices:['AWS Trusted Advisorのコアチェック(一部のベストプラクティスチェック)','24時間365日、電話・チャットで技術サポートエンジニアに直接問い合わせできる技術支援','アカウント・請求に関する問い合わせサポートおよびAWS Healthによるサービスの状態に関する通知','専任のTechnical Account Manager(TAM)による戦略的なアドバイス'], correct:[0,2],
    why:['正しい。Basic Supportには、AWS Trusted Advisorの一部のベストプラクティスチェック(コアチェック)が含まれます。','誤り。24時間365日の技術サポートエンジニアへの問い合わせは、Business Support+等の有料プランで提供される機能です。','正しい。Basic Supportには、アカウント・請求に関する問い合わせサポートと、AWS Healthによるサービスの状態に関する通知が含まれます。','誤り。専任のTAMは、Enterprise Support等のより上位の有料プランで提供される機能です。']},
  {id:'p363', domain:'concepts', type:'single', source:SOURCES.wafCost, text:'AWS Well-Architected Frameworkの「コスト最適化の柱」の設計原則の一つ「消費モデルの導入(Adopt a consumption model)」が重視する内容として正しいものはどれですか？',
    choices:['実際に消費したコンピューティングリソースの分だけ料金を支払い、ビジネス要件に応じて使用量を増減させること','将来の需要に備えてハードウェアを事前に大量購入しておくこと','ワークロードのビジネス上の成果とそれにかかるコストを測定すること','IT部門主導でコストと使用状況を分析し、収益に帰属させること'], correct:[0],
    why:['正しい。「消費モデルの導入」は、実際に消費したコンピューティングリソースの分だけ料金を支払い、ビジネス要件に応じて使用量を増減させることを重視する設計原則です。例えば開発・テスト環境は業務時間外に停止することでコストを削減できます。','誤り。これは消費モデルとは逆の、従来のオンプレミス的な事前調達の考え方です。','誤り。これは「効率の測定(Measure Overall Efficiency)」という別の設計原則の内容です。','誤り。これは「費用の分析と帰属(Analyze and attribute expenditure)」という別の設計原則の内容です。']},
  {id:'p364', domain:'concepts', type:'single', source:SOURCES.wafPerformance, text:'AWS Well-Architected Frameworkの「パフォーマンス効率の柱」の設計原則の一つ「メカニカルシンパシーを持つ(Consider mechanical sympathy)」が重視する内容として正しいものはどれですか？',
    choices:['複数のAWSリージョンにワークロードを展開し、低コストで世界中の顧客に低レイテンシーを提供すること','データのアクセスパターン等を考慮し、ワークロードの目的に最も適した技術的アプローチ（データベースやストレージの種類等）を選択すること','サーバーの運用・管理を意識せずに済むサーバーレスアーキテクチャを採用すること','異なるインスタンスタイプやストレージ構成で比較テストを繰り返し実施すること'], correct:[1],
    why:['誤り。これは「数分でグローバル展開する(Go global in minutes)」という別の設計原則の内容です。','正しい。「メカニカルシンパシーを持つ」は、データのアクセスパターンなどを考慮して、ワークロードの目的に最も適した技術的アプローチ（データベースやストレージの種類等）を選択することを重視する設計原則です。','誤り。これは「サーバーレスアーキテクチャを使用する(Use serverless architectures)」という別の設計原則の内容です。','誤り。これは「実験の頻度を増やす(Experiment more often)」という別の設計原則の内容です。']},
  {id:'p365', domain:'concepts', type:'single', source:SOURCES.wafSustainability, text:'AWS Well-Architected Frameworkの「持続可能性の柱」の設計原則の一つ「使用率を最大化する(Maximize utilization)」が重視する内容として正しいものはどれですか？',
    choices:['新しく登場したより効率的なハードウェアやソフトウェアを継続的に評価し、採用できるよう設計すること','ワークロードの環境への影響を測定し、将来の影響を予測すること','ワークロードを適切な規模(ライトサイジング)にし、無駄なアイドル状態のリソースを減らすことで、基盤となるハードウェアの使用率とエネルギー効率を高めること','マネージドサービスを利用し、データセンターの共通コンポーネントの影響を複数顧客で分担すること'], correct:[2],
    why:['誤り。これは「新しくより効率的なハードウェア・ソフトウェアの提供を予測し適応する」という別の設計原則の内容です。','誤り。これは「影響の認識(Understand your impact)」という別の設計原則の内容です。','正しい。「使用率を最大化する」は、ワークロードをライトサイジングし効率的な設計を行うことで高い使用率を確保し、アイドル状態のリソースを減らして基盤ハードウェアのエネルギー効率を最大化することを重視する設計原則です（例: 30%使用率のホスト2台より60%使用率のホスト1台の方が効率的）。','誤り。これは「マネージドサービスを使用する(Use managed services)」という別の設計原則の内容です。']},
  {id:'p366', domain:'security', type:'single', source:SOURCES.wafSecurity, text:'AWS Well-Architected Frameworkの「セキュリティの柱」の設計原則の一つ「強固なアイデンティティ基盤を実装する(Implement a strong identity foundation)」が重視する内容として正しいものはどれですか？',
    choices:['ネットワークの境界からアプリケーション・コードまで、複数の階層すべてにセキュリティ管理策を適用すること','ソフトウェアベースの自動化されたセキュリティ機構を活用し、ベストプラクティスをコード化すること','インシデント対応のための計画・プロセスをあらかじめ準備しておくこと','最小権限の原則を実装し、各操作に適切な権限分離を強制するとともに、アイデンティティ管理を一元化し、長期的な静的認証情報への依存をなくすこと'], correct:[3],
    why:['誤り。これは「セキュリティを全レイヤーに適用する(Apply security at all layers)」という別の設計原則の内容です。','誤り。これは「セキュリティのベストプラクティスを自動化する(Automate security best practices)」という別の設計原則の内容です。','誤り。これは「セキュリティイベントに備える(Prepare for security events)」という別の設計原則の内容です。','正しい。「強固なアイデンティティ基盤を実装する」は、最小権限の原則を実装し適切な権限分離を強制するとともに、アイデンティティ管理を一元化して長期的な静的認証情報への依存を排除することを重視する設計原則です。']},
  {id:'p367', domain:'security', type:'single', source:SOURCES.wafSecurity, text:'AWS Well-Architected Frameworkの「セキュリティの柱」の設計原則の一つ「トレーサビリティを維持する(Maintain traceability)」が重視する内容として正しいものはどれですか？',
    choices:['環境に対する操作や変更をリアルタイムで監視・警告・監査し、ログやメトリクスの収集をシステムと統合して自動的に調査・対応できるようにすること','リスク評価や緩和戦略を適用しながらデータ・システム・資産を保護すること','データを機密レベルに分類し、暗号化などの仕組みを適切に利用すること','人がデータへ直接アクセスする必要性を減らし、誤操作のリスクを低減すること'], correct:[0],
    why:['正しい。「トレーサビリティを維持する」は、環境への操作や変更をリアルタイムで監視・警告・監査し、ログ・メトリクスの収集をシステムと統合して自動的な調査・対応を可能にすることを重視する設計原則です。','誤り。これはセキュリティの柱全体の概要的な説明です。','誤り。これは「データを保護する(Protect data in transit and at rest)」という別の設計原則の内容です。','誤り。これは「人がデータに直接触れないようにする(Keep people away from data)」という別の設計原則の内容です。']},
  {id:'p368', domain:'security', type:'single', source:SOURCES.verifiedPermissions, text:'あるSaaS企業が、複数のアプリケーションにまたがる「誰がどのリソースに対してどの操作を許可されるか」という認可(authorization)ロジックを、アプリケーションのコードから切り離し、Cedarポリシー言語を使って一元的に管理・テストしたいと考えている。最も適したサービスはどれですか？',
    choices:['Amazon Cognito','Amazon Verified Permissions','AWS IAM Identity Center','AWS Directory Service'], correct:[1],
    why:['誤り。Amazon Cognitoはユーザーの認証(サインアップ・サインイン)やIDプールによる一時的なAWS認証情報の発行を主に担うサービスであり、アプリケーション独自のきめ細かな認可ロジックの一元管理は主目的ではありません。','正しい。Amazon Verified Permissionsは、Cedarポリシー言語を使ってアプリケーションの認可ロジックをビジネスロジックから切り離し、一元的なポリシー管理・テストを可能にするきめ細かな認可サービスです。認証はCognito等の別の手段で行われている前提で動作します。','誤り。AWS IAM Identity Centerは、AWSアカウントやAWS管理対象アプリケーションへの従業員のサインインを一元管理するサービスであり、カスタムアプリケーション独自の認可ロジックの管理を主目的とはしていません。','誤り。AWS Directory Serviceは、Microsoft Active Directoryと連携・統合するためのディレクトリサービスです。']},
  {id:'p369', domain:'tech', type:'single', source:SOURCES.appflow, text:'Salesforceに蓄積された商談データを、コードを書かずに定期的なスケジュールでAmazon Redshiftに取り込み、インターネットを経由せずAWS PrivateLink経由でプライベートにデータを転送したい場合、最も適したサービスはどれですか？',
    choices:['AWS Glue','Amazon Kinesis Data Streams','Amazon AppFlow','AWS DataSync'], correct:[2],
    why:['誤り。AWS GlueはETL(データの抽出・変換・ロード)やデータカタログ作成を行うサービスであり、SaaSアプリケーションとの定期連携に特化したものではありません。','誤り。Amazon Kinesis Data Streamsはストリーミングデータのリアルタイム取り込みを行うサービスであり、SalesforceのようなSaaSアプリケーションとの連携機能は持ちません。','正しい。Amazon AppFlowは、Salesforce等のSaaSアプリケーションとAWSサービス(Amazon S3やAmazon Redshift等)の間で、コードを書かずにオンデマンドまたはスケジュールでデータを安全に交換できるマネージド型の統合サービスです。AWS PrivateLinkと連携し、インターネットを経由しないプライベートなデータ転送にも対応します。','誤り。AWS DataSyncは主にオンプレミスとAWSストレージ間、またはAWSストレージサービス間のデータ転送・同期を行うサービスであり、SaaSアプリケーションとの連携は主目的ではありません。']},
  {id:'p370', domain:'tech', type:'single', source:SOURCES.imageBuilder, text:'複数のチームが使用するEC2のAMI(Amazon マシンイメージ)について、OSパッチの適用や必要なソフトウェアのインストールといったカスタマイズ・テスト・配布のパイプラインを自動化し、常に最新かつセキュリティ基準を満たしたイメージを維持したい場合、最も適したサービスはどれですか？',
    choices:['AWS CodeDeploy','AWS Systems Manager','Amazon Elastic Container Registry (ECR)','EC2 Image Builder'], correct:[3],
    why:['誤り。AWS CodeDeployはアプリケーションのデプロイを自動化するサービスであり、AMI自体の作成・パッチ適用・テストのパイプラインを管理するものではありません。','誤り。AWS Systems Managerは稼働中のインスタンスの運用管理(パッチ適用や設定管理等)を行うサービスであり、新しいイメージの作成パイプライン自体を管理するものではありません。','誤り。Amazon ECRはコンテナイメージを保存するレジストリサービスであり、AMIの作成・テスト・パッチ適用の自動化は行いません。','正しい。EC2 Image Builderは、AMIやコンテナイメージのカスタマイズ・テスト・配布を自動化し、OSパッチの適用などを含めて常に最新でセキュアなイメージを維持するためのマネージドサービスです。サービス自体の利用に追加費用はかからず、生成時に使用するEC2インスタンスなど他のAWSリソースの料金のみが発生します。']},
  {id:'p371', domain:'tech', type:'single', source:SOURCES.elb, text:'WebアプリケーションでURLのパスに応じて異なるターゲットグループにリクエストを振り分けたい(パスベースルーティング)場合に最も適したElastic Load Balancingの種類はどれですか？',
    choices:['Application Load Balancer (ALB)','Network Load Balancer (NLB)','Gateway Load Balancer (GWLB)','Classic Load Balancer'], correct:[0],
    why:['正しい。Application Load Balancer (ALB)はOSI参照モデルのレイヤー7(アプリケーション層)で動作し、URLのパスやホストヘッダーなどHTTP/HTTPSの内容に基づいて異なるターゲットグループへリクエストを振り分けるパスベース・ホストベースのルーティングに対応しています。','誤り。Network Load Balancer (NLB)はレイヤー4(トランスポート層)で動作し、TCP/UDP/TLSトラフィックを極めて高いスループットと低レイテンシーで処理しますが、HTTPのパスに基づくルーティングは行いません。','誤り。Gateway Load Balancer (GWLB)は、サードパーティ製の仮想アプライアンス(ファイアウォール等)にトラフィックを透過的に振り分けるためのもので、アプリケーションのパスベースルーティング用途ではありません。','誤り。Classic Load Balancerは旧世代のロードバランサーで、パスベースルーティングなどALBの高度な機能には対応していません。']},
  {id:'p372', domain:'tech', type:'single', source:SOURCES.elb, text:'複数のVPCを行き来するすべてのトラフィックを、サードパーティ製の侵入検知/防止(IDS/IPS)用仮想アプライアンス群に透過的に経由させ、検査後のトラフィックを引き続き宛先へ届けたい場合、最も適したElastic Load Balancingの種類はどれですか？',
    choices:['Application Load Balancer (ALB)','Gateway Load Balancer (GWLB)','Network Load Balancer (NLB)','Classic Load Balancer'], correct:[1],
    why:['誤り。ALBはHTTP/HTTPSのアプリケーショントラフィックのルーティング用であり、第三者の仮想アプライアンスへの透過的なトラフィック転送は主目的ではありません。','正しい。Gateway Load Balancer (GWLB)はOSI参照モデルのレイヤー3で動作し、GENEVEプロトコル(UDPポート6081)を使ってトラフィックをサードパーティ製の仮想アプライアンス(ファイアウォールやIDS/IPS等)の集まりに透過的に振り分け、検査後のトラフィックを引き続き宛先へ届けることができます。','誤り。NLBは高性能なTCP/UDPトラフィックの負荷分散用であり、サードパーティ仮想アプライアンスへの透過的な挿入を主目的とした設計ではありません。','誤り。Classic Load Balancerは旧世代のロードバランサーで、GWLBのような仮想アプライアンス挿入機能はありません。']},
  {id:'p373', domain:'billing', type:'single', source:SOURCES.ec2Ri, text:'EC2リザーブドインスタンスの支払いオプションのうち、「契約期間の開始時に一部の料金のみを前払いし、残りは利用期間中の時間料金として分割して支払う」ことで、全額前払い(All Upfront)より初期費用を抑えつつ、前払いなし(No Upfront)よりも割引率を高くできるオプションはどれですか？',
    choices:['All Upfront','No Upfront','Partial Upfront','Savings Plans'], correct:[2],
    why:['誤り。All Upfrontは契約期間の開始時に全額を前払いするオプションで、以降の追加料金は発生しません。','誤り。No Upfrontは前払いなしで、利用期間中の時間料金のみを支払うオプションです。','正しい。Partial Upfrontは契約開始時に一部の料金を前払いし、残りを利用期間中の時間料金として分割して支払うオプションで、All UpfrontとNo Upfrontの中間の割引率・キャッシュフローとなります。','誤り。Savings Plansはリザーブドインスタンスとは別の購入オプションで、インスタンスファミリーに縛られずEC2・Fargate・Lambda等を横断して適用できます。']},
  {id:'p374', domain:'billing', type:'multi', source:SOURCES.riMarketplace, text:'Amazon EC2 Reserved Instance Marketplaceで、不要になったリザーブドインスタンスを出品・売却する際の条件・制限として正しいものを2つ選択してください。',
    choices:['Convertible Reserved Instance(コンバーティブル)も含め、すべての種類のリザーブドインスタンスを出品できる','出品できるのはAmazon EC2のStandard Reserved Instanceのみで、Amazon RDSやAmazon ElastiCacheの予約インスタンスは出品できない','リザーブドインスタンスを購入した直後であればいつでも出品できる','出品するには契約期間の残り期間が1か月以上必要である'], correct:[1,3],
    why:['誤り。出品できるのはAmazon EC2のStandard Reserved Instanceのみで、Convertible Reserved Instanceは出品できません。','正しい。Reserved Instance Marketplaceで出品できるのはAmazon EC2のStandard Reserved Instance(リージョナル/ゾーナル)のみで、Amazon RDSやAmazon ElastiCacheなど他サービスの予約インスタンスは出品できません。','誤り。前払い(アップフロント)料金がある場合はAWSがその支払いを受領済みであることに加え、アカウント内でアクティブになってから最低30日経過している必要があります。','正しい。出品するには、Standard Reserved Instanceの契約期間の残り期間が1か月以上なければなりません。']},
  {id:'p375', domain:'billing', type:'single', source:SOURCES.trustedadvisor, text:'AWS Trusted Advisorの「コアチェック」(Service Limitsの全項目とSecurity/Fault Toleranceの一部項目)は、無料のBasic Supportプランでも確認できる。一方、コスト最適化等を含む全項目の「フルチェック」を利用するには、どのサポートプランへの加入が必要ですか？',
    choices:['Basic Support','Basic Supportに無料のアドオン機能を追加することで利用できる','Enterprise Supportのみ(Business Support+やUnified Operationsでは利用できない)','Business Support+・Enterprise Support・Unified Operationsのいずれか'], correct:[3],
    why:['誤り。Basic Supportではコアチェック(Service Limitsの全項目とSecurity/Fault Toleranceの一部項目)のみ利用可能で、フルチェックは利用できません。','誤り。フルチェックの利用はアドオンではなく、上位の有料サポートプランへの加入によって提供されます。','誤り。Enterprise Supportに限らず、Business Support+やUnified Operationsでもフルチェックを利用できます。','正しい。AWS公式ドキュメントによれば、Trusted Advisorのフルチェックは、Business Support+・Enterprise Support・Unified Operationsのいずれかのサポートプランに加入している顧客が利用できます。Basic Supportでは、Service Limitsの全項目とSecurity/Fault Toleranceの一部項目のみ利用可能です。']},
  {id:'p376', domain:'tech', type:'single', source:SOURCES.cloudshell, text:'AWS CLIをローカル端末にインストールしたり認証情報を別途設定したりすることなく、AWS Management Consoleから直接起動したブラウザ上のターミナルで、すぐにAWSリソースを操作したい場合、最も適したサービスはどれですか？',
    choices:['AWS CloudShell','Amazon WorkSpaces','AWS Systems Manager Session Manager','AWS Cloud9'], correct:[0],
    why:['正しい。AWS CloudShellは、AWS Management Consoleから直接起動できるブラウザベースの事前認証済みシェルで、AWS CLIがプリインストールされており、ログイン時のコンソール認証情報がそのまま利用できます。','Amazon WorkSpacesはクラウド上の仮想デスクトップ(DaaS)であり、ブラウザ上のコマンドラインシェルではありません。','Session ManagerはEC2インスタンス等へのSSHキー不要なアクセス手段であり、AWSアカウント操作用の事前認証済みシェル環境ではありません。','AWS Cloud9はEC2インスタンス等の環境構築を伴うブラウザベースの統合開発環境(IDE)であり、CloudShellのような環境構築不要のシェル専用サービスではありません。']},
  {id:'p377', domain:'tech', type:'single', source:SOURCES.route53, text:'Amazon Route 53を使って、プライマリサイトが正常かどうかを定期的に確認し、障害が検知された場合に自動的にセカンダリサイトへDNSの参照先を切り替えたい場合、使用する機能はどれですか？',
    choices:['ジオロケーションルーティングポリシー','ヘルスチェックとフェイルオーバールーティングポリシー','加重(Weighted)ルーティングポリシー','レイテンシーベースルーティングポリシー'], correct:[1],
    why:['ジオロケーションルーティングポリシーは、ユーザーの地理的位置に基づいて応答するリソースを決定するものであり、正常性の監視や自動切り替えが主目的ではありません。','正しい。Route 53のヘルスチェック機能はエンドポイントの正常性を定期的に確認し、フェイルオーバールーティングポリシーと組み合わせることで、障害時にセカンダリサイトへ自動的にDNSの参照先を切り替えられます。','加重ルーティングポリシーは、設定した比率に応じて複数のリソースにトラフィックを振り分けるものであり、障害時の自動切り替えが主目的ではありません。','レイテンシーベースルーティングポリシーは、ユーザーに最も低いレイテンシーで応答できるリージョンにルーティングするものであり、障害時の自動切り替えが主目的ではありません。']},
  {id:'p378', domain:'tech', type:'single', source:SOURCES.elb, text:'1秒間に数百万リクエストに達するような極めて高いトラフィックを、超低レイテンシーで処理しつつ、クライアントに単一の静的IPアドレスを提供したい場合、最も適したElastic Load Balancingの種類はどれですか？',
    choices:['Application Load Balancer (ALB)','Gateway Load Balancer (GWLB)','Network Load Balancer (NLB)','Classic Load Balancer (CLB)'], correct:[2],
    why:['ALBはHTTP/HTTPSなどアプリケーション層(レイヤー7)のルーティングに特化しており、静的IPの提供や超低レイテンシーの処理が主目的ではありません。','GWLBは、サードパーティ製の仮想アプライアンス(IDS/IPS等)にトラフィックを透過的に経由させることに特化したロードバランサーです。','正しい。Network Load Balancer(NLB)は、TCP/UDPなどトランスポート層(レイヤー4)で動作し、毎秒数百万リクエスト規模の急激なトラフィック変動を超低レイテンシーで処理でき、各アベイラビリティーゾーンに静的IPアドレス(Elastic IP)を割り当てられます。','Classic Load Balancerは旧世代のロードバランサーで、新規の設計では推奨されていません。']},
  {id:'p379', domain:'tech', type:'single', source:SOURCES.ebs, text:'Amazon EBSボリュームのスナップショットを複数回取得する場合の課金・保存の仕組みとして正しいものはどれですか？',
    choices:['毎回ボリューム全体のデータを複製するため、スナップショットのたびにボリュームと同じ容量分の料金が発生する','スナップショットはボリュームとは独立してEC2インスタンス上にのみ保存され、インスタンスを削除すると失われる','スナップショットを取得するとボリュームが自動的に暗号化され、取得後は復号できなくなる','最初のスナップショットはボリューム全体のデータを保存するが、2回目以降は前回のスナップショットから変更されたブロックのみを保存する増分(インクリメンタル)方式のため、ストレージ使用量を抑えられる'], correct:[3],
    why:['誤り。2回目以降のスナップショットは変更分のみを保存する増分方式であり、毎回全体を複製するわけではありません。','誤り。EBSスナップショットはAmazon S3に保存され、EC2インスタンスのライフサイクルとは独立して永続化されます。','誤り。スナップショットの取得自体が自動暗号化や復号不能化を引き起こすことはありません(元のボリュームが暗号化されていればスナップショットも暗号化されます)。','正しい。EBSスナップショットは増分方式で保存されるため、最初のスナップショット以降は変更されたブロックのみが追加で保存され、ストレージ使用量とコストを抑えられます。']},
  {id:'p380', domain:'security', type:'single', source:SOURCES.config, text:'複数の個別のAWS Configルールを一つのパッケージとしてまとめ、テンプレートを使って組織内の複数のアカウント・リージョンに一括でデプロイ・管理したい場合、AWS Configで使用する機能はどれですか？',
    choices:['コンフォーマンスパック(Conformance Packs)','アグリゲータ(Aggregator)','カスタムルール(Custom Rules)','修復アクション(Remediation Actions)'], correct:[0],
    why:['正しい。コンフォーマンスパックは、複数のAWS Configルールと修復アクションをテンプレートとして一つにまとめ、組織内の複数のアカウント・リージョンに一括でデプロイ・管理できる機能です。','アグリゲータは、複数アカウント・リージョンのConfigデータを一か所に集約して閲覧するための機能であり、ルールをまとめてデプロイする機能ではありません。','カスタムルールは、AWS Lambda等を使って独自に作成する個別のConfigルールであり、複数ルールをまとめて配布する仕組みそのものではありません。','修復アクションは、ルール違反を検知した際に自動的に是正措置を実行する機能で、コンフォーマンスパックの構成要素の一つですが、それ自体は複数ルールをまとめる機能ではありません。']},
  {id:'p381', domain:'security', type:'single', source:SOURCES.verifiedPermissions, text:'Amazon Verified Permissionsを使った認可(authorization)の仕組みの特徴として正しいものはどれですか？',
    choices:['アプリケーションのソースコード内に認可ロジックをハードコーディングすることで、評価速度を最大化する','Cedarポリシー言語で記述された認可ポリシーをアプリケーションのコードから切り離して一元管理し、アプリケーションからのリアルタイムなAPI呼び出しによって認可判定(許可/拒否)を評価する','IAMポリシーのみを使用し、Cedarのような独自のポリシー言語は使用しない','認可判定の結果を事前に全てキャッシュし、ポリシーを更新しても即座には反映されない'], correct:[1],
    why:['誤り。Verified Permissionsは認可ロジックをアプリケーションのコードから切り離して一元管理することを目的としています。','正しい。Amazon Verified Permissionsは、Cedarポリシー言語で記述した認可ポリシーをアプリケーションのコードから切り離して一元管理し、アプリケーションからのリアルタイムなAPI呼び出しによって認可判定を評価するフルマネージドサービスです。','誤り。Verified PermissionsはIAMポリシーではなく、独自のCedarポリシー言語を使用します。','誤り。認可判定はリアルタイムのAPI呼び出しによって評価されます。']},
  {id:'p382', domain:'security', type:'single', source:SOURCES.directoryService, text:'オンプレミスに既存のActive Directoryを運用している企業が、ディレクトリのユーザー情報をAWS側に複製・同期せず、認証リクエストをそのままオンプレミスのADにリダイレクト(プロキシ)するだけの仕組みを使いたい場合、AWS Directory Serviceのどの機能が最も適していますか？',
    choices:['AWS Managed Microsoft AD','Simple AD','AD Connector','Amazon Cognito ユーザープール'], correct:[2],
    why:['AWS Managed Microsoft ADは、AWSクラウド上に新しいMicrosoft Active Directoryを構築するものであり、ユーザー情報の一部がAWS側にも保持されます。','Simple ADは、AWS上に構築する基本的な機能のみを持つ独立したディレクトリであり、オンプレミスADと連携する機能ではありません。','正しい。AD Connectorは、ユーザー情報をAWS側に複製せず、認証リクエストをそのままオンプレミスの既存Active Directoryにリダイレクト(プロキシ)するゲートウェイです。','Amazon CognitoユーザープールはWebアプリ/モバイルアプリ向けの独自のユーザーディレクトリであり、オンプレミスのADをそのままプロキシする仕組みではありません。']},
  {id:'p383', domain:'concepts', type:'single', source:SOURCES.localZones, text:'AWS Local ZonesとAWS Wavelengthの違いとして正しいものはどれですか？',
    choices:['Local Zonesは通信事業者(キャリア)の5Gネットワークの内部に設置されるのに対し、Wavelengthは一般的な大都市圏のデータセンターに設置される','Local Zonesは追加費用なしで全リージョンに自動的に有効化されるのに対し、Wavelengthは無効化できない','どちらも同じインフラストラクチャの別名であり、技術的な違いはない','Local Zonesは大都市圏の近接拠点にAWSサービスのサブセットを展開するのに対し、Wavelengthは通信事業者の5G等のネットワークエッジにAWSインフラを展開し、モバイルデバイスからの超低レイテンシーアクセスに特化している'], correct:[3],
    why:['誤り。この説明は逆です。Wavelengthが通信事業者の5Gネットワークの内部(エッジ)に設置されます。','誤り。Local ZonesもWavelengthも使用するには個別に有効化が必要です。','誤り。両者は異なる目的を持つ別々のインフラストラクチャです。','正しい。Local Zonesは大都市圏の近接拠点にAWSサービスのサブセットを展開してレイテンシーを下げるのに対し、Wavelengthは通信事業者のネットワークエッジにAWSインフラを展開し、5G等のモバイルデバイスからの超低レイテンシーアクセスに特化しています。']},
  {id:'p384', domain:'concepts', type:'single', source:SOURCES.shared, text:'AWSの責任共有モデルにおいて、Amazon EC2インスタンスに適用するセキュリティグループのインバウンド/アウトバウンドルールの設定は、マネージド型サービスであるかどうかにかかわらず、常に誰の責任ですか？',
    choices:['顧客(利用者)','AWS','AWSと顧客が折半で負う共同責任','インスタンスが稼働するアベイラビリティーゾーンの運用者'], correct:[0],
    why:['正しい。ファイアウォールであるセキュリティグループやネットワークACLのルール設定は「クラウド内のセキュリティ」に該当し、常に顧客側の責任です。','誤り。AWSはクラウドを保護する物理インフラ等の責任を負いますが、セキュリティグループのルール設定自体は顧客の責任です。','誤り。責任共有モデルでは項目ごとに責任の所在が明確に分かれており、ルール設定を折半で負うものではありません。','誤り。そのような運用者の概念はなく、ルール設定は顧客が行います。']},
  {id:'p385', domain:'concepts', type:'multi', source:SOURCES.watool, text:'AWS Well-Architected Toolの特徴として正しいものを2つ選択してください。',
    choices:['追加費用なしで利用できる','ワークロードの脆弱性を自動的にスキャンし、パッチを適用する','ワークロードのレビュー結果を「マイルストーン」として記録し、時間の経過に伴う改善を追跡できる','ワークロードの構成変更を自動的にロールバックする'], correct:[0,2],
    why:['正しい。AWS Well-Architected Toolは追加費用なしで利用できます。','誤り。脆弱性スキャンとパッチ適用はAmazon Inspectorなど別のサービスの役割です。','正しい。レビューを実施するたびに「マイルストーン」として結果を記録でき、時間の経過に伴うワークロードの改善を追跡できます。','誤り。構成変更の自動ロールバックは行いません。あくまで質問形式のレビューと改善提案を提供するツールです。']},
  {id:'p386', domain:'billing', type:'single', source:SOURCES.savingsplansTypes, text:'EC2 Instance Savings PlansとCompute Savings Plansの違いとして正しいものはどれですか？',
    choices:['EC2 Instance Savings Plansは3年契約のみ、Compute Savings Plansは1年契約のみ選択できる','EC2 Instance Savings Plansは特定のインスタンスファミリー・リージョンに固定される代わりにCompute Savings Plansより高い割引率が得られるが、Compute Savings Plansはインスタンスファミリー・リージョンを問わずEC2・Fargate・Lambdaにまたがって柔軟に適用できる','Compute Savings PlansはAmazon RDSの予約に特化しており、EC2には適用できない','EC2 Instance Savings Plansは前払いを選択できず、常に時間単位の後払いとなる'], correct:[1],
    why:['誤り。どちらも1年・3年のいずれかの契約期間を選択できます。','正しい。EC2 Instance Savings Plansは特定のインスタンスファミリー・リージョンに固定される代わりに高い割引率が得られ、Compute Savings Plansはインスタンスファミリー・リージョン・OS・テナンシーを問わずEC2・Fargate・Lambdaにまたがって柔軟に適用できます（割引率はやや低めです）。','誤り。Compute Savings PlansはAmazon RDSではなく、EC2・Fargate・Lambdaに適用されます。','誤り。EC2 Instance Savings Plansも全額前払い・一部前払い・前払いなしを選択できます。']},
  {id:'p387', domain:'billing', type:'single', source:SOURCES.billingConductor, text:'AWS Billing Conductorで作成する「プロフォーマ(見なし)」のカスタム請求書について正しい説明はどれですか？',
    choices:['プロフォーマの請求内容がそのままAWSへの実際の支払い金額として扱われ、Consolidated Billingによる実際の請求とは別に支払いが発生する','プロフォーマの設定を行うと、AWS Organizationsの管理アカウントへの実際の請求額も自動的に変更される','プロフォーマのカスタム請求書は、独自の価格ルールに基づいて社内やエンドカスタマー向けに作成する見なし上の請求情報であり、AWSへの実際の支払いは引き続きConsolidated Billingを通じて行われ、実際の請求額には影響しない','プロフォーマの機能を使うには、各メンバーアカウントがAWS Organizationsから離脱する必要がある'], correct:[2],
    why:['誤り。プロフォーマの請求内容は見なし上のものであり、AWSへの実際の支払いとは別です。','誤り。プロフォーマの設定は実際の請求額には影響しません。','正しい。Billing Conductorのプロフォーマのカスタム請求書は、独自の価格ルールに基づいて作成する見なし上の請求情報であり、AWSへの実際の支払いは引き続きConsolidated Billingを通じて行われます。','誤り。Billing Conductorを使うにはAWS Organizations内のメンバーアカウントである必要があり、離脱は不要です。']},
  {id:'p388', domain:'billing', type:'multi', source:SOURCES.costOptimizationHub, text:'AWS Cost Optimization HubとAWS Compute Optimizerの関係について正しいものを2つ選択してください。',
    choices:['Cost Optimization HubはCompute Optimizerの推奨事項を自動的に購入・適用し、ユーザーの承認は不要である','Cost Optimization Hubは、Compute Optimizerのライトサイジング推奨に加え、Savings Plansやリザーブドインスタンスの購入推奨など複数の種類のコスト削減推奨事項を、組織内の複数アカウント・リージョンにわたって一元的に集約する、より上位の集約レイヤーである','Compute OptimizerはCost Optimization Hubの機能を内包する上位サービスであり、Cost Optimization Hubは不要になった','Compute Optimizerは主にEC2インスタンスやEBSボリューム等のリソース使用率を分析してライトサイジング(適正サイズ化)を推奨するサービスであり、Cost Optimization Hubが集約する推奨事項の供給元の一つである'], correct:[1,3],
    why:['誤り。推奨事項の購入・適用には引き続きユーザーの承認・操作が必要です。','正しい。Cost Optimization Hubは、Compute Optimizerのライトサイジング推奨やSavings Plans/リザーブドインスタンスの購入推奨など複数のコスト削減推奨事項を、組織内の複数アカウント・リージョンにわたって一元的に集約する上位の集約レイヤーです。','誤り。この説明は逆です。Cost Optimization HubがCompute Optimizer等の推奨事項を集約する上位レイヤーです。','正しい。Compute Optimizerはリソース使用率を分析してライトサイジングを推奨するサービスであり、その推奨事項はCost Optimization Hubが集約する供給元の一つです。']},
  {id:'p389', domain:'concepts', type:'single', source:SOURCES.wafOps, text:'AWS Well-Architected Frameworkの「運用上の優秀性の柱」の設計原則の一つ「運用をコードとして実行する(Perform operations as code)」が重視する内容として正しいものはどれですか？',
    choices:['インフラストラクチャや運用手順をコード(例: AWS CloudFormationのテンプレート)として定義することで、人為的ミスを減らし、イベントへの対応を一貫させ、時間の経過とともに運用手順を進化させやすくすること','アプリケーションのソースコードの脆弱性を自動的にスキャンすること','障害を自動的に検知し、複数のアベイラビリティーゾーンにまたがって自動復旧させること','利用していないリソースを停止し、コストを削減すること'], correct:[0],
    why:['正しい。「運用をコードとして実行する」は、インフラや運用手順をコードとして定義することで、人為的ミスを減らし、イベントへの対応を一貫させ、運用手順を継続的に進化させやすくすることを重視する設計原則です。','これはAmazon Inspector等の脆弱性スキャンサービスの内容です。','これは信頼性の柱の内容です。','これはコスト最適化の柱の内容です。']},
  {id:'p390', domain:'concepts', type:'single', source:SOURCES.wafSustainability, text:'AWS Well-Architected Frameworkの「持続可能性の柱」の設計原則の一つ「影響を理解する(Understand your impact)」が重視する内容として正しいものはどれですか？',
    choices:['マネージドサービスを使用し、運用の重労働をAWSに任せること','ワークロードのビジネス上の成果に対する環境への影響を測定する指標を定義し、設計変更を行う際にその影響を評価・比較できるようにすること','需要の変化に応じてリソースを動的に拡大・縮小し、使用率を最大化すること','リソースの使用を地理的に分散させ、低レイテンシーを実現すること'], correct:[1],
    why:['これは持続可能性の柱の別の設計原則「マネージドサービスを使用する」の内容です。','正しい。「影響を理解する」は、ワークロードのビジネス上の成果に対する環境への影響を測定する指標を定義し、設計変更を行う際にその影響を評価・比較できるようにすることを重視する設計原則です。','これは持続可能性の柱の別の設計原則「使用率を最大化する」の内容です。','これはパフォーマンス効率や信頼性に関連する内容であり、この設計原則の説明ではありません。']},
  {id:'p391', domain:'concepts', type:'multi', source:SOURCES.rtorpo, text:'ディザスタリカバリ(DR)における「RTO(目標復旧時間)」と「RPO(目標復旧時点)」の違いとして正しいものを2つ選択してください。',
    choices:['RTOは障害発生から復旧までに許容できる最大の時間を表す目標値である','RPOは障害発生から復旧までに許容できる最大の時間を表す目標値である','RTOは障害発生時に許容できる最大のデータ損失量を表す目標値である','RPOは直前の正常なバックアップ/復旧時点から障害発生までに許容できる最大のデータ損失量を表す目標値である'], correct:[0,3],
    why:['正しい。RTO(目標復旧時間)は、障害発生から復旧までに許容できる最大の時間を表す目標値です。','誤り。これはRTOの説明です。RPOはデータ損失量に関する指標です。','誤り。これはRPOの説明です。RTOは復旧時間に関する指標です。','正しい。RPO(目標復旧時点)は、直前の正常なバックアップ/復旧時点から障害発生までに許容できる最大のデータ損失量を表す目標値です。']},
  {id:'p392', domain:'concepts', type:'single', source:SOURCES.wafCost, text:'AWS Well-Architected Frameworkの「コスト最適化の柱」の設計原則の一つ「費用の分析と帰属(Analyze and attribute expenditure)」が重視する内容として正しいものはどれですか？',
    choices:['開発・テスト環境は使用していない時間帯に停止し、使用した分のみ料金を払うこと','差別化につながらない重労働への投資をやめ、AWSにインフラ運用を任せること','コストと使用状況を正確に測定・モニタリングし、ワークロードの所有者ごとに費用を適切に帰属させることで、投資対効果を把握し最適化を促すこと','ワークロードのアウトプットとそれにかかるコストの両方を測定し、効率を評価すること'], correct:[2],
    why:['これは別の設計原則「消費モデルの導入」の内容です。','これは別の設計原則「差別化につながらない重労働への投資をやめる」の内容です。','正しい。「費用の分析と帰属」は、コストと使用状況を正確に測定・モニタリングし、ワークロードの所有者ごとに費用を適切に帰属させることで、投資対効果を把握し最適化を促すことを重視する設計原則です。','これは別の設計原則「効率の測定」の内容です。']},
  {id:'p393', domain:'security', type:'single', source:SOURCES.wafSecurity, text:'AWS Well-Architected Frameworkの「セキュリティの柱」の設計原則の一つ「セキュリティインシデントに備える(Prepare for security events)」が重視する内容として正しいものはどれですか？',
    choices:['セキュリティ要件をすべてのレイヤー（例: VPC境界、各コンピューティングインスタンス、OS、アプリケーション）に適用すること','ユーザー・システムの行動やイベントを監査し、変更内容をログとして記録・分析・保持できるようにすること','すべてのユーザーに強い権限を一律に付与し、承認プロセスを簡略化すること','組織のセキュリティインシデント管理・対応のポリシーやプロセスをあらかじめ準備し、ツールやアクセス権を事前に用意して、検出・調査・復旧を迅速化すること'], correct:[3],
    why:['これは別の設計原則「セキュリティを全レイヤーに適用する」の内容です。','これは別の設計原則「トレーサビリティを維持する」の内容です。','誤り。最小権限の原則に反する内容であり、セキュリティの柱が推奨する内容ではありません。','正しい。「セキュリティインシデントに備える」は、組織のインシデント管理・対応のポリシーやプロセスをあらかじめ準備し、ツールやアクセス権を事前に用意して検出・調査・復旧を迅速化することを重視する設計原則です。']},
  {id:'p394', domain:'security', type:'single', source:SOURCES.wafService, text:'AWS WAFの「マネージドルールグループ(AWS Managed Rules)」とは何ですか？',
    choices:['AWSやAWS Marketplaceの出品者が事前に作成・管理している、一般的な脆弱性(SQLインジェクション、XSS等)や既知の悪性IPに対応するルールセットで、自分でルールを一つずつ作成しなくても有効化できるもの','DDoS攻撃を受けた際に自動的に課金を補償してくれる仕組み','IPアドレスごとのリクエスト数のしきい値を設定し、超えた場合に自動的にブロックする独自のルール','複数のAWSアカウントにWAFルールを一元的に配布・適用する仕組み'], correct:[0],
    why:['正しい。マネージドルールグループは、AWSやAWS Marketplaceの出品者が事前に作成・管理している、一般的な脆弱性や既知の悪性IPに対応するルールセットで、自分で一つずつルールを作成しなくても有効化できます。','これはAWS Shield Advancedの補償(DDoS Cost Protection)の説明です。','これはAWS WAFのレート制限ルールの説明であり、マネージドルールグループとは別の機能です。','これはAWS Firewall Managerの説明です。']},
  {id:'p395', domain:'security', type:'single', source:SOURCES.securityIR, text:'AWS Security Incident Responseの役割として正しいものはどれですか？',
    choices:['機械学習を使ってAWS環境内の不審なAPIコールやネットワーク通信を独自に検出するサービス','Amazon GuardDutyやAWS Security Hub CSPM等が検出したセキュリティ上の検出結果を取り込んで自動トリアージし、対応が必要と判断された場合には専門のセキュリティインシデント対応チームが調査・コンテインメント・復旧のガイダンスを提供するマネージドサービス','セキュリティの検出結果や設定のベストプラクティス準拠状況を一元的に集約・可視化するサービス','複数のセキュリティ検出結果の関連性を可視化し、根本原因の調査を支援するサービス'], correct:[1],
    why:['これはAmazon GuardDutyの説明です。','正しい。AWS Security Incident Responseは、GuardDutyやSecurity Hub CSPM等の検出結果を取り込んで自動トリアージし、対応が必要と判断された場合には専門のセキュリティインシデント対応チームが調査・コンテインメント・復旧のガイダンスを提供するマネージドサービスです。','これはAWS Security Hubの説明です。','これはAmazon Detectiveの説明です。']},
  {id:'p396', domain:'security', type:'multi', source:SOURCES.securityIR, text:'AWS Security Incident Responseの特徴として正しいものを2つ選択してください。',
    choices:['Amazon GuardDutyやAWS Security Hub CSPM等の検出結果を取り込んでトリアージするが、自らセキュリティの検出結果(フィンディング)を生成するわけではない','脆弱性スキャンやペネトレーションテストを実施して、セキュリティ体制を評価する','対応が必要と判断された場合、24時間365日体制のセキュリティインシデント対応専門チームによる調査やコンテインメントの支援を受けられる','取り込んだすべての検出結果を、重要度に関わらずそのまま担当者に通知する'], correct:[0,2],
    why:['正しい。AWS Security Incident Responseは検出サービスではなく、GuardDuty等が生成した検出結果を取り込んでトリアージする仕組みです。','誤り。脆弱性スキャンやペネトレーションテストは、本サービスの対象範囲外です。','正しい。対応が必要と判断された場合、24時間365日体制の専門チームによる調査やコンテインメントの支援を受けられます。','誤り。取り込んだ検出結果の大部分は自動トリアージで処理され、対応が必要と判断された一部のみが担当者に通知されます。']},
  {id:'p397', domain:'tech', type:'single', source:SOURCES.iotGreengrass, text:'ある工場で、各設備のセンサーデータをエッジデバイス上でローカルに前処理し、簡易な機械学習推論もエッジデバイス上で実行したい。さらに、ネットワーク接続が一時的に切断してもエッジデバイス上での処理を継続し、接続が回復した際にAWS IoT Coreと同期したい場合、最も適したサービスはどれですか？',
    choices:['AWS IoT Core','Amazon Kinesis Data Streams','AWS IoT Greengrass','AWS Lambda'], correct:[2],
    why:['AWS IoT Coreはクラウド上で動作するメッセージブローカーであり、エッジデバイス上でローカルに処理を継続する機能は提供しません。','Amazon Kinesis Data Streamsはクラウド上のストリーミングデータ取り込みサービスであり、エッジデバイス上で動作するものではありません。','正しい。AWS IoT Greengrassは、エッジデバイス上でローカルにデータ処理や機械学習推論を実行できるIoTエッジランタイムで、ネットワーク接続が一時的に切断しても処理を継続し、接続回復時にAWS IoT Core等と同期できます。','AWS Lambda単体はクラウド上で実行されるサーバーレスコンピューティングサービスであり、ネットワーク切断時にエッジデバイス上で処理を継続する仕組みは提供しません。']},
  {id:'p398', domain:'tech', type:'multi', source:SOURCES.transitGateway, text:'VPCピアリングとAWS Transit Gatewayの使い分けとして正しいものを2つ選択してください。',
    choices:['VPCピアリング接続は推移的(transitive)であり、A-B間・B-C間をピアリングすればAはCとも自動的に通信できる','少数のVPC間の接続であればVPCピアリングで十分だが、数十・数百のVPCやオンプレミス拠点を接続する場合は、Transit Gatewayを使ってハブ&スポーク型に集約した方が管理がシンプルになる','Transit Gatewayは同一リージョン内のVPC同士の接続には利用できず、異なるリージョン間の接続専用のサービスである','Transit Gatewayはハブとして機能し、接続されたVPCやオンプレミス拠点間のルーティングを集中管理できる'], correct:[1,3],
    why:['誤り。VPCピアリング接続は推移的ではなく、AはCと直接通信できません。','正しい。少数のVPC間の接続であればVPCピアリングで十分ですが、数十・数百のVPCやオンプレミス拠点を接続する場合は、Transit Gatewayでハブ&スポーク型に集約した方が管理がシンプルになります。','誤り。Transit Gatewayは同一リージョン内のVPC同士の接続にも利用でき、リージョン間接続専用ではありません。','正しい。Transit Gatewayはハブとして機能し、接続されたVPCやオンプレミス拠点間のルーティングを集中管理できます。']},
  {id:'p399', domain:'tech', type:'single', source:SOURCES.ecr, text:'Amazon ECRにプッシュされたコンテナイメージについて、OSパッケージの既知の脆弱性(CVE)を自動的にスキャンしたい場合、最も適した方法はどれですか？',
    choices:['ECR単体では脆弱性スキャン機能を提供していないため、別途サードパーティ製品を利用する','AWS Trusted Advisorのセキュリティチェックを有効にする','Amazon GuardDutyのマルウェア保護機能を有効にする','Amazon ECRの拡張スキャン機能(Amazon Inspectorと連携)を有効にし、イメージのプッシュ時や継続的に脆弱性を自動スキャンする'], correct:[3],
    why:['誤り。ECRにはAmazon Inspectorと連携した拡張スキャン機能が組み込まれています。','AWS Trusted Advisorはコスト・パフォーマンス・セキュリティ等のベストプラクティスチェックを行いますが、コンテナイメージのCVEスキャンは行いません。','Amazon GuardDutyのマルウェア保護はEBSボリューム等を対象としたマルウェア検出機能であり、コンテナイメージのOSパッケージ脆弱性スキャンとは異なります。','正しい。Amazon ECRの拡張スキャン機能はAmazon Inspectorと連携し、イメージのプッシュ時や継続的にOSパッケージの既知の脆弱性(CVE)を自動スキャンできます。']},
  {id:'p400', domain:'billing', type:'single', source:SOURCES.costExplorer, text:'購入済みのリザーブドインスタンスやSavings Plansについて、実際にどの程度活用されているか(利用率)、またオンデマンド利用全体に対してどの程度の割合が割引適用されているか(カバレッジ)を確認したい場合、最も適したサービスはどれですか？',
    choices:['AWS Cost Explorer','AWS Budgets','AWS Cost and Usage Report (CUR)の生データを独自に分析する','AWS Trusted Advisor'], correct:[0],
    why:['正しい。AWS Cost Explorerには、購入済みのリザーブドインスタンスやSavings Plansの利用率(Utilization)レポートやカバレッジ(Coverage)レポートがあり、活用度を可視化できます。','AWS Budgetsは予算のしきい値超過を通知する機能であり、利用率・カバレッジレポートは提供しません。','生データの独自分析は可能ですが、追加の分析作業が必要であり、専用レポートを持つCost Explorerの方が適切です。','AWS Trusted AdvisorはRI/SPの購入推奨チェックを提供しますが、利用率・カバレッジの専用レポートはCost Explorerの機能です。']},
  {id:'p401', domain:'billing', type:'single', source:SOURCES.ec2Ri, text:'購入したAmazon EC2の標準リザーブドインスタンス(Standard RI)について、利用中のアベイラビリティーゾーンや、同一インスタンスファミリー内でのインスタンスサイズを変更したいが、リザーブドインスタンスの割引自体は引き続き受けたい場合、最も適した方法はどれですか？',
    choices:['リザーブドインスタンスをいったんEC2 Reserved Instance Marketplaceで売却し、新しい条件のリザーブドインスタンスを再度購入する','リザーブドインスタンスの「変更(モディファイ)」機能を使い、アベイラビリティーゾーンや同一インスタンスファミリー内のインスタンスサイズなどの属性を変更する','オンデマンドインスタンスに切り替え、リザーブドインスタンスは契約期間が終了するまで放置する','Savings Plansに切り替える'], correct:[1],
    why:['誤り。売却・再購入は手続きが煩雑でコストもかかり、既存の契約条件を失います。','正しい。Standard Reserved Instanceは「変更(モディファイ)」機能を使うことで、アベイラビリティーゾーンや同一インスタンスファミリー内のインスタンスサイズなどの属性を、割引を維持したまま変更できます。','誤り。リザーブドインスタンスの割引を活用できず、無駄が生じます。','誤り。Savings Plansへの切り替えは別の購入オプションへの変更であり、既存のリザーブドインスタンスの属性変更にはなりません。']},
  {id:'p402', domain:'concepts', type:'single', source:SOURCES.wafPerformance, text:'AWS Well-Architected Frameworkの「パフォーマンス効率の柱」の設計原則の一つ「高度なテクノロジーを誰でも使えるようにする(Democratize advanced technologies)」が重視する内容として正しいものはどれですか？',
    choices:['データベースや機械学習、メディアエンコーディングなどの複雑な技術をマネージドサービスとして利用できるようにし、専門知識が無いチームでも高度な技術を素早く導入・活用できるようにすること','ワークロードの目的に最も適した技術的アプローチを、データアクセスパターン等を考慮して選択すること','低コストで様々な設定を試し、本番環境に影響を与えずに実験を繰り返すこと','AWSの世界中のリージョンを利用して、わずか数クリックで複数リージョンにアプリケーションを展開すること'], correct:[0],
    why:['正しい。「高度なテクノロジーを誰でも使えるようにする」は、データベースや機械学習などの複雑な技術をマネージドサービスとして提供することで、専門知識を持たないチームでも高度な技術を素早く導入・活用できるようにすることを重視する設計原則です。','これは別の設計原則「メカニカルシンパシーを持つ」の内容です。','これは別の設計原則「実験の頻度を増やす(Experiment more often)」の内容です。','これは別の設計原則「数分でグローバル展開する(Go global in minutes)」の内容です。']},
  {id:'p403', domain:'concepts', type:'single', source:SOURCES.wafPerformance, text:'AWS Well-Architected Frameworkの「パフォーマンス効率の柱」の設計原則の一つ「実験の頻度を増やす(Experiment more often)」が重視する内容として正しいものはどれですか？',
    choices:['物理サーバーの運用・保守を不要にし、マネージドサービスの活用によって運用負荷を下げること','仮想化やクラウドの俊敏性を活用し、異なるインスタンスタイプやストレージ、構成の比較実験を低コストかつ短時間で繰り返し行えること','データのアクセスパターンなどを考慮して、ワークロードの目的に最も適した技術的アプローチを選択すること','高度なテクノロジーをマネージドサービスとして誰でも利用できるようにすること'], correct:[1],
    why:['これは別の設計原則「サーバーレスアーキテクチャを使用する(Use serverless architectures)」の内容です。','正しい。「実験の頻度を増やす」は、仮想化やクラウドの俊敏性を活用し、異なるインスタンスタイプ・ストレージ・構成などの比較実験を低コストかつ短時間で繰り返し行えることを重視する設計原則です。','これは別の設計原則「メカニカルシンパシーを持つ」の内容です。','これは別の設計原則「高度なテクノロジーを誰でも使えるようにする(Democratize advanced technologies)」の内容です。']},
  {id:'p404', domain:'concepts', type:'single', source:SOURCES.wafCost, text:'AWS Well-Architected Frameworkの「コスト最適化の柱」の設計原則の一つ「クラウド財務管理を導入する(Implement Cloud Financial Management)」が重視する内容として正しいものはどれですか？',
    choices:['利用していない開発・テスト環境を停止し、使用した分だけ料金を支払うこと','データセンター運用の重労働をAWSに任せ、差別化につながらない作業への投資を減らすこと','コスト最適化を継続的なビジネス上の取り組みとして位置づけ、財務・技術・ビジネスの各部門が連携してコスト管理とコスト最適化に必要な知識・プログラムを構築すること','ワークロードのビジネス上の成果と、それにかかるコストの両方を測定すること'], correct:[2],
    why:['これは別の設計原則「消費モデルの導入(Adopt a consumption model)」の内容です。','これは別の設計原則「差別化につながらない重労働への投資をやめる」の内容です。','正しい。「クラウド財務管理を導入する」は、コスト最適化を継続的なビジネス上の取り組みとして位置づけ、財務・技術・ビジネスの各部門が連携してコスト管理とコスト最適化に必要な知識やプログラムを構築することを重視する、コスト最適化の柱の設計原則です。','これは別の設計原則「効率の測定(Measure overall efficiency)」の内容です。']},
  {id:'p405', domain:'concepts', type:'single', source:SOURCES.wafSustainability, text:'AWS Well-Architected Frameworkの「持続可能性の柱」の設計原則の一つ「持続可能性の目標を設定する(Establish sustainability goals)」が重視する内容として正しいものはどれですか？',
    choices:['需要の変化に応じてリソースを動的に拡大・縮小し、使用率を最大化すること','マネージドサービスを使用し、運用の重労働をAWSに任せること','サプライヤーの選定やワークロード自体の影響だけでなく、エンドユーザーが製品やサービスを使う際に生じる影響(ダウンストリームへの影響)を削減すること','長期的な目標を設定し、各ワークロードについて、現在の状況に対する改善の進捗を追跡できるよう、投資対効果を含めた持続可能性の目標を定めること'], correct:[3],
    why:['これは別の設計原則「使用率を最大化する」の内容です。','これは別の設計原則「マネージドサービスを使用する」の内容です。','これは別の設計原則「ダウンストリームへの影響を削減する」の内容です。','正しい。「持続可能性の目標を設定する」は、長期的な目標を設定し、各ワークロードについて現在の状況に対する改善の進捗を追跡できるよう、投資対効果を含めた持続可能性の目標を定めることを重視する設計原則です。']},
  {id:'p406', domain:'security', type:'single', source:SOURCES.rolesAnywhere, text:'オンプレミスのデータセンターで稼働するサーバー群から、長期的なIAMアクセスキーを保存・管理せずにAWSリソースへアクセスしたい。サーバーには社内の認証局(CA)が発行したX.509証明書を導入できる場合、最も適したサービスはどれですか？',
    choices:['AWS IAM Roles Anywhere','AWS Direct Connect','AWS Site-to-Site VPN','AWS Secrets Manager'], correct:[0],
    why:['正しい。AWS IAM Roles Anywhereは、信頼された認証局(CA)が発行したX.509証明書を使って、オンプレミスのサーバーなどAWS外部のワークロードにIAMロールの一時的なセキュリティ認証情報を発行できるサービスで、長期的なアクセスキーの管理が不要になります。','誤り。AWS Direct Connectはオンプレミスとの専用線接続サービスであり、認証情報の発行機能はありません。','誤り。AWS Site-to-Site VPNはネットワーク接続サービスであり、認証情報の発行機能はありません。','誤り。AWS Secrets Managerはシークレットの保管・ローテーションサービスであり、証明書ベースで一時的なAWS認証情報を発行する機能ではありません。']},
  {id:'p407', domain:'security', type:'single', source:SOURCES.guardduty, text:'Amazon GuardDutyの「S3 Protection」機能が検出する脅威として最も適切なものはどれですか？',
    choices:['EC2インスタンスのOS内で動作するマルウェアの有無','Amazon S3バケットに対するデータの不正な持ち出し(exfiltration)や破壊の試みなど、S3特有のセキュリティリスク','Amazon RDSデータベースへの不審なログイン活動','Amazon EKSクラスターのKubernetes監査ログ上の不審な操作'], correct:[1],
    why:['誤り。これはGuardDutyのMalware Protection for EC2の説明です。','正しい。GuardDutyのS3 Protectionは、CloudTrailのS3データイベント等を分析し、S3バケットに対するデータの不正な持ち出しや破壊の試みなど、S3特有のセキュリティリスクを検出する機能です。','誤り。これはGuardDutyのRDS Protectionの説明です。','誤り。これはGuardDutyのEKS Protection(EKS Audit Log Monitoring)の説明です。']},
  {id:'p408', domain:'security', type:'single', source:SOURCES.kms, text:'AWS KMSのカスタマーマネージドキー（対称暗号化キー）の自動ローテーションに関する説明として正しいものはどれですか？',
    choices:['カスタマーマネージドキーは作成時から自動ローテーションが常に有効になっており、無効化することはできない','AWSマネージドキーには自動ローテーション機能が提供されておらず、利用者が手動でローテーションする必要がある','カスタマーマネージドキーの自動ローテーションは利用者が任意で有効化するオプション機能（既定では約365日ごと）であり、一方AWSマネージドキーは無効化できない自動ローテーションが約1年ごとに行われる','ローテーションを行うと、既存の暗号化済みデータはすべて新しい鍵で再暗号化される'], correct:[2],
    why:['誤り。カスタマーマネージドキーの自動ローテーションは既定では無効で、利用者が有効化するオプション機能です。','誤り。AWSマネージドキーは利用者が有効・無効を切り替えることはできませんが、AWSによって自動的に約1年ごとにローテーションされます。','正しい。カスタマーマネージドキーの自動ローテーションは利用者が任意で有効化するオプション機能で、既定のローテーション期間は約365日です。一方AWSマネージドキーは、利用者が無効化できない自動ローテーションが約1年ごとに行われます。','誤り。ローテーションされるのは鍵マテリアル自体であり、既存の暗号化済みデータの再暗号化は行われません（復号時には暗号化時に使われた鍵マテリアルが自動的に使用されます）。']},
  {id:'p409', domain:'security', type:'multi', source:SOURCES.rolesAnywhere, text:'AWS IAM Roles Anywhereの特徴として正しいものを2つ選択してください。',
    choices:['AWS外部のワークロードが、信頼された認証局(CA)の発行したX.509証明書を使って認証し、IAMロールの一時的なセキュリティ認証情報を取得できる','オンプレミスの認証局(CA)自体の構築・運用を代替するサービスである','信頼を確立するための「トラストアンカー」として、AWS Private CAまたは外部のCA証明書を登録できる','IAMユーザーのパスワードポリシーを強制するサービスである'], correct:[0,2],
    why:['正しい。AWS IAM Roles Anywhereは、信頼された認証局(CA)が発行したX.509証明書を使って認証し、ワークロードがIAMロールを引き受けて一時的なセキュリティ認証情報を取得できるようにします。','誤り。Roles Anywhereは既存のCA(AWS Private CAまたは外部のCA)と連携する側であり、CA自体の構築・運用を代替するサービスではありません。','正しい。Roles Anywhereでは、AWS Private CAまたは外部のCA証明書を「トラストアンカー」として登録し、Roles AnywhereとPKIの間の信頼を確立します。','誤り。これはIAMのパスワードポリシー機能の説明であり、Roles Anywhereの役割ではありません。']},
  {id:'p410', domain:'tech', type:'single', source:SOURCES.bedrock, text:'複数のAIプロバイダーが提供する基盤モデル(Foundation Model)を比較・選択し、単一のAPIを通じて生成AIアプリケーションに組み込みたい。モデルをホストするインフラを自前で構築・管理したくない場合、最も適したサービスはどれですか？',
    choices:['Amazon SageMaker','Amazon Rekognition','Amazon Comprehend','Amazon Bedrock'], correct:[3],
    why:['誤り。Amazon SageMakerは自前の機械学習モデルを構築・学習・デプロイするためのフルマネージドサービスで、複数プロバイダーの基盤モデルへの単一API経由のアクセスを主目的とするサービスではありません。','誤り。Amazon Rekognitionは画像・動画解析に特化したサービスです。','誤り。Amazon Comprehendは自然言語処理(NLP)に特化したサービスです。','正しい。Amazon Bedrockは、Anthropic・Meta・Amazonなど複数のAIプロバイダーの基盤モデルに単一のAPIからアクセスできるフルマネージドサービスで、モデルをホストするインフラの構築・管理は不要です。']},
  {id:'p411', domain:'tech', type:'single', source:SOURCES.sagemaker, text:'自社独自のデータを使って機械学習モデルを構築・学習・デプロイしたいが、学習用インフラの構築・管理やスケーリングの運用負荷は避けたい場合、最も適したサービスはどれですか？',
    choices:['Amazon SageMaker','Amazon Bedrock','AWS Glue','Amazon Comprehend'], correct:[0],
    why:['正しい。Amazon SageMakerは、機械学習モデルの構築・学習・デプロイのためのフルマネージドサービスで、学習用インフラの構築・管理やスケーリングをAWSに任せられます。','誤り。Amazon Bedrockは既存の基盤モデルをAPI経由で利用するサービスであり、独自データでのモデルの学習・構築を主目的とするサービスではありません。','誤り。AWS GlueはデータのETL(抽出・変換・ロード)に特化したサービスです。','誤り。Amazon Comprehendは学習済みの自然言語処理モデルを提供するサービスで、独自モデルの学習を主目的とするものではありません。']},
  {id:'p412', domain:'tech', type:'single', source:SOURCES.appsync, text:'モバイルアプリから複数のデータソース(データベースやAPI等)に単一のエンドポイントでアクセスし、データ更新時にクライアントへリアルタイムに通知(Pub/Sub)も行いたい場合、最も適したサービスはどれですか？',
    choices:['Amazon API Gateway','AWS AppSync','Amazon EventBridge','Amazon SQS'], correct:[1],
    why:['誤り。Amazon API Gatewayは主にRESTful/HTTP/WebSocket APIの作成・公開・保護に特化したサービスです。','正しい。AWS AppSyncは、GraphQLおよびPub/Sub APIを通じて複数のデータソースに単一のエンドポイントからアクセスし、リアルタイムの更新配信も行えるフルマネージドのサーバーレスサービスです。','誤り。Amazon EventBridgeはイベント駆動のルーティングサービスであり、クライアントへのリアルタイムなPub/Sub配信を主目的とするAPIサービスではありません。','誤り。Amazon SQSはメッセージキューイングサービスであり、クライアントへのリアルタイム配信を主目的とするAPIサービスではありません。']},
  {id:'p413', domain:'tech', type:'single', source:SOURCES.storageLens, text:'組織全体で複数のAWSアカウント・リージョンにまたがるAmazon S3の利用状況を可視化し、ライフサイクルルールの設定漏れなどコスト最適化やデータ保護のベストプラクティスに関する推奨事項を確認したい場合、最も適した機能はどれですか？',
    choices:['AWS Trusted Advisor','AWS Cost Explorer','Amazon S3 Storage Lens','Amazon CloudWatch'], correct:[2],
    why:['誤り。AWS Trusted Advisorはアカウント全体のベストプラクティスチェックを行いますが、S3の利用状況に特化した詳細な可視化は行いません。','誤り。AWS Cost Explorerはコストと使用量の分析に特化したサービスで、S3のライフサイクル設定状況など保護ベストプラクティスの可視化は主目的ではありません。','正しい。Amazon S3 Storage Lensは、組織全体のS3ストレージの利用状況・アクティビティを可視化し、ライフサイクルルールの設定漏れなどコスト最適化やデータ保護のベストプラクティスに関する推奨事項を確認できる分析機能です。','誤り。Amazon CloudWatchは汎用的な監視サービスであり、S3ストレージ特有のベストプラクティス推奨機能は主目的ではありません。']},
  {id:'p414', domain:'billing', type:'single', source:SOURCES.dataExports, text:'コストと使用量のデータを、必要な列や行だけに絞り込んでSQLでカスタマイズしながら、業界標準のFOCUS形式を含む複数の形式でAmazon S3へ定期的に自動エクスポートしたい場合、最も適したサービスはどれですか？',
    choices:['AWS Budgets','AWS Cost Categories','AWS Cost Anomaly Detection','AWS Data Exports'], correct:[3],
    why:['誤り。AWS Budgetsは予算のしきい値超過を通知するサービスであり、データのカスタムエクスポート機能ではありません。','誤り。AWS Cost Categoriesは請求ディメンションに基づいてコストを分類する機能であり、データのエクスポート自体を主目的とするものではありません。','誤り。AWS Cost Anomaly Detectionは異常なコストの急増を検知する機能です。','正しい。AWS Data Exportsは、コスト・使用量データを、SQLによる列・行の選択でカスタマイズしながら、業界標準のFOCUS形式などの形式でAmazon S3へ定期的にエクスポートできるサービスです。']},
  {id:'p415', domain:'tech', type:'single', source:SOURCES.personalize, text:'ECサイトでユーザーごとの行動データ（クリック履歴・購買履歴等）に基づいた商品レコメンデーション機能を実装したいが、機械学習モデルの構築・学習の専門知識は社内にない。最も適したサービスはどれですか？',
    choices:['ユーザーの行動データに基づいて、機械学習の専門知識なしに個別の商品レコメンデーションやユーザーセグメントの生成をアプリに組み込めるフルマネージド型サービス','テキストデータから感情分析やエンティティ抽出を行うサービス','ビジネスインテリジェンス向けのダッシュボードを作成するサービス','画像・動画からオブジェクトや顔を検出するサービス'], correct:[0],
    why:['正しい。Amazon Personalizeは、ユーザーの行動データに基づいて、機械学習の専門知識なしに商品・コンテンツの個別レコメンデーションやユーザーセグメントの生成をアプリに組み込めるフルマネージド型の機械学習サービスです。','これはAmazon Comprehendの説明です。','これはAmazon QuickSightの説明です。','これはAmazon Rekognitionの説明です。']},
  {id:'p416', domain:'tech', type:'single', source:SOURCES.appconfig, text:'本番環境で稼働中のアプリケーションに対して、コードの再デプロイを行わずに、機能フラグ(フィーチャーフラグ)の有効化・無効化や設定値の変更を対象ユーザーを絞って段階的に展開し、問題発生時には即座に変更をロールバックしたい場合、最も適したサービスはどれですか？',
    choices:['AWS CloudFormation','AWS AppConfig','AWS Systems Manager Parameter Store','AWS CodeDeploy'], correct:[1],
    why:['誤り。AWS CloudFormationはテンプレートに基づいてAWSリソースをプロビジョニングするIaCサービスであり、機能フラグの段階的展開を主目的とするものではありません。','正しい。AWS AppConfigは、機能フラグや動的な設定データを使い、コードの再デプロイなしに本番環境でのアプリケーションの挙動を安全に変更できるサービスで、対象ユーザーを絞った段階的な展開や、CloudWatchアラームと連携した自動ロールバックにも対応します。','誤り。Parameter Storeは設定値・シークレットの保管に使われますが、段階的な展開や自動ロールバックなどAppConfig特有の機能は備えていません。','誤り。AWS CodeDeployはアプリケーションのデプロイ(配置)を自動化するサービスであり、実行中のアプリケーションの設定値を動的に変更する機能フラグの仕組みではありません。']},
  {id:'p417', domain:'tech', type:'multi', source:SOURCES.mwaa, text:'Apache Airflowを使ったデータパイプライン(ワークフロー)を、Airflowのスケジューラーやワーカーなどの基盤を自前で構築・運用せずに実行したい場合に当てはまる、Amazon Managed Workflows for Apache Airflow (MWAA)の特徴として正しいものを2つ選択してください。',
    choices:['オープンソースのApache Airflowと同じユーザーインターフェース・コードをそのまま利用できる','ワークフローの定義には、Airflow独自の構文ではなくAWS CloudFormationテンプレートを使用する','設定した最小・最大値の範囲内で、ワーカー(実行環境)の数を需要に応じて自動的にスケーリングする','ワークフローの実行はAWS Lambda上でのみ行われ、コンテナ環境では実行できない'], correct:[0,2],
    why:['正しい。Amazon MWAAは、オープンソースのApache Airflowと同じユーザーインターフェース・コードをそのまま利用できるマネージドサービスです。','誤り。MWAAのワークフローはPythonで書かれたApache AirflowのDAG(Directed Acyclic Graph)として定義し、CloudFormationテンプレートではありません。','正しい。Amazon MWAAは、設定した最小・最大のワーカー数の範囲内で、ワークロードの需要に応じてワーカーを自動的にスケーリングします。','誤り。MWAAのスケジューラー・ワーカーはAWS Fargate上のコンテナとして稼働します。']},
  {id:'p418', domain:'tech', type:'single', source:SOURCES.storagegateway, text:'オンプレミスのアプリケーションサーバーから、iSCSIプロトコルを使ってブロックストレージとしてマウントし、よく使うデータをオンプレミス側にキャッシュしつつ、データ自体はAmazon S3にバックアップされる形で保存したい場合、AWS Storage Gatewayのどのタイプが適していますか？',
    choices:['File Gateway','Tape Gateway','Volume Gateway（キャッシュ型ボリューム）','AWS DataSync'], correct:[2],
    why:['誤り。File Gatewayは、NFSやSMBといったファイルプロトコルでS3にアクセスするためのタイプです。','誤り。Tape Gatewayは、既存のテープバックアップの仕組みを仮想テープライブラリ(VTL)としてクラウド上の低コストストレージに置き換えるタイプです。','正しい。Volume Gateway（キャッシュ型ボリューム）は、iSCSIプロトコルでブロックストレージとしてマウントできるタイプで、よく使うデータをオンプレミス側にキャッシュしながら、データ自体はAmazon S3に非同期にバックアップ・保存されます。','誤り。AWS DataSyncは、オンプレミスとAWSストレージ間でのデータ転送・同期に特化したサービスで、iSCSIによるブロックストレージのマウントは提供しません。']},
  {id:'p419', domain:'tech', type:'single', source:SOURCES.cloudformation, text:'同一のAWS CloudFormationテンプレートを、組織内の複数のAWSアカウント・複数のリージョンに対して一括でデプロイ・更新したい場合、最も適した機能はどれですか？',
    choices:['ネストされたスタック(Nested Stacks)','変更セット(Change Sets)','AWS Service Catalog','CloudFormation StackSets'], correct:[3],
    why:['誤り。ネストされたスタックは、1つのスタック内で他のスタックのテンプレートを再利用する仕組みであり、複数アカウント・リージョンへの一括展開を主目的とするものではありません。','誤り。変更セットは、スタックを更新する前に変更内容を事前に確認するための機能です。','誤り。AWS Service Catalogは、承認済みのITサービス(CloudFormationテンプレート等)をカタログ化してユーザーにセルフサービスで提供する仕組みであり、複数アカウント・リージョンへの一括展開自体を実現する機能ではありません。','正しい。CloudFormation StackSetsを使うと、1つの操作で、組織内の複数のAWSアカウント・複数のリージョンに対して同一のテンプレートに基づくスタックを作成・更新・削除できます。']},
  {id:'p420', domain:'security', type:'single', source:SOURCES.wafSecurity, text:'AWS Well-Architected Frameworkの「セキュリティの柱」の設計原則の一つ「保管中および転送中のデータを保護する(Protect data in transit and at rest)」が重視する内容として正しいものはどれですか？',
    choices:['データを機密性・重要度に応じて分類し、暗号化・アクセス制御・ライフサイクルポリシーなど適切な保護メカニズムを適用すること','すべての操作ログを記録し、変更をリアルタイムで監査・追跡できるようにすること','単一障害点を避けるために境界・ネットワーク・アプリケーションなど複数のレイヤーで防御を行うこと','手動のセキュリティ対応をイベント駆動型の自動化された仕組みに置き換えること'], correct:[0],
    why:['正しい。「保管中および転送中のデータを保護する」設計原則は、データを機密性・重要度に応じて分類し、暗号化、アクセス制御、適切なライフサイクルポリシーなどの保護メカニズムを適用することを重視します。','これは「トレーサビリティを維持する(Maintain traceability)」の説明です。','これは「セキュリティを全レイヤーに適用する(Apply security at all layers)」の説明です。','これは「セキュリティのベストプラクティスを自動化する(Automate security best practices)」の説明です。']},
  {id:'p421', domain:'security', type:'multi', source:SOURCES.organizations, text:'AWS Organizationsの「委任管理者(delegated administrator)」機能に関する説明として正しいものを2つ選択してください。',
    choices:['委任管理者に登録すると、管理アカウント(management account)自身はそのセキュリティサービスを一切操作できなくなる','GuardDutyやSecurity Hub、Macieなど対応するAWSサービスについて、管理アカウントの認証情報を使わずに、指定したメンバーアカウントから組織全体の設定・管理を行えるようにする','委任管理者に設定できるメンバーアカウントは、組織内に1つだけである','委任管理者の登録はサービスごとに行う必要があり、あるサービスで委任管理者に設定しても、他のサービスには自動的に適用されない'], correct:[1,3],
    why:['誤り。委任管理者を登録しても、管理アカウントが各サービスを管理する能力自体は失われません。','正しい。委任管理者機能を使うと、GuardDutyやSecurity Hub、Macieなど対応するサービスについて、管理アカウントの認証情報を使わずに、指定したメンバーアカウントから組織全体の設定・管理を行えるようになります。','誤り。委任管理者に設定できるメンバーアカウントの数や組み合わせはサービスによって異なり、組織全体で1つだけに制限されるわけではありません。','正しい。委任管理者の登録はサービス単位で行う必要があり、あるサービス(例: GuardDuty)で委任管理者に設定しても、他のサービス(例: Security Hub)には自動的には適用されません。']},
  {id:'p422', domain:'security', type:'single', source:SOURCES.verifiedPermissions, text:'Amazon Verified PermissionsとAWS IAMの役割の違いとして正しいものはどれですか？',
    choices:['IAMは自社アプリケーションのビジネスロジックレベルの認可を扱うのに対し、Verified PermissionsはAWSリソースへのAPIアクセス権限を管理する','IAMはAWSリソース・APIへのアクセス権限を管理するのに対し、Verified Permissionsは自社アプリケーション内の「誰がどのリソースに対してどの操作を許可されるか」という、アプリケーション独自のきめ細かな認可ロジックをCedarポリシー言語で管理する','両方とも同じ機能を提供する完全に代替可能なサービスであり、選択に違いはない','Verified Permissionsは、IAMユーザーやロールの作成・管理そのものを行うサービスである'], correct:[1],
    why:['誤り。説明が逆です。IAMがAWSリソースへのアクセス権限を管理し、Verified Permissionsがアプリケーション独自の認可ロジックを扱います。','正しい。IAMはAWSのリソース・APIへのアクセス権限(誰がどのAWS操作を行えるか)を管理するのに対し、Amazon Verified Permissionsは自社アプリケーション内の「誰がどのリソースに対してどの操作を許可されるか」という、アプリケーション独自のきめ細かな認可(authorization)ロジックをCedarポリシー言語を使って管理します。','誤り。両者は対象レイヤーが異なり、互換的に代替できるものではありません。','誤り。IAMユーザー・ロールの作成・管理はAWS IAMの役割であり、Verified Permissionsの役割ではありません。']},
  {id:'p423', domain:'concepts', type:'single', source:SOURCES.migrationStrategies, text:'ある企業が、オンプレミスのVMware vSphere環境で稼働する多数の仮想マシンを、OSやアプリケーションには手を加えず、VMware HCX等を使ってハイパーバイザーレベルでほぼそのままクラウドへ移行し、既存のVMware運用ツール・スキルを引き続き活用したいと考えている。この移行戦略は次のうちどれですか？',
    choices:['Rehost（リホスト）','Replatform（リプラットフォーム）','Relocate（リロケート）','Repurchase（リパーチェス）'], correct:[2],
    why:['誤り。Rehostは、仮想マシンをAmazon EC2上に移行する「リフト&シフト」であり、VMware vSphere環境自体は維持しません。','誤り。Replatformは、コードの大幅な変更なしに一部の基盤をマネージドサービスに置き換える戦略です。','正しい。Relocateは、VMware Cloud on AWSなどを利用し、OSやアプリケーションに手を加えず、ハイパーバイザー(VMware vSphere)のレベルでほぼそのまま仮想マシンをクラウドへ移行し、既存のVMware運用ツール・スキルを継続して活用できる移行戦略です。','誤り。Repurchaseは、既存のアプリケーションを別のSaaS製品などに置き換える戦略です。']},
  {id:'p424', domain:'concepts', type:'single', source:SOURCES.wafOps, text:'AWS Well-Architected Frameworkの「運用上の優秀性の柱」の設計原則の一つ「頻繁に、小規模かつ可逆的な変更を行う(Make frequent, small, reversible changes)」が重視する内容として正しいものはどれですか？',
    choices:['すべての運用上の失敗を記録し、原因分析を行って再発防止策を導入すること','予期しない障害が発生する可能性を前提に、事前に障害を想定した対策を講じること','運用手順を定期的に見直し、改善の機会を特定すること','システムをいつでも安全に元の状態に戻せるように、変更を小さい単位に分割して頻繁に反映することで、問題発生時の影響とロールバックの手間を最小限にすること'], correct:[3],
    why:['これは「すべての運用上の失敗から学ぶ(Learn from all of your operational failures)」の説明です。','これは「障害を予測する(Anticipate failure)」の説明です。','これは「運用手順を定期的に改善する(Refine operations procedures frequently)」の説明です。','正しい。「頻繁に、小規模かつ可逆的な変更を行う」は、変更を小さい単位に分割して頻繁に反映することで、変更が失敗した場合の影響を抑え、容易かつ安全に元の状態へロールバックできるようにすることを重視します。']},
  {id:'p425', domain:'concepts', type:'single', source:SOURCES.wafCost, text:'AWS Well-Architected Frameworkの「コスト最適化の柱」の設計原則の一つ「差別化につながらない重い作業にお金を使わない(Stop spending money on undifferentiated heavy lifting)」が重視する内容として正しいものはどれですか？',
    choices:['データセンターの運用やハードウェア・OSの保守など、自社の競争優位性に直結しない作業はAWSのマネージドサービスに任せ、自社は差別化につながる開発に集中すること','クラウドの利用量を事前にコミットすることで割引を受けること','コストと使用量のデータを部門やプロジェクト単位で分類・集計すること','リソースの使用率を継続的に監視し、無駄なリソースを特定すること'], correct:[0],
    why:['正しい。「差別化につながらない重い作業にお金を使わない」は、データセンターの運用やハードウェア・OSの保守など、自社の競争優位性に直結しない重労働な作業はAWSのマネージドサービスに任せ、自社のリソースは差別化につながる開発に集中させることを重視する設計原則です。','これはリザーブドインスタンスやSavings Plansなど「コミットメントに基づく割引」の説明であり、この設計原則の主旨とは異なります。','これはコスト配分タグやAWS Cost Categoriesの説明です。','これは「費用の分析と帰属」等、使用率の可視化に関する内容です。']},
  {id:'p426', domain:'billing', type:'single', source:SOURCES.costExplorer, text:'現在稼働しているEC2インスタンス群の実際の使用率(CPU・メモリ等)を分析し、過剰にプロビジョニングされているインスタンスについて、よりコスト効率の良いインスタンスタイプやサイズへの変更(ライトサイジング)を推奨してほしい。AWS Cost Explorerのどの機能を使うのが適切ですか？',
    choices:['予算のしきい値アラート機能','ライトサイジングの推奨(Rightsizing Recommendations)機能','リザーブドインスタンス購入の推奨機能','カスタムレポートの保存機能'], correct:[1],
    why:['誤り。予算のしきい値アラートは、コストや使用量が設定した予算に近づいた際に通知する機能であり、インスタンスサイズの推奨は行いません。','正しい。AWS Cost Explorerの「ライトサイジングの推奨」機能は、EC2インスタンスの実際の使用率データを分析し、過剰にプロビジョニングされているインスタンスについて、よりコスト効率の良いインスタンスタイプやサイズへの変更を推奨します。','誤り。これは、将来のEC2利用実績に基づいてリザーブドインスタンスやSavings Plansの購入量を推奨する別の機能です。','誤り。カスタムレポートの保存機能は、コスト分析のレポートを再利用可能な形で保存する機能であり、インスタンスサイズの推奨機能ではありません。']},
  {id:'p427', domain:'billing', type:'single', source:SOURCES.costAnomalyDetection, text:'AWS Cost Anomaly Detectionが異常なコストの急増を検知した際、その原因となった要素(どのAWSサービス・アカウント・リージョン・使用タイプが主にコスト増加に影響したか)を分析した情報を、アラートの一部として確認したい場合、どの機能を使用しますか？',
    choices:['AWS Budgetsのしきい値アラート','AWS Cost Categoriesによる分類','Cost Anomaly Detectionの根本原因分析(Root Cause Analysis)','AWS Trusted Advisorのコスト最適化チェック'], correct:[2],
    why:['誤り。AWS Budgetsは、事前に設定した固定のしきい値を超えた場合にアラートを送る機能であり、異常の原因分析機能ではありません。','誤り。AWS Cost Categoriesは、コストをルールに基づいて分類する機能であり、異常検知やその原因分析を行う機能ではありません。','正しい。AWS Cost Anomaly Detectionは、検知した異常なコストの急増について、どのAWSサービス・アカウント・リージョン・使用タイプが主な要因かを分析した根本原因(Root Cause Analysis)の情報をアラートとともに提示します。','誤り。AWS Trusted Advisorのコスト最適化チェックは、一般的なコスト最適化のベストプラクティスを確認するものであり、個別の異常コストの根本原因分析機能ではありません。']},
  {id:'p428', domain:'concepts', type:'single', source:SOURCES.s3, text:'企業が「このサービスに保存したデータが絶対に失われてはならない」という要件と、「システムが常に利用可能でなければならない」という要件をそれぞれ別の指標で評価したいと考えている。データの損失・破損のしにくさを表す指標と、システムが利用可能である時間の割合を表す指標の組み合わせとして正しいものはどれですか？',
    choices:['Durability(耐久性)とAvailability(可用性)','Elasticity(弾力性)とScalability(スケーラビリティ)','Reliability(信頼性)とFault Tolerance(耐障害性)','RPO(目標復旧時点)とRTO(目標復旧時間)'], correct:[0],
    why:['正しい。データの損失・破損のしにくさを表す指標がDurability(耐久性)、システムが必要なときに正しく動作し利用可能である時間の割合を表す指標がAvailability(可用性)です。例えばAmazon S3標準ストレージクラスは99.999999999%の耐久性と99.99%の可用性を別々の数値で示しています。','誤り。Elasticity(弾力性)は需要に応じてリソースを増減できる能力、Scalability(スケーラビリティ)は需要の増加に対応してリソースを拡張できる能力を指し、いずれもデータの損失防止や稼働時間そのものの指標ではありません。','誤り。Reliability(信頼性)は障害から回復し期待どおりに機能し続ける能力、Fault Tolerance(耐障害性)はコンポーネントの一部が故障しても全体として機能し続ける能力を指し、データ保全性や稼働時間そのものを表す指標ではありません。','誤り。RPO/RTOはディザスタリカバリにおける許容データ損失量/復旧時間の目標値であり、サービスそのものの耐久性・可用性を表す一般的な指標ではありません。']},
  {id:'p429', domain:'concepts', type:'single', source:SOURCES.waf, text:'あるチームが新しいワークロードを設計するにあたり、AWS Well-Architected Frameworkを活用したいと考えている。このフレームワークを活用する目的として最も適切なものはどれですか？',
    choices:['AWSサポートへの問い合わせ回数を減らすため','運用上の優秀性・セキュリティ・信頼性・パフォーマンス効率・コスト最適化・持続可能性の6つの柱に基づくベストプラクティスに沿って設計をレビューし、潜在的なリスクや改善点を把握するため','AWS利用料金の請求を一つのアカウントに統合するため','オンプレミスのサーバーをAWSへ移行する際の手順を自動生成するため'], correct:[1],
    why:['誤り。AWS Well-Architected Frameworkはサポート問い合わせの削減を直接の目的とするものではありません。','正しい。AWS Well-Architected Frameworkは、6つの柱に基づくベストプラクティスに沿ってワークロードの設計をレビューし、潜在的なリスクや改善点を把握するための指針です。AWS Well-Architected Toolを使えば、このレビューをAWSマネジメントコンソール上で実施し、改善のマイルストーンを記録できます。','誤り。これはAWS Organizationsの一括支払い(Consolidated Billing)の目的です。','誤り。これは移行計画ツール(例: AWS Migration Evaluator、AWS Application Migration Service等)の役割です。']},
  {id:'p430', domain:'concepts', type:'multi', source:SOURCES.tco, text:'企業がオンプレミスのデータセンターとAWSクラウドのTotal Cost of Ownership(TCO、総所有コスト)を比較する際、クラウド側で考慮すべき要素として適切なものを2つ選択してください。',
    choices:['実際に使用した分だけ発生する従量課金のコンピューティング・ストレージ費用','データセンターの建設費や冷却設備などの固定資産にかかる先行投資(CapEx)','サーバーの物理的な保守・交換や電源・冷却の運用にかかる人件費・設備費が不要になることによるコスト削減','複数のオンプレミスデータセンター間でハードウェアを均等に配置するための運搬費'], correct:[0,2],
    why:['正しい。クラウドでは、実際に使用したコンピューティング・ストレージ等のリソースに対してのみ従量課金で費用が発生するため、TCO比較の際に考慮すべき要素です。','誤り。データセンターの建設費等の先行投資(CapEx)は、オンプレミス側のTCOで考慮すべき要素であり、クラウド移行によって削減される側のコストです。','正しい。クラウドに移行することで、サーバーの物理的な保守・交換や電源・冷却設備の運用など、ビジネスの差別化につながらない重い作業(undifferentiated heavy lifting)にかかる人件費・設備費が不要になり、TCOの削減要素となります。','誤り。これはTCO比較において一般的に考慮される要素ではありません。']},
  {id:'p431', domain:'concepts', type:'single', source:SOURCES.wafPerformance, text:'アクセス数が時間帯によって大きく変動するWebアプリケーションに対して、需要の増減に応じてサーバー台数を自動的に増減させる設計方針(水平スケーリング)が、単一のサーバーの性能を強化する設計方針(垂直スケーリング)よりも適している理由として最も適切なものはどれですか？',
    choices:['垂直スケーリングは常にコストが高くなるため','水平スケーリングはデータの耐久性を直接的に高めるため','垂直スケーリングにはインスタンスタイプごとに上限があり単一障害点になりやすいのに対し、水平スケーリングは需要に応じて台数を増減させることで単一障害点を避けながら、より細かくリソースをコストに見合う形で調整できるため','水平スケーリングはダウンタイムなしでは実施できないため'], correct:[2],
    why:['誤り。垂直スケーリングのコストはインスタンスタイプやワークロードに依存し、一概に常に水平スケーリングより高いとは言えません。','誤り。スケーリングの方式はデータの耐久性(Durability)を直接的に高めるものではありません。','正しい。垂直スケーリングは1台のインスタンスの性能強化であるため、インスタンスタイプごとの上限に達すると単一障害点になりやすい一方、水平スケーリングは需要に応じて台数を増減させることで単一障害点を避けつつ、よりきめ細かく需要とコストのバランスを取ることができます。','誤り。水平スケーリングは新しいインスタンスを追加・削除する方式であり、既存インスタンスを停止する垂直スケーリングのサイズ変更と異なり、通常ダウンタイムを伴わずに実施できます。']},
  {id:'p432', domain:'security', type:'single', source:SOURCES.nitroSystem, text:'金融業界の顧客が、EC2インスタンス上で稼働するワークロードについて「AWSの運用担当者(Amazonの従業員を含む)がインスタンスの内部にアクセスできない」という保証を求めている。この要件を満たす基盤技術として最も適切なものはどれですか？',
    choices:['AWS CloudHSM','Amazon GuardDuty','AWS Key Management Service(KMS)','AWS Nitro System(Nitro Hypervisor・Nitro Security Chipによるインスタンスの分離)'], correct:[3],
    why:['誤り。AWS CloudHSMは暗号鍵を保護する専用ハードウェアモジュールであり、EC2インスタンス自体への運用者アクセスを排除する技術ではありません。','誤り。Amazon GuardDutyは脅威検出サービスであり、インスタンスへのアクセスを構造的に排除する基盤技術ではありません。','誤り。AWS KMSは暗号鍵の作成・管理サービスであり、インスタンスへのアクセス排除を保証する技術ではありません。','正しい。AWS Nitro Systemは、Nitro Hypervisor・Nitro Security Chipなどの専用ハードウェア・ソフトウェアによってインスタンスを分離し、Amazonの従業員を含むいかなる運用者もインスタンスの内部にアクセスできないように設計されています。']},
  {id:'p433', domain:'security', type:'single', source:SOURCES.controlTower, text:'複数のAWSアカウントを新規に展開する際、セキュリティ・コンプライアンスのベストプラクティスに沿ったガードレール(必須の設定ルール)を自動的に適用した状態で、一貫性のあるマルチアカウント環境(ランディングゾーン)を素早く構築したい場合、最も適したサービスはどれですか？',
    choices:['AWS Control Tower','AWS Organizations単体','AWS IAM Identity Center単体','AWS Service Catalog'], correct:[0],
    why:['正しい。AWS Control Towerは、AWS Organizationsをベースに、セキュリティ・コンプライアンスのベストプラクティスに沿ったガードレールを自動的に適用した、一貫性のあるマルチアカウント環境(ランディングゾーン)を素早く構築・運用するためのサービスです。','誤り。AWS Organizations単体では複数アカウントのグループ化や一括請求、SCPの適用は可能ですが、ガードレールの自動適用やランディングゾーンのセットアップ機能は提供していません(Control Towerが内部でOrganizationsを利用しています)。','誤り。AWS IAM Identity Centerは複数アカウントへのシングルサインオン(SSO)アクセスを提供するサービスであり、ランディングゾーンそのものを構築する機能ではありません。','誤り。AWS Service Catalogは、承認済みのITサービス(製品)のカタログを作成・管理するサービスであり、マルチアカウント環境のガードレール設定を目的とするものではありません。']},
  {id:'p434', domain:'security', type:'single', source:SOURCES.compliancePrograms, text:'ある企業が、利用中のAWSサービスがPCI DSSやISO 27001など、自社が従う必要のある特定のコンプライアンスプログラム・規格の対象になっているかどうかを確認したい。AWSが提供するどの情報を参照するのが最も適切ですか？',
    choices:['AWS Trusted Advisorのセキュリティチェック結果','AWSコンプライアンスプログラムのページで、AWSが準拠している規格・フレームワークの一覧と対象サービスを確認する','Amazon GuardDutyの検出結果','AWS Personal Health Dashboard'], correct:[1],
    why:['誤り。AWS Trusted Advisorはアカウント固有のリソース設定に関するチェックを行うツールであり、AWS全体がどの規格に準拠しているかを示すものではありません。','正しい。AWSコンプライアンスプログラムのページでは、AWSがPCI DSSやISO 27001をはじめとする各種規格・法規制にどのように準拠しているか、またどのサービスが対象範囲に含まれるかが整理されています(具体的な認証書・報告書自体はAWS Artifactから入手します)。','誤り。Amazon GuardDutyは脅威検出サービスであり、コンプライアンス規格への準拠状況を示すものではありません。','誤り。AWS Personal Health Dashboardはアカウントに影響するAWSの運用イベントを通知するものであり、コンプライアンス情報を提供するものではありません。']},
  {id:'p435', domain:'security', type:'single', source:SOURCES.directoryService, text:'新規に作成するAWS環境で、既存のオンプレミスのActive Directoryとは独立した、クラウド上で完結する本格的なMicrosoft Active Directoryをマネージド型で利用したい場合、AWS Directory Serviceのどの機能が最も適切ですか？',
    choices:['AD Connector(オンプレミスADへのプロキシ)','Simple AD','AWS Managed Microsoft AD','Amazon Cognitoユーザープール'], correct:[2],
    why:['誤り。AD Connectorは既存のオンプレミスのActive Directoryへのリクエストをプロキシする仕組みであり、オンプレミスADとは独立したクラウド上のADを提供するものではありません。','誤り。Simple ADはSambaベースの簡易的なディレクトリで、一部の機能(信頼関係など)がAWS Managed Microsoft ADより限定されます。本格的なMicrosoft Active Directoryの機能が必要な場合には適しません。','正しい。AWS Managed Microsoft ADは、AWS上で実際のMicrosoft Active Directoryをマネージド型で稼働させる機能で、オンプレミスのADとは独立してクラウド上で本格的なAD機能を利用できます。','誤り。Amazon Cognitoユーザープールは、Webアプリ・モバイルアプリ向けの認証機能を提供するものであり、Active Directoryの機能を提供するものではありません。']},
  {id:'p436', domain:'tech', type:'single', source:SOURCES.cloudformation, text:'インフラのプロビジョニングを手作業のコンソール操作ではなく、テンプレートファイルに定義してコードとして管理・再現できるようにしたい(Infrastructure as Code)。この目的に最も適したAWSサービスはどれですか？',
    choices:['AWS Systems Manager','AWS Config','AWS CodeDeploy','AWS CloudFormation'], correct:[3],
    why:['誤り。AWS Systems Managerは、運用管理やパッチ適用などの運用タスクを行うサービスであり、インフラ構成全体をテンプレートで定義・構築するIaCサービスではありません。','誤り。AWS Configは既存リソースの設定変更を記録・評価するサービスであり、インフラをコードとしてプロビジョニングするサービスではありません。','誤り。AWS CodeDeployはアプリケーションのコードを既存のコンピューティング環境へ配置(デプロイ)するサービスであり、インフラそのものを定義するサービスではありません。','正しい。AWS CloudFormationは、テンプレートファイル(JSON/YAML)でAWSリソースの構成を定義し、コードとして管理・再現できるようにするInfrastructure as Code(IaC)サービスです。']},
  {id:'p437', domain:'tech', type:'single', source:SOURCES.amplify, text:'React・Next.jsで構築したフロントエンドと、Gitリポジトリ連携による継続的デプロイ(CI/CD)を使って、Webアプリケーションを素早くホスティングしたい。この用途に最も適したサービスはどれですか？',
    choices:['AWS Amplify Hosting','AWS Elastic Beanstalk','Amazon Lightsail','AWS CodeDeploy'], correct:[0],
    why:['正しい。AWS Amplify Hostingは、Gitリポジトリと連携した継続的デプロイ(CI/CD)により、React・Next.js等のフレームワークで構築したフルスタックのWebアプリケーションをAWSのグローバルCDN上に簡単にホスティングできるサービスです。','誤り。AWS Elastic Beanstalkは、EC2やRDSなどのインフラを含めてWebアプリケーション環境を管理するサービスで、Amplifyのようなフロントエンド特化のGit連携ホスティング機能は主目的ではありません。','誤り。Amazon Lightsailは、仮想サーバー・ストレージ・ネットワークをシンプルな料金体系でまとめて提供するサービスであり、フレームワーク特化のCI/CDホスティングを主目的とするものではありません。','誤り。AWS CodeDeployはアプリケーションのデプロイを自動化するサービスであり、単体でWebホスティング環境を提供するものではありません。']},
  {id:'p438', domain:'tech', type:'single', source:SOURCES.fsx, text:'Windows Server上で稼働する既存のアプリケーションから、SMBプロトコルでアクセスできるマネージド型のファイルストレージを、Active Directory統合やNTFSのアクセス制御を保持したまま利用したい場合、最も適したサービスはどれですか？',
    choices:['Amazon EFS','Amazon FSx for Windows File Server','Amazon S3','Amazon EBS'], correct:[1],
    why:['誤り。Amazon EFSはLinuxベースのNFSプロトコルに対応したマネージド型ファイルストレージであり、Windows環境のSMBプロトコルやActive Directory統合には対応していません。','正しい。Amazon FSx for Windows File Serverは、SMBプロトコルでアクセスでき、Active Directory統合やNTFSのアクセス制御、Windowsのネイティブなファイルシステム機能を保持したマネージド型ファイルストレージです。','誤り。Amazon S3はオブジェクトストレージであり、SMBプロトコルでのファイル共有やNTFSアクセス制御を提供するものではありません。','誤り。Amazon EBSはEC2インスタンスにアタッチするブロックストレージであり、複数クライアントからのSMB共有を目的とするものではありません。']},
  {id:'p439', domain:'tech', type:'multi', source:SOURCES.sns, text:'1つのイベント(注文確定など)の発生を、画像処理用のSQSキュー、通知メール送信用のLambda関数、分析用のデータベース書き込み処理など、複数の独立したサブスクライバーに同時に配信したい(ファンアウトパターン)。この実現に必要なAWSサービスの組み合わせとして適切なものを2つ選択してください。',
    choices:['Amazon SQS単体のみを使い、複数のサブスクライバーに同じキューを共有させる','Amazon SNSでトピックにメッセージを発行(パブリッシュ)する','AWS Step Functionsで状態遷移を順番に実行する','SNSトピックに対して、SQSキューやLambda関数など複数の異なるサブスクライバーをサブスクライブ(登録)する'], correct:[1,3],
    why:['誤り。Amazon SQSのキューは基本的に1つのメッセージが1つのコンシューマーによって処理される設計であり、単体のキュー共有では複数の独立したサブスクライバーへの同時配信(ファンアウト)を実現しにくいです。','正しい。Amazon SNSのパブリッシュ/サブスクライブモデルを使い、トピックにメッセージを発行することで、ファンアウトパターンの配信を開始できます。','誤り。AWS Step Functionsはワークフローの状態遷移を順序立てて実行するサービスであり、1つのイベントを複数の独立したサブスクライバーに同時配信するファンアウトパターンの主目的には使われません。','正しい。SNSトピックに対してSQSキューやLambda関数など複数の異なるサブスクライバーをサブスクライブすることで、1つのメッセージを各サブスクライバーに同時配信するファンアウトパターンを実現できます。']},
  {id:'p440', domain:'billing', type:'single', source:SOURCES.dataExports, text:'請求・使用量データを、Parquet形式などの構造化された形で定期的にAmazon S3へ出力し、Amazon AthenaやAmazon QuickSightなど任意の分析ツールと柔軟に連携させたい場合、最も適したサービスはどれですか？',
    choices:['AWS Budgets','AWS Cost Explorer','AWS Data Exports','AWS Cost Anomaly Detection'], correct:[2],
    why:['誤り。AWS Budgetsは予算のしきい値を監視してアラートを送信するサービスであり、分析用にデータをS3へ出力する機能を主目的とするものではありません。','誤り。AWS Cost Explorerはコンソール上でコストデータを可視化・分析するサービスであり、Parquet形式でのS3への定期出力を主目的とするものではありません。','正しい。AWS Data Exportsは、請求・使用量データ(標準データスキーマ)をParquetやCSV等の形式で定期的にS3に出力し、Amazon AthenaやAmazon QuickSightなど任意の分析ツールと柔軟に連携できるようにするサービスです。','誤り。AWS Cost Anomaly Detectionは機械学習でコストの異常な急増を検知するサービスであり、分析用データのS3への定期出力を主目的とするものではありません。']},
  {id:'p441', domain:'tech', type:'single', source:SOURCES.memorydb, text:'マイクロサービスアーキテクチャにおいて、マイクロ秒単位の読み取りレイテンシーを実現しつつ、キャッシュとしてだけでなくデータそのものを永続的に保存するプライマリデータベースとしても利用したい場合、最も適したサービスはどれですか？',
    choices:['Amazon MemoryDB','Amazon ElastiCache','Amazon DynamoDB','Amazon RDS'], correct:[0],
    why:['正しい。Amazon MemoryDBは、Redis OSS・Valkey互換のインメモリデータベースで、マルチAZのトランザクションログによりデータを永続的に保存するため、マイクロ秒単位のレイテンシーを維持しつつプライマリデータベースとして利用できます。','誤り。Amazon ElastiCacheは主にキャッシュ用途のインメモリサービスであり、再起動時にデータが失われる可能性があるため、データそのものを保存するプライマリデータベースとしての利用は主目的ではありません。','誤り。Amazon DynamoDBはマネージド型のNoSQLデータベースですが、インメモリデータベースのようなマイクロ秒単位のレイテンシーは主目的としていません。','誤り。Amazon RDSはリレーショナルデータベースのマネージドサービスであり、インメモリデータベースのようなマイクロ秒単位のレイテンシーは実現しません。']},
  {id:'p442', domain:'tech', type:'single', source:SOURCES.codeartifact, text:'複数の開発チームが、npmやMavenなどのパッケージマネージャーで使用する社内共通ライブラリを安全に保管・共有したい。さらに、npmjs等の公開リポジトリのパッケージをキャッシュしてビルドを高速化・安定化させたい場合、最も適したサービスはどれですか？',
    choices:['Amazon ECR','AWS CodeArtifact','AWS CodeCommit','Amazon S3'], correct:[1],
    why:['誤り。Amazon ECRはコンテナイメージを保存するレジストリサービスであり、npm・Maven等のパッケージ管理を主目的とするものではありません。','正しい。AWS CodeArtifactは、npm・Maven・pip・NuGet等のパッケージマネージャーで使うパッケージを安全に保管・共有できるマネージド型のアーティファクトリポジトリサービスで、公開リポジトリをアップストリームとして設定し、取得したパッケージをキャッシュする機能も備えています。','誤り。これはソースコードのバージョン管理サービスであり、ビルド済みパッケージの保管・共有を主目的とするものではありません。','誤り。Amazon S3は汎用のオブジェクトストレージであり、パッケージマネージャーとの連携やバージョン管理機能を持つパッケージリポジトリとしての機能は備えていません。']},
  {id:'p443', domain:'tech', type:'single', source:SOURCES.cloudshell, text:'特定のEC2インスタンスにログインするのではなく、AWS Management Consoleから直接、事前に認証済みのブラウザ上のターミナルを起動し、AWS CLIがプリインストールされた環境でAWSリソースをすぐに操作したい場合、最も適したサービスはどれですか？',
    choices:['AWS Systems Manager Session Manager','AWS CloudFormation','AWS CloudShell','Amazon WorkSpaces'], correct:[2],
    why:['誤り。Session Managerは、特定のEC2インスタンス等のノードに対してSSHキーや踏み台サーバーなしでシェルアクセスするための機能であり、インスタンスではなくコンソール上で汎用的にCLI操作を行うCloudShellとは目的が異なります。','誤り。AWS CloudFormationはIaCによるリソースのプロビジョニングサービスであり、ブラウザ上のターミナル環境を提供するものではありません。','正しい。AWS CloudShellは、AWS Management Consoleから直接起動できる、事前に認証済みのブラウザ上のターミナルで、AWS CLIや主要な開発ツールがプリインストールされており、ローカル環境の設定なしにすぐAWSリソースを操作できます。','誤り。Amazon WorkSpacesは仮想デスクトップ環境を提供するサービスであり、コンソール上のブラウザターミナルとは異なります。']},
  {id:'p444', domain:'tech', type:'single', source:SOURCES.mwaa, text:'データエンジニアリングチームが、既存の多数のApache Airflow DAG(Pythonで書かれたワークフロー定義)をそのまま使い続けながら、Airflowのスケジューラー・ワーカーなどの基盤の構築・運用をマネージド化してクラウドに移行したい場合、最も適したサービスはどれですか？',
    choices:['AWS Step Functions', 'AWS Glueのワークフロー機能のみ', 'Amazon EventBridge Scheduler', 'Amazon Managed Workflows for Apache Airflow (MWAA)'], correct:[3],
    why:['誤り。AWS Step Functionsは独自のステートマシン(ASL)でワークフローを定義するサービスであり、既存のAirflow DAG(Pythonコード)をそのまま移行することはできません。','誤り。AWS Glueのワークフロー機能はGlueのジョブ間の依存関係を管理するものであり、既存のAirflow DAGをそのまま実行する仕組みではありません。','誤り。Amazon EventBridge Schedulerはスケジュールに基づいてイベントを発生させるサービスであり、Airflowの複雑な依存関係管理やDAGの実行基盤を代替するものではありません。','正しい。MWAAは、Apache Airflowのスケジューラー・ワーカーなどの基盤をマネージドで提供するサービスで、既存のAirflow DAG(Pythonコード)やAirflow用のオペレーター・プラグインをそのまま利用しながらクラウドに移行できます。']},
  {id:'p445', domain:'tech', type:'multi', source:SOURCES.storageLens, text:'Amazon S3 Storage Lensの特徴として正しいものを2つ選択してください。',
    choices:['組織内の複数のAWSアカウント・複数のリージョンにまたがるS3の使用状況・アクティビティの傾向を、単一のダッシュボードで可視化できる','S3バケットに保存されたオブジェクトの内容を自動的に暗号化する','コスト最適化（未使用の古いバージョンの削除等）やデータ保護のベストプラクティスに関する推奨事項を提示する','バケット内に保存された個人情報等の機密データを機械学習で自動的に検出・分類する'], correct:[0,2],
    why:['正しい。S3 Storage Lensは、組織内の複数のAWSアカウント・複数のリージョンにまたがるS3の使用状況・アクティビティの傾向を単一のダッシュボードで可視化できる機能です。','誤り。Storage Lensはデータの暗号化を自動的に行う機能ではありません。暗号化はS3自体の暗号化設定やAWS KMS等で行います。','正しい。Storage Lensは、使用状況の可視化に加えて、コスト最適化やデータ保護のベストプラクティスに関する推奨事項(コンテキストに応じた改善提案)も提示します。','誤り。これはAmazon Macieの説明であり、Storage Lensの機能ではありません。']},
  {id:'p446', domain:'security', type:'single', source:SOURCES.securityIR, text:'Amazon GuardDutyやAWS Security Hub等で検出されたセキュリティ上の懸念事項について、自動検知だけでなく、実際のセキュリティインシデント発生時にAWSのセキュリティ専門家(インシデント対応チーム)による人的な支援・トリアージを受けたい場合、最も適したサービスはどれですか？',
    choices:['AWS Security Incident Response', 'Amazon GuardDuty', 'Amazon Detective', 'AWS Security Hub'], correct:[0],
    why:['正しい。AWS Security Incident Responseは、実際のセキュリティインシデント発生時にAWSのセキュリティ専門家チームへの連絡・支援を受けられるサービスで、インシデントのトリアージや対応の一元管理、事前の準備状況レビューなどを提供します。','誤り。Amazon GuardDutyは機械学習等を用いた自動的な脅威検出サービスであり、人的な支援を提供するものではありません。','誤り。Amazon Detectiveは検出結果に関連するログの自動分析・可視化を行うサービスであり、AWSの専門家による人的支援を提供するものではありません。','誤り。AWS Security Hubは複数のセキュリティサービスの検出結果を集約するサービスであり、人的な支援を提供するものではありません。']},
  {id:'p447', domain:'security', type:'multi', source:SOURCES.cleanrooms, text:'AWS Clean Roomsの特徴として正しいものを2つ選択してください。',
    choices:['コラボレーションの各参加企業は、自社のデータセットの内容を他の参加企業に生データのまま開示する必要がある','参加企業は、自社が保有するデータを別の場所に移動させることなく、元の保存場所(S3等)からデータを読み込んでクエリやジョブを実行できる','データコラボレーションに参加するには、全参加企業がAWS Organizationsで1つの管理アカウントに統合されている必要がある','SQLクエリによる分析に加えて、データを暗号化したまま処理するCryptographic Computingや、ユーザー識別を防ぐDifferential Privacyなどのプライバシー強化技術を利用できる'], correct:[1,3],
    why:['誤り。AWS Clean Roomsは、参加企業が互いにデータセットの内容(生データ)を開示することなく分析できるようにする点が特徴であり、生データの開示を必要とするものではありません。','正しい。AWS Clean Roomsでは、クエリやジョブを実行する際、データはその元の保存場所(S3やSnowflake等)から読み込まれ、データを別の場所に移動させる必要はありません。','誤り。Clean Roomsのコラボレーションは、異なるAWSアカウント間（Organizationsへの統合は不要）で、招待したアカウントを選んで参加できる仕組みです。','正しい。Clean Roomsは、通常のSQLクエリ・PySparkジョブに加えて、データを暗号化したまま処理するCryptographic Computingや、ユーザー識別を防ぐDifferential Privacyなどのプライバシー強化技術を提供します。']},
  {id:'p448', domain:'security', type:'single', source:SOURCES.acmpca, text:'AWS Organizations配下の複数のAWSアカウントで、それぞれ個別にプライベート認証局(CA)を構築するのではなく、1つのAWS Private CAで作成したCA階層を複数アカウントで共有し、各アカウントから証明書を発行できるようにしたい場合、最も適切な方法はどれですか？',
    choices:['各アカウントに個別にAWS Private CAを作成し、それぞれ別のCA階層として運用する', 'AWS Private CAで作成したプライベート認証局を、AWS Resource Access Manager (RAM)を使って他のアカウントと共有する', '各アカウントでAWS Certificate Manager (ACM)のパブリック証明書を個別に発行する', 'AWS KMSのカスタマーマネージドキーを各アカウント間で共有する'], correct:[1],
    why:['誤り。個別にCAを構築すると、アカウントごとに別のCA階層となり、証明書の信頼チェーンが統一されず、CAの管理コストも増加します。','正しい。AWS Private CAで作成したプライベート認証局は、AWS Resource Access Manager (RAM)を使って他のAWSアカウントと共有でき、共有先のアカウントは同じCA階層から証明書を発行できます。','誤り。ACMのパブリック証明書はインターネット公開用の証明書であり、社内向けのプライベートなCA階層の共有とは異なります。','誤り。KMSのキー共有は暗号鍵の共有であり、プライベート認証局(CA)階層の共有とは異なる仕組みです。']},
  {id:'p449', domain:'concepts', type:'single', source:SOURCES.wafOps, text:'AWS Well-Architected Frameworkの「運用上の優秀性の柱」の設計原則の一つ「障害を予測する(Anticipate failure)」が重視する内容として正しいものはどれですか？',
    choices:['変更を小さい単位に分割して頻繁に反映し、ロールバックを容易にすること','大小を問わずすべての運用上の失敗(イベント)から教訓を得て、継続的な改善につなげること','潜在的な障害の原因(依存関係の障害等)を事前に特定し、事前のテスト(障害注入テストやゲームデー等)によって障害発生時の挙動や復旧手順を検証しておくこと','運用手順をコードとして定義し、人手によるオペレーションを減らすこと'], correct:[2],
    why:['これは「頻繁に、小規模かつ可逆的な変更を行う(Make frequent, small, reversible changes)」の説明です。','これは「すべての運用上の失敗から学ぶ(Learn from all of your operational failures)」の説明です。','正しい。「障害を予測する(Anticipate failure)」は、潜在的な障害の原因を事前に洗い出し、障害注入テストやゲームデーなどを通じて障害発生時の挙動や復旧手順を事前に検証しておくことを重視する設計原則です。','これは「運用をコードとして実行する(Perform operations as code)」の説明です。']},
  {id:'p450', domain:'concepts', type:'single', source:SOURCES.wafOps, text:'AWS Well-Architected Frameworkの「運用上の優秀性の柱」の設計原則の一つ「運用手順を頻繁に改善する(Refine operations procedures frequently)」が重視する内容として正しいものはどれですか？',
    choices:['潜在的な障害の原因を事前に特定し、障害注入テストを実施すること','変更を小規模かつ可逆的な単位に分割して頻繁に反映すること','大小を問わずすべての運用上の失敗から教訓を得ること','ワークロードの成長や変化に合わせて、運用手順自体を定期的に見直し、自動化の機会を含む改善点を取り入れて更新し続けること'], correct:[3],
    why:['これは「障害を予測する(Anticipate failure)」の説明です。','これは「頻繁に、小規模かつ可逆的な変更を行う(Make frequent, small, reversible changes)」の説明です。','これは「すべての運用上の失敗から学ぶ(Learn from all of your operational failures)」の説明です。','正しい。「運用手順を頻繁に改善する」は、ワークロードの成長や変化に合わせて運用手順自体を定期的に見直し、自動化の機会を含む改善点を取り入れて更新し続けることを重視する設計原則です。']},
  {id:'p451', domain:'concepts', type:'single', source:SOURCES.tco, text:'オンプレミスからクラウドへの移行がTotal Cost of Ownership(TCO、総所有コスト)の削減につながる理由として最も適切なものはどれですか？',
    choices:['将来の需要予測に基づいて機器を事前に過剰導入する必要がなく、実際の使用量に応じて柔軟にリソースを調整できるため、遊休リソースにかかるコストを削減できる','AWSの無料利用枠を使えば、すべてのワークロードの料金が一切発生しなくなるため','AWSサポートプランの料金が常に無料になるため','クラウドに移行すればサーバーの物理的な故障が発生しなくなるため'], correct:[0],
    why:['正しい。オンプレミスでは将来の需要予測に基づいて機器を事前に過剰導入(オーバープロビジョニング)する必要がありますが、クラウドでは実際の使用量に応じて柔軟にリソースを調整できるため、遊休リソースにかかるコストを削減でき、これがTCO削減の要因の一つとなります。','誤り。無料利用枠は一部のサービス・一定の範囲に限られており、すべてのワークロードの料金が無料になるわけではありません。','誤り。Basic Supportは無料ですが、上位のサポートプランは有料であり、サポート料金全体が常に無料になるわけではありません。','誤り。クラウドでも基盤となる物理ハードウェアの故障は発生し得ますが、AWSが冗長化・保守を行うことで利用者への影響を抑えています。物理故障が完全になくなるわけではありません。']},
  {id:'p452', domain:'billing', type:'single', source:SOURCES.ec2Ri, text:'Amazon EC2のConvertible Reserved InstancesとStandard Reserved Instancesの違いとして正しいものはどれですか？',
    choices:['Standard Reserved Instancesは契約期間中に異なるインスタンスファミリーへ交換できるが、Convertible Reserved Instancesは交換できない','Convertible Reserved Instancesは契約期間中に同等以上の価値を持つ別の構成に交換できるが、Reserved Instance Marketplaceで売却することはできない。一方Standard Reserved Instancesは構成の交換はできないが、不要になった場合はMarketplaceで売却できる','どちらのリザーブドインスタンスも契約期間中に自由に構成を交換でき、かつ不要になった場合はMarketplaceで売却もできる','どちらのリザーブドインスタンスも、契約期間中の構成交換・Marketplaceでの売却のいずれもできない'], correct:[1],
    why:['誤り。説明が逆です。構成を交換できるのはConvertible Reserved Instancesであり、Standard Reserved Instancesは交換できません。','正しい。Convertible Reserved Instancesは契約期間中に同等以上の価値を持つ別の構成(インスタンスファミリー・OS・テナンシー等)に交換できる柔軟性を持ちますが、Reserved Instance Marketplaceで売却することはできません。一方Standard Reserved Instancesは構成の交換はできませんが、不要になった場合はMarketplaceで売却できます。','誤り。両方の機能を同時に持つリザーブドインスタンスの種類はありません。','誤り。Standard Reserved InstancesはMarketplaceでの売却が可能であり、Convertible Reserved Instancesは構成の交換が可能です。']},
  {id:'p453', domain:'billing', type:'single', source:SOURCES.capacityReservation, text:'Amazon EC2のOn-Demand Capacity Reservationで特定のアベイラビリティーゾーンの容量を確保したうえで、その利用に対して料金の割引も適用したい場合、最も適切な方法はどれですか？',
    choices:['Capacity Reservationを作成するだけで、自動的にオンデマンド料金から割引が適用される','Capacity Reservationには自動的にスポット料金が適用されるため、追加の対応は不要である','確保した容量と同じインスタンスファミリー・アベイラビリティーゾーン・プラットフォームに対応するリージョナルのリザーブドインスタンスやSavings Plansを別途購入し、Capacity Reservationと組み合わせることで、容量確保と料金の割引を両方得る','Capacity ReservationはSavings Plansやリザーブドインスタンスと併用できないため、割引を受ける方法はない'], correct:[2],
    why:['誤り。On-Demand Capacity Reservation自体には料金の割引はなく、容量を確保した分はオンデマンド料金が基準になります。','誤り。Capacity Reservationはオンデマンドの容量確保の仕組みであり、スポット料金が適用されるものではありません。','正しい。確保した容量と一致するリージョナルのリザーブドインスタンスやSavings Plansを別途購入してCapacity Reservationと組み合わせることで、容量の確保と料金の割引を両方得ることができます。','誤り。Capacity ReservationはリザーブドインスタンスやSavings Plansと併用でき、組み合わせることで割引を受けられます。']},
  {id:'p454', domain:'tech', type:'single', source:SOURCES.qDeveloper, text:'開発者がAWSマネジメントコンソールやIDE(統合開発環境)上で、コードの提案・説明、既存コードのセキュリティ脆弱性スキャン、AWSのアーキテクチャやベストプラクティスに関する質問応答などの支援を会話形式で受けたい場合、最も適したサービスはどれですか？',
    choices:['Amazon Q Developer','Amazon Q Business','Amazon CodeGuru','AWS Systems Manager'], correct:[0],
    why:['正しい。Amazon Q Developerは、IDEやAWSコンソール上でコードの提案・説明・セキュリティスキャン、AWSに関する質問応答などを会話形式で支援する生成AIアシスタントです。','誤り。Amazon Q Businessは社内文書やデータソースを活用するエンタープライズ向けの生成AIアシスタントで、開発者のコーディング支援に特化したものではありません。','誤り。Amazon CodeGuruはコードレビューやアプリケーションのパフォーマンスプロファイリングに特化したサービスで、対話形式のアシスタントではありません。','誤り。AWS Systems Managerはオペレーション管理サービスで、コーディング支援機能は持ちません。']},
  {id:'p455', domain:'tech', type:'single', source:SOURCES.qDeveloper, text:'Amazon Q Developerの特徴として正しいものはどれですか？',
    choices:['AWSアカウントを保有する企業の管理者のみが利用でき、個人が無料で利用することはできない','Amazon Bedrock上に構築された生成AIアシスタントで、Visual Studio CodeやJetBrains系IDEなど主要なIDEに拡張機能として統合して利用できる','オンプレミスのソースコードリポジトリをAWSのCodeCommitへ自動的に移行するサービスである','EC2インスタンス上のコードを自動的に本番環境へデプロイするCI/CDパイプラインサービスである'], correct:[1],
    why:['誤り。Amazon Q Developerは、AWS Builder IDを使えば個人開発者もAWSアカウントなしで無料で利用を開始できます。','正しい。Amazon Q DeveloperはAmazon Bedrock上に構築された生成AIアシスタントで、Visual Studio Code・JetBrains系IDE・Visual Studio・Eclipse(プレビュー)など主要なIDEに拡張機能として統合できます。','誤り。ソースコードリポジトリを移行するサービスではありません。','誤り。CI/CDパイプラインサービスではなく、対話形式の開発支援アシスタントです。']},
  {id:'p456', domain:'security', type:'single', source:SOURCES.appfabric, text:'自社で利用している複数のSaaS(Software as a Service)アプリケーション(生産性ツールやセキュリティツールなど)の監査ログを一か所に集約し、共通のスキーマに正規化した上で、横断的に異常なユーザー行動を分析したい場合、最も適したサービスはどれですか？',
    choices:['AWS CloudTrail','Amazon CloudWatch Logs','AWS AppFabric','AWS Config'], correct:[2],
    why:['誤り。AWS CloudTrailはAWSアカウント内のAPIコール履歴を記録するサービスで、サードパーティSaaSアプリケーションの監査ログを正規化・集約するものではありません。','誤り。CloudWatch Logsはログの収集・保存・監視を行うサービスですが、複数SaaSアプリケーションの監査ログを標準スキーマに正規化する機能は持ちません。','正しい。AWS AppFabricは、複数のSaaSアプリケーションを接続し、監査ログを標準化されたスキーマ(OCSF)に正規化して集約することで、横断的なセキュリティの可視化・分析を可能にするサービスです。','誤り。AWS ConfigはAWSリソースの構成変更を記録・評価するサービスで、SaaSアプリケーションの監査ログを扱うものではありません。']},
  {id:'p457', domain:'security', type:'single', source:SOURCES.appfabric, text:'AWS AppFabricとAWS Security Hubの役割の違いとして正しいものはどれですか？',
    choices:['AppFabricはAWSサービスの検出結果を集約し、Security Hubはサードパーティ製SaaSアプリケーションの監査ログを集約する','両方とも全く同じ役割を持ち、どちらか一方だけを使えばよい','Security Hubはログを集約するだけでスキーマの正規化は行わないが、AppFabricはOCSFへの正規化を行う','Security HubはAmazon GuardDutyやAmazon Inspectorなど複数のAWSセキュリティサービスの検出結果を集約するのに対し、AppFabricはSlackやMicrosoft 365などサードパーティ製SaaSアプリケーションの監査ログを集約・正規化する'], correct:[3],
    why:['誤り。説明が逆です。','誤り。AppFabricはSaaSアプリケーションの監査ログ集約、Security HubはAWSセキュリティサービスの検出結果集約と役割が異なります。','誤り。Security Hub自体もAWS Security Finding Format(ASFF)で検出結果を正規化しますが、対象がAWSサービスの検出結果である点がAppFabricと異なります。','正しい。Security HubはGuardDuty・Inspector・Macieなど複数のAWSセキュリティサービスの検出結果を集約するのに対し、AppFabricはSlackやMicrosoft 365などサードパーティ製SaaSアプリケーションの監査ログをOCSFに正規化して集約します。']},
  {id:'p458', domain:'security', type:'single', source:SOURCES.nitroSystem, text:'非常に機密性の高いデータ(個人情報や医療データなど)を処理する際に、同じEC2インスタンス内で動作する他のアプリケーションや、OSレベルの管理者権限を持つ者からも隔離された、独立した実行環境を作りたい場合に使用できる、AWS Nitro Systemをベースにした機能は何ですか？',
    choices:['AWS Nitro Enclaves','Amazon EC2 Auto Scaling','AWS CloudHSM','Amazon EC2 Dedicated Host'], correct:[0],
    why:['正しい。AWS Nitro Enclavesは、AWS Nitro Systemをベースに、EC2インスタンス内で親インスタンスのOS・ハイパーバイザー・管理者からも隔離された、永続ストレージやネットワークを持たない独立した実行環境を作成できる機能です。','誤り。EC2 Auto Scalingは需要に応じてインスタンス数を自動的に増減させる機能で、隔離された実行環境を作る機能ではありません。','誤り。AWS CloudHSMは専用のハードウェアセキュリティモジュールで暗号鍵を管理するサービスで、アプリケーションの実行環境そのものを隔離する機能ではありません。','誤り。EC2 Dedicated Hostは物理サーバーを特定の顧客専用に割り当てる機能で、インスタンス内部でのデータ隔離を実現するものではありません。']},
  {id:'p459', domain:'tech', type:'single', source:SOURCES.kinesis, text:'Amazon Kinesis Data Streamsにおいて、データストリームの取り込み・読み取りのキャパシティ(スループット)を調整する基本単位は何ですか？',
    choices:['リザーブドインスタンス','シャード(Shard)','Amazon S3バケット','SQSキューの可視性タイムアウト'], correct:[1],
    why:['誤り。リザーブドインスタンスはEC2の購入オプションであり、Kinesisのキャパシティ単位ではありません。','正しい。Amazon Kinesis Data Streamsでは、ストリームは1つ以上の「シャード」で構成され、シャードの数によってデータの取り込み・読み取りのスループット(キャパシティ)が決まります。','誤り。S3バケットはオブジェクトストレージの格納単位であり、Kinesisのキャパシティ単位ではありません。','誤り。可視性タイムアウトはAmazon SQSの機能であり、Kinesisのキャパシティ単位ではありません。']},
  {id:'p460', domain:'tech', type:'single', source:SOURCES.dms, text:'ソースとターゲットでデータベースエンジンの種類が異なる場合(例: オンプレミスのOracleからAmazon Auroraへの移行)、AWS Database Migration Service (AWS DMS) でデータ移行を行う前に、テーブル定義などのスキーマ自体を変換するために使用するツールは何ですか？',
    choices:['AWS DMSのレプリケーションインスタンス','AWS Application Migration Service (MGN)','AWS Schema Conversion Tool (AWS SCT)','AWS DataSync'], correct:[2],
    why:['誤り。レプリケーションインスタンスはDMSでデータそのものを移行・継続的に複製するためのコンポーネントで、スキーマの変換を行うものではありません。','誤り。AWS MGN(AWS Transform MGN)はサーバー全体をリフト&シフトでクラウドに移行するサービスで、異種データベース間のスキーマ変換を行うものではありません。','正しい。AWS Schema Conversion Tool (AWS SCT) は、ソースとターゲットでデータベースエンジンが異なる場合に、テーブル定義などのスキーマを変換するために使用するツールです。変換後、AWS DMSがデータの移行・継続的な複製を担当します。','誤り。AWS DataSyncはファイル/オブジェクトストレージ間のデータ転送サービスで、データベースのスキーマ変換機能は持ちません。']},
  {id:'p461', domain:'tech', type:'single', source:SOURCES.opensearch, text:'生成AIを使った社内向けチャットボットで、社内ドキュメントの内容をもとに回答させる「検索拡張生成(RAG)」を実装したい。ドキュメントをベクトル(embedding)に変換して保存し、意味的に類似した内容をk-NN(近似最近傍)検索で取得したい場合、最も適したサービスはどれですか？',
    choices:['Amazon Athena','AWS Glue','Amazon DynamoDB','Amazon OpenSearch Service'], correct:[3],
    why:['誤り。AthenaはS3上のデータに対してSQLクエリを実行するサービスで、ベクトル検索(k-NN)の機能は持ちません。','誤り。AWS GlueはETL(抽出・変換・ロード)サービスで、ベクトル検索機能は持ちません。','誤り。DynamoDBはキーバリュー型のNoSQLデータベースで、標準機能として近似最近傍のベクトル検索は提供していません。','正しい。Amazon OpenSearch Serviceはベクトル検索(k-NN)機能を備えており、ドキュメントのembeddingを保存して意味的に類似したコンテンツを検索する、RAGのための検索基盤として利用できます。']},
  {id:'p462', domain:'concepts', type:'single', source:SOURCES.controlTower, text:'AWS Control TowerとAWS Organizationsの関係として正しいものはどれですか？',
    choices:['Control Towerは、AWS OrganizationsやAWS IAM Identity Center、AWS Configなど既存の複数のAWSサービスを基盤として、ベストプラクティスに基づいたマルチアカウント環境(ランディングゾーン)を自動的にセットアップ・管理するサービスである','Control TowerはOrganizationsの後継サービスであり、Organizationsは非推奨になっている','Control TowerとOrganizationsは互いに独立しており、連携して利用することはできない','Organizationsがランディングゾーンの自動構築を行い、Control TowerはSCP(サービスコントロールポリシー)の管理のみを行う'], correct:[0],
    why:['正しい。AWS Control Towerは、AWS OrganizationsによるマルチアカウントやSCPの管理、IAM Identity CenterによるSSO、AWS Configによる構成管理など、複数の既存AWSサービスを基盤として、ベストプラクティスに基づくランディングゾーンを自動的にセットアップ・管理するサービスです。','誤り。AWS Organizationsは現在も提供されている現役のサービスであり、非推奨にはなっていません。','誤り。Control TowerはOrganizationsなど既存サービスと連携して動作します。','誤り。説明が逆です。ランディングゾーンの自動構築を行うのはControl Towerで、Organizations自体はSCPの適用などマルチアカウント管理の基盤機能を提供します。']},
  {id:'p463', domain:'concepts', type:'single', source:SOURCES.resilienceHub, text:'AWS Resilience HubとAWS Elastic Disaster Recovery (AWS DRS) の役割の違いとして正しいものはどれですか？',
    choices:['両方とも実際の障害復旧(フェイルオーバー)を自動的に実行するサービスである','Resilience Hubはアプリケーションのレジリエンス目標(RTO/RPO)の定義・評価・改善提案を行うサービスであり、実際のディザスタリカバリ(フェイルオーバー)を実行するのはAWS DRSなど別のサービスの役割である','AWS DRSはレジリエンス目標を評価するだけで、実際の障害復旧は行わない','両方とも名称が異なるだけで全く同じ機能を提供する'], correct:[1],
    why:['誤り。Resilience Hub自体は実際のフェイルオーバーを自動実行するサービスではありません。','正しい。AWS Resilience Hubは、Well-Architected Frameworkに基づきアプリケーションのレジリエンス目標(RTO/RPO)を定義・評価し、改善策を提示するサービスです。一方、実際のディザスタリカバリ(サーバーの継続的レプリケーションとフェイルオーバー)を実行するのはAWS Elastic Disaster Recoveryなど別のサービスの役割です。','誤り。AWS DRSは実際のサーバーのレプリケーションとフェイルオーバーを実行するサービスです。','誤り。両者は役割が異なる別のサービスです。']},
  {id:'p464', domain:'concepts', type:'multi', source:SOURCES.globalInfra, text:'次のうち、AWSグローバルインフラストラクチャを構成する要素として正しいものを2つ選択してください。',
    choices:['アベイラビリティーゾーン(AZ)','IAMロール','リージョン','セキュリティグループ'], correct:[0,2],
    why:['正しい。アベイラビリティーゾーン(AZ)は、AWSグローバルインフラストラクチャを構成する要素の一つです。','誤り。IAMロールはAWS Identity and Access Managementの機能であり、地理的なインフラ要素ではありません。','正しい。リージョンは、AWSグローバルインフラストラクチャを構成する要素の一つです。','誤り。セキュリティグループはEC2インスタンス等に適用する仮想ファイアウォール機能であり、地理的なインフラ要素ではありません。']},
  {id:'p465', domain:'billing', type:'single', source:SOURCES.ec2Ri, text:'ある企業が、特定のアベイラビリティーゾーンでの容量確保までは必要としておらず、リージョン内のどのAZでインスタンスを起動しても割引を適用したいと考えている。この場合、どちらのスコープのリザーブドインスタンスを選択すべきですか？',
    choices:['ゾーナルスコープのリザーブドインスタンス','オンデマンドインスタンスのみ(リザーブドインスタンスを使わない)','リージョナルスコープのリザーブドインスタンス','スポットインスタンスのみ'], correct:[2],
    why:['誤り。ゾーナルスコープは特定のAZでの容量確保が保証される一方、割引の適用もそのAZ内の利用に限られます。','誤り。オンデマンドインスタンスのみでは、長期利用による割引を受けられません。','正しい。リージョナルスコープのリザーブドインスタンスは、特定のAZでの容量確保は保証されませんが、リージョン内のどのAZでインスタンスを起動しても割引が適用されます。','誤り。スポットインスタンスは空き容量を活用する割引で、中断の可能性があり、コミットメント型の割引とは異なります。']},
  {id:'p466', domain:'billing', type:'single', source:SOURCES.savingsplansTypes, text:'Savings Plansを契約する際に、利用者が確約(コミット)する内容として正しいものはどれですか？',
    choices:['特定のインスタンスタイプを事前に一定数購入すること','月額固定のサブスクリプション料金を支払うこと','特定のアベイラビリティーゾーンでの容量確保を保証すること','1時間あたりの一定の利用金額($/時)を、1年または3年の期間にわたって継続的に利用することを確約すること'], correct:[3],
    why:['誤り。特定のインスタンスタイプを事前購入するのはリザーブドインスタンスの説明です。','誤り。Savings Plansは月額固定のサブスクリプションではなく、時間あたりの利用金額に対するコミットメントです。','誤り。容量確保を保証するのはCapacity ReservationやゾーナルスコープのRIの役割であり、Savings Plans自体には容量確保の保証はありません。','正しい。Savings Plansは、1時間あたりの一定の利用金額($/時)を1年または3年の期間継続して利用することを確約することで、料金の割引を受けられる料金モデルです。']},
  {id:'p467', domain:'concepts', type:'single', source:SOURCES.migrationStrategies, text:'移行戦略の一つである「リパーチェス(Repurchase)」の説明として正しいものはどれですか？',
    choices:['既存のアプリケーションを捨てて、同様の機能を持つ商用のSaaS製品など、全く新しい製品に切り替えること','アプリケーションをそのまま変更せずにクラウドへ移行すること(リフト&シフト)','アプリケーションのコア部分を変更せず、ミドルウェアをマネージド型サービスに置き換えること','現時点では移行せず、既存の環境にそのまま残しておくこと'], correct:[0],
    why:['正しい。リパーチェス(Repurchase)は、既存のアプリケーションを捨てて、同様の機能を持つ商用のSaaS製品など全く新しい製品に切り替える移行戦略です。例えば、自社構築のCRMをSalesforceに切り替える場合などが該当します。','これは「リホスト(Rehost)」の説明です。','これは「リプラットフォーム(Replatform)」の説明です。','これは「リテイン(Retain)」の説明です。']},
  {id:'p468', domain:'concepts', type:'multi', source:SOURCES.outposts, text:'AWSのハイブリッド・エッジ関連サービスに関する説明として正しいものを2つ選択してください。',
    choices:['AWS Outpostsは、AWSが提供する専用のハードウェアをオンプレミスのデータセンターに設置し、オンプレミス環境でもAWSと同じAPI・サービス・ツールを使用できるようにするサービスである','AWS Local Zonesは、通信事業者の5Gネットワークのエッジに設置され、5Gデバイス向けの超低レイテンシーなアプリケーションを実現するためのサービスである','AWS Wavelengthは、通信事業者の5Gネットワークのエッジにコンピューティング・ストレージサービスを組み込み、モバイルデバイスからの超低レイテンシーなアクセスを実現するサービスである','AWS Local Zonesは、法令によりデータを自社データセンター内に物理的に保持する必要がある場合に、AWSのハードウェアをオンプレミスに設置して使う選択肢である'], correct:[0,2],
    why:['正しい。AWS Outpostsは専用ハードウェアをオンプレミスに設置し、オンプレミスでもAWSと同じAPI・サービスを使えるようにするハイブリッドクラウドサービスです。','誤り。これはAWS Wavelengthの特徴です。AWS Local Zonesは通信事業者の5Gネットワークではなく、AWS自身が特定の大都市圏に設置するインフラの拠点です。','正しい。AWS Wavelengthは通信事業者の5Gネットワークのエッジにコンピューティング・ストレージを組み込み、モバイルデバイスから超低レイテンシーでアクセスできるようにするサービスです。','誤り。これはAWS Outpostsの特徴です。AWS Local Zonesは顧客自身のデータセンターにハードウェアを設置するものではなく、AWSが特定の大都市圏に設置する拠点です。']},
  {id:'p469', domain:'concepts', type:'single', source:SOURCES.wafSustainability, text:'AWS Well-Architected Frameworkの「持続可能性の柱」の設計原則の一つ「新しい、より効率的なハードウェアとソフトウェアの提供を予測して採用する」が推奨する内容として正しいものはどれですか？',
    choices:['使用していないリソースを停止し、コストを削減すること','より電力効率の高い新しいプロセッサ(例: Gravitonプロセッサ)やソフトウェアのバージョンを継続的に評価し、大きな手直しなしに新技術を採用できるように柔軟に設計すること','ワークロードの環境への影響(エネルギー使用量や排出量)を測定し、改善効果の大きい箇所を特定すること','リソースの使用率を最大化し、アイドル状態のキャパシティを減らすこと'], correct:[1],
    why:['これはコスト最適化の柱の内容であり、持続可能性の柱の「新しいハードウェア・ソフトウェアの採用」の説明ではありません。','正しい。この設計原則は、より電力効率の高いプロセッサやソフトウェアを継続的に評価し、大きな手直しなしに新技術を採用できるように柔軟に設計することを推奨しています。','これは持続可能性の柱の別の設計原則「影響を理解する(Understand your impact)」の説明です。','これは持続可能性の柱の別の設計原則「使用率を最大化する(Maximize utilization)」の説明です。']},
  {id:'p470', domain:'security', type:'single', source:SOURCES.signer, text:'ある企業が、Lambda関数のデプロイパッケージが社内の承認済みビルドプロセスを経た、改ざんのないものであることを保証し、署名のないコードや信頼できない発行元のコードがデプロイされないようにしたい。最も適したサービスはどれですか？',
    choices:['AWS Certificate Manager (ACM)','Amazon Inspector','AWS Signer','AWS CloudHSM'], correct:[2],
    why:['誤り。ACMはSSL/TLS証明書の発行・管理を行うサービスで、コードの署名検証は行いません。','誤り。Amazon Inspectorはソフトウェアの脆弱性スキャンを行うサービスで、コード署名の検証機能は提供しません。','正しい。AWS Signerは、Lambdaのデプロイパッケージにデジタル署名を行い、Lambda側で署名とパッケージの完全性を検証することで、承認された信頼できるコードのみがデプロイされるようにするコード署名サービスです。','誤り。AWS CloudHSMは専用のハードウェアセキュリティモジュールで暗号鍵を管理するサービスであり、コード署名サービスではありません。']},
  {id:'p471', domain:'security', type:'single', source:SOURCES.cloudtrail, text:'AWS CloudTrailにおける「管理イベント(Management Events)」と「データイベント(Data Events)」の違いとして正しいものはどれですか？',
    choices:['管理イベントは有料で、データイベントは常に無料で記録される','管理イベントはS3オブジェクトへのGetObject等のデータ操作を記録し、データイベントはIAMやEC2などのリソースの作成・変更といった管理操作を記録する','データイベントはすべてのトレイルでデフォルトで記録され、管理イベントは個別に有効化が必要である','管理イベントはIAMのAPI呼び出しやリソースの作成・変更といったコントロールプレーンの操作を記録し、データイベントはS3オブジェクトへのGetObject/PutObjectやLambda関数のInvokeといった大量に発生しうるデータプレーンの操作を記録する。トレイルはデフォルトで管理イベントを記録し、データイベントの記録には追加料金がかかる'], correct:[3],
    why:['誤り。デフォルトで記録される管理イベントは追加料金なしで利用でき、データイベントの記録には追加料金がかかります。','誤り。管理イベントとデータイベントの説明が逆です。','誤り。デフォルトで記録されるのは管理イベントであり、データイベントは個別に有効化(かつ追加料金)が必要です。','正しい。管理イベントはIAMのAPI呼び出し等のコントロールプレーン操作、データイベントはS3オブジェクト操作やLambda Invoke等の高頻度なデータプレーン操作を記録します。トレイルはデフォルトで管理イベントを記録し、データイベントの記録には追加料金が発生します。']},
  {id:'p472', domain:'security', type:'single', source:SOURCES.kms, text:'AWS KMSの「マルチリージョンキー(multi-Region keys)」の特徴として正しいものはどれですか？',
    choices:['同じキーIDと鍵材料を持つキーを複数のリージョンに複製(レプリケート)し、一方のリージョンで暗号化したデータを、暗号化キーの再暗号化やリージョンをまたぐAWS KMSへの呼び出しをせずに、別のリージョンで復号できるようにする機能','1つのキーを作成すれば、すべてのAWSリージョンで自動的に利用可能になる、グローバルに共有されたキー','AWSマネージドキーを複数のリージョンに自動的に複製する、デフォルトで有効な機能','既存のシングルリージョンキーを、作成後にいつでもマルチリージョンキーへ変換できる機能'], correct:[0],
    why:['正しい。マルチリージョンキーは、同じキーIDと鍵材料を持つキーを複数のリージョンに複製し、一方のリージョンで暗号化したデータを、再暗号化やクロスリージョン呼び出しなしに別のリージョンで復号できるようにする機能です。','誤り。マルチリージョンキーはグローバルではなく、選択したリージョンに個別に複製(レプリケート)して使うものです。','誤り。AWSマネージドキーは常にシングルリージョンキーであり、マルチリージョンキーとして自動複製されることはありません。','誤り。既存のシングルリージョンキーをマルチリージョンキーに変換することはできません。マルチリージョンキーはキー作成時に指定する必要があります。']},
  {id:'p473', domain:'tech', type:'single', source:SOURCES.dataZone, text:'ある大企業で、各部門が独自にS3やRedshiftにデータを保存しており、他部門のデータ資産がどこにあるか把握できず、アクセス権限の管理も属人的になっている。部門をまたいでデータをカタログ化し、きめ細かなアクセス制御のもとでデータの発見・利用申請・共有を行えるようにしたい。最も適したサービスはどれですか？',
    choices:['AWS Glue','Amazon DataZone','AWS Lake Formation単体でのアクセス制御のみ','AWS Resource Access Manager (RAM)'], correct:[1],
    why:['誤り。AWS Glueはデータのカタログ化やETL処理を行うサービスですが、組織横断的なビジネス用語集やセルフサービスでのデータ発見・利用申請機能は提供しません。','正しい。Amazon DataZoneは、AWS・オンプレミス・サードパーティに分散したデータをカタログ化し、きめ細かなアクセス制御によるガバナンスを維持しながら、組織内の利用者がセルフサービスでデータを発見・申請・共有できるようにするデータ管理サービスです。','誤り。AWS Lake Formationはデータレイクへの権限管理を行う基盤的な機能ですが、組織横断的なカタログ検索やセルフサービスでのデータ利用申請ワークフローはDataZoneが提供します。','誤り。AWS RAMはVPCサブネットやTransit Gateway等のAWSリソースを複数アカウント間で共有するサービスであり、データカタログやガバナンスの機能は提供しません。']},
  {id:'p474', domain:'tech', type:'single', source:SOURCES.dataZone, text:'データサイエンティストやビジネスアナリストが、どのデータセットが「顧客の契約更新率」を表しているかを、技術的なテーブル名ではなく業務で使われる用語で検索・理解できるようにしたい。Amazon DataZoneのどの機能がこれを実現しますか？',
    choices:['AWS Glueのジョブスケジューリング機能','Amazon Athenaのクエリエディタ','ビジネスグロッサリー(業務用語集)機能。業務用語とデータ資産を関連付けることで、技術的な知識がない利用者でも業務用語でデータを検索・発見できるようにする','Amazon Redshiftのマテリアライズドビュー'], correct:[2],
    why:['誤り。Glueのジョブスケジューリングはデータ処理ジョブの実行管理を行う機能であり、業務用語でのデータ検索機能ではありません。','誤り。Athenaはクエリ実行エンジンであり、業務用語集の機能は提供しません。','正しい。Amazon DataZoneのビジネスグロッサリー機能は、業務で使われる用語とデータ資産を関連付けることで、技術的な知識がない利用者でも業務用語を使ってデータを検索・発見できるようにします。','誤り。マテリアライズドビューはクエリ結果をあらかじめ計算して保持する機能であり、業務用語でのデータ発見とは関係ありません。']},
  {id:'p475', domain:'tech', type:'single', source:SOURCES.glue, text:'データアナリストが、プログラミングコードを書かずに、GUI上で欠損値の補完や列の分割、形式の統一といったデータクリーニング・前処理の作業を視覚的に行いたい。最も適したサービスはどれですか？',
    choices:['AWS Glueのジョブ(Apache Sparkベースのコード)','Amazon Athena','AWS Step Functions','AWS Glue DataBrew。250種類以上の事前構築された変換処理を使い、コードを書かずにビジュアルなインターフェースでデータのクリーニング・正規化を行えるサービス'], correct:[3],
    why:['誤り。AWS Glueの通常のジョブはApache Spark等のコードを書いてETL処理を行うため、「コードを書かずに」という要件に合いません。','誤り。Amazon Athenaは S3データに対するSQLクエリサービスであり、ビジュアルなデータクリーニング機能は提供しません。','誤り。AWS Step Functionsは複数のサービスをワークフローとして連携させる機能であり、データクリーニング自体を行うサービスではありません。','正しい。AWS Glue DataBrewは、250種類以上の事前構築された変換処理を備え、コードを書かずにビジュアルなインターフェースでデータのクリーニングや正規化を行えるサービスです。']},
  {id:'p476', domain:'tech', type:'single', source:SOURCES.quicksight, text:'Amazon QuickSightの生成AIを活用した機能で、利用者が自然言語でビジネスに関する質問を入力すると、自動的にデータを分析してグラフや要約といった回答を生成する機能は何ですか？',
    choices:['Amazon Q in QuickSight（旧称QuickSight Q）。自然言語の質問に対して、機械学習でデータを分析し、グラフや文章での要約などの回答を自動生成する生成BI機能','AWS Glueのデータカタログ','Amazon Redshiftのマテリアライズドビュー','AWS Cost Explorerのカスタムレポート機能'], correct:[0],
    why:['正しい。Amazon Q in QuickSight(旧称QuickSight Q)は、自然言語の質問を解釈してデータを分析し、グラフや文章での要約などの回答を自動生成する生成AI(生成BI)機能です。','誤り。AWS Glueのデータカタログはメタデータを管理する機能であり、自然言語での質問応答機能ではありません。','誤り。マテリアライズドビューはクエリ結果を保持する機能であり、自然言語での質問応答とは関係ありません。','誤り。AWS Cost Explorerのカスタムレポートはコスト分析用の機能であり、QuickSightの自然言語質問応答機能とは異なります。']},
  {id:'p477', domain:'tech', type:'single', source:SOURCES.keyspaces, text:'オンプレミスでApache Cassandraを使い、CQL(Cassandra Query Language)やオープンソースのCassandra用ドライバーをそのまま使い続けたいチームが、サーバー管理不要のマネージド型データベースへ移行したい場合、Amazon DynamoDBと比較してAmazon Keyspacesが適している理由は何ですか？',
    choices:['DynamoDBよりも常に低価格で利用できるため','Amazon KeyspacesはApache Cassandraと互換性があり、既存のCQLクエリやオープンソースのCassandra用ドライバーをそのまま使って移行できるが、DynamoDBは独自のAPIとデータモデルを使うため、アプリケーションの書き換えが必要になる','DynamoDBはマネージド型ではなく、サーバーの管理が必要であるため','Amazon KeyspacesはリレーショナルデータベースであるためSQLをそのまま使えるため'], correct:[1],
    why:['誤り。料金はワークロードによって異なり、Keyspacesが常に低価格とは限りません。','正しい。Amazon KeyspacesはApache Cassandra互換のマネージド型データベースで、既存のCQLクエリやCassandra用ドライバーをそのまま使って移行できます。一方DynamoDBは独自のAPI・データモデルを使うため、アプリケーションの書き換えが必要になります。','誤り。DynamoDBもKeyspacesと同様にサーバー管理が不要なマネージド型(サーバーレス)のデータベースです。','誤り。Amazon Keyspacesはリレーショナルデータベースではなく、Cassandra互換のNoSQL(列指向)データベースであり、CQLを使用します(標準のSQLではありません)。']},
  {id:'p478', domain:'billing', type:'single', source:SOURCES.repost, text:'ある個人開発者が、AWSの有料サポートプランには加入していないが、技術的な質問について他の利用者やAWSの担当者から無料で回答を得たいと考えている。最も適した方法はどれですか？',
    choices:['AWS Business Support+に加入し、サポートケースを作成する','AWS Trusted Advisorのフルチェック結果を確認する','AWS re:Postで質問を投稿する。AWSアカウントを持つ誰でも無料で利用でき、コミュニティの専門家やAWSの従業員が回答に参加する','AWS Artifactでコンプライアンスレポートを確認する'], correct:[2],
    why:['誤り。Business Support+は有料のサポートプランであり、無料で利用したいという要件に合いません。','誤り。Trusted Advisorのフルチェックは主にBusiness Support+以上のプランで利用できる機能で、無料のQ&Aとは異なります。','正しい。AWS re:Postは、AWSアカウントを持つ誰でも無料で利用できるコミュニティ主導のQ&Aサービスで、コミュニティの専門家に加えAWSの従業員も回答に参加します。','誤り。AWS Artifactはコンプライアンスレポート等をダウンロードするサービスであり、質問・回答の場ではありません。']},
  {id:'p479', domain:'billing', type:'single', source:SOURCES.repost, text:'AWS re:Postについて正しい説明はどれですか？',
    choices:['AWS re:Postの利用には、いずれかの有料サポートプランへの加入が必須である','AWS re:Postは、AWSが従業員のみで運営する公式FAQページであり、他の利用者からの回答機能はない','AWS re:Postは特定の有料プランの利用者のみがアクセスできる非公開のナレッジベースである','AWS re:Postは、従来のAWS Forumsを置き換えるものとして提供された、コミュニティ主導の質問・回答サービスであり、AWS Free Tierの一部として、AWSアカウントを持つ誰でも無料でアクセスできる'], correct:[3],
    why:['誤り。re:Postの利用に有料サポートプランへの加入は不要です。','誤り。コミュニティの専門家(他の利用者やAWS Partner等)も回答に参加する、コミュニティ主導のQ&Aサービスです。','誤り。re:PostはAWSアカウントを持つ誰でも無料でアクセスできる公開のサービスです。','正しい。AWS re:Postは、従来のAWS Forumsを置き換えるものとして提供されたコミュニティ主導のQ&Aサービスであり、AWS Free Tierの一部としてAWSアカウントを持つ誰でも無料でアクセスできます。']},
  {id:'p480', domain:'tech', type:'single', source:SOURCES.codeguru, text:'ある開発チームが、本番環境で稼働中のJavaアプリケーションについて「CPU使用率が高く処理コストがかさんでいる箇所」を特定し、効率改善のためのコード最適化を行いたいと考えている。最も適したサービスはどれですか？',
    choices:['Amazon CodeGuru Profilerを使い、実行時のパフォーマンスデータから最もコストのかかるコード行を特定する','AWS X-Rayを使い、マイクロサービス間のリクエストの流れを可視化する','AWS Trusted Advisorを使い、コスト最適化のベストプラクティスチェックを行う','Amazon CloudWatch Logsを使い、アプリケーションログを検索する'], correct:[0],
    why:['正しい。Amazon CodeGuru Profilerは、稼働中のアプリケーションのランタイムパフォーマンスデータを収集し、機械学習によりCPU使用率が高い(最もコストのかかる)コード行を特定して改善案を提示します。','誤り。AWS X-Rayは分散トレーシングのサービスで、リクエストの流れの可視化が主目的であり、コード行単位のCPUボトルネック特定とは異なります。','誤り。Trusted Advisorはアカウント全体のベストプラクティスチェックを行うサービスで、コード行単位の分析は行いません。','誤り。CloudWatch Logsはログの収集・検索サービスであり、コードのパフォーマンス分析専用の機能ではありません。']},
  {id:'p481', domain:'tech', type:'single', source:SOURCES.resourceGroups, text:'AWS Resource Groupsの主な用途として最も適切なものはどれですか？',
    choices:['複数のAWSアカウントの利用料金を一つの請求書にまとめる','タグやCloudFormationスタックを基準に関連するリソースをグループ化し、サービスごとのコンソールを切り替えずに一つの画面で状態確認や一括操作を行う','IAMユーザーに付与された権限を分析し、過剰な権限を検出する','複数のVPCをプライベートに接続する'], correct:[1],
    why:['誤り。これはAWS Organizationsの一括支払い(Consolidated Billing)の説明です。','正しい。AWS Resource Groupsは、タグまたはCloudFormationスタックを基準に関連するリソースをグループ化し、サービスごとのコンソールを切り替えることなく一つの画面でまとめて状態確認・操作ができるようにするサービスです。','誤り。これはAWS IAM Access Analyzerの説明です。','誤り。これはAWS Transit GatewayやVPCピアリングの説明です。']},
  {id:'p482', domain:'security', type:'single', source:SOURCES.licenseManager, text:'ある企業が、オンプレミスから持ち込んだ(BYOL)データベースソフトウェアのライセンスについて、契約上の上限コア数を超えてEC2インスタンスが起動されないよう、使用状況を一元的に追跡・管理したいと考えている。最も適したサービスはどれですか？',
    choices:['AWS Service Catalogを使い、承認済みのAMIのみを配布する','AWS Organizationsのサービスコントロールポリシー(SCP)で、特定のインスタンスタイプの起動を禁止する','AWS License Managerを使い、ライセンスのルール(上限コア数等)を設定し、使用状況を追跡する','Amazon Inspectorを使い、インスタンスの脆弱性をスキャンする'], correct:[2],
    why:['誤り。Service Catalogは承認済みのIT製品をカタログ化して配布するサービスで、ライセンス使用量の追跡機能はありません。','誤り。SCPはAWSサービス・アクションの許可/拒否を制御するポリシーで、ソフトウェアライセンスの使用量追跡はできません。','正しい。AWS License Managerは、BYOLソフトウェアのライセンスについて、コア数・インスタンス数・vCPU数等に基づくルールを設定し、使用状況を一元的に追跡・管理できるサービスです。','誤り。Amazon Inspectorはソフトウェアの脆弱性診断を行うサービスで、ライセンス管理機能はありません。']},
  {id:'p483', domain:'security', type:'single', source:SOURCES.parameterStore, text:'AWS Systems Manager パラメータストアの「標準(Standard)」ティアと「アドバンスト(Advanced)」ティアの違いとして正しいものはどれですか？',
    choices:['標準ティアのみ暗号化(SecureString)に対応している','アドバンストティアは無料で、標準ティアには料金が発生する','標準ティアはパラメータ数に上限がなく、アドバンストティアには上限がある','標準ティアには保存できるパラメータの値のサイズ(4KBまで)や保存数に上限があり、より大きな値や高いスループットが必要な場合はアドバンストティアを使用する'], correct:[3],
    why:['誤り。暗号化(SecureString)は標準・アドバンスト両方のティアで利用できます。','誤り。料金体系が逆です。標準ティアは無料の範囲が大きく、アドバンストティアはパラメータ数やAPIコール数に応じて料金が発生します。','誤り。標準ティアのパラメータ数には既定の上限があります。','正しい。標準ティアは保存できる値のサイズ(4KBまで)やパラメータ数に上限があり、より大きな値・高いスループット・パラメータポリシーなどが必要な場合はアドバンストティアを使用します。']},
  {id:'p484', domain:'security', type:'single', source:SOURCES.verifiedAccess, text:'AWS Verified Accessの特徴として正しいものはどれですか？',
    choices:['VPN接続を必要とせず、ゼロトラストの原則に基づきユーザーのID情報やデバイスのセキュリティ状態を検証した上で、社内アプリケーションへのアクセスを許可する','インターネットを経由せず専用線でオンプレミスとAWSを接続する','複数のVPCをメッシュ状に接続するハブとなる','S3バケットへのアクセスをインターネットを経由せずプライベートに行う'], correct:[0],
    why:['正しい。AWS Verified Accessは、VPNを必要とせず、ゼロトラストの原則に基づいてユーザーのID情報やデバイスのセキュリティ状態(準拠状況)を継続的に検証し、社内アプリケーションへのアクセスを許可するサービスです。','誤り。これはAWS Direct Connectの説明です。','誤り。これはAWS Transit Gatewayの説明です。','誤り。これはAWS PrivateLink(VPCエンドポイント)の説明です。']},
  {id:'p485', domain:'security', type:'single', source:SOURCES.cloudhsm, text:'AWS CloudHSMとAWS KMSの違いとして正しいものはどれですか？',
    choices:['AWS KMSは物理的に専有のハードウェアを提供し、AWS CloudHSMは複数の顧客で共有するマルチテナント型である','AWS CloudHSMは顧客専有(シングルテナント)のハードウェアセキュリティモジュールのクラスターを複数のアベイラビリティーゾーンに展開して高可用性を実現するサービスであり、AWS KMSはAWSが管理するマルチテナント型のマネージドサービスである','両サービスとも機能・管理方式に違いはなく、名称のみが異なる','AWS CloudHSMは無料で利用でき、AWS KMSには必ず料金が発生する'], correct:[1],
    why:['誤り。説明が逆です。シングルテナント専有ハードウェアを提供するのはAWS CloudHSMです。','正しい。AWS CloudHSMは、顧客専有(シングルテナント)のハードウェアセキュリティモジュール(HSM)を複数のアベイラビリティーゾーンに分散したクラスターとして提供し高可用性を実現します。一方AWS KMSは、AWSが管理するマルチテナント型のマネージドサービスとしてキー管理を提供します。','誤り。シングルテナント専有かマルチテナント共有かという管理方式の違いがあります。','誤り。両サービスとも使用量等に応じて料金が発生します。']},
  {id:'p486', domain:'billing', type:'single', source:SOURCES.costOptimizationHub, text:'AWS Organizationsを利用する企業が、管理アカウントから、傘下の全メンバーアカウントにまたがるEC2・EBS等のコスト削減推奨事項(ライトサイジングやSavings Plans購入等)を一つの画面でまとめて確認し、優先順位をつけて対応したいと考えている。最も適したサービスはどれですか？',
    choices:['AWS Budgetsで、各メンバーアカウントに予算アラートを設定する','AWS Cost Explorerで、各メンバーアカウントのコストを個別に確認する','AWS Cost Optimization Hubを使い、組織内の全メンバーアカウントのコスト削減推奨事項を一つの画面に集約し、優先順位付けして確認する','Amazon CloudWatchで、各アカウントのEC2使用率メトリクスを監視する'], correct:[2],
    why:['誤り。AWS Budgetsは予算超過のアラート通知を行うサービスで、削減推奨事項の集約は主目的ではありません。','誤り。Cost Explorer単体では各アカウントを個別に確認することになり、組織全体の推奨事項を一括で優先順位付けすることはできません。','正しい。AWS Cost Optimization Hubは、AWS Compute OptimizerやCost Explorerのライトサイジング推奨、Savings Plans推奨などを、組織内の全メンバーアカウントにまたがって一つの画面に集約し、推定節約額に基づいて優先順位付けして確認できるサービスです。','誤り。CloudWatchは個々のメトリクス監視が目的で、組織全体のコスト削減推奨の集約機能ではありません。']},
  {id:'p487', domain:'billing', type:'single', source:SOURCES.billingConductor, text:'AWSのリセラー(パートナー)企業が、傘下の顧客アカウントごとに異なる独自の価格設定(マージンの付与等)を適用し、顧客向けにカスタマイズした請求書を発行したいと考えている。最も適したサービスはどれですか？',
    choices:['AWS Cost Categoriesを使い、コストを独自のカテゴリに分類する','AWS Budgetsを使い、顧客ごとに予算アラートを設定する','コスト配分タグを使い、顧客ごとにリソースへタグ付けする','AWS Billing Conductorを使い、顧客アカウントを「課金グループ」にまとめ、グループごとに独自の価格設定やマージンを適用したプロフォーマ請求書を作成する'], correct:[3],
    why:['誤り。Cost Categoriesはコストをビジネス上の意味のあるカテゴリに分類する機能で、顧客ごとの価格設定機能はありません。','誤り。Budgetsは予算アラート機能であり、価格設定のカスタマイズはできません。','誤り。コスト配分タグはコストの内訳を把握するための分類手段であり、価格設定機能ではありません。','正しい。AWS Billing Conductorは、顧客アカウントを「課金グループ」としてまとめ、グループごとに独自の価格設定ルールやマージンを適用したプロフォーマ(見積もり)請求書を作成できるサービスで、AWSパートナーのリセール業務等に利用されます。']},
  {id:'p488', domain:'tech', type:'single', source:SOURCES.resourceGroups, text:'AWS Resource Groupsの仕様として正しいものはどれですか？',
    choices:['1つのリソースグループは、同じリージョン内にある既存の別のリソースグループを含めることができる(ネスト)','1つのリソースグループに複数のリージョンのリソースを混在させることができる','リソースグループは、タグやCloudFormationスタックとは無関係にランダムにリソースを割り当てる','リソースグループを作成すると、対象リソースのコストが自動的に削減される'], correct:[0],
    why:['正しい。AWS Resource Groupsのグループはネスト可能で、1つのリソースグループが同じリージョン内の既存の別のリソースグループを含むことができます。','誤り。1つのリソースグループは同一リージョン内のリソースで構成されます。','誤り。リソースグループのメンバーシップは、タグベースまたはCloudFormationスタックベースのクエリによって決まります。','誤り。Resource Groups自体にコストを自動的に削減する機能はありません(管理・一括操作を容易にするサービスです)。']},
  {id:'p489', domain:'concepts', type:'single', source:SOURCES.edgelocation, text:'Amazon CloudFrontの配信アーキテクチャにおける「リージョナルエッジキャッシュ」の役割として正しいものはどれですか？',
    choices:['利用者からのリクエストを最初に受け付ける、世界中に多数配置された拠点である','エッジロケーションとオリジンサーバーの間に位置し、エッジロケーションよりも大きなキャッシュ容量でコンテンツをより長く保持することで、オリジンへのアクセスを減らす役割を持つ','AWSアカウントの請求情報を一括管理する拠点である','複数のアベイラビリティーゾーンで構成される地理的エリアである'], correct:[1],
    why:['誤り。これはエッジロケーションの説明です。','正しい。リージョナルエッジキャッシュは、エッジロケーションとオリジンサーバーの間に位置し、エッジロケーションよりも大きなキャッシュ容量でコンテンツをより長い期間保持することで、オリジンへのリクエストを減らし配信を効率化します。','誤り。請求管理とは無関係です。','誤り。これはリージョンの説明です。']},
  {id:'p490', domain:'concepts', type:'single', source:SOURCES.waf, text:'AWS Well-Architected Frameworkの6つの柱のうち、他の5つの柱(運用上の優秀性、セキュリティ、信頼性、パフォーマンス効率、コスト最適化)よりも後から追加された柱はどれですか？',
    choices:['セキュリティの柱','信頼性の柱','持続可能性の柱。クラウドワークロードが環境に与える影響を最小化することを目的として、6つ目の柱として追加された','コスト最適化の柱'], correct:[2],
    why:['誤り。セキュリティの柱は当初からの柱の一つです。','誤り。信頼性の柱は当初からの柱の一つです。','正しい。持続可能性の柱は、クラウドワークロードが環境に与える影響(エネルギー消費や水使用量など)を最小化することを目的として、6つ目の柱として後から追加されました。','誤り。コスト最適化の柱は当初からの柱の一つです。']},
  {id:'p491', domain:'concepts', type:'single', source:SOURCES.hybridCloud, text:'オンプレミスのデータセンターとAWSクラウドを組み合わせた「ハイブリッドクラウド」構成を採用する利点として最も適切なものはどれですか？',
    choices:['すべてのワークロードを即座にクラウドへ移行することが義務付けられる','オンプレミス環境への投資をすべて放棄する必要がある','ネットワークの遅延が常にゼロになる','既存のオンプレミスへの投資やレイテンシー・データ保管要件等の制約を踏まえつつ、段階的かつ柔軟にクラウドへ移行したり、クラウドの能力を既存環境に拡張したりできる'], correct:[3],
    why:['誤り。ハイブリッドクラウドは即座の全面移行を義務付けるものではありません。','誤り。既存のオンプレミス投資を活かしながら移行できる点が利点です。','誤り。レイテンシーは構成やネットワーク状況に依存し、常にゼロになるわけではありません。','正しい。ハイブリッドクラウドは、既存のオンプレミスへの投資、レイテンシーやデータ保管場所の要件などの制約を踏まえつつ、段階的かつ柔軟にクラウドへ移行したり、クラウドの能力(拡張性やサービス)を既存のオンプレミス環境に拡張したりできる利点があります。']},
  {id:'p492', domain:'concepts', type:'multi', source:SOURCES.globalInfra, text:'AWSグローバルインフラストラクチャにおける「リージョン」の特徴として正しいものを2つ選択してください。',
    choices:['複数のアベイラビリティーゾーン(AZ)で構成されている','1つのデータセンターのみで構成される最小単位である','データの保存場所やレイテンシー、コンプライアンス要件等を踏まえて利用者が選択できる、地理的に分離された独立したエリアである','すべてのリージョンは常に単一のAZのみを持つ'], correct:[0,2],
    why:['正しい。リージョンは、地理的に離れた複数のアベイラビリティーゾーン(AZ)で構成されています。','誤り。1つのデータセンターのみで構成される最小単位という説明はリージョンには当てはまりません。AZは通常1つ以上の個別のデータセンターで構成されます。','正しい。リージョンは、データの保存場所、レイテンシー、コンプライアンス要件などを踏まえて利用者が選択できる、地理的に分離された独立したエリアです。','誤り。多くのリージョンは複数のAZ(多くは3つ以上)で構成されています。']},
  {id:'p493', domain:'tech', type:'single', source:SOURCES.grafana, text:'ある運用チームが、CloudWatch・Amazon OpenSearch Service・AWS X-Ray・Amazon Managed Service for Prometheusなど複数のデータソースにまたがるメトリクス・ログ・トレースを、1つのダッシュボード上で横断的に可視化・分析したいと考えている。Grafanaサーバーの構築・運用は行いたくない場合、最も適したサービスはどれですか？',
    choices:['Amazon Managed Grafana','Amazon CloudWatch Dashboards単体','Amazon QuickSight','AWS X-Rayのサービスマップ'], correct:[0],
    why:['正しい。Amazon Managed Grafanaは、複数のデータソースを横断して運用メトリクス・ログ・トレースを可視化するダッシュボードを、サーバーの構築・運用不要でフルマネージドに提供するサービスです。','CloudWatch Dashboards単体ではCloudWatch以外の多様なデータソース(OpenSearch Service、Prometheus等)を横断した可視化は困難です。','Amazon QuickSightはBI(ビジネスインテリジェンス)向けのダッシュボードサービスで、運用メトリクス・ログ・トレースの横断的な可視化が主目的ではありません。','AWS X-Rayのサービスマップは分散トレーシングに特化した機能であり、複数データソースを横断したダッシュボードではありません。']},
  {id:'p494', domain:'tech', type:'single', source:SOURCES.firehose, text:'IoTデバイスから送られてくるストリーミングデータを、シャードの容量管理やカスタムアプリケーションの開発を行うことなく、ほぼリアルタイムにAmazon S3へ自動的に配信し、必要に応じて配信前にデータを変換(Lambdaによる変換等)したい場合、最も適したサービスはどれですか？',
    choices:['Amazon Kinesis Data Streams','Amazon Data Firehose','Amazon SQS','AWS Glue'], correct:[1],
    why:['Kinesis Data Streamsは開発者自身がシャードを管理し、独自のコンシューマーアプリケーションを実装する必要があります。','正しい。Amazon Data Firehoseは、シャード管理不要でストリーミングデータをS3等の送信先へ自動配信でき、配信前のデータ変換(Lambda連携)にも対応しています。','Amazon SQSはメッセージキューイングサービスであり、ストリーミングデータの自動配信サービスではありません。','AWS GlueはサーバーレスのETLサービスであり、ストリーミングデータのリアルタイム配信を主目的とするサービスではありません。']},
  {id:'p495', domain:'tech', type:'single', source:SOURCES.cloudfront, text:'Amazon CloudFrontディストリビューションの背後にあるAmazon S3バケットについて、CloudFront経由のリクエストのみを許可し、SSE-KMSで暗号化されたオブジェクトへのアクセスにも対応させたい場合、AWSが現在推奨する設定方法はどれですか？',
    choices:['S3バケットを「静的ウェブサイトホスティング」エンドポイントとして公開し、バケットポリシーで全世界に許可する','レガシーなOrigin Access Identity (OAI)を設定する','Origin Access Control (OAC) を設定する','S3バケットのACLで「認証済みユーザーグループ」に読み取り権限を付与する'], correct:[2],
    why:['バケットを全世界に公開してしまうと、CloudFront経由以外からも直接アクセスできてしまいセキュリティ要件を満たしません。','OAI(Origin Access Identity)はレガシーな方式で、SSE-KMS暗号化や一部のAWSリージョンに対応していません。AWSはOACへの移行を推奨しています。','正しい。Origin Access Control (OAC) はSigV4署名リクエストを使い、SSE-KMS暗号化オブジェクトへのアクセスや、2022年12月以降に追加されたオプトインリージョンを含む全リージョンのS3バケットに対応する、AWSが推奨する方式です。','S3 ACLでの認証済みユーザーグループへの付与は、AWS全体の認証済みユーザーに公開されてしまうため、CloudFront限定のアクセス制御にはなりません。']},
  {id:'p496', domain:'tech', type:'single', source:SOURCES.fis, text:'AWS Fault Injection Service (AWS FIS) で障害注入実験を実行する際、CPU使用率などのメトリクスがあらかじめ定めたしきい値を超えた場合に、実験を安全に自動停止させたい。この目的のためにAWS FISの実験テンプレートに設定する仕組みは何ですか？',
    choices:['IAMロールの権限境界(Permissions Boundary)','VPCのネットワークACL','CloudWatchのログサブスクリプションフィルター','CloudWatchアラームと連携する「停止条件(Stop Condition)」'], correct:[3],
    why:['IAMの権限境界は権限範囲の制御であり、実験の自動停止には関与しません。','ネットワークACLはサブネット単位の通信制御であり、実験の自動停止機能ではありません。','ログサブスクリプションフィルターはログの転送処理であり、実験を停止する仕組みではありません。','正しい。AWS FISでは、CloudWatchアラームを「停止条件(Stop Condition)」として実験テンプレートに設定でき、アラームが発報すると実験は自動的に停止します(一度停止した実験は再開できません)。']},
  {id:'p497', domain:'tech', type:'single', source:SOURCES.codedeploy, text:'Lambda関数の新しいバージョンへ切り替える際、トラフィックの一部(例: 10%)を新バージョンへ送って一定時間様子を見てから、問題がなければ残り全てのトラフィックを切り替える、といったトラフィックシフトの方式を設定したい場合、AWS CodeDeployが提供するデプロイ設定として最も適切なものはどれですか？',
    choices:['カナリア(Canary)デプロイ設定','AllAtOnce(即時全量切り替え)デプロイ設定','AWS CloudFormationのスタック更新','Amazon Route 53の加重ルーティング単体'], correct:[0],
    why:['正しい。AWS CodeDeployのカナリア(Canary)デプロイ設定では、最初に一部のトラフィックのみを新バージョンに送り、指定した時間が経過して問題がなければ残りのトラフィックを切り替えます。','AllAtOnceは新バージョンへ即座に全トラフィックを切り替える設定で、段階的な検証は行いません。','CloudFormationのスタック更新自体にはCodeDeployのようなトラフィックシフト機能は組み込まれていません。','Route 53の加重ルーティングはDNSレベルでの振り分けであり、CodeDeployのLambda/ECSトラフィックシフト機能とは異なる仕組みです。']},
  {id:'p498', domain:'security', type:'single', source:SOURCES.vpcFlowLogs, text:'Amazon VPC Flow Logsを有効にしてネットワークトラフィックを監査しているが、記録されるべきログに含まれない(記録対象外の)通信として正しいものはどれですか？',
    choices:['EC2インスタンス間のプライベートIPアドレスを使った通信','インスタンスがAmazonが提供するDNSサーバーに問い合わせるDNSトラフィックや、インスタンスメタデータ(169.254.169.254)宛のトラフィック','インターネットゲートウェイを経由する通信','NATゲートウェイを経由する通信(短命なものを除く)'], correct:[1],
    why:['プライベートIP間の通信は通常の対象としてログに記録されます。','正しい。VPC Flow Logsは、AmazonProvidedDNSへの問い合わせや、インスタンスメタデータ(169.254.169.254)宛のトラフィック、DHCP、Windowsのライセンスアクティベーション通信などを記録対象外としています。','インターネットゲートウェイ経由の通信は記録対象です。','通常のNATゲートウェイ通信は記録対象です(作成後すぐに削除される短命なリージョナルNATゲートウェイの通信は対象外です)。']},
  {id:'p499', domain:'security', type:'single', source:SOURCES.acmpca, text:'AWS Private CAで発行したプライベート証明書が侵害された疑いがあるため失効(revoke)させ、クライアント側がその証明書を信頼しないよう失効状態を確認できるようにしたい場合、AWS Private CAが提供する仕組みとして正しいものはどれですか？',
    choices:['AWS Certificate Manager (ACM) のパブリック証明書の自動更新機能','Amazon Inspectorによる証明書の脆弱性スキャン','OCSP(オンライン証明書ステータスプロトコル)、またはS3に保存される証明書失効リスト(CRL)によるフルマネージドの失効ステータス確認','AWS WAFのレート制限ルール'], correct:[2],
    why:['ACMのパブリック証明書の自動更新機能は、失効状態の確認とは異なる機能です。','Amazon Inspectorは脆弱性スキャンサービスであり、証明書の失効確認機能ではありません。','正しい。AWS Private CAは、OCSP(オンライン証明書ステータスプロトコル)とCRL(証明書失効リスト、S3に保存)という2つのフルマネージドな失効ステータス確認の仕組みを提供しています。','AWS WAFのレート制限ルールはWebアプリケーションへのリクエスト制御機能であり、証明書の失効とは無関係です。']},
  {id:'p500', domain:'security', type:'multi', source:SOURCES.cognito, text:'Amazon Cognitoのユーザープールにサインインした際に発行されるトークンに関する説明として正しいものを2つ選択してください。',
    choices:['IDトークンには、ユーザーの属性(メールアドレス等)に関するクレーム情報が含まれ、アプリケーションがユーザーの身元を確認するために使用する','アクセストークンの有効期限はデフォルトで無期限であり、一度発行されると失効しない','リフレッシュトークンを使うことで、ユーザーに再度サインインを求めることなく、新しいIDトークンとアクセストークンを取得できる','IDトークン・アクセストークン・リフレッシュトークンはいずれも、Cognito ID プール(フェデレーテッドアイデンティティ)が発行する一時的なAWS認証情報である'], correct:[0,2],
    why:['正しい。IDトークンはJWT形式で、ユーザーの属性に関するクレーム情報を含み、アプリケーションがユーザーの身元(本人確認)を確認するために使用します。','誤り。アクセストークンにはデフォルトの有効期限が設定されており(アプリケーションクライアントごとに設定可能)、無期限ではありません。','正しい。リフレッシュトークンを使うことで、ユーザーに再サインインを求めることなく新しいIDトークン・アクセストークンを取得できます(デフォルトでは発行から30日間有効)。','誤り。IDトークン・アクセストークン・リフレッシュトークンはユーザープールが発行するトークンです。一時的なAWS認証情報を発行するのはCognito IDプール(フェデレーテッドアイデンティティ)の役割です。']},
  {id:'p501', domain:'concepts', type:'single', source:SOURCES.localZones, text:'AWS Local Zonesを利用する際の仕組みとして正しいものはどれですか？',
    choices:['独立した新しいAWSリージョンとして、既存のVPCとは別に専用のアカウントを作成する必要がある','オンプレミスのデータセンターにAWSのラックを設置し、AWSが遠隔管理する','通信事業者の5Gネットワーク内にコンピューティングリソースを配置する','対象のLocal Zoneにオプトインした上で、親リージョンの既存VPC内にそのLocal Zone向けのサブネットを作成することで、VPCをLocal Zoneまで拡張して利用する'], correct:[3],
    why:['新しいリージョンやアカウントの作成は不要です。Local Zoneは特定の親リージョンに紐づいています。','これはAWS Outpostsの説明です。','これはAWS Wavelengthの説明です。','正しい。AWS Local Zonesは、対象のZoneにオプトインした上で、親リージョンの既存VPC内にLocal Zone向けのサブネットを作成することでVPCを拡張して利用します。']},
  {id:'p502', domain:'concepts', type:'single', source:SOURCES.edgelocation, text:'遠隔地のユーザーからAmazon S3バケットへのアップロード・ダウンロード速度を改善するため、Amazon S3 Transfer Accelerationを有効にした。この機能が高速化を実現する仕組みとして正しいものはどれですか？',
    choices:['Amazon CloudFrontが利用する世界中のエッジロケーションを経由させ、エッジロケーションからAWSのグローバルネットワークを通じて最適化された経路でS3へデータを転送する','S3バケットのデータを複数のアベイラビリティーゾーンに複製し、最も近いAZから配信する','バケット内のオブジェクトを事前に複数のリージョンへレプリケーションしておく','EC2インスタンスをユーザーの近くのリージョンに配置し、プロキシとして中継させる'], correct:[0],
    why:['正しい。S3 Transfer Accelerationは、CloudFrontが利用する世界中のエッジロケーションを経由させ、そこからAWSのグローバルネットワークを通じて最適化された経路でS3へデータを転送することで高速化します。','これはS3の耐久性・可用性に関する仕組みであり、Transfer Accelerationの高速化の仕組みとは異なります。','これはクロスリージョンレプリケーションの説明であり、事前のレプリケーションを前提としないTransfer Accelerationとは異なります。','Transfer AccelerationはEC2インスタンスの配置によるプロキシ方式ではなく、エッジロケーションを経由する仕組みです。']},
  {id:'p503', domain:'concepts', type:'single', source:SOURCES.resilienceHub, text:'AWS Resilience Hubでアプリケーションの評価(アセスメント)を実行すると、レジリエンス目標に対する達成度を示す指標が算出される。この指標と、それを改善する方法として正しい組み合わせはどれですか？',
    choices:['可用性(Availability)という指標が算出され、リザーブドインスタンスの購入によってのみ改善できる','レジリエンシースコアという指標が算出され、推奨されるアラームやテストを実装することでスコアを改善できる','コンプライアンススコアという指標が算出され、AWS Config のルール修正によってのみ改善できる','セキュリティスコアという指標が算出され、IAMポリシーの見直しによってのみ改善できる'], correct:[1],
    why:['可用性という名称の指標ではなく、Resilience Hubが算出するのは「レジリエンシースコア」です。','正しい。AWS Resilience Hubの評価では「レジリエンシースコア」が算出され、評価によって推奨されるアラームやテストを実装することでスコアを改善できます。','コンプライアンススコアはResilience Hubの指標ではありません。','セキュリティスコアはResilience Hubの指標ではありません。']},
  {id:'p504', domain:'billing', type:'single', source:SOURCES.costAllocTags, text:'AWSのコスト配分タグには「AWS生成タグ(例: aws:createdBy)」と「ユーザー定義タグ」の2種類がある。これらをコスト配分レポートやCost Explorerで利用できるようにするために必要な操作として正しいものはどれですか？',
    choices:['リソースにタグさえ付与すれば、追加の操作なしで自動的にコスト配分レポートに反映される','AWS生成タグのみ、Billing and Cost Management コンソールでの有効化(アクティベート)が必要で、ユーザー定義タグは不要である','AWS生成タグ・ユーザー定義タグのいずれも、Billing and Cost Management コンソールでそれぞれ個別に有効化(アクティベート)する必要がある','ユーザー定義タグのみ、IAMポリシーでの許可が必要で、AWS生成タグは不要である'], correct:[2],
    why:['タグを付与しただけでは反映されず、コンソールでの有効化(アクティベート)が必要です。','ユーザー定義タグについても、別途有効化(アクティベート)の操作が必要です。','正しい。AWS生成タグとユーザー定義タグは、それぞれBilling and Cost Managementコンソールの「コスト配分タグ」画面で個別に有効化する必要があり、反映されるまで最大24時間程度かかる場合があります。','IAMポリシーでの許可は主な要件ではなく、コンソールでの有効化が必要な操作です。']},
  {id:'p505', domain:'billing', type:'single', source:SOURCES.costCategories, text:'サポート費用など、複数の部門(コストカテゴリ)で共通して発生する費用を、各部門の利用割合に応じて比例配分したり、あらかじめ決めた割合で按分したりして、各コストカテゴリに配分したい場合、AWS Cost Categoriesが提供する機能として正しいものはどれですか？',
    choices:['コスト配分タグ','Savings Plansの適用範囲設定','AWS Budgetsのアラート閾値','分割請求ルール(Split Charge Rules)'], correct:[3],
    why:['コスト配分タグはリソースに付与したタグに基づく分類機能であり、共有費用の按分機能ではありません。','Savings Plansの適用範囲設定は割引の適用先設定であり、コスト按分機能ではありません。','AWS Budgetsのアラート閾値は予算超過の通知機能であり、費用按分機能ではありません。','正しい。AWS Cost Categoriesの「分割請求ルール(Split Charge Rules)」を使うと、共有費用を比例配分(Proportional)・固定割合(Fixed)・均等割り(Even)のいずれかの方法で他のコストカテゴリに按分できます。']},
  {id:'p506', domain:'concepts', type:'single', source:SOURCES.artifact, text:'医療分野の顧客データを扱う企業が、AWSの一部サービスを利用するにあたり、HIPAA(医療保険の相互運用性と責任に関する法律)に対応するためのBusiness Associate Addendum(BAA)をAWSと締結したい。この契約を確認・締結するために使用するAWSのサービス・機能はどれですか？',
    choices:['AWS Artifactの「Agreements」機能','AWS Artifactの「Reports」機能','AWS Config','AWS Audit Manager'], correct:[0],
    why:['正しい。AWS ArtifactのAgreements機能を使うと、BAAやNDAなどAWSとの契約をセルフサービスで確認・締結(レビュー・受諾)できます。','誤り。Artifactの「Reports」機能は、SOCやISO認証などの第三者審査済みレポートのダウンロードに使う機能で、契約の締結機能ではありません。','誤り。AWS Configはリソース構成の記録・評価を行うサービスで、契約の締結機能はありません。','誤り。AWS Audit Managerはコンプライアンス証拠の収集を支援するサービスで、契約の締結機能はありません。']},
  {id:'p507', domain:'concepts', type:'single', source:SOURCES.shared, text:'AWSの責任共有モデルにおいて、サービスの種類(EC2のようなIaaS、RDSのようなマネージド型サービスなど)にかかわらず、常にAWSの責任となる項目はどれですか？',
    choices:['ゲストOS(ユーザーが起動したEC2インスタンス上のOS)へのセキュリティパッチ適用','AWSのデータセンターやハードウェアなど、クラウドを支える物理的なグローバルインフラストラクチャの保護','セキュリティグループ・ネットワークACLの設定','保存データの暗号化を有効にするかどうかの設定'], correct:[1],
    why:['誤り。EC2インスタンスのゲストOSへのパッチ適用は顧客の責任です(Amazon RDSのようなマネージド型サービスでは異なります)。','正しい。データセンターの物理的セキュリティなど「クラウド自体のセキュリティ」は、サービスの種類にかかわらず常にAWSの責任です。','誤り。セキュリティグループ・NACLの設定は常に顧客の責任です。','誤り。暗号化を有効にするかどうかの設定は顧客の責任です(AWSは暗号化機能自体を提供します)。']},
  {id:'p508', domain:'security', type:'single', source:SOURCES.iotDeviceDefender, text:'工場内で稼働する大量のIoTデバイスについて、デバイスの証明書やポリシーなどの構成がセキュリティのベストプラクティス(例: 過度に広い権限を持つポリシーが設定されていないか)に準拠しているかどうかを、スケジュールに基づいて定期的に自動チェックしたい場合、最も適したAWSのサービス・機能はどれですか？',
    choices:['AWS Config のコンフォーマンスパック','Amazon GuardDuty','AWS IoT Device Defenderの「Audit」機能','Amazon Inspector'], correct:[2],
    why:['誤り。AWS Configは汎用的なAWSリソースの構成評価サービスであり、IoTデバイス固有のセキュリティベストプラクティス(証明書・ポリシー等)に特化した監査機能はありません。','誤り。GuardDutyはAWS環境全体の脅威検知サービスで、IoTデバイスの構成監査機能はありません。','正しい。AWS IoT Device Defenderの「Audit」機能は、IoTデバイスに関連するリソースの構成をセキュリティのベストプラクティスに照らしてスケジュールまたはオンデマンドで自動的にチェックします。','誤り。Amazon InspectorはEC2・ECR・Lambda等の脆弱性スキャンを行うサービスで、IoTデバイスの構成監査は対象外です。']},
  {id:'p509', domain:'security', type:'multi', source:SOURCES.iotDeviceDefender, text:'AWS IoT Device Defenderの「Detect」機能に関する説明として正しいものを2つ選択してください。',
    choices:['「Rules Detect」では、利用者がメトリクスに対する正常な挙動(ルール)を自分で定義し、それから外れた場合に異常を検知する','検知した異常は、Amazon S3に保存されるだけで、CloudWatchやSNSと連携することはできない','「ML Detect」では、機械学習モデルがデバイスの過去のデータから自動的に正常な挙動を学習し、異常を検知する','Detect機能を使うには、監視対象のデバイス側に専用の重いエージェントソフトウェアを必ずインストールする必要がある'], correct:[0,2],
    why:['正しい。「Rules Detect」は、利用者が定義したメトリクスの正常な挙動(ルール)に対する逸脱を検知する仕組みです。','誤り。検知結果(アラーム)はAWS IoTコンソール・API経由で確認できるほか、Amazon CloudWatchやAmazon SNSと連携して通知できます。','正しい。「ML Detect」は、機械学習モデルが過去のデバイスデータから正常な挙動を自動的に学習し、そこからの逸脱を異常として検知します。','誤り。AWS IoT Device DefenderはAWS IoT Coreと連携してクラウド側でメトリクスを評価する仕組みが中心で、専用の重いエージェントの必須インストールを前提とはしていません。']},
  {id:'p510', domain:'security', type:'single', source:SOURCES.systemsManager, text:'数百台規模のEC2インスタンス・オンプレミスサーバーに対して、OSのセキュリティパッチを定期的なメンテナンスウィンドウで自動的に適用し、パッチ適用状況(準拠/非準拠)をレポートとして集約したい場合、最も適したAWSの機能はどれですか？',
    choices:['AWS Systems Manager の Session Manager','AWS Systems Manager の Parameter Store','AWS Config のコンフォーマンスパック','AWS Systems Manager の Patch Manager'], correct:[3],
    why:['誤り。Session Managerは、ポートを開けずにインスタンスへシェルアクセスするための機能で、パッチ適用機能ではありません。','誤り。Parameter Storeは設定値・機密情報の保管機能で、パッチ適用機能ではありません。','誤り。Configのコンフォーマンスパックはコンプライアンスルールの集約評価機能であり、パッチの自動適用自体は行いません。','正しい。AWS Systems Manager の Patch Manager は、パッチベースラインとメンテナンスウィンドウに基づいて、EC2・オンプレミスサーバーへのOSパッチ適用を自動化し、準拠状況をレポートします。']},
  {id:'p511', domain:'security', type:'single', source:SOURCES.siteToSiteVpn, text:'AWS Site-to-Site VPNについて、AWS側の機器障害に対する可用性を確保する仕組みとして正しいものはどれですか？',
    choices:['1つのVPN接続は異なるアベイラビリティーゾーンで終端する2本のトンネルで構成され、片方に障害が発生すると自動的にもう一方のトンネルにフェイルオーバーする','1つのVPN接続は1本のトンネルのみで構成され、障害時はAWS側が新しいVPN接続を自動的に再作成する','VPN接続の可用性はAWS Direct Connectと組み合わせない限り確保できない','カスタマーゲートウェイ機器の障害に対しても、1つのVPN接続だけで自動的に保護される'], correct:[0],
    why:['正しい。1つのSite-to-Site VPN接続は異なるアベイラビリティーゾーンで終端する2本のトンネルで構成され、AWS側の障害時は自動的にもう一方のトンネルにフェイルオーバーします。','誤り。1つのVPN接続は最初から2本のトンネルで構成されています。','誤り。Direct Connectと組み合わせなくても、2本のトンネル構成自体でAWS側の障害に対する可用性は確保されます。','誤り。カスタマーゲートウェイ機器(利用者側)の障害に対しては、別のカスタマーゲートウェイを使った2つ目のVPN接続を追加する必要があります。']},
  {id:'p512', domain:'tech', type:'single', source:SOURCES.prometheus, text:'すでにAmazon EKSや自己管理のKubernetes環境で、オープンソースのPrometheusと同じPromQLクエリ言語・データモデルを使ってコンテナのメトリクスを監視しているチームが、運用管理の負担を減らしつつ同じ仕組みをAWS上で使い続けたい場合、最も適したサービスはどれですか？',
    choices:['Amazon CloudWatch Logs','Amazon Managed Service for Prometheus','Amazon OpenSearch Service','AWS X-Ray'], correct:[1],
    why:['誤り。CloudWatch Logsはログの収集・保存サービスで、PromQLと同じクエリ言語・データモデルは提供しません。','正しい。Amazon Managed Service for Prometheusは、オープンソースのPrometheusと同じPromQLクエリ言語・データモデルをそのまま使える、サーバーレスのマネージド型モニタリングサービスです。','誤り。OpenSearch Serviceは全文検索・ログ分析サービスで、PromQL互換ではありません。','誤り。X-Rayは分散トレーシングサービスで、メトリクス監視のためのPromQL互換サービスではありません。']},
  {id:'p513', domain:'tech', type:'multi', source:SOURCES.grafana, text:'Amazon Managed Grafanaのワークスペースにユーザーがサインインする際の認証方法として正しいものを2つ選択してください。',
    choices:['AWS IAM Identity Center(旧AWS SSO)と連携してサインインする','IAMユーザーのアクセスキー・シークレットキーを使ってサインインする','SAML 2.0に対応した外部IDプロバイダーと連携してサインインする','Amazon Cognitoのユーザープールにのみ対応し、他の方法は利用できない'], correct:[0,2],
    why:['正しい。Amazon Managed Grafanaのワークスペースは、AWS IAM Identity Centerと連携したサインインに対応しています。','誤り。GrafanaワークスペースへのユーザーサインインはIAMユーザーのアクセスキーではなく、IAM Identity CenterまたはSAML 2.0経由のシングルサインオンで行います。','正しい。SAML 2.0に対応した外部IDプロバイダーと連携したサインインにも対応しています。','誤り。Cognitoユーザープール専用ではなく、IAM Identity CenterまたはSAML 2.0のいずれか(または両方)を使用します。']},
  {id:'p514', domain:'tech', type:'single', source:SOURCES.codeartifact, text:'複数の開発チームが、npmやPyPI、Maven Centralなどの公開パッケージリポジトリに依存するプロジェクトを開発している。これらの公開パッケージを、社内の共通リポジトリ経由でキャッシュしつつ取得できるようにし、各開発者が直接インターネット上の公開リポジトリにアクセスする必要をなくしたい場合、AWS CodeArtifactのどの機能を使いますか？',
    choices:['ドメイン(Domain)','アセットのバージョニング','パッケージのステータス管理(公開/非公開の切り替え)','外部接続(External Connection)を使ったアップストリームリポジトリの設定'], correct:[3],
    why:['誤り。ドメインは複数のリポジトリをまとめる論理的なコンテナであり、公開リポジトリとの接続機能ではありません。','誤り。アセットのバージョニングはパッケージバージョンの管理機能で、外部リポジトリとの接続機能ではありません。','誤り。パッケージの公開/非公開のステータス管理は、外部リポジトリとの接続機能ではありません。','正しい。CodeArtifactリポジトリに外部接続(External Connection)を設定すると、npmjs・PyPI・Maven Centralなどの公開リポジトリにあるパッケージを、リクエスト時に取得してキャッシュできます。']},
  {id:'p515', domain:'tech', type:'single', source:SOURCES.amazonMQ, text:'オンプレミスで稼働中のApache ActiveMQベースのアプリケーションをAmazon MQに移行する際、開発・テスト用途で可用性の要件は低いが、できるだけシンプルな構成で始めたい場合に選択するデプロイモードはどれですか？',
    choices:['シングルインスタンスブローカー(単一のアベイラビリティーゾーンで稼働する1台のブローカー)','アクティブ/スタンバイのマルチAZブローカー(異なるAZで稼働する2台のブローカーの冗長構成)','Amazon ECS上でのセルフマネージドクラスター構成','オンプレミスのブローカーをAWS Direct Connect経由でそのまま利用し続ける構成'], correct:[0],
    why:['正しい。シングルインスタンスブローカーは単一AZで稼働する1台の構成で、開発・テスト用途などシンプルな構成に向いています(高可用性は提供されません)。','誤り。アクティブ/スタンバイのマルチAZブローカーは高可用性が必要な本番用途向けの構成で、2台のブローカーが必要です。','誤り。Amazon MQはAWSが管理するマネージド型サービスであり、ECS上でのセルフマネージドクラスター構成という選択肢はありません。','誤り。Amazon MQはAWS上で稼働するマネージド型ブローカーを新規に作成するサービスであり、オンプレミスのブローカーをそのまま使う機能ではありません。']},
  {id:'p516', domain:'tech', type:'single', source:SOURCES.resourceExplorer, text:'複数のAWSリージョン・複数のAWSアカウントにまたがって作成されたリソース(EC2インスタンス、DynamoDBテーブルなど)を、名前やタグ、IDなどで検索エンジンのように横断的に検索したい場合、最も適したサービスはどれですか？',
    choices:['AWS Resource Groups','AWS Resource Explorer','AWS Config','AWS Systems Manager'], correct:[1],
    why:['誤り。AWS Resource Groupsは、タグやCloudFormationスタックに基づいてリソースをグループ化する機能であり、検索エンジンのような横断検索機能ではありません。','正しい。AWS Resource Explorerは、複数のリージョン・アカウントにまたがるリソースを、名前やタグ、IDなどのメタデータを使って検索エンジンのような体験で検索できるサービスです。','誤り。AWS Configはリソースの構成変更履歴の記録・評価サービスで、検索エンジンのような横断検索機能ではありません。','誤り。AWS Systems Managerはインスタンスの運用管理が主な役割で、リソースの横断検索機能ではありません。']},
  {id:'p517', domain:'billing', type:'single', source:SOURCES.organizations, text:'AWS Organizationsにおいて、複数のAWSアカウントのうち「管理アカウント(Management Account)」自身を組織から外したい場合、正しい方法はどれですか？',
    choices:['管理アカウントの管理者がLeaveOrganization APIを呼び出す','他のメンバーアカウントの管理者が、管理アカウントを組織から削除(Remove)する','組織(Organization)自体を削除(DeleteOrganization)する','管理アカウントの役割を一時的に他のメンバーアカウントに委任(Delegated Administrator)してから退出する'], correct:[2],
    why:['誤り。LeaveOrganization APIはメンバーアカウントが組織から退出するための操作で、管理アカウントはこの方法では退出できません。','誤り。メンバーアカウントの管理者には、管理アカウントを削除する権限はありません。','正しい。管理アカウントを組織から外すには、組織自体を削除(DeleteOrganization)する必要があります。','誤り。委任管理者(Delegated Administrator)は特定のAWSサービスの管理権限を他のメンバーアカウントに委任する仕組みであり、管理アカウント自体の退出方法ではありません。']},
  {id:'p518', domain:'billing', type:'single', source:SOURCES.marketplace, text:'AWS Marketplaceで、あるソフトウェア販売者(セラー)が特定の購入者(バイヤー)のAWSアカウントに対してのみ、カスタムの価格やEULA(使用許諾契約)を提示したい場合に使用する機能はどれですか？',
    choices:['プライベートオファー(Private Offer)','コンソリデーティッドビリング(Consolidated Billing)','AWS Billing Conductor','Savings Plans'], correct:[0],
    why:['正しい。プライベートオファーは、セラーが特定の購入者のAWSアカウントに対してのみ、カスタムの価格やEULAなどの条件を提示できる機能です。提示されたオファーには有効期限があります。','誤り。コンソリデーティッドビリングは組織内の複数アカウントの請求を一括管理する機能で、販売者と購入者間の個別の価格提示機能ではありません。','誤り。AWS Billing Conductorは請求のカスタマイズ(プロフォーマ請求)を行うサービスで、Marketplaceの個別オファー機能ではありません。','誤り。Savings Plansはコンピューティング利用料金の割引プログラムで、サードパーティ製品の個別オファー機能ではありません。']},
  {id:'p519', domain:'concepts', type:'single', source:SOURCES.slaLegal, text:'あるAWSサービスについて、AWSが提示する「SLA(Service Level Agreement)」の役割として最も適切なものはどれですか？',
    choices:['AWSが保証する稼働率などの水準を契約として定め、満たせなかった場合に利用者がサービスクレジットなどの補償を申請できるようにする','利用者が許容できる最大のデータ損失量を、利用者自身が事前に定義する','利用者が許容できる障害復旧までの最大時間を、利用者自身が事前に定義する','AWSのサポートプランごとの応答時間を定める'], correct:[0],
    why:['正しい。SLAはAWSが対象サービスの稼働率などについて保証する契約で、満たせなかった場合は利用者がサービスクレジット等の補償を申請できます。','誤り。これはRPO(目標復旧時点)の説明です。利用者側が定義する指標であり、AWSが提示するSLAとは異なります。','誤り。これはRTO(目標復旧時間)の説明です。利用者側が定義する指標であり、AWSが提示するSLAとは異なります。','誤り。サポートプランの応答時間はサポート契約の一部であり、個々のサービスのSLA(稼働率保証)とは別の仕組みです。']},
  {id:'p520', domain:'concepts', type:'single', source:SOURCES.hybridCloud, text:'ある企業が、AWSに加えて他社のクラウドプロバイダーのサービスも組み合わせて、それぞれの得意分野を活かしながら運用したいと考えています。このようなクラウドのデプロイモデルを何と呼びますか？',
    choices:['ハイブリッドクラウド','マルチクラウド','プライベートクラウド','パブリッククラウド'], correct:[1],
    why:['誤り。ハイブリッドクラウドは、オンプレミス環境とクラウド環境を組み合わせる形態を指し、複数のクラウドプロバイダーを組み合わせる形態とは異なります。','正しい。複数の異なるクラウドプロバイダーのサービスを組み合わせて利用する形態は「マルチクラウド」と呼ばれます。','誤り。プライベートクラウドは単一の組織専用の環境を指し、複数プロバイダーの組み合わせとは異なります。','誤り。パブリッククラウドは単一のクラウドプロバイダーが提供する、複数の組織が共有する環境を指します。']},
  {id:'p521', domain:'concepts', type:'multi', source:SOURCES.wafReliability, text:'Amazon S3の「99.999999999%(イレブンナイン)」という数値と、サービスの「可用性(Availability)」に関する説明として正しいものを2つ選択してください。',
    choices:['S3の99.999999999%は、保存したオブジェクトが失われない確率(耐久性/Durability)を表す数値であり、サービスが使える時間の割合(可用性)を表すものではない','耐久性(Durability)と可用性(Availability)は同じ概念であり、どちらも「サービスが使える時間の割合」を表す','S3のSLAで保証される月間稼働率(可用性)は、耐久性の数値(イレブンナイン)とは別に、個別にパーセンテージで定められている','可用性が99.999999999%あれば、データが失われることは絶対にない'], correct:[0,2],
    why:['正しい。S3の99.999999999%(イレブンナイン)は、保存したオブジェクトが失われない確率である「耐久性(Durability)」を表す数値であり、サービスを利用できる時間の割合である「可用性(Availability)」とは異なる概念です。','誤り。耐久性(データが失われない性質)と可用性(サービスが使える時間の割合)は異なる概念です。','正しい。S3のSLAで保証される稼働率(可用性)は、耐久性のイレブンナインとは別の指標として、月間稼働率のパーセンテージで個別に定められています。','誤り。可用性の数値はサービスが使える時間の割合を表すものであり、データの耐久性(損失確率)を表すものではありません。']},
  {id:'p522', domain:'security', type:'single', source:SOURCES.iam, text:'ある企業で、開発者ごとにIAMユーザーを作成する際、各開発者には担当するプロジェクトのS3バケットとLambda関数の操作権限だけを付与し、他のプロジェクトのリソースにはアクセスできないようにしたいと考えています。このような権限設計の考え方を何と呼びますか？',
    choices:['責任共有モデル','コンソリデーティッドビリング(一括支払い)','最小権限の原則(Principle of Least Privilege)','多要素認証(MFA)'], correct:[2],
    why:['誤り。責任共有モデルはAWSと利用者の間での責任範囲の分担を表す考え方であり、個々のユーザーへの権限付与の設計方針ではありません。','誤り。コンソリデーティッドビリングは複数アカウントの請求を一括管理する仕組みであり、権限設計とは無関係です。','正しい。最小権限の原則は、ユーザーやアプリケーションに対して、タスクの実行に必要な最小限の権限だけを付与する設計の考え方です。','誤り。MFAはログイン時の追加認証の仕組みであり、権限の範囲を決める設計方針ではありません。']},
  {id:'p523', domain:'security', type:'single', source:SOURCES.securityLake, text:'ある企業が、Amazon Security Lakeに集約されたセキュリティログを、新たなデータ取り込みパイプラインを構築せずに、Amazon Athenaを使ってSQLで直接分析したいと考えています。Security Lakeのサブスクライバーアクセスの仕組みとして正しいものはどれですか？',
    choices:['Security Lakeのデータは常にAmazon RDSに格納され、JDBC接続でのみ分析できる','サブスクライバーは必ずS3オブジェクトのコピーを自分のアカウントに作成してから分析する必要がある','Security Lakeのデータへのアクセスは、Amazon QuickSightからのみ許可されている','Security LakeはAWS Lake Formationのテーブルとしてデータを管理しており、サブスクライバーに「クエリアクセス」を許可することで、Amazon AthenaなどからSQLで直接クエリできる'], correct:[3],
    why:['誤り。Security Lakeのデータは利用者自身のアカウント内のAmazon S3にApache Parquet形式で格納されます。','誤り。「クエリアクセス」を許可された場合、S3オブジェクトのコピーを作成しなくても、Lake Formationのテーブルを経由してその場でクエリできます(コピーが必要なのは「データアクセス」方式の場合です)。','誤り。QuickSightに限らず、Amazon AthenaやAmazon Redshift Spectrumなど複数の分析サービスからアクセスできます。','正しい。Security LakeはAWS Lake Formationでテーブルを管理しており、サブスクライバーに「クエリアクセス」を許可すると、Amazon Athena等からSQLで直接データをクエリできます。']},
  {id:'p524', domain:'security', type:'single', source:SOURCES.signer, text:'ある企業が、AWS Signerで署名したLambdaのデプロイパッケージについて、後からビルドプロセスの秘密鍵が漏洩していたことが判明したため、その署名プロファイルで行われた署名を無効化し、今後そのプロファイルで新たな署名ができないようにしたいと考えています。使用すべき機能はどれですか？',
    choices:['AWS Signerの署名プロファイルの失効(Revoke Signing Profile)。指定した有効時刻以降に行われた署名は信頼されなくなり、そのプロファイルは新たな署名ジョブに使用できなくなる','AWS KMSのキーの無効化(Disable Key)','AWS Certificate Managerでの証明書の失効(Revoke Certificate)','IAMユーザーのアクセスキーのローテーション'], correct:[0],
    why:['正しい。AWS Signerでは署名プロファイルを失効(Revoke)させることができ、指定した有効時刻以降に行われた署名は信頼されなくなり、そのプロファイル自体も新たな署名ジョブには使用できなくなります。','誤り。AWS KMSのキー無効化は暗号化キーの無効化であり、AWS Signerの署名プロファイルとは別の仕組みです。','誤り。ACMの証明書失効はSSL/TLS証明書に対する操作であり、Signerのコード署名プロファイルとは異なります。','誤り。アクセスキーのローテーションはIAMユーザーの認証情報の更新であり、すでに行われた署名プロファイルの失効には対応できません。']},
  {id:'p525', domain:'security', type:'single', source:SOURCES.rolesAnywhere, text:'AWS IAM Roles Anywhereにおいて、「トラストアンカー(Trust Anchor)」の役割として正しいものはどれですか？',
    choices:['オンプレミスのサーバーに発行する、長期的なIAMアクセスキーそのもの','AWS Private CAまたは外部の認証局(CA)の証明書を登録することで、その認証局が発行したX.509証明書を信頼する基点として機能する設定','IAMユーザーのパスワードポリシーを定義する設定','VPC内の通信を暗号化するためのTLS終端ポイント'], correct:[1],
    why:['誤り。トラストアンカーは長期アクセスキーそのものではなく、信頼する認証局を登録する設定です。Roles Anywhereを使う目的はむしろ長期アクセスキーを不要にすることです。','正しい。トラストアンカーは、AWS Private CAまたは外部のCAの証明書を登録することで、その認証局が発行したX.509証明書をAWS側が信頼するための基点となる設定です。','誤り。パスワードポリシーはIAMユーザーに関する設定であり、Roles Anywhereのトラストアンカーとは無関係です。','誤り。トラストアンカーはTLS終端ポイントではなく、証明書発行元を信頼するための設定です。']},
  {id:'p526', domain:'tech', type:'single', source:SOURCES.cloudMap, text:'マイクロサービス構成のアプリケーションで、ECSタスクやEC2インスタンスなど動的に増減するバックエンドサービスの場所を、各サービスにハードコーディングせずに、API呼び出しやDNSクエリで動的に検出(サービスディスカバリー)できるようにしたい場合、最も適したサービスはどれですか？',
    choices:['Amazon Route 53(パブリックホストゾーンでの静的なDNSレコード管理)','AWS App Mesh','AWS Cloud Map','AWS Resource Groups'], correct:[2],
    why:['誤り。Route 53の通常のDNSレコードは静的な設定が基本で、バックエンドリソースの動的な登録・解除・ヘルスチェックに基づく検出には、サービスディスカバリー専用のAWS Cloud Mapが適しています。','誤り。AWS App Meshはサービスメッシュによる通信制御・可観測性のためのサービスで、サービスディスカバリーのための名前解決の仕組み自体ではありません。','正しい。AWS Cloud Mapは、ECSタスクやEC2インスタンスなど動的に変化するリソースに論理的な名前を登録し、API呼び出しやDNSクエリで動的に検出できるようにするサービスディスカバリーサービスです。ヘルスチェックに対応し、正常なリソースのみを返します。','誤り。AWS Resource Groupsはタグ等でリソースをグループ化して一括操作する機能であり、アプリケーションからの動的なサービスディスカバリー機能ではありません。']},
  {id:'p527', domain:'tech', type:'single', source:SOURCES.iotSitewise, text:'工場内の製造装置から温度・圧力・稼働状況などのデータを継続的に収集し、装置やプロセスを表す「アセットモデル」として整理した上で、総合設備効率(OEE)などの指標をダッシュボードで監視したい場合、最も適したサービスはどれですか？',
    choices:['AWS IoT Device Defender','AWS IoT Greengrass','Amazon Managed Service for Prometheus','AWS IoT SiteWise'], correct:[3],
    why:['誤り。AWS IoT Device Defenderは、IoTデバイスのセキュリティ監査・異常検知を行うサービスで、産業設備のデータ収集・指標監視を主目的とはしません。','誤り。AWS IoT Greengrassは、エッジデバイス上でソフトウェアを実行・管理するためのサービスで、産業データを「アセットモデル」として整理する機能そのものではありません。','誤り。Amazon Managed Service for Prometheusは、コンテナ環境などの運用メトリクスの収集・保存サービスであり、産業設備専用のアセットモデリング機能は提供しません。','正しい。AWS IoT SiteWiseは、産業設備からのデータを収集・整理し、装置やプロセスを表す「アセットモデル」として構造化した上で、SiteWise Monitorを使ってOEEなどの指標をほぼリアルタイムにダッシュボードで監視できるサービスです。']},
  {id:'p528', domain:'tech', type:'single', source:SOURCES.appstream, text:'自社で開発した複数のWindowsデスクトップアプリケーションについて、ユーザーの端末に個別にインストールさせることなく、ブラウザ経由でセッションごとにストリーミング配信し、使用後は自動的に環境を初期化したいと考えています。最も適したサービスはどれですか？',
    choices:['Amazon WorkSpaces Applications（旧Amazon AppStream 2.0）','Amazon WorkSpaces(仮想デスクトップ環境全体の提供、DaaS)','AWS Transfer Family','AWS Client VPN'], correct:[0],
    why:['正しい。Amazon WorkSpaces Applications（旧Amazon AppStream 2.0）は、個別のデスクトップアプリケーションをユーザーの端末にインストールせず、セッションごとにブラウザへストリーミング配信できるサービスで、使用後のセッション終了時に環境を初期化する運用が可能です。','誤り。Amazon WorkSpacesは、個別アプリではなく仮想デスクトップ環境全体(DaaS)を提供するサービスです。','誤り。AWS Transfer Familyは、SFTP/FTPS等のプロトコルでファイル転送を行うマネージドサービスであり、アプリケーションのストリーミング配信機能ではありません。','誤り。AWS Client VPNはリモートアクセスVPNサービスであり、アプリケーションのストリーミング配信機能ではありません。']},
  {id:'p529', domain:'tech', type:'multi', source:SOURCES.cloudMap, text:'AWS Cloud Mapの特徴として正しいものを2つ選択してください。',
    choices:['DNSクエリでの検出には対応しておらず、API呼び出し(DiscoverInstances)のみで利用できる','ヘルスチェックを設定すると、正常(Healthy)と判定されたリソースのインスタンスのみを検出結果として返す','Amazon EC2インスタンスのみを登録対象とし、コンテナやデータベース、キューなどは登録できない','Amazon DynamoDBテーブルやAmazon SQSキューなど、IPアドレスを持たないリソースもサービスインスタンスとして登録できる'], correct:[1,3],
    why:['誤り。AWS Cloud MapはAPI呼び出し(DiscoverInstances)に加えて、VPC内のDNSクエリやパブリックDNSクエリでの検出にも対応しています。','正しい。ヘルスチェック(Amazon Route 53のヘルスチェックまたはサードパーティのヘルスチェック)を設定すると、Cloud Mapは正常と判定されたリソースのみを検出結果として返します。','誤り。EC2インスタンスだけでなく、ECSタスク、DynamoDBテーブル、SQSキューなど、IPアドレスを持たないリソースを含め幅広く登録できます。','正しい。Amazon DynamoDBテーブルやAmazon SQSキューのように、IPアドレスを持たないリソースについても、エンドポイント情報(ARN等)をサービスインスタンスとして登録し、API経由で検出できます。']},
  {id:'p530', domain:'billing', type:'single', source:SOURCES.riMarketplace, text:'Amazon EC2 Reserved Instance Marketplaceで、保有しているStandard Reserved Instanceを出品・売却する際のルールとして正しいものはどれですか？',
    choices:['リージョナルスコープのStandard RIのみが出品対象で、ゾーナルスコープのStandard RIは出品できない','リージョナルスコープ・ゾーナルスコープのいずれのStandard RIも出品対象となり、売却が成立すると、売却価格(アップフロント価格)に対してAWSへ12%のサービス料が課される','出品には手数料は一切発生せず、売却代金の全額がそのまま売り手に支払われる','購入したばかりのStandard RIも、契約成立直後からすぐに出品できる'], correct:[1],
    why:['誤り。リージョナルスコープ・ゾーナルスコープのいずれのStandard RIも出品対象です。','正しい。Reserved Instance Marketplaceでは、リージョナル・ゾーナルいずれのスコープのStandard RIも出品対象となり、売却が成立した場合、売り手が設定したアップフロント価格に対してAWSへ12%のサービス料が課されます。','誤り。売却が成立した場合、アップフロント価格に対して12%のサービス料が発生します。','誤り。出品するには、アカウント内でアクティブになってから最低30日が経過していることと、契約の残り期間が1か月以上あることが必要です。']},
  {id:'p531', domain:'billing', type:'single', source:SOURCES.riMarketplace, text:'Amazon EC2 Reserved Instance Marketplaceで、ある企業が売り手としてリザーブドインスタンスを出品しようとしています。売り手としての登録・出品に関する制限として正しいものはどれですか？',
    choices:['一つのAWSアカウントで売却できるリザーブドインスタンスの金額・件数に上限はない','Amazon EC2のConvertible Reserved Instanceも、Standard Reserved Instanceと同様に出品できる','売り手として登録するには米国の住所を持つ銀行口座が必要であり、アカウントの生涯で売却できる総額または件数には上限(いずれか先に達した時点まで)が設定されている','Amazon RDSやAmazon ElastiCacheの予約インスタンスも、EC2と同じ市場で出品できる'], correct:[2],
    why:['誤り。1アカウントが生涯で売却できる総額または件数には上限が設定されています。','誤り。Convertible Reserved InstanceはReserved Instance Marketplaceでは出品できません。出品できるのはStandard Reserved Instanceのみです。','正しい。売り手として登録するには米国の住所を持つ銀行口座が必要で、1アカウントが生涯で売却できる総額または件数には上限(いずれか先に達した時点まで)が設定されています。','誤り。出品できるのはAmazon EC2のStandard Reserved Instanceのみで、RDSやElastiCacheの予約インスタンスは出品できません。']},
  {id:'p532', domain:'concepts', type:'single', source:SOURCES.serviceQuotas, text:'ある企業が、1つのリージョンで作成できるVPCの数の上限に達してしまい、追加のVPCを作成できなくなりました。この上限を引き上げるために利用すべきAWSのサービスはどれですか？',
    choices:['AWS Trusted Advisor','AWS Service Quotas','AWS Config','AWS Organizations'], correct:[1],
    why:['誤り。Trusted Advisorはベストプラクティスのチェックを行うサービスであり、クォータの引き上げリクエスト自体はできません。','正しい。Service Quotasは各サービスのクォータ(上限値)を確認し、引き上げ可能なクォータについてはリクエストを申請できるサービスです。','誤り。Configはリソース設定の変更履歴を記録・評価するサービスであり、クォータ管理とは無関係です。','誤り。Organizationsは複数アカウントの統合管理サービスであり、個々のサービスのクォータ引き上げはできません。']},
  {id:'p533', domain:'concepts', type:'single', source:SOURCES.sixAdv, text:'「弾力性(Elasticity)」と「スケーラビリティ(Scalability)」の違いを説明したものとして最も適切なものはどれですか？',
    choices:['弾力性は需要の増減に応じてリソースを自動的に増減させる短期的な仕組みを指し、スケーラビリティは需要の増加に合わせてリソースを拡張し続けられる能力を指す。両者は密接に関連するが同義ではない','弾力性とスケーラビリティは完全に同じ意味であり、置き換えて使っても問題ない','弾力性はデータの耐久性を表し、スケーラビリティは可用性を表す','弾力性はセキュリティの強度を表し、スケーラビリティは料金の安さを表す'], correct:[0],
    why:['正しい。弾力性は需要の変化に応じてリソースを自動的に増減する(スケールイン・スケールアウト)仕組みを、スケーラビリティは需要増加に合わせてリソースを拡張しパフォーマンスを維持できる能力を指し、関連はしますが同一の概念ではありません。','誤り。両者は関連する概念ですが、指す範囲が異なるため同義ではありません。','誤り。これらは耐久性(Durability)・可用性(Availability)の説明であり、弾力性・スケーラビリティとは異なります。','誤り。弾力性・スケーラビリティはセキュリティや料金の指標ではありません。']},
  {id:'p534', domain:'concepts', type:'single', source:SOURCES.awsHealth, text:'AWS Healthが提供する2種類の情報のうち、「自分のAWSアカウントのリソースに影響する可能性がある事象」を通知する機能は何と呼ばれますか？',
    choices:['AWS Service Health Dashboard（全利用者向けの一般的なサービス状況）','AWS Personal Health Dashboard（アカウント固有のイベント通知）','AWS Trusted Advisor（ベストプラクティスチェック）','AWS Budgets（予算超過の通知）'], correct:[1],
    why:['誤り。Service Health Dashboardは全利用者向けにAWSサービス全体の稼働状況を公開するもので、自分のアカウント固有の情報ではありません。','正しい。AWS Healthは、自分のアカウントのリソースに影響しうるイベント（メンテナンス予定や障害など）をPersonal Health Dashboardを通じて個別に通知します。','誤り。Trusted Advisorはコスト・パフォーマンス等のベストプラクティスをチェックするサービスで、アカウント固有の障害通知とは異なります。','誤り。Budgetsは予算額に対する使用状況の通知であり、サービスイベントの通知とは異なります。']},
  {id:'p535', domain:'security', type:'single', source:SOURCES.shield, text:'AWS Shield Advancedの「コスト保護(Cost Protection)」機能について正しい説明はどれですか？',
    choices:['DDoS攻撃によってEC2・ELB・CloudFront・Route 53などのリソースがスケールアウトし、その結果として発生した使用量増加分の料金についてクレジットを申請できる機能','AWS全体の月額利用料金に一律の割引を適用する機能','リザーブドインスタンスの購入費用を保護する機能','S3のストレージ費用を自動的に最適化する機能'], correct:[0],
    why:['正しい。Shield Advancedのコスト保護は、DDoS攻撃を受けた保護対象リソースがスケールアウトしたことで発生した使用量増加分の料金について、サービスクレジットを申請できる機能です。','誤り。コスト保護は特定のDDoS攻撃に起因する費用増加分が対象であり、全体への一律割引ではありません。','誤り。リザーブドインスタンスの購入費用とは無関係です。','誤り。S3のストレージコスト最適化はS3 Intelligent-Tiering等の役割であり、Shield Advancedの機能ではありません。']},
  {id:'p536', domain:'security', type:'single', source:SOURCES.cloudhsm, text:'AWS CloudHSMがAWS KMSと異なる最大の特徴は何ですか？',
    choices:['FIPS 140-2レベル3検証済みの専有（シングルテナント）のハードウェアセキュリティモジュールを提供し、顧客がハードウェアを排他的に制御できる点','鍵の保管・管理を完全に無料で提供する点','鍵のローテーションを一切サポートしない点','S3のデータ保存にのみ利用できる点'], correct:[0],
    why:['正しい。CloudHSMは、FIPS 140-2レベル3検証済みの専有(シングルテナント)HSMを提供し、顧客がハードウェアを排他的に制御できる点がマルチテナントで運用されるKMSとの大きな違いです。','誤り。CloudHSMはクラスター単位で課金される有料サービスです。','誤り。CloudHSM内の鍵についても、利用者自身でローテーションを管理できます。','誤り。CloudHSMはS3に限らず、KMSでは満たせない厳格なコンプライアンス要件を持つ様々な用途の暗号鍵管理に利用できます。']},
  {id:'p537', domain:'security', type:'multi', source:SOURCES.guardduty, text:'Amazon GuardDutyが提供する保護プラン(Protection Plan)として正しいものを2つ選択してください。',
    choices:['EKS Protection（Kubernetesの監査ログ等を分析する機能）','RDS Protection（データベースへの不審なログインアクティビティ等を検知する機能）','ラウンドロビン保護（DNSの負荷分散を監視する機能）','アクティブ-アクティブ保護（複数リージョンの同時稼働を監視する機能）'], correct:[0,1],
    why:['正しい。EKS ProtectionはAmazon EKSの監査ログやランタイムの挙動を分析し、不審なアクティビティを検知する保護プランです。','正しい。RDS Protectionはデータベースへのログインアクティビティを分析し、侵害の兆候を検知する保護プランです。','誤り。「ラウンドロビン保護」はGuardDutyの保護プラン名ではなく、架空の名称です。','誤り。「アクティブ-アクティブ保護」はGuardDutyの保護プラン名ではなく、架空の名称です。']},
  {id:'p538', domain:'tech', type:'single', source:SOURCES.codebuild, text:'AWS CodeBuildとAWS CodePipelineの役割の違いとして正しいものはどれですか？',
    choices:['CodeBuildはソースコードのビルド・テストを実行するサービスであり、CodePipelineはソース取得からビルド・デプロイまでのリリースプロセス全体を自動化するワークフローを管理するサービスである','CodeBuildとCodePipelineは全く同じ機能を提供する','CodeBuildはEC2インスタンスの起動を行うサービスであり、CodePipelineはS3へのファイルアップロードを行うサービスである','CodeBuildはDNSの管理を行うサービスであり、CodePipelineはネットワーク監視を行うサービスである'], correct:[0],
    why:['正しい。CodeBuildはビルド・テストの実行に特化したサービスで、CodePipelineはソース取得・ビルド・デプロイといった複数のステージを連携させたリリースパイプライン全体のワークフローを管理します。','誤り。両者は異なる役割を持つサービスです。','誤り。これはAmazon EC2やAmazon S3の説明であり、CodeBuild・CodePipelineの役割ではありません。','誤り。これはAmazon Route 53やAmazon CloudWatchの説明であり、CodeBuild・CodePipelineの役割ではありません。']},
  {id:'p539', domain:'tech', type:'multi', source:SOURCES.route53, text:'Amazon Route 53が提供する正式なルーティングポリシーとして正しいものを2つ選択してください。',
    choices:['ヘルスチェック（ルーティングポリシーではなく、エンドポイントの正常性を監視する付随機能）','加重（Weighted）ルーティング：指定した比率でトラフィックを複数リソースに分配する','レイテンシーベースルーティング：ユーザーに最も低いレイテンシーを提供できるリージョンのリソースへ振り分ける','ラウンドロビン（Route 53の正式なルーティングポリシー名ではなく、一般的なDNS用語）'], correct:[1,2],
    why:['誤り。ヘルスチェックはルーティングポリシーの判断材料として使われる付随機能であり、ルーティングポリシーそのものではありません。','正しい。加重ルーティングは、指定した比率に基づいてトラフィックを複数のリソースへ分配する正式なルーティングポリシーです。','正しい。レイテンシーベースルーティングは、ユーザーに最も低いレイテンシーを提供できるリージョンのリソースへトラフィックを振り分ける正式なルーティングポリシーです。','誤り。「ラウンドロビン」はRoute 53の正式なルーティングポリシー名ではなく、一般的なDNSの負荷分散手法を指す用語です。']},
  {id:'p540', domain:'tech', type:'single', source:SOURCES.eventbridge, text:'定期的（例: 毎日午前3時）にLambda関数を実行したい場合に、Amazon EventBridgeが提供する機能として適切なものはどれですか？',
    choices:['EventBridge Scheduler：cron式またはrate式で指定したスケジュールに基づき、サーバーレスでターゲットを定期的または1回限り呼び出せる機能','EventBridgeはイベント駆動のみに対応しており、時刻ベースのスケジュール実行はサポートしていない','EC2インスタンスを常時起動し続けてcronジョブを実行する機能','S3バケットのライフサイクルルールを設定する機能'], correct:[0],
    why:['正しい。EventBridge Schedulerは、cron式やrate式で指定したスケジュールに基づいて、Lambda関数などのターゲットをサーバーレスで定期的または1回限り呼び出せる機能です。','誤り。EventBridgeはイベント駆動のルールに加えて、スケジュールベースの定期実行もサポートしています。','誤り。EC2を常時起動してcronを実行するのはサーバーレスではなく非効率な方法で、EventBridgeの機能ではありません。','誤り。S3のライフサイクルルールはオブジェクトの保存期間管理機能であり、定期実行とは無関係です。']},
  {id:'p541', domain:'tech', type:'single', source:SOURCES.athena, text:'あるデータ分析チームが、Amazon S3に保存されたログファイルに対してインフラを構築せずにSQLクエリを直接実行したいと考えています。一方、別のチームは、大量の構造化データを継続的に格納し高速なBIレポート集計を行うデータウェアハウスを必要としています。それぞれに最も適したサービスの組み合わせはどれですか？',
    choices:['両方ともAmazon Redshiftを使うべきである','前者にはAmazon Athena（S3上のデータに対するサーバーレスなSQLクエリサービス）、後者にはAmazon Redshift（高速な集計に最適化されたデータウェアハウス）が適している','両方ともAmazon Athenaを使うべきである','前者にはAmazon Redshift、後者にはAmazon Athenaが適している'], correct:[1],
    why:['誤り。S3上のログに対するアドホックなSQLクエリには、インフラ構築が不要なAthenaの方が適しています。','正しい。Athenaはサーバーレスでインフラ管理不要なS3への直接クエリに、Redshiftは大量データの継続的格納と高速な集計に最適化されたデータウェアハウスとして適しています。','誤り。継続的なデータウェアハウスとしての用途にはAthenaよりRedshiftの方が適しています。','誤り。用途が逆です。アドホックなS3クエリにはAthena、データウェアハウス用途にはRedshiftが適しています。']},
  {id:'p542', domain:'tech', type:'single', source:SOURCES.dedicatedHosts, text:'ソケット単位でライセンスされたソフトウェア（BYOL: Bring Your Own License）をAmazon EC2上で利用したい場合、物理サーバーのソケット数・コア数を可視化でき、BYOLに最も適したEC2の購入オプションはどれですか？',
    choices:['オンデマンドインスタンス','スポットインスタンス','Dedicated Host（専有ホスト）','リザーブドインスタンス'], correct:[2],
    why:['誤り。オンデマンドインスタンスでは物理サーバーのソケット数・コア数は可視化されず、ソケット単位のBYOLには適していません。','誤り。スポットインスタンスは中断される可能性があり、ソケット単位のBYOLの可視性も提供しません。','正しい。Dedicated Hostは物理サーバーを丸ごと専有し、ソケット数・コア数を可視化できるため、ソケット単位・コア単位のBYOLに最も適した購入オプションです。','誤り。リザーブドインスタンスは料金の割引オプションであり、物理サーバーのソケット数・コア数を可視化する機能はありません。']},
  {id:'p543', domain:'billing', type:'single', source:SOURCES.dedicatedHosts, text:'Amazon EC2のDedicated Hostの利用費用をさらに削減する方法として正しいものはどれですか？',
    choices:['Dedicated Host Reservationを購入することで、オンデマンドのDedicated Host料金と比較して最大70%の割引を受けられる','Dedicated HostはAWS無料利用枠の対象であり、無料で利用できる','Dedicated Hostの料金は常にインスタンス単位で課金されるため、Savings Plansの対象にはならない','Dedicated Hostには割引オプションが一切用意されていない'], correct:[0],
    why:['正しい。Dedicated Host Reservationを購入すると、オンデマンドのDedicated Host料金と比較して最大70%の割引を受けられます。','誤り。Dedicated HostはAWS無料利用枠の対象外であることが公式ドキュメントで明記されています。','誤り。Dedicated Hostはインスタンス単位ではなくホスト単位で課金されます。','誤り。Dedicated Host Reservationという専用の割引購入オプションが用意されています。']},
  {id:'p544', domain:'billing', type:'single', source:SOURCES.consolidatedBilling, text:'AWS Organizationsの一括支払い（Consolidated Billing）を利用している組織において、リザーブドインスタンスやSavings Plansの割引はどのように扱われますか？',
    choices:['割引は購入したメンバーアカウント内でのみ適用され、他のメンバーアカウントの利用には一切適用されない','デフォルトでは、組織内の他のメンバーアカウントの対象利用分にも割引が共有され、組織全体で割引を最大限に活用できる','割引は管理アカウントの利用分にのみ適用され、メンバーアカウントには一切適用されない','割引を共有するには、すべてのメンバーアカウントで個別に同じリザーブドインスタンスを購入する必要がある'], correct:[1],
    why:['誤り。デフォルト設定では、割引は組織内の他のメンバーアカウントの対象利用分にも共有されます。','正しい。一括支払いを利用する組織では、デフォルトでリザーブドインスタンスやSavings Plansの割引が組織内の対象アカウント間で共有され、組織全体として割引を最大限に活用できます。','誤り。管理アカウントに限らず、条件を満たす組織内の利用分に割引が共有されます。','誤り。個別に同じものを購入する必要はなく、割引共有の仕組みによって自動的に適用されます。']},
  {id:'p545', domain:'concepts', type:'single', source:SOURCES.transform, text:'あるIT部門が、老朽化したオンプレミスのメインフレームアプリケーションと、VMware上で稼働する多数の仮想サーバーを、できるだけ人手を介さずにAWSへモダナイゼーション・移行したいと考えています。コードの分析・移行計画の立案・実行までをAIエージェントが支援し、追加料金なしで利用できるサービスはどれですか？',
    choices:['AWS Transform','AWS Application Migration Service (MGN)のみを単独で使用する','AWS CloudFormationでテンプレートを手作業で記述する','Amazon Q Developerのみを使用する'], correct:[0],
    why:['正しい。AWS Transformは、メインフレームやVMware環境、.NETアプリケーションなどのモダナイゼーション・移行作業について、専門分野ごとのAIエージェントがコードの分析・移行計画の立案から実行までを支援するサービスで、利用に追加料金はかかりません。','誤り。AWS MGNはリホスト(サーバーの再ホスト)に特化したサービスで、メインフレームのモダナイゼーションやVMware移行計画全体を単独でカバーするものではありません。','誤り。CloudFormationのテンプレートを手作業で記述する方法は、AIエージェントによる自動化とは異なり、人手による作業が大きく必要になります。','誤り。Amazon Q Developerはソフトウェア開発者向けの生成AIアシスタントであり、メインフレーム・VMwareのインフラ移行全体を計画・実行する専用サービスではありません。']},
  {id:'p546', domain:'concepts', type:'single', source:SOURCES.globalInfra, text:'ミッションクリティカルなアプリケーションを、単一のデータセンター障害によって完全に停止しないように設計したい場合、AWSのグローバルインフラストラクチャにおいて推奨される設計はどれですか？',
    choices:['1つのアベイラビリティーゾーン(AZ)内の1つのデータセンターにすべてのリソースを集約し、冗長化は行わない','同一リージョン内の、地理的に分離され独立した電源・ネットワークを持つ複数のアベイラビリティーゾーン(AZ)にリソースを分散配置する','すべてのリソースをエッジロケーションに配置する','1つのAZ内で、同じデータセンター内に複数のEC2インスタンスを配置する'], correct:[1],
    why:['誤り。単一のAZ・単一のデータセンターに集約すると、そのデータセンターの障害がアプリケーション全体の停止に直結します。','正しい。同一リージョン内の、独立した電源・ネットワーク・冷却設備を持つ複数のAZにリソースを分散配置することで、1つのAZ(データセンター群)で障害が発生してもアプリケーション全体の可用性を維持できます。','誤り。エッジロケーションはCloudFrontなどのコンテンツ配信用のキャッシュ拠点であり、アプリケーション本体の高可用性設計のための配置先ではありません。','誤り。同じデータセンター内に配置する限り、そのデータセンターの障害によって影響を受けるリスクは残ります。']},
  {id:'p547', domain:'concepts', type:'multi', source:SOURCES.globalInfra, text:'新しいワークロードをAWSに展開するにあたり、どのAWSリージョンを選択するかを決める際に考慮すべき要素として正しいものを2つ選択してください。',
    choices:['そのリージョンが地球上で最も標高の高い場所にあるかどうか','エンドユーザーとの間のネットワークレイテンシーを低く抑えられるか(エンドユーザーの地理的な位置に近いか)','そのリージョン内のアベイラビリティーゾーンの数は常に1つに統一されているか','データの保存場所に関する法律・規制(データレジデンシー)の要件を満たせるか'], correct:[1,3],
    why:['誤り。標高はリージョン選択の考慮要素ではありません。','正しい。エンドユーザーに近いリージョンを選ぶことで、ネットワークレイテンシーを低く抑えられます。これはリージョン選択の代表的な考慮要素です。','誤り。リージョンごとのアベイラビリティーゾーンの数は一律ではなく、リージョンによって異なります。','正しい。利用するデータの保存場所に関する法律・規制(データレジデンシー、コンプライアンス要件)を満たせるかは、リージョン選択の重要な考慮要素です。']},
  {id:'p548', domain:'concepts', type:'single', source:SOURCES.hybridCloud, text:'ある企業が、オンプレミスのデータセンターにある既存システムを維持しながら、AWS Direct ConnectやAWS Site-to-Site VPNを使ってオンプレミス環境とAWS VPCを接続し、両方の環境を組み合わせて運用しています。このようなクラウドのデプロイモデルは何と呼ばれますか？',
    choices:['パブリッククラウド','マルチクラウド','ハイブリッドクラウド','プライベートクラウド'], correct:[2],
    why:['誤り。パブリッククラウドは、クラウドプロバイダーが所有・運用し複数の組織が共有する環境のみを指し、オンプレミス環境との接続・組み合わせは含みません。','誤り。マルチクラウドは複数の異なるクラウドプロバイダーを組み合わせる形態であり、オンプレミスとクラウド1社を組み合わせる形態とは異なります。','正しい。オンプレミス環境とクラウド環境を、Direct ConnectやVPNなどで接続して組み合わせて利用する形態は「ハイブリッドクラウド」と呼ばれます。','誤り。プライベートクラウドは単一の組織専用に構築・運用される環境を指し、オンプレミスとパブリッククラウドの組み合わせとは異なる概念です。']},
  {id:'p549', domain:'tech', type:'single', source:SOURCES.xray, text:'複数のマイクロサービスで構成されたアプリケーションにおいて、特定のリクエストが遅延している原因が、どのサービス(コンポーネント)にあるのかを特定したい場合、AWS X-Rayが提供する機能として最も適切なものはどれですか？',
    choices:['各サービスのCPU・メモリ使用率を時系列のグラフで表示する','各サービスのログを全文検索できるようにする','各サービスの利用料金を可視化する','リクエストがどのサービスを経由したかを「サービスマップ」として可視化し、どのサービスで時間がかかっているか(ボトルネック)を直感的に特定できるようにする'], correct:[3],
    why:['これはAmazon CloudWatchメトリクスの説明です。','これはAmazon CloudWatch LogsやOpenSearch Serviceによるログ検索の説明です。','これはAWS Cost Explorerなどのコスト可視化サービスの説明です。','正しい。AWS X-Rayは、リクエストが経由したサービスの経路を「サービスマップ」として可視化し、どのサービスがボトルネックになっているかを直感的に特定できるようにする分散トレーシングサービスです。']},
  {id:'p550', domain:'tech', type:'single', source:SOURCES.natGateway, text:'プライベートサブネット内のEC2インスタンスがインターネットへアウトバウンド通信を行うための仕組みとして、NATゲートウェイを使う場合、NATインスタンス(EC2上に自分で構築するNAT)と比較した特徴として正しいものはどれですか？',
    choices:['AWSによって管理されるマネージド型のサービスであり、OSのパッチ適用などの保守作業が不要で、最大100Gbpsまで自動的にスケールする','NATゲートウェイは必ずプライベートサブネットに配置する必要がある','NATゲートウェイは踏み台(ジャンプ)サーバーとしても利用できる唯一の選択肢である','OSのパッチ適用やスケーリングの設計を利用者自身が行う必要がある'], correct:[0],
    why:['正しい。NATゲートウェイはAWSによって管理されるマネージド型のサービスで、OSのパッチ適用などの保守が不要であり、帯域幅も最大100Gbpsまで自動的にスケールします。','誤り。NATゲートウェイはパブリックサブネットに作成し、Elastic IPを関連付けて使用します。','誤り。NATゲートウェイは踏み台サーバーの機能を提供しません。踏み台サーバーとして使いたい場合はNATインスタンス(EC2)側で構築する必要があります。','誤り。これはNATインスタンス(自分でEC2上に構築するNAT)の特徴であり、NATゲートウェイはAWSが保守・スケーリングを行います。']},
  {id:'p551', domain:'tech', type:'single', source:SOURCES.lex, text:'Amazon ConnectのコンタクトセンターにAIチャットボットを組み込み、顧客の発話内容から「意図(インテント)」を判断し、必要な情報(スロット)が不足している場合は追加の質問をして聞き出し、すべて揃った時点でAWS Lambda関数を呼び出して処理を完了(フルフィルメント)させたい場合、対話エンジンの構築に使うべきサービスはどれですか？',
    choices:['Amazon Polly','Amazon Lex','Amazon Transcribe','Amazon Comprehend'], correct:[1],
    why:['誤り。Amazon Pollyはテキストを音声に変換する(Text-to-Speech)サービスで、対話の意図理解やスロットの管理は行いません。','正しい。Amazon Lexは、ユーザーの発話から「インテント(意図)」を判断し、不足する「スロット(必要な情報)」を対話形式で聞き出し、すべて揃った時点でLambda関数などによる「フルフィルメント(処理の実行)」を行う対話エンジンを構築できるサービスです。Amazon Connectのコンタクトフローに組み込めます。','誤り。Amazon Transcribeは音声をテキストに変換する(Speech-to-Text)サービスで、対話の意図理解自体は行いません。','誤り。Amazon Comprehendはテキストから感情やキーフレーズを抽出する自然言語処理サービスで、対話エンジンそのものではありません。']},
  {id:'p552', domain:'security', type:'single', source:SOURCES.iamIdentityCenter, text:'複数のAWSアカウントを運用する組織において、従業員ごとに「どのAWSアカウントに対して、どのレベルの権限を持たせるか」をIAMポリシーの集合としてテンプレート化し、それをユーザーやグループに割り当てることでアクセス許可を管理したい場合、AWS IAM Identity Centerで使用する仕組みは何ですか？',
    choices:['サービスコントロールポリシー(SCP)','IAMロールの信頼ポリシー','許可セット(Permission Set)','バケットポリシー'], correct:[2],
    why:['誤り。SCPはAWS Organizationsで組織・OU単位に権限の上限(許可できる操作の上限)を設定する仕組みであり、ユーザーごとのアクセス許可の割り当てそのものを管理する仕組みではありません。','誤り。IAMロールの信頼ポリシーは、どのプリンシパルがロールを引き受けられるかを定義するものであり、許可セットのように複数のAWSアカウントへまとめて割り当てる管理単位ではありません。','正しい。IAM Identity Centerの「許可セット(Permission Set)」は、IAMポリシーの集合をテンプレート化したもので、ユーザーやグループに対してAWSアカウントごとに割り当てることでアクセス許可を管理できます。割り当てると、対象アカウントにそのポリシーを持つIAMロールが自動的に作成されます。','誤り。バケットポリシーはAmazon S3バケット単位のリソースベースポリシーであり、複数のAWSアカウントへの権限割り当てを管理する仕組みではありません。']},
  {id:'p553', domain:'security', type:'single', source:SOURCES.accessAnalyzer, text:'あるセキュリティ担当者が、組織内で「過去一定期間使われていないIAMロール」「使われていないアクセスキー」「付与されているが実際には使われていない過剰な権限」を継続的に洗い出し、最小権限化を進めたいと考えています。この目的に適したAWS IAM Access Analyzerの機能は何ですか？',
    choices:['外部アクセス分析(意図しない外部アカウントからのアクセス可否を検出する機能)','ポリシーの基本チェック(IAMポリシーの文法エラーを検出する機能)','カスタムポリシーチェック(組織独自のセキュリティ基準に対するポリシーの適合を検証する機能)','未使用アクセス分析(Unused Access Analysis、未使用のIAMロール・アクセスキー・コンソールパスワード・使われていない権限を継続的に検出する機能)'], correct:[3],
    why:['誤り。外部アクセス分析は、リソースが意図せず外部アカウントや公衆からアクセス可能になっていないかを検出する機能であり、未使用の権限の検出とは異なります。','誤り。基本チェックはポリシーをデプロイする前に文法エラーやベストプラクティス違反を検出する機能で、デプロイ後の利用状況の分析は行いません。','誤り。カスタムポリシーチェックも、ポリシーをデプロイする前に組織独自の基準に適合しているかを検証する機能で、実際の利用状況に基づく分析ではありません。','正しい。未使用アクセス分析(Unused Access Analysis)は、組織内のIAMロール・ユーザーを継続的に監視し、未使用のロール・アクセスキー・コンソールパスワードや、実際には使われていない権限(過剰な権限)を検出結果として提示する機能です。']},
  {id:'p554', domain:'security', type:'single', source:SOURCES.mfa, text:'AWS IAMの多要素認証(MFA)で利用できるデバイスの種類として正しいものはどれですか？',
    choices:['TOTP(時間ベースのワンタイムパスワード)を生成する仮想認証アプリ、FIDO規格のセキュリティキー(物理デバイス)、専用の装置でコードを生成するハードウェアTOTPトークンの3種類に対応している','仮想認証アプリのみに対応しており、物理的なセキュリティキーには対応していない','ハードウェアTOTPトークンのみに対応しており、スマートフォンの認証アプリには対応していない','MFAはルートユーザーには設定できず、IAMユーザーのみに設定できる'], correct:[0],
    why:['正しい。AWS IAMのMFAは、TOTPアルゴリズムを使う仮想認証アプリ(Google Authenticator等)、FIDO規格のセキュリティキー(物理デバイス、1つのキーを複数のIAMユーザー・ルートユーザーに登録することも可能)、専用のハードウェアTOTPトークンの3種類に対応しています。','誤り。仮想認証アプリ以外にも、FIDOセキュリティキーやハードウェアTOTPトークンにも対応しています。','誤り。ハードウェアTOTPトークン以外にも、仮想認証アプリやFIDOセキュリティキーにも対応しています。','誤り。MFAはルートユーザー・IAMユーザーの両方に設定できます(特にルートユーザーへの設定が強く推奨されています)。']},
  {id:'p555', domain:'billing', type:'single', source:SOURCES.free, text:'AWSの現行のFree Tier(無料利用枠)における「常時無料(Always Free)」の対象サービスについて正しい説明はどれですか？',
    choices:['新規アカウント作成から6か月間、または付与された無料クレジットを使い切るまでの間だけ無料で利用できる','Freeプラン・Paidプランのどちらであっても、各サービスで定められた毎月の利用量の上限内であれば、期間の制限なく無料で利用できる','アカウント作成時に一度だけ適用され、2回目以降のアカウントでは利用できない','利用するには事前にAWS Business Supportへの加入が必要である'], correct:[1],
    why:['誤り。これは新規アカウントに付与される無料クレジット(最大200ドル、6か月間)の説明です。「常時無料」の対象サービスはこれとは別の区分で、期間の制限はありません。','正しい。「常時無料(Always Free)」の対象サービスは、FreeプランでもPaidプランでも、毎月定められた利用量の上限内であれば期間の制限なく無料で利用できます(上限を超えた分は課金されます)。','誤り。常時無料サービスはアカウントの新旧を問わず、条件を満たせば継続的に利用できます。','誤り。常時無料サービスの利用にサポートプランへの加入は必要ありません。']},
  {id:'p556', domain:'billing', type:'single', source:SOURCES.support, text:'AWS Supportプランに付帯する「DevOpsエージェント クレジット」について正しい説明はどれですか？',
    choices:['どのサポートプランでも、付与されるクレジットの割合は同じ(Support料金の50%)である','Basic Supportプランでのみ付与される','Support料金に対する一定の割合としてクレジットが付与され、その割合はプランによって異なる(例: Business Support+は30%、Enterprise Supportは75%、Unified Operationsは100%)','クレジットには有効期限がなく、何年でも貯めておける'], correct:[2],
    why:['誤り。プランによって付与される割合は異なります。','誤り。Basic Supportは無料のプランであり、DevOpsエージェント クレジットの付帯対象ではありません(有料プランに付帯する特典です)。','正しい。DevOpsエージェント クレジットは、そのサポートプランの料金に対する一定の割合として付与され、Business Support+は30%、Enterprise Supportは75%、Unified Operationsは100%など、プランによって割合が異なります。','誤り。クレジットは毎月付与され、その月の末までに使われなければ失効します。']},
  {id:'p557', domain:'billing', type:'single', source:SOURCES.support, text:'AWSが「本番ワークロードに対して推奨する最小限のサポートプラン」として位置づけているプランに含まれる機能として正しいものはどれですか？',
    choices:['専任のテクニカルアカウントマネージャー(TAM)','5分未満のインシデント管理エンジニアによる初回応答(ビジネス/ミッションクリティカルな障害時)','24時間365日のワークロードモニタリング','AWS Well-Architected Reviewおよびプロアクティブなセキュリティレビュー'], correct:[3],
    why:['誤り。専任のTAMが付くのはEnterprise Support以上のプランです。','誤り。5分未満のインシデント管理エンジニアによる初回応答はUnified Operationsプランの特徴です。','誤り。24時間365日のワークロードモニタリングはUnified Operationsプランの特徴です。','正しい。AWSが本番ワークロードへの最小推奨プランと位置づけるBusiness Support+には、AWS Well-Architected Reviewやプロアクティブなセキュリティレビューが含まれています。']},
  {id:'p558', domain:'concepts', type:'single', source:SOURCES.waLens, text:'サーバーレスアーキテクチャに特化したアーキテクチャレビューを行いたい場合、AWS Well-Architected Frameworkのどの機能を利用するのが最も適切ですか？',
    choices:['Serverless Applications Lens（サーバーレスアプリケーションレンズ）を適用したレビュー','AWS Trusted Advisorのコスト最適化チェック','Amazon Inspectorによる脆弱性スキャン','AWS Configのコンフォーマンスパック'], correct:[0],
    why:['正しい。Serverless Applications Lens(サーバーレスアプリケーションレンズ)は、6つの柱の一般的な質問に加えて、サーバーレスワークロードに特化した追加のベストプラクティス・質問を提供するレンズです。','誤り。これはコスト最適化に関するチェックであり、サーバーレスアーキテクチャに特化したレビューではありません。','誤り。これは脆弱性スキャンサービスであり、アーキテクチャレビューの機能ではありません。','誤り。これは設定のコンプライアンス準拠を評価する機能であり、サーバーレスに特化したアーキテクチャレビューではありません。']},
  {id:'p559', domain:'concepts', type:'multi', source:SOURCES.cloudValueFramework, text:'AWSのCloud Value Framework（クラウド・バリュー・フレームワーク）が、クラウド導入の価値を測定する際の観点として挙げている項目を2つ選びなさい。',
    choices:['運用上の回復性(Operational Resilience)の向上','キャパシティの事前予測が不要になること(推測が不要になること)','ビジネスアジリティ(Business Agility)の向上','固定費を可変費に変換できること'], correct:[0,2],
    why:['正しい。Cloud Value Frameworkは、コスト削減・スタッフの生産性向上・運用上の回復性(Operational Resilience)の向上・ビジネスアジリティ・持続可能性(サステナビリティ)の5つの観点でクラウド導入の価値を測定します。','誤り。これはクラウドコンピューティングの6つのメリット(Six Advantages)で語られる「推測をやめる」という利点であり、Cloud Value Frameworkの観点そのものの名称ではありません。','正しい。ビジネスアジリティの向上は、Cloud Value Frameworkが示す価値の観点の一つです。','誤り。これも6つのメリットで語られる「固定費を可変費に変換」という利点であり、Cloud Value Framework独自の観点名ではありません。']},
  {id:'p560', domain:'concepts', type:'single', source:SOURCES.cloudValueFramework, text:'AWSのCloud Value Frameworkにおける「スタッフの生産性向上(Staff Productivity)」という価値の観点が重視しているものとして最も適切なものはどれですか？',
    choices:['サーバーの調達から稼働開始までのリードタイムを短縮すること自体','インフラの運用・保守といった差別化につながらない作業から人員を解放し、より戦略的で差別化につながる仕事に時間を使えるようにすること','電力消費量を削減し環境負荷を下げること','ハードウェア障害発生時の復旧時間を短縮すること'], correct:[1],
    why:['誤り。これはビジネスアジリティ(迅速なプロビジョニング)に関連する観点です。','正しい。スタッフの生産性向上は、インフラ運用などの差別化につながらない重労働から人員を解放し、より戦略的で付加価値の高い業務に時間を使えるようにすることを重視する観点です。','誤り。これは持続可能性(サステナビリティ)の観点です。','誤り。これは運用上の回復性(Operational Resilience)に関連する観点です。']},
  {id:'p561', domain:'concepts', type:'single', source:SOURCES.drStrategies, text:'4つの代表的なディザスタリカバリ(DR)戦略のうち、「バックアップ&リストア(Backup and Restore)」戦略の特徴として正しいものはどれですか？',
    choices:['複数のリージョンで常時アクティブにワークロードを稼働させ、ほぼゼロのRTOを実現する、最もコストが高い戦略','復旧リージョンでスケールダウンされた状態のワークロードを常時稼働させておく戦略','4つの戦略の中で最も低コストだが、データとインフラの復旧にかかる時間が最も長く、RTO/RPOが最も大きくなる戦略','復旧リージョンにコアとなるデータレプリケーション基盤だけを常時稼働させておく戦略'], correct:[2],
    why:['誤り。これはマルチサイトアクティブ/アクティブ戦略の説明です。','誤り。これはウォームスタンバイ戦略の説明です。','正しい。バックアップ&リストアは、定期的にバックアップを取得し障害時にそこから復旧する戦略で、4つの戦略の中で最も低コストですが、復旧にかかる時間(RTO)やデータ損失量(RPO)は最も大きくなります。','誤り。これはパイロットライト戦略の説明です。']},
  {id:'p562', domain:'concepts', type:'single', source:SOURCES.watool, text:'AWS Well-Architected Tool(コンソールのツール)を使ってレビューを実施する際、ワークロードの種類に応じた追加の質問を含めたい場合にできることとして正しいものはどれですか？',
    choices:['AWSサポートに連絡し、専任のソリューションアーキテクトによる有人レビューを依頼する必要がある','6つの柱とは別に、全く新しいフレームワークを一から作成する必要がある','IAM Access Analyzerと連携し、未使用の権限を自動的に除去する','レビュー対象のワークロードに、Serverless Applications LensやSaaS Lensなどのレンズを適用して、そのワークロードタイプに特化した質問を追加する'], correct:[3],
    why:['誤り。AWS Well-Architected Toolはセルフサービスの無料ツールであり、有人レビューへの連絡は必須ではありません。','誤り。レンズは6つの柱を置き換えるのではなく、それに追加する形で特化した質問を提供します。','誤り。これはIAM Access Analyzerの機能であり、Well-Architected Toolのレンズ機能とは無関係です。','正しい。AWS Well-Architected Toolでは、ワークロードにレンズ(Lens)を適用することで、6つの柱の一般的な質問に加え、そのワークロードタイプに特化した追加の質問でレビューできます。']},
  {id:'p563', domain:'security', type:'single', source:SOURCES.networkAccessAnalyzer, text:'ある企業が、本番環境のVPCと開発環境のVPCが意図せずネットワーク的に到達可能になっていないかを検証したいと考えています。実際にネットワークへパケットを送信せずにこれを検証できるAWSのサービス・機能はどれですか？',
    choices:['AWS Network Access Analyzer','Amazon GuardDuty','AWS Trusted Advisor','Amazon Inspector'], correct:[0],
    why:['正しい。Network Access Analyzerは、指定したネットワークアクセス要件(例: 本番VPCと開発VPCの分離)に反する潜在的なネットワークパスを、実際にパケットを送信せず静的解析によって検出します。','誤り。GuardDutyは脅威検知サービスであり、ネットワークパスの静的解析機能ではありません。','誤り。Trusted Advisorはベストプラクティスのチェックを行いますが、ネットワークパスの到達可能性を静的解析する機能ではありません。','誤り。Inspectorは主にEC2やコンテナイメージ、Lambda関数の脆弱性スキャンを行うサービスです。']},
  {id:'p564', domain:'security', type:'single', source:SOURCES.auditManager, text:'AWS Audit Managerの特徴として正しいものはどれですか？',
    choices:['IAMポリシーの許可内容をシミュレーションし、アクセスが許可されるか拒否されるかを判定する','PCI DSSやCISベンチマークなど、一般的なコンプライアンス標準に対応した事前定義済みのフレームワークを提供し、継続的にエビデンスを収集して監査の準備を支援する','ネットワークのパケットをキャプチャし、通信内容を解析する','S3バケット内のデータを走査し、個人を特定できる情報(PII)を検出する'], correct:[1],
    why:['誤り。これはIAM Policy Simulatorの説明です。','正しい。Audit Managerは、PCI DSSやCISベンチマークなど一般的な標準に対応した事前定義済みのフレームワークを提供し、関連するAWSリソースの設定などのエビデンスを継続的に収集して監査の準備を支援します。','誤り。これはVPC Traffic Mirroringなどの説明です。','誤り。これはAmazon Macieの説明です。']},
  {id:'p565', domain:'security', type:'multi', source:SOURCES.iamPolicySimulator, text:'IAM Policy Simulator(IAMポリシーシミュレーター)を使ってテストできる対象として正しいものを2つ選びなさい。',
    choices:['EC2インスタンスのOSにインストールされたソフトウェアの脆弱性','IAMユーザー・グループ・ロールにアタッチされたIDベースのポリシー','インターネットからVPC内のリソースへの実際のネットワーク到達性','ユーザーが指定したリソースベースのポリシー'], correct:[1,3],
    why:['誤り。これはAmazon Inspectorの説明であり、IAM Policy Simulatorの機能ではありません。','正しい。IAM Policy Simulatorは、IAMユーザー・グループ・ロールに既にアタッチされているIDベースのポリシーをテストできます。','誤り。これはAWS Network Access Analyzerなどの説明です。IAM Policy Simulatorは実際のAWSサービスへリクエストを送信せずにポリシーの評価結果だけを返します。','正しい。IAM Policy Simulatorは、ユーザーが指定(提供)したリソースベースのポリシーもテスト対象にできます。']},
  {id:'p566', domain:'tech', type:'single', source:SOURCES.mediaconvert, text:'あるメディア企業が、保有する大量の動画ファイルを様々な画面サイズ・帯域幅向けにオンデマンド配信できる形式へ一括でトランスコードしたいと考えています。この用途に最も適したAWSサービスはどれですか？',
    choices:['AWS Elemental MediaLive','Amazon Kinesis Video Streams','AWS Elemental MediaConvert','Amazon CloudFront'], correct:[2],
    why:['誤り。MediaLiveはライブ映像のリアルタイムエンコードに使われるサービスです。','誤り。Kinesis Video Streamsはデバイスからのライブ映像の取り込み・処理に使われるサービスです。','正しい。MediaConvertは、ファイルベースの動画処理サービスで、アダプティブビットレート(ABR)パッケージングなどにより、様々な画面サイズ・帯域幅向けにオンデマンド配信用の動画ファイルを一括でトランスコードできます。','誤り。CloudFrontはコンテンツ配信(CDN)サービスであり、動画のトランスコード自体は行いません。']},
  {id:'p567', domain:'tech', type:'single', source:SOURCES.ec2, text:'Amazon EC2のインスタンスタイプのファミリーに関する説明として正しいものはどれですか？',
    choices:['ストレージ最適化インスタンスは、GPUを搭載し機械学習の学習処理に特化している','汎用インスタンスは、メモリに対するvCPUの比率が最も高く設計されている','メモリ最適化インスタンスは、大量のローカルNVMeストレージへの高速・低レイテンシーなアクセスに特化している','コンピューティング最適化インスタンスは、vCPUに対するメモリの比率が低く、バッチ処理や科学モデリングなど高い計算性能を要する処理に適している'], correct:[3],
    why:['誤り。GPUを搭載し機械学習に特化しているのは高速コンピューティング(アクセラレーテッドコンピューティング)インスタンスです。ストレージ最適化インスタンスは大量のローカルストレージへの高速アクセスに特化しています。','誤り。メモリに対するvCPUの比率が高いのはコンピューティング最適化インスタンスです。汎用インスタンスはコンピューティング・メモリ・ネットワーキングのバランスが取れた設計です。','誤り。大量のローカルNVMeストレージへの高速アクセスに特化しているのはストレージ最適化インスタンスです。メモリ最適化インスタンスはメモリに対するvCPUの比率が低く設計されています。','正しい。コンピューティング最適化インスタンスは、vCPUに対するメモリの比率が低く設計されており、バッチ処理や科学モデリング、メディアトランスコーディングなど高い計算性能を要する処理に適しています。']},
  {id:'p568', domain:'tech', type:'single', source:SOURCES.cloudwatch, text:'Amazon CloudWatchの「複合アラーム(Composite Alarm)」の特徴として正しいものはどれですか？',
    choices:['複数の既存のCloudWatchアラームを論理演算子(AND/OR)で組み合わせて、1つの新しいアラームとして評価する','複数のリージョンのメトリクスを1つのダッシュボードに表示する','ログデータに対してSQLに似たクエリ言語で分析を行う','アラームの発生時に、自動的にEC2インスタンスをスケールアウトする'], correct:[0],
    why:['正しい。複合アラームは、既存の複数のCloudWatchアラームをAND/ORなどの論理演算子で組み合わせて評価し、個々のアラームが示す通知の数を減らしてノイズを抑えるために使われます。','誤り。これはCloudWatchダッシュボードの一般的な機能の説明であり、複合アラーム特有の特徴ではありません。','誤り。これはCloudWatch Logs Insightsの説明です。','誤り。これはAmazon EC2 Auto Scalingと連携したスケーリングポリシーの説明であり、複合アラーム自体がスケーリングを行うわけではありません。']},
  {id:'p569', domain:'billing', type:'single', source:SOURCES.serviceQuotas, text:'ある企業が、特定のAWSサービスのクォータ(サービスの上限値)に対する使用率が事前に設定したしきい値に達した際に、プロアクティブに通知を受け取りたいと考えています。AWS Service Quotasを使ってこれを実現する方法として正しいものはどれですか？',
    choices:['AWS Budgetsでコストしきい値のアラートを設定する','Service Quotasのコンソールで対象のクォータに対してAmazon CloudWatchアラームを作成し、使用率がしきい値に達した際に通知するよう設定する','AWS Trusted Advisorのサービス制限チェックを手動で毎日確認する','クォータの引き上げリクエストを事前に送信しておく'], correct:[1],
    why:['誤り。AWS Budgetsはコスト・使用量の予算に対するアラートであり、サービスクォータの使用率監視を直接行うものではありません。','正しい。Service Quotasは、対象のクォータがCloudWatchアラームに対応している場合、コンソール上でクォータの使用率に対するCloudWatchアラームを作成し、しきい値に達した際に通知するよう設定できます。','誤り。手動での確認はプロアクティブな自動通知の仕組みではありません。','誤り。引き上げリクエストはクォータの上限値自体を変更する操作であり、使用率のしきい値通知とは異なります。']},
  {id:'p570', domain:'billing', type:'single', source:SOURCES.trustedadvisor, text:'AWS Trusted Advisorの全てのチェック項目(コスト最適化・パフォーマンス・セキュリティ・耐障害性・サービス制限の全カテゴリ)を利用するために必要な最小限のAWSサポートプランはどれですか？',
    choices:['Basic Support','特定のサポートプランには依存せず、全てのAWSアカウントで常に全チェックが利用できる','Business Support+（またはそれ以上のEnterprise Support・Unified Operations）','個別にAWS Trusted Advisorの追加料金を支払うことで、Basic Supportのままでも全チェックが利用可能になる'], correct:[2],
    why:['誤り。Basic Supportではサービス制限カテゴリの全チェックと、セキュリティ・耐障害性カテゴリの一部のチェックのみが利用でき、全カテゴリ・全チェックは利用できません。','誤り。全チェックの利用可否はサポートプランに依存します。','正しい。Trusted Advisorの全チェック項目を利用するには、Business Support+以上(Business Support+・Enterprise Support・Unified Operations)のサポートプランが必要です。','誤り。Trusted Advisorの全チェック利用は個別の追加料金ではなく、サポートプランのランクによって決まります。']},
  {id:'p571', domain:'tech', type:'single', source:SOURCES.deviceFarm, text:'モバイルアプリの開発チームが、シミュレーターやエミュレーターではなく実機の様々なAndroid/iOSデバイスを使って、アプリの動作確認や自動テストを実施したいと考えています。最も適したサービスはどれですか？',
    choices:['AWS Device Farm','AWS CodeBuild','Amazon WorkSpaces','AWS CloudShell'], correct:[0],
    why:['正しい。AWS Device Farmは、AWSがホストする実機の様々なAndroid/iOS/Webデバイス上でアプリをテストできるサービスで、ブラウザからのリモートアクセスや自動テストの並列実行に対応しています。','CodeBuildはソースコードのビルド・テスト(コンパイルやユニットテストの実行)を行うCI/CDサービスであり、実機デバイスでのテストに特化したサービスではありません。','WorkSpacesはクラウド上の仮想デスクトップを提供するサービスであり、モバイル実機テスト用のサービスではありません。','CloudShellはブラウザから使えるコマンドラインシェル環境であり、モバイル実機テストとは関係ありません。']},
  {id:'p572', domain:'tech', type:'single', source:SOURCES.locationService, text:'配送会社が、荷物を積んだ車両がオンプレミスで管理している「配送完了エリア」のポリゴン境界に入った、または出た際に自動的にイベントを発生させ、車両の現在位置をリアルタイムに追跡したいと考えています。最も適したサービス・機能はどれですか？',
    choices:['Amazon CloudWatchのメトリクスアラーム','Amazon Location Serviceのジオフェンス(Geofence)とトラッカー(Tracker)','AWS IoT Core のルールエンジン','Amazon EventBridge のスケジュールルール'], correct:[1],
    why:['CloudWatchのメトリクスアラームは数値指標のしきい値監視であり、地理的な境界(ポリゴン)の出入りを検知する機能ではありません。','正しい。Amazon Location Serviceのトラッカーはデバイスの位置情報を収集・追跡し、ジオフェンスは指定したポリゴンや円形の地理的境界への出入りを検知してイベントを発生させる機能です。','IoT Coreのルールエンジンはメッセージ(MQTT等)の内容に応じたルーティングを行う仕組みであり、地理的境界の判定機能自体は持ちません。','EventBridgeのスケジュールルールは時刻に基づいた定期実行であり、位置情報に基づくイベント検知ではありません。']},
  {id:'p573', domain:'tech', type:'single', source:SOURCES.beanstalk, text:'AWS Elastic Beanstalkで、HTTPリクエストを処理するWebアプリケーションに加えて、SQSキューからメッセージを受け取ってバックグラウンドでバッチ処理を行うコンポーネントも、同じ仕組みでデプロイ・管理したいと考えています。Elastic Beanstalkが提供する機能として適切なものはどれですか？',
    choices:['Webサーバー環境のみが提供されており、バックグラウンド処理を行う環境は別のサービスで構築する必要がある','バックグラウンド処理を行う場合は、Elastic Beanstalkの管理対象外でLambda関数を別途手動構築する必要がある','HTTPリクエストを処理する「Webサーバー環境」と、SQSキューをポーリングしてバックグラウンドタスクを処理する「ワーカー環境」の2種類の環境タイプを提供している','ワーカー環境はSQS以外のメッセージキューサービスからのみメッセージを受信できる'], correct:[2],
    why:['誤り。Elastic Beanstalkは、Webサーバー環境に加えてワーカー環境も提供しています。','誤り。ワーカー環境はElastic Beanstalkの管理対象内で提供される環境タイプです。','正しい。Elastic Beanstalkは、HTTPリクエストを処理する「Webサーバー環境」と、Amazon SQSキューをポーリングしてバックグラウンドタスクを処理する「ワーカー環境」の2種類の環境タイプを提供しており、同じデプロイの仕組みで管理できます。','誤り。ワーカー環境はAmazon SQSキューをポーリングしてメッセージを処理する仕組みです。']},
  {id:'p574', domain:'tech', type:'single', source:SOURCES.opensearch, text:'ログ分析基盤を構築するにあたり、トラフィック量の変動が予測しづらく、クラスターのノード数やストレージ容量をあらかじめ見積もって管理する運用負荷を避け、使用量に応じて自動的にスケーリングするOpenSearchの利用形態を採用したいと考えています。最も適したものはどれですか？',
    choices:['プロビジョンドクラスター(ドメイン)で、常に最大トラフィックを見込んだノード数を固定で起動しておく','Amazon OpenSearch Serviceではなく、自己管理のEC2上にOpenSearchを構築する','Reserved Instanceを購入してOpenSearchのノードコストを削減する','Amazon OpenSearch Serverless を利用し、クラスターのキャパシティ管理を行わずに使用量に応じて自動でスケーリングさせる'], correct:[3],
    why:['誤り。常に最大トラフィックを見込んだ固定ノード数での運用は、キャパシティの見積り・管理が必要になり、今回の要件(運用負荷の回避)に反します。','誤り。自己管理のEC2上への構築は、OSやソフトウェアの運用管理負荷がさらに増えるため適切ではありません。','誤り。Reserved Instanceはコスト削減の手段であり、キャパシティ管理の負荷を解消するものではありません。','正しい。Amazon OpenSearch Serverlessは、クラスターのノード数やストレージ容量の管理を行わずに、使用量に応じて自動的にスケーリングするサーバーレスの利用形態です。']},
  {id:'p575', domain:'tech', type:'single', source:SOURCES.resourceExplorer, text:'AWS Resource Explorerを使って複数のAWSリージョンにまたがるリソースを横断的に検索したいと考えていますが、特定のリージョンのリソースが検索結果に表示されません。考えられる原因として最も適切なものはどれですか？',
    choices:['検索対象としたいリージョンでAWS Resource Explorerを有効化し、インデックスを作成していない','AWS Resource Explorerは単一リージョン内のリソース検索のみに対応しており、複数リージョンの横断検索はそもそもできない','対象リソースにタグが1つも付与されていないと検索結果に一切表示されない','AWS Organizationsを導入していないアカウントでは、AWS Resource Explorerをそもそも利用できない'], correct:[0],
    why:['正しい。AWS Resource Explorerで横断検索を行うには、検索対象としたい各リージョンでResource Explorerを有効化してインデックスを作成する必要があり、未作成のリージョンのリソースは検索結果に含まれません。','誤り。Resource Explorerは、集約リージョンを指定することで複数リージョンのリソースを横断的に検索できます。','誤り。タグはリソースの属性の一つにすぎず、タグが無いリソースも名前やIDなどで検索できます。','誤り。AWS Resource Explorerは単一アカウントでも利用でき、AWS Organizationsは必須ではありません。']},
  {id:'p576', domain:'tech', type:'single', source:SOURCES.imageBuilder, text:'EC2 Image Builderで作成したカスタムAMIについて、本番環境への配布前に自動テストを実施し、問題が無ければ複数のAWSリージョン・複数のAWSアカウントへ自動的にコピー・共有したいと考えています。この要件を実現するEC2 Image Builderの機能として正しいものはどれですか？',
    choices:['EC2 Image Builderはイメージのビルドのみを行い、テストや配布(ディストリビューション)の自動化機能は提供していない','イメージパイプラインの中に「テストコンポーネント」と「ディストリビューション設定」を組み込むことで、ビルド後の自動テストと、複数リージョン・複数アカウントへのAMIの自動コピー・共有を1つのパイプラインで実現できる','複数リージョンへの配布には、AWS Backupを別途併用する必要がある','複数アカウントへの共有は、AMIを一度S3にエクスポートしてから手動で再インポートする必要がある'], correct:[1],
    why:['誤り。EC2 Image Builderはビルドパイプラインの中にテストやディストリビューション(配布)の設定を組み込める統合的なサービスです。','正しい。EC2 Image Builderのイメージパイプラインでは、ビルド後に実行する「テストコンポーネント」と、コピー先リージョンや共有先アカウントを指定する「ディストリビューション設定」を組み込むことで、テストから複数リージョン・複数アカウントへの配布までを自動化できます。','誤り。複数リージョンへのAMI配布はImage Builder自体のディストリビューション設定で行え、AWS Backupは不要です。','誤り。複数アカウントへの共有もディストリビューション設定内で直接指定でき、S3経由の手動エクスポート・インポートは不要です。']},
  {id:'p577', domain:'security', type:'single', source:SOURCES.wafService, text:'AWS WAFのBot Controlマネージドルールグループを使って、望ましくないボットからのリクエストを検出した際に、即座にブロックするのではなく、人間のユーザーであることを確認するための操作(視覚的なパズルを解く、またはバックグラウンドでの検証)を挟んでから通過を判定したいと考えています。この要件を実現する方法として正しいものはどれですか？',
    choices:['Bot Controlのルールアクションは常にBlockのみで、他のアクションへは変更できない','AWS Shield Advancedを追加契約することで自動的に有効になる','マネージドルールグループのルールアクションの上書き設定で、対象ルールのアクションをBlockからCAPTCHA(視覚的なパズル)またはChallenge(バックグラウンドでの検証)に変更する','VPCセキュリティグループのルールでボットのIPアドレスを個別にブロックする'], correct:[2],
    why:['誤り。マネージドルールグループのルールアクションは、設定でBlock以外のアクション(CAPTCHAやChallenge等)に上書きできます。','誤り。Shield AdvancedはDDoS対策のサービスであり、CAPTCHA/Challengeアクションの設定とは異なります。','正しい。AWS WAFでは、マネージドルールグループの設定でルールアクションを上書きでき、BlockをCAPTCHA(視覚的なパズルで人間であることを確認)やChallenge(ユーザー操作を要さないバックグラウンドでの検証)に変更できます。','誤り。セキュリティグループはインスタンス/ENI単位のステートフルなファイアウォールであり、Webアプリケーション層でのボット判定やCAPTCHA表示は行えません。']},
  {id:'p578', domain:'security', type:'single', source:SOURCES.accessAnalyzer, text:'ある開発チームが、IAMポリシーをAWS環境にデプロイする前に、CI/CDパイプラインの中でそのポリシーがIAMのポリシー文法に準拠しているか、またAWSのベストプラクティスから外れていないかを自動的にチェックし、エラーやセキュリティ警告があればデプロイを止めたいと考えています。最も適した機能はどれですか？',
    choices:['AWS Trusted Advisorのセキュリティチェック','Amazon Inspectorのポリシースキャン機能','AWS Configの設定変更履歴機能','AWS IAM Access Analyzerのポリシー検証(Policy Validation)機能'], correct:[3],
    why:['誤り。Trusted Advisorはアカウント全体のベストプラクティスチェックを行いますが、デプロイ前の個別IAMポリシーの文法・ベストプラクティス検証に特化した機能ではありません。','誤り。Amazon Inspectorは、EC2やコンテナ、Lambda関数の脆弱性スキャンを行うサービスであり、IAMポリシーの検証機能は提供していません。','誤り。AWS Configはリソースの設定変更履歴や準拠状況の評価を行うサービスであり、デプロイ前のポリシー検証機能ではありません。','正しい。IAM Access Analyzerのポリシー検証機能は、IAMポリシーをIAMのポリシー文法とAWSのベストプラクティスに照らしてチェックし、エラー・セキュリティ警告・一般的な警告・提案(サジェスチョン)として結果を返すため、CI/CDパイプラインに組み込んでデプロイ前チェックに利用できます。']},
  {id:'p579', domain:'security', type:'multi', source:SOURCES.cognito, text:'モバイルアプリのユーザー認証にAmazon Cognitoのユーザープールを使っている企業が、漏洩した認証情報(パスワードリスト攻撃等)の使用や、不審なサインインパターンを検知して自動的にブロックまたはMFAを要求したいと考えています。Amazon Cognitoがこの要件のために提供する機能に関する正しい説明を2つ選択してください。',
    choices:['ユーザープールの脅威保護(Threat Protection)機能は、サインインの試行を公開されている漏洩認証情報のリストと照合し、一致した場合にサインインのブロック等のアクションを設定できる','脅威保護(Threat Protection)機能は追加の契約や設定なしに、すべてのユーザープールで自動的に有効になっている','脅威保護(Threat Protection)機能は、サインイン時の活動にリスクスコアを割り当てる適応型認証(アダプティブオーセンティケーション)を提供し、リスクが高いと判定された場合にMFAの要求やサインインのブロックといった対応を設定できる','脅威保護(Threat Protection)機能を使うには、ユーザープールではなくIDプールを使用する必要がある'], correct:[0,2],
    why:['正しい。Cognitoのユーザープールの脅威保護機能は、サインイン試行を漏洩した認証情報のリストと照合し、一致した場合にブロックする等のアクションを設定できる機能(漏洩認証情報の検出)を提供します。','誤り。脅威保護機能は、対応する機能プランの選択や設定が必要な機能であり、すべてのユーザープールで無条件に自動的に有効になっているわけではありません。','正しい。脅威保護機能の適応型認証は、サインイン時の活動にリスクスコアを割り当て、リスクが高いと判定された場合にMFA要求やブロックといった対応を行えます。','誤り。脅威保護機能はユーザープールの機能であり、IDプールの機能ではありません。']},
  {id:'p580', domain:'concepts', type:'single', source:SOURCES.skillBuilder, text:'ある企業が、社員全体のクラウドリテラシー向上のため、まずは無料で利用できるAWS公式のオンデマンド学習コンテンツを導入し、特に資格取得を目指す一部の社員にはハンズオンラボも含めた学習環境を提供したいと考えています。最も適したサービスの使い方はどれですか？',
    choices:['AWS Skill Builderを導入し、全社員には無料のデジタルコースを提供しつつ、資格取得を目指す社員にはサブスクリプションプランを契約してハンズオンラボ等を利用させる','全社員にAWS Professional Servicesとの個別契約を結ばせる','AWS Trusted Advisorを導入し、学習進捗をチェックする','AWS re:Postの有料プランに全社員を登録する'], correct:[0],
    why:['正しい。AWS Skill Builderは無料のデジタルコースを提供しており、追加でサブスクリプションを契約することでハンズオンラボや認定試験対策コンテンツなど、より発展的な学習コンテンツを利用できます。','誤り。AWS Professional Servicesは個別のコンサルティング・導入支援サービスであり、全社員向けの学習コンテンツの提供を目的としたものではありません。','誤り。Trusted Advisorはアカウントのベストプラクティスチェックサービスであり、学習コンテンツや進捗管理の機能は提供していません。','誤り。AWS re:Postはコミュニティによる質疑応答の場であり、体系立った学習コースの提供を主目的としたものではありません。']},
  {id:'p581', domain:'concepts', type:'single', source:SOURCES.skillBuilder, text:'AWS認定資格の取得を目指すエンジニアが、座学だけでなく実際のAWSコンソールやCLIを操作する実践的な演習を通じて理解を深めたいと考えています。AWS Skill Builderが提供する機能のうち、この目的に最も適したものはどれですか？',
    choices:['無料のデジタルコース(動画・読み物形式の学習コンテンツ)のみ','サブスクリプションで提供される、実際のAWS環境を使ったハンズオンラボ','他の学習者同士が質問し合うディスカッションフォーラムのみ','AWSパートナー企業の紹介ページ'], correct:[1],
    why:['誤り。無料のデジタルコースは動画や読み物中心の学習コンテンツであり、実際の環境を操作する演習そのものではありません。','正しい。AWS Skill Builderのサブスクリプションでは、実際のAWS環境を使ったハンズオンラボが提供されており、座学だけでなく実践的な操作演習を通じてスキルを身につけられます。','誤り。ディスカッションフォーラムは学習者同士の交流の場であり、実践的な操作演習そのものではありません。','誤り。パートナー企業の紹介はAWS Skill Builderの主な学習コンテンツではありません。']},
  {id:'p582', domain:'billing', type:'single', source:SOURCES.partnerNetwork, text:'ある企業が、大規模なAWS移行プロジェクトにおいて、自社に無いAWSアーキテクチャ設計やマイグレーションの専門知識を持つ外部の専門企業に、設計から構築までの実装支援を依頼したいと考えています。このような専門知識を持つ企業を探すために活用できる仕組みとして最も適切なものはどれですか？',
    choices:['AWS Trusted Advisor','AWS Marketplaceでソフトウェア製品を検索する','AWS Partner Network (APN) を通じて、AWSアーキテクチャ設計やマイグレーションの実績・専門知識を持つコンサルティングパートナーを探す','AWS re:Postで同様の質問を投稿する'], correct:[2],
    why:['誤り。Trusted Advisorはアカウントのベストプラクティスチェックツールであり、外部の実装支援企業を探す仕組みではありません。','誤り。AWS Marketplaceは主にソフトウェア製品(SaaS等)を検索・購入するためのカタログであり、実装支援のコンサルティングサービスを探す主目的の仕組みとは異なります。','正しい。AWS Partner Network (APN) には、AWS上でのアーキテクチャ設計や移行支援などの実績・専門知識を持つコンサルティングパートナーが参加しており、企業は自社のニーズに合ったパートナーを探して実装支援を依頼できます。','誤り。re:Postはコミュニティによる質疑応答の場であり、大規模プロジェクトの実装支援を正式に依頼する仕組みではありません。']},
  {id:'p583', domain:'billing', type:'single', source:SOURCES.partnerNetwork, text:'AWS Partner Network (APN) と AWS Marketplace の違いに関する説明として最も適切なものはどれですか？',
    choices:['両者は同一の仕組みであり、呼び方が異なるだけである','APNはソフトウェア製品を購入するためのカタログであり、Marketplaceはパートナー企業のコミュニティである','APNは請求書の一括管理機能であり、Marketplaceはサポートプランの一種である','APNは、AWS上でのソリューション構築・導入・運用を支援するパートナー企業（コンサルティングパートナーやテクノロジーパートナー）で構成されるコミュニティであるのに対し、Marketplaceはサードパーティ製のソフトウェアやデータ製品を検索・購入(契約)できるオンラインカタログである'], correct:[3],
    why:['誤り。APNはパートナー企業のコミュニティ、Marketplaceはソフトウェア等の購入カタログであり、異なる仕組みです。','誤り。説明が逆です。ソフトウェア製品を購入するためのカタログはAWS Marketplace、パートナー企業のコミュニティはAPNです。','誤り。APNもMarketplaceも、請求書の一括管理機能やサポートプランではありません。','正しい。APNは、AWS上でのソリューションの構築・導入・運用を支援するコンサルティングパートナーやテクノロジーパートナーなどで構成されるグローバルなパートナーコミュニティであり、Marketplaceはサードパーティ製のソフトウェア・データ製品を検索し購入(契約)できるオンラインカタログです。']},
  {id:'p584', domain:'tech', type:'single', source:SOURCES.lakeFormation, text:'ある企業は、Amazon S3上に構築したデータレイクに対して、部門ごとに異なるデータベース・テーブル・さらには特定の列や行までアクセス許可を細かく制御したいと考えている。IAMポリシーだけでは管理が煩雑になるため、データレイク専用の権限管理の仕組みを導入したい。最も適したサービスはどれですか？',
    choices:['AWS Lake Formation','AWS Identity and Access Management (IAM) のリソースベースポリシーのみ','Amazon Macie','AWS Resource Access Manager (RAM)'], correct:[0],
    why:['正しい。AWS Lake Formationは、データレイク内のデータベース・テーブル・列・行単位で詳細なアクセス許可を一元的に管理できるサービスです。','誤り。IAMのリソースベースポリシーだけでは、データレイク内のテーブルや列・行単位の細かい権限管理を効率的に行うことは困難です。','誤り。Amazon Macieは機密データの検出・分類サービスであり、アクセス許可の管理機能ではありません。','誤り。AWS RAMはVPCサブネットやTransit Gateway等のリソースをアカウント間で共有する機能であり、データレイクのテーブル・列単位の権限管理機能はありません。']},
  {id:'p585', domain:'tech', type:'single', source:SOURCES.medialive, text:'ある企業は、社内イベントをライブ配信し、スマートフォンやスマートTVなど様々な再生デバイスに対応した複数のビットレート・形式でリアルタイムに変換して配信したいと考えている。最も適したサービスはどれですか？',
    choices:['AWS Elemental MediaConvert','AWS Elemental MediaLive','Amazon Kinesis Data Streams','Amazon CloudFront'], correct:[1],
    why:['誤り。MediaConvertは録画済み(オンデマンド)の動画ファイルをバッチでトランスコードするサービスで、ライブ配信のリアルタイム変換には対応していません。','正しい。AWS Elemental MediaLiveは、ライブの動画コンテンツをリアルタイムで複数の形式・ビットレートへ変換し、放送・ストリーミング配信向けに出力できるサービスです。','誤り。Kinesis Data Streamsは汎用的なリアルタイムデータストリーミング基盤であり、動画のエンコード・フォーマット変換に特化したサービスではありません。','誤り。CloudFrontは変換済みのコンテンツを配信するCDNであり、動画のエンコード自体を行うサービスではありません。']},
  {id:'p586', domain:'tech', type:'single', source:SOURCES.ecs, text:'ある開発チームは、Dockerコンテナ化したアプリケーションを本番環境で稼働させたいが、EC2インスタンスのプロビジョニングやOSのパッチ適用、容量管理といったサーバー管理の手間を一切負いたくないと考えている。AWS独自のコンテナオーケストレーションAPIを使い、サーバーレスでコンテナを実行する構成として最も適したものはどれですか？',
    choices:['Amazon EKS を EC2 起動タイプで実行する','Amazon ECS を EC2 起動タイプで実行する','Amazon ECS を AWS Fargate 起動タイプで実行する','Amazon ECR にコンテナイメージを保存するだけで実行する'], correct:[2],
    why:['誤り。EKSはKubernetes標準APIを使用します（「AWS独自のAPI」という条件に合わず）。またEC2起動タイプではサーバー管理が必要です。','誤り。EC2起動タイプでは、依然としてEC2インスタンスのプロビジョニングやOSパッチ適用などのサーバー管理が必要です。','正しい。Amazon ECSをAWS Fargate起動タイプで実行すると、AWS独自のコンテナオーケストレーションAPIを使いながら、サーバーのプロビジョニングや管理を行わずにコンテナを実行できます。','誤り。ECRはコンテナイメージを保存するレジストリであり、コンテナを実行する機能はありません。']},
  {id:'p587', domain:'tech', type:'single', source:SOURCES.eks, text:'あるチームは、オンプレミスで既にKubernetesを使ってコンテナアプリケーションを運用しており、既存のKubernetesマニフェストやツールチェイン(kubectl等)をそのまま使ってAWS上でも運用したいと考えている。最も適したサービスはどれですか？',
    choices:['Amazon ECS（AWS独自のタスク定義形式を使用)','AWS Elastic Beanstalk','AWS App Runner','Amazon EKS（Kubernetes標準APIに準拠したマネージド型コントロールプレーンを提供)'], correct:[3],
    why:['誤り。ECSはAWS独自のAPI・タスク定義形式を使用するため、既存のKubernetesマニフェストをそのまま使うことはできません。','誤り。Elastic BeanstalkはPaaS型のデプロイサービスであり、Kubernetes標準APIには準拠していません。','誤り。App RunnerはコンテナやソースコードからWebアプリケーションを直接デプロイするサービスで、Kubernetes標準APIには準拠していません。','正しい。Amazon EKSはKubernetes標準APIに準拠したマネージド型コントロールプレーンを提供するため、既存のKubernetesマニフェストやkubectl等のツールチェインをそのまま活用できます。']},
  {id:'p588', domain:'security', type:'single', source:SOURCES.iamPolicySimulator, text:'管理者が新しいIAMポリシーを作成し、実際にユーザーへアタッチする前に、そのポリシーが特定のアクション(例: Amazon S3への書き込み)を許可するかどうかをシミュレーションして事前に検証したい。最も適した方法はどれですか？',
    choices:['IAM Policy Simulatorを使って、ポリシーをアタッチする前にアクションの許可・拒否結果をテストする','AWS CloudTrailのイベント履歴を確認し、過去に似たアクションが許可されたかどうかを調べる','Amazon Inspectorでポリシーの脆弱性スキャンを実行する','AWS Trusted Advisorのセキュリティチェックでポリシーの内容を確認する'], correct:[0],
    why:['正しい。IAM Policy Simulatorは、IAMポリシーを実際にアタッチする前に、特定のアクションが許可されるか拒否されるかをシミュレーションしてテストできる機能です。','誤り。CloudTrailは実際に発生したAPIコールの履歴を記録するものであり、未適用のポリシーの事前シミュレーションはできません。','誤り。Amazon Inspectorはソフトウェアの脆弱性スキャンサービスであり、IAMポリシーのシミュレーション機能はありません。','誤り。Trusted Advisorは一般的なベストプラクティスのチェックを行いますが、個別のポリシーの許可・拒否結果をシミュレーションする機能ではありません。']},
  {id:'p589', domain:'security', type:'single', source:SOURCES.networkAccessAnalyzer, text:'あるセキュリティ担当者は、実際にトラフィックを送信せずに、VPC内のネットワーク構成(セキュリティグループ、NACL、ルートテーブル等)を静的に解析し、意図しない形でインターネットから到達可能になっているリソースがないかを特定したいと考えている。最も適したサービスはどれですか？',
    choices:['Amazon GuardDuty','AWS Network Access Analyzer','VPC Flow Logs','AWS Network Firewall'], correct:[1],
    why:['誤り。GuardDutyは実際のログ(VPC Flow Logs、CloudTrail等)を継続的に分析して脅威を検知するサービスであり、ネットワーク構成の静的解析は行いません。','正しい。AWS Network Access Analyzerは、実際にトラフィックを送信せずにVPCのネットワーク構成を静的に解析し、意図しない到達可能性(ネットワークパス)を特定できるサービスです。','誤り。VPC Flow Logsは実際に発生した通信の記録であり、構成の静的解析ではありません。','誤り。AWS Network Firewallはトラフィックをフィルタリングする実行時の保護サービスであり、構成の静的解析機能ではありません。']},
  {id:'p590', domain:'security', type:'single', source:SOURCES.securityIR, text:'ある企業は、セキュリティインシデントが発生した際に、AWSのセキュリティ専門チームによる24時間365日の支援を受けながら、調査・復旧を迅速に進められるサブスクリプション型のサービスを導入したいと考えている。最も適したサービスはどれですか？',
    choices:['Amazon GuardDuty','AWS Security Hub','AWS Security Incident Response','Amazon Detective'], correct:[2],
    why:['誤り。GuardDutyは脅威を検知するサービスであり、インシデント発生時の専門チームによる調査・復旧支援そのものを提供するものではありません。','誤り。Security Hubは複数のセキュリティサービスの検出結果を集約するダッシュボードであり、専門チームによる対応支援サービスではありません。','正しい。AWS Security Incident Responseは、セキュリティインシデント発生時にAWSのセキュリティ専門チームによる24時間365日の支援を受けながら調査・復旧を進められるサブスクリプション型のサービスです。','誤り。Detectiveは根本原因調査のためのログ分析・可視化サービスであり、人による専門チームの直接支援を提供するサービスではありません。']},
  {id:'p591', domain:'security', type:'multi', source:SOURCES.verifiedAccess, text:'AWS Verified Accessの特徴として正しいものを2つ選択してください。',
    choices:['従来のVPNクライアントをすべてのユーザーのデバイスにインストールする必要がある','ユーザーのIDやデバイスの状態といった複数の信頼データソースに基づき、リクエストごとにアクセス可否を継続的に評価するゼロトラストのアクセスモデルを採用している','インターネット経由でのアクセスを一切許可せず、Direct Connect経由のみでアクセスを許可する','VPNを使わずに、企業の内部アプリケーションへ安全にアクセスできるようにする'], correct:[1,3],
    why:['誤り。AWS Verified AccessはVPNクライアントを必要としないアクセス方式です。','正しい。Verified Accessは、ユーザーID・デバイスの状態など複数の信頼データソースを基に、リクエストごとに継続的にアクセス可否を評価するゼロトラストのモデルを採用しています。','誤り。Direct Connect経由のみに限定されるものではなく、インターネット経由でのアクセスにも対応します。','正しい。Verified Accessは、VPNを使わずに企業の内部アプリケーションへ安全にアクセスできるようにするサービスです。']},
  {id:'p592', domain:'billing', type:'single', source:SOURCES.costAllocTags, text:'ある企業は、複数の部門・プロジェクトで共有しているAWS環境において、各リソースのコストをプロジェクトごとに集計し、部門への費用の割り振り(チャージバック)を行いたいと考えている。最も適した方法はどれですか？',
    choices:['各部門ごとに別のAWSリージョンを使用する','AWS Budgetsでプロジェクトごとに予算のしきい値を設定する','AWS Cost Anomaly Detectionでプロジェクトごとの異常コストを検知する','リソースにコスト配分タグ(Cost Allocation Tags)を付与し、タグ別のコストレポートを有効化する'], correct:[3],
    why:['誤り。リージョンを分けることは可能ですが、コストの集計・割り振りの仕組みそのものではなく、運用が煩雑になります。','誤り。Budgetsは予算のしきい値監視とアラートの仕組みであり、コストの部門別割り振り(チャージバック)自体を目的とした機能ではありません。','誤り。Cost Anomaly Detectionは異常なコスト増加を検知する機能であり、コストの割り振り機能ではありません。','正しい。リソースにコスト配分タグを付与し、タグ別のコストレポートを有効化することで、プロジェクトや部門ごとのコストを集計し、チャージバックに活用できます。']},
  {id:'p593', domain:'billing', type:'single', source:SOURCES.riMarketplace, text:'ある企業は、1年前に購入したスタンダードリザーブドインスタンスが、事業計画の変更により今後使用しないことが判明した。購入したリザーブドインスタンスの残存期間分の費用を回収する方法として最も適したものはどれですか？',
    choices:['Amazon EC2 Reserved Instance Marketplaceで、残りの契約期間分のリザーブドインスタンスを他の顧客へ販売する','AWS Supportに連絡し、リザーブドインスタンスの購入を無条件でキャンセル・全額返金してもらう','リザーブドインスタンスをコンバーティブルリザーブドインスタンスに変換してから使用を止める','Savings Plansへ切り替えることで、残存期間分の費用も自動的に無効化される'], correct:[0],
    why:['正しい。Amazon EC2 Reserved Instance Marketplaceでは、不要になったスタンダードリザーブドインスタンスの残りの契約期間分を他の顧客に販売し、費用の一部を回収できます。','誤り。リザーブドインスタンスの購入は原則として無条件でのキャンセル・全額返金はできません。','誤り。コンバーティブルリザーブドインスタンスへの変換は可能な場合がありますが、これは費用回収の方法ではなく、インスタンスタイプ等の変更に関する機能です。','誤り。Savings Plansへの切り替えは新たな契約であり、既存のリザーブドインスタンスの残存期間分の費用を自動的に無効化するものではありません。']},
  {id:'p594', domain:'concepts', type:'single', source:SOURCES.hybridCloud, text:'ある企業は、機密性の高いデータベースをオンプレミスのデータセンターに残しつつ、Webアプリケーション層はAWS上にデプロイし、AWS Direct Connectで両者を接続して一つのシステムとして運用したいと考えている。このようなデプロイモデルは何と呼ばれますか？',
    choices:['マルチクラウド','ハイブリッドクラウド','パブリッククラウド','プライベートクラウド'], correct:[1],
    why:['誤り。マルチクラウドは複数の異なるクラウドプロバイダーを組み合わせて利用する形態であり、オンプレミスとの接続を指す言葉ではありません。','正しい。オンプレミス環境とクラウド環境をDirect Connect等で接続し、両方を組み合わせて一つのシステムとして運用する形態はハイブリッドクラウドと呼ばれます。','誤り。パブリッククラウドは複数の組織が共有するクラウド環境のみを指し、オンプレミスとの組み合わせは含みません。','誤り。プライベートクラウドは単一組織専用の環境を指し、この設問のようなオンプレミスとクラウドの組み合わせを指す用語ではありません。']},
  {id:'p595', domain:'concepts', type:'multi', source:SOURCES.rtorpo, text:'ディザスタリカバリにおける「RTO」「RPO」に関する説明として正しいものを2つ選択してください。',
    choices:['RTOは、障害発生からシステムが復旧し業務を再開できるまでに許容される最大の時間を指す','RPOは、AWSが対象サービスの稼働率について保証する契約上の水準を指す','RPOは、障害発生時に許容できるデータ損失の時間的な範囲(最後の復旧ポイントからどこまで遡れるか)を指す','RTOとRPOはいずれも、AWSのサポートプランによって自動的に決定される固定値である'], correct:[0,2],
    why:['正しい。RTO(目標復旧時間)は、障害発生からシステムが復旧し業務を再開できるまでに許容される最大の時間を指します。','誤り。これはSLA(サービスレベルアグリーメント)の説明です。RPOはデータ損失の許容範囲を指します。','正しい。RPO(目標復旧時点)は、障害発生時に許容できるデータ損失の時間的な範囲を指します。','誤り。RTOとRPOは、サポートプランによって自動的に決まるものではなく、企業自身が事業要件に基づいて設定する目標値です。']},
  {id:'p596', domain:'concepts', type:'single', source:SOURCES.slaLegal, text:'あるAWSの有料サービスが、SLA(Service Level Agreement)で定める稼働率の水準を満たさなかった場合、利用者が受けられる対応として最も適切なものはどれですか？',
    choices:['自動的にそのサービスの利用が無料になり、以降の利用料金は一切発生しない','AWSから自動的に別のリージョンへのデータ移行が実施される','所定の条件を満たしてサービスクレジットを申請することで、未達成分に応じた補償を受けられる場合がある','IAMの権限が自動的に拡張され、追加のリソースを無償で利用できるようになる'], correct:[2],
    why:['誤り。SLA違反時に自動的に完全無料になるわけではなく、サービスクレジットという形で一部補償される仕組みです。','誤り。SLA違反時にAWSが自動的にデータを別リージョンへ移行する仕組みはありません。','正しい。SLAで定める稼働率の水準を満たさなかった場合、利用者は所定の条件(申請等)を満たすことでサービスクレジットの形で補償を受けられる場合があります。','誤り。SLA違反とIAM権限の拡張は無関係です。']},
  {id:'p597', domain:'tech', type:'single', source:SOURCES.gamelift, text:'あるゲーム開発会社は、セッションベースのオンラインマルチプレイヤーゲームのサーバーを、プレイヤー数の増減に応じて自動的にスケールさせながら運用したい。サーバーのプロビジョニングやスケーリングの管理をAWS側に任せたい場合、最も適したサービスはどれですか？',
    choices:['Amazon GameLift Servers（マネージド型のフリート）','Amazon GameLift Servers Anywhere（自己管理型のフリート）','Amazon EC2 Auto Scalingのみを単独で使用','AWS Batch'], correct:[0],
    why:['正しい。Amazon GameLift Serversのマネージド型フリートを使うと、ゲームサーバーのデプロイ・プレイヤー需要に応じた自動スケーリング・ヘルスモニタリングなどをAWS側に任せられます。','誤り。GameLift Servers Anywhereは、自社のオンプレミスやその他のクラウド上で自己管理するサーバーに対してGameLift Serversのセッション管理機能のみを利用する形態で、プロビジョニングやスケーリング自体は自分で管理します。','誤り。EC2 Auto Scalingだけでは、ゲームセッションの配置やプレイヤーのマッチメイキングなど、ゲーム専用の機能は提供されません。','誤り。AWS Batchはバッチ処理ジョブ向けのサービスで、リアルタイムのゲームセッション管理には適していません。']},
  {id:'p598', domain:'tech', type:'multi', source:SOURCES.gamelift, text:'Amazon GameLift Serversの「FlexMatch」機能の特徴として正しいものを2つ選択してください。',
    choices:['プレイヤーの属性(スキルレベルなど)に基づいた独自のマッチメイキングルールを設定できる','最大2人のプレイヤー同士の対戦にのみ対応しており、3人以上のチーム戦には対応していない','進行中のゲームセッションに空きが出た際、新たなプレイヤーを呼び込んで埋める「マッチバックフィル」に対応している','DDoS攻撃からゲームサーバーへの通信を保護するマネージドファイアウォール機能'], correct:[0,2],
    why:['正しい。FlexMatchでは、プレイヤーのスキルレベルなどの属性や複雑なロジックに基づいた独自のマッチメイキングルールを設定できます。','誤り。FlexMatchは2人から200人までの同時プレイヤーによる対戦に対応しており、チーム戦のバランス調整もサポートしています。','正しい。FlexMatchは、ゲームセッションの空いたプレイヤー枠を埋める「マッチバックフィル」に対応しており、セッションを満員の状態に保てます。','誤り。これはAWS Shieldの説明です。']},
  {id:'p599', domain:'tech', type:'single', source:SOURCES.chimeSdk, text:'あるSaaS企業は、自社のWebアプリケーションに、ビデオ通話・音声通話・画面共有の機能を組み込みたいと考えている。独自にリアルタイム通信基盤をゼロから構築・運用するのではなく、AWSが提供するコンポーネントを使って素早く実装したい場合、最も適したサービスはどれですか？',
    choices:['Amazon Connect','Amazon Chime SDK','Amazon API Gateway','AWS AppSync'], correct:[1],
    why:['誤り。Amazon Connectはコンタクトセンター(カスタマーサービス)向けのサービスです。','正しい。Amazon Chime SDKは、メッセージング・音声・ビデオ・画面共有の機能を自社アプリに組み込める、リアルタイムコミュニケーション向けのコンポーネント群で、独自の通信基盤をゼロから構築する必要がありません。','誤り。API Gatewayは、APIの作成・公開・管理を行うサービスで、リアルタイム通信コンポーネントそのものは提供しません。','誤り。AWS AppSyncはGraphQL APIを構築・管理するサービスです。']},
  {id:'p600', domain:'tech', type:'single', source:SOURCES.managedFlink, text:'あるデータエンジニアリングチームは、ストリーミングデータに対してJavaで記述した複雑なカスタムロジック（状態管理や外部データベースへの非同期呼び出しを含む）を適用し、長時間稼働する継続的なアプリケーションを構築したい。IDEを使ってコードをバージョン管理しながら開発したい場合、最も適した選択肢はどれですか？',
    choices:['Amazon Managed Service for Apache Flink Studio（ノートブック）','Amazon QuickSight','Amazon Managed Service for Apache Flink（DataStream APIを使ったFlinkアプリケーション）','AWS Glue'], correct:[2],
    why:['誤り。Studio(ノートブック)は、SQL・Python・Scalaを使ってその場でデータを対話的に探索・可視化するのに適していますが、Gitでのバージョン管理やCI/CDといった一般的な開発プロセスには、IDEで直接開発するDataStream APIの方が適しています。','誤り。QuickSightはBIダッシュボードサービスで、ストリーム処理エンジンではありません。','正しい。長時間稼働する継続的なアプリケーションで、状態管理や外部システムへの非同期呼び出しなど高度な制御が必要な場合は、IDEでJava/Python/ScalaのDataStream APIを使ってFlinkアプリケーションを開発するManaged Service for Apache Flinkが適しています。','誤り。AWS Glueはバッチ指向のETLサービスで、継続的なストリーム処理アプリケーションの実行基盤ではありません。']},
  {id:'p601', domain:'tech', type:'single', source:SOURCES.internetMonitor, text:'あるグローバル企業は、自社のWebアプリケーションについて、特定の国・地域のインターネットサービスプロバイダー(ISP)経由でアクセスするユーザーだけ通信の遅延や可用性低下が発生していることを把握し、改善策（別リージョンへのルーティングやCloudFrontの利用など）の提案も受けたいと考えている。最も適したサービスはどれですか？',
    choices:['AWS X-Ray','Amazon CloudWatch Synthetics','VPC Flow Logs','Amazon CloudWatch Internet Monitor'], correct:[3],
    why:['誤り。X-Rayは分散アプリケーション内部のリクエストのトレーシングを行うサービスで、エンドユーザー側のインターネット経路の問題は対象としません。','誤り。CloudWatch Syntheticsは、外形監視(定期的な疑似リクエスト)でエンドポイントの可用性を確認する機能で、ISP・地域別のインターネット経路の分析は行いません。','誤り。VPC Flow LogsはVPC内のネットワークインターフェースを通過するトラフィックの記録で、インターネット経路上のISP単位の性能分析はできません。','正しい。Amazon CloudWatch Internet Monitorは、クライアントの所在地とISP(ネットワーク)の組み合わせ(city-networks)ごとに、アプリケーションのインターネット経由の性能・可用性を測定し、別リージョンやCloudFrontの利用など改善のための提案も提供します。']},
  {id:'p602', domain:'security', type:'single', source:SOURCES.paymentCryptography, text:'ある決済処理会社(プロセッサー)は、PCI基準に準拠したカード会員PINの処理やCVV生成などの暗号処理を行いたいが、自社でPCI PTS認定のハードウェアセキュリティモジュール(HSM)を調達・運用する負担は避けたいと考えている。最も適したサービスはどれですか？',
    choices:['AWS Payment Cryptography','AWS KMS','AWS CloudHSM','AWS Certificate Manager (ACM)'], correct:[0],
    why:['正しい。AWS Payment Cryptographyは、PCI基準(PCI PIN、PCI P2PE、PCI DSS)に準拠した決済処理向けの暗号機能・鍵管理を、専用のペイメントHSMを自前で調達せずに利用できるマネージド型サービスです。','誤り。KMSは汎用的なデータ暗号化向けの鍵管理サービスで、決済業界特有のPIN変換やCVV生成といった機能は提供しません。','誤り。CloudHSMは汎用的な専有HSMインスタンスを提供しますが、決済処理に特化した機能・PCI認定は前提としていません。','誤り。ACMはSSL/TLS証明書の発行・管理サービスです。']},
  {id:'p603', domain:'security', type:'single', source:SOURCES.paymentCryptography, text:'AWS Payment CryptographyとAWS KMSの違いとして正しいものはどれですか？',
    choices:['AWS KMSはPCI PIN基準に準拠したカード会員PINの変換機能を提供するが、AWS Payment Cryptographyは提供しない','AWS Payment Cryptographyはカード会員PINの変換やCVV・ARQCの生成・検証など決済処理特有の暗号操作に特化しているが、AWS KMSは汎用的なデータの暗号化・復号向けの鍵管理に特化している','AWS Payment Cryptographyは無料で利用できるが、AWS KMSは従量課金制である','両者は全く同じ機能を提供する互換サービスであり、用途による使い分けは存在しない'], correct:[1],
    why:['誤り。PCI PIN基準に準拠したカード会員PINの変換などの機能を提供するのはAWS Payment Cryptographyの方です。','正しい。AWS Payment Cryptographyはカード会員PINの変換、CVV/CVV2/ARQCの生成・検証など決済処理特有の暗号操作に特化しているのに対し、AWS KMSは汎用的なデータの暗号化・復号のための鍵管理に特化しています。','誤り。両サービスとも従量課金制(pay-as-you-go)で提供されます。','誤り。用途が異なる別サービスであり、互換性のある同一機能を提供するものではありません。']},
  {id:'p604', domain:'security', type:'single', source:SOURCES.wafAtp, text:'あるWebサービスは、ログイン画面に対して、漏洩した認証情報を使った不正ログイン試行(アカウントテイクオーバー)やブルートフォース攻撃・クレデンシャルスタッフィングを検知・ブロックしたいと考えている。最も適した機能はどれですか？',
    choices:['AWS WAF Fraud Control - Account Creation Fraud Prevention (ACFP)','AWS Shield Advanced','AWS WAF Fraud Control - Account Takeover Prevention (ATP)','Amazon CognitoのThreat Protection機能'], correct:[2],
    why:['誤り。ACFPはアカウント新規登録(サインアップ)ページを偽アカウント作成から保護する機能であり、既存アカウントへの不正ログインを防ぐものではありません。','誤り。Shield AdvancedはDDoS攻撃からの保護に特化した機能で、漏洩認証情報を使ったログイン試行の検知は主目的ではありません。','正しい。AWS WAF Fraud Control - Account Takeover Prevention (ATP)は、アプリケーションのログインエンドポイントへのリクエストを検査し、漏洩した認証情報のデータベースと照合したり、ブルートフォース攻撃・クレデンシャルスタッフィングのパターンを検知してブロックする管理ルールグループです。','誤り。Amazon CognitoのThreat Protection機能はCognitoユーザープール向けの別の保護機能であり、AWS WAFのATP機能はCognitoユーザープールには適用されません(ATPは自社でホストする独自のログインエンドポイントが対象です)。']},
  {id:'p605', domain:'security', type:'single', source:SOURCES.wafAcfp, text:'あるオンラインサービスは、新規アカウント登録(サインアップ)ページに対して、ボットによる大量の偽アカウント作成(新規登録ボーナスの不正利用やなりすまし等の目的)を検知・ブロックしたいと考えている。最も適した機能はどれですか？',
    choices:['AWS WAF Fraud Control - Account Takeover Prevention (ATP)','AWS Firewall Manager','Amazon GuardDuty','AWS WAF Fraud Control - Account Creation Fraud Prevention (ACFP)'], correct:[3],
    why:['誤り。ATPは既存アカウントへの不正ログイン(アカウントテイクオーバー)を防ぐ機能で、サインアップページの保護を主目的とはしていません。','誤り。Firewall Managerは複数アカウント・リソースに対してWAFルールなどを一元的に適用するサービスで、偽アカウント作成の検知自体は行いません。','誤り。GuardDutyはAWSアカウント内の脅威検知サービスで、Webアプリケーションのサインアップページへのリクエスト内容は検査対象ではありません。','正しい。AWS WAF Fraud Control - Account Creation Fraud Prevention (ACFP)は、アカウント新規登録(サインアップ)エンドポイントへのリクエストを検査し、行動分析や機械学習を用いて偽アカウント作成の試みを検知・自動的にブロックする管理ルールグループです。']},
  {id:'p606', domain:'concepts', type:'single', source:SOURCES.wafPerformance, text:'AWS Well-Architected Frameworkの「パフォーマンス効率の柱」の設計原則の一つ「数分でグローバル展開する(Go global in minutes)」が重視する内容として最も適切なものはどれですか？',
    choices:['複数のAWSリージョンにワークロードを配置することで、低コストで世界中のユーザーに近い場所からサービスを提供し、レイテンシーを改善できること','新しいインスタンスタイプやサービスが登場した際、それを迅速に試して採用すること','需要の変化に応じてリソースを自動的に増減させること','システムの状態を常にコードとして定義し、変更をバージョン管理すること'], correct:[0],
    why:['正しい。「数分でグローバル展開する」という設計原則は、複数のAWSリージョンにワークロードを配置することで、低コストで世界中のユーザーに近い場所からサービスを提供し、レイテンシーを改善できることを重視しています。','誤り。これは設計原則「高度なテクノロジーを誰でも使えるようにする」の内容です。','誤り。これは弾力性(Elasticity)に関する一般的な説明です。','誤り。これは運用上の優秀性の柱の設計原則「運用をコードとして実行する」の内容です。']},
  {id:'p607', domain:'concepts', type:'single', source:SOURCES.cloudValueFramework, text:'AWSのCloud Value Frameworkにおける「運用上の回復性(Operational Resilience)」という価値の観点が重視しているものとして最も適切なものはどれですか？',
    choices:['インフラの運用・保守といった差別化につながらない作業から人員を解放すること','障害やセキュリティインシデントの発生時にも、サービスの中断を最小限に抑え、迅速に復旧できるようにすること','電力消費量を削減し環境負荷を下げること','新しいリージョンへの展開や新サービスの立ち上げにかかる期間を短縮すること'], correct:[1],
    why:['誤り。これはスタッフの生産性向上(Staff Productivity)の観点です。','正しい。運用上の回復性(Operational Resilience)は、障害やセキュリティインシデントの発生時にもサービスの中断を最小限に抑え、迅速に復旧できるようにすることを重視する価値の観点です。','誤り。これは持続可能性(サステナビリティ)の観点です。','誤り。これはビジネスアジリティ(Business Agility)の観点です。']},
  {id:'p608', domain:'billing', type:'single', source:SOURCES.capacityReservationFleet, text:'ある企業は、Amazon EC2のCapacity Reservation Fleetを使って、複数のインスタンスタイプ(例: m4.16xlarge、m5.24xlarge、m5.16xlarge)に優先順位を付けて容量を確保したいと考えている。優先順位(priority)の扱いとして正しいものはどれですか？',
    choices:['優先順位の数値が大きいインスタンスタイプほど優先的に容量確保が試みられる','優先順位は参考情報にすぎず、実際にはすべてのインスタンスタイプへ均等に容量が割り当てられる','優先順位の数値が小さいインスタンスタイプほど優先され、そのタイプで十分な空き容量がない場合に次に優先順位の高いタイプが試みられる','優先順位はAZ(アベイラビリティーゾーン)ごとに自動的に再計算され、ユーザーが指定することはできない'], correct:[2],
    why:['誤り。優先順位は数値が小さいほど優先度が高くなります。','誤り。Capacity Reservation Fleetは現在「prioritized」という割り当て戦略のみをサポートしており、優先順位に基づいて順番に容量確保を試みます。','正しい。Capacity Reservation Fleetの優先順位は数値が小さいほど優先度が高く、優先度の高いインスタンスタイプで十分な空き容量が確保できない場合に、次に優先順位の高いインスタンスタイプでの容量確保が試みられます。','誤り。優先順位はFleetの作成時にユーザー自身が各インスタンスタイプに割り当てる値です。']},
  {id:'p609', domain:'billing', type:'single', source:SOURCES.capacityReservationFleet, text:'Amazon EC2のCapacity Reservation Fleetで確保した容量について、実際にその容量分のインスタンスを起動していない(未使用の)場合の課金として正しいものはどれですか？',
    choices:['未使用分は自動的に無料になる','未使用分にはスポット料金が適用される','Capacity Reservation Fleetを作成すると自動的にオンデマンド料金から割引が適用される','通常の単体のOn-Demand Capacity Reservationと同様、確保した容量を実際に使用しているかどうかにかかわらず、オンデマンド料金相当の費用が発生する'], correct:[3],
    why:['誤り。確保した容量は未使用であっても無料にはなりません。','誤り。Capacity Reservation Fleetはオンデマンドの容量確保の仕組みであり、スポット料金は適用されません。','誤り。Capacity Reservation Fleet自体には割引はなく、確保した容量にはオンデマンド料金相当の費用が発生します。','正しい。Capacity Reservation Fleetは、通常の単体のOn-Demand Capacity Reservationと同様に、確保した容量を実際に使用しているかどうかにかかわらず、オンデマンド料金相当の費用が発生する仕組みです。']},
  {id:'p610', domain:'tech', type:'single', source:SOURCES.cloudWan, text:'ある企業は、世界中に展開する多数の支社・データセンター・複数リージョンのVPCを、単一のダッシュボードから宣言的なポリシーで一元的に接続・管理したいと考えている。個々のリージョンごとに手動でピアリングやルーティングを設定するのではなく、AWSに接続構成の詳細を任せたい場合、最も適したサービスはどれですか？',
    choices:['AWS Cloud WAN','AWS Transit Gateway(単体)','AWS Direct Connect','Amazon VPCピアリング接続'], correct:[0],
    why:['正しい。AWS Cloud WANは、支社・データセンター・複数リージョンのVPCを、単一のダッシュボードとJSON形式のポリシーで宣言的に接続・管理できるマネージド型のWANサービスで、リージョンごとの手動設定をAWSに任せられます。','誤り。Transit Gateway単体では、複数リージョンにまたがる接続はリージョンごとに個別の設定・ピアリングが必要です。','誤り。Direct Connectはオンプレミスとの専用線接続サービスであり、複数リージョン・複数拠点を宣言的に一元管理する仕組みではありません。','誤り。VPCピアリングは1対1の接続であり、大規模な拠点網を単一ポリシーで一元管理する仕組みではありません。']},
  {id:'p611', domain:'tech', type:'single', source:SOURCES.kinesisVideo, text:'ある企業は、数千台規模の防犯カメラからのライブ映像を継続的にクラウドへ取り込み、フレーム単位でリアルタイムに処理するカスタムアプリケーションを構築したいと考えている。映像は取り込み・再生時刻によってインデックスされ、指定した保持期間保存される必要がある。最も適したサービスはどれですか？',
    choices:['Amazon Kinesis Data Streams','Amazon Kinesis Video Streams','Amazon S3','AWS Elemental MediaLive'], correct:[1],
    why:['誤り。Kinesis Data Streamsは構造化されたレコードデータ向けの汎用ストリーミングサービスで、映像コーデックの取り込みや時刻インデックス付き再生には最適化されていません。','正しい。Kinesis Video Streamsは、多数のデバイスからのライブ映像を取り込み、取り込み・再生時刻でインデックスして保持期間を指定して保存しつつ、フレーム単位でのリアルタイム処理を可能にするサービスです。','誤り。S3は汎用のオブジェクトストレージであり、映像のライブ取り込みやフレーム単位の再生・インデックス機能そのものは提供しません。','誤り。MediaLiveはライブ映像を放送・配信向けの形式にリアルタイムでエンコードするサービスで、デバイスからの映像取り込み・カスタムアプリ向け分析を主目的とはしていません。']},
  {id:'p612', domain:'tech', type:'single', source:SOURCES.cwSynthetics, text:'あるWebサービス運営チームは、実際の顧客トラフィックが少ない時間帯でも、顧客が辿るのと同じ操作手順(ログイン、検索、購入など)を定期的なスケジュールで自動的に再現し、問題を顧客より先に発見したいと考えている。最も適したサービスはどれですか？',
    choices:['Amazon CloudWatchアラーム(メトリクスのしきい値監視)','AWS X-Ray','Amazon CloudWatch Synthetics(カナリア)','Amazon Route 53ヘルスチェック'], correct:[2],
    why:['誤り。CloudWatchアラームはメトリクスのしきい値超過を検知する仕組みであり、顧客の操作手順そのものを再現するものではありません。','誤り。X-Rayは実際のリクエストの分散トレーシングを行う機能であり、顧客不在の時間帯に操作を能動的に再現するものではありません。','正しい。CloudWatch Synthetics(カナリア)は、顧客が辿るのと同じ操作手順を定期的なスケジュールで自動的に再現するスクリプトで、実際の顧客トラフィックが無くても問題を顧客より先に発見できます。','誤り。Route 53ヘルスチェックはエンドポイントの単純な生死確認が中心で、複数ステップの操作手順の再現は行いません。']},
  {id:'p613', domain:'tech', type:'single', source:SOURCES.fargate, text:'ある企業は、Amazon ECSとAmazon EKSの両方でコンテナワークロードを運用しており、どちらのオーケストレーターを使う場合でも、基盤となるEC2インスタンスを自前でプロビジョニング・管理せずに済む共通のコンピューティング方式を採用したいと考えている。最も適したものはどれですか？',
    choices:['Amazon EC2 Auto Scalingグループ上で稼働するECS/EKSのEC2起動タイプ','AWS Lambda','Amazon Lightsail','AWS Fargate(ECSタスク・EKSポッドの両方のコンピューティングタイプとして利用可能)'], correct:[3],
    why:['誤り。EC2起動タイプでは、引き続き利用者自身がEC2インスタンスのプロビジョニングやパッチ適用を行う必要があります。','誤り。LambdaはECS/EKSのタスク・ポッドの実行基盤そのものではなく、関数単位の別のサーバーレスコンピューティングサービスです。','誤り。LightsailはシンプルなVPS(仮想サーバー)サービスであり、ECS/EKSのコンピューティングタイプではありません。','正しい。AWS Fargateは、Amazon ECSのタスクとAmazon EKSのポッドの両方に使えるサーバーレスのコンピューティングタイプで、どちらのオーケストレーターでも基盤のEC2インスタンスを自前で管理する必要がありません。']},
  {id:'p614', domain:'tech', type:'single', source:SOURCES.redshift, text:'あるデータ分析チームは、Amazon Redshiftクラスタ内の既存テーブルと、Amazon S3に蓄積された大量の生ログデータを、S3側のデータをRedshiftへロードすることなく、SQLで結合して分析したいと考えている。最も適したRedshiftの機能はどれですか？',
    choices:['Amazon Redshift Spectrum','Amazon Redshiftの自動ワークロード管理(WLM)','Amazon Redshiftのリザーブドノード','Amazon Redshiftのコンカレンシースケーリング'], correct:[0],
    why:['正しい。Amazon Redshift Spectrumを使うと、S3に蓄積されたデータをRedshiftへロードすることなく、Redshiftクラスタ内の既存テーブルとSQLで直接結合して分析できます。','誤り。WLMはクエリの実行キューやリソース配分を管理する機能で、S3データへの直接クエリ機能ではありません。','誤り。リザーブドノードは料金の割引プランであり、S3データへの直接クエリ機能ではありません。','誤り。コンカレンシースケーリングは同時実行クエリの急増に自動対応する機能で、S3データへの直接クエリ機能ではありません。']},
  {id:'p615', domain:'tech', type:'single', source:SOURCES.rekognition, text:'あるセキュリティシステムは、Amazon Kinesis Video Streamsで取り込んだライブ映像をリアルタイムに分析し、映像内の人物の顔を検出・認識したいと考えている。機械学習モデルを独自に開発せずにこれを実現したい場合、最も適したサービスはどれですか？',
    choices:['Amazon Rekognition Video','Amazon Comprehend','Amazon Transcribe','Amazon Polly'], correct:[0],
    why:['正しい。Amazon Rekognition VideoはKinesis Video Streamsと統合でき、ライブ映像をリアルタイムに分析して顔の検出・認識などを行えます。','誤り。Comprehendはテキストの自然言語処理サービスであり、映像内の顔検出は行いません。','誤り。Transcribeは音声からテキストへの変換サービスであり、映像内の顔検出は行いません。','誤り。Pollyはテキストから音声を合成するサービスであり、映像内の顔検出は行いません。']},
  {id:'p616', domain:'security', type:'single', source:SOURCES.guardduty, text:'あるセキュリティ運用チームは、EKSクラスタ・Fargate上のECS・EC2インスタンス内で実際に実行されているプロセスやファイルアクセス、ネットワーク接続といったOSレベルの挙動を継続的に監視し、侵害の兆候を検知したいと考えている。EBSボリュームのエージェントレススキャンだけでは検知できないこの要件に最も適した機能はどれですか？',
    choices:['GuardDutyのMalware Protection for EC2','AWS Config','GuardDutyのRuntime Monitoring','Amazon Inspector'], correct:[2],
    why:['誤り。Malware Protection for EC2はエージェントレスでEBSボリュームをスキャンしてマルウェアを検出する機能であり、実行中のプロセスやネットワーク接続などのOSレベルの継続的な挙動監視は行いません。','誤り。AWS Configはリソースの構成変更履歴やコンプライアンス評価を行うサービスで、実行中のプロセス等のランタイムの挙動監視は行いません。','正しい。GuardDutyのRuntime Monitoringは、セキュリティエージェントを使ってEKS・Fargate上のECS・EC2のOSレベル・ネットワーク・ファイルイベントを継続的に監視し、不審な挙動を検知します。','誤り。Amazon Inspectorは主にOS・アプリケーションの脆弱性スキャンを行うサービスで、実行中のプロセスの継続的なランタイム挙動監視とは異なります。']},
  {id:'p617', domain:'security', type:'single', source:SOURCES.wafAtp, text:'CloudFrontディストリビューションを保護しているAWS WAFのATP(Account Takeover Prevention)に関する説明として正しいものはどれですか？',
    choices:['ATPはログイン試行のリクエストのみを検査し、アプリケーションからのレスポンスは一切検査しない','ATPはAmazon Cognitoユーザープールのログインにも標準で適用できる','ATPのレスポンス検査は、Webトラフィックのレイテンシーを増加させないよう同期的に処理される','CloudFrontディストリビューションを保護する場合に限り、ログイン試行に対するアプリケーションのレスポンス(成功/失敗)も追加で検査し、失敗率の高いクライアントセッションやIPアドレスを一時的にブロックできる'], correct:[3],
    why:['誤り。CloudFrontディストリビューションの場合、ATPはリクエストに加えてレスポンスも検査できます。','誤り。ATP機能はAmazon Cognitoユーザープールには適用されません。','誤り。ATPのレスポンス検査は非同期で処理されるため、Webトラフィックのレイテンシーを増加させません。','正しい。CloudFrontディストリビューションを保護する場合に限り、ATPはログイン試行に対するレスポンス(成功/失敗)も追加で検査し、失敗率の高いクライアントセッションやIPアドレスを一時的にブロックできます。']},
  {id:'p618', domain:'security', type:'single', source:SOURCES.wafAcfp, text:'あるオンラインサービスは、新規アカウント登録(サインアップ)ページとログインページの両方を、それぞれ偽アカウント作成とアカウントテイクオーバーから保護したいと考えている。AWS WAFでこれを実現する方法として正しいものはどれですか？',
    choices:['ACFP(Account Creation Fraud Prevention)とATP(Account Takeover Prevention)は、いずれも独立したマネージドルールグループであり、同一のWeb ACLに両方追加して、それぞれサインアップエンドポイントとログインエンドポイントを保護できる','ACFPとATPは同時に同一のWeb ACLへ追加できないため、どちらか一方を選ぶ必要がある','ACFPを有効化すると、ATPの機能も自動的に含まれるため、ATPを別途追加する必要はない','サインアップページとログインページの両方を保護するには、AWS Shield Advancedの契約が別途必須である'], correct:[0],
    why:['正しい。ACFPとATPはそれぞれ独立したマネージドルールグループであり、同一のWeb ACLに両方を追加することで、サインアップエンドポイントとログインエンドポイントをそれぞれ保護できます。','誤り。両者は同一のWeb ACLに同時に追加して併用できます。','誤り。ACFPとATPは別々の機能であり、一方を有効化しても他方が自動的に含まれることはありません。','誤り。ACFP・ATPの利用にShield Advancedの契約は必須ではありません。']},
  {id:'p619', domain:'concepts', type:'multi', source:SOURCES.waLens, text:'AWS Well-Architected Toolにおける「レンズ(Lens)」の適用に関する説明として正しいものを2つ選択してください。',
    choices:['1つのワークロードに対して、AWS公式のレンズカタログやカスタムレンズを複数追加して評価できる','1つのワークロードには1種類のレンズしか適用できず、途中で変更するには新しいワークロードとして作り直す必要がある','ワークロードを定義すると、基本となる「AWS Well-Architected Framework Lens」が自動的に適用される','レンズはAWS公式のものしか利用できず、組織独自のベストプラクティスを反映したカスタムレンズは作成できない'], correct:[0,2],
    why:['正しい。1つのワークロードに対して、AWS公式のレンズカタログやカスタムレンズを複数追加して評価できます。','誤り。1つのワークロードに複数のレンズを追加でき、新しいワークロードとして作り直す必要はありません。','正しい。ワークロードを定義すると、基本となるAWS Well-Architected Framework Lensが自動的に適用されます。','誤り。組織独自のベストプラクティスを反映したカスタムレンズも作成・共有できます。']},
  {id:'p620', domain:'concepts', type:'single', source:SOURCES.transform, text:'ある企業は、長年運用してきた.NET Framework製の社内業務アプリケーションを、コンテナ化してLinux環境でも動かせるように、.NET 8以降へモダナイズしたいと考えている。できるだけ人手を介さずにこの変換作業を支援してほしい場合、最も適したサービスはどれですか？',
    choices:['AWS Elastic Beanstalk','AWS Transform','AWS CodeBuild','Amazon Q Developer(コード生成支援のみ)'], correct:[1],
    why:['誤り。Elastic Beanstalkはアプリケーションのデプロイ・運用を簡素化するサービスで、.NET Frameworkから.NET 8以降へのコード変換(モダナイゼーション)自体は行いません。','正しい。AWS Transformは、AIエージェントを使って.NET Framework製アプリケーションを.NET 8以降へモダナイズし、コンテナ化やLinux環境での実行を可能にする変換作業を支援します(マインフレーム・VMwareワークロードの移行にも対応)。','誤り。CodeBuildはビルド・テストを自動化するCI/CDサービスで、.NETのモダナイゼーション変換そのものを行う専用機能ではありません。','誤り。Amazon Q Developerはコード生成・開発支援ツールであり、AWS Transformほど包括的な.NETモダナイゼーションのワークフローを提供するものではありません。']},
  {id:'p621', domain:'tech', type:'single', source:SOURCES.cloudWan, text:'AWS Cloud WANの「コアネットワークポリシー(core network policy)」に関する説明として正しいものはどれですか？',
    choices:['セキュリティグループのルールをJSON形式で記述したもので、EC2インスタンス単位の通信制御にのみ使用される','各リージョンのトランジットゲートウェイ間のピアリングを、利用者が1つずつ手動で設定するための手順書','セグメントやアタッチメントのルーティングを宣言的に定義する単一のポリシードキュメントで、これを適用するとAWSが複数リージョンのコアネットワークエッジを自動的にフルメッシュでピアリングする','単一リージョン内でのみ有効で、複数リージョンにまたがる設定には利用できない'], correct:[2],
    why:['誤り。これはセキュリティグループの説明であり、コアネットワークポリシーとは異なる概念です。','誤り。コアネットワークポリシーを適用すると、リージョン間のピアリングはAWSが自動的に構成します。','正しい。コアネットワークポリシーは、セグメントやアタッチメントのルーティングを宣言的に定義する単一のポリシードキュメントで、適用するとAWSが複数リージョンのコアネットワークエッジを自動的にフルメッシュでピアリングします。','誤り。コアネットワークポリシーでは、ポリシードキュメント内で複数のAWSリージョンを定義でき、リージョンをまたいだ構成が可能です。']},
  {id:'p622', domain:'tech', type:'multi', source:SOURCES.cwSynthetics, text:'Amazon CloudWatch Synthetics(カナリア)の実装に関する説明として正しいものを2つ選択してください。',
    choices:['カナリアはEC2インスタンス上でのみ実行可能であり、サーバーレスでは利用できない','カナリアはNode.js、Python、Javaのいずれかで書かれたスクリプトとして実装され、内部的にAWS Lambda関数として実行される','カナリアの実行頻度は最短でも1時間に1回である','カナリアは最短1分間隔で定期的に実行するようスケジュールできる'], correct:[1,3],
    why:['誤り。カナリアはAWS Lambda関数として実行され、EC2インスタンスの管理は不要です。','正しい。カナリアはNode.js、Python、Javaのいずれかで書かれたスクリプトとして実装され、内部的にAWS Lambda関数として実行されます。','誤り。カナリアは最短1分間隔で実行するようスケジュールできます。','正しい。カナリアはcron式やrate式を使って、最短1分間隔で定期的に実行するようスケジュールできます。']},
  {id:'p623', domain:'concepts', type:'single', source:SOURCES.prescriptiveGuidance, text:'あるIT部門が、大規模なオンプレミスからAWSへの移行プロジェクトを計画するにあたり、AWSの技術専門家がまとめた、具体的なアーキテクチャ・手順・コードサンプルを含む移行パターン集を参考にしたいと考えている。最も適した情報源はどれですか？',
    choices:['AWS Prescriptive Guidance','AWS Trusted Advisor','AWS Artifact','AWS Cost and Usage Report (CUR)'], correct:[0],
    why:['正しい。AWS Prescriptive Guidanceは、AWSの技術専門家がまとめた、具体的なアーキテクチャ・手順・コードサンプルを含む移行・モダナイゼーションのパターン集やガイドを提供するコンテンツライブラリです。','誤り。Trusted Advisorは自分のAWS環境に対する推奨事項を提示するサービスで、移行パターン集ではありません。','誤り。Artifactはコンプライアンスレポートをダウンロードするポータルです。','誤り。CURはコストと使用状況のレポートであり、移行パターン集ではありません。']},
  {id:'p624', domain:'concepts', type:'single', source:SOURCES.resilienceHub, text:'あるチームがAWS Resilience Hubでアプリケーションのレジリエンス評価(アセスメント)を実行したところ、目標とするRTO/RPOを満たしていないという結果が出た。実際の障害を模したテストでアーキテクチャの弱点を検証したい場合、Resilience Hubが提供する機能として正しいものはどれですか？',
    choices:['アプリケーションのソースコードを自動的に修正し、レジリエンス目標を満たす構成に書き換える','アプリケーションの構成に基づいてAWS Fault Injection Service (FIS)の実験を推奨し、その実験を実行することでレジリエンススコアの改善状況を追跡できる','障害発生時に自動的に別リージョンへフェイルオーバーする機能を、追加設定なしで有効化する','本番環境とは別に、同一構成のステージング環境を自動的に複製する'], correct:[1],
    why:['誤り。Resilience Hubはソースコードを自動修正する機能は提供していません。','正しい。Resilience Hubは、オンボードしたアプリケーションの構成に基づいてAWS Fault Injection Service (FIS)の実験を推奨し、その実験を実行(または独自のFIS実験を実行)することでレジリエンススコアの改善状況を追跡できます。','誤り。実際のフェイルオーバーの仕組み自体はRoute 53やアプリケーション側の構成で実装する必要があり、Resilience Hubはそれを評価・推奨する側のサービスです。','誤り。環境の複製自体を行うサービスではありません。']},
  {id:'p625', domain:'concepts', type:'single', source:SOURCES.cloudValueFramework, text:'AWSのCloud Value Framework（クラウド・バリュー・フレームワーク）における「コスト削減(Cost Savings)」の観点が重視しているものとして最も適切なものはどれですか？',
    choices:['従業員が新しい技術の学習に充てられる時間を増やすこと','障害発生時にシステムが自動的に復旧する能力を高めること','従量課金制による無駄なキャパシティの削減や、スケールメリットによる単価低下など、オンプレミス運用と比較したインフラ・運用コストの低減','新しいリージョンへのサービス展開を短期間で実現すること'], correct:[2],
    why:['これは「スタッフの生産性向上(Staff Productivity)」の観点の説明です。','これは「運用上の回復性(Operational Resilience)」の観点の説明です。','正しい。「コスト削減(Cost Savings)」の観点は、従量課金制による無駄なキャパシティの削減や、AWSの規模の経済による単価低下など、オンプレミス運用と比較したインフラ・運用コストの低減を重視します。','これは「ビジネスアジリティ(Business Agility)」の観点の説明です。']},
  {id:'p626', domain:'security', type:'single', source:SOURCES.inspector, text:'あるソフトウェア開発チームは、アプリケーションの実行環境(EC2やコンテナ)の脆弱性スキャンだけでなく、GitHubリポジトリ上のアプリケーションのソースコード自体や、利用しているサードパーティのライブラリ（依存関係）、Infrastructure as Codeの定義ファイルについても、コーディングの早い段階で脆弱性を検出したいと考えている。最も適したサービス・機能はどれですか？',
    choices:['Amazon Inspectorの標準機能であるEC2・ECR・Lambdaの継続的スキャン','AWS Config','Amazon GuardDuty','Amazon InspectorのCode Security機能（ソースコード・サードパーティの依存関係・Infrastructure as Codeの脆弱性スキャンに対応し、リポジトリ単位でスキャン設定を構成できる）'], correct:[3],
    why:['誤り。これはInspectorの従来の機能で、実行環境(EC2・ECR上のコンテナイメージ・Lambda関数)のスキャンが対象であり、ソースコードリポジトリ自体のスキャンは対象外です。','誤り。Configはリソースの構成変更を記録・評価するサービスで、ソースコードの脆弱性スキャンは行いません。','誤り。GuardDutyは脅威検知サービスであり、ソースコードの静的スキャンは行いません。','正しい。Amazon InspectorのCode Security機能は、第一者のソースコード・サードパーティの依存関係・Infrastructure as Codeの脆弱性をスキャンでき、コードリポジトリ単位でスキャン設定(頻度など)を構成できます。']},
  {id:'p627', domain:'security', type:'single', source:SOURCES.guardduty, text:'ある企業は、ユーザーがアップロードした画像・ドキュメントファイルを保存するAmazon S3バケットについて、悪意のあるファイルが混入していないかを継続的に検査し、不審なファイルを検知した場合はEventBridge経由で自動的に隔離(別バケットへの移動)したいと考えている。最も適したサービスはどれですか？',
    choices:['Amazon GuardDuty Malware Protection for S3','Amazon Macie','AWS Config','Amazon Inspector'], correct:[0],
    why:['正しい。GuardDuty Malware Protection for S3は、S3へ新しくアップロードされたオブジェクトをマルウェアの観点でスキャンし、結果をEventBridgeへ発行することで、隔離などの自動対応ワークフローを構築できます。','誤り。Macieは個人情報(PII)などの機密データの検出を専門とするサービスで、マルウェアスキャンは行いません。','誤り。Configはリソースの構成変更を記録するサービスであり、ファイルの内容のマルウェアスキャンは行いません。','誤り。InspectorはEC2・ECR・Lambda等の脆弱性スキャンが中心で(Code Securityはソースコード対象)、S3オブジェクトのマルウェアスキャンは対象外です。']},
  {id:'p628', domain:'security', type:'single', source:SOURCES.iamIdentityCenter, text:'ある企業は、多数のプロジェクトごとにAWSリソースへのアクセス権限を管理する際、プロジェクトが増えるたびに新しい許可セット(Permission Set)を作るのではなく、ユーザーの「所属チーム」属性とリソースに付与したタグを比較して自動的にアクセスを許可する方式にしたいと考えている。AWS IAM Identity Centerでこれを実現する仕組みは何ですか？',
    choices:['ロールベースアクセス制御(RBAC)専用の許可セットを、プロジェクトごとに個別作成する','属性ベースアクセス制御(ABAC)。ユーザーの属性をIAMセッションに渡し、aws:PrincipalTag等の条件キーを使ってリソースのタグと比較するポリシーを作成することで、新しいリソースが作成・タグ付けされるたびに個別の許可セットを追加せずにアクセス制御できる','AWS Organizationsのサービスコントロールポリシー(SCP)でアカウント単位の上限を設定する','AWS IAM Access Analyzerで未使用のアクセス許可を定期的に検出し手動で削除する'], correct:[1],
    why:['誤り。これは設問の課題(プロジェクトが増えるたびに個別の許可セットを作る手間)を解消する方法ではありません。','正しい。属性ベースアクセス制御(ABAC)を使うと、ユーザーの属性をIAMセッションに渡し、aws:PrincipalTagなどの条件キーでリソースのタグと比較するポリシーを作成できるため、新しいリソースが適切にタグ付けされていれば、個別の許可セットを追加せずにアクセスを制御できます。','誤り。SCPは権限の上限を設定する仕組みであり、属性に基づく動的なアクセス制御とは異なります。','誤り。Access Analyzerの未使用アクセス分析とは異なる機能です。']},
  {id:'p629', domain:'security', type:'multi', source:SOURCES.secretsmanager, text:'AWS Secrets Managerの「シークレットのリージョン間レプリケーション(Replication)」に関する説明として正しいものを2つ選択してください。',
    choices:['プライマリリージョンでシークレットをローテーションすると、新しい値は自動的にレプリカへ伝播され、レプリカごとに個別にローテーションを設定する必要はない','レプリカシークレットは暗号化されずにコピーされ、転送中のみ暗号化される','レプリカは暗号化されたシークレットデータとタグ・リソースポリシーなどのメタデータを保持し、必要であれば後からプライマリから切り離して独立したシークレットに昇格(プロモート)できる','商用リージョンとAWS GovCloud (US)やAWS中国リージョンとの間でも自由にレプリケーションできる'], correct:[0,2],
    why:['正しい。ローテーションはプライマリリージョンで実行され、新しい値は自動的に関連するすべてのレプリカへ伝播されるため、レプリカごとに個別のローテーション設定は不要です。','誤り。レプリカの暗号化されたシークレットデータは保管時も暗号化された状態でコピーされます。','正しい。レプリカは暗号化されたシークレットデータとタグ・リソースポリシーなどのメタデータを保持し、必要であれば後からプライマリから切り離して独立したシークレットに昇格できます。','誤り。商用リージョンとAWS GovCloud (US)やAWS中国リージョンなどの特殊なリージョンとの間ではレプリケーションできません。']},
  {id:'p630', domain:'billing', type:'single', source:SOURCES.activate, text:'ある自己資金(ブートストラップ)で運営しているスタートアップが、特定のベンチャーキャピタルやアクセラレーターの紹介を受けていない状態で、AWS Activateのクレジットに申請したいと考えている。利用すべき仕組みはどれですか？',
    choices:['Activate Portfolio(プロバイダーの紹介が必要な仕組み)','AWS Marketplaceのプライベートオファー','Activate Founders(自己資金のスタートアップが直接申請できる仕組み)','AWS Support Business Support+プラン'], correct:[2],
    why:['誤り。Activate Portfolioは、VCやアクセラレーターなどの提供者(Activate Provider)から紹介されたスタートアップ向けの仕組みで、提供者のOrg IDが必要です。','誤り。AWS Marketplaceのプライベートオファーとは別の仕組みです。','正しい。Activate Foundersは、自己資金(ブートストラップ)のスタートアップが、提供者の紹介なしに直接申請できる仕組みです。','誤り。これはAWSサポートプランであり、AWS Activateのクレジット申請経路とは異なります。']},
  {id:'p631', domain:'billing', type:'single', source:SOURCES.supportApp, text:'ある開発チームは、AWSサポートケースの作成・更新・解決を、AWS Support Centerコンソールを開かずに、普段使っているSlackチャンネル上で行い、チームメンバーにも状況を共有したいと考えている。最も適した方法はどれですか？',
    choices:['Amazon SNSでSlackへの通知を自前のLambda関数で実装する','AWS ChatbotでCloudWatchアラームの通知のみをSlackへ転送する','AWS Health DashboardのRSSフィードをSlackへ連携する','AWS Support AppをSlackワークスペースに連携し、Slackチャンネルからサポートケースの作成・更新・検索・解決やサポートエージェントとのライブチャットを行う'], correct:[3],
    why:['誤り。自前の実装は不要で、AWSが提供するマネージドな連携機能があります。','誤り。AWS ChatbotはCloudWatchアラーム等の運用通知をチャットツールへ転送する機能であり、サポートケース自体の作成・更新はできません。','誤り。AWS Health Dashboardはサービスの状態情報を提供するものであり、個別のサポートケース管理機能ではありません。','正しい。AWS Support AppをSlackワークスペースに連携することで、Slackチャンネルからサポートケースの作成・更新・検索・解決や、サポートエージェントとのライブチャットを行えます。Slack側での操作はAWS Support Centerコンソールにも反映されます。']},
  {id:'p632', domain:'tech', type:'single', source:SOURCES.ivs, text:'ある企業が、自社のモバイルアプリに、低遅延のライブ配信機能(視聴者参加型のオークションやライブコマースなど)を、独自の配信インフラを構築せずに組み込みたいと考えている。最も適したサービスはどれですか？',
    choices:['Amazon Interactive Video Service (IVS)','Amazon CloudFront','AWS Elemental MediaConvert','Amazon Kinesis Video Streams'], correct:[0],
    why:['正しい。Amazon IVSは、独自の配信インフラを構築せずに低遅延のライブ動画配信機能をアプリに組み込めるフルマネージド型サービスで、視聴者参加型の体験(チャット機能等)にも対応しています。','誤り。CloudFrontはコンテンツ配信(CDN)サービスであり、ライブ配信エンコーディング自体を行うサービスではありません。','誤り。MediaConvertはファイルベース(オンデマンド)の動画トランスコードサービスで、ライブ配信には対応していません。','誤り。Kinesis Video Streamsはデバイスからの映像を保存・分析するためのサービスで、視聴者向けの低遅延ライブ配信に特化したサービスではありません。']},
  {id:'p633', domain:'tech', type:'single', source:SOURCES.ivs, text:'Amazon Interactive Video Service (IVS)とAWS Elemental MediaLiveの使い分けとして正しい説明はどれですか？',
    choices:['両者はまったく同じ用途のサービスであり、どちらを使っても結果に違いはない','IVSは、シンプルなAPIと組み込みプレーヤーで低遅延のインタラクティブなライブ配信をすぐに組み込みたい場合に適しており、MediaLiveは、複数の出力形式・ビットレートへの変換や既存の放送ワークフローへの統合など、より柔軟で高度なライブエンコーディング要件に適している','MediaLiveは視聴者向けの低遅延配信にのみ使われ、放送用途では使われない','IVSはオンデマンド(録画済み)動画の配信専用サービスである'], correct:[1],
    why:['誤り。両者は想定する用途が異なります。','正しい。IVSはシンプルなAPIと組み込みプレーヤーで低遅延のインタラクティブなライブ配信を素早く組み込みたい場合に適しており、MediaLiveは複数の出力形式への変換や既存の放送ワークフローへの統合など、より柔軟で高度なライブエンコーディング要件に適しています。','誤り。MediaLiveは放送やストリーミング配信など幅広い用途で使われます。','誤り。IVSはライブ(リアルタイム)配信向けのサービスです。']},
  {id:'p634', domain:'tech', type:'single', source:SOURCES.globalAccelerator, text:'AWS Global Acceleratorの仕組みとして正しい説明はどれですか？',
    choices:['リクエストごとに異なるIPアドレスを動的に割り当て、DNSの再解決によってリージョンを切り替える','エッジロケーションにコンテンツをキャッシュすることで配信を高速化する、CloudFrontと同一の仕組みを使う','2つの静的なAnycast IPアドレスを固定のエントリポイントとして提供し、AWSのグローバルネットワークを経由して、ヘルスチェックに基づき自動的に正常なリージョンのエンドポイントへトラフィックをルーティングする','オンプレミスとAWS間の専用線接続を提供し、インターネットを経由しない閉域網でのアクセスを実現する'], correct:[2],
    why:['誤り。Global Acceleratorは固定の静的IPアドレスを提供し、動的に変化するものではありません。','誤り。CloudFrontはコンテンツのキャッシュによる配信高速化が中心ですが、Global Acceleratorはキャッシュを行わず、AWSのグローバルネットワーク経由でトラフィックを最適なエンドポイントへルーティングします。','正しい。Global Acceleratorは2つの静的なAnycast IPアドレスを固定のエントリポイントとして提供し、AWSのグローバルネットワークを経由して、ヘルスチェックに基づき自動的に正常なリージョンのエンドポイントへトラフィックをルーティングします。','誤り。これはAWS Direct Connectの説明です。']},
  {id:'p635', domain:'tech', type:'multi', source:SOURCES.appconfig, text:'AWS AppConfigにおける「設定データのソース」に関する説明として正しいものを2つ選択してください。',
    choices:['設定データはAppConfigが独自に保持するホスト型設定(Hosted Configuration)としてのみ保存でき、他のAWSサービスに保存されたデータを設定ソースとして使うことはできない','AppConfigでホストする設定データ(Hosted Configuration)に加え、Systems Manager Parameter StoreやAmazon S3に保存された既存の設定データも、設定ソースとして利用できる','AppConfigは設定データの形式を問わずすべて暗号化前提とし、暗号化されていないプレーンテキストの設定は一切利用できない','設定の内容はJSONスキーマやLambda関数によるバリデーターでデプロイ前に検証でき、検証に失敗した場合はデプロイをブロックできる'], correct:[1,3],
    why:['誤り。AppConfigはホスト型設定に加えて、Parameter StoreやS3など他のAWSサービスに保存された設定データもソースとして利用できます。','正しい。AppConfigでホストする設定データ(Hosted Configuration)に加え、Systems Manager Parameter StoreやAmazon S3に保存された既存の設定データも設定ソースとして利用できます。','誤り。暗号化は可能ですが必須ではなく、プレーンテキストの設定データも利用できます。','正しい。設定の内容はJSONスキーマやLambda関数によるバリデーターでデプロイ前に検証でき、検証に失敗した場合はデプロイをブロックできます。']},
  {id:'p636', domain:'concepts', type:'single', source:SOURCES.tco, text:'オンプレミスのデータセンターとAWSクラウドのTotal Cost of Ownership(TCO)を比較する際、オンプレミス側で見落とされがちなコスト要素として適切なものはどれですか？',
    choices:['データセンターの電力・冷却・物理的スペースの確保や、ハードウェアの保守・運用を行う人件費など、ハードウェア購入費以外の運用コスト','AWSの無料利用枠の対象サービスの利用料金','AWSサポートプランの月額料金','AWS Marketplaceで購入するサードパーティ製ソフトウェアのライセンス費用'], correct:[0],
    why:['正しい。オンプレミスのTCOを算出する際は、データセンターの電力・冷却・物理的スペースの確保や、ハードウェアの保守・運用に関わる人件費など、ハードウェア購入費以外の運用コストも見落とさず含める必要があります。','誤り。これはAWS側の料金要素であり、オンプレミス側のコストではありません。','誤り。これはAWS側のコストです。','誤り。これはAWS Marketplaceで購入するソフトウェアのコストであり、オンプレミスのハードウェア運用コストとは異なります。']},
  {id:'p637', domain:'concepts', type:'single', source:SOURCES.prescriptiveGuidance, text:'AWS Prescriptive Guidanceが提供するコンテンツのうち、「Guide（ガイド）」の位置づけとして最も適切なものはどれですか？',
    choices:['ビジネス上の課題をクラウド導入でどう解決するかを、IT・事業の経営層向けにまとめた最上位の方針文書(Strategy)','Strategyの内容を、関連するPatternと結び付けながら、実施可能な要素に分解して提示する文書で、アーキテクトやマネージャー、テクニカルリードを主な対象とする','コード・手順・トラブルシューティングなど、実装者(builder)向けの最も具体的な手順書(Pattern)','AWSの利用料金の見積りを作成するツール'], correct:[1],
    why:['これはStrategy(戦略)文書の説明です。','正しい。Guide(ガイド)は、Strategyの内容を関連するPatternと結び付けながら実施可能な要素に分解して提示する文書で、アーキテクトやマネージャー、テクニカルリードなどを主な対象としています。','これはPattern(パターン)文書の説明です。','これはAWS Pricing Calculatorの説明です。']},
  {id:'p638', domain:'concepts', type:'single', source:SOURCES.serviceQuotas, text:'AWS Service Quotasのコンソールで、あるクォータの「Adjustable(調整可能)」列が「No」と表示されていた。このクォータについて正しい説明はどれですか？',
    choices:['サポートケースを作成すれば必ず引き上げ可能になる','Business Support以上のプランであれば自動的に引き上げられる','AWSのサービスにより固定された上限(ハードリミット)であり、通常の引き上げリクエストでは変更できない','Service QuotasのAPIを呼び出せば即座に引き上げられる'], correct:[2],
    why:['誤り。「Adjustable」が「No」のクォータは、サポートケースを作成しても通常は引き上げられません。','誤り。サポートプランのレベルによって自動的に引き上げられるものではありません。','正しい。「Adjustable」が「No」のクォータは、AWSのサービスにより固定された上限(ハードリミット)であり、通常の引き上げリクエストの対象外です。','誤り。APIを呼び出しても、調整不可能なクォータを引き上げることはできません。']},
  {id:'p639', domain:'security', type:'single', source:SOURCES.wafAtp, text:'AWS WAFのATP(Account Takeover Prevention)における「リクエスト検査(Request inspection)」の仕組みとして正しいものはどれですか？',
    choices:['ログイン成功後のレスポンスを非同期に検査し、失敗率の高いIPをブロックする','VPCフローログを解析し、不審な通信パターンを検知する','CloudTrailの管理イベントを分析し、API呼び出しの異常を検知する','ログインリクエストで送信されたメールアドレスとパスワードの組み合わせを、AWSが保持・更新する漏洩済み認証情報のデータベースと照合する'], correct:[3],
    why:['誤り。これはATPの「レスポンス検査(Response inspection)」の説明です。','誤り。VPC Flow Logsとは異なる仕組みです。','誤り。AWS CloudTrailとは異なる仕組みです。','正しい。ATPのリクエスト検査は、ログインリクエストのメールアドレスとパスワードの組み合わせを、AWSが保持・更新する漏洩済み認証情報のデータベースと照合します。']},
  {id:'p640', domain:'security', type:'single', source:SOURCES.wafAtp, text:'CloudFrontディストリビューションに適用したAWS WAFのATP(Account Takeover Prevention)の「レスポンス検査(Response inspection)」に関する制約として正しいものはどれですか？',
    choices:['クライアントがHTTP/3(QUIC)で通信しているWebリクエストについては、レスポンス検査の対象外となる','レスポンス検査は同期的に行われるため、Webトラフィックのレイテンシーが増加する','Amazon Cognitoユーザープールと連携している場合のみレスポンス検査が利用できる','レスポンス検査はALB(Application Load Balancer)でのみ利用できる機能である'], correct:[0],
    why:['正しい。AWS WAFは、クライアントがHTTP/3(QUIC)で送信するWebリクエストについてはレスポンス検査を行いません。','誤り。レスポンス検査は非同期で行われるため、Webトラフィックのレイテンシーは増加しません。','誤り。ATP機能自体がAmazon Cognitoユーザープールには対応していません。','誤り。レスポンス検査はCloudFrontディストリビューションに適用した場合に利用できる機能です。']},
  {id:'p641', domain:'security', type:'multi', source:SOURCES.networkAccessAnalyzer, text:'AWS Network Access AnalyzerのNetwork Access Scope(ネットワークアクセススコープ)の定義に関する説明として正しいものを2つ選択してください。',
    choices:['MatchPathsには、セキュリティ・コンプライアンス要件に違反するとみなすネットワークパスの条件(送信元・宛先等)を指定する','スコープの定義には、実際にテストパケットを送信してパスを検証する設定が必須である','ExcludePathsには、MatchPathsの条件に一致するが正当な例外として検出結果から除外したいネットワークパスの条件を指定する','1つのスコープには1つの送信元リソースしか指定できない'], correct:[0,2],
    why:['正しい。MatchPathsには、セキュリティ・コンプライアンス要件に違反するとみなすネットワークパスの条件(送信元・宛先等)を指定します。','誤り。Network Access Analyzerは実際にパケットを送信せず、静的解析(自動推論)によってパスを検証します。','正しい。ExcludePathsには、MatchPathsの条件に一致するものの正当な例外として検出結果から除外したいネットワークパスの条件を指定します。','誤り。リソースID・リソースタイプ・タグ・IPアドレス範囲など複数の条件を組み合わせて指定できます。']},
  {id:'p642', domain:'billing', type:'single', source:SOURCES.supportApp, text:'AWS Support Appを使ってSlackチャンネルからサポートケースを操作できるようにする場合、チャンネルのメンバーが実際に実行できる操作の範囲は何によって決まりますか？',
    choices:['Slackのチャンネル管理者権限の有無','AWS Support Appに関連付けたIAMロールにアタッチされたIAMポリシーの許可内容','Slackワークスペースの有料プランかどうか','AWSサポートプランの契約金額'], correct:[1],
    why:['誤り。Slack側の管理者権限ではなく、AWS側のIAMロールの権限によって決まります。','正しい。AWS Support Appは関連付けたIAMロールを使ってAWS SupportやService QuotasのAPIを呼び出すため、Slackチャンネルのメンバーが実行できる操作の範囲は、そのIAMロールにアタッチされたIAMポリシーの許可内容によって決まります。フルアクセスを許可するポリシーをアタッチすると、チャンネル内の誰でもケースを作成・更新・解決できてしまう点に注意が必要です。','誤り。Slackの有料プランとは無関係です。','誤り。サポートプランの契約金額そのものではなく、IAMロールの権限によって決まります。']},
  {id:'p643', domain:'tech', type:'single', source:SOURCES.groundStation, text:'ある企業が、自社の人工衛星から取得したデータを受信するために、地上アンテナ設備を自前で構築・運用せず、必要な時だけ衛星との通信(ダウンリンク)を予約して利用したいと考えている。最も適したサービスはどれですか？',
    choices:['AWS IoT Core','Amazon Location Service','AWS Ground Station','AWS Direct Connect'], correct:[2],
    why:['誤り。AWS IoT Coreは地上のIoTデバイスとクラウド間の通信を管理するサービスで、人工衛星との通信設備を提供するものではありません。','誤り。Amazon Location Serviceは地図・位置情報サービスで、衛星通信設備とは無関係です。','正しい。AWS Ground Stationは、人工衛星との通信(ダウンリンク/アップリンク)に必要なアンテナ設備を自前で構築・運用せず、必要な時に予約して利用できるフルマネージド型の衛星通信サービスです。','誤り。AWS Direct ConnectはオンプレミスとAWSを専用線で接続するサービスで、衛星通信とは異なります。']},
  {id:'p644', domain:'tech', type:'single', source:SOURCES.mediaPackage, text:'ライブイベントの映像をAWS Elemental MediaLiveでリアルタイムにエンコードした後、視聴者が使う様々なデバイスやCDNに合わせて配信用にパッケージングし、配信元(オリジン)として機能させたい場合、最も適したサービスはどれですか？',
    choices:['AWS Elemental MediaConvert','Amazon CloudFront','AWS Elemental MediaStore','AWS Elemental MediaPackage'], correct:[3],
    why:['誤り。MediaConvertはファイルベース(オンデマンド)の動画トランスコードサービスで、ライブ配信のパッケージングには使用しません。','誤り。CloudFrontはCDN(コンテンツ配信網)であり、動画のパッケージング・オリジネーションを行うサービスではありません。','誤り。MediaStoreはメディア向けのストレージサービスであり、パッケージング機能ではありません。','正しい。AWS Elemental MediaPackageは、MediaLiveなどでエンコードした映像を、様々な再生デバイスやCDN向けに配信用にパッケージングし、オリジン(配信元)として機能するサービスです。']},
  {id:'p645', domain:'tech', type:'multi', source:SOURCES.mediaPackage, text:'AWS Elemental MediaPackageの特徴として正しいものを2つ選択してください。',
    choices:['出力形式はMP4ファイルのダウンロードのみに対応している','HLSやDASHなど複数のアダプティブビットレート配信形式で、同じ入力から複数の出力をパッケージングできる','動画のアップロードから編集まで一括して行うノンリニア編集ツールである','DRM(デジタル著作権管理)と連携し、コンテンツを保護した配信を行える'], correct:[1,3],
    why:['誤り。MediaPackageはHLSやDASHなどストリーミング配信形式の出力に対応しており、単純なMP4ファイルのダウンロード提供が主目的ではありません。','正しい。MediaPackageは、同じ入力からHLSやDASHなど複数のアダプティブビットレート配信形式へパッケージングして出力できます。','誤り。MediaPackageは動画編集ツールではありません。','正しい。MediaPackageはSPEKE APIを通じてDRMプロバイダーと連携し、コンテンツを保護した配信を行うことができます。']},
  {id:'p646', domain:'tech', type:'single', source:SOURCES.s3glacier, text:'Amazon S3のストレージクラスのうち、最低保存期間(Minimum storage duration)が180日と最も長く設定されているものはどれですか？',
    choices:['S3 Glacier Deep Archive','S3 Glacier Flexible Retrieval','S3 Standard-IA','S3 One Zone-IA'], correct:[0],
    why:['正しい。S3 Glacier Deep Archiveの最低保存期間は180日で、他のストレージクラスより長く設定されています。','誤り。S3 Glacier Flexible Retrievalの最低保存期間は90日です。','誤り。S3 Standard-IAの最低保存期間は30日です。','誤り。S3 One Zone-IAの最低保存期間は30日です。']},
  {id:'p647', domain:'tech', type:'single', source:SOURCES.datasync, text:'AWS DataSyncがデータ転送の整合性を確認する仕組みとして正しいものはどれですか？',
    choices:['転送元と転送先のファイルサイズだけを比較し、一致すれば整合性ありと判断する','転送元と転送先のファイル・オブジェクトのチェックサムとメタデータを計算・比較し、差異があれば検証エラーとする','整合性の検証は行わず、転送が完了したことのみを記録する','転送先にのみチェックサムを保存し、転送元とは比較しない'], correct:[1],
    why:['誤り。ファイルサイズの比較だけでなく、チェックサムとメタデータを計算して比較します。','正しい。AWS DataSyncは転送時に常に整合性チェックを行い、転送元と転送先のファイル・オブジェクトのチェックサムとメタデータを計算・比較します。差異があれば検証エラーとなります。','誤り。DataSyncは常にデータ転送時の整合性チェックを行います。','誤り。転送元・転送先の両方のチェックサムとメタデータを比較します。']},
  {id:'p648', domain:'tech', type:'single', source:SOURCES.managedFlink, text:'Amazon Managed Service for Apache Flinkの「Studioノートブック」の特徴として正しいものはどれですか？',
    choices:['ノートブックはJavaのみに対応しており、SQLやPythonは利用できない','インタラクティブな開発は一切できず、本番運用のアプリケーションのみを対象とする','Apache Zeppelinをベースに、SQL・Python・Scalaでストリームデータをインタラクティブにクエリ・可視化でき、開発したノートブックを継続稼働する本番アプリケーションへ昇格(プロモート)できる','ノートブックの実行には別途Amazon SageMakerの起動が必要である'], correct:[2],
    why:['誤り。StudioノートブックはApache Zeppelinをベースに、SQL・Python・Scalaに対応しています。','誤り。Studioノートブックはまずインタラクティブな分析のために使い、その後本番運用のアプリケーションへ昇格させることができます。','正しい。Managed Service for Apache FlinkのStudioノートブックは、Apache Zeppelinをベースに、SQL・Python・Scalaでストリームデータをインタラクティブにクエリ・可視化でき、開発したノートブックを継続的に稼働する本番アプリケーションへ昇格(プロモート)できます。','誤り。Amazon SageMakerの起動は不要です。']},
  {id:'p649', domain:'tech', type:'single', source:SOURCES.databrew, text:'AWS Glue DataBrewで、ある列の欠損値を補完したり特定のフォーマットへ変換したりする一連のデータ変換ステップをまとめて保存し、後から更新したり別のデータセットに対して再利用したりしたい場合、使用する仕組みは何と呼ばれますか？',
    choices:['レシピ(Recipe) — 適用した変換ステップの集合として保存し、更新や他のデータセットへの再利用ができる','AWS Step Functionsのステートマシン','AWS CloudFormationのテンプレート','Amazon S3のライフサイクルルール'], correct:[0],
    why:['正しい。AWS Glue DataBrewでは、適用した変換ステップを「レシピ(Recipe)」としてまとめて保存でき、後から更新したり他のデータセットに対して再利用・継続的に適用したりできます。','誤り。Step Functionsはワークフロー(処理の流れ)をオーケストレーションする仕組みであり、DataBrewのデータ変換ステップの保存形式ではありません。','誤り。CloudFormationはインフラをコード化するサービスであり、データ変換ステップの保存形式ではありません。','誤り。S3のライフサイクルルールはオブジェクトのストレージクラス移行や有効期限切れの管理機能であり、データ変換とは無関係です。']},
  {id:'p650', domain:'tech', type:'single', source:SOURCES.comprehendMedical, text:'Amazon Comprehend Medicalとは何ですか？',
    choices:['EC2インスタンスやコンテナイメージの脆弱性を継続的にスキャンするサービス','医師の診療メモや退院時サマリーなどの非構造化された臨床テキストから、医療状態・投薬情報・保護対象保健情報(PHI)などのエンティティを検出し、ICD-10-CMやRxNormといった標準的な医療用語体系にリンクできる自然言語処理(NLP)サービス','患者との診察の様子を録音し、音声をリアルタイムで文字起こしするサービス','電子カルテ(EHR)システムそのものを提供するSaaS製品'], correct:[1],
    why:['誤り。これはAmazon Inspectorの説明です。','正しい。Amazon Comprehend Medicalは、臨床テキストから医療状態・投薬情報・PHIなどのエンティティを検出し、ICD-10-CMやRxNormなどの標準的な医療用語体系にリンクできる自然言語処理(NLP)サービスです。','誤り。これはAmazon Transcribe Medicalのような音声文字起こしサービスの説明です。Comprehend Medicalはテキストを分析するサービスです。','誤り。Comprehend Medicalは既存のテキストデータを分析するAPIサービスであり、EHRシステムそのものではありません。']},
  {id:'p651', domain:'tech', type:'single', source:SOURCES.cloudwatchRum, text:'Amazon CloudWatch RUM (Real User Monitoring)とは何ですか？',
    choices:['サーバーサイドのAPIレイテンシーを分散トレーシングで可視化するサービス','定期的に模擬アクセス(カナリア)を実行し、エンドポイントの可用性を継続的に監視するサービス','実際のユーザーのセッションから、Webアプリケーションのページ読み込み時間やクライアント側のエラー、モバイルアプリの画面読み込み時間やクラッシュといったクライアント側のパフォーマンスデータを、実際のユーザーセッションからほぼリアルタイムに収集・可視化するサービス','VPC内を流れるネットワークトラフィックをキャプチャして分析するサービス'], correct:[2],
    why:['誤り。これはAWS X-Rayの説明です。','誤り。これはAmazon CloudWatch Synthetics(カナリア)の説明です。','正しい。CloudWatch RUMは、実際のユーザーセッションから、Webアプリのページ読み込み時間やエラー、モバイルアプリの画面読み込み時間やクラッシュなどのクライアント側パフォーマンスデータをほぼリアルタイムに収集・可視化するサービスです。','誤り。これはVPC Flow Logsやトラフィックミラーリングの説明です。']},
  {id:'p652', domain:'tech', type:'single', source:SOURCES.appstream, text:'Amazon WorkSpaces Applications(旧Amazon AppStream 2.0)のフリートタイプのうち、「On-Demand」の特徴として正しいものはどれですか？',
    choices:['インスタンスは常に起動した状態を維持し、利用の有無にかかわらず常に起動インスタンスの料金が課金される','フリートの作成後も、On-DemandとAlways-Onの間でフリートタイプをいつでも変更できる','複数ユーザーが1つのインスタンスを同時に共有するマルチセッション専用の設定であり、単一セッションでは利用できない','ユーザーが利用していない間インスタンスは停止状態になり、ユーザーがストリーミングを開始するとインスタンスが起動するため起動を待つ時間(目安1〜2分程度)が生じる一方、アイドル時は低い停止インスタンス料金となる'], correct:[3],
    why:['誤り。これは「Always-On」フリートタイプの特徴です。','誤り。フリートタイプはフリート作成時に指定し、作成後に変更することはできません。','誤り。マルチセッションはAlways-On/On-Demandのいずれのフリートタイプでも利用できるオプションです。','正しい。On-Demandフリートでは、利用していない間インスタンスは停止状態となり、ストリーミング開始時に起動するため多少の待ち時間が生じますが、アイドル時は低い停止インスタンス料金となります。']},
  {id:'p653', domain:'tech', type:'multi', source:SOURCES.fis, text:'AWS Fault Injection Service (AWS FIS)の実験テンプレート(Experiment Template)を構成する要素として正しいものを2つ選択してください。',
    choices:['ターゲット(Target) — アクションを実行する対象のAWSリソースを指定する','IAMユーザーのMFAデバイス設定','実験ロール(Experiment Role) — AWS FISが実験を実行するために必要な権限を付与するIAMロール','S3バケットのライフサイクルルール'], correct:[0,2],
    why:['正しい。ターゲットは、アクションを実行する対象のAWSリソースを指定する実験テンプレートの構成要素です。','誤り。MFAデバイス設定はFISの実験テンプレートの構成要素ではありません。','正しい。実験ロールは、AWS FISが実験を実行するために必要な権限を付与するIAMロールで、実験テンプレートの構成要素の一つです。','誤り。S3のライフサイクルルールはFISの実験テンプレートの構成要素ではありません。']},
  {id:'p654', domain:'security', type:'single', source:SOURCES.s3ObjectLock, text:'Amazon S3 Object Lockの「コンプライアンスモード(Compliance mode)」の特徴として正しいものはどれですか？',
    choices:['保持期間中は、AWSアカウントのルートユーザーを含め、いかなるユーザーもオブジェクトバージョンを上書き・削除できない','特別な権限(s3:BypassGovernanceRetention)を持つ一部のユーザーであれば、保持期間中でも削除や設定変更ができる','バケットでS3バージョニングを有効にしていなくても使用できる','保持期間を後から自由に短縮できる'], correct:[0],
    why:['正しい。コンプライアンスモードでは、保持期間中はルートユーザーを含めいかなるユーザーもオブジェクトバージョンを上書き・削除できません(保持期間中に削除する唯一の方法はAWSアカウント自体を削除することです)。','誤り。これは「ガバナンスモード(Governance mode)」の特徴です。','誤り。S3 Object LockはバケットでS3バージョニングが有効になっている場合にのみ機能します。','誤り。コンプライアンスモードでは、保持モードの変更や保持期間の短縮はできません。']},
  {id:'p655', domain:'security', type:'single', source:SOURCES.imdsv2, text:'Amazon EC2のインスタンスメタデータサービスにおける、IMDSv1とIMDSv2の仕組みの違いとして正しいものはどれですか？',
    choices:['IMDSv1はセッション指向のトークンベースのリクエストを使用し、IMDSv2は単純なリクエスト/レスポンス方式である','IMDSv1は単純なリクエスト/レスポンス方式でメタデータを直接取得できるのに対し、IMDSv2はまずPUTリクエストでセッショントークンを取得し、以降のGET/HEADリクエストにそのトークンをヘッダーとして含める、セッション指向の方式である','IMDSv1・IMDSv2のいずれも、セッショントークンを取得しなければメタデータへアクセスできない','IMDSv2は常にIMDSv1よりも低いレイテンシーで応答することが保証されている'], correct:[1],
    why:['誤り。説明が逆です。IMDSv1が単純なリクエスト/レスポンス方式、IMDSv2がセッション指向のトークンベース方式です。','正しい。IMDSv2では、まずPUTリクエストでセッショントークンを取得し、以降のGET/HEADリクエストにそのトークンをヘッダーとして含める必要があります。この仕組みは、単純なGETリクエストだけで悪用されるSSRFなどの脆弱性への防御層(多層防御)になります。','誤り。IMDSv1はトークンを使わずメタデータへアクセスできる方式です。','誤り。レイテンシーの優劣が保証されているわけではありません。']},
  {id:'p656', domain:'security', type:'single', source:SOURCES.imdsv2, text:'EC2インスタンスでセキュリティを強化するため、IMDSv1形式のリクエストを拒否し、IMDSv2のみを許可したい場合、インスタンスメタデータオプションでどのように設定しますか？',
    choices:['セキュリティグループでポート80/443への外部からのインバウンドアクセスを拒否する','VPCエンドポイントポリシーでIMDSv1のバージョン番号を指定して拒否する','インスタンスメタデータオプションの「HttpTokens」を「required」に設定する。これにより、有効なセッショントークンを含まないリクエスト(IMDSv1形式のリクエスト)は401 Unauthorizedエラーとなる','IAMロールのアクセス許可ポリシーでIMDSv1形式の呼び出しを拒否するステートメントを追加する'], correct:[2],
    why:['誤り。インスタンスメタデータサービスへのリクエストはインスタンス内部から行われるため、セキュリティグループのインバウンドルールでは制御できません。','誤り。インスタンスメタデータサービスはVPCエンドポイント経由のサービスではありません。','正しい。インスタンスメタデータオプションの「HttpTokens」を「required」に設定すると、有効なセッショントークンを含まないリクエスト(IMDSv1形式)は401 Unauthorizedエラーとなり、IMDSv2のみが許可されます。','誤り。IAMポリシーでIMDSのバージョンを制御することはできません。']},
  {id:'p657', domain:'billing', type:'multi', source:SOURCES.purchaseOrderMgmt, text:'AWS Purchase Order Managementにおいて、請求書(インボイス)と購入注文(PO)のライン品目を照合する仕組みに関する説明として正しいものを2つ選択してください。',
    choices:['1つのAWSアカウントにつき、登録できる購入注文は常に1件までに制限されている','請求書の請求元エンティティ(Bill fromエンティティ)が、購入注文に設定された「Bill from」エンティティと一致しないライン品目は、照合の対象から除外される','照合の際は、登録された購入注文のうち必ず最も古いものが優先的に使用される','複数のライン品目タイプ(ALL/AWS Monthly Usage/AWS Subscription Purchase等)が条件に一致する場合、より限定的(具体的)なタイプのライン品目が優先して使用される'], correct:[1,3],
    why:['誤り。1アカウントにつき最大100件のアクティブな購入注文を登録できます。','正しい。請求書の請求元エンティティと購入注文の「Bill from」エンティティが一致しないライン品目は、照合の対象から除外されます。','誤り。すべての条件が同等に一致する場合は、最も古いものではなく、最近更新された購入注文が優先されます。','正しい。複数のライン品目タイプが条件に一致する場合は、ALLのような汎用的なタイプよりも、より限定的(具体的)なタイプのライン品目が優先して使用されます。']},
  {id:'p658', domain:'billing', type:'single', source:SOURCES.dataExports, text:'AWS Data Exportsで選択できるエクスポートの種類に関する説明として正しいものはどれですか？',
    choices:['エクスポートできるのはレガシーのCost and Usage Report (CUR)のみであり、CUR 2.0やFOCUS形式は選択できない','エクスポートできるデータの種類は1種類のみに固定されている','Amazon QuickSightと統合した事前構築済みのコスト・使用状況ダッシュボードを作成する機能は提供されていない','CUR 2.0、Cost Optimization Hubの推奨事項、FOCUS形式、炭素排出量データを含む複数の標準データエクスポート種類に加え、QuickSight統合のコスト・使用状況ダッシュボードや、レガシーCURのエクスポートも選択できる'], correct:[3],
    why:['誤り。CUR 2.0やFOCUS形式(1.0/1.2)も選択できます。','誤り。標準データエクスポートだけでも複数のテーブル(CUR 2.0、Cost Optimization Hub推奨事項、FOCUS 1.0/1.2、炭素排出量)から選択できます。','誤り。QuickSightと統合した事前構築済みのコスト・使用状況ダッシュボードを作成する機能が提供されています。','正しい。AWS Data Exportsは、CUR 2.0・Cost Optimization Hub推奨事項・FOCUS形式・炭素排出量データを含む複数の標準データエクスポート種類に加え、QuickSight統合ダッシュボードやレガシーCURのエクスポートも選択できます。']},
  {id:'p659', domain:'concepts', type:'single', source:SOURCES.sustainabilityConsole, text:'AWS Sustainability コンソールと、従来のAWS Billingコンソール内にあった「Customer Carbon Footprint Tool (CCFT)」の関係として正しいものはどれですか？',
    choices:['Sustainability コンソールはCCFTを置き換えて機能を拡張した後継のスタンドアロンサービスであり、CCFTは2026年6月30日付で廃止(deprecate)される予定である','CCFTはSustainability コンソールの廃止後に新設される予定の後継サービスである','両者はまったく無関係の別目的のサービスであり、置き換え関係にはない','CCFTは現在も提供が継続されており、今後廃止される予定はない'], correct:[0],
    why:['正しい。AWS Sustainability コンソールは、AWS Billingコンソール内のCustomer Carbon Footprint Tool (CCFT)を置き換えて機能を拡張した、無料のスタンドアロンサービスで、CCFTは2026年6月30日付で廃止される予定です。','誤り。順序が逆です。Sustainability コンソールがCCFTを置き換える後継サービスです。','誤り。Sustainability コンソールはCCFTの機能を拡張した後継サービスであり、無関係ではありません。','誤り。CCFTは2026年6月30日付で廃止される予定です。']},
  {id:'p660', domain:'concepts', type:'single', source:SOURCES.waLens, text:'AWS Well-Architected Toolにおける「カスタムレンズ(Custom Lens)」の説明として正しいものはどれですか？',
    choices:['AWSが作成・保守する公式のレンズカタログに含まれるレンズの総称である','利用者が独自のピラー・質問・ベストプラクティス・改善プランを定義して作成する、AWS公式コンテンツではないユーザー定義のレンズであり、他のAWSアカウントと共有することもできる','1つのワークロードに適用できるレンズの数に上限はなく、何個でも同時に適用できる','一度ワークロードからレンズを削除すると、そのレンズに関連する評価データは完全に削除され、再度追加しても復元できない'], correct:[1],
    why:['誤り。これはAWSが提供する「レンズカタログ」のレンズの説明です。','正しい。カスタムレンズは、利用者が独自のピラー・質問・ベストプラクティス・改善プランを定義して作成するユーザー定義のレンズで、他のAWSアカウントと共有することもできます。','誤り。1つのワークロードに一度に追加できるレンズは最大5つ、適用できる合計は最大20レンズまでという上限があります。','誤り。レンズをワークロードから削除してもそのレンズに関連するデータは保持され、再度そのレンズを追加すると復元されます。']},
  {id:'p661', domain:'concepts', type:'single', source:SOURCES.sustainabilityConsole, text:'AWS Sustainability コンソールが、従来のCustomer Carbon Footprint Tool (CCFT)と比べて優れている点として正しいものはどれですか？',
    choices:['炭素排出量データを分単位のリアルタイムで提供する','請求(Billing)権限を持つユーザーしか利用できないよう、アクセス制限がより厳格になった','請求(Billing)の権限を持たないユーザーでもデータを閲覧できるため、サステナビリティ担当チームが請求データへのアクセス権を持たなくても炭素排出量データを確認できる','炭素排出量データの算出方法が市場ベース(MBM)のみに一本化された'], correct:[2],
    why:['誤り。炭素排出量データは月次単位で提供されるものであり、分単位のリアルタイム提供ではありません。','誤り。説明が逆です。CCFTは請求権限が必要でしたが、Sustainability コンソールは請求権限を必要としません。','正しい。Sustainability コンソールは請求権限を必要としないため、サステナビリティ担当チームが請求データへのアクセス権を持たなくても炭素排出量データを確認できます。','誤り。市場ベース(MBM)・ロケーションベース(LBM)の両方の算出方法が引き続き提供されます。']},
  {id:'p662', domain:'concepts', type:'single', source:SOURCES.migrationStrategies, text:'移行戦略の「Replatform（リプラットフォーム）」と「Repurchase（リパーチェス）」の違いとして正しいものはどれですか？',
    choices:['Replatformはアプリケーションのコアアーキテクチャを維持したままクラウドに最適化する一部変更を加える戦略であるのに対し、Repurchaseは既存のアプリケーションを(多くはSaaS型の)別製品に置き換える戦略である','Replatformは別製品に置き換える戦略であり、Repurchaseはコアアーキテクチャを維持する戦略である(説明が逆)','両者はまったく同じ意味であり、呼び方が異なるだけである','Replatformはオンプレミスに残す戦略であり、Repurchaseは廃止する戦略である'], correct:[0],
    why:['正しい。Replatformはコアアーキテクチャを維持しつつクラウド最適化のための一部変更を加える戦略、Repurchaseは既存アプリケーションを多くはSaaS型の別製品に置き換える戦略です。','誤り。説明が逆です。','誤り。両者は異なる移行戦略です。','誤り。これらはRetain（リテイン）・Retire（リタイア）の説明です。']},
  {id:'p663', domain:'concepts', type:'single', source:SOURCES.migrationStrategies, text:'移行戦略の「Relocate（リロケート）」が、「Rehost（リホスト）」と比べて特徴的な点として正しいものはどれですか？',
    choices:['Relocateは、VMware Cloud on AWS等を利用してハイパーバイザーレベルでインフラをそのまま移設するため、OSやアプリケーション、運用手順にほぼ変更を加えずに移行できるのに対し、Rehostは通常、仮想マシンをAmazon EC2インスタンスとして個別に再作成(再プロビジョニング)する','Relocateはアプリケーションのコードを全面的に書き換える戦略であり、Rehostは何も変更しない戦略である','RelocateはSaaS製品への置き換えを意味し、Rehostはオンプレミスに残すことを意味する','両者に実質的な違いはなく、どちらを選んでも移行作業の内容は同じになる'], correct:[0],
    why:['正しい。Relocateはハイパーバイザーレベルでインフラをそのまま移設しOS・アプリケーション・運用手順にほぼ変更を加えないのに対し、Rehostは通常EC2インスタンスとして個別に再作成します。','誤り。これはRefactorの説明に近く、Relocate/Rehostいずれの説明でもありません。','誤り。これはRepurchase・Retainの説明です。','誤り。両者は異なる移行アプローチです。']},
  {id:'p664', domain:'concepts', type:'single', source:SOURCES.prescriptiveGuidance, text:'AWS Prescriptive Guidanceが提供するコンテンツのうち、「Strategy（戦略）」の位置づけとして最も適切なものはどれですか？',
    choices:['特定のシナリオに対する、アーキテクチャ図・実装手順・コードサンプルを含む具体的な手順書であり、実装担当者を主な対象とする','IT部門・事業部門の経営層を主な対象とし、個別の実装手順ではなく、クラウド導入を通じて1つ以上のビジネス課題を解決する広範な方向性を示すものであり、関連するPattern(パターン)やGuide(ガイド)を束ねて特定のビジネス成果に結びつける','特定の技術領域を深掘りした、段階的な移行手順をまとめたコンテンツである','AWSのサポートケースのテンプレート集である'], correct:[1],
    why:['誤り。これはPattern（パターン）の説明です。','正しい。Strategy（戦略）は、IT・事業部門の経営層を主な対象とし、クラウド導入を通じたビジネス課題の解決に向けた広範な方向性を示すもので、関連するPatternやGuideを束ねて特定のビジネス成果に結びつけます。','誤り。これはGuide（ガイド）に近い説明です。','誤り。サポートケースのテンプレート集ではありません。']},
  {id:'p665', domain:'concepts', type:'single', source:SOURCES.waLens, text:'AWS Well-Architected Toolの「レンズカタログ(Lens Catalog)」に関する説明として正しいものはどれですか？',
    choices:['レンズカタログに含まれるのは、利用者が独自に作成したカスタムレンズのみである','レンズカタログの利用には、Well-Architected Toolとは別の追加のライセンス購入が必要である','レンズカタログに一度追加したレンズは、ワークロードから個別に削除することができない','レンズカタログには、すべてのワークロードにデフォルトで適用される基本の「AWS Well-Architected Framework」レンズに加え、Financial Services Industry LensやHealthcare Industry Lensなど、特定の業界・ユースケースに特化したAWS公式のレンズが複数含まれている'], correct:[3],
    why:['誤り。レンズカタログにはAWS公式のレンズも含まれます。カスタムレンズのみではありません。','誤り。レンズカタログはWell-Architected Toolの機能の一部として追加費用なく利用できます。','誤り。ワークロードに追加したレンズは個別に削除できます。','正しい。レンズカタログには基本のAWS Well-Architected Frameworkレンズに加え、Financial Services Industry LensやHealthcare Industry Lensなど業界・ユースケース特化のAWS公式レンズが複数含まれています。']},
  {id:'p666', domain:'billing', type:'single', source:SOURCES.capacityBlocks, text:'ある機械学習チームが、3週間後から始まる3日間だけ、複数のGPUインスタンスを使った短期集中の分散トレーニングジョブを計画している。オンデマンドでは必要なタイミングでの十分なGPU容量確保が保証されない。この要件に最も適したEC2の購入オプションはどれですか？',
    choices:['Amazon EC2 Capacity Blocks for ML','標準のオンデマンドインスタンス','1年または3年のリザーブドインスタンス','スポットインスタンス'], correct:[0],
    why:['正しい。Capacity Blocks for MLは、将来の特定の日付から始まる一定期間のGPU容量を事前に予約できるため、このような短期集中のトレーニングジョブに適しています。','誤り。オンデマンドでは必要なタイミングでの容量確保が保証されません。','誤り。1年・3年という長期コミットメントが必要であり、3日間だけの短期利用には適していません。','誤り。スポットインスタンスは中断される可能性があり、容量確保が保証されません。']},
  {id:'p667', domain:'billing', type:'multi', source:SOURCES.capacityBlocks, text:'Amazon EC2 Capacity Blocks for MLに関する説明として正しいものを2つ選択してください。',
    choices:['価格は、予約の申し込み(オファー)時点での需給状況に応じて変動する','価格は常に、通常のオンデマンド料金と同一の固定額である','Capacity Blockで確保したインスタンスの起動は、オンデマンドインスタンスの上限(クォータ)にはカウントされない','1つのAWSアカウントが同時に保有できるCapacity Blockの予約は1件までに制限されている'], correct:[0,2],
    why:['正しい。Capacity Blockの価格は、予約を申し込む時点での需給状況に応じて変動します。','誤り。価格は固定ではなく需給状況に応じて変動します。','正しい。Capacity Blockで確保したインスタンスは、通常のオンデマンドインスタンスの上限(クォータ)とは別枠で扱われ、カウントされません。','誤り。複数のCapacity Block予約を保有することができます。']},
  {id:'p668', domain:'billing', type:'single', source:SOURCES.capacityBlocks, text:'Amazon EC2 Capacity Blocks for MLで確保したインスタンス群が、EC2 UltraClustersに配置されることによる利点として最も適切なものはどれですか？',
    choices:['複数のインスタンスを低レイテンシーなネットワークで密に接続できるため、大規模な分散機械学習トレーニングに適している','インスタンスの起動コストが自動的に無料になる','インスタンスがどのアベイラビリティーゾーンにも依存しなくなる','インスタンスのOSパッチ適用がすべてAWS側の責任になる'], correct:[0],
    why:['正しい。UltraClustersへの配置により、複数インスタンスが低レイテンシーなネットワークで密に接続され、大規模な分散機械学習トレーニングに適した構成になります。','誤り。起動コストが無料になるわけではありません。','誤り。インスタンスは特定のアベイラビリティーゾーン内に配置されます。','誤り。ゲストOSへのパッチ適用は引き続き利用者の責任です(責任共有モデル)。']},
  {id:'p669', domain:'billing', type:'single', source:SOURCES.riMarketplace, text:'ある企業が、通常AWSから新規購入する際に必要な1年・3年という長期コミットメントを避けつつ、リザーブドインスタンスによる割引を短期間だけ利用したいと考えている。Amazon EC2 Reserved Instance Marketplaceを買い手として利用するメリットとして最も適切なものはどれですか？',
    choices:['AWSから新規購入するよりも常に高い価格でしか購入できない','残存期間が1年・3年未満の、より短い期間のStandard Reserved Instanceを購入できる場合があり、AWSから新規購入するよりも低い価格で購入できることもある','購入後、残存期間にかかわらず自由に別のインスタンスタイプへ無償で交換できる','Marketplaceで購入したリザーブドインスタンスには、AWSから新規購入した場合と異なり利用期限が存在しない'], correct:[1],
    why:['誤り。出品者によっては、AWSからの新規購入より低い価格で出品されていることもあります。','正しい。Reserved Instance Marketplaceでは、残存期間が1年・3年未満の短い期間のStandard Reserved Instanceが出品されていることがあり、AWSからの新規購入より低い価格で購入できる場合もあります。','誤り。Standard Reserved Instanceは購入後にインスタンスタイプを無償で交換することはできません(交換可能なのはConvertible Reserved Instanceです)。','誤り。Marketplaceで購入したリザーブドインスタンスにも、出品されていた残存期間に応じた利用期限があります。']},
  {id:'p670', domain:'security', type:'single', source:SOURCES.s3ObjectLock, text:'Amazon S3 Object Lockの「ガバナンスモード(Governance mode)」と「コンプライアンスモード(Compliance mode)」の違いとして正しいものはどれですか？',
    choices:['ガバナンスモードでは、特別な権限(s3:BypassGovernanceRetention等)を持つユーザーであれば保護設定を上書き・削除できるのに対し、コンプライアンスモードでは保持期間が満了するまで、ルートユーザーを含めいかなるユーザーもオブジェクトを削除・上書きできない','両モードとも、権限にかかわらず誰もオブジェクトを削除・上書きできない','ガバナンスモードの方がコンプライアンスモードよりも厳格な保護を提供する','コンプライアンスモードは、設定後いつでも保護を解除できる'], correct:[0],
    why:['正しい。ガバナンスモードは特別な権限を持つユーザーであれば保護設定を上書き・削除できますが、コンプライアンスモードは保持期間満了までルートユーザーを含め誰も削除・上書きできません。','誤り。ガバナンスモードには特別な権限による上書きの仕組みがあります。','誤り。厳格さはコンプライアンスモードの方が上です。','誤り。コンプライアンスモードは保持期間満了まで解除できません。']},
  {id:'p671', domain:'security', type:'single', source:SOURCES.backup, text:'AWS Backupの「Vault Lock」を有効にする目的として最も適切なものはどれですか？',
    choices:['バックアップボールト内のすべてのバックアップに対し、削除や保持設定の変更を誰も(AWSを含め)行えないWORM(Write Once Read Many)のポリシーを適用し、ランサムウェア対策やコンプライアンス要件に対応するため','バックアップの取得速度を高速化するため','バックアップの保存先リージョンを自動的に切り替えるため','バックアップにかかる料金を割引するため'], correct:[0],
    why:['正しい。Vault Lockは、ボールト内のバックアップに対する削除・保持設定の変更を誰も行えないWORMポリシーを適用し、ランサムウェア対策やコンプライアンス要件への対応に利用します。','誤り。取得速度の高速化が目的ではありません。','誤り。保存先リージョンの自動切り替え機能ではありません。','誤り。料金の割引制度ではありません。']},
  {id:'p672', domain:'security', type:'single', source:SOURCES.imdsv2, text:'あるアプリケーションは、インスタンスメタデータサービス(IMDS)から取得する情報を一切利用しない設計になっている。セキュリティをさらに高めるための設定として最も適切なものはどれですか？',
    choices:['インスタンスメタデータオプションの「HttpTokens」を「required」に設定し、IMDSv2のみを許可する','インスタンスメタデータオプションの「HttpEndpoint」を「disabled」に設定し、インスタンスメタデータサービス自体を無効化する','セキュリティグループでインスタンスメタデータサービスへのアウトバウンド通信を拒否する','IAMロールをそのインスタンスから削除する'], correct:[1],
    why:['誤り。HttpTokensをrequiredにするのはIMDSv2を使う場合の設定であり、メタデータを一切使わないケースではより厳格な「無効化」が可能です。','正しい。メタデータを一切利用しないのであれば、「HttpEndpoint」を「disabled」に設定してインスタンスメタデータサービス自体を無効化するのが最も安全です。','誤り。インスタンスメタデータサービスへの通信はインスタンス内部で完結するため、セキュリティグループのアウトバウンドルールでは制御できません。','誤り。IAMロールを削除すると、インスタンスメタデータ以外で必要な権限も失われてしまいます。']},
  {id:'p673', domain:'tech', type:'single', source:SOURCES.appSignals, text:'ある企業は、マイクロサービスで構成されたアプリケーションについて、サービス間の依存関係を可視化し、SLO(サービスレベル目標)を設定して追跡したいと考えている。アプリケーションコードへの手動での計装作業やカスタムダッシュボードの作成を最小限に抑えたい場合、最も適したAWSサービスはどれですか？',
    choices:['Amazon CloudWatch Application Signals','Amazon CloudWatch Synthetics','Amazon CloudWatch RUM','AWS X-Ray単体'], correct:[0],
    why:['正しい。Application Signalsは、アプリケーションを自動計装してサービス間の依存関係を可視化し、SLOの作成・追跡を、手動の計装作業やカスタムダッシュボード作成なしで行えます。','誤り。Syntheticsは合成監視(定期的な疑似リクエスト)によって可用性を監視する機能で、サービス間依存関係の自動可視化は行いません。','誤り。RUMは実際のエンドユーザーのブラウザ側を計測する機能で、SLOの作成・追跡機能は持ちません。','誤り。X-Ray単体では分散トレーシングは行えますが、SLOの作成・追跡機能は提供されません。']},
  {id:'p674', domain:'tech', type:'multi', source:SOURCES.appSignals, text:'Amazon CloudWatch Application Signalsに関する説明として正しいものを2つ選択してください。',
    choices:['Application Signals cross-account機能を使うと、CloudWatch Observability Access Managerを利用して複数のAWSアカウントにまたがるアプリケーションを単一のリージョン内で監視・トラブルシューティングできる','Java、Python、Node.js、.NETなどで書かれたアプリケーションに対応している','AWS Lambdaで実行されるアプリケーションには対応していない','サポートされているリージョンは常に1つの商用リージョンのみである'], correct:[0,1],
    why:['正しい。Application Signals cross-account機能では、CloudWatch Observability Access Managerを利用して複数アカウントにまたがるアプリケーションを単一リージョン内で監視・トラブルシューティングできます。','正しい。Application SignalsはJava、Python、Node.js、.NETのアプリケーションをサポートしています。','誤り。AWS Lambdaで実行されるアプリケーションにも対応しています。','誤り。カナダ西部(カルガリー)を除くほぼすべての商用リージョンでサポートされています。']},
  {id:'p675', domain:'tech', type:'single', source:SOURCES.userNotifications, text:'ある企業のクラウド運用チームは、複数のAWSアカウント・複数のリージョンにまたがって発生する、AWS Healthからの障害通知や、CloudWatchアラームに基づく独自の通知を、サービスごとにフィルタして一つの画面で横断的に確認したいと考えている。最も適したサービスはどれですか？',
    choices:['AWS User Notifications','Amazon SNS','AWS Trusted Advisor','Amazon CloudWatch Internet Monitor'], correct:[0],
    why:['正しい。AWS User Notificationsは、AWS管理通知とユーザー設定通知をサービス別にフィルタしながら、複数アカウント・複数リージョンにまたがって一つの画面で横断的に確認できます。','Amazon SNSはメッセージ配信サービスであり、複数アカウント・リージョン横断の通知集約・フィルタ機能を持つものではありません。','これはAWS Trusted Advisorの説明とは異なります。Trusted Advisorはベストプラクティスのチェックを行うサービスです。','これはAmazon CloudWatch Internet Monitorの説明とは異なります。']},
  {id:'p676', domain:'tech', type:'single', source:SOURCES.cloudfront, text:'動画配信サイトが、有料会員のみが特定のプレミアムコンテンツにアクセスできるよう、Amazon CloudFront経由の配信に対してアクセス制限をかけたいと考えている。最も適した方法はどれですか？',
    choices:['オリジンのAmazon S3バケットポリシーで、全世界からの読み取りを許可する','CloudFrontの署名付きURL（Signed URL）または署名付きCookie（Signed Cookie）を発行し、有効期限やアクセス権限を持つ会員にのみ配信を許可する','CloudFrontのキャッシュ無効化（Invalidation）を定期的に実行する','オリジンサーバーのIPアドレスを会員にのみ公開する'], correct:[1],
    why:['誤り。全世界に読み取りを許可すると、有料会員以外もアクセスできてしまいます。','正しい。CloudFrontの署名付きURLや署名付きCookieを使うと、有効期限や許可されたIPレンジなどの条件を満たすユーザーにのみコンテンツへのアクセスを許可できます。','誤り。キャッシュの無効化はコンテンツ更新時にキャッシュを破棄する機能であり、アクセス制限の機能ではありません。','誤り。CloudFrontは複数のエッジロケーションを経由するため、オリジンのIPアドレスを直接公開する運用は適切ではありません。']},
  {id:'p677', domain:'tech', type:'single', source:SOURCES.sagemaker, text:'あるデータサイエンスチームが、ノートブックでのデータ探索からモデルの学習・デバッグ・デプロイまでの一連の機械学習ワークフローを、複数のツールを使い分けることなく単一のWebベースの統合開発環境（IDE）で完結させたいと考えている。最も適したサービスはどれですか？',
    choices:['Amazon SageMaker Ground Truth（学習データのラベリングに特化したツール）','AWS Cloud9（汎用的なクラウドベースの統合開発環境）','Amazon SageMaker Studio（機械学習に特化した、ノートブック作成からモデルの学習・デバッグ・デプロイまでを一元的に行えるWebベースの統合開発環境）','AWS CloudShell（ブラウザ上でAWS CLIを実行できるシェル環境）'], correct:[2],
    why:['誤り。Ground Truthは学習データのラベリングに特化したツールであり、IDE全体の機能は提供しません。','誤り。Cloud9は汎用的なクラウドIDEであり、機械学習に特化した機能（実験管理やモデルデプロイの一元化等）は持ちません。','正しい。SageMaker Studioは、ノートブックでのデータ探索からモデルの学習・デバッグ・デプロイまでの機械学習ワークフロー全体を、単一のWebベースの統合開発環境で行えます。','誤り。CloudShellはAWS CLI操作用のブラウザターミナルであり、機械学習向けのIDEではありません。']},
  {id:'p678', domain:'tech', type:'single', source:SOURCES.lightsail, text:'個人ブログやシンプルな会社紹介サイトを、VPCのサブネット設計やセキュリティグループの詳細設定を行うことなく、WordPressなどの定番構成があらかじめ用意された低コストな仮想サーバーで素早く立ち上げたい場合、最も適したサービスはどれですか？',
    choices:['Amazon EC2（自分でAMIやVPC、セキュリティグループを設計する）','AWS Fargate','Amazon EKS','Amazon Lightsail（WordPress等のブループリントがあらかじめ用意され、月額定額料金で簡単に立ち上げられる仮想プライベートサーバー）'], correct:[3],
    why:['誤り。EC2は柔軟ですが、VPCやセキュリティグループなどのネットワーク設計を自分で行う必要があり、今回の「シンプルに素早く」という要件には手間がかかります。','誤り。FargateはコンテナをサーバーレスでEC2から実行するための仕組みで、WordPress等の定番ブループリントを提供するものではありません。','誤り。EKSはKubernetesクラスタの管理サービスであり、シンプルなWebサイト向けのサービスではありません。','正しい。Lightsailは、WordPress等の定番アプリケーションのブループリントがあらかじめ用意され、複雑なネットワーク設定無しで月額定額料金ですぐに使える仮想プライベートサーバーサービスです。']},
  {id:'p679', domain:'security', type:'single', source:SOURCES.s3ObjectLock, text:'ある企業が、新しく作成するAmazon S3バケットに対してObject Lockを有効化しようとしています。Object Lockを有効にするための前提条件として正しいものはどれですか？',
    choices:['バケットでAmazon S3バージョニング（Versioning）が有効になっている必要があり、Object Lockはバージョニングが有効なバケットでのみ機能する','バケットをパブリックアクセス可能な設定にしておく必要がある','バケットにAWS KMSによるサーバーサイド暗号化（SSE-KMS）を設定しておく必要がある','バケットのライフサイクルルールで自動削除を設定しておく必要がある'], correct:[0],
    why:['正しい。S3 Object Lockは、S3バージョニングが有効なバケットでのみ機能します。','誤り。パブリックアクセスの可否とObject Lockの有効化は無関係です。','誤り。SSE-KMSによる暗号化の設定はObject Lockの前提条件ではありません。','誤り。Object Lockはオブジェクトの削除・上書きを防ぐ機能であり、自動削除のライフサイクルルールとは目的が相反します。']},
  {id:'p680', domain:'security', type:'multi', source:SOURCES.iamPolicySimulator, text:'IAM Policy Simulatorに関する説明として正しいものを2つ選択してください。',
    choices:['実際にAWSリソースへ影響を与える本物のAPIコールを発行せずに、ポリシーがアクションを許可するか拒否するかを評価できる','シミュレーション結果は、実際のライブ環境での評価結果と常に完全に一致することが保証されている','IDベースのポリシーだけでなく、ユーザーが指定したリソースベースのポリシーや、アカウントがAWS Organizationsのメンバーである場合はSCPの影響もシミュレートできる','シミュレーションで使用したポリシーの変更内容は、実際にそのユーザーやロールにアタッチされているポリシーにも反映される'], correct:[0,2],
    why:['正しい。Policy Simulatorは実際のAPIコールを発行せず、安全にポリシーの評価結果（許可/拒否）を確認できます。','誤り。AWS公式ドキュメントでも、シミュレーション結果はライブ環境と異なる場合があるため、テスト後にライブ環境でも確認することが推奨されています。','正しい。Policy SimulatorはIDベースのポリシーに加え、ユーザーが指定したリソースベースのポリシーや、組織のSCPの影響もシミュレートできます。','誤り。シミュレーター上でのポリシー編集はシミュレーションのみに影響し、実際にアカウントにアタッチされているポリシーは変更されません。']},
  {id:'p681', domain:'security', type:'single', source:SOURCES.paymentCryptography, text:'ある決済処理会社が、AWS Payment Cryptographyで管理している対称鍵を、提携先のパートナー企業のHSMへ安全にエクスポートしたいと考えている。クリアテキストの鍵コンポーネントを紙で共有することなく、業界標準の規格に準拠して鍵を電子的に交換したい場合、採用される方式はどれですか？',
    choices:['AWS KMSのマルチリージョンキーのレプリケーション機能を使って複製する','鍵暗号化鍵（KEK）を使い、TR-31（対称鍵交換）やTR-34（非対称鍵ペアを使った鍵配送方式）といった業界標準規格に準拠して鍵をインポート・エクスポートする','AWS CloudHSMのクラスタ間でのバックアップ・リストア機能を使って複製する','IAMロールを一時的に引き受けさせ、鍵のARNをそのまま相手に共有する'], correct:[1],
    why:['誤り。これはAWS KMSの機能であり、AWS Payment Cryptographyの鍵交換方式とは異なります。','正しい。AWS Payment Cryptographyは、鍵暗号化鍵（KEK）を使い、対称鍵交換のTR-31や、非対称鍵ペアを使った鍵配送方式のTR-34といった業界標準規格に準拠して、鍵を電子的にインポート・エクスポートできます。','誤り。これはAWS CloudHSMの機能であり、AWS Payment Cryptographyの鍵交換の仕組みではありません。','誤り。鍵のARNを共有しても鍵の実体を安全に交換したことにはならず、業界標準の鍵交換方式ではありません。']},
  {id:'p682', domain:'security', type:'multi', source:SOURCES.verifiedPermissions, text:'Amazon Verified Permissionsの「ポリシーストア（Policy Store）」に関する説明として正しいものを2つ選択してください。',
    choices:['複数のアプリケーションにまたがって共有される、単一のグローバルなポリシーストアが自動的に1つだけ作成される','1つのポリシーストアは、通常1つのアプリケーションに対応し、そのアプリケーションのCedarポリシー・スキーマ・（任意で）エンティティ情報を保持するコンテナとして機能する','ポリシーストアに保存されたポリシーは、IAMのアクセスキーの一種として扱われる','アプリケーションが認可の判断を求める際、Verified PermissionsはポリシーストアのポリシーとスキーマをもとにCedarポリシー言語で評価し、許可（Allow）または拒否（Deny）の判断を返す'], correct:[1,3],
    why:['誤り。ポリシーストアはアプリケーションごとに作成するものであり、単一のグローバルなストアが自動的に1つだけ作られるわけではありません。','正しい。ポリシーストアは通常1つのアプリケーションに対応し、そのアプリケーションのCedarポリシー・スキーマ・（任意で）エンティティ情報を保持するコンテナです。','誤り。ポリシーストアはIAMのアクセスキーとは無関係の、認可ロジックを格納する仕組みです。','正しい。アプリケーションからの認可リクエストに対して、Verified Permissionsはポリシーストアの内容をもとにCedarポリシー言語で評価し、許可または拒否を返します。']},
  {id:'p683', domain:'concepts', type:'single', source:SOURCES.transform, text:'ある企業が、VMware上で稼働している多数の仮想マシンを、ソースコードやアプリケーションの構成を変更することなく、Amazon EC2上で稼働する形式へできるだけ人手を介さずに変換したいと考えている。最も適したサービスはどれですか？',
    choices:['AWS Application Migration Service (AWS MGN)のみを使用する','AWS Direct Connectを使用してオンプレミスとAWSを専用線で接続する','AWS Transform（VMware環境向けのエージェント型AIが、仮想マシンの変換作業を支援する）','Amazon WorkSpacesを使用して仮想デスクトップに移行する'], correct:[2],
    why:['誤り。MGNはサーバーをブロックレベルでレプリケーションしリホストする仕組みであり、VMware仮想マシン特有の変換を専門に支援するものではありません。','誤り。Direct Connectはネットワーク接続サービスであり、仮想マシンの変換作業とは無関係です。','正しい。AWS Transformは、VMware環境向けの専門エージェントにより、仮想マシンをAmazon EC2上で稼働する形式へ変換する作業を人手を介さずに支援します。','誤り。WorkSpacesは仮想デスクトップサービスであり、サーバーワークロードの移行サービスではありません。']},
  {id:'p684', domain:'concepts', type:'single', source:SOURCES.skillBuilder, text:'ある企業の人材育成担当者が、組織内の多数の社員に対して、管理者が受講状況を一元的に把握しトレーニングを割り当てられる仕組みと、シングルサインオン（SSO）による利用を求めている。AWS Skill Builderのうち、最も適した提供形態はどれですか？',
    choices:['無料のデジタルコースのみを個別に受講させる','Individual（個人向け）サブスクリプションを社員ごとに契約する','AWS re:Postで質問を投稿させる','Team（チーム向け）サブスクリプション（管理者機能とシングルサインオンを備え、管理者が社員にトレーニングを割り当てて進捗を追跡できる）'], correct:[3],
    why:['誤り。無料のデジタルコースには、管理者による一元的な受講状況の把握や割り当て機能はありません。','誤り。Individualサブスクリプションは個人向けの契約であり、組織の管理者機能やSSOは提供されません。','誤り。re:PostはQ&Aコミュニティサービスであり、トレーニングの管理機能ではありません。','正しい。Team サブスクリプションは、管理者機能とシングルサインオンを備え、管理者が社員にトレーニングを割り当てて進捗を追跡できます。']},
  {id:'p685', domain:'billing', type:'single', source:SOURCES.invoices, text:'ある企業の経理担当者が、AWS Billing and Cost Managementコンソールの「Bills」ページで今月分の請求書を確認したところ、請求ステータスが「Pending」と表示されていた。この状態に関する説明として正しいものはどれですか？',
    choices:['当月の請求期間がまだ締まっておらず、現時点までの使用量に基づく見積もり額が表示されている状態で、期間が締まり「Issued」になると確定した請求書（PDF）が発行される','請求書がAWSにより却下され、支払いができない状態','支払いがAWSに未着である状態','アカウントが一時停止されている状態'], correct:[0],
    why:['正しい。「Pending」は請求期間がまだ締まっておらず見積もり額が表示されている状態で、期間終了後に「Issued」となり確定した請求書（PDF）が発行されます。','誤り。「Pending」は請求書の却下を意味するものではありません。','誤り。支払いの未着状態を示すものではなく、請求期間が未確定であることを示します。','誤り。アカウント停止状態を示すステータスではありません。']},
  {id:'p686', domain:'billing', type:'single', source:SOURCES.invoices, text:'複数のAWSアカウントをAWS Organizationsで一括請求（Consolidated Billing）管理している企業で、管理アカウント（management account）の経理担当者が、各メンバーアカウントの請求内容を一つの画面でまとめて確認したいと考えている。最も適した方法はどれですか？',
    choices:['各メンバーアカウントに個別にサインインし、それぞれのBillsページを確認する','管理アカウントでBilling and Cost Managementコンソールの「Bills」ページにサインインし、「Charges by account」タブで各メンバーアカウントの使用料をまとめて確認する','AWS Trusted Advisorでメンバーアカウントのコストチェック結果を確認する','Amazon CloudWatchのダッシュボードでメンバーアカウントの請求額を可視化する'], correct:[1],
    why:['誤り。各アカウントに個別にサインインしなくても、管理アカウントから一括して確認できます。','正しい。管理アカウントのBillsページでは、「Charges by account」タブを使って各メンバーアカウントの使用料をまとめて確認できます。','誤り。Trusted Advisorはベストプラクティスのチェックサービスであり、請求内容の一覧表示機能ではありません。','誤り。CloudWatchは運用監視サービスであり、請求情報の一覧表示を目的としたサービスではありません。']},
  {id:'p687', domain:'billing', type:'single', source:SOURCES.invoices, text:'ある企業が、発行済みのAWS請求書（インボイス）に記載されている自社の会社名・住所が誤っていることに気づいた。これをBilling and Cost Managementコンソール上から修正したい場合、最も適した方法はどれですか？',
    choices:['請求書は一度発行されると一切修正できないため、新しいAWSアカウントを作成し直す','AWS Artifactでコンプライアンスレポートを再発行する','Billsページの「Invoices」タブから該当の請求書を選択し、「Update company and address for account」から会社名・住所の更新と請求書の再処理（reprocess）を行う','IAMユーザーのタグ情報を更新する'], correct:[2],
    why:['誤り。Billsページから会社名・住所などの情報を修正し、請求書を再処理することができます。','誤り。AWS Artifactはコンプライアンスレポートの提供サービスであり、請求書の修正機能ではありません。','正しい。Billsページの「Invoices」タブから該当請求書を選び、「Update company and address for account」で会社名・住所を更新し、請求書を再処理（reprocess）できます。','誤り。IAMユーザーのタグ情報の更新は、請求書の記載内容の修正とは無関係です。']},
  {id:'p688', domain:'tech', type:'single', source:SOURCES.healthomics, text:'ある製薬会社が、ゲノムデータを使った薬剤候補の解析パイプライン(WDL/Nextflowで記述)を、インフラの管理負担を抑えて大規模に実行し、かつ解析結果のバリアントデータを安価に保存・クエリしたいと考えている。最も適したサービスはどれですか？',
    choices:['AWS HealthOmics','Amazon EMR','AWS Batch','Amazon Comprehend Medical'], correct:[0],
    why:['正しい。AWS HealthOmicsは、WDL/Nextflow/CWLで記述されたバイオインフォマティクスのワークフローを完全マネージドで大規模に実行でき、バリアントストア等でゲノムデータを低コストに保存・クエリできます。','Amazon EMRは汎用のビッグデータフレームワーク(Hadoop/Spark)実行サービスであり、ゲノミクス向けの専用ワークフロー実行・ストレージ機能は持ちません。','AWS Batchは汎用のバッチジョブ実行サービスであり、ゲノミクス専用のワークフロー言語対応やバリアントストアは提供しません。','Amazon Comprehend Medicalは臨床テキストの自然言語処理サービスであり、ゲノムデータの解析パイプライン実行やバリアント保存を行うものではありません。']},
  {id:'p689', domain:'tech', type:'multi', source:SOURCES.healthomics, text:'AWS HealthOmicsが対応しているバイオインフォマティクスのワークフロー記述言語として正しいものを2つ選択してください。',
    choices:['WDL (Workflow Description Language)','AWS CloudFormationテンプレート(YAML/JSON)','Nextflow','AWS Step Functionsのステートマシン言語(ASL)'], correct:[0,2],
    why:['正しい。AWS HealthOmicsはWDL (Workflow Description Language)で記述されたワークフローに対応しています。','CloudFormationのテンプレート言語はAWSリソースのプロビジョニング用であり、HealthOmicsのワークフロー記述言語ではありません。','正しい。AWS HealthOmicsはNextflowで記述されたワークフローにも対応しています（CWLにも対応しています）。','AWS Step FunctionsのASLはステートマシンの定義言語であり、HealthOmicsのワークフロー記述言語ではありません。']},
  {id:'p690', domain:'security', type:'single', source:SOURCES.marketplaceVendorInsights, text:'ある企業の調達担当者が、AWS Marketplaceで提供されているSaaS製品を導入する前に、販売者側のセキュリティ体制(データプライバシー、アクセス制御等)を自社で個別に調査する手間を減らし、継続的に最新の評価を確認したいと考えている。最も適した機能はどれですか？',
    choices:['AWS Artifact','AWS Marketplace Vendor Insights','AWS Audit Manager','AWS License Manager'], correct:[1],
    why:['AWS Artifactは主にAWS自身の第三者認証レポートをダウンロードするサービスであり、Marketplace上の第三者SaaS販売者を評価する機能ではありません。','正しい。AWS Marketplace Vendor Insightsは、Marketplaceで提供されるSaaS製品について、販売者のセキュリティ情報をダッシュボードで一元的に確認でき、継続的に最新化される評価を提供します。','AWS Audit Managerは自社のAWS環境のコンプライアンス証拠を収集するサービスであり、Marketplaceの第三者販売者を評価する機能ではありません。','AWS License Managerはソフトウェアライセンスの使用状況管理を行うサービスであり、セキュリティ評価の機能ではありません。']},
  {id:'p691', domain:'security', type:'multi', source:SOURCES.marketplaceVendorInsights, text:'AWS Marketplace Vendor Insightsがセキュリティ評価の根拠として収集するエビデンスの種類として正しいものを2つ選択してください。',
    choices:['販売者のAWS本番環境からAWS Config/AWS Audit Manager経由で収集されるライブエビデンス','AWSが実施する販売者への立入検査報告書','販売者が提出するISO 27001やSOC 2 Type IIなどの認証・監査レポート','購入者自身が実施したペネトレーションテストの結果'], correct:[0,2],
    why:['正しい。評価対象の一部の管理策については、販売者の本番環境の設定をAWS Configルールで評価し、AWS Audit Managerが収集したライブエビデンスがダッシュボードに反映されます。','AWSが販売者へ立入検査を実施する仕組みは提供されていません。','正しい。販売者が提供するISO 27001やSOC 2 Type IIなどの第三者認証・監査レポートの内容も、評価項目にマッピングされてダッシュボードに反映されます。','購入者自身がペネトレーションテストを実施してエビデンスとする仕組みではありません（販売者自身のセルフアセスメントが用いられます）。']},
  {id:'p692', domain:'tech', type:'single', source:SOURCES.locationService, text:'配送業者が、複数の配送先を効率よく巡回するルートを計算し、有料道路やフェリーを避けた経路を算出したいと考えている。Amazon Location Serviceの機能のうち、最も適したものはどれですか？',
    choices:['Trackers(トラッカー)によるリアルタイム位置追跡','Geofence Collections(ジオフェンス)によるエリア進入検知','Routes機能によるルート計算(有料道路・フェリー回避等の条件指定を含む)','Places機能による地名・住所の検索(ジオコーディング)'], correct:[2],
    why:['Trackersはデバイスの現在位置をリアルタイムに追跡する機能であり、ルート計算の機能ではありません。','Geofenceは指定したエリアへの出入りを検知する機能であり、ルート計算の機能ではありません。','正しい。Amazon Location ServiceのRoutes機能は、複数地点間のルートを計算し、有料道路やフェリーの回避など条件を指定した経路算出に対応しています。','Placesは地名・住所の検索(ジオコーディング)や逆ジオコーディングを行う機能であり、ルート計算そのものではありません。']},
  {id:'p693', domain:'security', type:'single', source:SOURCES.wafAtp, text:'AWS WAFのATP(Account Takeover Prevention)について、ログイン試行の「成功」や「失敗」をどのように判定していますか？',
    choices:['送信元IPアドレスの地理的位置のみから判定する','リクエストヘッダーのUser-Agentのみから判定する','常にCAPTCHAの応答結果のみから判定する','アプリケーションからのレスポンス内容(レスポンス検査)を基に、ログイン試行が成功したか失敗したかを判定する'], correct:[3],
    why:['地理的位置のみでログインの成功・失敗を判定する仕組みではありません。','User-Agentのみでログイン成否を判定する仕組みではありません。','CAPTCHAはATPが提供する追加の緩和策の一つですが、成功・失敗の判定そのものではありません。','正しい。ATPのレスポンス検査(Response inspection)は、アプリケーションからのレスポンス内容を基にログイン試行の成功・失敗を判定し、その結果を基にブロックや緩和策を適用します。']},
  {id:'p694', domain:'security', type:'single', source:SOURCES.securityIR, text:'AWS Security Incident Responseの利用形態として正しいものはどれですか？',
    choices:['AWS Supportプランとは別に、Security Incident Response自体への登録(有効化)が必要なサービスである','Basic Supportに自動的に含まれる無料の機能である','Amazon GuardDutyを有効化すると自動的に有効になる機能である','AWS Organizationsの管理アカウントでのみ有効化できる機能である'], correct:[0],
    why:['正しい。AWS Security Incident Responseは、既存のAWS Supportプランとは別に、サービス自体への登録(有効化)が必要な独立したサービスです。','Basic Supportに自動的に含まれる無料機能ではありません。','GuardDutyを有効化しても自動的にSecurity Incident Responseが有効になるわけではありません(GuardDutyの検出結果を取り込む連携は可能です)。','管理アカウントに限らず、必要なアカウントで個別に有効化できます。']},
  {id:'p695', domain:'security', type:'single', source:SOURCES.networkAccessAnalyzer, text:'AWS Network Access Analyzerの分析結果に関する特徴として正しいものはどれですか？',
    choices:['分析のたびに実際のテストパケットをネットワークに送信して到達可能性を確認する','定義したNetwork Access Scope(分析条件)に違反する経路が見つかった場合、その経路をネットワーク図として可視化した結果を確認できる','常時バックグラウンドで自動的に実行され、継続的にリアルタイム監視を行う','分析結果はAWSサポートへの問い合わせを通じてのみ確認できる'], correct:[1],
    why:['Network Access Analyzerはネットワーク構成を静的に解析する機能であり、実際にテストパケットを送信するわけではありません。','正しい。Network Access Analyzerは、定義したNetwork Access Scopeの条件に違反する(意図しない)経路が見つかった場合、その経路をネットワーク図として可視化した結果を提供します。','Network Access Analyzerはオンデマンドで実行する分析であり、GuardDutyのような継続的なリアルタイム監視を行う機能ではありません。','分析結果はAWSマネジメントコンソールやAPIから直接確認でき、サポートへの問い合わせを必須とするものではありません。']},
  {id:'p696', domain:'concepts', type:'single', source:SOURCES.awsHealth, text:'AWS Health Dashboardの「Service Health Dashboard」に関する特徴として正しいものはどれですか？',
    choices:['自分のAWSアカウントに影響する個別の障害情報のみを表示する、サインインが必須のページである','有料のサポートプランに加入している利用者のみが閲覧できる','AWSサインインなしで誰でも閲覧できる、全体的なサービス状況を示す公開ページである','AWS Health APIを通じてのみアクセスでき、コンソール上では閲覧できない'], correct:[2],
    why:['これはPersonal Health Dashboard(アカウント固有の情報、サインインが必要)の説明です。','Service Health Dashboardは有料サポートの加入に関わらず誰でも閲覧できます。','正しい。Service Health Dashboardは、AWSへのサインインなしで誰でも閲覧できる、全リージョン・サービスの全体的な状況を示す公開ページです。','Service Health DashboardはWebページ上でも閲覧でき、APIのみに限定されるものではありません。']},
  {id:'p697', domain:'concepts', type:'single', source:SOURCES.slaLegal, text:'AWSのSLA(Service Level Agreement)でサービスクレジットを受け取るための一般的な手続きとして正しいものはどれですか？',
    choices:['SLA違反が発生すると自動的にクレジットが付与され、利用者側での手続きは不要である','SLA違反の有無に関わらず、毎月自動的にクレジットが付与される','AWSサポートが違反を検知した場合のみ、利用者への事前連絡なしにクレジットが付与される','多くの場合、利用者自身が所定の期間内に稼働率等の記録を添えてクレジットの申請(クレーム)を行う必要がある'], correct:[3],
    why:['多くのAWSサービスのSLAでは、クレジットは自動的には付与されず、利用者自身の申請が必要です。','SLA違反がない月にクレジットが自動付与されることはありません。','AWSが利用者に代わって自動的に申請を行う仕組みではありません。','正しい。多くのAWSサービスのSLAでは、利用者自身が所定の期間内に稼働率の記録等を添えてサービスクレジットを申請する必要があります。']},
  {id:'p698', domain:'concepts', type:'single', source:SOURCES.skillBuilder, text:'AWS認定資格の受験を控えたエンジニアが、本番の試験形式に慣れるために、AWS Skill Builderのサブスクリプションに含まれる模擬試験(Practice Exam)を活用したいと考えている。この模擬試験の位置づけとして正しいものはどれですか？',
    choices:['有料のサブスクリプション(Individual等)に含まれる、本番の試験形式に近い練習用の模擬試験である','無料のデジタルコースに自動的に含まれる、採点なしの練習問題である','AWS認定資格に合格した後にのみ解放される、復習用の問題集である','AWSパートナー企業の社員専用に提供される、一般利用者は利用できない模擬試験である'], correct:[0],
    why:['正しい。AWS Skill Builderの模擬試験(Practice Exam)は、有料のサブスクリプション(Individualプラン等)に含まれる、本番の試験形式に近い練習用コンテンツです。','模擬試験は無料のデジタルコースには含まれず、有料サブスクリプションの一部として提供されます。','模擬試験は資格の受験前に本番形式に慣れるためのものであり、合格後にのみ解放されるものではありません。','AWS Skill Builderの模擬試験はAWSパートナー企業の社員に限定されたものではありません。']},
  {id:'p699', domain:'billing', type:'multi', source:SOURCES.costCategories, text:'AWS Cost Categoriesのルール設定に関する特徴として正しいものを2つ選択してください。',
    choices:['ルールの条件(Dimensions)として、AWSサービスや使用タイプ、アカウントIDなどを指定できる','1つのコストカテゴリにつき、設定できるルールは1つのみに制限されている','複数のルールを組み合わせて、階層的(入れ子)にコストを分類できる','コスト配分タグを設定していないリソースの費用は、Cost Categoriesの対象に含めることができない'], correct:[0,2],
    why:['正しい。Cost Categoriesのルールでは、AWSサービスや使用タイプ、アカウントIDなど複数の条件(Dimensions)を組み合わせて分類ルールを定義できます。','1つのコストカテゴリに対して複数のルールを設定できます。','正しい。Cost Categoriesでは複数のルールを組み合わせて、階層的にコストを分類できます。','Cost Categoriesはタグが付与されていないリソースの費用も、アカウントIDやサービス名などタグ以外の条件に基づいて分類対象に含めることができます。']},
  {id:'p700', domain:'billing', type:'single', source:SOURCES.purchaseOrderMgmt, text:'AWS Purchase Order Managementで登録した購入注文(PO)は、どのように請求書と関連付けられますか？',
    choices:['POは請求書とは独立した社内文書であり、AWSの請求書には一切反映されない','AWSはPOの情報に基づいて請求書を生成し、各請求書は関連付けられた1つのPO番号と紐づけられ、Billing and Cost Managementコンソールで確認できる','POを登録すると、その時点の請求額が自動的にPOの金額まで割引される','POはAWS Organizationsの管理アカウントのみが登録でき、メンバーアカウントでは利用できない'], correct:[1],
    why:['誤り。AWSはPOの情報に基づいて請求書を生成するため、POの内容は請求書に反映されます。','正しい。AWSはPOの情報に基づいて請求書を生成し、各請求書は1つのPO番号(およびPOライン番号)と関連付けられます。関連付けられたPO番号はBilling and Cost Managementコンソールで確認できます。','誤り。POの登録自体は料金の割引を発生させるものではなく、社内の発注・照合プロセスを支援するものです。','誤り。POはAWS Organizationsの管理アカウントに限らず、該当するアカウントで登録・管理できます。']},
  {id:'p701', domain:'concepts', type:'single', source:SOURCES.drStrategies, text:'4つのDR戦略(Backup and Restore、Pilot Light、Warm Standby、Multi-Site Active/Active)のうち、実装コストが最も低く、その分RTO/RPOが最も長くなる(復旧に最も時間がかかる)戦略はどれですか？',
    choices:['Backup and Restore','Pilot Light','Warm Standby','Multi-Site Active/Active'], correct:[0],
    why:['正しい。Backup and Restoreは、バックアップデータのみを別リージョンに保持し、障害時にゼロから環境を構築する戦略で、4つのDR戦略のうち実装コストが最も低い一方、RTO/RPOは最も長くなります。','誤り。Pilot Lightはコア部分のレプリカを常時起動しておくため、Backup and Restoreよりコストが高く、RTO/RPOは短くなります。','誤り。Warm Standbyは縮小版の環境を常時稼働させるため、Pilot Lightよりさらにコストが高く、RTO/RPOも短くなります。','誤り。Multi-Site Active/Activeは複数リージョンで本番相当を同時稼働させるため、4つの戦略の中で最もコストが高く、RTOはほぼ即時です。']},
  {id:'p702', domain:'concepts', type:'single', source:SOURCES.globalInfra, text:'1つのAWSリージョンは、最低いくつのアベイラビリティーゾーン(AZ)で構成されるように設計されていますか？',
    choices:['1つ','3つ以上','10つ以上','AZの数はリージョンによらず常に同一である'], correct:[1],
    why:['誤り。1つのAZだけで構成されるリージョンはなく、単一障害点を避けるため複数のAZで構成されます。','正しい。AWSの各リージョンは、独立した電源・ネットワーク・冷却設備を持つ、最低3つの物理的に分離されたアベイラビリティーゾーン(AZ)で構成されるように設計されています。','誤り。多くのリージョンは3〜6個程度のAZで構成されており、10個以上は一般的ではありません。','誤り。AZの数はリージョンによって異なります(最低3つですが、それ以上のリージョンもあります)。']},
  {id:'p703', domain:'security', type:'multi', source:SOURCES.privatelink, text:'AWS PrivateLinkを使って、自社が提供するサービスを他のVPCやAWSアカウントの利用者に対してプライベートに公開(提供)する場合の仕組みとして正しいものを2つ選択してください。',
    choices:['Network Load Balancer(NLB)の背後にサービスを配置し、それをもとに「VPCエンドポイントサービス」を作成して利用者に公開する','サービス提供者側は、利用者のVPC内に自社のサービスのコピーを直接デプロイする必要がある','利用者は、提供されたVPCエンドポイントサービスに対して自分のVPC内に「インターフェースVPCエンドポイント」を作成し、接続を要求(リクエスト)することでサービスにアクセスする','サービス提供者と利用者のVPCは、インターネットゲートウェイを経由して通信する必要がある'], correct:[0,2],
    why:['正しい。サービスをNLBの背後に配置し、それを基にVPCエンドポイントサービスを作成することで、他のVPC/アカウントにプライベートに公開できます。','誤り。サービスのコピーを利用者側にデプロイする必要はなく、提供者側のVPC内にサービスを置いたまま、VPCエンドポイント経由で接続されます。','正しい。利用者側は自分のVPCにインターフェースVPCエンドポイントを作成し、提供者側のVPCエンドポイントサービスへの接続を要求することでアクセスできます（提供者側の承認が必要な場合があります）。','誤り。PrivateLinkによる接続はインターネットゲートウェイを経由せず、AWSのプライベートネットワーク内で行われます。']},
  {id:'p704', domain:'security', type:'single', source:SOURCES.verifiedAccess, text:'AWS Verified Accessにおける「トラストプロバイダー(Trust Provider)」の設定に関する説明として正しいものはどれですか？',
    choices:['1つのVerified Accessインスタンスには、IDトラストプロバイダーとデバイストラストプロバイダーをそれぞれ最大1つまでしか設定できない','トラストプロバイダーはIDトラストプロバイダーのみで構成され、デバイスの状態を評価する仕組みは別サービスが必要である','1つのVerified Accessインスタンスには、1つのIDトラストプロバイダーと、複数のデバイストラストプロバイダー(Jamf、CrowdStrike等)を組み合わせて設定できる','デバイストラストプロバイダーを設定すると、IDトラストプロバイダーの設定は不要になる'], correct:[2],
    why:['誤り。デバイストラストプロバイダーは複数組み合わせて設定できます。','誤り。Verified Accessはデバイストラストプロバイダーも標準でサポートしており、デバイスの状態(OSバージョンや準拠状況等)を評価に利用できます。','正しい。AWS Verified Accessでは、1つのインスタンスに1つのIDトラストプロバイダー(ユーザーのID情報を提供)と、複数のデバイストラストプロバイダー(デバイスのセキュリティ状態を提供)を組み合わせて設定し、アクセスポリシーの評価に利用できます。','誤り。多くの構成ではID・デバイスの両方のトラストプロバイダーを組み合わせて利用します。']},
  {id:'p705', domain:'security', type:'single', source:SOURCES.cognito, text:'Amazon Cognitoの「ホストされたUI(Hosted UI)」とは何ですか？',
    choices:['IAMユーザー専用のAWSマネジメントコンソールのログイン画面','Amazon Cognitoの管理コンソール画面そのもの','CloudFrontがキャッシュする静的なログインページの配信拠点','Cognitoが提供する、サインアップ・サインインおよび外部IDプロバイダーとの連携画面をあらかじめ用意し、カスタマイズ可能な状態でホスティングしてくれる機能'], correct:[3],
    why:['誤り。これはIAMユーザーのコンソールログイン画面の説明であり、Cognitoとは異なります。','誤り。Hosted UIはエンドユーザー向けのサインイン画面であり、管理コンソールではありません。','誤り。これはCloudFrontの説明であり、Hosted UIとは異なります。','正しい。Hosted UIは、Amazon Cognitoがあらかじめ用意するサインアップ・サインイン画面で、外部IDプロバイダー(Google等)との連携ボタンも含め、ロゴや配色などをカスタマイズした状態でCognito側にホスティングしてくれる機能です。独自の画面を自前で実装する必要がありません。']},
  {id:'p706', domain:'tech', type:'single', source:SOURCES.transferFamily, text:'AWS Transfer Familyがサポートするプロトコルとして正しいものはどれですか？',
    choices:['SFTP・FTPS・FTPに加え、EDI(電子データ交換)で広く使われるAS2プロトコルにも対応している','SFTPのみに対応しており、FTPS・FTPには対応していない','HTTPSのみに対応したファイルアップロード専用のサービスである','BitTorrentプロトコルを使った大容量ファイルの配布に特化したサービスである'], correct:[0],
    why:['正しい。AWS Transfer Familyは、SFTP・FTPS・FTPに加えて、取引先企業間のEDI(電子データ交換)で広く使われるAS2プロトコルによるファイル転送にも対応しています。','誤り。SFTPだけでなくFTPS・FTPにも対応しています。','誤り。HTTPSアップロード専用ではなく、SFTP等の標準プロトコルに対応したマネージドサービスです。','誤り。BitTorrentには対応していません。']},
  {id:'p707', domain:'tech', type:'single', source:SOURCES.appstream, text:'Amazon AppStream 2.0(現Amazon WorkSpaces Applications)のフリートタイプのうち、「Always-On」の特徴として正しいものはどれですか？',
    choices:['利用者からのリクエストがあった時点でインスタンスの起動を開始するため、接続開始までに数分の待ち時間が発生する','インスタンスは常に起動した状態で待機しており、ユーザーは即座にストリーミングセッションを開始できるが、起動している間は継続して課金される','インスタンスは一切起動されず、常に無料で待機し続ける','セッション終了後、インスタンスは自動的に削除され、二度と同じフリートで再利用されない'], correct:[1],
    why:['誤り。これは「On-Demand」フリートの特徴です。On-Demandはリクエスト時にインスタンスを起動するため、接続開始まで多少の待ち時間が発生します。','正しい。Always-Onフリートは、インスタンスを常に起動した状態で維持するため、ユーザーは待ち時間なく即座にセッションを開始できますが、起動している間は継続して課金されます(即時性重視)。','誤り。Always-Onのインスタンスは起動している間課金が発生し、無料ではありません。','誤り。フリートのインスタンスはセッション終了後に初期化(クリーンアップ)され、同じフリート内で再利用されます。']},
  {id:'p708', domain:'tech', type:'single', source:SOURCES.documentdb, text:'Amazon DocumentDB(MongoDB互換)の「グローバルクラスター(Global Clusters)」の特徴として正しいものはどれですか？',
    choices:['1つのリージョン内の複数のAZにまたがってレプリカを配置する機能であり、複数リージョンには対応していない','AWSアカウントでクラスターを共有するための権限管理機能','プライマリクラスターのデータを、高速なストレージベースのレプリケーションで複数のAWSリージョンのセカンダリクラスターに低レイテンシーで複製し、リージョン間での高速な読み取りや、リージョン障害時の災害復旧を可能にする機能','MongoDB以外のデータベースエンジンとの互換性を提供する機能'], correct:[2],
    why:['誤り。Global Clustersは単一リージョン内のAZ分散ではなく、複数のAWSリージョンにまたがる機能です。','誤り。これはAWS RAM等の説明であり、Global Clustersの機能ではありません。','正しい。DocumentDBのGlobal Clustersは、プライマリクラスターのデータをストレージベースのレプリケーションで複数リージョンのセカンダリクラスターへ低レイテンシーに複製し、リージョンをまたいだ高速な読み取りや、リージョン障害時の災害復旧を実現します。','誤り。DocumentDBはMongoDB互換のデータベースサービスであり、他エンジンとの互換性を提供する機能ではありません。']},
  {id:'p709', domain:'billing', type:'single', source:SOURCES.dataExports, text:'AWS Data Exportsで作成したエクスポートの更新(リフレッシュ)に関する説明として正しいものはどれですか？',
    choices:['エクスポートは作成時に一度だけ実行され、その後は手動で再作成しない限り更新されない','エクスポートのスケジュールはユーザーが設定できず、AWS側が決めた固定の頻度でのみ更新される','エクスポートされたデータは1回のみS3に保存され、過去のエクスポート結果は自動的に削除される','設定したスケジュールに基づいて定期的に自動実行され、S3内の出力先のデータが最新のコスト・使用量データで更新され続ける'], correct:[3],
    why:['誤り。AWS Data Exportsは一度きりの実行ではなく、定期的に自動更新されます。','誤り。エクスポートの更新頻度はユーザーの設定に基づきます。','誤り。過去のエクスポート結果が自動的に削除される仕組みではありません。','正しい。AWS Data Exportsで作成したエクスポートは、設定したスケジュールに基づいて定期的に自動実行され、S3内の出力先データが最新のコスト・使用量（または二酸化炭素排出量）データで更新され続けます。']},
  {id:'p710', domain:'tech', type:'single', source:SOURCES.dax, text:'あるオンラインゲームサービスは、DynamoDBに保存された特定のユーザープロフィール(ホットキー)への読み取りアクセスが特定の時間帯に集中し、応答時間を一桁台ミリ秒からマイクロ秒単位まで改善したいと考えている。読み取りは結果整合性で問題ない。最も適した方法はどれですか？', choices:['DynamoDB Accelerator (DAX) をDynamoDBの前面に構成し、結果整合性のある読み取りをインメモリでキャッシュする','DynamoDBグローバルテーブルを有効化し、複数リージョンに書き込みを分散する','DynamoDBのテーブルをAmazon S3にエクスポートし、S3から読み取る','DynamoDBの書き込みキャパシティユニットを増強する'], correct:[0], why:['正しい。DAXはDynamoDBと互換性のあるインメモリキャッシュサービスで、結果整合性のある読み取りの応答時間をマイクロ秒単位まで高速化でき、特定のキーに読み取りが集中するホットキーのシナリオに適しています。','誤り。グローバルテーブルは複数リージョン間のレプリケーションが目的で、読み取りレイテンシーをマイクロ秒単位まで改善するキャッシュ機能ではありません。','誤り。S3へのエクスポートは分析用途向けで、リアルタイムの低レイテンシー読み取りには適しません。','誤り。書き込みキャパシティの増強は、読み取りレイテンシーの改善には直接関係しません。']},
  {id:'p711', domain:'tech', type:'single', source:SOURCES.mediatailor, text:'あるOTT(Over-The-Top)動画配信事業者は、視聴者ごとに異なる広告を動画コンテンツ(VODおよびライブ配信)に挿入し、広告の視聴状況を追跡して収益化を強化したいと考えている。最も適したサービスはどれですか？', choices:['AWS Elemental MediaConvert','AWS Elemental MediaTailor','AWS Elemental MediaPackage','Amazon CloudFront'], correct:[1], why:['誤り。MediaConvertはファイルベースの動画トランスコーディング(形式変換)サービスであり、広告挿入機能はありません。','正しい。AWS Elemental MediaTailorは、VOD・ライブ配信の動画に視聴者ごとの広告を挿入し、広告視聴状況を追跡できる、スケーラブルな広告挿入・チャンネル編成サービスです。','誤り。MediaPackageは配信デバイスに応じた形式へのジャストインタイムパッケージングを行うサービスで、広告挿入自体は主機能ではありません(MediaTailorのオリジンとして連携することがあります)。','誤り。CloudFrontはコンテンツ配信network(CDN)であり、広告挿入機能はありません。']},
  {id:'p712', domain:'tech', type:'single', source:SOURCES.internetMonitor, text:'あるグローバル企業は、自社のWebアプリケーションについて、エンドユーザーのデバイスやブラウザに監視エージェントを一切インストールすることなく、特定の国・都市・通信事業者(ISP)ごとのインターネット接続品質(可用性・パフォーマンス)の低下を検知したいと考えている。最も適したサービスはどれですか？', choices:['Amazon CloudWatch Synthetics(カナリア)','AWS X-Ray','Amazon CloudWatch Internet Monitor','VPC Flow Logs'], correct:[2], why:['誤り。CloudWatch Syntheticsはカナリアスクリプトで定期的に操作を再現する監視で、エンドユーザー側のインターネット接続品質を国・ISP単位で可視化するものではありません。','誤り。X-Rayはアプリケーション内部の分散トレーシングを行うサービスで、インターネット接続品質の監視とは異なります。','正しい。CloudWatch Internet Monitorは、AWSが持つグローバルな可観測性データを使い、エンドユーザー側にエージェントを配置せずに、国・都市・通信事業者単位でのインターネット接続の可用性やパフォーマンスの低下を検知できます。','誤り。VPC Flow LogsはVPC内のネットワークトラフィックのログであり、インターネット側の接続品質を監視するものではありません。']},
  {id:'p713', domain:'tech', type:'single', source:SOURCES.managedFlink, text:'あるデータエンジニアリングチームは、ストリーミングデータのリアルタイム処理にApache Flinkを使いたいが、クラスターのプロビジョニングやキャパシティ管理、サーバーのパッチ適用などの運用作業を自分たちで行いたくないと考えている。最も適したサービスはどれですか？', choices:['自分でEC2クラスターを構築し、Apache Flinkをインストールして運用する','Amazon EMR上でFlinkクラスターを構築し、ノード数を手動で管理する','AWS Batchでバッチジョブとしてストリーミング処理を行う','Amazon Managed Service for Apache Flinkを使い、サーバーレスで実行基盤のプロビジョニング・スケーリング・パッチ適用をAWSに任せる'], correct:[3], why:['誤り。これではクラスターの構築・運用作業が必要になり、要件を満たしません。','誤り。EMR上のFlinkクラスターでもノード数などの管理が必要になる場合があります。','誤り。AWS Batchはバッチジョブ向けのサービスで、Flinkによるストリーミング処理の実行基盤ではありません。','正しい。Amazon Managed Service for Apache Flinkは、サーバーレスでFlinkアプリケーションの実行基盤のプロビジョニング・自動スケーリング・パッチ適用を管理してくれるため、運用作業を大幅に削減できます。']},
  {id:'p714', domain:'tech', type:'single', source:SOURCES.resourceExplorer, text:'ある企業は、1つのAWSアカウント内の複数のリージョン(us-east-1、us-west-2、eu-west-1)にまたがるリソースを、AWS Resource Explorerで横断的に検索できるようにしたい。この設定について正しい説明はどれですか？', choices:['各リージョンにResource Explorerのローカルインデックスを作成し、そのうち1つのリージョンのインデックスを「集約インデックス(aggregator index)」に指定することで、そのリージョンから全リージョンのリソースを横断検索できるようになる','Resource Explorerを有効化すると、自動的に全リージョンが横断検索の対象になり、追加の設定は不要である','横断検索を行うには、各リージョンのリソースにAWS RAMで共有設定を行う必要がある','横断検索の対象にできるリージョンは最大2つまでに制限されている'], correct:[0], why:['正しい。Resource Explorerはリージョンごとにローカルインデックスを作成し、そのうち1つを集約インデックスに指定することで、そのリージョンのビューから全リージョンのリソースを横断検索できるようになります。','誤り。横断検索には、いずれかのリージョンのインデックスを集約インデックスに指定する設定が必要です。','誤り。AWS RAMによるリソース共有は、Resource Explorerの横断検索設定とは無関係です。','誤り。対象リージョン数に2つという制限はありません。']},
  {id:'p715', domain:'tech', type:'single', source:SOURCES.mediatailor, text:'ある放送事業者は、既存のVOD(ビデオオンデマンド)コンテンツを使って、あらかじめ録画されたコンテンツを順番に配信する「リニアストリーミングチャンネル」を、動画のセグメント自体には手を加えず、マニフェスト(再生リスト)の生成だけで組み立てたいと考えている。最も適した機能はどれですか？', choices:['AWS Elemental MediaConvertでVODコンテンツをライブ配信用の形式に再変換する','AWS Elemental MediaTailorのチャンネル編成(Channel Assembly)機能を使い、オリジンサーバーのコンテンツセグメントはそのままに、マニフェストのみを動的に生成してリニアチャンネルを組み立てる','Amazon IVSでリアルタイムの配信チャンネルを新規に作成する','AWS Elemental MediaLiveで新たにライブエンコーダーを起動する'], correct:[1], why:['誤り。MediaConvertはファイルベースの変換サービスで、リニアチャンネルの組み立て機能はありません。','正しい。MediaTailorのチャンネル編成(Channel Assembly)は、コンテンツセグメント自体はオリジンサーバーから直接配信させたまま、マニフェストのみを動的に生成してVODコンテンツからリニアストリーミングチャンネルを組み立てる、マニフェスト専用の機能です。','誤り。Amazon IVSはライブのインタラクティブ動画配信向けのサービスで、既存VODからのチャンネル組み立て機能ではありません。','誤り。MediaLiveはライブエンコーディングを行うサービスで、既存のVODコンテンツからマニフェストのみでチャンネルを組み立てる機能ではありません。']},
  {id:'p716', domain:'security', type:'multi', source:SOURCES.cleanrooms, text:'AWS Clean Roomsにおいて、データ提供者がテーブルに設定できる「分析ルール(Analysis Rule)」の種類として正しいものを2つ選択してください。', choices:['Aggregation(集計)ルール — COUNT・SUM・AVGなどの集計関数を使ったクエリのみを許可する','Encryption(暗号化)ルール — テーブルのデータを常に暗号化した状態でのみクエリを許可する','List(リスト)ルール — 複数テーブル間の重複(オーバーラップ)を行単位のリストとして出力するクエリを許可する','Replication(複製)ルール — テーブルのデータを他のAWSリージョンへ複製する際の制御を行う'], correct:[0,2], why:['正しい。Aggregationルールは、COUNT・SUM・AVGなどの集計関数を使った、集計された統計のみを出力するクエリを許可する分析ルールです。','誤り。「Encryption」という名称の分析ルールの種類はありません(暗号化はAWS Clean Rooms全体で行われる保護機能です)。','正しい。Listルールは、複数テーブル間で重複(オーバーラップ)する行を行単位のリストとして出力するクエリを許可する分析ルールです。','誤り。「Replication」という名称の分析ルールの種類はありません。']},
  {id:'p717', domain:'security', type:'single', source:SOURCES.kms, text:'AWS KMSのカスタマーマネージドキーに対して「スケジュール削除(キーの削除)」を実行した場合の動作として正しいものはどれですか？', choices:['削除をスケジュールした直後に即座にキーが削除され、取り消すことはできない','待機期間中もキーは通常どおり暗号化・復号に使用でき、待機期間が終わった時点でのみ使用できなくなる','削除までの待機期間(7〜30日、デフォルト30日)が設定され、その間キーは「Pending deletion」状態となり暗号化・復号などの操作には使用できないが、待機期間が終わる前であれば削除をキャンセルできる','AWSマネージドキーと同様に、削除の予約はできるが、AWS側の承認が必要である'], correct:[2], why:['誤り。即座に削除されるのではなく、必ず待機期間が設けられます。','誤り。待機期間中もキーは暗号処理に使用できません。','正しい。カスタマーマネージドキーの削除をスケジュールすると、7〜30日(デフォルト30日)の待機期間が設定され、その間キーは「Pending deletion」状態となり暗号化・復号などの暗号処理には使用できません。待機期間が終わる前であれば削除をキャンセルできます。','誤り。AWSマネージドキーはそもそも削除をスケジュールすることができません(削除できるのはカスタマーマネージドキーのみ)。']},
  {id:'p718', domain:'security', type:'single', source:SOURCES.cleanrooms, text:'AWS Clean Roomsのカスタム分析ルール(Custom analysis rule)が、個々のレコードが結果に与える影響を統計的に抑え、特定の個人を結果から推測されにくくするために利用できる、プライバシー強化技術は何ですか？', choices:['AWS KMSによる保管時の暗号化','IAMロールによるアクセス制御','VPCエンドポイントによるプライベート接続','差分プライバシー(Differential Privacy) — クエリ結果にノイズを加えることで、個々のレコードの有無が結果に与える影響を統計的に抑える技術'], correct:[3], why:['誤り。KMSによる暗号化はデータの保管時保護の仕組みであり、クエリ結果への個人の影響を統計的に抑える技術ではありません。','誤り。IAMロールはアクセス制御の仕組みであり、クエリ結果のプライバシー強化技術ではありません。','誤り。VPCエンドポイントはネットワーク接続のプライベート化であり、プライバシー強化技術ではありません。','正しい。差分プライバシーは、クエリ結果にノイズを加えることで個々のレコードが結果に与える影響を統計的に抑え、特定の個人の情報が結果から推測されるリスクを低減する、Custom analysis ruleで利用できるプライバシー強化技術です。']},
  {id:'p719', domain:'security', type:'single', source:SOURCES.rolesAnywhere, text:'AWS IAM Roles Anywhereにおいて、「プロファイル(Profile)」の役割として正しいものはどれですか？', choices:['IAM Roles AnywhereがどのIAMロールをアサインできるかを指定し、さらにセッションポリシーを適用してそのセッションで行える操作の範囲を制限する','信頼するCA(証明書発行機関)を登録し、PKIとIAM Roles Anywhereの間の信頼を確立する','オンプレミスのワークロードに長期的なIAMアクセスキーを発行する','証明書の失効リスト(CRL)を管理する'], correct:[0], why:['正しい。プロファイルは、IAM Roles AnywhereがどのIAMロールをアサインできるかを指定し、さらに(任意の)セッションポリシーを適用することで、発行される一時的な認証情報が行える操作の範囲を制限します。','誤り。これはトラストアンカー(Trust Anchor)の役割です。','誤り。IAM Roles Anywhereは長期的なアクセスキーではなく、X.509証明書と交換で一時的な認証情報を発行する仕組みです。','誤り。これはプロファイルの役割ではありません。']},
  {id:'p720', domain:'billing', type:'single', source:SOURCES.capacityReservationFleet, text:'Amazon EC2のCapacity Reservation Fleetをキャンセルした場合の動作として正しいものはどれですか？', choices:['フリート配下の個々のCapacity Reservationは引き続き有効なまま残る','フリートに含まれる個々のCapacity Reservationもすべてキャンセルされ、新たなCapacity Reservationの作成も停止するが、キャンセル時点で既にその予約キャパシティ上で起動していたインスタンスは共有キャパシティ上でそのまま稼働し続ける','フリートをキャンセルすると、その予約キャパシティ上で稼働していたインスタンスは即座に停止される','フリートのキャンセルには、配下の全インスタンスを事前に終了させる必要がある'], correct:[1], why:['誤り。フリートをキャンセルすると、配下の個々のCapacity Reservationもキャンセルされます。','正しい。Capacity Reservation Fleetをキャンセルすると、配下の個々のCapacity Reservationもすべてキャンセルされ、新たな予約の作成も停止しますが、キャンセル時点で既にその予約キャパシティ上で稼働していたインスタンスは、共有キャパシティ上でそのまま稼働を継続します。','誤り。稼働中のインスタンスが即座に停止するわけではありません。','誤り。インスタンスの事前終了は必須ではありません。']},
  {id:'p721', domain:'billing', type:'single', source:SOURCES.dedicatedHosts, text:'ソケット単位・コア単位でライセンスされたソフトウェア(BYOL)をAmazon EC2のDedicated Host上で利用している企業が、物理ホストが提供するソケット数・コア数に基づいてライセンス使用量を自動的に追跡し、上限を超えないように管理したい。最も適した方法はどれですか？', choices:['AWS Cost Explorerでソフトウェアライセンスのコストを可視化する','AWS Trusted Advisorでライセンス使用量の推奨事項を確認する','AWS License Managerでソケット単位またはコア単位のライセンス設定(license configuration)を作成し、Dedicated Hostに関連付けて使用量を追跡する','Amazon Inspectorでライセンス違反のリスクをスキャンする'], correct:[2], why:['誤り。Cost Explorerはコストの可視化を行うサービスで、ライセンス使用量の追跡機能ではありません。','誤り。Trusted Advisorはベストプラクティスの推奨事項を提示するサービスで、ソケット/コア単位のライセンス追跡機能ではありません。','正しい。AWS License Managerでは、ソケット単位やコア単位のカウント方式を指定したライセンス設定を作成し、Dedicated Hostに関連付けることで、物理ホストが提供するソケット数・コア数に基づいてライセンス使用量を自動的に追跡し、上限(ハードリミット)を設定して超過を防ぐことができます。','誤り。Inspectorは脆弱性スキャンサービスであり、ソフトウェアライセンスの追跡機能ではありません。']},
  {id:'p722', domain:'concepts', type:'single', source:SOURCES.rtorpo, text:'あるシステムでは、重要なデータベースのバックアップを毎日1回、深夜0時に取得している。この運用において、障害発生時に許容される実質的なRPO(目標復旧時点)の上限として最も適切なものはどれですか？', choices:['常にゼロ(データ損失は発生しない)','バックアップの取得にかかる時間そのもの','最大で約1週間','最大で約24時間(直前のバックアップから次の障害発生までの最大経過時間)'], correct:[3], why:['誤り。バックアップの間隔が空いている限り、データ損失がゼロになることは保証されません。','誤り。バックアップの取得にかかる時間自体はRPOを決定する要素ではありません。','誤り。バックアップが毎日取得されているため、最大の損失範囲は1週間ではなく約24時間です。','正しい。バックアップが1日1回しか取得されていない場合、障害が次のバックアップの直前に発生すると、最大で約24時間分のデータが失われる可能性があり、これがこの運用における実質的なRPOの上限となります。']},
  {id:'p723', domain:'concepts', type:'single', source:SOURCES.snowFamily, text:'AWS Snow Familyのうち、最も小型・軽量で、電力や設置スペースが限られたエッジ環境での利用に適したデバイスはどれですか？また、データ量が十分に小さい場合、物理的な返送を待たずにネットワーク経由でAWSにデータを送り返すことも可能です。最も適切なデバイスはどれですか？',
    choices:['AWS Snowcone — Snow Familyの中で最も小型・軽量なデバイスで、エッジでのデータ収集・コンピューティングに使え、少量のデータであればAWS DataSyncを使ってネットワーク経由で返送することもできる','AWS Snowball Edge Storage Optimized — 大容量のストレージ容量を備えた、データセンター規模の移行向けデバイス','AWS Snowmobile — トラックで輸送する、エクサバイト規模のデータ移行用デバイス','AWS Direct Connect — 専用線でオンプレミスとAWSを接続するネットワークサービス'], correct:[0],
    why:['正しい。AWS Snowconeは、Snow Familyの中で最も小型・軽量なデバイスで、電力や設置スペースが限られたエッジ環境での利用に適しており、データ量が少ない場合はAWS DataSyncを使ってネットワーク経由でAWSにデータを送り返すこともできます。','誤り。Snowball Edge Storage Optimizedは大容量ストレージを備えたデータセンター規模の移行向けデバイスで、Snowconeより大きく重いデバイスです。','誤り。Snowmobileはトラックで輸送するエクサバイト規模の移行用デバイスで、小型・軽量ではありません。','誤り。Direct Connectは物理デバイスではなく、専用線によるネットワーク接続サービスです。']},
  {id:'p724', domain:'concepts', type:'single', source:SOURCES.controlTower, text:'AWS Control Towerにおいて、組織内で新しいAWSアカウントを作成する際に、事前定義された標準的な構成・ガードレールを適用した状態で自動的にアカウントをプロビジョニングする仕組みを何と呼びますか？',
    choices:['AWS Organizations の一括支払い(Consolidated Billing)','Account Factory — 標準化された構成・ガードレールを適用した新規AWSアカウントを自動的にプロビジョニングする、AWS Control Towerの仕組み','AWS Service Catalogの製品(Product)','AWS CloudFormation StackSets'], correct:[1],
    why:['誤り。Consolidated Billingは複数アカウントの請求を一つにまとめる機能であり、新規アカウントのプロビジョニングとは異なります。','正しい。Account Factoryは、AWS Control Towerが提供する仕組みで、事前定義された標準構成・ガードレールを適用した新規AWSアカウントを自動的にプロビジョニングします。','誤り。Service Catalogの製品は、承認済みのITサービスをカタログ化してセルフサービスでデプロイする仕組みであり、アカウント自体のプロビジョニングではありません。','誤り。CloudFormation StackSetsは、複数アカウント・リージョンにスタックを一括展開する仕組みであり、Control TowerのAccount Factoryとは異なる機能です。']},
  {id:'p725', domain:'concepts', type:'single', source:SOURCES.outposts, text:'AWS Outpostsの利用形態に関する説明として正しいものはどれですか？',
    choices:['利用者が独自に調達したサーバーラックに、AWSが提供するソフトウェアだけをインストールして利用する','利用開始後、必要な容量を使った分だけ従量課金され、契約期間の縛りは一切ない','利用者は必要なコンピューティング・ストレージ容量をあらかじめ注文し、AWSがハードウェアを物理的に設置・保守する。契約は一定の期間を前提とした容量ベースでの提供となる','既存のオンプレミスサーバーに後付けでインストールできるソフトウェアのみのサービスであり、専用ハードウェアは不要である'], correct:[2],
    why:['誤り。AWS Outpostsは、AWSが提供する専用ハードウェア(ラックまたはサーバー)を利用者の施設に設置する形態であり、利用者が調達した既存ラックにソフトウェアだけを導入するものではありません。','誤り。Outpostsは必要な容量を事前に注文する形態であり、純粋な従量課金・契約期間なしのサービスではありません。','正しい。AWS Outpostsは、利用者が必要なコンピューティング・ストレージ容量をあらかじめ注文し、AWSがハードウェアを物理的に設置・保守する、一定の契約期間を前提とした容量ベースのサービスです。','誤り。Outpostsは専用のハードウェア(ラックまたはサーバー)が必要であり、ソフトウェアのみでは提供されません。']},
  {id:'p726', domain:'security', type:'single', source:SOURCES.macie, text:'Amazon Macieが標準で提供する管理対象データ識別子(Managed Data Identifiers)では検出できない、企業独自のフォーマットを持つ機密データ(例: 社内の従業員ID番号の形式)を検出したい場合、Amazon Macieが提供する仕組みとして正しいものはどれですか？',
    choices:['AWS Configのカスタムルールを作成する','Amazon GuardDutyの脅威リストに登録する','Amazon Inspectorのカスタムパッケージルールを作成する','カスタムデータ識別子(Custom Data Identifiers) — 正規表現(regex)を使って、企業独自のフォーマットを持つ機密データのパターンを定義し、管理対象データ識別子と組み合わせて検出できる仕組み'], correct:[3],
    why:['誤り。AWS Configのカスタムルールはリソースの構成評価に使うものであり、S3内のデータの機密情報検出には使いません。','誤り。GuardDutyの脅威リストは既知の悪意あるIP等の検知に使うものであり、データの機密情報パターンの検出とは異なります。','誤り。Amazon Inspectorはソフトウェアの脆弱性スキャンを行うサービスであり、S3内データの機密情報検出は対象外です。','正しい。Amazon Macieのカスタムデータ識別子は、正規表現を使って企業独自のフォーマットを持つ機密データのパターンを定義でき、標準の管理対象データ識別子と組み合わせて検出範囲を広げられます。']},
  {id:'p727', domain:'security', type:'multi', source:SOURCES.ram, text:'AWS Resource Access Manager (RAM) を使って、1つのAWSアカウントで作成したリソースを、AWS Organizations配下の他のアカウントと共有できるものを2つ選択してください。',
    choices:['VPCサブネット','Amazon S3バケット内の個々のオブジェクト','AWS License Managerで作成したライセンス設定(License Configuration)','IAMロールそのもの'], correct:[0,2],
    why:['正しい。VPCサブネットは、AWS RAMを使ってOrganizations配下の他のアカウントと共有できる代表的なリソースタイプです。','誤り。S3バケット内の個々のオブジェクトは、RAMの共有対象リソースタイプではありません(S3へのアクセス許可はバケットポリシーやACL等で設定します)。','正しい。AWS License Managerのライセンス設定は、AWS RAMを使って複数のアカウントで共有できるリソースタイプの一つです。','誤り。IAMロールそのものはRAMの共有対象リソースタイプではなく、IAMロールはクロスアカウントのロール引き受け(AssumeRole)などの別の仕組みで利用します。']},
  {id:'p728', domain:'security', type:'single', source:SOURCES.privatelink, text:'AWS PrivateLinkのインターフェースVPCエンドポイントを使う際、「プライベートDNS」を有効にすることで得られる利点として正しいものはどれですか？',
    choices:['サービスの標準のパブリックDNS名をそのまま使ってアプリケーションからアクセスでき、エンドポイント経由であることを示す専用のDNS名にアプリケーションのコードを書き換える必要がない','インターネットゲートウェイを経由せずに、パブリックなDNSサーバーへの問い合わせ自体が完全に不要になる','VPC内の全てのDNSクエリを自動的に暗号化する','オンプレミスのDNSサーバーとAWSのDNSサーバーを自動的に同期する'], correct:[0],
    why:['正しい。プライベートDNSを有効にすると、サービスの標準のパブリックDNS名への問い合わせがVPC内で自動的にエンドポイントのプライベートIPに解決されるため、アプリケーションのコードをエンドポイント専用のDNS名に書き換える必要がありません。','誤り。プライベートDNSはDNSの名前解決先を変えるものであり、DNSクエリ自体をなくすものではありません。','誤り。プライベートDNSはDNS通信の暗号化機能ではありません。','誤り。プライベートDNSはオンプレミスDNSとの自動同期機能ではありません(オンプレミスとの連携にはRoute 53 Resolver等の別の仕組みを使います)。']},
  {id:'p729', domain:'tech', type:'single', source:SOURCES.deviceFarm, text:'AWS Device Farmが対応するテストの種類として正しいものはどれですか？',
    choices:['モバイルアプリの実機テストのみに対応し、デスクトップのWebブラウザのテストには対応していない','モバイルアプリ(Android/iOS)の実機テストに加えて、Seleniumを使ったデスクトップのWebブラウザ(Chrome、Firefox等)でのテストにも対応している','サーバーサイドのAPIの負荷テストに特化したサービスであり、クライアントアプリのテストには対応していない','インフラのコンプライアンス準拠状況のテストに特化したサービスである'], correct:[1],
    why:['誤り。Device Farmはモバイル実機テストに加え、デスクトップブラウザのテストにも対応しています。','正しい。AWS Device Farmは、モバイルアプリの実機テストに加えて、Seleniumを使ったデスクトップのWebブラウザでのテストにも対応しています。','誤り。Device Farmはクライアントアプリ(モバイル・Webブラウザ)のテストサービスであり、サーバーサイドAPIの負荷テスト専用ではありません。','誤り。Device Farmはインフラのコンプライアンステストサービスではありません(それはAWS Audit Manager等の役割です)。']},
  {id:'p730', domain:'tech', type:'single', source:SOURCES.iotSitewise, text:'AWS IoT SiteWiseの「アセットモデル(Asset Model)」の特徴として正しいものはどれですか？',
    choices:['1つの工場内のすべての機械を区別せず、単一のフラットなデータとして扱う','アセットモデルは、一度作成すると後から属性や計算式を追加・変更できない','階層構造(例: 工場 > 生産ライン > 個々の機械)を表現でき、親アセットは子アセットの指標を集約して参照できる。同じ種類の機械には同じアセットモデルを再利用できる','アセットモデルは、AWS IoT Core固有の機能であり、IoT SiteWiseでは利用できない'], correct:[2],
    why:['誤り。アセットモデルは機械やプロセスを個別のアセットとして区別し、階層的に整理できます。','誤り。アセットモデルは作成後も属性や計算式(メトリクス)を追加・変更できます。','正しい。アセットモデルは、工場>生産ライン>個々の機械といった階層構造を表現でき、親アセットは子アセットの指標を集約して参照できます。同じ種類の機械には同じアセットモデルを再利用できます。','誤り。アセットモデルはAWS IoT SiteWise自体の機能です。']},
  {id:'p731', domain:'tech', type:'single', source:SOURCES.mediatailor, text:'AWS Elemental MediaTailorが、動画のセグメント自体を再エンコードせずに、再生中の動画にクライアント側で広告表示などのトリガーとなるタイミング情報を挿入する際に利用する仕組みとして正しいものはどれですか？',
    choices:['動画の各フレームに透かし(ウォーターマーク)を画像として合成する','動画ファイル全体を毎回re-encode(再エンコード)してトリガー情報を焼き込む','DRM(デジタル権利管理)の鍵情報を動画に埋め込む','ID3タグ形式の時限メタデータ(timed metadata)をマニフェストやセグメントに挿入し、クライアント側プレーヤーがそれを読み取ってイベント(広告表示など)をトリガーできるようにする'], correct:[3],
    why:['誤り。これは映像への画像合成処理であり、MediaTailorの時限メタデータ挿入の仕組みではありません。','誤り。MediaTailorはセグメント自体の再エンコードを避けて軽量に動作することが特徴です。','誤り。これはDRMの仕組みであり、時限メタデータの挿入とは異なります。','正しい。MediaTailorは、ID3タグ形式の時限メタデータをマニフェストやセグメントに挿入でき、クライアント側プレーヤーがそれを読み取って広告表示などのイベントをトリガーできます。']},
  {id:'p732', domain:'tech', type:'single', source:SOURCES.cloudwatchRum, text:'Amazon CloudWatch RUM (Real User Monitoring) と Amazon CloudWatch Synthetics の違いとして正しいものはどれですか？',
    choices:['CloudWatch RUMは実際のエンドユーザーのブラウザから収集したパフォーマンス・エラーデータを使うパッシブな監視であるのに対し、CloudWatch Synthetics は定期的にスクリプト(Canary)を実行してエンドポイントやワークフローを能動的にテストするアクティブな監視である','CloudWatch RUMはサーバーサイドのログを収集するサービスであり、ブラウザのデータは収集しない','CloudWatch SyntheticsはAWS Lambda上では実行できず、EC2インスタンス上でのみ動作する','両者は全く同じ機能を提供する別名のサービスである'], correct:[0],
    why:['正しい。CloudWatch RUMは実際のエンドユーザーのブラウザから収集したデータを使うパッシブな監視であるのに対し、CloudWatch Synthetics は定期的にCanaryスクリプトを実行して能動的にテストするアクティブな監視です。','誤り。CloudWatch RUMはクライアント(ブラウザ)側のパフォーマンス・エラーデータを収集するサービスです。','誤り。CloudWatch SyntheticsのCanaryはAWS Lambda上で実行されます。','誤り。両者は収集するデータの性質(実際のユーザー vs 模擬的なスクリプト)が異なる別の監視手法です。']},
  {id:'p733', domain:'tech', type:'multi', source:SOURCES.codedeploy, text:'AWS CodeDeployのデプロイで使用する「AppSpecファイル」に定義できる内容として正しいものを2つ選択してください。',
    choices:['Amazon VPCのサブネット構成','BeforeInstall・AfterInstall・ApplicationStartなどのデプロイライフサイクルの各段階で実行するスクリプト(フック)','IAMユーザーのパスワードポリシー','デプロイ対象のファイルを配置する場所と、OS権限(所有者・パーミッション)の設定'], correct:[1,3],
    why:['誤り。VPCのサブネット構成はAppSpecファイルの定義内容ではありません。','正しい。AppSpecファイルには、BeforeInstall・AfterInstall・ApplicationStartなどのデプロイライフサイクルの各段階で実行するスクリプト(フック)を定義できます。','誤り。IAMユーザーのパスワードポリシーはAppSpecファイルの定義内容ではありません。','正しい。AppSpecファイルには、デプロイ対象のファイルを配置する場所やOS権限(所有者・パーミッション)の設定を定義できます。']},
  {id:'p734', domain:'billing', type:'single', source:SOURCES.dedicatedHosts, text:'Amazon EC2の「Dedicated Host」と「Dedicated Instance」の違いとして正しいものはどれですか？',
    choices:['Dedicated Instanceの方が、物理サーバーのソケット数・コア数やインスタンスの配置を利用者が可視化・制御できる','Dedicated Hostは、特定の物理サーバーを専有し、ソケット数・コア数やインスタンスの配置を利用者が可視化・制御できるため、ソケット/コア単位のソフトウェアライセンス(BYOL)の追跡に適している。Dedicated Instanceは専有ハードウェア上で動作するが、物理サーバー単位の可視化・制御はできない','両者に料金面・機能面での違いは一切ない','Dedicated HostはAWS Outposts専用のオプションであり、通常のAWSリージョンでは利用できない'], correct:[1],
    why:['誤り。実際には逆で、物理サーバーの可視化・制御はDedicated Hostの方で可能です。','正しい。Dedicated Hostは特定の物理サーバーを専有し、ソケット数・コア数やインスタンス配置を可視化・制御できるため、ソケット/コア単位のBYOLの追跡に適しています。Dedicated Instanceは専有ハードウェア上で動作しますが、物理サーバー単位の可視化・制御はできません。','誤り。両者には可視化・制御性やBYOLへの適性などの違いがあります。','誤り。Dedicated Hostは通常のAWSリージョンでも利用できるEC2の購入オプションです。']},
  {id:'p735', domain:'billing', type:'single', source:SOURCES.partnerNetwork, text:'AWS Partner Network (APN) におけるパートナーの分類として正しいものはどれですか？',
    choices:['すべてのAPNパートナーは、ソフトウェア製品の販売のみを行い、導入支援などのサービスは提供できない','APNパートナーは、AWSの社員のみで構成される内部組織である','APNには、導入支援・移行・運用などの専門サービスを提供する「コンサルティングパートナー」と、AWS上で動作するソフトウェア製品を開発・提供する「テクノロジーパートナー」という大きな分類がある','APNパートナーになるには、AWS認定資格を持つ社員が100名以上いることが必須条件である'], correct:[2],
    why:['誤り。コンサルティングパートナーは、導入支援・移行・運用などの専門サービスを提供します。','誤り。APNパートナーはAWSの社員ではなく、外部の企業・組織です。','正しい。AWS Partner Networkには、導入支援・移行・運用などの専門サービスを提供する「コンサルティングパートナー」と、AWS上で動作するソフトウェア製品を開発・提供する「テクノロジーパートナー」という大きな分類があります。','誤り。APNパートナーになるために、認定資格を持つ社員が100名以上必要という条件はありません。']}
];

